/* ספריית הכושר — מאגר קל לאפליקציה (he/en/ru/es). המאגר המלא: exercises-full.js */
const EXERCISES = [{"id":"0001","name":"3/4 sit-up","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0001-2gPfomN.jpg","gif_url":"videos/0001-2gPfomN.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0002","name":"45° side bend","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0002-Hy9D21L.jpg","gif_url":"videos/0002-Hy9D21L.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וידיים מתוחות ישר כלפי מטה לצידי הגוף.","תוך שמירה על גב ישר וליבה מופעלת, הטו באיטיות את הגו לצד אחד, בהורדת היד לכיוון הברך.","עצרו לרגע בנקודה התחתונה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התנועה בצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your arms extended straight down by your sides.","Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и вытянув руки по бокам.","Удерживая спину прямой и напрягая корпус, медленно наклоните туловище в сторону, опуская руку к колену.","Задержитесь на мгновение внизу, затем медленно вернитесь в исходное положение.","Повторите с другой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia abajo a los lados.","Manteniendo la espalda recta y el core activado, flexiona lentamente el torso hacia un lado, bajando la mano hacia la rodilla.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0003","name":"air bike","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0003-1ZFqTDN.jpg","gif_url":"videos/0003-1ZFqTDN.gif","instruction_steps":{"he":["שכבו על הגב עם ידיים מאחורי הראש.","הרימו את הרגליים מהרצפה וכופפו ברכיים בזווית של 90 מעלות.","הביאו את מרפק ימין לכיוון ברך שמאל תוך יישור רגל ימין בו-זמנית.","חזרו לנקודת ההתחלה וחזרו על התנועה בצד השני — מרפק שמאל לברך ימין תוך יישור רגל שמאל.","המשיכו להחליף צדדים בתנועת דיווש למספר החזרות הרצוי."],"en":["Lie flat on your back with your hands placed behind your head.","Lift your legs off the ground and bend your knees at a 90-degree angle.","Bring your right elbow towards your left knee while simultaneously straightening your right leg.","Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.","Continue alternating sides in a pedaling motion for the desired number of repetitions."],"ru":["Лягте на спину, положив руки за голову.","Поднимите ноги от земли и согните колени под углом 90 градусов.","Поднесите правый локоть к левому колену, одновременно выпрямляя правую ногу.","Вернитесь в исходное положение и повторите движение в противоположную сторону, приближая левый локоть к правому колену и выпрямляя левую ногу.","Продолжайте чередовать стороны, вращая педали, необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las manos colocadas detrás de la cabeza.","Levanta las piernas del suelo y flexiona las rodillas formando un ángulo de 90 grados.","Lleva el codo derecho hacia la rodilla izquierda mientras simultáneamente estiras la pierna derecha.","Regresa a la posición inicial y repite el movimiento del lado opuesto, llevando el codo izquierdo hacia la rodilla derecha mientras estiras la pierna izquierda.","Continúa alternando lados con un movimiento de pedaleo durante el número de repeticiones deseado."]}},{"id":"1512","name":"all fours squad stretch","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"quads","image":"images/1512-qBcKorM.jpg","gif_url":"videos/1512-qBcKorM.gif","instruction_steps":{"he":["התחילו על ארבע, עם ידיים ישר מתחת לכתפיים וברכיים ישר מתחת לאגן.","מתחו רגל אחת ישר לאחור, תוך שמירה על ברך כפופה וכף רגל מכופפת.","הורידו את האגן באיטיות לכיוון הרצפה, עד תחושת מתיחה בארבע ראשי.","החזיקו את התנוחה 20–30 שניות.","החליפו רגליים וחזרו על המתיחה בצד השני."],"en":["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Extend one leg straight back, keeping your knee bent and your foot flexed.","Slowly lower your hips towards the ground, feeling a stretch in your quads.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch on the other side."],"ru":["Встаньте на четвереньки, положив руки прямо под плечи и колени прямо под бедрами.","Вытяните одну ногу прямо назад, сохраняя колено согнутым и ступню согнутой.","Медленно опустите бедра к земле, чувствуя растяжение квадрицепсов.","Удерживайте это положение 20–30 секунд.","Поменяйте ноги и повторите растяжку с другой стороны."],"es":["Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.","Extiende una pierna hacia atrás, manteniendo la rodilla flexionada y el pie en flexión.","Baja lentamente las caderas hacia el suelo, sintiendo un estiramiento en los cuádriceps.","Mantén esta posición durante 20-30 segundos.","Cambia de pierna y repite el estiramiento del otro lado."]}},{"id":"0006","name":"alternate heel touchers","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0006-qaZVsGk.jpg","gif_url":"videos/0006-qaZVsGk.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","מתחו את הידיים ישר לצדדים, מקבילות לרצפה.","תוך הפעלת שרירי הבטן, הרימו את הכתפיים מהרצפה ומתחו את יד ימין לכיוון עקב ימין.","חזרו לנקודת ההתחלה וחזרו על התנועה בצד שמאל, במתיחת יד שמאל לכיוון עקב שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight out to the sides, parallel to the ground.","Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.","Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.","Continue alternating sides for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Вытяните руки прямо в стороны, параллельно земле.","Включив пресс, оторвите плечи от земли и протяните правую руку к правой пятке.","Вернитесь в исходное положение и повторите то же самое с левой стороны, потянув левую руку к левой пятке.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende los brazos hacia los lados, paralelos al suelo.","Activando el abdomen, levanta los hombros del suelo y lleva la mano derecha hacia el talón derecho.","Regresa a la posición inicial y repite del lado izquierdo, llevando la mano izquierda hacia el talón izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0007","name":"alternate lateral pulldown","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids"],"target":"lats","image":"images/0007-4IKbhHV.jpg","gif_url":"videos/0007-4IKbhHV.gif","instruction_steps":{"he":["שבו על מכשיר הכבלים עם גב ישר וכפות רגליים על הרצפה.","אחזו בידיות באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היטו את הגוף מעט לאחור ומשכו את הידיות לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה, ואז שחררו באיטיות את הידיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the cable machine with your back straight and feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на канатный тренажер, выпрямив спину и поставив ноги на землю.","Возьмитесь за ручки хватом сверху, на расстоянии чуть шире плеч.","Слегка откиньтесь назад и потяните ручки к груди, сжимая лопатки вместе.","Задержитесь на мгновение на пике движения, затем медленно отпустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en la máquina de cable con la espalda recta y los pies apoyados en el suelo.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Inclínate ligeramente hacia atrás y lleva las agarraderas hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1368","name":"ankle circles","category":"lower legs","body_part":"lower legs","equipment":"body weight","muscle_group":"ankle stabilizers","secondary_muscles":["ankle stabilizers"],"target":"calves","image":"images/1368-uL9CsKm.jpg","gif_url":"videos/1368-uL9CsKm.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים ישרות לפניכם.","הרימו רגל אחת מהרצפה וסובבו את הקרסול בתנועה מעגלית.","בצעו את מספר הסיבובים הרצוי בכיוון אחד, ואז החליפו כיוון.","חזרו על התנועה עם הרגל השנייה."],"en":["Sit on the ground with your legs extended in front of you.","Lift one leg off the ground and rotate your ankle in a circular motion.","Perform the desired number of circles in one direction, then switch to the other direction.","Repeat with the other leg."],"ru":["Сядьте на пол, вытянув ноги перед собой.","Поднимите одну ногу с земли и сделайте круговые движения лодыжкой.","Выполните нужное количество кругов в одну сторону, затем переключитесь на другую сторону.","Повторите с другой ногой."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti.","Levanta una pierna del suelo y rota el tobillo con un movimiento circular.","Realiza el número de círculos deseado en una dirección, luego cambia a la dirección contraria.","Repite con la otra pierna."]}},{"id":"3293","name":"archer pull up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/3293-72BC5Za.jpg","gif_url":"videos/3293-72BC5Za.gif","instruction_steps":{"he":["התחילו בתלייה על מוט מתח באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הפעילו את הליבה ומשכו את השכמות מטה ולאחור.","תוך כדי המשיכה למעלה, כופפו יד אחת והביאו את המרפק לכיוון הצד, תוך שמירה על היד השנייה ישרה.","המשיכו למשוך עד שהסנטר מעל המוט והיד הכפופה מכווצת לגמרי.","הורידו את עצמכם חזרה בשליטה, ביישור היד הכפופה, וחזרו על התנועה בצד השני.","החליפו צדדים בכל חזרה."],"en":["Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.","Continue pulling until your chin is above the bar and your bent arm is fully flexed.","Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.","Alternate sides with each repetition."],"ru":["Начните с подвешивания на перекладине хватом сверху, на расстоянии чуть шире плеч.","Напрягите корпус и потяните лопатки вниз и назад.","Подтягиваясь, согните одну руку и отведите локоть в сторону, сохраняя при этом другую руку прямой.","Продолжайте тянуть до тех пор, пока подбородок не окажется над перекладиной, а согнутая рука полностью не согнется.","Контролируемое опускание вниз, выпрямляя согнутую руку и повторяя движение на другую сторону.","Меняйте стороны при каждом повторении."],"es":["Comienza colgándote de una barra de dominadas con un agarre prono, un poco más separado que el ancho de los hombros.","Activa el core y lleva los omóplatos hacia abajo y atrás.","Mientras te elevas, flexiona un brazo y lleva el codo hacia el costado, manteniendo el otro brazo recto.","Continúa subiendo hasta que la barbilla quede por encima de la barra y el brazo flexionado esté completamente doblado.","Bájate de nuevo con control, estirando el brazo flexionado y repitiendo el movimiento del otro lado.","Alterna los lados en cada repetición."]}},{"id":"3294","name":"archer push up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/3294-A9qxk2F.jpg","gif_url":"videos/3294-A9qxk2F.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים מעט רחבות מרוחב הכתפיים.","מתחו יד אחת ישר הצידה, מקבילה לרצפה.","הורידו את הגוף בכיפוף מרפקים, תוך שמירה על גב ישר וליבה מופעלת.","דחפו חזרה למעלה לנקודת ההתחלה.","חזרו על התנועה בצד השני, במתיחת היד הנגדית הצידה.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart.","Extend one arm straight out to the side, parallel to the ground.","Lower your body by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position.","Repeat on the other side, extending the opposite arm out to the side.","Continue alternating sides for the desired number of repetitions."],"ru":["Начните с позиции отжимания, поставив руки чуть шире ширины плеч.","Вытяните одну руку прямо в сторону, параллельно земле.","Опустите тело, согнув локти, сохраняя спину прямой и напряженным корпусом.","Вернитесь в исходное положение.","Повторите то же самое с другой стороны, вытягивая противоположную руку в сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros.","Extiende un brazo hacia el lado, paralelo al suelo.","Baja el cuerpo flexionando los codos, manteniendo la espalda recta y el core activado.","Empuja hacia arriba para volver a la posición inicial.","Repite del otro lado, extendiendo el brazo opuesto hacia el lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"2355","name":"arm slingers hanging bent knee legs","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"abs","image":"images/2355-uWpxD4v.jpg","gif_url":"videos/2355-uWpxD4v.gif","instruction_steps":{"he":["היתלו על מוט מתח עם ידיים ישרות לגמרי וברכיים כפופות בזווית של 90 מעלות.","הפעילו את שרירי הליבה והרימו את הברכיים לכיוון החזה, קרוב ככל האפשר למרפקים.","הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.","Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, полностью выпрямив руки и согнув колени под углом 90 градусов.","Напрягите корпус и поднимите колени к груди, приближая их как можно ближе к локтям.","Медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las rodillas flexionadas formando un ángulo de 90 grados.","Activa el core y levanta las rodillas hacia el pecho, acercándolas lo más posible a los codos.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2333","name":"arm slingers hanging straight legs","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"abs","image":"images/2333-PXTIwgu.jpg","gif_url":"videos/2333-PXTIwgu.gif","instruction_steps":{"he":["היתלו על מוט מתח עם ידיים ישרות לגמרי ורגליים ישרות כלפי מטה.","הפעילו את שרירי הליבה והרימו את הרגליים לפניכם עד שהן מקבילות לרצפה.","החזיקו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your arms fully extended and your legs straight down.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Hold for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, полностью вытянув руки и опустив ноги вниз.","Напрягите корпус и поднимите ноги перед собой, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas estiradas hacia abajo.","Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo.","Mantén un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3214","name":"arms apart circular toe touch (male)","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","calves"],"target":"glutes","image":"images/3214-RtyAsy1.jpg","gif_url":"videos/3214-RtyAsy1.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וידיים מתוחות לצדדים.","תוך שמירה על רגליים ישרות, הטו את הגו קדימה מהמותניים והושיטו את יד ימין לכיוון קצות האצבעות של הרגליים.","תוך ההושטה מטה, הרימו בו-זמנית את רגל שמאל ישר לאחור, תוך שמירה על שיווי משקל.","חזרו לנקודת ההתחלה וחזרו על התנועה עם יד שמאל מושטת לכיוון קצות האצבעות ורגל ימין מורמת לאחור.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and arms extended to the sides.","Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.","As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.","Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, руки вытянуты в стороны.","Держа ноги прямыми, наклонитесь вперед в талии и дотянитесь правой рукой до пальцев ног.","Наклоняясь вниз, одновременно поднимите левую ногу прямо позади себя, сохраняя равновесие.","Вернитесь в исходное положение и повторите движение, потянув левую руку к пальцам ног и подняв правую ногу позади себя.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.","Manteniendo las piernas rectas, flexiona el torso hacia adelante desde la cintura y lleva la mano derecha hacia los dedos de los pies.","Mientras bajas, levanta simultáneamente la pierna izquierda recta detrás de ti, manteniendo el equilibrio.","Regresa a la posición inicial y repite el movimiento llevando la mano izquierda hacia los dedos de los pies y levantando la pierna derecha detrás de ti.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"3204","name":"arms overhead full sit-up (male)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/3204-NAkmgdx.jpg","gif_url":"videos/3204-NAkmgdx.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","מתחו את הידיים מעל הראש, כשהן ישרות.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד שהגו זקוף.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms overhead, keeping them straight.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Вытяните руки над головой, сохраняя их прямыми.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется в вертикальном положении.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende los brazos por encima de la cabeza, manteniéndolos rectos.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso quede erguido.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0009","name":"assisted chest dip (kneeling)","category":"chest","body_part":"chest","equipment":"leverage machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0009-PAgTVaK.jpg","gif_url":"videos/0009-PAgTVaK.gif","instruction_steps":{"he":["כווננו את המכשיר לגובה הרצוי וקבעו את הברכיים על הכרית.","אחזו בידיות עם כפות ידיים כלפי מטה וידיים ישרות לגמרי.","הורידו את הגוף בכיפוף מרפקים עד שהזרועות העליונות מקבילות לרצפה.","עצרו לרגע, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with your palms facing down and your arms fully extended.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте машину на желаемую высоту и зафиксируйте колени на подставке.","Возьмитесь за ручки ладонями вниз и полностью выпрямите руки.","Опустите тело, сгибая локти, пока плечи не станут параллельны полу.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla.","Agarra las agarraderas con las palmas hacia abajo y los brazos completamente extendidos.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Haz una pausa por un momento, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0011","name":"assisted hanging knee raise","category":"waist","body_part":"waist","equipment":"assisted","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0011-03lzqwk.jpg","gif_url":"videos/0011-03lzqwk.gif","instruction_steps":{"he":["היתלו על מוט מתח עם ידיים ישרות לגמרי וכפות ידיים פונות מכם.","הפעילו את שרירי הליבה והרימו את הברכיים לכיוון החזה, בכיפוף ירכיים וברכיים.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ שרירי הבטן.","הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, полностью вытянув руки и повернув ладони от себя.","Задействуйте мышцы корпуса и поднимите колени к груди, сгибая бедра и колени.","Задержитесь на мгновение в верхней точке движения, напрягая пресс.","Медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las rodillas hacia el pecho, flexionando las caderas y las rodillas.","Haz una pausa por un momento en la parte superior del movimiento, apretando el abdomen.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0010","name":"assisted hanging knee raise with throw down","category":"waist","body_part":"waist","equipment":"assisted","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0010-8K0w2yA.jpg","gif_url":"videos/0010-8K0w2yA.gif","instruction_steps":{"he":["היתלו על מוט מתח עם ידיים ישרות לגמרי וכפות ידיים פונות מכם.","הפעילו את שרירי הליבה והרימו את הברכיים לכיוון החזה, כשהרגליים צמודות.","כשהברכיים בגובה החזה, הטילו את הרגליים בפיצוץ כלפי מטה לכיוון הרצפה, עד יישור מלא.","תנו לרגליים להתנדנד חזרה למעלה וחזרו על התנועה למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, keeping your legs together.","Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.","Allow your legs to swing back up and repeat the movement for the desired number of repetitions."],"ru":["Повисните на перекладине, полностью вытянув руки и повернув ладони от себя.","Напрягите корпус и поднимите колени к груди, держа ноги вместе.","Как только ваши колени окажутся на уровне груди, резко бросьте ноги вниз к земле, полностью выпрямляя их.","Позвольте ногам подняться и повторите движение желаемое количество повторений."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las rodillas hacia el pecho, manteniendo las piernas juntas.","Una vez que las rodillas estén a la altura del pecho, lanza las piernas explosivamente hacia el suelo, extendiéndolas por completo.","Deja que las piernas se balanceen de vuelta hacia arriba y repite el movimiento el número de repeticiones deseado."]}},{"id":"1708","name":"assisted lying calves stretch","category":"lower legs","body_part":"lower legs","equipment":"assisted","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1708-GxDwDX0.jpg","gif_url":"videos/1708-GxDwDX0.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות.","כופפו ברך אחת והניחו את כף הרגל על הרצפה.","בעזרת הידיים או מגבת, משכו בעדינות את קצות האצבעות של הרגל לכיוון הגוף, עד תחושת מתיחה בתאומים.","החזיקו את המתיחה 20–30 שניות.","שחררו את המתיחה וחזרו עליה ברגל השנייה."],"en":["Lie on your back with your legs extended.","Bend one knee and place your foot flat on the ground.","Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other leg."],"ru":["Лягте на спину, вытянув ноги.","Согните одно колено и поставьте стопу на землю.","Руками или полотенцем осторожно потяните пальцы ног к телу, чувствуя растяжение в икрах.","Удерживайте растяжку 20–30 секунд.","Освободите растяжку и повторите на другую ногу."],"es":["Túmbate sobre tu espalda con las piernas extendidas.","Flexiona una rodilla y coloca el pie plano sobre el suelo.","Con las manos o una toalla, jala suavemente los dedos del pie hacia tu cuerpo, sintiendo un estiramiento en la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Suelta el estiramiento y repite con la otra pierna."]}},{"id":"1709","name":"assisted lying glutes stretch","category":"upper legs","body_part":"upper legs","equipment":"assisted","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"glutes","image":"images/1709-yn0LjwL.jpg","gif_url":"videos/1709-yn0LjwL.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות.","כופפו את ברך ימין והניחו את קרסול ימין על ירך שמאל, מעט מעל הברך.","אחזו בירך שמאל בשתי הידיים ומשכו אותה בעדינות לכיוון החזה.","החזיקו את המתיחה 20–30 שניות.","שחררו וחזרו על התנועה בצד השני."],"en":["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."],"ru":["Лягте на спину, вытянув ноги.","Согните правое колено и положите правую лодыжку на левое бедро, чуть выше колена.","Возьмите левое бедро обеими руками и осторожно потяните его к груди.","Удерживайте растяжку 20–30 секунд.","Отпустите и повторите с другой стороны."],"es":["Túmbate sobre tu espalda con las piernas extendidas.","Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla.","Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho.","Mantén el estiramiento durante 20-30 segundos.","Suelta y repite del otro lado."]}},{"id":"1710","name":"assisted lying gluteus and piriformis stretch","category":"upper legs","body_part":"upper legs","equipment":"assisted","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"glutes","image":"images/1710-RQNVT10.jpg","gif_url":"videos/1710-RQNVT10.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות.","כופפו את ברך ימין והניחו את קרסול ימין על ירך שמאל, מעט מעל הברך.","אחזו בירך שמאל בשתי הידיים ומשכו אותה בעדינות לכיוון החזה.","החזיקו את המתיחה 20–30 שניות.","שחררו את המתיחה וחזרו עליה בצד השני."],"en":["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."],"ru":["Лягте на спину, вытянув ноги.","Согните правое колено и положите правую лодыжку на левое бедро, чуть выше колена.","Возьмите левое бедро обеими руками и осторожно потяните его к груди.","Удерживайте растяжку 20–30 секунд.","Освободите растяжку и повторите с другой стороны."],"es":["Túmbate sobre tu espalda con las piernas extendidas.","Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla.","Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho.","Mantén el estiramiento durante 20-30 segundos.","Suelta el estiramiento y repite del otro lado."]}},{"id":"0012","name":"assisted lying leg raise with lateral throw down","category":"waist","body_part":"waist","equipment":"assisted","muscle_group":"hip flexors","secondary_muscles":["hip flexors","obliques"],"target":"abs","image":"images/0012-UGhRD1A.jpg","gif_url":"videos/0012-UGhRD1A.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וידיים לצידי הגוף.","הניחו את הידיים מתחת לישבן לתמיכה.","הפעילו את שרירי הבטן והרימו את הרגליים מהרצפה, כשהן ישרות.","תוך שמירה על רגליים צמודות, הורידו אותן לצד אחד עד כמה סנטימטרים מעל הרצפה.","עצרו לרגע, ואז הרימו את הרגליים חזרה לנקודת ההתחלה.","חזרו על התנועה לצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift your legs off the ground, keeping them straight.","While keeping your legs together, lower them to one side until they are a few inches above the ground.","Pause for a moment, then lift your legs back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Лягте на спину, вытянув ноги и положив руки по бокам.","Положите руки под ягодицы для поддержки.","Напрягите пресс и поднимите ноги от земли, сохраняя их прямыми.","Держа ноги вместе, опустите их в сторону, пока они не окажутся на несколько дюймов над землей.","Сделайте паузу на мгновение, затем поднимите ноги обратно в исходное положение.","Повторите движение в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Coloca las manos debajo de los glúteos como apoyo.","Activa el abdomen y levanta las piernas del suelo, manteniéndolas rectas.","Manteniendo las piernas juntas, bájalas hacia un lado hasta que queden a pocos centímetros del suelo.","Haz una pausa por un momento, luego levanta las piernas de vuelta a la posición inicial.","Repite el movimiento hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0013","name":"assisted lying leg raise with throw down","category":"waist","body_part":"waist","equipment":"assisted","muscle_group":"hip flexors","secondary_muscles":["hip flexors","quadriceps"],"target":"abs","image":"images/0013-VX5YKR5.jpg","gif_url":"videos/0013-VX5YKR5.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וידיים לצידי הגוף.","הניחו את הידיים מתחת לישבן לתמיכה.","הפעילו את הליבה והרימו את הרגליים מהרצפה, כשהן ישרות.","הרימו את הרגליים עד שהן ניצבות לרצפה.","הורידו את הרגליים חזרה לנקודת ההתחלה.","בו-זמנית, הטילו את הרגליים מטה לכיוון הרצפה, כשהן ישרות.","הרימו את הרגליים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, keeping them straight.","Raise your legs until they are perpendicular to the ground.","Lower your legs back down to the starting position.","Simultaneously, throw your legs down towards the ground, keeping them straight.","Raise your legs back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, вытянув ноги и положив руки по бокам.","Положите руки под ягодицы для поддержки.","Напрягите корпус и поднимите ноги от земли, сохраняя их прямыми.","Поднимайте ноги до тех пор, пока они не станут перпендикулярно земле.","Опустите ноги обратно в исходное положение.","Одновременно опустите ноги на землю, сохраняя их прямыми.","Поднимите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Coloca las manos debajo de los glúteos como apoyo.","Activa el core y levanta las piernas del suelo, manteniéndolas rectas.","Eleva las piernas hasta que queden perpendiculares al suelo.","Baja las piernas de vuelta a la posición inicial.","Simultáneamente, lanza las piernas hacia el suelo, manteniéndolas rectas.","Eleva las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0014","name":"assisted motion russian twist","category":"waist","body_part":"waist","equipment":"medicine ball","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0014-r7cT9YD.jpg","gif_url":"videos/0014-r7cT9YD.gif","instruction_steps":{"he":["שבו על הרצפה עם ברכיים כפופות וכפות רגליים על הרצפה.","החזיקו את כדור הכוח בשתי ידיים מול החזה.","היטו את הגוף מעט לאחור, תוך הפעלת שרירי הבטן ושמירה על גב ישר.","סובבו באיטיות את הגו ימינה, בהבאת כדור הכוח לצד ימין של הגוף.","עצרו לרגע, ואז סובבו את הגו שמאלה, בהבאת כדור הכוח לצד שמאל של הגוף.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Sit on the ground with your knees bent and feet flat on the floor.","Hold the medicine ball with both hands in front of your chest.","Lean back slightly, engaging your abs and keeping your back straight.","Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.","Continue alternating sides for the desired number of repetitions."],"ru":["Сядьте на пол, согните колени и поставьте ступни на пол.","Держите медицинский мяч обеими руками перед грудью.","Слегка откиньтесь назад, напрягая пресс и держа спину прямо.","Медленно поверните туловище вправо, направляя медицинский мяч к правой стороне тела.","Сделайте паузу на мгновение, затем поверните туловище влево, направляя медицинский мяч к левой стороне тела.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.","Sostén el balón medicinal con ambas manos frente al pecho.","Inclínate ligeramente hacia atrás, activando el abdomen y manteniendo la espalda recta.","Gira lentamente el torso hacia la derecha, llevando el balón medicinal hacia el lado derecho del cuerpo.","Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando el balón medicinal hacia el lado izquierdo del cuerpo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0015","name":"assisted parallel close grip pull-up","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0015-vrhHa6D.jpg","gif_url":"videos/0015-vrhHa6D.gif","instruction_steps":{"he":["כווננו את המכשיר למשקל ולגובה הרצויים.","הניחו את הידיים על המקבילים באחיזה צרה, כפות ידיים פונות זו לזו.","היתלו על המוטות עם ידיים ישרות לגמרי וכפות רגליים באוויר.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון המוטות, תוך שמירה על מרפקים קרובים לגוף.","המשיכו למשוך עד שהסנטר מעל המוטות.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to your desired weight and height.","Place your hands on the parallel bars with a close grip, palms facing each other.","Hang from the bars with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.","Continue pulling until your chin is above the bars.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Настройте машину на желаемый вес и рост.","Положите руки на параллельные брусья узким хватом, ладонями друг к другу.","Повисните на перекладинах, полностью вытянув руки и оторвав ноги от земли.","Напрягите мышцы спины и подтяните тело к перекладинам, держа локти близко к телу.","Продолжайте тянуть, пока подбородок не окажется над перекладинами.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina al peso y la altura deseados.","Coloca las manos en las barras paralelas con un agarre cerrado, con las palmas mirándose entre sí.","Cuélgate de las barras con los brazos completamente extendidos y los pies sin tocar el suelo.","Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las barras, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de las barras.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0016","name":"assisted prone hamstring","category":"upper legs","body_part":"upper legs","equipment":"assisted","muscle_group":"glutes","secondary_muscles":["glutes","lower back"],"target":"hamstrings","image":"images/0016-VedGSby.jpg","gif_url":"videos/0016-VedGSby.gif","instruction_steps":{"he":["שכבו על הבטן על מזרן או ספסל עם רגליים ישרות לגמרי.","היעזרו בבן/בת זוג או בגומיית התנגדות לקיבוע הקרסוליים.","הפעילו את שרירי הירך האחורית והרימו את הרגליים לכיוון הישבן, תוך שמירה על ברכיים ישרות.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie face down on a mat or bench with your legs fully extended.","Have a partner or use a resistance band to secure your ankles.","Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте лицом вниз на коврик или скамью, полностью вытянув ноги.","Попросите партнера или используйте эспандер, чтобы зафиксировать лодыжки.","Напрягите мышцы задней поверхности бедра и поднимите ноги к ягодицам, держа колени прямо.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo sobre una esterilla o un banco con las piernas completamente extendidas.","Pide a un compañero o usa una banda elástica para sujetar tus tobillos.","Activa los isquiotibiales y levanta las piernas hacia los glúteos, manteniendo las rodillas rectas.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1713","name":"assisted prone lying quads stretch","category":"upper legs","body_part":"upper legs","equipment":"assisted","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"quads","image":"images/1713-YUYAMEj.jpg","gif_url":"videos/1713-YUYAMEj.gif","instruction_steps":{"he":["שכבו על הבטן על הרצפה עם רגליים מתוחות.","כופפו את ברך שמאל והושיטו את יד שמאל לאחור לאחיזת כף רגל שמאל או הקרסול.","משכו בעדינות את כף רגל שמאל לכיוון הישבן, עד תחושת מתיחה בארבע ראשי השמאלי.","החזיקו את המתיחה 20–30 שניות, ואז שחררו.","חזרו על התנועה עם רגל ימין."],"en":["Lie face down on the ground with your legs extended.","Bend your left knee and reach back with your left hand to grab your left foot or ankle.","Gently pull your left foot towards your glutes, feeling a stretch in your left quad.","Hold the stretch for 20-30 seconds, then release.","Repeat with your right leg."],"ru":["Лягте лицом вниз на землю, вытянув ноги.","Согните левое колено и потянитесь левой рукой назад, чтобы схватить левую ступню или лодыжку.","Аккуратно подтяните левую ногу к ягодицам, чувствуя растяжение в левом квадрицепсе.","Удерживайте растяжку 20–30 секунд, затем расслабьтесь.","Повторите с правой ногой."],"es":["Túmbate boca abajo en el suelo con las piernas extendidas.","Flexiona la rodilla izquierda y lleva la mano izquierda hacia atrás para agarrar el pie o el tobillo izquierdo.","Jala suavemente el pie izquierdo hacia los glúteos, sintiendo un estiramiento en el cuádriceps izquierdo.","Mantén el estiramiento durante 20-30 segundos, luego suelta.","Repite con la pierna derecha."]}},{"id":"1714","name":"assisted prone rectus femoris stretch","category":"waist","body_part":"waist","equipment":"assisted","muscle_group":"quadriceps","secondary_muscles":["quadriceps"],"target":"abs","image":"images/1714-2Ryn564.jpg","gif_url":"videos/1714-2Ryn564.gif","instruction_steps":{"he":["שכבו על הבטן על הרצפה עם רגליים ישרות.","כופפו את ברך ימין והושיטו את יד ימין לאחור לאחיזת כף רגל ימין או הקרסול.","משכו בעדינות את כף רגל ימין או הקרסול לכיוון הישבן, עד תחושת מתיחה בקדמת ירך ימין.","החזיקו את המתיחה 20–30 שניות.","שחררו וחזרו על התנועה בצד השני."],"en":["Lie face down on the ground with your legs straight.","Bend your right knee and reach back with your right hand to grab your right foot or ankle.","Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."],"ru":["Лягте лицом вниз на землю, выпрямив ноги.","Согните правое колено и протяните правую руку назад, чтобы схватить правую ступню или лодыжку.","Аккуратно потяните правую ступню или лодыжку к ягодицам, ощущая растяжение в передней части правого бедра.","Удерживайте растяжку 20–30 секунд.","Отпустите и повторите с другой стороны."],"es":["Túmbate boca abajo en el suelo con las piernas rectas.","Flexiona la rodilla derecha y lleva la mano derecha hacia atrás para agarrar el pie o el tobillo derecho.","Jala suavemente el pie o el tobillo derecho hacia los glúteos, sintiendo un estiramiento en la parte frontal del muslo derecho.","Mantén el estiramiento durante 20-30 segundos.","Suelta y repite del otro lado."]}},{"id":"0017","name":"assisted pull-up","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0017-kiJ4Z2K.jpg","gif_url":"videos/0017-kiJ4Z2K.gif","instruction_steps":{"he":["כווננו את המכשיר להגדרות המשקל והגובה הרצויות.","אחזו בידיות באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היתלו עם ידיים ישרות לגמרי וכפות רגליים באוויר.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון הידיות, תוך שמירה על מרפקים קרובים לגוף.","המשיכו למשוך עד שהסנטר מעל הידיות.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to your desired weight and height settings.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Настройте машину на желаемые параметры веса и роста.","Возьмитесь за ручки хватом сверху, на расстоянии чуть шире плеч.","Висите, полностью вытянув руки и оторвав ноги от земли.","Задействуйте мышцы спины и подтяните тело к ручкам, держа локти близко к телу.","Продолжайте тянуть, пока подбородок не окажется над ручками.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina a los valores de peso y altura deseados.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Cuélgate con los brazos completamente extendidos y los pies sin tocar el suelo.","Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las agarraderas, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de las agarraderas.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1716","name":"assisted seated pectoralis major stretch with stability ball","category":"chest","body_part":"chest","equipment":"assisted","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1716-RoV1Rfa.jpg","gif_url":"videos/1716-RoV1Rfa.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו כדור פיזיו בשתי הידיים ומתחו את הידיים ישר לפניכם.","הורידו את כדור הפיזיו באיטיות לכיוון החזה, עד תחושת מתיחה בשרירי החזה.","החזיקו את המתיחה כמה שניות, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a stability ball with both hands and extend your arms straight out in front of you.","Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч, поставив ноги на землю и выпрямив спину.","Возьмите мяч для стабилизации обеими руками и вытяните руки прямо перед собой.","Медленно опустите мяч-стабилизатор к груди, чувствуя растяжение грудных мышц.","Удерживайте растяжку несколько секунд, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.","Sostén un balón de estabilidad con ambas manos y extiende los brazos rectos frente a ti.","Baja lentamente el balón de estabilidad hacia el pecho, sintiendo un estiramiento en los pectorales.","Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1712","name":"assisted side lying adductor stretch","category":"upper legs","body_part":"upper legs","equipment":"assisted","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"adductors","image":"images/1712-hC6oYY5.jpg","gif_url":"videos/1712-hC6oYY5.gif","instruction_steps":{"he":["שכבו על הצד עם רגליים ישרות זו על גבי זו.","כופפו מעט את הרגל התחתונה לייצוב.","הניחו את כף הרגל העליונה על משטח יציב, כמו ספסל או מדרגה.","תוך שמירה על הרגל העליונה ישרה, הורידו אותה באיטיות לכיוון הרצפה, עד תחושת מתיחה בירך הפנימית.","החזיקו את המתיחה 20–30 שניות.","חזרו לנקודת ההתחלה וחזרו על התנועה בצד השני."],"en":["Lie on your side with your legs straight and stacked on top of each other.","Bend your bottom leg slightly for stability.","Place your top foot on a stable surface, such as a bench or step.","Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.","Hold the stretch for 20-30 seconds.","Return to the starting position and repeat on the other side."],"ru":["Лягте на бок, выпрямив ноги и положив их друг на друга.","Слегка согните нижнюю ногу для устойчивости.","Поставьте верхнюю ногу на устойчивую поверхность, например на скамью или ступеньку.","Удерживая верхнюю ногу прямой, медленно опустите ее к земле, чувствуя растяжение внутренней части бедра.","Удерживайте растяжку 20–30 секунд.","Вернитесь в исходное положение и повторите то же самое в другую сторону."],"es":["Túmbate de lado con las piernas rectas y apiladas una sobre la otra.","Flexiona ligeramente la pierna de abajo para mayor estabilidad.","Coloca el pie de arriba sobre una superficie estable, como un banco o un escalón.","Manteniendo la pierna de arriba recta, bájala lentamente hacia el suelo, sintiendo un estiramiento en la parte interna del muslo.","Mantén el estiramiento durante 20-30 segundos.","Regresa a la posición inicial y repite del otro lado."]}},{"id":"1758","name":"assisted sit-up","category":"waist","body_part":"waist","equipment":"assisted","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/1758-aumB2IV.jpg","gif_url":"videos/1758-aumB2IV.gif","instruction_steps":{"he":["שבו על קצה ספסל או בקשו ממישהו להחזיק את כפות הרגליים.","שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the edge of a bench or have someone hold your feet down.","Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на край скамьи или попросите кого-нибудь держать вас за ноги.","Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el borde de un banco o pide a alguien que te sujete los pies.","Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1431","name":"assisted standing chin-up","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1431-7OeHptV.jpg","gif_url":"videos/1431-7OeHptV.gif","instruction_steps":{"he":["כווננו את המכשיר לרמת הסיוע הרצויה.","עמדו על משטח הרגליים ואחזו בידיות באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שמרו על חזה מורם וכתפיים לאחור, הפעילו את הליבה וכופפו ברכיים מעט.","משכו את הגוף למעלה בכיפוף המרפקים ודחיפתם מטה לכיוון צידי הגוף.","המשיכו למשוך עד שהסנטר מעל המוט.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to your desired assistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your chest up and shoulders back, engage your core, and slightly bend your knees.","Pull your body up by flexing your elbows and driving your elbows down towards your sides.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Настройте машину на желаемый уровень помощи.","Встаньте на платформу для ног и возьмитесь за рукоятки хватом сверху, на расстоянии чуть шире плеч.","Держите грудь поднятой, а плечи отведенными назад, задействуйте корпус и слегка согните колени.","Поднимите тело вверх, сгибая локти и направляя локти вниз в стороны.","Продолжайте тянуть, пока подбородок не окажется над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina al nivel de asistencia deseado.","Sube a la plataforma para los pies y agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Mantén el pecho arriba y los hombros atrás, activa el core y flexiona ligeramente las rodillas.","Levanta el cuerpo flexionando los codos y llevándolos hacia abajo, en dirección a los costados.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1432","name":"assisted standing pull-up","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1432-f4xtKBj.jpg","gif_url":"videos/1432-f4xtKBj.gif","instruction_steps":{"he":["כווננו את המכשיר להגדרות המשקל והגובה הרצויות.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו בידיות באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הפעילו את רחב הגבי והבייספס, ומשכו את עצמכם למעלה לכיוון הידיות.","עצרו לרגע בנקודה העליונה, תוך כיווץ שרירי הגב.","הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to your desired weight and height settings.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Engage your lats and biceps, and pull yourself up towards the handles.","Pause for a moment at the top, squeezing your back muscles.","Slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Настройте машину на желаемые параметры веса и роста.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмитесь за ручки хватом сверху, на расстоянии чуть шире плеч.","Задействуйте широчайшие и бицепсы и подтяните себя к ручкам.","Задержитесь на мгновение в верхней точке, напрягая мышцы спины.","Медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina a los valores de peso y altura deseados.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Activa los dorsales y los bíceps, y levántate hacia las agarraderas.","Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda.","Bájate lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0018","name":"assisted standing triceps extension (with towel)","category":"upper arms","body_part":"upper arms","equipment":"assisted","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0018-7HcfMBP.jpg","gif_url":"videos/0018-7HcfMBP.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מגבת בשתי ידיים מאחורי הראש.","שמרו על מרפקים קרובים לאוזניים וזרועות עליונות ללא תזוזה.","יישרו באיטיות את האמות כלפי מעלה, בכיווץ הטרייספס בנקודה העליונה.","עצרו לרגע, ואז הורידו את המגבת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.","Keep your elbows close to your ears and your upper arms stationary.","Slowly extend your forearms upward, squeezing your triceps at the top.","Pause for a moment, then slowly lower the towel back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите полотенце обеими руками за головой.","Держите локти близко к ушам, а плечи неподвижно.","Медленно вытяните предплечья вверх, сжимая трицепсы вверху.","Сделайте паузу на мгновение, затем медленно опустите полотенце обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una toalla con ambas manos detrás de la cabeza.","Mantén los codos cerca de las orejas y la parte superior de los brazos quieta.","Extiende lentamente los antebrazos hacia arriba, apretando los tríceps en la parte superior.","Haz una pausa por un momento, luego baja lentamente la toalla de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0019","name":"assisted triceps dip (kneeling)","category":"upper arms","body_part":"upper arms","equipment":"leverage machine","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0019-J60bN17.jpg","gif_url":"videos/0019-J60bN17.gif","instruction_steps":{"he":["כווננו את המכשיר למשקל ולגובה הרצויים.","כרעו על הכרית מול המכשיר, כשהידיים אוחזות בידיות.","הורידו את הגוף בכיפוף מרפקים, תוך שמירה על גב ישר וקרוב למכשיר.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to your desired weight and height.","Kneel down on the pad facing the machine, with your hands gripping the handles.","Lower your body by bending your elbows, keeping your back straight and close to the machine.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Настройте машину на желаемый вес и рост.","Встаньте на колени лицом к тренажеру, взявшись руками за ручки.","Опустите тело, согнув локти, держа спину прямо и близко к тренажеру.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina al peso y la altura deseados.","Arrodíllate sobre la almohadilla frente a la máquina, con las manos sujetando las agarraderas.","Baja el cuerpo flexionando los codos, manteniendo la espalda recta y cerca de la máquina.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2364","name":"assisted wide-grip chest dip (kneeling)","category":"chest","body_part":"chest","equipment":"leverage machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/2364-PnZJIrk.jpg","gif_url":"videos/2364-PnZJIrk.gif","instruction_steps":{"he":["כווננו את המכשיר לגובה הרצוי וקבעו את הברכיים על הכרית.","אחזו בידיות באחיזה רחבה ושמרו על כיפוף קל במרפקים.","הורידו את הגוף בכיפוף מרפקים עד שהזרועות העליונות מקבילות לרצפה.","דחפו את עצמכם חזרה למעלה לנקודת ההתחלה על ידי יישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with a wide grip and keep your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте машину на желаемую высоту и зафиксируйте колени на подставке.","Возьмитесь за рукоятки широким хватом и держите локти слегка согнутыми.","Опустите тело, сгибая локти, пока плечи не станут параллельны полу.","Вернитесь в исходное положение, вытянув руки.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla.","Agarra las agarraderas con un agarre amplio y mantén los codos ligeramente flexionados.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"3220","name":"astride jumps (male)","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3220-f9lVSSI.jpg","gif_url":"videos/3220-f9lVSSI.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","כופפו ברכיים והורידו את הגוף לעמדת סקוואט.","קפצו למעלה בפיצוץ, תוך יישור הרגליים והידיים.","באוויר, פתחו את הרגליים לצדדים והרימו את הידיים לצדדים.","נחתו ברכות עם רגליים ברוחב כתפיים, בכיפוף ברכיים לבלימת הנחיתה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively upwards, extending your legs and arms.","While in the air, spread your legs apart and bring your arms out to the sides.","Land softly with your feet shoulder-width apart, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Согните колени и опустите тело в присед.","Резко прыгните вверх, вытягивая ноги и руки.","Находясь в воздухе, разведите ноги в стороны и разведите руки в стороны.","Мягко приземлитесь, поставив ноги на ширине плеч, согнув колени, чтобы поглотить удар.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.","Salta explosivamente hacia arriba, extendiendo las piernas y los brazos.","Mientras estás en el aire, separa las piernas y lleva los brazos hacia los lados.","Aterriza suavemente con los pies separados a la altura de los hombros, flexionando las rodillas para absorber el impacto.","Repite el número de repeticiones deseado."]}},{"id":"3672","name":"back and forth step","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/3672-fNGumX0.jpg","gif_url":"videos/3672-fNGumX0.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","צעדו קדימה עם כף רגל ימין, בכיפוף הברך והורדת הגוף לעמדת מספריים.","דחפו עם כף רגל ימין וצעדו חזרה לנקודת ההתחלה.","חזרו על התנועה עם כף רגל שמאל, לסירוגין בין הרגליים בכל צעד.","המשיכו לצעוד קדימה ואחורה, בקצב אחיד.","המשיכו למשך הזמן או מספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Step forward with your right foot, bending your knee and lowering your body into a lunge position.","Push off with your right foot and step back to the starting position.","Repeat the movement with your left foot, alternating legs with each step.","Continue stepping back and forth, maintaining a steady pace.","Repeat for the desired duration or number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Сделайте шаг вперед правой ногой, согнув колено и опустив тело в положение выпада.","Оттолкнитесь правой ногой и вернитесь в исходное положение.","Повторите движение левой ногой, чередуя ноги при каждом шаге.","Продолжайте шагать вперед и назад, сохраняя устойчивый темп.","Повторяйте желаемую продолжительность или количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con el pie derecho, flexionando la rodilla y bajando el cuerpo hacia una posición de zancada.","Empuja con el pie derecho y da un paso atrás para regresar a la posición inicial.","Repite el movimiento con el pie izquierdo, alternando las piernas en cada paso.","Continúa dando pasos hacia adelante y hacia atrás, manteniendo un ritmo constante.","Repite durante la duración o el número de repeticiones deseado."]}},{"id":"1314","name":"back extension on exercise ball","category":"back","body_part":"back","equipment":"stability ball","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1314-qLpO4vV.jpg","gif_url":"videos/1314-qLpO4vV.gif","instruction_steps":{"he":["הניחו את כדור הפיזיו על הרצפה ושכבו עליו על הבטן, כשהאגן נשען על הכדור וכפות הרגליים נשענות על קיר או משטח יציב אחר.","מקמו את הידיים מאחורי הראש או מוצלבות על החזה.","הפעילו את הליבה והרימו באיטיות את פלג הגוף העליון מהכדור, ביישור הגב עד שהגוף יוצר קו ישר מהראש ועד העקבים.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Положите мяч на землю и лягте на него лицом вниз, положив бедра на мяч, а ступни упираясь в стену или другую устойчивую поверхность.","Положите руки за голову или скрестите на груди.","Напрягите корпус и медленно поднимите верхнюю часть тела с мяча, вытягивая спину до тех пор, пока тело не образует прямую линию от головы до пяток.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared u otra superficie estable.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3297","name":"back lever","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms","core"],"target":"upper back","image":"images/3297-GaSzzuh.jpg","gif_url":"videos/3297-GaSzzuh.gif","instruction_steps":{"he":["התחילו בתלייה על מוט מתח באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","הפעילו את הליבה ומשכו את השכמות מטה ולאחור.","כופפו ברכיים ואספו אותן לכיוון החזה.","הרימו באיטיות את הרגליים, כשהן ישרות, עד שהגוף מקביל לרצפה.","החזיקו את התנוחה כמה שניות, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.","Hold this position for a few seconds, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с подвешивания на перекладине хватом сверху, руки чуть шире плеч.","Напрягите корпус и потяните лопатки вниз и назад.","Согните колени и подтяните их к груди.","Медленно поднимите ноги вверх, удерживая их прямыми, пока тело не станет параллельно земле.","Удерживайте это положение несколько секунд, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Activa el core y lleva los omóplatos hacia abajo y atrás.","Flexiona las rodillas y llévalas hacia el pecho.","Levanta lentamente las piernas, manteniéndolas rectas, hasta que el cuerpo quede paralelo al suelo.","Mantén esta posición durante unos segundos, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1405","name":"back pec stretch","category":"back","body_part":"back","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"lats","image":"images/1405-chfnQnM.jpg","gif_url":"videos/1405-chfnQnM.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים.","מתחו את הידיים ישר לפניכם, מקבילות לרצפה.","הצליבו את הידיים מול הגוף, כשיד ימין מעל יד שמאל.","שלבו את האצבעות וסובבו את כפות הידיים הרחק מהגוף.","הרימו באיטיות את הידיים למעלה והרחק מהגוף, עד תחושת מתיחה בגב ובחזה.","החזיקו את המתיחה 15–30 שניות, ואז שחררו.","חזרו על התנועה בצד הנגדי."],"en":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you, parallel to the ground.","Cross your arms in front of your body, with your right arm over your left arm.","Interlock your fingers and rotate your palms away from your body.","Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.","Hold the stretch for 15-30 seconds, then release.","Repeat on the opposite side."],"ru":["Встаньте прямо, ноги на ширине плеч.","Вытяните руки прямо перед собой, параллельно земле.","Скрестите руки перед телом, положив правую руку на левую.","Сцепите пальцы и поверните ладони от тела.","Медленно поднимите руки вверх и от тела, чувствуя растяжение в спине и груди.","Удерживайте растяжку 15–30 секунд, затем расслабьтесь.","Повторите на противоположной стороне."],"es":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende los brazos rectos frente a ti, paralelos al suelo.","Cruza los brazos frente al cuerpo, con el brazo derecho sobre el brazo izquierdo.","Entrelaza los dedos y gira las palmas alejándolas del cuerpo.","Levanta lentamente los brazos hacia arriba y alejándolos del cuerpo, sintiendo un estiramiento en la espalda y el pecho.","Mantén el estiramiento durante 15-30 segundos, luego suelta.","Repite del lado opuesto."]}},{"id":"1473","name":"backward jump","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes","calves"],"target":"quads","image":"images/1473-SaDOwk7.jpg","gif_url":"videos/1473-SaDOwk7.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","כופפו ברכיים מעט וקפצו לאחור, בדחיפה משתי הרגליים.","נחתו ברכות על כריות כפות הרגליים, בכיפוף ברכיים לבלימת הנחיתה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump backwards, pushing off with both feet.","Land softly on the balls of your feet, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Слегка согните колени и подпрыгните назад, отталкиваясь обеими ногами.","Мягко приземлитесь на подушечки стоп, согнув колени, чтобы поглотить удар.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Flexiona ligeramente las rodillas y salta hacia atrás, impulsándote con ambos pies.","Aterriza suavemente sobre la punta de los pies, flexionando las rodillas para absorber el impacto.","Repite el número de repeticiones deseado."]}},{"id":"0020","name":"balance board","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"calves","secondary_muscles":["calves","hamstrings","glutes"],"target":"quads","image":"images/0020-xAySMB0.jpg","gif_url":"videos/0020-xAySMB0.gif","instruction_steps":{"he":["הניחו את קרש שיווי המשקל על משטח ישר.","עלו על קרש שיווי המשקל עם כף רגל אחת, וודאו שהיא ממורכזת.","העבירו באיטיות את המשקל לכף הרגל שעל קרש שיווי המשקל, תוך הפעלת הליבה.","שמרו על שיווי משקל ויציבות תוך החזקת התנוחה למשך הזמן הרצוי.","חזרו על התרגיל עם כף הרגל השנייה."],"en":["Place the balance board on a flat surface.","Step onto the balance board with one foot, ensuring it is centered.","Slowly shift your weight onto the foot on the balance board, keeping your core engaged.","Maintain your balance and stability as you hold the position for a desired amount of time.","Repeat the exercise with the other foot."],"ru":["Поместите балансборд на ровную поверхность.","Встаньте на балансборд одной ногой, убедившись, что он находится по центру.","Медленно перенесите вес тела на ногу на балансборде, сохраняя при этом корпус напряженным.","Сохраняйте баланс и стабильность, удерживая позицию в течение желаемого периода времени.","Повторите упражнение другой ногой."],"es":["Coloca la tabla de equilibrio sobre una superficie plana.","Sube a la tabla de equilibrio con un pie, asegurándote de que esté centrado.","Desplaza lentamente tu peso hacia el pie que está sobre la tabla de equilibrio, manteniendo el core activado.","Mantén el equilibrio y la estabilidad mientras sostienes la posición durante el tiempo deseado.","Repite el ejercicio con el otro pie."]}},{"id":"0968","name":"band alternating biceps curl","category":"upper arms","body_part":"upper arms","equipment":"band","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0968-3omWx6P.jpg","gif_url":"videos/0968-3omWx6P.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את הגומייה באחיזה תחתונה, כפות ידיים כלפי מעלה.","שמרו על מרפקים צמודים לצידי הגוף וכופפו באיטיות יד אחת למעלה לכיוון הכתף, בכיווץ הבייספס בנקודה העליונה.","הורידו את היד חזרה לנקודת ההתחלה וחזרו על התנועה עם היד השנייה.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.","Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.","Lower the arm back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмитесь за ленту обратным хватом ладонями вверх.","Держите локти близко к бокам и медленно поднимите одну руку к плечу, сжимая бицепс вверху.","Опустите руку обратно в исходное положение и повторите то же самое с другой рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con un agarre supino, con las palmas hacia arriba.","Mantén los codos cerca de los costados y flexiona lentamente un brazo hacia el hombro, apretando el bíceps en la parte superior.","Baja el brazo de vuelta a la posición inicial y repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"0969","name":"band alternating v-up","category":"waist","body_part":"waist","equipment":"band","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0969-ztAa1RK.jpg","gif_url":"videos/0969-ztAa1RK.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וידיים מתוחות מעל הראש, אוחזות בגומייה.","הפעילו את שרירי הבטן והרימו את הרגליים ופלג הגוף העליון בו-זמנית, במתיחת הידיים לכיוון קצות האצבעות של הרגליים.","תוך כדי הורדת הרגליים ופלג הגוף העליון, החליפו את מיקום הרגליים בהצלבה זו על זו.","חזרו על התנועה, בהחלפת מיקום הרגליים בכל חזרה.","המשיכו למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.","Repeat the movement, alternating the position of your legs with each repetition.","Continue for the desired number of repetitions."],"ru":["Лягте на спину, выпрямите ноги и вытяните руки над головой, удерживая ленту.","Напрягите пресс и одновременно поднимите ноги и верхнюю часть тела от земли, дотягиваясь руками до пальцев ног.","Опуская ноги и верхнюю часть тела обратно вниз, поменяйте положение ног, скрещивая одну над другой.","Повторите движение, меняя положение ног при каждом повторении.","Продолжайте необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.","Activa el abdomen y levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies.","Mientras bajas las piernas y la parte superior del cuerpo de nuevo, cambia la posición de las piernas, cruzando una sobre la otra.","Repite el movimiento, alternando la posición de las piernas en cada repetición.","Continúa durante el número de repeticiones deseado."]}},{"id":"0970","name":"band assisted pull-up","category":"back","body_part":"back","equipment":"band","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0970-r1XNRYB.jpg","gif_url":"videos/0970-r1XNRYB.gif","instruction_steps":{"he":["עגנו את הגומייה למוט מתח או נקודת עיגון יציבה.","דרכו על הגומייה ואחזו במוט עם כפות ידיים פונות מכם, ידיים מעט רחבות מרוחב הכתפיים.","היתלו עם ידיים ישרות לגמרי, תוך שמירה על ליבה מופעלת וכתפיים מטה ולאחור.","משכו את הגוף למעלה לכיוון המוט בכיווץ השכמות זו לזו והובלת המרפקים מטה לכיוון האגן.","המשיכו למשוך עד שהסנטר מעל המוט, ואז הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the band to a pull-up bar or sturdy anchor point.","Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your core engaged and your shoulders down and back.","Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ленту к перекладине или прочной точке крепления.","Встаньте на ленту и возьмитесь за перекладину ладонями от себя, руки расставлены чуть шире плеч.","Висите, полностью вытянув руки, удерживая корпус напряженным, а плечи опущенными и отведенными назад.","Подтяните тело к перекладине, сжимая лопатки вместе и направляя локти вниз к бедрам.","Продолжайте тянуть, пока подбородок не окажется над перекладиной, затем медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta la banda a una barra de dominadas o a un punto de anclaje resistente.","Pisa la banda y agarra la barra con las palmas mirando hacia afuera, con las manos un poco más separadas que el ancho de los hombros.","Cuélgate con los brazos completamente extendidos, manteniendo el core activado y los hombros abajo y atrás.","Sube el cuerpo hacia la barra juntando los omóplatos y llevando los codos hacia abajo, en dirección a las caderas.","Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0971","name":"band assisted wheel rollerout","category":"waist","body_part":"waist","equipment":"band","muscle_group":"lower back","secondary_muscles":["lower back"],"target":"abs","image":"images/0971-zhF9lW4.jpg","gif_url":"videos/0971-zhF9lW4.gif","instruction_steps":{"he":["כרעו על הרצפה והחזיקו את ידיות הגומייה בשתי ידיים, כפות ידיים כלפי מטה.","הניחו את הגומייה על הרצפה לפניכם ומקמו את הידיים ברוחב כתפיים.","הפעילו את הליבה וגלגלו באיטיות את הגלגל קדימה, במתיחת הגוף רחוק ככל האפשר תוך שמירה על שליטה.","עצרו לרגע בנקודה הרחוקה ביותר, ואז גלגלו באיטיות את הגלגל חזרה לכיוון הברכיים לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Kneel on the floor and hold the handles of the band with both hands, palms facing down.","Place the band on the ground in front of you and position your hands shoulder-width apart.","Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте на колени и возьмитесь за ручки ремня обеими руками ладонями вниз.","Положите ленту на пол перед собой и поставьте руки на ширине плеч.","Включите корпус и медленно катите колесо вперед, вытягивая тело как можно дальше, сохраняя при этом контроль.","Сделайте паузу на мгновение в самой дальней точке, затем медленно перекатите колесо обратно к коленям, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Arrodíllate en el suelo y sostén las agarraderas de la banda con ambas manos, con las palmas hacia abajo.","Coloca la banda en el suelo frente a ti y posiciona las manos separadas a la altura de los hombros.","Activa el core y rueda lentamente la rueda hacia adelante, extendiendo el cuerpo lo más que puedas mientras mantienes el control.","Haz una pausa por un momento en el punto más lejano, luego rueda lentamente la rueda de vuelta hacia las rodillas para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1254","name":"band bench press","category":"chest","body_part":"chest","equipment":"band","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1254-khlHMqs.jpg","gif_url":"videos/1254-khlHMqs.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","אחזו בידיות הגומייה באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","יישרו את הידיים לגמרי, בדחיפת הגומיות הרחק מהחזה.","הורידו את הגומיות באיטיות חזרה לחזה, תוך שמירה על מרפקים בזווית של 90 מעלות.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, pushing the bands away from your chest.","Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмитесь за рукоятки ленты верхним хватом, на расстоянии чуть шире плеч.","Полностью выпрямите руки, отталкивая ленты от груди.","Медленно опустите ленты обратно к груди, держа локти под углом 90 градусов.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra las agarraderas de la banda con un agarre prono, un poco más separadas que el ancho de los hombros.","Extiende los brazos por completo, empujando las bandas alejándolas del pecho.","Baja lentamente las bandas de vuelta hacia el pecho, manteniendo los codos en un ángulo de 90 grados.","Repite el número de repeticiones deseado."]}},{"id":"0980","name":"band bent-over hip extension","category":"upper legs","body_part":"upper legs","equipment":"band","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0980-wSScovH.jpg","gif_url":"videos/0980-wSScovH.gif","instruction_steps":{"he":["עגנו את הגומייה לנקודת עיגון יציבה בגובה הקרסול.","עמדו עם הגב לנקודת העיגון, רגליים ברוחב כתפיים.","צעדו לאחור ליצירת מתח בגומייה, תוך שמירה על ברכיים כפופות מעט.","הטו את הגו מהירכיים ורכנו קדימה, תוך שמירה על עמוד שדרה ניטרלי.","מתחו את רגל ימין ישר לאחור, בכיווץ הישבן בנקודה העליונה.","הורידו את רגל ימין חזרה וחזרו על התנועה עם רגל שמאל.","המשיכו להחליף רגליים למספר החזרות הרצוי."],"en":["Attach the band to a sturdy anchor point at ankle height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step back to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and lean forward, maintaining a neutral spine.","Extend your right leg straight back, squeezing your glutes at the top.","Lower your right leg back down and repeat with the left leg.","Continue alternating legs for the desired number of repetitions."],"ru":["Прикрепите ремешок к прочной точке крепления на высоте лодыжки.","Встаньте лицом от точки крепления, поставив ноги на ширине плеч.","Сделайте шаг назад, чтобы создать напряжение в ленте, держа колени слегка согнутыми.","Наклонитесь вперед и наклонитесь вперед, сохраняя нейтральное положение позвоночника.","Вытяните правую ногу прямо назад, сжимая ягодицы вверху.","Опустите правую ногу обратно и повторите то же самое с левой ногой.","Продолжайте чередовать ноги желаемое количество повторений."],"es":["Sujeta la banda a un punto de anclaje resistente a la altura del tobillo.","Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.","Da un paso atrás para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas.","Flexiona las caderas e inclínate hacia adelante, manteniendo la columna en posición neutral.","Extiende la pierna derecha recta hacia atrás, apretando los glúteos en la parte superior.","Baja la pierna derecha de vuelta y repite con la pierna izquierda.","Continúa alternando las piernas durante el número de repeticiones deseado."]}},{"id":"0972","name":"band bicycle crunch","category":"waist","body_part":"waist","equipment":"band","muscle_group":"hip flexors","secondary_muscles":["hip flexors","obliques"],"target":"abs","image":"images/0972-tZkGYZ9.jpg","gif_url":"videos/0972-tZkGYZ9.gif","instruction_steps":{"he":["שכבו על הגב עם ידיים מאחורי הראש וברכיים כפופות.","הרימו את כפות הרגליים מהרצפה והביאו את ברך ימין לכיוון החזה, ובו-זמנית סובבו את הגו להבאת מרפק שמאל לכיוון ברך ימין.","יישרו את רגל ימין תוך הבאת ברך שמאל לכיוון החזה וסיבוב הגו להבאת מרפק ימין לכיוון ברך שמאל.","המשיכו להחליף את תנועת הסיבוב, כאילו אתם מדוושים על אופניים, תוך שמירה על ליבה מופעלת לאורך כל התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your hands behind your head and your knees bent.","Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.","Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.","Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, заведите руки за голову и согните колени.","Поднимите ноги от земли и поднесите правое колено к груди, одновременно поворачивая туловище, чтобы поднести левый локоть к правому колену.","Выпрямите правую ногу, одновременно подтягивая левое колено к груди и поворачивая туловище так, чтобы правый локоть приблизился к левому колену.","Продолжайте чередовать скручивающие движения, как если бы вы крутили педали на велосипеде, сохраняя при этом корпус задействованным на протяжении всего движения.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las manos detrás de la cabeza y las rodillas flexionadas.","Levanta los pies del suelo y lleva la rodilla derecha hacia el pecho mientras simultáneamente giras el torso para llevar el codo izquierdo hacia la rodilla derecha.","Estira la pierna derecha mientras llevas la rodilla izquierda hacia el pecho y giras el torso para llevar el codo derecho hacia la rodilla izquierda.","Continúa alternando el movimiento de giro, como si estuvieras pedaleando una bicicleta, manteniendo el core activado durante todo el movimiento.","Repite el número de repeticiones deseado."]}},{"id":"0974","name":"band close-grip pulldown","category":"back","body_part":"back","equipment":"band","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0974-DptumMx.jpg","gif_url":"videos/0974-DptumMx.gif","instruction_steps":{"he":["עגנו את הגומייה לנקודת עיגון גבוהה, כמו מוט מתח או קורה יציבה.","עמדו מול נקודת העיגון ואחזו בגומייה באחיזה תחתונה, ידיים ברוחב כתפיים.","צעדו לאחור ליצירת מתח בגומייה, תוך שמירה על רגליים ברוחב אגן.","הפעילו את הליבה ושמרו על גב ישר תוך משיכת הגומייה מטה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, ואז שחררו באיטיות את הגומייה חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.","Step back to create tension in the band, keeping your feet hip-width apart.","Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ленту к высокой точке крепления, например к перекладине или прочной балке.","Встаньте лицом к точке крепления и возьмитесь за ленту хватом снизу, руки на ширине плеч.","Сделайте шаг назад, чтобы создать натяжение ленты, держа ноги на ширине плеч.","Напрягите корпус и держите спину прямо, тянув ленту к груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно отпустите ленту обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente.","Ponte de pie frente al punto de anclaje y agarra la banda con un agarre supino, con las manos separadas a la altura de los hombros.","Da un paso atrás para generar tensión en la banda, manteniendo los pies separados a la altura de las caderas.","Activa el core y mantén la espalda recta mientras tiras de la banda hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en la parte inferior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0975","name":"band close-grip push-up","category":"upper arms","body_part":"upper arms","equipment":"band","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0975-ufaxB52.jpg","gif_url":"videos/0975-ufaxB52.gif","instruction_steps":{"he":["הניחו גומייה סביב הזרועות העליונות, מעט מעל המרפקים.","התמקמו בעמדת שכיבת סמיכה עם ידיים ישר מתחת לכתפיים והגוף בקו ישר מהראש ועד העקבים.","כופפו מרפקים והורידו את החזה לכיוון הרצפה, תוך שמירה על מרפקים צמודים לצידי הגוף.","דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place a band around your upper arms, just above the elbows.","Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Наденьте ленту на плечи чуть выше локтей.","Примите позу для отжимания, положив руки прямо под плечи, а тело образуя прямую линию от головы до пяток.","Согните локти и опустите грудь к земле, держа локти близко к бокам.","Оттолкнитесь ладонями, чтобы вытянуть руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca una banda alrededor de la parte superior de los brazos, justo por encima de los codos.","Adopta una posición de flexión de brazos con las manos justo debajo de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.","Flexiona los codos y baja el pecho hacia el suelo, manteniendo los codos cerca de los costados.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0976","name":"band concentration curl","category":"upper arms","body_part":"upper arms","equipment":"band","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0976-kmVVAfu.jpg","gif_url":"videos/0976-kmVVAfu.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם רגליים פסוקות וכפות רגליים על הרצפה.","החזיקו קצה אחד של הגומייה ביד ודרכו על הקצה השני עם כף הרגל באותו צד.","רכנו מעט קדימה והשעינו את המרפק על החלק הפנימי של הירך, מעט מעל הברך.","עם כף היד כלפי מעלה, כופפו באיטיות את היד לכיוון הכתף, תוך שמירה על הזרוע העליונה ללא תזוזה.","עצרו לרגע בנקודה העליונה, ואז הורידו את היד באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Sit on a bench or chair with your legs spread apart and your feet flat on the ground.","Hold one end of the band in your hand and step on the other end with your foot on the same side.","Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee.","With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower your hand back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Сядьте на скамью или стул, раздвинув ноги и поставив ступни на землю.","Возьмите один конец ленты в руку и наступите на другой конец ногой с той же стороны.","Слегка наклонитесь вперед и положите локоть на внутреннюю часть бедра, чуть выше колена.","Повернув ладонь вверх, медленно согните руку к плечу, сохраняя плечо неподвижным.","Задержитесь на мгновение в верхней точке, затем медленно опустите руку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Siéntate en un banco o silla con las piernas separadas y los pies apoyados en el suelo.","Sostén un extremo de la banda en la mano y pisa el otro extremo con el pie del mismo lado.","Inclínate ligeramente hacia adelante y apoya el codo en la parte interna del muslo, justo encima de la rodilla.","Con la palma hacia arriba, flexiona lentamente la mano hacia el hombro, manteniendo quieta la parte superior del brazo.","Haz una pausa por un momento en la parte superior, luego baja lentamente la mano de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"3117","name":"band fixed back close grip pulldown","category":"back","body_part":"back","equipment":"band","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/3117-4LoWllp.jpg","gif_url":"videos/3117-4LoWllp.gif","instruction_steps":{"he":["עגנו את הגומייה לנקודה קבועה מעליכם, כמו מוט מתח או קורה יציבה.","שבו על ספסל או כיסא מול הגומייה, עם כפות רגליים על הרצפה וברכיים כפופות.","אחזו בגומייה באחיזה צרה, כפות ידיים פונות אליכם.","שמרו על גב ישר והפעילו את שרירי הליבה.","משכו את הגומייה מטה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, בהרגשת הכיווץ ברחב הגבי.","שחררו באיטיות את הגומייה חזרה לנקודת ההתחלה, תוך שמירה על שליטה לאורך כל התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.","Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.","Grasp the band with a close grip, palms facing towards you.","Keep your back straight and engage your core.","Pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the band back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ленту к фиксированной точке над вами, например, к перекладине или прочной балке.","Сядьте на скамью или стул лицом к ленте, поставьте ступни на землю и согните колени.","Возьмитесь за ленту крепким хватом ладонями к себе.","Держите спину прямо и задействуйте корпус.","Потяните ленту вниз к груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, чувствуя сокращение широчайших мышц.","Медленно отпустите ленту обратно в исходное положение, сохраняя контроль на протяжении всего движения.","Повторите необходимое количество повторений."],"es":["Sujeta la banda a un punto fijo por encima de ti, como una barra de dominadas o una viga resistente.","Siéntate en un banco o silla frente a la banda, con los pies apoyados en el suelo y las rodillas flexionadas.","Agarra la banda con un agarre cerrado, con las palmas hacia ti.","Mantén la espalda recta y activa el core.","Tira de la banda hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.","Suelta lentamente la banda de vuelta a la posición inicial, manteniendo el control durante todo el movimiento.","Repite el número de repeticiones deseado."]}},{"id":"3116","name":"band fixed back underhand pulldown","category":"back","body_part":"back","equipment":"band","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/3116-ZH68exZ.jpg","gif_url":"videos/3116-ZH68exZ.gif","instruction_steps":{"he":["עגנו את הגומייה לנקודת עיגון יציבה מעל הראש.","עמדו מול נקודת העיגון עם רגליים ברוחב כתפיים.","אחזו בגומייה באחיזה תחתונה, ידיים מעט רחבות מרוחב הכתפיים.","צעדו לאחור ליצירת מתח בגומייה, תוך שמירה על ידיים מתוחות לגמרי.","הפעילו את שרירי הליבה וכווצו את השכמות זו לזו.","משכו את הגומייה מטה לכיוון החזה, כשהמרפקים מובילים.","עצרו לרגע בנקודה התחתונה של התנועה, בהרגשת הכיווץ ברחב הגבי.","שחררו באיטיות את המתח בגומייה וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the band to a sturdy anchor point above your head.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Step back to create tension in the band, keeping your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull the band down towards your chest, leading with your elbows.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ремешок к прочной точке крепления над головой.","Встаньте лицом к точке крепления, поставив ноги на ширине плеч.","Возьмите ленту обратным хватом снизу, руки на расстоянии чуть шире плеч.","Сделайте шаг назад, чтобы создать напряжение в ленте, держа руки полностью выпрямленными.","Напрягите корпус и сведите лопатки вместе.","Потяните ленту вниз к груди, ведя локтями.","Сделайте паузу на мгновение в нижней части движения, чувствуя сокращение широчайших мышц.","Медленно ослабьте натяжение ленты и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.","Da un paso atrás para generar tensión en la banda, manteniendo los brazos completamente extendidos.","Activa el core y junta los omóplatos.","Tira de la banda hacia el pecho, guiando el movimiento con los codos.","Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.","Suelta lentamente la tensión de la banda y regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0977","name":"band front lateral raise","category":"shoulders","body_part":"shoulders","equipment":"band","muscle_group":"traps","secondary_muscles":["traps","upper back"],"target":"delts","image":"images/0977-sTg7iys.jpg","gif_url":"videos/0977-sTg7iys.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את הגומייה מול הירכיים, כפות ידיים כלפי מטה.","שמרו על ידיים ישרות והרימו את הגומייה לפניכם עד שהידיים מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגומייה באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the band back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите ленту перед бедрами ладонями вниз.","Держите руки прямо и поднимите ленту перед собой, пока руки не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите ленту обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo.","Mantén los brazos rectos y levanta la banda frente a ti hasta que los brazos queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0978","name":"band front raise","category":"shoulders","body_part":"shoulders","equipment":"band","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0978-TFA88iB.jpg","gif_url":"videos/0978-TFA88iB.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את הגומייה מול הירכיים, כפות ידיים כלפי מטה.","שמרו על ידיים ישרות והרימו אותן באיטיות קדימה עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and slowly raise them forward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите ленту перед бедрами ладонями вниз.","Держите руки прямо и медленно поднимите их вперед, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo.","Mantén los brazos rectos y levántalos lentamente hacia adelante hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1408","name":"band hip lift","category":"upper legs","body_part":"upper legs","equipment":"band","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/1408-E4R8Hz1.jpg","gif_url":"videos/1408-E4R8Hz1.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו גומיית התנגדות מעט מעל הברכיים.","הפעילו את שרירי הישבן והליבה.","לחצו את העקבים לרצפה והרימו את האגן, בכיווץ הישבן בנקודה העליונה.","עצרו לרגע בנקודה העליונה, ואז הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on your back with your knees bent and feet flat on the ground.","Place a resistance band just above your knees.","Engage your glutes and core muscles.","Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Поместите ленту сопротивления чуть выше колен.","Задействуйте ягодицы и мышцы корпуса.","Прижмите пятки к земле и поднимите бедра от пола, сжимая ягодицы в верхней части.","Задержитесь на мгновение в верхней точке, затем медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca una banda elástica justo por encima de las rodillas.","Activa los glúteos y los músculos del core.","Presiona los talones contra el suelo y levanta las caderas del suelo, apretando los glúteos en la parte superior.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0979","name":"band horizontal pallof press","category":"waist","body_part":"waist","equipment":"band","muscle_group":"obliques","secondary_muscles":["obliques","glutes"],"target":"abs","image":"images/0979-9pa4H5m.jpg","gif_url":"videos/0979-9pa4H5m.gif","instruction_steps":{"he":["עגנו את הגומייה לנקודת עיגון יציבה בגובה המותניים.","עמדו ניצב לנקודת העיגון עם רגליים ברוחב כתפיים.","אחזו בידית הגומייה בשתי ידיים וצעדו הרחק מנקודת העיגון ליצירת מתח בגומייה.","הביאו את הידיים לחזה, תוך שמירה על מרפקים כפופים וצמודים לגוף.","הפעילו את הליבה ושמרו על עמידה יציבה.","מתחו את הידיים ישר לפניכם, בדחיפת הגומייה הרחק מהגוף.","החזיקו את התנוחה המתוחה כמה שניות, בהתמקדות בשמירת מתח בליבה.","החזירו באיטיות את הידיים לחזה, תוך התנגדות למשיכת הגומייה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the band to a sturdy anchor point at waist height.","Stand perpendicular to the anchor point with your feet shoulder-width apart.","Grasp the band handle with both hands and step away from the anchor point to create tension in the band.","Bring your hands to your chest, keeping your elbows bent and close to your body.","Engage your core and maintain a stable stance.","Extend your arms straight out in front of you, pushing the band away from your body.","Hold the extended position for a few seconds, focusing on maintaining tension in your core.","Slowly bring your hands back to your chest, resisting the pull of the band.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ремешок к прочной точке крепления на высоте талии.","Встаньте перпендикулярно точке крепления, поставив ноги на ширине плеч.","Возьмитесь за ручку ленты обеими руками и отойдите от точки крепления, чтобы создать натяжение ленты.","Поднесите руки к груди, держа локти согнутыми и близко к телу.","напрягите мышцы кора ​​и сохраняйте устойчивую позицию.","Вытяните руки прямо перед собой, отталкивая ленту от тела.","Удерживайте вытянутое положение в течение нескольких секунд, сосредотачиваясь на поддержании напряжения в корпусе.","Медленно верните руки к груди, сопротивляясь натяжению ленты.","Повторите необходимое количество повторений."],"es":["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.","Ponte de pie perpendicular al punto de anclaje con los pies separados a la altura de los hombros.","Agarra la agarradera de la banda con ambas manos y aléjate del punto de anclaje para generar tensión en la banda.","Lleva las manos hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo.","Activa el core y mantén una postura estable.","Extiende los brazos rectos frente a ti, empujando la banda alejándola del cuerpo.","Mantén la posición extendida durante unos segundos, enfocándote en mantener la tensión en el core.","Lleva lentamente las manos de vuelta al pecho, resistiendo el tirón de la banda.","Repite el número de repeticiones deseado."]}},{"id":"0981","name":"band jack knife sit-up","category":"waist","body_part":"waist","equipment":"band","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0981-KCBKjma.jpg","gif_url":"videos/0981-KCBKjma.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וידיים מתוחות מעל הראש, אוחזות בגומייה.","הפעילו את שרירי הבטן והרימו את הרגליים ופלג הגוף העליון בו-זמנית, והביאו את הידיים לכיוון כפות הרגליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים ופלג הגוף העליון באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, выпрямите ноги и вытяните руки над головой, удерживая ленту.","Напрягите пресс и одновременно поднимите ноги и верхнюю часть тела, поднеся руки к ногам.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги и верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.","Activa el abdomen y levanta las piernas y la parte superior del cuerpo simultáneamente, llevando las manos hacia los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0983","name":"band kneeling one arm pulldown","category":"back","body_part":"back","equipment":"band","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids"],"target":"lats","image":"images/0983-pmnrOp0.jpg","gif_url":"videos/0983-pmnrOp0.gif","instruction_steps":{"he":["עגנו את הגומייה לנקודת עיגון יציבה מעל הראש.","כרעו והחזיקו את הגומייה ביד אחת, כף יד כלפי מטה.","מתחו את היד לגמרי מעל הראש, עם כיפוף קל במרפק.","הפעילו את רחב הגבי ומשכו את הגומייה מטה לכיוון הצד, בהבאת המרפק לכיוון בית החזה.","עצרו לרגע בנקודה התחתונה, ואז שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Attach the band to a sturdy anchor point above your head.","Kneel down and hold the band with one hand, palm facing down.","Extend your arm fully overhead, keeping your elbow slightly bent.","Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Прикрепите ремешок к прочной точке крепления над головой.","Встаньте на колени и возьмите ленту одной рукой ладонью вниз.","Вытяните руку полностью над головой, слегка согнув локоть.","Задействуйте широчайшие мышцы и потяните ленту вниз в сторону, приближая локоть к грудной клетке.","Задержитесь на мгновение в нижней точке, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza.","Arrodíllate y sostén la banda con una mano, con la palma hacia abajo.","Extiende el brazo por completo por encima de la cabeza, manteniendo el codo ligeramente flexionado.","Activa los dorsales y tira de la banda hacia el costado, llevando el codo hacia las costillas.","Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0985","name":"band kneeling twisting crunch","category":"waist","body_part":"waist","equipment":"band","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0985-225x2Vd.jpg","gif_url":"videos/0985-225x2Vd.gif","instruction_steps":{"he":["עגנו את הגומייה לנקודת עיגון יציבה בגובה המותניים.","כרעו עם הגב לנקודת העיגון והחזיקו את הגומייה בשתי ידיים, עם מרפקים כפופים וצמודים לצידי הגוף.","הפעילו את שרירי הבטן וסובבו באיטיות את הגו לצד אחד, בהבאת הידיים לכיוון הירך הנגדית.","עצרו לרגע, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התנועה בצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Attach the band to a sturdy anchor point at waist height.","Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.","Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.","Pause for a moment, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Прикрепите ремешок к прочной точке крепления на высоте талии.","Встаньте на колени лицом от точки крепления и возьмитесь за ленту обеими руками, держа локти согнутыми и прижатыми к бокам.","Напрягите пресс и медленно поверните туловище в одну сторону, приближая руки к противоположному бедру.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение.","Повторите с другой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.","Arrodíllate de espaldas al punto de anclaje y sostén la banda con ambas manos, manteniendo los codos flexionados y cerca de los costados.","Activa el abdomen y gira lentamente el torso hacia un lado, llevando las manos hacia la cadera opuesta.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0984","name":"band lying hip internal rotation","category":"upper legs","body_part":"upper legs","equipment":"band","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/0984-vIICElP.jpg","gif_url":"videos/0984-vIICElP.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וגומיית התנגדות מלופפת סביב כפות הרגליים.","כופפו ברכיים והביאו אותן לכיוון החזה, כשכפות הרגליים צמודות.","סובבו באיטיות את הברכיים החוצה, זו מזו, תוך שמירה על כפות רגליים צמודות.","עצרו לרגע בסוף הסיבוב, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on your back with your legs straight and a resistance band looped around your feet.","Bend your knees and bring them towards your chest, keeping your feet together.","Slowly rotate your knees outwards, away from each other, while keeping your feet together.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, выпрямите ноги и обвяжите ступни эластичной лентой.","Согните колени и подтяните их к груди, держа стопы вместе.","Медленно разверните колени наружу, друг от друга, сохраняя при этом стопы вместе.","Сделайте небольшую паузу в конце вращения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las piernas rectas y una banda elástica enrollada alrededor de los pies.","Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies juntos.","Rota lentamente las rodillas hacia afuera, separándolas entre sí, mientras mantienes los pies juntos.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1002","name":"band lying straight leg raise","category":"waist","body_part":"waist","equipment":"band","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/1002-bbLR7fB.jpg","gif_url":"videos/1002-bbLR7fB.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וכפות רגליים צמודות.","הניחו את הגומייה סביב קשתות כפות הרגליים והחזיקו את הקצוות בידיים.","תוך הפעלת שרירי הבטן, הרימו את שתי הרגליים מהרצפה עד שהן ניצבות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs straight and your feet together.","Place the band around the arches of your feet and hold the ends of the band with your hands.","Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, ноги прямые, ступни вместе.","Оберните ленту вокруг сводов стоп и возьмитесь за концы ленты руками.","Включив пресс, поднимите обе ноги от земли, пока они не станут перпендикулярны полу.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las piernas rectas y los pies juntos.","Coloca la banda alrededor de los arcos de los pies y sostén los extremos de la banda con las manos.","Activando el abdomen, levanta ambas piernas del suelo hasta que queden perpendiculares al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0986","name":"band one arm overhead biceps curl","category":"upper arms","body_part":"upper arms","equipment":"band","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0986-UNAB8ak.jpg","gif_url":"videos/0986-UNAB8ak.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והניחו קצה אחד של הגומייה מתחת לכף הרגל.","החזיקו את הקצה השני של הגומייה עם היד מתוחה לגמרי מעל הראש, כף יד פונה קדימה.","תוך שמירה על הזרוע העליונה ללא תזוזה, כופפו את האמה לכיוון הכתף, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז הורידו את האמה באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Stand with your feet shoulder-width apart and place one end of the band under your foot.","Hold the other end of the band with your arm fully extended overhead, palm facing forward.","Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.","Pause for a moment at the top, then slowly lower your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Встаньте, ноги на ширине плеч, и поместите один конец ленты под ногу.","Держите другой конец ленты, полностью вытянув руку над головой ладонью вперед.","Удерживая плечо неподвижно, согните предплечье к плечу, сжимая бицепс.","Задержитесь на мгновение в верхней точке, затем медленно опустите предплечье обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca un extremo de la banda bajo el pie.","Sostén el otro extremo de la banda con el brazo completamente extendido por encima de la cabeza, con la palma hacia adelante.","Manteniendo quieta la parte superior del brazo, flexiona el antebrazo hacia el hombro, apretando el bíceps.","Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0987","name":"band one arm single leg split squat","category":"upper legs","body_part":"upper legs","equipment":"band","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"quads","image":"images/0987-arsYEd3.jpg","gif_url":"videos/0987-arsYEd3.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן והניחו גומיית התנגדות סביב הקרסוליים.","מתחו רגל אחת לאחור והניחו את גב כף הרגל על ספסל או מדרגה מאחוריכם.","אחזו במשענת ביד אחת לשיווי משקל.","כופפו את רגל העמידה והורידו את הגוף לעמדת סקוואט, תוך שמירה על הברך בקו אחד עם כף הרגל.","דחפו דרך העקב לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Stand with your feet hip-width apart and place a resistance band around your ankles.","Extend one leg forward and rest the top of your foot on a bench or step behind you.","Hold onto a support with one hand for balance.","Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Встаньте, ноги на ширине плеч, и наденьте эластичную ленту на лодыжки.","Вытяните одну ногу вперед и положите верхнюю часть стопы на скамью или сделайте шаг позади себя.","Держитесь за опору одной рукой для равновесия.","Согните стоящую ногу и опустите тело в положение приседа, удерживая колено на одной линии с пальцами ног.","Оттолкнитесь пяткой, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos.","Extiende una pierna hacia adelante y apoya la parte superior del pie sobre un banco o escalón detrás de ti.","Sujétate de un apoyo con una mano para mantener el equilibrio.","Flexiona la pierna de apoyo y baja el cuerpo hacia una posición de sentadilla, manteniendo la rodilla alineada con los dedos del pie.","Empuja con el talón para regresar a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"0988","name":"band one arm standing low row","category":"back","body_part":"back","equipment":"band","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0988-km0sQC0.jpg","gif_url":"videos/0988-km0sQC0.gif","instruction_steps":{"he":["עגנו את הגומייה לנקודת עיגון יציבה בגובה המותניים.","עמדו מול נקודת העיגון עם רגליים ברוחב כתפיים.","החזיקו את הגומייה ביד אחת, כף יד פונה פנימה, וצעדו לאחור ליצירת מתח בגומייה.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","משכו את הגומייה לכיוון המותניים, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה, ואז שחררו באיטיות את הגומייה חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Attach the band to a stable anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band with one hand, palm facing inward, and step back to create tension in the band.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Прикрепите ремешок к устойчивой точке крепления на высоте талии.","Встаньте лицом к точке крепления, поставив ноги на ширине плеч.","Держите ленту одной рукой ладонью внутрь и отступите назад, чтобы создать натяжение ленты.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Потяните ленту к талии, сжимая лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения, затем медленно отпустите ленту обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Sujeta la banda a un punto de anclaje estable a la altura de la cintura.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Sostén la banda con una mano, con la palma hacia adentro, y da un paso atrás para generar tensión en la banda.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Tira de la banda hacia la cintura, juntando los omóplatos.","Haz una pausa por un momento en la parte superior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0989","name":"band one arm twisting chest press","category":"chest","body_part":"chest","equipment":"band","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0989-c16nYGA.jpg","gif_url":"videos/0989-c16nYGA.gif","instruction_steps":{"he":["עגנו את הגומייה לנקודת עיגון יציבה בגובה החזה.","עמדו כשהצד פונה לנקודת העיגון ואחזו בגומייה ביד אחת.","צעדו הרחק מנקודת העיגון ליצירת מתח בגומייה.","מקמו את כפות הרגליים ברוחב כתפיים וכופפו ברכיים מעט.","הביאו את היד שאוחזת בגומייה על פני הגוף, לכיוון הכתף הנגדית.","תוך שמירה על מתח בגומייה, דחפו את היד קדימה והרחק מהגוף, במתיחת היד.","חזרו באיטיות לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי.","החליפו צדדים וחזרו על התרגיל ביד השנייה."],"en":["Attach the band to a sturdy anchor point at chest height.","Stand with your side facing the anchor point and grab the band with one hand.","Step away from the anchor point to create tension in the band.","Position your feet shoulder-width apart and slightly bend your knees.","Bring your hand holding the band across your body, towards the opposite shoulder.","While maintaining tension in the band, push your hand forward and away from your body, extending your arm.","Slowly return to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other hand."],"ru":["Прикрепите ремешок к прочной точке крепления на уровне груди.","Встаньте боком к точке крепления и возьмитесь за ленту одной рукой.","Отойдите от точки крепления, чтобы создать напряжение в ленте.","Поставьте ноги на ширине плеч и слегка согните колени.","Проведите руку, удерживающую ленту, через тело к противоположному плечу.","Сохраняя натяжение ленты, толкните руку вперед и в сторону от тела, вытягивая руку.","Медленно вернитесь в исходное положение и повторите необходимое количество повторений.","Поменяйте сторону и повторите упражнение другой рукой."],"es":["Sujeta la banda a un punto de anclaje resistente a la altura del pecho.","Ponte de pie con el costado hacia el punto de anclaje y agarra la banda con una mano.","Aléjate del punto de anclaje para generar tensión en la banda.","Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.","Lleva la mano que sostiene la banda a través del cuerpo, hacia el hombro opuesto.","Manteniendo la tensión en la banda, empuja la mano hacia adelante y alejándola del cuerpo, extendiendo el brazo.","Regresa lentamente a la posición inicial y repite el número de repeticiones deseado.","Cambia de lado y repite el ejercicio con la otra mano."]}},{"id":"0990","name":"band one arm twisting seated row","category":"back","body_part":"back","equipment":"band","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0990-DKBwJrL.jpg","gif_url":"videos/0990-DKBwJrL.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם כפות רגליים על הרצפה וגב ישר.","החזיקו את הגומייה ביד אחת ומתחו את היד לגמרי לפניכם.","תוך שמירה על גב ישר, משכו את הגומייה לכיוון הגוף בכיפוף המרפק וכיווץ השכמות זו לזו.","בו-זמנית, סובבו את הגו לכיוון הצד של היד המושכת.","עצרו לרגע בנקודה העליונה, ואז שחררו באיטיות את המתח בגומייה וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold the band with one hand and extend your arm fully in front of you.","Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.","At the same time, twist your torso towards the side of the pulling arm.","Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Сядьте на скамью или стул, поставив ноги на землю и выпрямив спину.","Держите ленту одной рукой и вытяните руку полностью перед собой.","Сохраняя спину прямой, потяните ленту к себе, сгибая локоть и сводя лопатки вместе.","В то же время поверните туловище в сторону тянущей руки.","Задержитесь на мгновение в верхней точке, затем медленно ослабьте натяжение ленты и вернитесь в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta.","Sostén la banda con una mano y extiende el brazo completamente frente a ti.","Manteniendo la espalda recta, tira de la banda hacia el cuerpo flexionando el codo y juntando los omóplatos.","Al mismo tiempo, gira el torso hacia el lado del brazo que tira.","Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión de la banda y regresa a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0991","name":"band pull through","category":"upper legs","body_part":"upper legs","equipment":"band","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0991-VtTbiP3.jpg","gif_url":"videos/0991-VtTbiP3.gif","instruction_steps":{"he":["עגנו גומיית התנגדות לנקודת עיגון יציבה בגובה הרצפה.","עמדו עם הגב לנקודת העיגון, רגליים ברוחב כתפיים.","צעדו קדימה ליצירת מתח בגומייה, תוך שמירה על ברכיים כפופות מעט.","הטו את הגו מהירכיים ודחפו את הישבן לאחור, תוך שמירה על כיפוף קל בברכיים.","הורידו את הגו עד שהוא מקביל לרצפה, עד תחושת מתיחה בירך האחורית.","דחפו את האגן קדימה וכווצו את הישבן לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a resistance band to a sturdy anchor point at ground level.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step forward to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Drive your hips forward and squeeze your glutes to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ленту сопротивления к прочной точке крепления на уровне земли.","Встаньте лицом от точки крепления, поставив ноги на ширине плеч.","Сделайте шаг вперед, чтобы создать напряжение в ленте, держа колени слегка согнутыми.","Наклонитесь в бедрах и отведите ягодицы назад, сохраняя небольшой изгиб в коленях.","Опускайте туловище до тех пор, пока оно не станет параллельно земле, чувствуя растяжение подколенных сухожилий.","Поднимите бедра вперед и сожмите ягодицы, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una banda elástica a un punto de anclaje resistente a nivel del suelo.","Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.","Da un paso adelante para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas.","Flexiona las caderas y lleva los glúteos hacia atrás, manteniendo una ligera flexión en las rodillas.","Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.","Empuja las caderas hacia adelante y aprieta los glúteos para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0992","name":"band push sit-up","category":"waist","body_part":"waist","equipment":"band","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"abs","image":"images/0992-zFzbBfL.jpg","gif_url":"videos/0992-zFzbBfL.gif","instruction_steps":{"he":["עגנו את הגומייה היטב לנקודת עיגון יציבה.","שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","החזיקו את הגומייה בשתי הידיים ומתחו את הידיים ישר כלפי התקרה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the band securely to a stable anchor point.","Lie flat on your back with your knees bent and feet flat on the ground.","Hold the band with both hands and extend your arms straight up towards the ceiling.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Надежно прикрепите ремешок к устойчивой точке крепления.","Лягте на спину, согните колени и поставьте ступни на землю.","Возьмите ленту обеими руками и вытяните руки прямо вверх к потолку.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta la banda de forma segura a un punto de anclaje estable.","Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Sostén la banda con ambas manos y extiende los brazos rectos hacia el techo.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0993","name":"band reverse fly","category":"shoulders","body_part":"shoulders","equipment":"band","muscle_group":"upper back","secondary_muscles":["upper back","trapezius"],"target":"delts","image":"images/0993-sTfvVsG.jpg","gif_url":"videos/0993-sTfvVsG.gif","instruction_steps":{"he":["עגנו את הגומייה לחפץ קבוע בגובה החזה.","עמדו עם רגליים ברוחב כתפיים והחזיקו את הגומייה בשתי ידיים לפניכם.","שמרו על ידיים ישרות והרימו אותן לצדדים עד שהן מקבילות לרצפה.","כווצו את השכמות זו לזו בנקודה העליונה של התנועה.","הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the band to a stationary object at chest height.","Stand with your feet shoulder-width apart and hold the band with both hands in front of you.","Keep your arms straight and lift them out to the sides until they are parallel to the ground.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ремешок к неподвижному объекту на уровне груди.","Встаньте, ноги на ширине плеч, держите ленту обеими руками перед собой.","Держите руки прямо и поднимите их в стороны, пока они не станут параллельны земле.","В верхней точке движения сведите лопатки вместе.","Медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta la banda a un objeto fijo a la altura del pecho.","Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos frente a ti.","Mantén los brazos rectos y levántalos hacia los lados hasta que queden paralelos al suelo.","Junta los omóplatos en la parte superior del movimiento.","Baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0994","name":"band reverse wrist curl","category":"lower arms","body_part":"lower arms","equipment":"band","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"forearms","image":"images/0994-Ezpnw9d.jpg","gif_url":"videos/0994-Ezpnw9d.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם כפות רגליים על הרצפה.","החזיקו את הגומייה באחיזה עליונה, כפות ידיים כלפי מטה, ולפפו אותה סביב האצבעות.","השעינו את האמות על הירכיים, כששורשי כף היד משתלשלים מעבר לקצה.","גלגלו באיטיות את שורשי כף היד כלפי מעלה, בכיווץ האמות.","עצרו לרגע בנקודה העליונה, ואז הורידו את שורשי כף היד באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench or chair with your feet flat on the ground.","Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью или стул, поставив ноги на землю.","Возьмите ремешок сверху ладонями вниз и оберните его вокруг пальцев.","Положите предплечья на бедра так, чтобы запястья свисали с краев.","Медленно поднимите запястья вверх, сжимая предплечья.","Задержитесь на мгновение в верхней точке, затем медленно опустите запястья обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco o silla con los pies apoyados en el suelo.","Sostén la banda con un agarre prono, con las palmas hacia abajo, y envuélvela alrededor de los dedos.","Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde.","Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos.","Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0996","name":"band seated hip internal rotation","category":"upper legs","body_part":"upper legs","equipment":"band","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/0996-9gbyYKk.jpg","gif_url":"videos/0996-9gbyYKk.gif","instruction_steps":{"he":["שבו על כיסא או ספסל עם גב ישר וכפות רגליים על הרצפה.","הניחו גומיית התנגדות סביב הירכיים, מעט מעל הברכיים.","שמרו על ברכיים כפופות בזווית של 90 מעלות ורגליים ברוחב כתפיים.","הפעילו את הישבן וסובבו באיטיות את הברכיים החוצה, בדחיפה נגד התנגדות הגומייה.","עצרו לרגע בסוף התנועה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a chair or bench with your back straight and feet flat on the ground.","Place a resistance band around your thighs, just above your knees.","Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.","Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на стул или скамью, выпрямив спину и поставив ступни на землю.","Оберните ленту сопротивления вокруг бедер, чуть выше колен.","Держите колени согнутыми под углом 90 градусов, а ноги на ширине плеч.","Напрягите ягодицы и медленно разверните колени наружу, преодолевая сопротивление ленты.","Сделайте небольшую паузу в конце движения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.","Coloca una banda elástica alrededor de los muslos, justo por encima de las rodillas.","Mantén las rodillas flexionadas formando un ángulo de 90 grados y los pies separados a la altura de los hombros.","Activa los glúteos y rota lentamente las rodillas hacia afuera, empujando contra la resistencia de la banda.","Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1011","name":"band seated twist","category":"waist","body_part":"waist","equipment":"band","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/1011-S1JXDAG.jpg","gif_url":"videos/1011-S1JXDAG.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים מתוחות לפניכם וגב ישר.","לפפו את הגומייה סביב המותניים והחזיקו את הקצוות בשתי הידיים.","הפעילו את שרירי הבטן וסובבו באיטיות את הגו לצד אחד, תוך שמירה על גב ישר וכפות רגליים על הרצפה.","עצרו לרגע בסוף הסיבוב, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על הסיבוב לצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Sit on the ground with your legs extended in front of you and your back straight.","Wrap the band around your waist and hold the ends with both hands.","Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Сядьте на пол, вытянув ноги перед собой и выпрямив спину.","Оберните ленту вокруг талии и возьмитесь за концы обеими руками.","Напрягите пресс и медленно поверните туловище в сторону, сохраняя спину прямой и ноги на земле.","Сделайте небольшую паузу в конце поворота, затем медленно вернитесь в исходное положение.","Повторите поворот в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti y la espalda recta.","Envuelve la banda alrededor de la cintura y sostén los extremos con ambas manos.","Activa el abdomen y gira lentamente el torso hacia un lado, manteniendo la espalda recta y los pies en el suelo.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite el giro hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0997","name":"band shoulder press","category":"shoulders","body_part":"shoulders","equipment":"band","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0997-peAeMR3.jpg","gif_url":"videos/0997-peAeMR3.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והניחו את הגומייה מתחת לכפות הרגליים.","החזיקו את הגומייה עם כפות ידיים פונות קדימה והרימו את הידיים לגובה הכתפיים, מרפקים כפופים.","לחצו את הגומייה מעל הראש, עד יישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגומייה באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.","Press the band overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the band back to shoulder height.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, и поместите ленту под ноги.","Держите ленту ладонями вперед и поднимите руки на высоту плеч, локти согнуты.","Нажмите на ленту над головой, полностью выпрямив руки.","Задержитесь на мгновение в верхней точке, затем медленно опустите ленту обратно на высоту плеч.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.","Sostén la banda con las palmas hacia adelante y eleva las manos a la altura de los hombros, con los codos flexionados.","Empuja la banda por encima de la cabeza, extendiendo completamente los brazos.","Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"1018","name":"band shrug","category":"back","body_part":"back","equipment":"band","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/1018-trmte8s.jpg","gif_url":"videos/1018-trmte8s.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והניחו את הגומייה מתחת לכפות הרגליים, אוחזים בקצוות בידיים.","שמרו על ידיים ישרות ורפויות, ותנו לגומייה להשתלשל מול הירכיים.","הפעילו את שרירי הטרפז במשיכת כתפיים כלפי מעלה, והרימו את הגומייה גבוה ככל האפשר.","החזיקו את הכיווץ לרגע, ואז הורידו את הכתפיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.","Keep your arms straight and relaxed, and let the band hang in front of your thighs.","Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, расставив ноги на ширине плеч, и поместите ленту под ноги, держа концы руками.","Держите руки прямыми и расслабленными, позвольте ленте свисать перед бедрами.","Задействуйте трапеции, пожимая плечами вверх и поднимая ленту как можно выше.","Удерживайте напряжение на мгновение, затем медленно опустите плечи обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies, sosteniendo los extremos con las manos.","Mantén los brazos rectos y relajados, y deja que la banda cuelgue frente a los muslos.","Activa los trapecios encogiendo los hombros hacia arriba, levantando la banda lo más alto posible.","Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0998","name":"band side triceps extension","category":"upper arms","body_part":"upper arms","equipment":"band","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0998-obe5LMq.jpg","gif_url":"videos/0998-obe5LMq.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את הגומייה בשתי ידיים, כפות ידיים כלפי מטה.","מתחו את הידיים ישר לצדדים, מקבילות לרצפה.","כופפו באיטיות את המרפקים והביאו את הידיים לכיוון הכתפיים, תוך שמירה על זרועות עליונות ללא תזוזה.","עצרו לרגע, ואז יישרו באיטיות את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.","Extend your arms straight out to the sides, keeping them parallel to the ground.","Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.","Pause for a moment, then slowly extend your arms back out to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмитесь за ленту обеими руками ладонями вниз.","Вытяните руки прямо в стороны, держа их параллельно земле.","Медленно согните локти и поднесите руки к плечам, сохраняя плечи неподвижными.","Сделайте паузу на мгновение, затем медленно вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos, con las palmas hacia abajo.","Extiende los brazos hacia los lados, manteniéndolos paralelos al suelo.","Flexiona lentamente los codos y lleva las manos hacia los hombros, manteniendo quieta la parte superior de los brazos.","Haz una pausa por un momento, luego extiende lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0999","name":"band single leg calf raise","category":"lower legs","body_part":"lower legs","equipment":"band","muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/0999-9JprnPh.jpg","gif_url":"videos/0999-9JprnPh.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן והניחו את הגומייה סביב כרית כף רגל שמאל.","אחזו בחפץ יציב לשיווי משקל במידת הצורך.","הרימו באיטיות את עקב שמאל מהרצפה, בהעברת משקל הגוף לכרית כף הרגל.","עצרו לרגע בנקודה העליונה, ואז הורידו את עקב שמאל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו לרגל ימין."],"en":["Stand with your feet hip-width apart and place the band around the ball of your left foot.","Hold onto a stable object for balance if needed.","Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your left heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the right leg."],"ru":["Встаньте, ноги на ширине плеч, и наденьте ленту на подушечку левой стопы.","При необходимости держитесь за устойчивый предмет для равновесия.","Медленно поднимите левую пятку от земли, перенеся вес тела на подушечки стопы.","Задержитесь на мгновение в верхней точке, затем медленно опустите левую пятку обратно в исходное положение.","Повторите необходимое количество повторений, затем переключитесь на правую ногу."],"es":["Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie izquierdo.","Sujétate de un objeto estable para mantener el equilibrio si es necesario.","Levanta lentamente el talón izquierdo del suelo, llevando el peso del cuerpo hacia la punta del pie.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón izquierdo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia a la pierna derecha."]}},{"id":"1000","name":"band single leg reverse calf raise","category":"lower legs","body_part":"lower legs","equipment":"band","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1000-QsSQWbf.jpg","gif_url":"videos/1000-QsSQWbf.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן והניחו את הגומייה סביב כרית כף הרגל.","אחזו בחפץ יציב לשיווי משקל.","הרימו באיטיות את העקב מהרצפה, בהעברת משקל הגוף לכרית כף הרגל.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקב באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו לרגל השנייה."],"en":["Stand with your feet hip-width apart and place the band around the ball of your foot.","Hold onto a stable object for balance.","Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."],"ru":["Встаньте, ноги на ширине плеч, и наденьте ленту на подушечку стопы.","Держитесь за устойчивый предмет для равновесия.","Медленно поднимите пятку от земли, перенеся вес тела на подушечки стопы.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятку обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую ногу."],"es":["Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie.","Sujétate de un objeto estable para mantener el equilibrio.","Levanta lentamente el talón del suelo, llevando el peso del cuerpo hacia la punta del pie.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia a la otra pierna."]}},{"id":"1001","name":"band single leg split squat","category":"upper legs","body_part":"upper legs","equipment":"band","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"quads","image":"images/1001-y8bYM8w.jpg","gif_url":"videos/1001-y8bYM8w.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן והניחו גומיית התנגדות סביב הקרסוליים.","צעדו צעד גדול קדימה עם רגל ימין וצעד קטן לאחור עם רגל שמאל.","כופפו ברכיים והורידו את הגוף עד שירך ימין מקבילה לרצפה, כשברך שמאל מעט מעל הרצפה.","דחפו דרך עקב ימין כדי לחזור לנקודת ההתחלה.","חזרו על התנועה בצד השני."],"en":["Stand with your feet hip-width apart and place a resistance band around your ankles.","Take a big step forward with your right foot and a smaller step back with your left foot.","Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.","Push through your right heel to return to the starting position.","Repeat on the other side."],"ru":["Встаньте, ноги на ширине плеч, и наденьте эластичную ленту на лодыжки.","Сделайте большой шаг вперед правой ногой и маленький шаг назад левой ногой.","Согните колени и опустите тело до тех пор, пока правое бедро не станет параллельно земле, сохраняя левое колено немного выше земли.","Оттолкнитесь правой пяткой, чтобы вернуться в исходное положение.","Повторите с другой стороны."],"es":["Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos.","Da un paso grande hacia adelante con el pie derecho y un paso más pequeño hacia atrás con el pie izquierdo.","Flexiona las rodillas y baja el cuerpo hasta que el muslo derecho quede paralelo al suelo, manteniendo la rodilla izquierda ligeramente por encima del suelo.","Empuja con el talón derecho para regresar a la posición inicial.","Repite del otro lado."]}},{"id":"1004","name":"band squat","category":"upper legs","body_part":"upper legs","equipment":"band","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1004-TUZLh71.jpg","gif_url":"videos/1004-TUZLh71.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, כשהגומייה ממוקמת מעט מעל הברכיים.","תוך שמירה על חזה מורם וליבה מופעלת, דחפו את האגן לאחור וכופפו ברכיים לירידה לסקוואט.","ודאו שהברכיים בקו אחד עם כפות הרגליים ושהמשקל בעקבים.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, with the band placed just above your knees.","Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.","Make sure your knees are tracking over your toes and your weight is in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, расположив ленту чуть выше колен.","Удерживая грудь поднятой и напряженным корпус, отведите бедра назад и согните колени, чтобы опуститься в присед.","Убедитесь, что ваши колени касаются пальцев ног, а ваш вес приходится на пятки.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con la banda colocada justo por encima de las rodillas.","Manteniendo el pecho arriba y el core activado, lleva las caderas hacia atrás y flexiona las rodillas para bajar a una posición de sentadilla.","Asegúrate de que las rodillas se alineen con los dedos de los pies y de que el peso recaiga en los talones.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1003","name":"band squat row","category":"upper legs","body_part":"upper legs","equipment":"band","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","back"],"target":"glutes","image":"images/1003-w1NOByi.jpg","gif_url":"videos/1003-w1NOByi.gif","instruction_steps":{"he":["עגנו את הגומייה לנקודת עיגון יציבה בגובה המותניים.","עמדו מול נקודת העיגון עם רגליים ברוחב כתפיים.","החזיקו את ידיות הגומייה עם כפות ידיים פונות זו לזו וידיים מתוחות לפניכם.","כופפו ברכיים ורדו לעמדת סקוואט, תוך שמירה על גב ישר וחזה מורם.","מעמדת הסקוואט, משכו את ידיות הגומייה לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the band to a sturdy anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees and lower into a squat position, keeping your back straight and chest lifted.","From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ремешок к прочной точке крепления на высоте талии.","Встаньте лицом к точке крепления, поставив ноги на ширине плеч.","Держите ручки лент ладонями друг к другу, а руки вытянуты перед собой.","Согните колени и опуститесь в присед, сохраняя спину прямой и грудь поднятой.","Из положения приседа потяните ручки лент к себе, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti.","Flexiona las rodillas y baja a una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Desde la posición de sentadilla, tira de las agarraderas de la banda hacia el cuerpo, juntando los omóplatos.","Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1005","name":"band standing crunch","category":"waist","body_part":"waist","equipment":"band","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/1005-Kzg30R7.jpg","gif_url":"videos/1005-Kzg30R7.gif","instruction_steps":{"he":["עגנו את הגומייה לנקודת עיגון יציבה בגובה המותניים.","עמדו עם הגב לנקודת העיגון, רגליים ברוחב כתפיים.","החזיקו את הגומייה בשתי ידיים והביאו אותה לגובה החזה, עם מרפקים כפופים וצמודים לגוף.","הפעילו את שרירי הבטן והתגלגלו באיטיות קדימה, בהבאת החזה לכיוון הברכיים.","עצרו לרגע בנקודה העליונה של הכפיפה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the band to a sturdy anchor point at waist height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ремешок к прочной точке крепления на высоте талии.","Встаньте лицом от точки крепления, поставив ноги на ширине плеч.","Возьмите ленту обеими руками и поднесите ее к груди, держа локти согнутыми и близко к телу.","Напрягите пресс и медленно наклонитесь вперед, приближая грудь к коленям.","Сделайте паузу на мгновение в верхней точке скручивания, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.","Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.","Sostén la banda con ambas manos y llévala hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo.","Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando el pecho hacia las rodillas.","Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1022","name":"band standing rear delt row","category":"shoulders","body_part":"shoulders","equipment":"band","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/1022-tc5dYrf.jpg","gif_url":"videos/1022-tc5dYrf.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והניחו את הגומייה מתחת לכפות הרגליים.","החזיקו את ידיות הגומייה עם כפות ידיים פונות זו לזו וידיים מתוחות לפניכם.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","משכו את הגומייה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, и поместите ленту под ноги.","Держите ручки лент ладонями друг к другу, а руки вытянуты перед собой.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Потяните ленту к груди, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.","Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Tira de la banda hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1007","name":"band standing twisting crunch","category":"waist","body_part":"waist","equipment":"band","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/1007-euq4pwp.jpg","gif_url":"videos/1007-euq4pwp.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והניחו את הגומייה סביב הגב העליון, בהצלבתה מול החזה.","החזיקו את קצוות הגומייה בידיים, עם מרפקים כפופים וצמודים לצידי הגוף.","הפעילו את שרירי הבטן וסובבו את הגו לצד אחד, בהבאת המרפק לכיוון הברך הנגדית.","עצרו לרגע, ואז חזרו לנקודת ההתחלה.","חזרו על התנועה בצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.","Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.","Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, расставив ноги на ширине плеч, и оберните ленту вокруг верхней части спины, пересекая ее перед грудью.","Возьмите концы ленты руками, держа локти согнутыми и прижатыми к бокам.","Напрягите пресс и поверните туловище в одну сторону, приближая локоть к противоположному колену.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите с другой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de la espalda, cruzándola frente al pecho.","Sujeta los extremos de la banda con las manos, manteniendo los codos flexionados y cerca de los costados.","Activa el abdomen y gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1008","name":"band step-up","category":"upper legs","body_part":"upper legs","equipment":"band","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1008-d5bTEPV.jpg","gif_url":"videos/1008-d5bTEPV.gif","instruction_steps":{"he":["הניחו גומייה סביב הירכיים, מעט מעל הברכיים.","עמדו מול מדרגה או משטח עם רגליים ברוחב אגן.","עלו על המשטח עם כף רגל ימין, בדחיפה דרך העקב.","מתחו את רגל שמאל לאחור, כשהיא ישרה.","הורידו את כף רגל שמאל חזרה לרצפה.","חזרו על התנועה עם כף רגל שמאל עולה על המשטח.","המשיכו להחליף רגליים למספר החזרות הרצוי."],"en":["Place a band around your thighs, just above your knees.","Stand facing a step or platform with your feet hip-width apart.","Step up onto the platform with your right foot, pushing through your heel.","Extend your left leg behind you, keeping it straight.","Lower your left foot back down to the ground.","Repeat with your left foot stepping up onto the platform.","Continue alternating legs for the desired number of repetitions."],"ru":["Наденьте резинку на бедра, чуть выше колен.","Встаньте лицом к ступеньке или платформе, поставив ноги на ширине плеч.","Встаньте на платформу правой ногой, отталкиваясь пяткой.","Вытяните левую ногу позади себя, сохраняя ее прямой.","Опустите левую ногу обратно на землю.","Повторите то же самое, вставив левую ногу на платформу.","Продолжайте чередовать ноги желаемое количество повторений."],"es":["Coloca una banda alrededor de los muslos, justo por encima de las rodillas.","Ponte de pie frente a un escalón o plataforma con los pies separados a la altura de las caderas.","Sube a la plataforma con el pie derecho, empujando con el talón.","Extiende la pierna izquierda hacia atrás, manteniéndola recta.","Baja el pie izquierdo de nuevo hasta el suelo.","Repite subiendo a la plataforma con el pie izquierdo.","Continúa alternando las piernas durante el número de repeticiones deseado."]}},{"id":"1009","name":"band stiff leg deadlift","category":"upper legs","body_part":"upper legs","equipment":"band","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1009-kuMiR2T.jpg","gif_url":"videos/1009-kuMiR2T.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והניחו את הגומייה סביב הקרסוליים.","החזיקו את הגומייה בשתי ידיים מול הירכיים, כפות ידיים פונות לגוף.","תוך שמירה על גב ישר וליבה מופעלת, הטו את הגו מהירכיים והורידו באיטיות את פלג הגוף העליון לכיוון הרצפה.","תוך כדי הירידה, דחפו את האגן לאחור ותנו לברכיים להתכופף מעט.","הורידו את הגומייה לכיוון הרצפה, עד תחושת מתיחה בירך האחורית.","עצרו לרגע בנקודה התחתונה, ואז הפעילו את הישבן והירך האחורית להרמת פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and place the band around your ankles.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.","As you lower, push your hips back and allow your knees to bend slightly.","Lower the band towards the ground, feeling a stretch in your hamstrings.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, и наденьте ленту на лодыжки.","Держите ленту обеими руками перед бедрами, ладонями к телу.","Удерживая спину прямой и корпус напряженным, наклонитесь в бедрах и медленно опустите верхнюю часть тела к земле.","Опускаясь, отведите бедра назад и позвольте коленям слегка согнуться.","Опустите ленту к земле, чувствуя растяжение подколенных сухожилий.","Задержитесь на мгновение в нижней точке, затем задействуйте ягодицы и мышцы задней поверхности бедра, чтобы поднять верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los tobillos.","Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo.","Manteniendo la espalda recta y el core activado, flexiona las caderas y baja lentamente la parte superior del cuerpo hacia el suelo.","Mientras bajas, empuja las caderas hacia atrás y deja que las rodillas se flexionen ligeramente.","Baja la banda hacia el suelo, sintiendo un estiramiento en los isquiotibiales.","Haz una pausa breve en la posición baja, luego activa los glúteos y los isquiotibiales para levantar la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1023","name":"band straight back stiff leg deadlift","category":"upper legs","body_part":"upper legs","equipment":"band","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1023-lHeUULr.jpg","gif_url":"videos/1023-lHeUULr.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והניחו את הגומייה סביב הרגליים העליונות.","החזיקו את הגומייה בשתי ידיים מול הירכיים, כפות ידיים פונות לגוף.","תוך שמירה על גב ישר וברכיים כפופות מעט, הטו את הגו מהירכיים והורידו את הגומייה לכיוון הרצפה.","הרגישו את המתיחה בירך האחורית תוך כדי הורדת הגומייה.","הפעילו את הישבן והירך האחורית להרמת הגוף חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and place the band around your upper legs.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground.","Feel the stretch in your hamstrings as you lower the band.","Engage your glutes and hamstrings to lift your body back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, и наденьте ленту на верхнюю часть ног.","Держите ленту обеими руками перед бедрами, ладонями к телу.","Держа спину прямой и слегка согнутыми в коленях, наклонитесь в бедрах и опустите ленту к земле.","Почувствуйте растяжение подколенных сухожилий, когда опускаете ленту.","Задействуйте ягодицы и мышцы задней поверхности бедра, чтобы поднять тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de las piernas.","Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo.","Manteniendo la espalda recta y las rodillas ligeramente flexionadas, flexiona las caderas y baja la banda hacia el suelo.","Siente el estiramiento en los isquiotibiales mientras bajas la banda.","Activa los glúteos y los isquiotibiales para levantar el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1010","name":"band straight leg deadlift","category":"back","body_part":"back","equipment":"band","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"spine","image":"images/1010-KUaoUV8.jpg","gif_url":"videos/1010-KUaoUV8.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והניחו את הגומייה סביב כפות הרגליים.","החזיקו את הגומייה בשתי ידיים, כפות ידיים פונות לגוף, ושמרו על ידיים ישרות.","הפעילו את הליבה ושמרו על כיפוף קל בברכיים.","הטו באיטיות את הגו קדימה מהירכיים, תוך שמירה על גב ישר וחזה מורם.","הורידו את הגומייה לכיוון הרצפה, תוך שמירה על רגליים ישרות.","עצרו לרגע בנקודה התחתונה, ואז כווצו את הישבן והירך האחורית לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and place the band around your feet.","Hold the band with both hands, palms facing your body, and keep your arms straight.","Engage your core and maintain a slight bend in your knees.","Slowly hinge forward at your hips, keeping your back straight and chest lifted.","Lower the band towards the ground while keeping your legs straight.","Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, и наденьте ленту на ступни.","Держите ленту обеими руками ладонями к телу и держите руки прямыми.","Напрягите корпус и сохраняйте небольшой изгиб в коленях.","Медленно наклонитесь вперед в бедрах, сохраняя спину прямой и грудь поднятой.","Опустите ленту к земле, сохраняя ноги прямыми.","Задержитесь на мгновение в нижней точке, затем сожмите ягодицы и мышцы задней поверхности бедра, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los pies.","Sujeta la banda con ambas manos, con las palmas mirando hacia el cuerpo, y mantén los brazos rectos.","Activa el core y mantén una ligera flexión en las rodillas.","Inclínate lentamente hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Baja la banda hacia el suelo manteniendo las piernas rectas.","Haz una pausa breve en la posición baja y luego contrae los glúteos y los isquiotibiales para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1012","name":"band twisting overhead press","category":"shoulders","body_part":"shoulders","equipment":"band","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/1012-u4bAmKp.jpg","gif_url":"videos/1012-u4bAmKp.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והניחו את הגומייה מתחת לכפות הרגליים.","החזיקו את ידיות הגומייה בגובה הכתפיים, עם כפות ידיים פונות קדימה.","הפעילו את הליבה ולחצו את הגומייה מעל הראש, עד יישור מלא של הידיים.","תוך כדי הלחיצה, סובבו את הגו לצד אחד, תוך שמירה על אגן יציב.","עצרו לרגע בנקודה העליונה, ואז חזרו לנקודת ההתחלה.","חזרו על הלחיצה והסיבוב בצד הנגדי.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles at shoulder height with your palms facing forward.","Engage your core and press the band overhead, fully extending your arms.","As you press, twist your torso to one side, keeping your hips stable.","Pause for a moment at the top, then return to the starting position.","Repeat the press and twist on the opposite side.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, и поместите ленту под ноги.","Держите ручки лент на уровне плеч ладонями вперед.","Напрягите корпус и нажмите на ленту над головой, полностью выпрямляя руки.","При нажатии поворачивайте туловище в сторону, сохраняя бедра устойчивыми.","Задержитесь на мгновение в верхней точке, затем вернитесь в исходное положение.","Повторите нажатие и поверните на противоположную сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.","Sujeta las asas de la banda a la altura de los hombros con las palmas mirando hacia delante.","Activa el core y empuja la banda por encima de la cabeza, extendiendo completamente los brazos.","Mientras empujas, gira el torso hacia un lado, manteniendo las caderas estables.","Haz una pausa breve en la parte alta y luego vuelve a la posición inicial.","Repite el empuje y el giro hacia el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1369","name":"band two legs calf raise - (band under both legs) v. 2","category":"lower legs","body_part":"lower legs","equipment":"band","muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/1369-jl6uxZV.jpg","gif_url":"videos/1369-jl6uxZV.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והניחו גומיית התנגדות מתחת לשתי כפות הרגליים.","החזיקו את קצוות הגומייה בידיים לייצוב.","הרימו את העקבים מהרצפה גבוה ככל האפשר, בעזרת שרירי התאומים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and place a resistance band under both feet.","Hold the ends of the band with your hands for stability.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, и поместите эспандер под обе ноги.","Для устойчивости удерживайте концы ленты руками.","Поднимите пятки от земли как можно выше, используя икроножные мышцы.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca una banda elástica bajo ambos pies.","Sujeta los extremos de la banda con las manos para mantener el equilibrio.","Levanta los talones del suelo lo más alto posible, usando las pantorrillas.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1013","name":"band underhand pulldown","category":"back","body_part":"back","equipment":"band","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1013-k6tUeqS.jpg","gif_url":"videos/1013-k6tUeqS.gif","instruction_steps":{"he":["עגנו את הגומייה לנקודת עיגון גבוהה, כמו מוט מתח או קורה יציבה.","עמדו מול נקודת העיגון עם רגליים ברוחב כתפיים.","אחזו בגומייה באחיזה תחתונה, ידיים מעט רחבות מרוחב הכתפיים.","מתחו את הידיים לגמרי מעל הראש, עם כיפוף קל במרפקים.","הפעילו את רחב הגבי ומשכו את הגומייה מטה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, ואז שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Extend your arms fully overhead, keeping your elbows slightly bent.","Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ленту к высокой точке крепления, например к перекладине или прочной балке.","Встаньте лицом к точке крепления, поставив ноги на ширине плеч.","Возьмите ленту обратным хватом снизу, руки на расстоянии чуть шире плеч.","Вытяните руки полностью над головой, слегка согнув локти.","Напрягите широчайшие и потяните ленту вниз к груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.","Extiende completamente los brazos por encima de la cabeza, manteniendo los codos ligeramente flexionados.","Activa los dorsales y tira de la banda hacia abajo en dirección al pecho, juntando los omóplatos.","Haz una pausa breve en la parte baja del movimiento, luego libera lentamente la tensión y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1014","name":"band v-up","category":"waist","body_part":"waist","equipment":"band","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/1014-H6ETwO9.jpg","gif_url":"videos/1014-H6ETwO9.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וידיים מתוחות מעל הראש, אוחזות בגומייה.","תוך הפעלת שרירי הבטן, הרימו את הרגליים ופלג הגוף העליון מהרצפה בו-זמנית, עם ידיים נמתחות לכיוון כפות הרגליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים ופלג הגוף העליון באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, выпрямите ноги и вытяните руки над головой, удерживая ленту.","Включив пресс, одновременно поднимите ноги и верхнюю часть тела от земли, потянув руки к пальцам ног.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги и верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.","Activando el abdomen, levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1015","name":"band vertical pallof press","category":"waist","body_part":"waist","equipment":"band","muscle_group":"obliques","secondary_muscles":["obliques","glutes"],"target":"abs","image":"images/1015-G7PXMlT.jpg","gif_url":"videos/1015-G7PXMlT.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים ולפפו את הגומייה סביב חפץ יציב בגובה החזה.","החזיקו את הגומייה בשתי ידיים וצעדו הרחק מנקודת העיגון, ליצירת מתח בגומייה.","התמקמו ניצב לנקודת העיגון, כשהצד פונה לגומייה.","מתחו את הידיים ישר לפניכם, תוך שמירה על הידיים בגובה החזה.","הפעילו את הליבה ולחצו את הגומייה הרחק מהחזה, עד יישור מלא של הידיים.","החזיקו את התנוחה כמה שניות, ואז החזירו את הגומייה באיטיות לכיוון החזה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.","Hold the band with both hands and step away from the anchor point, creating tension in the band.","Position yourself perpendicular to the anchor point, with your side facing the band.","Extend your arms straight out in front of you, keeping your hands at chest height.","Engage your core and press the band away from your chest, fully extending your arms.","Hold the position for a few seconds, then slowly bring the band back towards your chest.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, и оберните ленту вокруг прочного предмета на уровне груди.","Возьмите ленту обеими руками и отойдите от точки крепления, создавая напряжение в ленте.","Встаньте перпендикулярно точке крепления, боком к ленте.","Вытяните руки прямо перед собой, держа ладони на уровне груди.","Напрягите корпус и отведите ленту от груди, полностью выпрямляя руки.","Удерживайте это положение несколько секунд, затем медленно верните ленту обратно к груди.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros y enrolla la banda alrededor de un objeto firme a la altura del pecho.","Sujeta la banda con ambas manos y aléjate del punto de anclaje, creando tensión en la banda.","Colócate perpendicular al punto de anclaje, con el costado mirando hacia la banda.","Extiende los brazos rectos hacia delante, manteniendo las manos a la altura del pecho.","Activa el core y empuja la banda alejándola del pecho, extendiendo completamente los brazos.","Mantén la posición durante unos segundos y luego lleva lentamente la banda de vuelta hacia el pecho.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"1016","name":"band wrist curl","category":"lower arms","body_part":"lower arms","equipment":"band","muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"forearms","image":"images/1016-vUTfFHw.jpg","gif_url":"videos/1016-vUTfFHw.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם כפות רגליים על הרצפה.","החזיקו את הגומייה בשתי ידיים, כפות ידיים כלפי מעלה, והשעינו את האמות על הירכיים.","גלגלו באיטיות את שורשי כף היד כלפי מעלה, בכיווץ האמות.","עצרו לרגע בנקודה העליונה, ואז הורידו את שורשי כף היד באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench or chair with your feet flat on the ground.","Hold the band with both hands, palms facing up, and rest your forearms on your thighs.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью или стул, поставив ноги на землю.","Держите ленту обеими руками ладонями вверх и положите предплечья на бедра.","Медленно поднимите запястья вверх, сжимая предплечья.","Задержитесь на мгновение в верхней точке, затем медленно опустите запястья обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco o silla con los pies apoyados en el suelo.","Sujeta la banda con ambas manos, con las palmas hacia arriba, y apoya los antebrazos sobre los muslos.","Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos.","Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1017","name":"band y-raise","category":"shoulders","body_part":"shoulders","equipment":"band","muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/1017-aHDy5O5.jpg","gif_url":"videos/1017-aHDy5O5.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את הגומייה מול הירכיים, כפות ידיים פונות פנימה.","שמרו על ידיים ישרות והרימו אותן למעלה ולצדדים, ביצירת צורת Y עם הגוף.","כווצו את השכמות זו לזו בנקודה העליונה של התנועה.","הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.","Keep your arms straight and lift them up and out to the sides, forming a 'Y' shape with your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, и держите ленту перед бедрами ладонями внутрь.","Держите руки прямо и поднимите их вверх и в стороны, образуя своим телом букву «Y».","В верхней точке движения сведите лопатки вместе.","Медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la banda frente a los muslos con las palmas mirando hacia adentro.","Mantén los brazos rectos y levántalos hacia arriba y hacia los lados, formando una 'Y' con el cuerpo.","Junta los omóplatos en la parte superior del movimiento.","Baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0023","name":"barbell alternate biceps curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0023-Yza7XrQ.jpg","gif_url":"videos/0023-Yza7XrQ.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו מוט בכל יד, כפות ידיים פונות קדימה.","שמרו על הזרועות העליונות ללא תזוזה ונשפו תוך כיפוף המשקולות בכיווץ הבייספס.","המשיכו להרים את המוטות עד שהבייספס מכווץ במלואו והמוטות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המוטות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, לסירוגין בין הידיים."],"en":["Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the barbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите в каждую руку по штанге ладонями вперед.","Держите плечи неподвижно и выдыхайте, сгибая штангу и одновременно сокращая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","На вдохе начните медленно опускать штангу обратно в исходное положение.","Повторите желаемое количество повторений, чередуя руки."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra en cada mano, con las palmas mirando hacia delante.","Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps.","Continúa levantando las barras hasta que los bíceps estén completamente contraídos y las barras estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala mientras comienzas a bajar lentamente las barras de vuelta a la posición inicial.","Repite el número de repeticiones deseado, alternando los brazos."]}},{"id":"0024","name":"barbell bench front squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes","calves"],"target":"quads","image":"images/0024-Y7YcmIJ.jpg","gif_url":"videos/0024-Y7YcmIJ.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים והמוט מונח על החזה העליון, מעט מתחת לעצם הבריח.","החזיקו את המוט באחיזה עליונה, עם מרפקים מורמים וזרועות עליונות מקבילות לרצפה.","הורידו את הגוף לעמדת סקוואט בכיפוף ברכיים וירכיים, תוך שמירה על גב ישר וחזה מורם.","עצרו לרגע בנקודה התחתונה של הסקוואט, ואז דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.","Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.","Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и положив штангу на верхнюю часть груди, чуть ниже ключиц.","Держите штангу хватом сверху, держа локти вверху и плечам параллельно земле.","Опустите тело в присед, сгибая колени и бедра, сохраняя спину прямой и грудь вверх.","Задержитесь на мгновение в нижней части приседа, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, justo debajo de la clavícula.","Sujeta la barra con un agarre pronado, manteniendo los codos elevados y los brazos superiores paralelos al suelo.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.","Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0025","name":"barbell bench press","category":"chest","body_part":"chest","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0025-EIeI8Vf.jpg","gif_url":"videos/0025-EIeI8Vf.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט מהמתקן והחזיקו אותו ישר מעל החזה עם ידיים ישרות לגמרי.","הורידו את המוט באיטיות לכיוון החזה, תוך שמירה על מרפקים קרובים לגוף.","עצרו לרגע כשהמוט נוגע בחזה.","דחפו את המוט חזרה למעלה לנקודת ההתחלה על ידי יישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу хватом сверху на расстоянии чуть шире плеч.","Снимите штангу со стойки и держите ее прямо над грудью, полностью вытянув руки.","Медленно опустите штангу к груди, держа локти прижатыми.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, вытянув руки.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0026","name":"barbell bench squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0026-W9pFVv1.jpg","gif_url":"videos/0026-W9pFVv1.gif","instruction_steps":{"he":["הכינו מוט על מתקן סקוואט בגובה החזה.","עמדו עם הגב למתקן, רגליים ברוחב כתפיים.","כופפו ברכיים והורידו את הגוף לעמדת סקוואט, תוך שמירה על גב ישר וחזה מורם.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט מהמתקן וצעדו לאחור, תוך הקפדה שהרגליים עדיין ברוחב כתפיים.","הורידו את הגוף לסקוואט, תוך שמירה על ברכיים בקו אחד עם קצות האצבעות.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up a barbell on a squat rack at chest height.","Stand facing away from the rack, with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.","Lower your body down into a squat, keeping your knees in line with your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите штангу на стойке для приседаний на уровне груди.","Встаньте лицом от стойки, ноги на ширине плеч.","Согните ноги в коленях и опустите тело в положение приседа, держа спину прямо и грудь вверх.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Снимите штангу со стойки и отступите назад, убедившись, что ваши ноги по-прежнему находятся на ширине плеч.","Опустите тело в присед, удерживая колени на одной линии с пальцами ног.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca una barra en un soporte de sentadillas a la altura del pecho.","Ponte de pie de espaldas al soporte, con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y retrocede un paso, asegurándote de que los pies sigan separados a la altura de los hombros.","Baja el cuerpo hacia una sentadilla, manteniendo las rodillas alineadas con los dedos de los pies.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1316","name":"barbell bent arm pullover","category":"back","body_part":"back","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"lats","image":"images/1316-cA9FuWG.jpg","gif_url":"videos/1316-cA9FuWG.gif","instruction_steps":{"he":["שכבו על ספסל כשהראש בקצה אחד וכפות הרגליים על הרצפה.","החזיקו מוט באחיזה ברוחב כתפיים ומתחו את הידיים ישר מעל החזה.","הורידו את המוט מאחורי הראש תוך שמירה על ידיים כפופות מעט.","עצרו לרגע, ואז הרימו את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Lower the barbell behind your head while keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив голову на один конец и поставив ноги на пол.","Возьмите штангу хватом на ширине плеч и вытяните руки прямо над грудью.","Опустите штангу за голову, держа руки слегка согнутыми.","Сделайте паузу на мгновение, затем поднимите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.","Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.","Baja la barra detrás de la cabeza manteniendo los brazos ligeramente flexionados.","Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0027","name":"barbell bent over row","category":"back","body_part":"back","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0027-eZyBC3j.jpg","gif_url":"videos/0027-eZyBC3j.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","הטו את הגו קדימה מהירכיים תוך שמירה על גב ישר וחזה מורם.","אחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","משכו את המוט לכיוון החזה התחתון על ידי כיווץ השכמות ושרירי הגב.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the hips while keeping your back straight and chest up.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Наклонитесь вперед в бедрах, сохраняя спину прямой и грудь вверх.","Возьмите штангу хватом сверху, руки на расстоянии чуть шире плеч.","Потяните штангу к нижней части груди, сводя лопатки и напрягая мышцы спины.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado.","Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Tira de la barra hacia la parte inferior del pecho retrayendo los omóplatos y contrayendo los músculos de la espalda.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2407","name":"barbell biceps curl (with arm blaster)","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2407-aee2Fcj.jpg","gif_url":"videos/2407-aee2Fcj.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה תחתונה, כפות ידיים כלפי מעלה.","הצמידו את הזרועות העליונות לארם-בלאסטר, תוך שמירה על מרפקים קרובים לגוף.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המוט עד שהבייספס מכווץ במלואו והמוט בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping your elbows close to your torso.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу обратным хватом ладонями вверх.","Прижмите плечи к армбластеру, держа локти близко к туловищу.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.","Coloca los brazos superiores contra el soporte para brazos, manteniendo los codos cerca del torso.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0028","name":"barbell clean and press","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes","shoulders","triceps"],"target":"quads","image":"images/0028-SGY8Zui.jpg","gif_url":"videos/0028-SGY8Zui.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והמוט על הרצפה לפניכם.","כופפו ברכיים והטו את הגו מהירכיים לירידה, ואחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","דחפו דרך העקבים ויישרו ירכיים וברכיים להרמת המוט מהרצפה, כשהוא צמוד לגוף.","כשהמוט מגיע לירכיים, יישרו ירכיים בפיצוץ, משכו כתפיים, ומשכו את המוט למעלה לכיוון החזה.","כשהמוט מגיע לגובה החזה, רדו מתחתיו במהירות ותפסו אותו בגובה הכתפיים, עם מרפקים פונים קדימה וכפות ידיים כלפי מעלה.","מתנוחת התפיסה, לחצו את המוט מעל הראש ביישור הידיים ודחיפתו ישר למעלה.","הורידו את המוט חזרה לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and the barbell on the floor in front of you.","Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.","As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.","As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.","From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, положите штангу на пол перед собой.","Согните ноги в коленях и наклоните бедра, чтобы опуститься и взять штангу хватом сверху, расставив руки чуть шире плеч.","Двигайтесь пятками и выпрямите бедра и колени, чтобы поднять штангу от пола, удерживая ее близко к телу.","Когда штанга достигнет бедер, резко разогните бедра, пожмите плечами и подтяните штангу к груди.","Когда штанга достигнет уровня груди, быстро опуститесь под нее и поймайте ее на уровне плеч, направив локти вперед и ладони вверх.","Из позиции захвата выжмите штангу над головой, вытянув руки и толкнув штангу прямо вверх.","Опустите штангу обратно в исходное положение и повторите желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.","Flexiona las rodillas y las caderas para bajar y agarrar la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Empuja con los talones y extiende las caderas y las rodillas para levantar la barra del suelo, manteniéndola cerca del cuerpo.","Cuando la barra llegue a los muslos, extiende las caderas de forma explosiva, encoge los hombros y tira de la barra hacia el pecho.","Cuando la barra llegue a la altura del pecho, baja rápidamente debajo de ella y atrápala a la altura de los hombros, con los codos apuntando hacia delante y las palmas hacia arriba.","Desde la posición de recepción, empuja la barra por encima de la cabeza extendiendo los brazos y llevando la barra recta hacia arriba.","Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"0029","name":"barbell clean-grip front squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/0029-qi996YS.jpg","gif_url":"videos/0029-qi996YS.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים והמוט מונח על החזה העליון, עם מרפקים פונים קדימה.","הורידו את הגוף בכיפוף ברכיים ודחיפת האגן לאחור, כאילו אתם מתיישבים לאחור על כיסא.","שמרו על חזה מורם וגב ישר תוך כדי הירידה, וודאו שהברכיים לא עוברות את קצות האצבעות של הרגליים.","המשיכו לרדת עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים לחזרה לעמידה, ביישור הירכיים והברכיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.","Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.","Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч, положив штангу на верхнюю часть груди, локти направлены вперед.","Опустите тело, согнув колени и отведя бедра назад, как будто вы садитесь на стул.","При опускании держите грудь поднятой, а спину прямой, следя за тем, чтобы колени не выходили за носки ног.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение в нижней точке, затем оттолкнитесь пятками, чтобы снова встать, выпрямляя бедра и колени.","Повторите необходимое количество повторений."],"es":["Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, con los codos apuntando hacia delante.","Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás, como si te sentaras en una silla.","Mantén el pecho elevado y la espalda recta mientras bajas, asegurándote de que las rodillas no sobrepasen los dedos de los pies.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa breve en la parte baja y luego empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."]}},{"id":"0030","name":"barbell close-grip bench press","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0030-J6Dx1Mu.jpg","gif_url":"videos/0030-J6Dx1Mu.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","אחזו במוט באחיזה צרה, מעט צרה מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו באיטיות לכיוון החזה, עם מרפקים קרובים לגוף.","עצרו לרגע כשהמוט נוגע בחזה.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу узким хватом, на расстоянии чуть уже ширины плеч.","Снимите штангу и медленно опустите ее к груди, держа локти близко к телу.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0031","name":"barbell curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0031-25GPyDY.jpg","gif_url":"videos/0031-25GPyDY.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה תחתונה, כפות ידיים פונות קדימה.","שמרו על מרפקים צמודים לגוף ונשפו תוך כדי כיפוף המוט למעלה וכיווץ הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמוט בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the bar back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу обратным хватом ладонями вперед.","Держите локти близко к туловищу и выдыхайте, сгибая штангу и одновременно сокращая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","На вдохе начните медленно опускать штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas mirando hacia delante.","Mantén los codos cerca del torso y exhala mientras levantas el peso contrayendo los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala mientras comienzas a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0032","name":"barbell deadlift","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0032-ila4NZS.jpg","gif_url":"videos/0032-ila4NZS.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים כשהמוט על הרצפה מולכם.","כופפו ברכיים והטו את הגו קדימה מהירכיים, ואחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","שמרו על גב ישר וחזה מורם, ודחפו דרך העקבים כדי להרים את המוט מהרצפה תוך יישור הירכיים והברכיים.","בעמידה זקופה, כווצו את הישבן ושמרו על שרירי הליבה מופעלים.","הורידו את המוט חזרה לרצפה בכיפוף ירכיים וברכיים, תוך שמירה על גב ישר.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","As you stand up straight, squeeze your glutes and keep your core engaged.","Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, положите штангу на землю перед собой.","Согните колени и наклоните бедра, чтобы опустить туловище и взять штангу хватом сверху, руки на расстоянии чуть шире плеч.","Держите спину прямо, а грудь приподнятой, пока вы двигаетесь пятками, чтобы поднять штангу с земли, вытягивая бедра и колени.","Вставая прямо, сожмите ягодицы и держите корпус напряженным.","Опустите штангу обратно на землю, сгибая бедра и колени, сохраняя спину прямой.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.","Flexiona las rodillas y las caderas para bajar el torso y agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas.","Al ponerte de pie, aprieta los glúteos y mantén el core activado.","Baja la barra de vuelta al suelo flexionando las caderas y las rodillas, manteniendo la espalda recta.","Repite el número de repeticiones deseado."]}},{"id":"0033","name":"barbell decline bench press","category":"chest","body_part":"chest","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0033-GrO65fd.jpg","gif_url":"videos/0033-GrO65fd.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשכפות הרגליים מקובעות והראש נמוך מהאגן.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו באיטיות לכיוון החזה, עם מרפקים צמודים לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, зафиксировав ноги и опустив голову ниже бедер.","Возьмите штангу хватом сверху на расстоянии чуть шире плеч.","Ослабьте штангу и медленно опустите ее к груди, держа локти прижатыми.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0034","name":"barbell decline bent arm pullover","category":"back","body_part":"back","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"lats","image":"images/0034-hMEptv0.jpg","gif_url":"videos/0034-hMEptv0.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשהראש נמוך מהאגן וכפות הרגליים מקובעות.","החזיקו מוט באחיזה עליונה (כפות ידיים פונות מכם) ומתחו את הידיים ישר מעל החזה.","הורידו את המוט מאחורי הראש בשליטה, תוך שמירה על ידיים כפופות מעט.","עצרו לרגע, ואז הרימו את המוט חזרה לנקודת ההתחלה בכיווץ רחב הגבי.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position by contracting your lats.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, опустив голову ниже бедер и зафиксировав ступни.","Возьмите штангу пронированным хватом (ладонями от себя) и вытяните руки прямо над грудью.","Контролируемо опустите штангу за голову, держа руки слегка согнутыми.","Сделайте паузу на мгновение, затем поднимите штангу обратно в исходное положение, напрягая широчайшие мышцы.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.","Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho.","Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos ligeramente flexionados.","Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial contrayendo los dorsales.","Repite el número de repeticiones deseado."]}},{"id":"0035","name":"barbell decline close grip to skull press","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0035-LMGXZn8.jpg","gif_url":"videos/0035-LMGXZn8.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשהראש נמוך מהרגליים, והחזיקו מוט באחיזה צרה.","הורידו את המוט לכיוון המצח בכיפוף מרפקים, תוך שמירה על זרועות עליונות ללא תזוזה.","עצרו לרגע, ואז יישרו ידיים ולחצו את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.","Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms to press the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, опустив голову ниже ног, и возьмите штангу узким хватом.","Опустите штангу ко лбу, согнув локти, сохраняя плечи неподвижными.","Сделайте паузу на мгновение, затем вытяните руки, чтобы вернуть штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con la cabeza más baja que los pies y sujeta una barra con un agarre cerrado.","Baja la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos.","Haz una pausa breve y luego extiende los brazos para empujar la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1255","name":"barbell decline pullover","category":"chest","body_part":"chest","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1255-9sgNE2O.jpg","gif_url":"videos/1255-9sgNE2O.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשהראש נמוך מהאגן וכפות הרגליים מקובעות.","החזיקו את המוט באחיזה עליונה (כפות ידיים פונות מכם) וידיים מעט רחבות מרוחב הכתפיים.","מתחו את הידיים מעל החזה, עם כיפוף קל במרפקים.","הורידו את המוט בתנועה קשתית מאחורי הראש, עד תחושת מתיחה בחזה ובכתפיים.","עצרו לרגע, ואז החזירו את המוט לנקודת ההתחלה בהיפוך התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.","Extend your arms above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.","Pause for a moment, then return the barbell to the starting position by reversing the motion.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, опустив голову ниже бедер и зафиксировав ступни.","Держите штангу пронированным хватом (ладонями от себя), расставив руки чуть шире плеч.","Вытяните руки над грудью, сохраняя небольшой изгиб в локтях.","Опустите штангу по дуге за голову, чувствуя растяжение в груди и плечах.","Сделайте паузу на мгновение, затем верните штангу в исходное положение, изменив движение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.","Sujeta la barra con un agarre pronado (palmas mirando hacia afuera) y las manos un poco más separadas que el ancho de los hombros.","Extiende los brazos por encima del pecho, manteniendo una ligera flexión en los codos.","Baja la barra describiendo un arco detrás de la cabeza, sintiendo un estiramiento en el pecho y los hombros.","Haz una pausa breve y luego devuelve la barra a la posición inicial invirtiendo el movimiento.","Repite el número de repeticiones deseado."]}},{"id":"0036","name":"barbell decline wide-grip press","category":"chest","body_part":"chest","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0036-hl8DUh8.jpg","gif_url":"videos/0036-hl8DUh8.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשכפות הרגליים מקובעות והראש נמוך מהאגן.","אחזו במוט באחיזה רחבה, מעט רחבה מרוחב הכתפיים.","הורידו את המוט לחזה, עם מרפקים פתוחים לצדדים.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows out to the sides.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, зафиксировав ноги и опустив голову ниже бедер.","Возьмите штангу широким хватом, на расстоянии чуть шире ширины плеч.","Опустите штангу к груди, разведя локти в стороны.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.","Baja la barra hacia el pecho, manteniendo los codos hacia los lados.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0037","name":"barbell decline wide-grip pullover","category":"back","body_part":"back","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"lats","image":"images/0037-Hj4FOCd.jpg","gif_url":"videos/0037-Hj4FOCd.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשהראש נמוך מהאגן וכפות הרגליים מקובעות.","החזיקו מוט באחיזה רחבה ומתחו את הידיים ישר מעל החזה.","הורידו את המוט מאחורי הראש בשליטה, תוך שמירה על ידיים ישרות.","עצרו לרגע, ואז הרימו את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a wide grip and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms straight.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, опустив голову ниже бедер и зафиксировав ступни.","Возьмите штангу широким хватом и вытяните руки прямо над грудью.","Контролируемо опустите штангу за голову, держа руки прямыми.","Сделайте паузу на мгновение, затем поднимите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.","Sujeta una barra con un agarre amplio y extiende los brazos rectos por encima del pecho.","Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos rectos.","Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0038","name":"barbell drag curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0038-IENzBdA.jpg","gif_url":"videos/0038-IENzBdA.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה תחתונה, כפות ידיים כלפי מעלה.","תנו למוט להשתלשל בידיים ישרות מול הירכיים.","תוך שמירה על הזרועות העליונות במקומן, גלגלו את המוט למעלה לכיוון החזה בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Let the barbell hang at arm's length in front of your thighs.","Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу обратным хватом ладонями вверх.","Пусть штанга висит на расстоянии вытянутой руки перед бедрами.","Удерживая плечи неподвижно, поднимите штангу к груди, напрягая бицепсы.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.","Deja que la barra cuelgue a la longitud del brazo frente a los muslos.","Manteniendo los brazos superiores fijos, levanta la barra hacia el pecho contrayendo los bíceps.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1370","name":"barbell floor calf raise","category":"lower legs","body_part":"lower legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1370-2IHEa2T.jpg","gif_url":"videos/1370-2IHEa2T.gif","instruction_steps":{"he":["הניחו מוט על הרצפה לפניכם.","עמדו כשכריות כפות הרגליים על קצה המוט והעקבים משתלשלים.","אחזו בחפץ יציב לשיווי משקל במידת הצורך.","הרימו את העקבים גבוה ככל האפשר, בעזרת שרירי התאומים להרמת הגוף.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place a barbell on the floor in front of you.","Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.","Hold onto a stable object for balance if needed.","Raise your heels as high as possible, using your calves to lift your body.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Положите штангу на пол перед собой.","Встаньте подушечками стоп на край штанги, свесив пятки.","При необходимости держитесь за устойчивый предмет для равновесия.","Поднимите пятки как можно выше, используя икроножные мышцы для подъема тела.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca una barra en el suelo frente a ti.","Ponte de pie con la parte delantera de los pies sobre el borde de la barra, dejando los talones colgando.","Sujétate de un objeto estable para mantener el equilibrio si es necesario.","Levanta los talones lo más alto posible, usando las pantorrillas para elevar el cuerpo.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0039","name":"barbell front chest squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/0039-IeTIEqg.jpg","gif_url":"videos/0039-IeTIEqg.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים, כפות רגליים פונות מעט החוצה.","החזיקו את המוט מול החזה, ידיים ברוחב כתפיים ומרפקים פונים קדימה.","הפעילו את הליבה ושמרו על חזה מורם תוך הורדת הגוף לעמדת סקוואט, בדחיפת האגן לאחור וכיפוף הברכיים.","רדו עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Для начала встаньте, поставив ноги на ширине плеч, носки слегка развернуты наружу.","Держите штангу перед грудью, руки на ширине плеч, локти направлены вперед.","Напрягите корпус и держите грудь поднятой, опуская тело в присед, отводя бедра назад и сгибая колени.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra frente al pecho con las manos separadas a la altura de los hombros, los codos apuntando hacia delante.","Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0041","name":"barbell front raise","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"delts","image":"images/0041-b2Uoz54.jpg","gif_url":"videos/0041-b2Uoz54.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט מול הירכיים באחיזה עליונה.","שמרו על ידיים ישרות והרימו את המוט קדימה ולמעלה עד גובה הכתפיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, удерживайте штангу перед бедрами хватом сверху.","Держите руки прямо и поднимите штангу вперед и вверх, пока она не достигнет уровня плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado.","Mantén los brazos rectos y levanta la barra hacia delante y hacia arriba hasta que alcance la altura de los hombros.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0040","name":"barbell front raise and pullover","category":"chest","body_part":"chest","equipment":"barbell","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0040-33AzZeV.jpg","gif_url":"videos/0040-33AzZeV.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה עליונה, כפות ידיים כלפי מטה.","שמרו על ידיים ישרות והרימו את המוט לפניכם עד גובה הכתפיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","לאחר מכן, הורידו את המוט מאחורי הראש, תוך שמירה על ידיים ישרות.","עצרו לרגע בנקודה התחתונה, ואז הרימו את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Next, lower the barbell behind your head, keeping your arms straight.","Pause for a moment at the bottom, then raise the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу хватом сверху ладонями вниз.","Держите руки прямо и поднимите штангу перед собой до уровня плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Затем опустите штангу за голову, держа руки прямыми.","Сделайте небольшую паузу в нижней точке, затем поднимите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.","Mantén los brazos rectos y levanta la barra frente a ti hasta que alcance la altura de los hombros.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","A continuación, baja la barra detrás de la cabeza, manteniendo los brazos rectos.","Haz una pausa breve en la parte baja y luego levanta la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0042","name":"barbell front squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/0042-zG0zs85.jpg","gif_url":"videos/0042-zG0zs85.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים, כפות רגליים פונות מעט החוצה.","החזיקו את המוט מול הכתפיים, מונח על עצמות הבריח והכתפיים.","הפעילו את הליבה ושמרו על חזה מורם תוך הורדת הגוף לעמדת סקוואט, בדחיפת האגן לאחור וכיפוף הברכיים.","רדו עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Для начала встаньте, поставив ноги на ширине плеч, носки слегка развернуты наружу.","Держите штангу перед плечами, положив ее на ключицы и плечи.","Напрягите корпус и держите грудь поднятой, опуская тело в присед, отводя бедра назад и сгибая колени.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra frente a los hombros, apoyándola sobre la clavícula y los hombros.","Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0043","name":"barbell full squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/0043-qXTaZnJ.jpg","gif_url":"videos/0043-qXTaZnJ.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, כפות הרגליים פונות מעט החוצה.","הניחו את המוט על הגב העליון, על שרירי הטרפז או הדלתא האחורית.","הפעילו את שרירי הליבה ושמרו על חזה זקוף כשאתם מתחילים לרדת.","כופפו ברכיים וירכיים, ודחפו את האגן לאחור ולמטה כאילו אתם מתיישבים על כיסא.","רדו עד שהירכיים מקבילות לרצפה או מעט מתחת.","שמרו על הברכיים בקו אחד עם כפות הרגליים ועל המשקל בעקבים.","דחפו דרך העקבים כדי לחזור לעמידה, תוך יישור הירכיים והברכיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower yourself until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Держите штангу на верхней части спины, опираясь на трапеции или задние дельты.","Напрягите корпус и держите грудь поднятой, когда начинаете опускать тело вниз.","Согните колени и бедра, отводя бедра назад и вниз, как будто вы сидите на стуле.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или немного ниже.","Держите колени на одной линии с пальцами ног, а вес тела перенесите на пятки.","Протолкните пятки, чтобы встать обратно, выпрямляя бедра и колени.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.","Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.","Baja hasta que los muslos queden paralelos al suelo o un poco por debajo.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."]}},{"id":"1461","name":"barbell full squat (back pov)","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/1461-DhMl549.jpg","gif_url":"videos/1461-DhMl549.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, כפות הרגליים פונות מעט החוצה.","הניחו את המוט על הגב העליון, על שרירי הטרפז או הדלתא האחורית.","הפעילו את שרירי הליבה ושמרו על חזה זקוף כשאתם מתחילים לרדת.","כופפו ברכיים וירכיים, ודחפו את האגן לאחור ולמטה כאילו אתם מתיישבים על כיסא.","הורידו את הגוף עד שהירכיים מקבילות לרצפה או מעט מתחת.","שמרו על הברכיים בקו אחד עם כפות הרגליים ועל המשקל בעקבים.","דחפו דרך העקבים כדי לחזור לעמידה, תוך יישור הירכיים והברכיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Держите штангу на верхней части спины, опираясь на трапеции или задние дельты.","Напрягите корпус и держите грудь поднятой, когда начинаете опускать тело вниз.","Согните колени и бедра, отводя бедра назад и вниз, как будто вы сидите на стуле.","Опускайте тело до тех пор, пока бедра не станут параллельны земле или немного ниже.","Держите колени на одной линии с пальцами ног, а вес тела перенесите на пятки.","Протолкните пятки, чтобы встать обратно, выпрямляя бедра и колени.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.","Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.","Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."]}},{"id":"1462","name":"barbell full squat (side pov)","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/1462-iYzB0Cz.jpg","gif_url":"videos/1462-iYzB0Cz.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, כפות הרגליים פונות מעט החוצה.","הניחו את המוט על הגב העליון, על שרירי הטרפז או הדלתא האחורית.","הפעילו את שרירי הליבה ושמרו על חזה זקוף כשאתם מתחילים לרדת.","כופפו ברכיים וירכיים, ודחפו את האגן לאחור ולמטה כאילו אתם מתיישבים על כיסא.","הורידו את הגוף עד שהירכיים מקבילות לרצפה או מעט מתחת.","שמרו על הברכיים בקו אחד עם כפות הרגליים ועל המשקל בעקבים.","דחפו דרך העקבים כדי לחזור לעמידה, תוך יישור הירכיים והברכיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Держите штангу на верхней части спины, опираясь на трапеции или задние дельты.","Напрягите корпус и держите грудь поднятой, когда начинаете опускать тело вниз.","Согните колени и бедра, отводя бедра назад и вниз, как будто вы сидите на стуле.","Опускайте тело до тех пор, пока бедра не станут параллельны земле или немного ниже.","Держите колени на одной линии с пальцами ног, а вес тела перенесите на пятки.","Протолкните пятки, чтобы встать обратно, выпрямляя бедра и колени.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.","Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.","Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."]}},{"id":"1545","name":"barbell full zercher squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/1545-vR1vold.jpg","gif_url":"videos/1545-vR1vold.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וכפות רגליים פונות מעט החוצה.","החזיקו את המוט בקפלי המרפקים, כשהידיים אוחזות במוט לייצוב.","הפעילו את הליבה ושמרו על חזה מורם תוך הורדת האגן לאחור ולמטה לעמדת סקוואט.","שמרו על הברכיים בקו אחד עם כפות הרגליים ועל המשקל בעקבים.","רדו עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","דחפו דרך העקבים כדי לחזור לעמידה, וכווצו את הישבן בנקודה העליונה של התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top of the movement.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка развернув пальцы ног.","Держите штангу на сгибах локтей, удерживая ее руками для устойчивости.","Напрягите корпус и держите грудь поднятой, опуская бедра назад и вниз в положение приседа.","Держите колени на одной линии с пальцами ног, а вес тела перенесите на пятки.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Проведите пятками, чтобы встать обратно, сжимая ягодицы в верхней части движения.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra en el pliegue de los codos, agarrándola con las manos para mantener la estabilidad.","Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Empuja con los talones para volver a ponerte de pie, apretando los glúteos en la parte alta del movimiento.","Repite el número de repeticiones deseado."]}},{"id":"1409","name":"barbell glute bridge","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1409-qKBpF7I.jpg","gif_url":"videos/1409-qKBpF7I.gif","instruction_steps":{"he":["התחילו בשכיבה על הגב על הרצפה עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו מוט על האגן, אוחזים בו היטב בשתי הידיים.","הפעילו את הישבן ושרירי הליבה, ואז הרימו את האגן מהרצפה עד שהגוף יוצר קו ישר מהברכיים ועד הכתפיים.","עצרו לרגע בנקודה העליונה, תוך כיווץ הישבן.","הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что лягте на спину на землю, согните колени и поставьте ступни на пол.","Положите штангу на бедра, крепко удерживая ее обеими руками.","Задействуйте ягодицы и мышцы корпуса, затем поднимите бедра от земли, пока ваше тело не образует прямую линию от колен до плеч.","Задержитесь на мгновение в верхней точке, напрягая ягодицы.","Медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Empieza tumbado boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.","Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos.","Activa los glúteos y el core, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa breve en la parte alta, apretando los glúteos.","Baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3562","name":"barbell glute bridge two legs on bench (male)","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","core"],"target":"glutes","image":"images/3562-qg2PGl6.jpg","gif_url":"videos/3562-qg2PGl6.gif","instruction_steps":{"he":["התחילו בישיבה על קצה ספסל כשהגב העליון נשען עליו וכפות הרגליים על הרצפה, ברוחב אגן.","הניחו מוט על האגן, אוחזים בו היטב בשתי הידיים.","הפעילו את הישבן ושרירי הליבה, ואז דחפו דרך העקבים להרמת האגן מהספסל, ביצירת קו ישר מהברכיים ועד הכתפיים.","עצרו לרגע בנקודה העליונה, תוך כיווץ הישבן.","הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что сядьте на край скамьи, прислонившись к ней верхней частью спины, а ступни поставьте на землю, на ширине плеч.","Положите штангу на бедра, крепко удерживая ее обеими руками.","Задействуйте ягодицы и мышцы корпуса, затем надавите на пятки, чтобы поднять бедра со скамьи, создавая прямую линию от колен до плеч.","Задержитесь на мгновение в верхней точке, напрягая ягодицы.","Медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Empieza sentado en el borde de un banco con la parte superior de la espalda apoyada contra él y los pies planos sobre el suelo, separados a la altura de las caderas.","Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos.","Activa los glúteos y el core, luego empuja con los talones para levantar las caderas del banco, creando una línea recta desde las rodillas hasta los hombros.","Haz una pausa breve en la parte alta, apretando los glúteos.","Baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0044","name":"barbell good morning","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"lower back","secondary_muscles":["lower back"],"target":"hamstrings","image":"images/0044-XlZ4lAC.jpg","gif_url":"videos/0044-XlZ4lAC.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים והמוט מונח על הגב העליון.","תוך שמירה על גב ישר וליבה מופעלת, הטו את הגו קדימה מהירכיים, בדחיפת הישבן לאחור כאילו אתם מנסים לגעת בקיר שמאחוריכם.","הורידו את הגו עד שהוא מקביל לרצפה, עד תחושת מתיחה בירך האחורית.","עצרו לרגע, ואז חזרו לנקודת ההתחלה בכיווץ הישבן ודחיפת האגן קדימה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и положив штангу на верхнюю часть спины.","Удерживая спину прямой и напряженным корпус, наклонитесь вперед в бедрах, отводя ягодицы назад, как будто вы пытаетесь коснуться ягодицами стены позади себя.","Опускайте туловище до тех пор, пока оно не станет параллельно земле, чувствуя растяжение подколенных сухожилий.","Сделайте паузу на мгновение, затем вернитесь в исходное положение, сжимая ягодицы и толкая бедра вперед.","Повторите необходимое количество повторений."],"es":["Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda.","Manteniendo la espalda recta y el core activado, flexiona las caderas hacia delante, empujando los glúteos hacia atrás como si intentaras tocar la pared detrás de ti con ellos.","Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.","Haz una pausa breve y luego vuelve a la posición inicial apretando los glúteos y empujando las caderas hacia delante.","Repite el número de repeticiones deseado."]}},{"id":"0045","name":"barbell guillotine bench press","category":"chest","body_part":"chest","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0045-GXoaSgn.jpg","gif_url":"videos/0045-GXoaSgn.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הורידו את המוט באיטיות לכיוון הצוואר, עם מרפקים פונים החוצה.","עצרו לרגע כשהמוט מעט מעל הצוואר.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.","Pause for a moment when the barbell is just above your neck.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Медленно опустите штангу к шее, держа локти направленными наружу.","Сделайте паузу на мгновение, когда штанга окажется чуть выше вашей шеи.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Baja la barra lentamente hacia el cuello, manteniendo los codos apuntando hacia afuera.","Haz una pausa breve cuando la barra esté justo encima del cuello.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0046","name":"barbell hack squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0046-5VCj6iH.jpg","gif_url":"videos/0046-5VCj6iH.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים וקצות האצבעות של הרגליים פונות מעט החוצה.","החזיקו את המוט מאחורי הרגליים, מונח על הירכיים העליונות.","הורידו את הגוף בכיפוף ברכיים וירכיים, תוך שמירה על גב ישר וחזה מורם.","המשיכו לרדת עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","עצרו לרגע, ואז דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart and your toes slightly turned out.","Hold the barbell behind your legs, resting it on your upper thighs.","Lower your body by bending at the knees and hips, keeping your back straight and your chest up.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и слегка развернув пальцы ног.","Держите штангу за ногами, положив ее на верхнюю часть бедер.","Опустите тело, согнув колени и бедра, держа спину прямо и грудь вверх.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Сделайте паузу на мгновение, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Empieza de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra detrás de las piernas, apoyándola en la parte superior de los muslos.","Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1436","name":"barbell high bar squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/1436-Gnfo4FM.jpg","gif_url":"videos/1436-Gnfo4FM.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, כפות הרגליים פונות מעט החוצה.","הניחו את המוט על הגב העליון, מונח על שרירי הטרפז.","הפעילו את הליבה ושמרו על חזה מורם כשאתם מתחילים לרדת לסקוואט, בדחיפת האגן לאחור וכיפוף הברכיים.","רדו עד שהירכיים מקבילות לרצפה, או נמוך ככל שנוח לכם.","דחפו דרך העקבים כדי לחזור לעמידה, תוך יישור הירכיים והברכיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell on your upper back, resting it on your traps.","Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Положите штангу на верхнюю часть спины, положив ее на трапеции.","Напрягите корпус и держите грудь поднятой, когда начинаете приседать, отводя бедра назад и сгибая колени.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Протолкните пятки, чтобы встать обратно, выпрямляя бедра и колени.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.","Activa el core y mantén el pecho elevado mientras comienzas a bajar en sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."]}},{"id":"0047","name":"barbell incline bench press","category":"chest","body_part":"chest","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0047-3TZduzM.jpg","gif_url":"videos/0047-3TZduzM.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שכבו על הספסל עם כפות רגליים על הרצפה.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו באיטיות לכיוון החזה, עם מרפקים בזווית של 45 מעלות.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте на скамью, положив ноги на землю.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Снимите штангу и медленно опустите ее к груди, держа локти под углом 45 градусов.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate en el banco con los pies planos sobre el suelo.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos a un ángulo de 45 grados.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1719","name":"barbell incline close grip bench press","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1719-gx7s7uF.jpg","gif_url":"videos/1719-gx7s7uF.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שכבו על הספסל עם כפות רגליים על הרצפה.","אחזו במוט באחיזה צרה, מעט צרה מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו באיטיות לכיוון החזה, עם מרפקים קרובים לגוף.","עצרו לרגע כשהמוט נוגע בחזה.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте на скамью, положив ноги на землю.","Возьмите штангу узким хватом, на расстоянии чуть уже ширины плеч.","Снимите штангу и медленно опустите ее к груди, держа локти близко к телу.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate en el banco con los pies planos sobre el suelo.","Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0048","name":"barbell incline reverse-grip press","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0048-641mIfk.jpg","gif_url":"videos/0048-641mIfk.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שכבו על הספסל ואחזו במוט באחיזה הפוכה, ידיים מעט רחבות מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו לכיוון החזה העליון, עם מרפקים צמודים לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте на скамью и возьмите штангу обратным хватом, руки чуть шире плеч.","Снимите штангу и опустите ее к верхней части груди, держа локти прижатыми.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Recuéstate en el banco y agarra la barra con un agarre invertido, con las manos un poco más separadas que el ancho de los hombros.","Saca la barra del soporte y bájala hacia la parte superior del pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0049","name":"barbell incline row","category":"back","body_part":"back","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0049-dmgMp3n.jpg","gif_url":"videos/0049-dmgMp3n.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שכבו על הבטן על הספסל, כשהחזה צמוד לכרית וכפות הרגליים על הרצפה.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שמרו על גב ישר וליבה מופעלת.","משכו את המוט לכיוון החזה, תוך כיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest against the pad and your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте на скамью лицом вниз, прижавшись грудью к подушке, а ступни поставьте на землю.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Держите спину прямо, а корпус напряженным.","Подтяните штангу к груди, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate boca abajo en el banco con el pecho apoyado en el respaldo y los pies planos sobre el suelo.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Mantén la espalda recta y el core activado.","Tira de la barra hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0050","name":"barbell incline shoulder raise","category":"chest","body_part":"chest","equipment":"barbell","muscle_group":"deltoids","secondary_muscles":["deltoids","trapezius"],"target":"serratus anterior","image":"images/0050-xi0yckC.jpg","gif_url":"videos/0050-xi0yckC.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שבו על הספסל כשהגב צמוד לכרית וכפות הרגליים על הרצפה.","החזיקו מוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט לגובה הכתפיים, תוך שמירה על מרפקים כפופים מעט.","הרימו את המוט באיטיות מעל הראש, עד יישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell up to shoulder height, keeping your elbows slightly bent.","Slowly raise the barbell overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Сядьте на скамью, прислонившись спиной к подушке, а ступни поставьте на землю.","Возьмите штангу хватом сверху, на расстоянии чуть шире ширины плеч.","Поднимите штангу до уровня плеч, слегка согнув локти.","Медленно поднимите штангу над головой, полностью выпрямляя руки.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно на высоту плеч.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.","Sujeta una barra con un agarre pronado, un poco más ancho que la separación de los hombros.","Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.","Levanta lentamente la barra por encima de la cabeza, extendiendo completamente los brazos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"0051","name":"barbell jefferson squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0051-pkSoCW9.jpg","gif_url":"videos/0051-pkSoCW9.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וכפות רגליים פונות מעט החוצה.","החזיקו את המוט באחיזה עליונה, מונח על קדמת הגוף, מעט מתחת למותניים.","צעדו עם כף רגל שמאל קדימה וכף רגל ימין לאחור, תוך שמירה על רגליים ברוחב כתפיים.","כופפו ברכיים והורידו את הגוף לעמדת סקוואט, תוך שמירה על גב ישר וחזה מורם.","דחפו דרך העקבים לעמידה חזרה בנקודת ההתחלה.","חזרו על התנועה, בהחלפת הרגל הקדמית והאחורית בכל חזרה."],"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.","Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Push through your heels to stand back up to the starting position.","Repeat the movement, alternating your forward and back foot with each repetition."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка развернув пальцы ног.","Держите штангу хватом сверху, положив ее на переднюю часть тела, чуть ниже талии.","Сделайте шаг левой ногой вперед, а правой назад, держа ноги на ширине плеч.","Согните ноги в коленях и опустите тело в положение приседа, держа спину прямо и грудь вверх.","Оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите движение, чередуя переднюю и заднюю ногу при каждом повторении."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra con un agarre pronado, apoyándola en la parte delantera del cuerpo, justo debajo de la cintura.","Da un paso con el pie izquierdo hacia delante y el pie derecho hacia atrás, manteniendo los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Empuja con los talones para volver a ponerte de pie en la posición inicial.","Repite el movimiento, alternando el pie delantero y el trasero en cada repetición."]}},{"id":"0052","name":"barbell jm bench press","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0052-ZsiqXYa.jpg","gif_url":"videos/0052-ZsiqXYa.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הורידו את המוט לחזה, עם מרפקים צמודים לגוף.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Опустите штангу к груди, держа локти близко к телу.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0053","name":"barbell jump squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0053-1gFNTZV.jpg","gif_url":"videos/0053-1gFNTZV.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים, אוחזים מוט על הגב העליון.","רדו לסקוואט בכיפוף ברכיים ודחיפת האגן לאחור.","בהגיעכם לנקודה התחתונה של הסקוואט, התפרצו כלפי מעלה בקפיצה מהרצפה.","תוך כדי הקפיצה, יישרו ירכיים, ברכיים וקרסוליים, בדחיפה דרך קצות האצבעות של הרגליים.","נחתו ברכות חזרה בעמדת הסקוואט וחזרו מיד על התנועה למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Once you reach the bottom of the squat, explode upwards by jumping off the ground.","As you jump, extend your hips, knees, and ankles, pushing through your toes.","Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч, удерживая штангу на верхней части спины.","Опустите тело в присед, согнув колени и отведя бедра назад.","Как только вы достигнете нижней точки приседа, взорвитесь вверх, отпрыгнув от земли.","Во время прыжка вытягивайте бедра, колени и лодыжки, толкая пальцы ног.","Мягко приземлитесь обратно в положение приседа и сразу же повторите движение желаемое количество повторений."],"es":["Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Al llegar a la parte baja de la sentadilla, impúlsate hacia arriba saltando desde el suelo.","Al saltar, extiende las caderas, las rodillas y los tobillos, empujando con la punta de los pies.","Aterriza con suavidad de vuelta en la posición de sentadilla y repite el movimiento de inmediato el número de repeticiones deseado."]}},{"id":"1410","name":"barbell lateral lunge","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1410-py1HSzx.jpg","gif_url":"videos/1410-py1HSzx.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים מוט על הגב העליון.","צעדו צעד גדול הצידה עם כף רגל ימין, תוך שמירה על כף רגל שמאל נטועה במקומה.","כופפו את ברך ימין והורידו את הגוף לעמדת מספריים, תוך שמירה על רגל שמאל ישרה.","דחפו עם כף רגל ימין וחזרו לנקודת ההתחלה.","חזרו על התנועה בצד השני, בצעד עם כף רגל שמאל."],"en":["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.","Push off with your right foot and return to the starting position.","Repeat on the other side, stepping with your left foot."],"ru":["Встаньте, ноги на ширине плеч, удерживая штангу на верхней части спины.","Сделайте большой шаг в сторону правой ногой, удерживая левую ногу на месте.","Согните правое колено и опустите тело в положение выпада, сохраняя левую ногу прямой.","Оттолкнитесь правой ногой и вернитесь в исходное положение.","Повторите то же самое в другую сторону, наступая левой ногой."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.","Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo.","Flexiona la rodilla derecha y baja el cuerpo hacia una posición de zancada, manteniendo la pierna izquierda recta.","Empuja con el pie derecho y vuelve a la posición inicial.","Repite hacia el otro lado, dando el paso con el pie izquierdo."]}},{"id":"1435","name":"barbell low bar squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1435-bTpEUcm.jpg","gif_url":"videos/1435-bTpEUcm.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והמוט מונח על הגב העליון.","תוך שמירה על חזה מורם וליבה מופעלת, הורידו את הגוף באיטיות בכיפוף ברכיים ודחיפת האגן לאחור.","המשיכו לרדת עד שהירכיים מקבילות לרצפה או מעט מתחת.","עצרו לרגע, ואז דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, а штанга положитесь на верхнюю часть спины.","Удерживая грудь поднятой и напряженным корпус, медленно опустите тело, сгибая колени и отводя бедра назад.","Продолжайте опускаться до тех пор, пока бедра не станут параллельны земле или немного ниже.","Сделайте паузу на мгновение, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda.","Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.","Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0054","name":"barbell lunge","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0054-t8iSghb.jpg","gif_url":"videos/0054-t8iSghb.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים ומוט מונח על הגב העליון.","צעדו קדימה עם רגל ימין, תוך שמירה על גו זקוף.","הורידו את הגוף בכיפוף ברך ימין עד שהירך מקבילה לרצפה.","דחפו דרך עקב ימין כדי לחזור לנקודת ההתחלה.","חזרו על התנועה עם רגל שמאל, לסירוגין בין הרגליים למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step forward with your right foot, keeping your torso upright.","Lower your body by bending your right knee until your thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg, alternating legs for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и положив штангу на верхнюю часть спины.","Сделайте шаг вперед правой ногой, удерживая туловище в вертикальном положении.","Опустите тело, согнув правое колено, пока бедро не станет параллельно земле.","Оттолкнитесь правой пяткой, чтобы вернуться в исходное положение.","Повторите то же самое с левой ногой, чередуя ноги необходимое количество повторений."],"es":["Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda.","Da un paso hacia delante con el pie derecho, manteniendo el torso erguido.","Baja el cuerpo flexionando la rodilla derecha hasta que el muslo quede paralelo al suelo.","Empuja con el talón derecho para regresar a la posición inicial.","Repite con la pierna izquierda, alternando las piernas el número de repeticiones deseado."]}},{"id":"1720","name":"barbell lying back of the head tricep extension","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1720-yg8Totb.jpg","gif_url":"videos/1720-yg8Totb.gif","instruction_steps":{"he":["שכבו על ספסל עם כפות רגליים על הרצפה והראש בקצה הספסל.","החזיקו מוט באחיזה עליונה, ידיים ברוחב כתפיים, ומתחו את הידיים ישר מעל החזה.","תוך שמירה על הזרועות העליונות ללא תזוזה, הורידו באיטיות את המוט מאחורי הראש בכיפוף מרפקים.","עצרו לרגע, ואז יישרו את הידיים חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Возьмите штангу хватом сверху, руки на ширине плеч, вытяните руки вверх над грудью.","Удерживая плечи неподвижно, медленно опустите штангу за голову, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0055","name":"barbell lying close-grip press","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0055-EcaV7aL.jpg","gif_url":"videos/0055-EcaV7aL.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","אחזו במוט באחיזה צרה, ידיים ברוחב כתפיים, כפות ידיים פונות לכיוון כפות הרגליים.","הרימו את המוט מהמתקן והחזיקו אותו ישר מעל החזה עם ידיים ישרות לגמרי.","הורידו את המוט באיטיות לכיוון החזה, תוך שמירה על מרפקים קרובים לגוף.","עצרו לרגע כשהמוט נוגע בחזה, ואז דחפו אותו חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу узким хватом, руки на ширине плеч, ладони обращены к ногам.","Снимите штангу со стойки и держите ее прямо над грудью, полностью вытянув руки.","Медленно опустите штангу к груди, держа локти близко к телу.","Сделайте паузу на мгновение, когда штанга коснется груди, затем поднимите ее обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas mirando hacia los pies.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0056","name":"barbell lying close-grip triceps extension","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0056-HJ63mSO.jpg","gif_url":"videos/0056-HJ63mSO.gif","instruction_steps":{"he":["שכבו על ספסל עם כפות רגליים על הרצפה והראש בקצה הספסל.","אחזו במוט באחיזה צרה, ידיים ברוחב כתפיים, כפות ידיים כלפי מעלה.","יישרו את הידיים לגמרי, בהרמת המוט מעל החזה.","תוך שמירה על הזרועות העליונות ללא תזוזה, הורידו באיטיות את המוט לכיוון המצח בכיפוף מרפקים.","עצרו לרגע בנקודה התחתונה, ואז יישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.","Extend your arms fully, lifting the barbell above your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Возьмите штангу узким хватом, руки на ширине плеч, ладонями вверх.","Полностью выпрямите руки, подняв штангу над грудью.","Удерживая плечи неподвижно, медленно опустите штангу ко лбу, сгибая локти.","Задержитесь на мгновение в нижней точке, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas hacia arriba.","Extiende completamente los brazos, levantando la barra por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.","Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0057","name":"barbell lying extension","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0057-EMpUwRI.jpg","gif_url":"videos/0057-EMpUwRI.gif","instruction_steps":{"he":["שכבו על ספסל עם כפות רגליים על הרצפה והראש בקצה הספסל.","החזיקו את המוט באחיזה עליונה, ידיים ברוחב כתפיים, ומתחו את הידיים ישר מעל החזה.","תוך שמירה על הזרועות העליונות ללא תזוזה, הורידו באיטיות את המוט לכיוון המצח בכיפוף מרפקים.","עצרו לרגע, ואז יישרו את הידיים חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Возьмите штангу хватом сверху, руки на ширине плеч, вытяните руки вверх над грудью.","Удерживая плечи неподвижно, медленно опустите штангу ко лбу, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0058","name":"barbell lying lifting (on hip)","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/0058-SNFfUff.jpg","gif_url":"videos/0058-SNFfUff.gif","instruction_steps":{"he":["שכבו על הגב על ספסל, עם כפות רגליים על הרצפה וברכיים כפופות.","החזיקו את המוט באחיזה עליונה ומקמו אותו על הירכיים.","תוך הפעלת הישבן, הרימו את האגן מהספסל עד שהגוף יוצר קו ישר מהברכיים ועד הכתפיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back on a bench with your feet flat on the ground and your knees bent.","Hold the barbell with an overhand grip and position it on your hips.","Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину на скамью, поставьте ступни на землю и согните колени.","Возьмите штангу хватом сверху и расположите ее на бедрах.","Задействуя ягодицы, поднимите бедра со скамьи, пока ваше тело не образует прямую линию от колен до плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y las rodillas flexionadas.","Sujeta la barra con un agarre pronado y colócala sobre las caderas.","Activando los glúteos, levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0059","name":"barbell lying preacher curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0059-SYJ4Bkt.jpg","gif_url":"videos/0059-SYJ4Bkt.gif","instruction_steps":{"he":["שבו על ספסל פריצ'ר כשהחזה צמוד לכרית והידיים מתוחות מעבר לקצה, אוחזות במוט באחיזה תחתונה.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמוט בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью для проповедника, прижав грудь к подушке и вытянув руки через край, держа штангу обратным хватом.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco predicador con el pecho apoyado en el respaldo y los brazos extendidos sobre el borde, sujetando una barra con un agarre supino.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0061","name":"barbell lying triceps extension","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0061-iZop9xO.jpg","gif_url":"videos/0061-iZop9xO.gif","instruction_steps":{"he":["שכבו על ספסל עם כפות רגליים על הרצפה והראש בקצה הספסל.","החזיקו את המוט באחיזה עליונה, ידיים ברוחב כתפיים, ומתחו את הידיים ישר מעל החזה.","תוך שמירה על הזרועות העליונות ללא תזוזה, הורידו באיטיות את המוט לכיוון המצח בכיפוף מרפקים.","עצרו לרגע בנקודה התחתונה, ואז יישרו את הידיים חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Возьмите штангу хватом сверху, руки на ширине плеч, вытяните руки вверх над грудью.","Удерживая плечи неподвижно, медленно опустите штангу ко лбу, сгибая локти.","Задержитесь на мгновение в нижней точке, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.","Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0060","name":"barbell lying triceps extension skull crusher","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0060-h8LFzo9.jpg","gif_url":"videos/0060-h8LFzo9.gif","instruction_steps":{"he":["שכבו על ספסל עם כפות רגליים על הרצפה והראש בקצה הספסל.","החזיקו את המוט באחיזה עליונה, ידיים ברוחב כתפיים, ומתחו את הידיים ישר מעל החזה.","תוך שמירה על הזרועות העליונות ללא תזוזה, הורידו באיטיות את המוט לכיוון המצח בכיפוף מרפקים.","עצרו לרגע כשהמוט מעט מעל המצח, ואז יישרו את הידיים חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Возьмите штангу хватом сверху, руки на ширине плеч, вытяните руки вверх над грудью.","Удерживая плечи неподвижно, медленно опустите штангу ко лбу, сгибая локти.","Сделайте паузу на мгновение, когда штанга окажется прямо над лбом, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.","Haz una pausa breve cuando la barra esté justo encima de la frente y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0063","name":"barbell narrow stance squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0063-elhhVgj.jpg","gif_url":"videos/0063-elhhVgj.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וקצות האצבעות של הרגליים פונות מעט החוצה.","הניחו את המוט על הגב העליון, על שרירי הטרפז או הדלתא האחורית.","הפעילו את הליבה ושמרו על חזה מורם תוך הורדת הגוף באיטיות בכיפוף ברכיים ודחיפת האגן לאחור.","המשיכו לרדת עד שהירכיים מקבילות לרצפה או מעט מתחת.","עצרו לרגע, ואז דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","Держите штангу на верхней части спины, опираясь на трапеции или задние дельты.","Напрягите корпус и держите грудь поднятой, медленно опуская тело, сгибая колени и отводя бедра назад.","Продолжайте опускаться до тех пор, пока бедра не станут параллельны земле или немного ниже.","Сделайте паузу на мгновение, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.","Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0064","name":"barbell one arm bent over row","category":"back","body_part":"back","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0064-Jsgsc27.jpg","gif_url":"videos/0064-Jsgsc27.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, ברכיים כפופות מעט, ואחזו מוט ביד אחת באחיזה עליונה.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וראש בתנוחה ניטרלית.","משכו את המוט למעלה לכיוון החזה, תוך שמירה על מרפק קרוב לגוף וכיווץ השכמות זו לזו.","הורידו את המוט חזרה לנקודת ההתחלה בשליטה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.","Bend forward at the hips, keeping your back straight and your head in a neutral position.","Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Встаньте, ноги на ширине плеч, колени слегка согнуты, возьмите штангу одной рукой хватом сверху.","Наклонитесь вперед в бедрах, сохраняя спину прямой и голову в нейтральном положении.","Подтяните штангу к груди, держа локоть близко к телу и сжимая лопатки вместе.","Контролируемым образом опустите штангу обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con una mano usando un agarre pronado.","Inclínate hacia delante desde las caderas, manteniendo la espalda recta y la cabeza en posición neutral.","Tira de la barra hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.","Baja la barra de vuelta a la posición inicial de forma controlada.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0065","name":"barbell one arm floor press","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0065-vtusOWT.jpg","gif_url":"videos/0065-vtusOWT.gif","instruction_steps":{"he":["שכבו על הגב על הרצפה עם ברכיים כפופות וכפות רגליים על הרצפה.","החזיקו את המוט ביד אחת, כף יד כלפי מעלה, ומתחו את היד ישר מעל החזה.","הורידו את המוט באיטיות לכיוון החזה, תוך שמירה על מרפק קרוב לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.","Slowly lower the barbell towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Лягте на спину на пол, согните колени и поставьте ступни на землю.","Держите штангу одной рукой ладонью вверх и вытяните руку прямо над грудью.","Медленно опустите штангу к груди, держа локоть близко к телу.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.","Sujeta la barra con una mano, con la palma hacia arriba, y extiende el brazo recto por encima del pecho.","Baja la barra lentamente hacia el pecho, manteniendo el codo cerca del cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0066","name":"barbell one arm side deadlift","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"target":"glutes","image":"images/0066-2DxtqHL.jpg","gif_url":"videos/0066-2DxtqHL.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במוט ביד אחת באחיזה עליונה.","שמרו על גב ישר וליבה מופעלת.","הטו את הגו מהירכיים והורידו את המוט לצד החיצוני של הרגל, תוך שמירה על יד ישרה וחזה מורם.","הורידו את המוט נמוך ככל האפשר תוך שמירה על טכניקה נכונה.","עצרו לרגע, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.","Keep your back straight and your core engaged.","Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.","Lower the barbell as far as you can while maintaining good form.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, держите штангу в одной руке хватом сверху.","Держите спину прямо, а корпус напряженным.","Согнитесь в бедрах и опустите штангу к внешней стороне ноги, держа руку прямо и грудь вверх.","Опустите штангу как можно ниже, сохраняя при этом хорошую форму.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra en una mano con un agarre pronado.","Mantén la espalda recta y el core activado.","Flexiona las caderas y baja la barra hacia el exterior de la pierna, manteniendo el brazo recto y el pecho elevado.","Baja la barra tanto como puedas manteniendo una buena forma.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0067","name":"barbell one arm snatch","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"traps","secondary_muscles":["traps","forearms","core"],"target":"delts","image":"images/0067-xHKN2s8.jpg","gif_url":"videos/0067-xHKN2s8.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, קצות האצבעות פונות מעט החוצה.","אחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","כופפו ברכיים והורידו את האגן לעמדת סקוואט, תוך שמירה על גב ישר וחזה מורם.","יישרו ירכיים, ברכיים וקרסוליים בפיצוץ, בדחיפת המוט כלפי מעלה.","כשהמוט מגיע לגובה החזה, משכו אותו כלפי מעלה עם היד, כשהוא צמוד לגוף.","סובבו את המרפק מתחת למוט ויישרו את היד לגמרי מעל הראש, בנעילת המרפק.","הורידו את המוט חזרה לנקודת ההתחלה בשליטה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips, knees, and ankles, driving the barbell upwards.","As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.","Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","Возьмите штангу хватом сверху, расставив руки чуть шире плеч.","Согните ноги в коленях и опустите бедра в положение приседа, держа спину прямо и грудь вверх.","Взрывно выпрямите бедра, колени и лодыжки, поднимая штангу вверх.","Когда штанга достигнет уровня груди, потяните ее рукой вверх, держа ее близко к телу.","Поверните локоть под штангу и вытяните руку полностью над головой, блокируя локоть.","Контролируемым образом опустите штангу обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.","Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Extiende las caderas, las rodillas y los tobillos de forma explosiva, impulsando la barra hacia arriba.","Cuando la barra llegue a la altura del pecho, tira de ella hacia arriba con el brazo, manteniéndola cerca del cuerpo.","Rota el codo por debajo de la barra y extiende el brazo completamente por encima de la cabeza, bloqueando el codo.","Baja la barra de vuelta a la posición inicial de forma controlada.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0068","name":"barbell one leg squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0068-uKyN64F.jpg","gif_url":"videos/0068-uKyN64F.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט על הגב העליון.","הרימו כף רגל אחת מהרצפה ומתחו אותה קדימה, מקבילה לרצפה.","כופפו את רגל העמידה והורידו את הגוף כאילו אתם מתיישבים לאחור על כיסא, תוך שמירה על חזה מורם וגב ישר.","רדו עד שהירך מקבילה לרצפה, ואז דחפו דרך העקב לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגליים וחזרו על התרגיל."],"en":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Lift one foot off the ground and extend it forward, keeping it parallel to the ground.","Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.","Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"ru":["Встаньте, ноги на ширине плеч, держите штангу на верхней части спины.","Поднимите одну ногу от земли и вытяните ее вперед, удерживая параллельно земле.","Согните стоящую ногу и опустите тело вниз, как будто садитесь на стул, держа грудь поднятой, а спину прямой.","Опускайтесь до тех пор, пока бедро не станет параллельно земле, затем оттолкнитесь пяткой, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу и повторите."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.","Levanta un pie del suelo y extiéndelo hacia delante, manteniéndolo paralelo al suelo.","Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla, manteniendo el pecho elevado y la espalda recta.","Baja hasta que el muslo quede paralelo al suelo, luego empuja con el talón para volver a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."]}},{"id":"0069","name":"barbell overhead squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves","core"],"target":"quads","image":"images/0069-gfk9kD4.jpg","gif_url":"videos/0069-gfk9kD4.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וכפות רגליים פונות מעט החוצה.","החזיקו את המוט באחיזה רחבה, ומקמו אותו מעל הראש עם ידיים ישרות לגמרי.","הפעילו את הליבה והורידו את הגוף לעמדת סקוואט, תוך שמירה על חזה מורם וברכיים בקו אחד עם כפות הרגליים.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.","Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка развернув пальцы ног.","Возьмите штангу широким хватом, расположив ее над головой, полностью выпрямив руки.","Напрягите корпус и опустите тело в положение приседа, удерживая грудь поднятой, а колени касаясь пальцев ног.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra con un agarre amplio, colocándola por encima de la cabeza con los brazos completamente extendidos.","Activa el core y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con los dedos de los pies.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1411","name":"barbell palms down wrist curl over a bench","category":"lower arms","body_part":"lower arms","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/1411-yzYH9pI.jpg","gif_url":"videos/1411-yzYH9pI.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והאמות מונחות על הירכיים, כפות ידיים כלפי מטה.","החזיקו מוט באחיזה עליונה, ידיים ברוחב כתפיים.","הורידו את המוט לכיוון הרצפה בכיפוף שורשי כף היד, תוך שמירה על אמות ללא תזוזה.","עצרו לרגע בנקודה התחתונה, ואז הרימו באיטיות את המוט חזרה ביישור שורשי כף היד.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down.","Hold a barbell with an overhand grip, hands shoulder-width apart.","Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.","Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ступни на землю, положите предплечья на бедра ладонями вниз.","Возьмите штангу хватом сверху, руки на ширине плеч.","Опустите штангу к земле, сгибая запястья, сохраняя предплечья неподвижными.","Задержитесь на мгновение в нижней точке, затем медленно поднимите штангу вверх, вытягивая запястья.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies planos sobre el suelo y los antebrazos apoyados sobre los muslos, con las palmas hacia abajo.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros.","Baja la barra hacia el suelo flexionando las muñecas, manteniendo los antebrazos fijos.","Haz una pausa breve en la parte baja y luego levanta lentamente la barra extendiendo las muñecas.","Repite el número de repeticiones deseado."]}},{"id":"1412","name":"barbell palms up wrist curl over a bench","category":"lower arms","body_part":"lower arms","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/1412-SJAA2IQ.jpg","gif_url":"videos/1412-SJAA2IQ.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו מוט באחיזה תחתונה, כפות ידיים כלפי מעלה.","הניחו את האמות על הספסל, כששורשי כף היד משתלשלים מעבר לקצה.","תוך שמירה על אמות ללא תזוזה, נשפו וגלגלו את שורשי כף היד כלפי מעלה עד הסוף.","החזיקו בנקודת הכיווץ לרגע קצר, ואז שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ступни на землю и возьмите штангу обратным хватом ладонями вверх.","Положите предплечья на скамью так, чтобы запястья свисали с края.","Удерживая предплечья неподвижно, выдохните и согните запястья вверх как можно дальше.","Удерживайте сокращенное положение на короткую паузу, затем вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba.","Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.","Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.","Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3017","name":"barbell pendlay row","category":"back","body_part":"back","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/3017-r0z6xzQ.jpg","gif_url":"videos/3017-r0z6xzQ.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר והחזה מורם.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","משכו את המוט לכיוון הבטן העליונה, תוך כיווץ השכמות זו לזו.","הורידו את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Bend forward at the hips, keeping your back straight and your chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Наклонитесь вперед в бедрах, держа спину прямо и грудь вверх.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Потяните штангу к верхней части живота, сжимая лопатки вместе.","Опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos.","Baja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1751","name":"barbell pin presses","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1751-bndCa3Q.jpg","gif_url":"videos/1751-bndCa3Q.gif","instruction_steps":{"he":["הכינו מוט על מתקן כוח בגובה החזה.","עמדו מול המוט והתמקמו מתחתיו, עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט מהמתקן והחזיקו אותו ישר מעל החזה, עם ידיים מתוחות לגמרי.","הורידו את המוט לכיוון החזה, תוך שמירה על מרפקים צמודים לגוף.","עצרו לרגע כשהמוט נוגע בחזה.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up a barbell on a power rack at chest height.","Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart.","Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended.","Lower the barbell down towards your chest, keeping your elbows tucked in close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Установите штангу на силовую стойку на уровне груди.","Встаньте лицом к штанге и расположитесь под ней, поставив ноги на ширине плеч.","Возьмите штангу хватом сверху, на расстоянии чуть шире ширины плеч.","Снимите штангу со стойки и держите ее прямо над грудью, полностью вытянув руки.","Опустите штангу к груди, держа локти прижатыми к телу.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Coloca una barra en un rack de potencia a la altura del pecho.","Ponte de pie frente a la barra y colócate debajo de ella, con los pies separados a la altura de los hombros.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0070","name":"barbell preacher curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0070-qOgPVf6.jpg","gif_url":"videos/0070-qOgPVf6.gif","instruction_steps":{"he":["שבו על ספסל פריצ'ר כשהזרועות העליונות מונחות על הכרית והחזה צמוד למשענת.","אחזו במוט באחיזה תחתונה, מעט רחבה מרוחב הכתפיים.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המוט למעלה לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью для проповедника, положив плечи на подушку и грудь на опору.","Возьмите штангу хватом снизу, на расстоянии чуть шире ширины плеч.","Удерживая плечи неподвижно, выдохните и поднимите штангу к плечам.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte.","Agarra la barra con un agarre supino, un poco más ancho que la separación de los hombros.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0071","name":"barbell press sit-up","category":"waist","body_part":"waist","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"abs","image":"images/0071-wnEscH8.jpg","gif_url":"videos/0071-wnEscH8.gif","instruction_steps":{"he":["שכבו על הגב על מזרן עם ברכיים כפופות וכפות רגליים על הרצפה.","החזיקו את המוט באחיזה עליונה, מונח על החזה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back on a mat with your knees bent and feet flat on the ground.","Hold the barbell with an overhand grip, resting it on your chest.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину на коврик, согните колени и поставьте ступни на землю.","Возьмите штангу хватом сверху, положив ее на грудь.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en una esterilla con las rodillas flexionadas y los pies planos sobre el suelo.","Sujeta la barra con un agarre pronado, apoyándola sobre el pecho.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0072","name":"barbell prone incline curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0072-WLvTAv5.jpg","gif_url":"videos/0072-WLvTAv5.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שכבו על הבטן על הספסל, כשהחזה והבטן נשענים עליו.","החזיקו מוט באחיזה תחתונה, ברוחב כתפיים.","יישרו את הידיים לגמרי, ותנו למוט להשתלשל לכיוון הרצפה.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המוט עד שהבייספס מכווץ במלואו והמוט בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a barbell with an underhand grip, shoulder-width apart.","Extend your arms fully, allowing the barbell to hang down towards the floor.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте лицом вниз на скамью, прижавшись к ней грудью и животом.","Возьмите штангу хватом снизу на ширине плеч.","Полностью выпрямите руки, позволяя штанге свисать к полу.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.","Sujeta una barra con un agarre supino, separado a la altura de los hombros.","Extiende completamente los brazos, dejando que la barra cuelgue hacia el suelo.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0073","name":"barbell pullover","category":"back","body_part":"back","equipment":"barbell","muscle_group":"chest","secondary_muscles":["chest","triceps"],"target":"lats","image":"images/0073-i6LWjok.jpg","gif_url":"videos/0073-i6LWjok.gif","instruction_steps":{"he":["שכבו על ספסל כשהראש בקצה אחד וכפות הרגליים על הרצפה.","החזיקו מוט באחיזה ברוחב כתפיים ומתחו את הידיים ישר מעל החזה.","תוך שמירה על ידיים ישרות, הורידו את המוט מאחורי הראש בשליטה עד לתחושת מתיחה ברחב הגבי.","עצרו לרגע, ואז הרימו את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив голову на один конец и поставив ноги на пол.","Возьмите штангу хватом на ширине плеч и вытяните руки прямо над грудью.","Держа руки прямыми, контролируемо опустите штангу за голову, пока не почувствуете растяжение в широчайших.","Сделайте паузу на мгновение, затем поднимите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.","Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos rectos, baja la barra detrás de la cabeza de forma controlada hasta sentir un estiramiento en los dorsales.","Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0022","name":"barbell pullover to press","category":"back","body_part":"back","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","chest","shoulders"],"target":"lats","image":"images/0022-znLogoF.jpg","gif_url":"videos/0022-znLogoF.gif","instruction_steps":{"he":["שכבו על ספסל כשהראש בקצה אחד וכפות הרגליים על הרצפה.","החזיקו את המוט באחיזה עליונה (כפות ידיים פונות מכם) ומתחו את הידיים ישר מעל החזה.","תוך שמירה על ידיים ישרות, הורידו את המוט מאחורי הראש בתנועה קשתית עד לתחושת מתיחה ברחב הגבי.","עצרו לרגע, ואז הפכו את התנועה ולחצו את המוט חזרה לנקודת ההתחלה מעל החזה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your head at one end and your feet on the ground.","Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.","Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив голову на один конец и поставив ноги на землю.","Возьмите штангу пронированным хватом (ладонями от себя) и вытяните руки прямо над грудью.","Держа руки прямыми, опустите штангу за голову дугообразными движениями, пока не почувствуете растяжение широчайших мышц.","Сделайте паузу на мгновение, затем поменяйте направление движения и верните штангу в исходное положение над грудью.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.","Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos rectos, baja la barra detrás de la cabeza con un movimiento en forma de arco hasta sentir un estiramiento en los dorsales.","Haz una pausa breve, luego invierte el movimiento y empuja la barra de vuelta a la posición inicial por encima del pecho.","Repite el número de repeticiones deseado."]}},{"id":"0074","name":"barbell rack pull","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0074-za9Ni4z.jpg","gif_url":"videos/0074-za9Ni4z.gif","instruction_steps":{"he":["הכינו מוט על מתקן בגובה הברכיים.","עמדו עם רגליים ברוחב כתפיים, קצות האצבעות פונות מעט החוצה.","כופפו ירכיים וברכיים לירידה ואחזו במוט באחיזה עליונה, ידיים ברוחב כתפיים.","הפעילו את הליבה והרימו את המוט ביישור הירכיים והברכיים, במשיכת הכתפיים לאחור וכיווץ הישבן בנקודה העליונה.","הורידו את המוט חזרה לנקודת ההתחלה בכיפוף ירכיים וברכיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up a barbell on a rack at knee height.","Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.","Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.","Lower the barbell back down to the starting position by bending at the hips and knees.","Repeat for the desired number of repetitions."],"ru":["Установите штангу на стойку на уровне колен.","Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","Согните бедра и колени, чтобы опуститься вниз, и возьмите штангу хватом сверху, руки на ширине плеч.","Напрягите корпус и поднимите штангу, вытягивая бедра и колени, отводя плечи назад и сжимая ягодицы в верхней точке.","Опустите штангу обратно в исходное положение, сгибая бедра и колени.","Повторите необходимое количество повторений."],"es":["Coloca una barra en un soporte a la altura de la rodilla.","Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Flexiona las caderas y las rodillas para bajar y agarrar la barra con un agarre pronado, manos separadas a la altura de los hombros.","Activa el core y levanta la barra extendiendo las caderas y las rodillas, llevando los hombros hacia atrás y apretando los glúteos en la parte alta.","Baja la barra de vuelta a la posición inicial flexionando las caderas y las rodillas.","Repite el número de repeticiones deseado."]}},{"id":"0075","name":"barbell rear delt raise","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0075-Ln9iTbU.jpg","gif_url":"videos/0075-Ln9iTbU.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה עליונה, כפות ידיים כלפי מטה.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","הרימו את המוט לצדדים, תוך שמירה על ידיים ישרות, עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу хватом сверху ладонями вниз.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Поднимите штангу в стороны, держа руки прямыми, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Levanta la barra hacia los lados, manteniendo los brazos rectos, hasta que queden paralelos al suelo.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0076","name":"barbell rear delt row","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/0076-S9zHIvU.jpg","gif_url":"videos/0076-S9zHIvU.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","החזיקו מוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וחזה מורם.","משכו את המוט לכיוון החזה, תוך כיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Возьмите штангу хватом сверху, руки чуть шире плеч.","Наклонитесь вперед в бедрах, держа спину прямо и грудь вверх.","Подтяните штангу к груди, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.","Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Tira de la barra hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0078","name":"barbell rear lunge","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0078-VaP75jl.jpg","gif_url":"videos/0078-VaP75jl.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים ומוט מונח על הגב העליון.","צעדו לאחור עם רגל ימין, ונחתו על כרית כף הרגל.","כופפו את שתי הברכיים והורידו את הגוף עד שירך שמאל מקבילה לרצפה.","דחפו דרך עקב שמאל כדי לחזור לנקודת ההתחלה.","חזרו על התנועה עם הרגל השנייה."],"en":["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и положив штангу на верхнюю часть спины.","Сделайте шаг назад правой ногой, приземлившись на подушечку стопы.","Согните оба колена и опустите тело до тех пор, пока левое бедро не станет параллельно земле.","Оттолкнитесь левой пяткой, чтобы вернуться в исходное положение.","Повторите с другой ногой."],"es":["Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda.","Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.","Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo.","Empuja con el talón izquierdo para volver a la posición inicial.","Repite con la otra pierna."]}},{"id":"0077","name":"barbell rear lunge v. 2","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0077-62Nw60O.jpg","gif_url":"videos/0077-62Nw60O.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט על הגב העליון.","צעדו לאחור עם רגל ימין, ונחתו על כרית כף הרגל.","כופפו את שתי הברכיים והורידו את הגוף עד שירך שמאל מקבילה לרצפה.","דחפו דרך עקב שמאל כדי לחזור לנקודת ההתחלה.","חזרו על התנועה עם הרגל השנייה."],"en":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."],"ru":["Встаньте, ноги на ширине плеч, держите штангу на верхней части спины.","Сделайте шаг назад правой ногой, приземлившись на подушечку стопы.","Согните оба колена и опустите тело до тех пор, пока левое бедро не станет параллельно земле.","Оттолкнитесь левой пяткой, чтобы вернуться в исходное положение.","Повторите с другой ногой."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.","Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.","Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo.","Empuja con el talón izquierdo para volver a la posición inicial.","Repite con la otra pierna."]}},{"id":"0079","name":"barbell revers wrist curl v. 2","category":"lower arms","body_part":"lower arms","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0079-qDnGfDb.jpg","gif_url":"videos/0079-qDnGfDb.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה וברכיים כפופות.","החזיקו מוט באחיזה עליונה, כפות ידיים כלפי מטה, ידיים ברוחב כתפיים.","הניחו את האמות על הירכיים, כששורשי כף היד משתלשלים מעבר לקצה.","תוך שמירה על אמות ללא תזוזה, נשפו וגלגלו את שורשי כף היד כלפי מעלה עד הסוף.","החזיקו בנקודת הכיווץ לרגע קצר, ואז שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и согните колени.","Возьмите штангу хватом сверху, ладонями вниз, руки на ширине плеч.","Положите предплечья на бедра, позволяя запястьям свисать с края.","Удерживая предплечья неподвижно, выдохните и согните запястья вверх как можно дальше.","Удерживайте сокращенное положение на короткую паузу, затем вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies planos sobre el suelo y las rodillas flexionadas.","Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos separadas a la altura de los hombros.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.","Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2187","name":"barbell reverse close-grip bench press","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/2187-YqJw82s.jpg","gif_url":"videos/2187-YqJw82s.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","אחזו במוט באחיזה הפוכה, ידיים ברוחב כתפיים.","הרימו את המוט מהמתקן והחזיקו אותו ישר מעל החזה עם ידיים ישרות לגמרי.","הורידו את המוט באיטיות לכיוון החזה, עם מרפקים צמודים לגוף.","עצרו לרגע כשהמוט מעט מעל החזה.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a reverse grip, hands shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell down towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу обратным хватом, руки на ширине плеч.","Снимите штангу со стойки и держите ее прямо над грудью, полностью вытянув руки.","Медленно опустите штангу к груди, держа локти близко к телу.","Сделайте паузу на мгновение, когда штанга окажется чуть выше груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre invertido, manos separadas a la altura de los hombros.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra esté justo encima del pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0080","name":"barbell reverse curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0080-xNrS20v.jpg","gif_url":"videos/0080-xNrS20v.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה עליונה, כפות ידיים כלפי מטה.","שמרו על הזרועות העליונות ללא תזוזה ונשפו תוך כיפוף המוט כלפי מעלה, בכיווץ הבייספס.","המשיכו להרים את המוט עד שהבייספס מכווץ במלואו והוא בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו תוך הורדת המוט באיטיות חזרה לנקודת ההתחלה, עם זרועות עליונות ללא תזוזה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу хватом сверху ладонями вниз.","Держите плечи неподвижно и на выдохе поднимайте штангу вверх, сокращая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","На вдохе медленно опускайте штангу обратно в исходное положение, сохраняя плечи неподвижными.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.","Mantén los brazos superiores fijos y exhala mientras levantas la barra hacia arriba, contrayendo los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala mientras bajas lentamente la barra de vuelta a la posición inicial, manteniendo los brazos superiores fijos.","Repite el número de repeticiones deseado."]}},{"id":"0118","name":"barbell reverse grip bent over row","category":"back","body_part":"back","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0118-SzX3uzM.jpg","gif_url":"videos/0118-SzX3uzM.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","החזיקו מוט באחיזה עליונה, כפות ידיים כלפי מטה, וידיים מעט רחבות מרוחב הכתפיים.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וחזה מורם, עד שהגו כמעט מקביל לרצפה.","משכו את המוט לכיוון החזה התחתון, תוך כיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Держите штангу хватом сверху, ладонями вниз, руки на расстоянии чуть шире плеч.","Наклонитесь вперед в бедрах, держа спину прямо и грудь вверх, пока туловище не станет почти параллельно полу.","Потяните штангу к нижней части груди, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos un poco más separadas que el ancho de los hombros.","Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo.","Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1256","name":"barbell reverse grip decline bench press","category":"chest","body_part":"chest","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1256-DotAgEF.jpg","gif_url":"videos/1256-DotAgEF.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשכפות הרגליים מקובעות והראש נמוך מהאגן.","אחזו במוט באחיזה הפוכה, מעט רחבה מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו באיטיות לכיוון החזה, עם מרפקים צמודים לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, зафиксировав ноги и опустив голову ниже бедер.","Возьмите штангу обратным хватом, на расстоянии чуть шире ширины плеч.","Ослабьте штангу и медленно опустите ее к груди, держа локти прижатыми.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Agarra la barra con un agarre invertido, un poco más ancho que la separación de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1257","name":"barbell reverse grip incline bench press","category":"chest","body_part":"chest","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1257-DU7I633.jpg","gif_url":"videos/1257-DU7I633.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שכבו על הספסל עם כפות רגליים על הרצפה.","אחזו במוט באחיזה הפוכה, ידיים מעט רחבות מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו באיטיות לכיוון החזה, עם מרפקים צמודים לגוף.","עצרו לרגע כשהמוט נוגע בחזה.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте на скамью, положив ноги на землю.","Возьмите штангу обратным хватом, руки чуть шире плеч.","Ослабьте штангу и медленно опустите ее к груди, держа локти прижатыми.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate en el banco con los pies planos sobre el suelo.","Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1317","name":"barbell reverse grip incline bench row","category":"back","body_part":"back","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1317-8d8qJQI.jpg","gif_url":"videos/1317-8d8qJQI.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שבו על הספסל מול המשענת כשהחזה צמוד אליה.","אחזו במוט באחיזה הפוכה (כפות ידיים כלפי מטה) וידיים מעט רחבות מרוחב הכתפיים.","שמרו על גב ישר וליבה מופעלת.","משכו את המוט לכיוון הבטן העליונה, תוך כיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה.","הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench facing the backrest with your chest against it.","Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Сядьте на скамью лицом к спинке, прижавшись к ней грудью.","Возьмите штангу обратным хватом (ладонями вниз) и расставьте руки чуть шире плеч.","Держите спину прямо и напрягите корпус.","Потяните штангу к верхней части живота, сжимая лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения.","Медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco frente al respaldo con el pecho apoyado contra él.","Sujeta la barra con un agarre invertido (palmas hacia abajo) y las manos un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y el core activado.","Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento.","Baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1721","name":"barbell reverse grip skullcrusher","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/1721-yRLPCLu.jpg","gif_url":"videos/1721-yRLPCLu.gif","instruction_steps":{"he":["שכבו על ספסל עם כפות רגליים על הרצפה והראש בקצה הספסל.","החזיקו את המוט באחיזה הפוכה, כפות ידיים פונות לפנים שלכם, וידיים ברוחב כתפיים.","מתחו את הידיים ישר מעל החזה, עם מרפקים פנימה ושורשי כף יד ישרים.","הורידו באיטיות את המוט לכיוון המצח בכיפוף מרפקים, תוך שמירה על זרועות עליונות ללא תזוזה.","עצרו לרגע בנקודה התחתונה, ואז יישרו את הידיים חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.","Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.","Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Держите штангу обратным хватом ладонями к лицу, руки на ширине плеч.","Вытяните руки прямо вверх над грудью, сохраняя локти и запястья прямыми.","Медленно опустите штангу ко лбу, сгибая локти, сохраняя плечи неподвижными.","Задержитесь на мгновение в нижней точке, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta la barra con un agarre invertido, palmas mirando hacia la cara, y las manos separadas a la altura de los hombros.","Extiende los brazos rectos por encima del pecho, manteniendo los codos hacia dentro y las muñecas rectas.","Baja lentamente la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos.","Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0081","name":"barbell reverse preacher curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0081-4LIG9xr.jpg","gif_url":"videos/0081-4LIG9xr.gif","instruction_steps":{"he":["שבו על ספסל פריצ'ר כשהחזה צמוד לכרית והידיים מתוחות ישר כלפי מטה, אוחזות במוט באחיזה עליונה.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המוט כלפי מעלה תוך כיווץ הבייספס.","המשיכו להרים את המוט עד שהבייספס מכווץ במלואו והוא בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.","Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью для проповедника, прижав грудь к подушке и вытянув руки вниз, держа штангу хватом сверху.","Удерживая плечи неподвижно, выдохните и поднимите штангу вверх, одновременно напрягая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco predicador con el pecho apoyado en el cojín y los brazos extendidos rectos hacia abajo, sujetando una barra con un agarre pronado.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia arriba mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0082","name":"barbell reverse wrist curl","category":"lower arms","body_part":"lower arms","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0082-LsZkfU6.jpg","gif_url":"videos/0082-LsZkfU6.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו מוט באחיזה עליונה, כפות ידיים כלפי מטה.","הניחו את האמות על הירכיים, כששורשי כף היד משתלשלים מעבר לקצה.","גלגלו באיטיות את שורשי כף היד כלפי מעלה, והביאו את המוט לכיוון הגוף.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите штангу хватом сверху ладонями вниз.","Положите предплечья на бедра, позволяя запястьям свисать с края.","Медленно поднимите запястья вверх, приближая штангу к телу.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre pronado, con las palmas hacia abajo.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0084","name":"barbell rollerout","category":"waist","body_part":"waist","equipment":"barbell","muscle_group":"lower back","secondary_muscles":["lower back"],"target":"abs","image":"images/0084-7M66AVi.jpg","gif_url":"videos/0084-7M66AVi.gif","instruction_steps":{"he":["כרעו על הרצפה והחזיקו מוט בשתי ידיים, ברוחב כתפיים.","גלגלו את המוט קדימה, במתיחת הידיים ושמירה על ליבה מופעלת.","המשיכו להתגלגל קדימה עד שהגוף מתוח לגמרי והידיים מעל הראש.","עצרו לרגע, ואז גלגלו באיטיות את המוט חזרה לכיוון הברכיים, תוך שמירה על שליטה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Kneel on the floor and hold a barbell with both hands, shoulder-width apart.","Roll the barbell forward, extending your arms and keeping your core engaged.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.","Repeat for the desired number of repetitions."],"ru":["Встаньте на колени и возьмите штангу обеими руками на ширине плеч.","Перекатите штангу вперед, вытягивая руки и сохраняя корпус напряженным.","Продолжайте перекатываться вперед до тех пор, пока ваше тело не будет полностью выпрямлено, а руки не окажутся над головой.","Сделайте паузу на мгновение, затем медленно перекатите штангу обратно к коленям, сохраняя контроль.","Повторите необходимое количество повторений."],"es":["Ponte de rodillas en el suelo y sujeta una barra con ambas manos, separadas a la altura de los hombros.","Haz rodar la barra hacia delante, extendiendo los brazos y manteniendo el core activado.","Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.","Haz una pausa breve y luego haz rodar lentamente la barra de vuelta hacia las rodillas, manteniendo el control.","Repite el número de repeticiones deseado."]}},{"id":"0083","name":"barbell rollerout from bench","category":"waist","body_part":"waist","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"abs","image":"images/0083-Gxg9lDc.jpg","gif_url":"videos/0083-Gxg9lDc.gif","instruction_steps":{"he":["התחילו בכריעה על הרצפה עם מוט מונח על ספסל לפניכם.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","תוך שמירה על ליבה מופעלת וגב ישר, גלגלו באיטיות את המוט קדימה, במתיחת הידיים לפניכם.","המשיכו לגלגל את המוט קדימה עד שהגוף מתוח לגמרי והידיים מעל הראש.","עצרו לרגע במתיחה המלאה, ואז גלגלו באיטיות את המוט חזרה לכיוון הגוף, לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by kneeling on the floor with a barbell placed on a bench in front of you.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.","Continue rolling the barbell forward until your body is fully extended and your arms are overhead.","Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встанете на колени на пол, положив штангу на скамью перед собой.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Удерживая корпус напряженным и спину прямой, медленно перекатывайте штангу вперед, вытягивая руки перед собой.","Продолжайте перекатывать штангу вперед до тех пор, пока ваше тело не будет полностью выпрямлено, а руки не окажутся над головой.","Задержитесь на мгновение в полностью выпрямленном положении, затем медленно перекатите штангу обратно к телу, возвращаясь в исходное положение.","Повторите необходимое количество повторений."],"es":["Empieza de rodillas en el suelo con una barra colocada sobre un banco frente a ti.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Manteniendo el core activado y la espalda recta, haz rodar lentamente la barra hacia delante, extendiendo los brazos frente a ti.","Continúa haciendo rodar la barra hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.","Haz una pausa breve en la posición de extensión total, luego haz rodar lentamente la barra de vuelta hacia el cuerpo, volviendo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0085","name":"barbell romanian deadlift","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0085-wQ2c4XD.jpg","gif_url":"videos/0085-wQ2c4XD.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וכפות רגליים פונות קדימה.","אחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וברכיים כפופות מעט.","הורידו את המוט לכיוון הרצפה, כשהוא צמוד לגוף.","הרגישו את המתיחה בשרירי הירך האחורית תוך כדי הירידה.","כשאתם מרגישים מתיחה בירך האחורית, דחפו את האגן קדימה וחזרו לעמידה זקופה.","כווצו את הישבן בנקודה העליונה של התנועה.","הורידו את המוט חזרה לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at the hips, keeping your back straight and your knees slightly bent.","Lower the barbell towards the ground, keeping it close to your body.","Feel the stretch in your hamstrings as you lower the barbell.","Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.","Squeeze your glutes at the top of the movement.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, носки ног направлены вперед.","Возьмите штангу хватом сверху, руки чуть шире плеч.","Согните бедра, сохраняя спину прямой и слегка согнутыми в коленях.","Опустите штангу к земле, держа ее близко к телу.","Почувствуйте растяжение подколенных сухожилий, когда опускаете штангу.","Как только вы почувствуете растяжение подколенных сухожилий, выдвиньте бедра вперед и встаньте прямо.","Напрягите ягодицы в верхней точке движения.","Опустите штангу обратно в исходное положение и повторите желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante.","Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.","Flexiona las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Baja la barra hacia el suelo, manteniéndola cerca del cuerpo.","Siente el estiramiento en los isquiotibiales mientras bajas la barra.","Cuando sientas el estiramiento en los isquiotibiales, empuja las caderas hacia delante y ponte de pie.","Aprieta los glúteos en la parte alta del movimiento.","Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"0086","name":"barbell seated behind head military press","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0086-ngPpyRS.jpg","gif_url":"videos/0086-ngPpyRS.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו את המוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט מהמתקן והורידו אותו לגובה הכתפיים, מאחורי הראש.","לחצו את המוט כלפי מעלה עד יישור מלא של הידיים.","הורידו את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, behind your head.","Press the barbell upward until your arms are fully extended.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Снимите штангу со стойки и опустите ее на уровень плеч за голову.","Нажмите штангу вверх, пока руки полностью не выпрямятся.","Опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y bájala a la altura de los hombros, detrás de la cabeza.","Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos.","Baja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0087","name":"barbell seated bradford rocky press","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0087-0dCyly0.jpg","gif_url":"videos/0087-0dCyly0.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו את המוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט לגובה הכתפיים, עם מרפקים כפופים מעט ופונים קדימה.","לחצו את המוט מעל הראש, עד יישור מלא של הידיים.","הורידו את המוט חזרה לגובה הכתפיים וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.","Press the barbell overhead, fully extending your arms.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Поднимите штангу на высоту плеч, держа локти слегка согнутыми и направленными вперед.","Жмите штангу над головой, полностью выпрямляя руки.","Опустите штангу обратно на высоту плеч и повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.","Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y apuntando hacia delante.","Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.","Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado."]}},{"id":"0088","name":"barbell seated calf raise","category":"lower legs","body_part":"lower legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/0088-ktsFQAZ.jpg","gif_url":"videos/0088-ktsFQAZ.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה ומוט מונח על הירכיים.","הניחו את כריות כפות הרגליים על משטח מוגבה, כמו בלוק או מדרגה.","מקמו את המוט על הירכיים ואחזו בו היטב עם הידיים.","תוך שמירה על גב ישר וליבה מופעלת, הרימו את העקבים מהרצפה ביישור הקרסוליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Position the barbell across your thighs and hold it securely with your hands.","Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ступни на пол и положите штангу на бедра.","Поставьте подушечки стоп на приподнятую платформу, например, на блок или ступеньку.","Расположите штангу на бедрах и надежно удерживайте ее руками.","Удерживая спину прямой и напрягая корпус, поднимите пятки от земли, вытянув лодыжки.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre los muslos.","Coloca la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón.","Coloca la barra sobre los muslos y sujétala con firmeza con las manos.","Manteniendo la espalda recta y el core activado, levanta los talones del suelo extendiendo los tobillos.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1371","name":"barbell seated calf raise","category":"lower legs","body_part":"lower legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1371-ipvgBnC.jpg","gif_url":"videos/1371-ipvgBnC.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה ומוט מונח על הירכיים.","הניחו את כריות כפות הרגליים על משטח מוגבה, כמו בלוק או מדרגה.","הורידו את העקבים נמוך ככל האפשר, עד תחושת מתיחה בתאומים.","הרימו את העקבים גבוה ככל האפשר, בכיווץ התאומים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Lower your heels as far as possible, feeling a stretch in your calves.","Raise your heels as high as possible, contracting your calves.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ступни на пол и положите штангу на бедра.","Поставьте подушечки стоп на приподнятую платформу, например, на блок или ступеньку.","Опустите пятки как можно ниже, чувствуя растяжение в икрах.","Поднимите пятки как можно выше, напрягая икроножные мышцы.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre los muslos.","Coloca la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón.","Baja los talones tanto como sea posible, sintiendo un estiramiento en las pantorrillas.","Levanta los talones lo más alto posible, contrayendo las pantorrillas.","Repite el número de repeticiones deseado."]}},{"id":"1718","name":"barbell seated close grip behind neck triceps extension","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1718-4CBIBOM.jpg","gif_url":"videos/1718-4CBIBOM.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו את המוט באחיזה צרה מאחורי הצוואר, כפות ידיים פונות קדימה.","שמרו על מרפקים קרובים לראש והורידו באיטיות את המוט לכיוון העורף.","עצרו לרגע, ואז יישרו את הידיים חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with a close grip behind your neck, palms facing forward.","Keep your elbows close to your head and slowly lower the barbell towards the back of your head.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Держите штангу узким хватом за шеей ладонями вперед.","Держите локти близко к голове и медленно опустите штангу к затылку.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta la barra con un agarre cerrado detrás del cuello, con las palmas mirando hacia delante.","Mantén los codos cerca de la cabeza y baja lentamente la barra hacia la parte de atrás de la cabeza.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0089","name":"barbell seated close-grip concentration curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0089-1V1gj1u.jpg","gif_url":"videos/0089-1V1gj1u.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו מוט באחיזה תחתונה, ידיים ברוחב כתפיים.","השעינו את הזרועות העליונות על הירכיים הפנימיות, מעט מעל הברכיים, ותנו למוט להשתלשל לפניכם.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המוט למעלה לכיוון הכתפיים, בכיווץ הבייספס.","החזיקו את הכיווץ לרגע קצר, ואז שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на пол и возьмите штангу обратным хватом, руки на ширине плеч.","Положите плечи на внутреннюю поверхность бедер, чуть выше колен, и позвольте штанге свисать перед вами.","Удерживая плечи неподвижно, выдохните и поднимите штангу к плечам, напрягая бицепсы.","Удерживайте сокращенное положение на короткую паузу, затем вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, manos separadas a la altura de los hombros.","Apoya los brazos superiores contra el interior de los muslos, justo por encima de las rodillas, y deja que la barra cuelgue frente a ti.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros, contrayendo los bíceps.","Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0090","name":"barbell seated good morning","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0090-d960PgE.jpg","gif_url":"videos/0090-d960PgE.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה ומוט מונח על הגב העליון.","שמרו על גב ישר וחזה מורם.","הטו באיטיות את הגו קדימה מהירכיים, בהורדתו לכיוון הרצפה.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.","Keep your back straight and your chest up.","Slowly hinge forward at the hips, lowering your torso towards the ground.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставив ноги на землю, а штангу положите на верхнюю часть спины.","Держите спину прямо и грудь вверх.","Медленно наклонитесь вперед в бедрах, опуская туловище к земле.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre la parte superior de la espalda.","Mantén la espalda recta y el pecho elevado.","Inclínate lentamente hacia delante desde las caderas, bajando el torso hacia el suelo.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0091","name":"barbell seated overhead press","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0091-kTbSH9h.jpg","gif_url":"videos/0091-kTbSH9h.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו את המוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט מהמתקן והביאו אותו לגובה הכתפיים, עם מרפקים כפופים וכפות ידיים פונות קדימה.","לחצו את המוט מעל הראש ביישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.","Press the barbell overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder level.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Снимите штангу со стойки и поднимите ее на уровень плеч, согнув локти и повернув ладони вперед.","Выжмите штангу над головой, полностью выпрямив руки.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно на уровень плеч.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y llévala a la altura de los hombros, con los codos flexionados y las palmas hacia delante.","Empuja la barra por encima de la cabeza extendiendo completamente los brazos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"0092","name":"barbell seated overhead triceps extension","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0092-5uFK1xr.jpg","gif_url":"videos/0092-5uFK1xr.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו מוט באחיזה עליונה, ידיים ברוחב כתפיים, והרימו אותו מעל הראש.","הורידו את המוט מאחורי הראש בכיפוף מרפקים, תוך שמירה על הזרועות העליונות קרובות לראש.","עצרו לרגע, ואז יישרו את הידיים להרמת המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.","Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.","Pause for a moment, then extend your arms to raise the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите штангу хватом сверху, руки на ширине плеч, и поднимите ее над головой.","Опустите штангу за голову, согнув локти и держа плечи близко к голове.","Сделайте паузу на мгновение, затем вытяните руки и поднимите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y levántala por encima de la cabeza.","Baja la barra detrás de la cabeza flexionando los codos, manteniendo los brazos superiores cerca de la cabeza.","Haz una pausa breve y luego extiende los brazos para levantar la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0094","name":"barbell seated twist","category":"waist","body_part":"waist","equipment":"barbell","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0094-dFSNDOA.jpg","gif_url":"videos/0094-dFSNDOA.gif","instruction_steps":{"he":["שבו על ספסל ישר עם כפות רגליים על הרצפה וברכיים כפופות.","החזיקו מוט בשתי ידיים מול החזה, תוך שמירה על מרפקים כפופים מעט.","הפעילו את הליבה וסובבו באיטיות את הגו לצד אחד, תוך שמירה על גב ישר.","עצרו לרגע בסוף הסיבוב, ואז סובבו באיטיות חזרה לנקודת ההתחלה.","חזרו על הסיבוב לצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Sit on a flat bench with your feet flat on the ground and your knees bent.","Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.","Engage your core and slowly twist your torso to one side, keeping your back straight.","Pause for a moment at the end of the twist, then slowly rotate back to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Сядьте на плоскую скамью, поставьте ступни на землю и согните колени.","Держите штангу обеими руками перед грудью, слегка согнув локти.","Напрягите корпус и медленно поверните туловище в сторону, сохраняя спину прямой.","Сделайте паузу на мгновение в конце поворота, затем медленно поверните обратно в исходное положение.","Повторите поворот в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Siéntate en un banco plano con los pies planos sobre el suelo y las rodillas flexionadas.","Sujeta una barra con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados.","Activa el core y gira lentamente el torso hacia un lado, manteniendo la espalda recta.","Haz una pausa breve al final del giro y luego rota lentamente de vuelta a la posición inicial.","Repite el giro hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0095","name":"barbell shrug","category":"back","body_part":"back","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0095-dG7tG5y.jpg","gif_url":"videos/0095-dG7tG5y.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט לפניכם באחיזה עליונה.","שמרו על ידיים ישרות וגב ישר לאורך כל התרגיל.","הרימו את הכתפיים למעלה לכיוון האוזניים גבוה ככל האפשר, בכיווץ הטרפז בנקודה העליונה.","החזיקו לרגע, ואז הורידו את הכתפיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip.","Keep your arms straight and your back straight throughout the exercise.","Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, и держите штангу перед собой хватом сверху.","На протяжении всего упражнения держите руки прямыми и спину прямой.","Поднимите плечи к ушам как можно выше, сжимая трапеции вверху.","Задержитесь на мгновение, затем медленно опустите плечи обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a ti con un agarre pronado.","Mantén los brazos rectos y la espalda recta durante todo el ejercicio.","Levanta los hombros hacia las orejas lo más alto posible, apretando los trapecios en la parte alta.","Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0096","name":"barbell side bent v. 2","category":"waist","body_part":"waist","equipment":"barbell","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0096-i4JkUaL.jpg","gif_url":"videos/0096-i4JkUaL.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט בשתי ידיים, כפות ידיים כלפי מטה.","שמרו על גב ישר וליבה מופעלת לאורך כל התרגיל.","הטו באיטיות את הגו לצד ימין, בהורדת המוט לכיוון ברך ימין.","עצרו לרגע, ואז חזרו לנקודת ההתחלה.","חזרו על התנועה בצד שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Slowly bend your torso to the right side, lowering the barbell towards your right knee.","Pause for a moment, then return to the starting position.","Repeat the movement on the left side.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу обеими руками ладонями вниз.","На протяжении всего упражнения держите спину прямой и напряженным корпус.","Медленно наклоните туловище в правую сторону, опуская штангу к правому колену.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите движение с левой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con ambas manos, con las palmas hacia abajo.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Inclina lentamente el torso hacia el lado derecho, bajando la barra hacia tu rodilla derecha.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite el movimiento hacia el lado izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0098","name":"barbell side split squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0098-W31mMjd.jpg","gif_url":"videos/0098-W31mMjd.gif","instruction_steps":{"he":["עמדו עם רגליים רחבות מרוחב הכתפיים, כפות רגליים פונות מעט החוצה.","החזיקו מוט על הגב העליון, מונח על שרירי הטרפז.","הפעילו את הליבה ושמרו על חזה מורם תוך הורדת הגוף לעמדת סקוואט, בכיפוף ברכיים וירכיים.","תוך כדי הירידה, דחפו את הברכיים החוצה לצדדים ושמרו על המשקל בעקבים.","רדו עד שהירכיים מקבילות לרצפה, ואז דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a barbell across your upper back, resting it on your traps.","Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.","As you lower, push your knees out to the sides and keep your weight on your heels.","Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги шире плеч, носки слегка направлены наружу.","Держите штангу на верхней части спины, положив ее на трапеции.","Напрягите корпус и держите грудь поднятой, опуская тело в присед, сгибая колени и бедра.","Опускаясь, разведите колени в стороны и перенесите вес тела на пятки.","Опускайтесь до тех пор, пока бедра не станут параллельны земле, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.","Sujeta una barra sobre la parte superior de la espalda, apoyándola en los trapecios.","Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, flexionando las rodillas y las caderas.","Al bajar, empuja las rodillas hacia los lados y mantén el peso sobre los talones.","Baja hasta que los muslos queden paralelos al suelo, luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0097","name":"barbell side split squat v. 2","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0097-HUEqZ1y.jpg","gif_url":"videos/0097-HUEqZ1y.gif","instruction_steps":{"he":["עמדו עם רגליים רחבות מרוחב הכתפיים, קצות האצבעות פונות מעט החוצה.","הניחו מוט על הגב העליון, מונח על הכתפיים.","צעדו צעד גדול הצידה עם כף רגל ימין, תוך שמירה על כף רגל שמאל נטועה במקומה.","כופפו את ברך ימין והורידו את הגוף לעמדת סקוואט, תוך שמירה על חזה מורם וגב ישר.","דחפו דרך עקב ימין כדי לחזור לנקודת ההתחלה.","חזרו על התנועה בצד השני, בצעד הצידה עם כף רגל שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.","Hold a barbell across your upper back, resting it on your shoulders.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.","Push through your right heel to return to the starting position.","Repeat on the other side, stepping out with your left foot.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, поставив ноги шире плеч, носки слегка направлены наружу.","Держите штангу через верхнюю часть спины, положив ее на плечи.","Сделайте большой шаг в сторону правой ногой, удерживая левую ногу на месте.","Согните правое колено и опустите тело в положение приседа, удерживая грудь поднятой, а спину прямой.","Оттолкнитесь правой пяткой, чтобы вернуться в исходное положение.","Повторите то же самое с другой стороны, выставив левую ногу.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.","Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros.","Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo.","Flexiona la rodilla derecha y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y la espalda recta.","Empuja con el talón derecho para regresar a la posición inicial.","Repite hacia el otro lado, dando el paso con el pie izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1756","name":"barbell single leg deadlift","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1756-gEyURal.jpg","gif_url":"videos/1756-gEyURal.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן, אוחזים מוט מול הירכיים באחיזה עליונה.","העבירו את המשקל לכף רגל שמאל והרימו את כף רגל ימין מעט מהרצפה.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר ורגל ימין מתוחה לאחור לשיווי משקל.","הורידו את המוט לכיוון הרצפה, כשהוא צמוד לגוף ורגל שמאל כפופה מעט.","עצרו לרגע בנקודה התחתונה, ואז הפעילו את הישבן והירך האחורית להרמת הגו חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.","Shift your weight onto your left foot and lift your right foot slightly off the ground.","Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.","Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, удерживая штангу перед бедрами хватом сверху.","Перенесите вес тела на левую ногу и слегка поднимите правую ногу от земли.","Наклонитесь вперед в бедрах, сохраняя спину прямой и вытянув правую ногу позади себя для равновесия.","Опустите штангу к земле, держа ее близко к телу и слегка согнув левую ногу.","Задержитесь на мгновение в нижней точке, затем задействуйте ягодицы и мышцы задней поверхности бедра, чтобы поднять туловище обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de las caderas, sujetando una barra frente a los muslos con agarre prono.","Traslada el peso hacia el pie izquierdo y levanta el pie derecho ligeramente del suelo.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la pierna derecha extendida detrás de ti para el equilibrio.","Baja la barra hacia el suelo, manteniéndola cerca del cuerpo y la pierna izquierda ligeramente flexionada.","Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0099","name":"barbell single leg split squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0099-gGNQmVt.jpg","gif_url":"videos/0099-gGNQmVt.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים מוט על הגב העליון.","צעדו צעד גדול קדימה עם רגל אחת, תוך שמירה על גו זקוף.","הורידו את הגוף בכיפוף הברך והירך הקדמיות, תוך שמירה על הרגל האחורית ישרה.","המשיכו לרדת עד שהירך הקדמית מקבילה לרצפה.","עצרו לרגע, ואז דחפו דרך העקב הקדמי לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with one leg, keeping your torso upright.","Lower your body by bending your front knee and hip, while keeping your back leg straight.","Continue lowering until your front thigh is parallel to the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Встаньте, ноги на ширине плеч, удерживая штангу на верхней части спины.","Сделайте большой шаг вперед одной ногой, сохраняя туловище в вертикальном положении.","Опустите тело, согнув переднее колено и бедро, сохраняя при этом заднюю ногу прямой.","Продолжайте опускаться до тех пор, пока переднее бедро не станет параллельно земле.","Сделайте паузу на мгновение, затем оттолкнитесь передней пяткой, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.","Da un paso grande hacia adelante con una pierna, manteniendo el torso erguido.","Baja el cuerpo flexionando la rodilla delantera y la cadera, mientras mantienes la pierna trasera recta.","Continúa bajando hasta que el muslo delantero quede paralelo al suelo.","Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"2799","name":"barbell sitted alternate leg raise","category":"waist","body_part":"waist","equipment":"barbell","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/2799-G7xoEzr.jpg","gif_url":"videos/2799-G7xoEzr.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר והחזיקו מוט על הירכיים.","תוך שמירה על רגליים ישרות, הרימו רגל אחת גבוה ככל האפשר, כשהרגל השנייה נשארת על הרצפה.","הורידו את הרגל המורמת חזרה וחזרו על התנועה עם הרגל השנייה.","המשיכו להחליף רגליים למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and hold a barbell across your thighs.","Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.","Lower the raised leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."],"ru":["Сядьте на скамью с прямой спиной и держите штангу на бедрах.","Держа ноги прямыми, поднимите одну ногу как можно выше, удерживая другую ногу на земле.","Опустите поднятую ногу обратно вниз и повторите то же самое с другой ногой.","Продолжайте чередовать ноги желаемое количество повторений."],"es":["Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos.","Manteniendo las piernas rectas, levanta una pierna lo más alto posible mientras mantienes la otra pierna en el suelo.","Baja la pierna elevada y repite con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."]}},{"id":"2800","name":"barbell sitted alternate leg raise (female)","category":"waist","body_part":"waist","equipment":"barbell","muscle_group":"hip flexors","secondary_muscles":["hip flexors","quadriceps"],"target":"abs","image":"images/2800-BCs0G2F.jpg","gif_url":"videos/2800-BCs0G2F.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר והחזיקו מוט על הירכיים.","הניחו את הידיים על צידי הספסל לתמיכה.","תוך שמירה על רגליים ישרות, הרימו רגל אחת גבוה ככל האפשר, כשהיא מקבילה לרצפה.","הורידו את הרגל חזרה וחזרו על התנועה עם הרגל השנייה.","המשיכו להחליף רגליים למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and hold a barbell across your thighs.","Place your hands on the sides of the bench for support.","Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.","Lower the leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."],"ru":["Сядьте на скамью с прямой спиной и держите штангу на бедрах.","Положите руки по бокам скамьи для поддержки.","Держа ноги прямыми, поднимите одну ногу как можно выше, удерживая ее параллельно земле.","Опустите ногу обратно и повторите то же самое с другой ногой.","Продолжайте чередовать ноги желаемое количество повторений."],"es":["Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos.","Coloca las manos a los lados del banco para apoyarte.","Manteniendo las piernas rectas, levanta una pierna lo más alto posible manteniéndola paralela al suelo.","Baja la pierna y repite con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."]}},{"id":"0100","name":"barbell skier","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0100-4Leypho.jpg","gif_url":"videos/0100-4Leypho.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט מול הירכיים באחיזה עליונה.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וחזה מורם.","הרימו את המוט לכיוון הכתפיים ובו-זמנית קפצו קלות מהרצפה.","בהגיעכם לנקודה העליונה של התנועה, הפכו במהירות את הכיוון והורידו את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.","As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, удерживайте штангу перед бедрами хватом сверху.","Слегка согните колени и наклонитесь вперед в бедрах, держа спину прямо и грудь вверх.","Одновременно поднимите штангу к плечам, слегка подпрыгнув от земли.","Достигнув верхней точки движения, быстро поменяйте направление движения и опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Levanta simultáneamente la barra hacia los hombros mientras saltas ligeramente del suelo.","Al llegar a la parte más alta del movimiento, invierte rápidamente el movimiento y baja la barra de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0101","name":"barbell speed squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0101-euI1BwR.jpg","gif_url":"videos/0101-euI1BwR.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, כפות הרגליים פונות מעט החוצה.","הניחו את המוט על הגב העליון, על שרירי הטרפז או הדלתא האחורית.","הפעילו את הליבה ושמרו על חזה מורם תוך הורדת האגן לאחור ולמטה, כאילו אתם מתיישבים על כיסא.","רדו עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","דחפו דרך העקבים כדי לחזור לעמידה, וכווצו את הישבן בנקודה העליונה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Держите штангу на верхней части спины, опираясь на трапеции или задние дельты.","Напрягите корпус и держите грудь поднятой, опуская бедра назад и вниз, как будто вы садитесь на стул.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Протолкните пятки, чтобы встать, сжимая ягодицы вверху.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras llevas las caderas hacia atrás y hacia abajo, como si te sentaras en una silla.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta.","Repite el número de repeticiones deseado."]}},{"id":"2810","name":"barbell split squat v. 2","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/2810-HBYyX94.jpg","gif_url":"videos/2810-HBYyX94.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים, אוחזים מוט על הגב העליון.","צעדו צעד גדול קדימה עם רגל ימין, תוך שמירה על גו זקוף.","הורידו את הגוף בכיפוף ברכיים וירכיים עד שירך ימין מקבילה לרצפה.","עצרו לרגע, ואז דחפו דרך עקב ימין לחזרה לנקודת ההתחלה.","חזרו על התרגיל עם רגל שמאל קדימה למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with your right foot, keeping your torso upright.","Lower your body by bending your knees and hips until your right thigh is parallel to the ground.","Pause for a moment, then push through your right heel to return to the starting position.","Repeat with your left leg forward for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч, удерживая штангу на верхней части спины.","Сделайте большой шаг вперед правой ногой, сохраняя туловище в вертикальном положении.","Опустите тело, сгибая колени и бедра, пока правое бедро не станет параллельно земле.","Сделайте паузу на мгновение, затем оттолкнитесь правой пяткой, чтобы вернуться в исходное положение.","Повторите, выставив левую ногу вперед, необходимое количество повторений."],"es":["Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.","Da un paso grande hacia adelante con el pie derecho, manteniendo el torso erguido.","Baja el cuerpo flexionando las rodillas y las caderas hasta que el muslo derecho quede paralelo al suelo.","Haz una pausa breve, luego empuja con el talón derecho para volver a la posición inicial.","Repite con la pierna izquierda adelante el número de repeticiones deseado."]}},{"id":"0102","name":"barbell squat (on knees)","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0102-oR7O9LW.jpg","gif_url":"videos/0102-oR7O9LW.gif","instruction_steps":{"he":["התחילו בכריעה על הרצפה, ברכיים ברוחב אגן וקצות האצבעות של הרגליים פונים קדימה.","הניחו מוט על הכתפיים, אחזו בו באחיזה עליונה עם ידיים מעט רחבות מרוחב הכתפיים.","הפעילו את הליבה ושמרו על חזה מורם תוך הורדת הגוף באיטיות בכיפוף ברכיים, עם גב ישר.","המשיכו לרדת עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.","Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.","Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте на колени на землю, расставив колени на ширине бедер и направив пальцы ног вперед.","Положите штангу на плечи, возьмите ее хватом сверху и расставьте руки чуть шире плеч.","Напрягите корпус и держите грудь поднятой, медленно опуская тело вниз, сгибая колени, сохраняя спину прямой.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza arrodillado en el suelo con las rodillas separadas a la altura de las caderas y las puntas de los pies apuntando hacia adelante.","Coloca una barra sobre los hombros, sujetándola con agarre prono y las manos un poco más separadas que el ancho de los hombros.","Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas, manteniendo la espalda recta.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2798","name":"barbell squat jump step rear lunge","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/2798-RYcV1kH.jpg","gif_url":"videos/2798-RYcV1kH.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים, אוחזים מוט על הגב העליון.","רדו לסקוואט בכיפוף ברכיים ודחיפת האגן לאחור.","התפרצו כלפי מעלה, בקפיצה מהרצפה גבוה ככל האפשר.","נחתו ברכות על כפות הרגליים וצעדו מיד לאחור עם רגל אחת למספריים לאחור.","הורידו את הגוף עד שהירך הקדמית מקבילה לרצפה, תוך שמירה על גב ישר.","דחפו דרך העקב הקדמי לחזרה לנקודת ההתחלה.","חזרו על רצף הקפיצה והמספריים ברגל השנייה.","המשיכו להחליף רגליים למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Explode upwards, jumping off the ground as high as you can.","Land softly on your feet and immediately step back with one leg into a reverse lunge.","Lower your body down until your front thigh is parallel to the ground, keeping your back straight.","Push through your front heel to return to the starting position.","Repeat the jump and lunge sequence on the other leg.","Continue alternating legs for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч, удерживая штангу на верхней части спины.","Опустите тело в присед, согнув колени и отведя бедра назад.","Взрывайтесь вверх, отпрыгивая от земли как можно выше.","Мягко приземлитесь на ноги и сразу же сделайте шаг назад одной ногой в обратный выпад.","Опускайте тело вниз, пока переднее бедро не станет параллельно земле, сохраняя спину прямой.","Оттолкнитесь передней пяткой, чтобы вернуться в исходное положение.","Повторите последовательность прыжков и выпадов на другую ногу.","Продолжайте чередовать ноги желаемое количество повторений."],"es":["Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Impúlsate explosivamente hacia arriba, saltando del suelo lo más alto que puedas.","Aterriza suavemente sobre los pies y de inmediato retrocede con una pierna hacia una zancada inversa.","Baja el cuerpo hasta que el muslo delantero quede paralelo al suelo, manteniendo la espalda recta.","Empuja con el talón delantero para volver a la posición inicial.","Repite la secuencia de salto y zancada con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."]}},{"id":"0103","name":"barbell standing ab rollerout","category":"waist","body_part":"waist","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders","lower back"],"target":"abs","image":"images/0103-xnInPfE.jpg","gif_url":"videos/0103-xnInPfE.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו את המוט בשתי ידיים מול הירכיים.","הפעילו את הליבה וגלגלו באיטיות את המוט מטה לכיוון הרצפה, תוך שמירה על גב ישר וידיים מתוחות.","המשיכו לגלגל את המוט קדימה עד שהגוף מתוח לגמרי והידיים ישר מעל הראש.","עצרו לרגע, ואז גלגלו באיטיות את המוט חזרה לכיוון הירכיים, תוך שמירה על שליטה וליבה מופעלת.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.","Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.","Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.","Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч и держите штангу обеими руками перед бедрами.","Напрягите корпус и медленно катите штангу вниз к земле, держа спину прямо и руки вытянутыми.","Продолжайте катить штангу вперед до тех пор, пока ваше тело не будет полностью выпрямлено, а руки не окажутся прямо над головой.","Сделайте паузу на мгновение, затем медленно перекатите штангу обратно к бедрам, сохраняя контроль и напрягая корпус.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente a los muslos.","Activa el core y enrolla lentamente la barra hacia el suelo, manteniendo la espalda recta y los brazos extendidos.","Continúa enrollando la barra hacia adelante hasta que el cuerpo esté completamente extendido y las manos queden justo sobre la cabeza.","Haz una pausa breve, luego enrolla lentamente la barra de vuelta hacia los muslos, manteniendo el control y el core activado.","Repite el número de repeticiones deseado."]}},{"id":"0104","name":"barbell standing back wrist curl","category":"lower arms","body_part":"lower arms","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/0104-2qTvJAZ.jpg","gif_url":"videos/0104-2qTvJAZ.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה עליונה.","הניחו את המוט על גב כפות הידיים, כפות ידיים כלפי מטה ואצבעות פונות לגוף.","תוך שמירה על הזרועות העליונות במקומן, נשפו וגלגלו את שורשי כף היד כלפי מעלה עד הסוף.","החזיקו בנקודת הכיווץ לרגע קצר, ואז שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.","Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.","Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу хватом сверху.","Положите штангу на тыльную сторону рук ладонями вниз и пальцами к телу.","Удерживая плечи неподвижно, выдохните и согните запястья вверх как можно дальше.","Удерживайте сокращенное положение на короткую паузу, затем вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono.","Apoya la barra sobre el dorso de las manos con las palmas hacia abajo y los dedos apuntando hacia el cuerpo.","Manteniendo los brazos superiores quietos, exhala y flexiona las muñecas hacia arriba lo más posible.","Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0105","name":"barbell standing bradford press","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0105-dCPESfR.jpg","gif_url":"videos/0105-dCPESfR.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את המוט מול הכתפיים באחיזה עליונה.","לחצו את המוט מעל הראש, עד יישור מלא של הידיים.","הורידו את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip.","Press the barbell overhead, fully extending your arms.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, и держите штангу перед плечами хватом сверху.","Жмите штангу над головой, полностью выпрямляя руки.","Опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra frente a los hombros con agarre prono.","Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.","Baja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1372","name":"barbell standing calf raise","category":"lower legs","body_part":"lower legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1372-8ozhUIZ.jpg","gif_url":"videos/1372-8ozhUIZ.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והניחו מוט על הגב העליון.","הרימו את העקבים מהרצפה גבוה ככל האפשר, בעזרת קצות האצבעות בלבד.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and place a barbell across your upper back.","Raise your heels off the ground as high as possible, using only your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, положите штангу на верхнюю часть спины.","Поднимите пятки от земли как можно выше, используя только пальцы ног.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda.","Levanta los talones del suelo lo más alto posible, apoyándote solo en las puntas de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0106","name":"barbell standing close grip curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0106-4dUn2iv.jpg","gif_url":"videos/0106-4dUn2iv.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה תחתונה, ידיים קרובות זו לזו.","שמרו על מרפקים צמודים לגו וזרועות עליונות ללא תזוזה לאורך כל התנועה.","נשפו וכופפו את המשקולות תוך כיווץ הבייספס. המשיכו להרים את המוט עד שהבייספס מכווץ במלואו והמוט בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להחזיר את המוט באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу обратным хватом, руки близко друг к другу.","Держите локти близко к туловищу, а плечи неподвижно на протяжении всего движения.","На выдохе сгибайте штангу и одновременно напрягайте бицепсы. Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","На вдохе начните медленно возвращать штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos juntas.","Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.","Exhala al flexionar el peso contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala mientras comienzas a llevar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1456","name":"barbell standing close grip military press","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/1456-wdRZISl.jpg","gif_url":"videos/1456-wdRZISl.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את המוט באחיזה עליונה, ידיים מעט קרובות מרוחב הכתפיים.","הרימו את המוט לגובה הכתפיים, תוך שמירה על מרפקים קרובים לגוף.","לחצו את המוט מעל הראש, עד יישור מלא של הידיים.","הורידו את המוט חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows close to your body.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, и возьмите штангу хватом сверху, руки чуть ближе ширины плеч.","Поднимите штангу на высоту плеч, держа локти близко к телу.","Выжмите штангу над головой, полностью выпрямив руки.","Опустите штангу обратно на высоту плеч.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, manos un poco más juntas que el ancho de los hombros.","Levanta la barra hasta la altura de los hombros, manteniendo los codos cerca del cuerpo.","Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.","Baja la barra de nuevo a la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"2414","name":"barbell standing concentration curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2414-vsMcDi9.jpg","gif_url":"videos/2414-vsMcDi9.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט ביד אחת, כף יד כלפי מעלה.","הניחו את היד הנגדית על הירך לתמיכה.","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את המשקל למעלה לכיוון הכתף.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את המשקל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.","Rest your opposite hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Встаньте, ноги на ширине плеч, возьмите в одну руку штангу ладонью вверх.","Положите противоположную руку на бедро для поддержки.","Удерживая плечо неподвижно, выдохните и поднимите вес к плечу.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите вес обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con una mano, con la palma hacia arriba.","Apoya la otra mano sobre el muslo para mayor estabilidad.","Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente el peso de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0107","name":"barbell standing front raise over head","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0107-S8mo30S.jpg","gif_url":"videos/0107-S8mo30S.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במוט מול הירכיים באחיזה עליונה.","שמרו על גב ישר והפעילו את שרירי הליבה.","הרימו את המוט באיטיות לפניכם, תוך שמירה על ידיים ישרות וכפות ידיים כלפי מטה.","המשיכו להרים עד שהמוט מעט מעל גובה הכתפיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.","Keep your back straight and engage your core.","Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.","Continue lifting until the barbell is slightly above shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, удерживая штангу перед бедрами хватом сверху.","Держите спину прямо и задействуйте корпус.","Медленно поднимите штангу перед собой, держа руки прямыми ладонями вниз.","Продолжайте поднимать штангу до тех пор, пока она не окажется немного выше уровня плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra frente a los muslos con agarre prono.","Mantén la espalda recta y activa el core.","Levanta lentamente la barra frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.","Continúa levantando hasta que la barra quede ligeramente por encima del nivel de los hombros.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0108","name":"barbell standing leg calf raise","category":"lower legs","body_part":"lower legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/0108-rGwhJ5o.jpg","gif_url":"videos/0108-rGwhJ5o.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והניחו מוט על הגב העליון.","הרימו את העקבים מהרצפה גבוה ככל האפשר, בעזרת שרירי התאומים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and place a barbell across your upper back.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, положите штангу на верхнюю часть спины.","Поднимите пятки от земли как можно выше, используя икроножные мышцы.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda.","Levanta los talones del suelo lo más alto posible, usando las pantorrillas.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0109","name":"barbell standing overhead triceps extension","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0109-dZl9Q27.jpg","gif_url":"videos/0109-dZl9Q27.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה עליונה.","הרימו את המוט מעל הראש, עד יישור מלא של הידיים.","תוך שמירה על הזרועות העליונות קרובות לראש, הורידו באיטיות את המוט מאחורי הראש בכיפוף המרפקים.","עצרו לרגע, ואז הרימו את המוט חזרה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу хватом сверху.","Поднимите штангу над головой, полностью выпрямив руки.","Держа плечи близко к голове, медленно опустите штангу за голову, сгибая локти.","Сделайте паузу на мгновение, затем поднимите штангу обратно в исходное положение, вытянув руки.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono.","Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.","Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos.","Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0110","name":"barbell standing reverse grip curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0110-LWuA3aZ.jpg","gif_url":"videos/0110-LWuA3aZ.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה תחתונה, כפות ידיים כלפי מעלה.","שמרו על מרפקים צמודים לגוף וזרועות עליונות ללא תזוזה.","נשפו וכופפו את המשקולות תוך כיווץ הבייספס, והביאו את המוט קרוב ככל האפשר לכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу обратным хватом ладонями вверх.","Держите локти близко к туловищу, а плечи неподвижны.","Выдохните и согните штангу, одновременно напрягая бицепсы и поднося штангу как можно ближе к плечам.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.","Mantén los codos cerca del torso y los brazos superiores quietos.","Exhala y flexiona el peso contrayendo los bíceps, llevando la barra lo más cerca posible de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0111","name":"barbell standing rocking leg calf raise","category":"lower legs","body_part":"lower legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/0111-6HiHHe0.jpg","gif_url":"videos/0111-6HiHHe0.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט על הגב העליון.","הרימו את העקבים מהרצפה גבוה ככל האפשר, תוך איזון על כריות כפות הרגליים.","הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Raise your heels off the ground as high as possible, balancing on the balls of your feet.","Slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите штангу на верхней части спины.","Поднимите пятки от земли как можно выше, балансируя на подушечках стоп.","Медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.","Levanta los talones del suelo lo más alto posible, manteniendo el equilibrio sobre las puntas de los pies.","Baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0112","name":"barbell standing twist","category":"waist","body_part":"waist","equipment":"barbell","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0112-yQe5HpE.jpg","gif_url":"videos/0112-yQe5HpE.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט מול החזה בשתי ידיים, כפות ידיים כלפי מטה.","הפעילו את הליבה ושמרו על גב ישר לאורך כל התרגיל.","סובבו באיטיות את הגו ימינה, בסיבוב על כפות הרגליים והאגן, תוך שמירה על פלג גוף תחתון יציב.","עצרו לרגע בסוף הסיבוב, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על הסיבוב לצד שמאל.","המשיכו להחליף סיבובים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.","Engage your core and keep your back straight throughout the exercise.","Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите штангу перед грудью обеими руками ладонями вниз.","Напрягите корпус и держите спину прямо на протяжении всего упражнения.","Медленно поверните туловище вправо, поворачиваясь на ступнях и бедрах, сохраняя при этом нижнюю часть тела устойчивой.","Сделайте небольшую паузу в конце поворота, затем медленно вернитесь в исходное положение.","Повторите поворот в левую сторону.","Продолжайте чередовать скручивания желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente al pecho con ambas manos, palmas hacia abajo.","Activa el core y mantén la espalda recta durante todo el ejercicio.","Gira lentamente el torso hacia la derecha, pivotando sobre los pies y las caderas, mientras mantienes estable la parte inferior del cuerpo.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite el giro hacia el lado izquierdo.","Continúa alternando los giros el número de repeticiones deseado."]}},{"id":"1629","name":"barbell standing wide grip biceps curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1629-faHKVkK.jpg","gif_url":"videos/1629-faHKVkK.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה תחתונה, ידיים רחבות מרוחב הכתפיים.","שמרו על גב ישר ומרפקים צמודים לגו.","נשפו וכופפו את המוט למעלה לכיוון הכתפיים, תוך שמירה על זרועות עליונות ללא תזוזה.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your back straight and your elbows close to your torso.","Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу обратным хватом, руки шире ширины плеч.","Держите спину прямо, а локти близко к туловищу.","Выдохните и поднимите штангу к плечам, сохраняя плечи неподвижными.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите штангу обратно в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos más separadas que el ancho de los hombros.","Mantén la espalda recta y los codos cerca del torso.","Exhala y flexiona la barra hacia los hombros, manteniendo los brazos superiores quietos.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1457","name":"barbell standing wide military press","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/1457-Kyd9Rz5.jpg","gif_url":"videos/1457-Kyd9Rz5.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את המוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט לגובה הכתפיים, כשהמרפקים מעט לפני המוט.","לחצו את המוט מעל הראש, עד יישור מלא של הידיים.","הורידו את המוט חזרה לגובה הכתפיים וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.","Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, и возьмите штангу хватом сверху, чуть шире ширины плеч.","Поднимите штангу на высоту плеч, держа локти немного впереди штанги.","Выжмите штангу над головой, полностью выпрямив руки.","Опустите штангу обратно на высоту плеч и повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente por delante de la barra.","Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.","Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado."]}},{"id":"0113","name":"barbell standing wide-grip curl","category":"upper arms","body_part":"upper arms","equipment":"barbell","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0113-NdIb5Z1.jpg","gif_url":"videos/0113-NdIb5Z1.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה עליונה, ידיים רחבות מרוחב הכתפיים.","תנו למוט להשתלשל בידיים ישרות מול הירכיים, עם כפות ידיים פונות מהגוף.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המוט כלפי מעלה בכיווץ הבייספס.","המשיכו להרים את המוט עד שהבייספס מכווץ במלואו והוא בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang at arm's length in front of your thighs, with your palms facing away from your body.","Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу хватом сверху, руки на ширине плеч.","Пусть штанга висит на расстоянии вытянутой руки перед бедрами, ладонями от тела.","Удерживая плечи неподвижно, выдохните и поднимите штангу вверх, напрягая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros.","Deja que la barra cuelgue a la longitud del brazo frente a los muslos, con las palmas mirando hacia afuera del cuerpo.","Manteniendo los brazos superiores quietos, exhala y flexiona la barra hacia arriba contrayendo los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0114","name":"barbell step-up","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0114-Kxquu2E.jpg","gif_url":"videos/0114-Kxquu2E.gif","instruction_steps":{"he":["עמדו מול ספסל או מדרגה עם מוט מונח על הגב העליון.","הניחו כף רגל אחת על הספסל או המדרגה, וודאו שכל כף הרגל נוגעת במשטח.","דחפו דרך העקב ועלו על הספסל או המדרגה, ביישור מלא של הירך והברך.","עצרו קצרות בנקודה העליונה, ואז הורידו את עצמכם חזרה לנקודת ההתחלה.","חזרו על התרגיל ברגל הנגדית.","המשיכו להחליף רגליים למספר החזרות הרצוי."],"en":["Stand in front of a bench or step with a barbell resting on your upper back.","Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your heel and step up onto the bench or step, fully extending your hip and knee.","Pause briefly at the top, then lower yourself back down to the starting position.","Repeat with the opposite leg.","Continue alternating legs for the desired number of repetitions."],"ru":["Встаньте перед скамьей или сделайте шаг, положив штангу на верхнюю часть спины.","Поставьте одну ногу на скамью или ступеньку так, чтобы вся стопа соприкасалась с поверхностью.","Надавите пяткой и встаньте на скамью или ступеньку, полностью выпрямляя бедро и колено.","Сделайте короткую паузу в верхней точке, затем опуститесь обратно в исходное положение.","Повторите с противоположной ногой.","Продолжайте чередовать ноги желаемое количество повторений."],"es":["Ponte de pie frente a un banco o escalón con una barra apoyada en la parte superior de la espalda.","Coloca un pie sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie.","Empuja con el talón y sube al banco o escalón, extendiendo completamente la cadera y la rodilla.","Haz una pausa breve en la parte más alta, luego baja de vuelta a la posición inicial.","Repite con la pierna contraria.","Continúa alternando las piernas durante el número de repeticiones deseado."]}},{"id":"0115","name":"barbell stiff leg good morning","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0115-JrOHAZc.jpg","gif_url":"videos/0115-JrOHAZc.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","החזיקו את המוט על הגב העליון, מונח על שרירי הטרפז.","תוך שמירה על גב ישר, הטו את הגו קדימה מהירכיים, בדחיפת הישבן לאחור.","הורידו את הגו עד שהוא מקביל לרצפה, עד תחושת מתיחה בירך האחורית.","הפעילו את הישבן והירך האחורית לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the barbell across your upper back, resting it on your traps.","Keeping your back straight, hinge forward at the hips, pushing your glutes back.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Держите штангу на верхней части спины, положив ее на трапеции.","Сохраняя спину прямой, наклонитесь вперед в бедрах, отводя ягодицы назад.","Опускайте туловище до тех пор, пока оно не станет параллельно земле, чувствуя растяжение подколенных сухожилий.","Задействуйте ягодицы и мышцы задней поверхности бедра, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios.","Manteniendo la espalda recta, inclínate hacia adelante desde las caderas, empujando los glúteos hacia atrás.","Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.","Activa los glúteos y los isquiotibiales para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0116","name":"barbell straight leg deadlift","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"glutes","secondary_muscles":["glutes","lower back"],"target":"hamstrings","image":"images/0116-hrVQWvE.jpg","gif_url":"videos/0116-hrVQWvE.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וכפות רגליים פונות קדימה.","אחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","הטו את הגו מהירכיים והורידו את המוט לכיוון הרצפה, תוך שמירה על גב ישר וברכיים כפופות מעט.","הורידו את המוט עד שתרגישו מתיחה בירך האחורית.","הפעילו את הירך האחורית והישבן כדי להרים את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.","Lower the barbell until you feel a stretch in your hamstrings.","Engage your hamstrings and glutes to lift the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, носки ног направлены вперед.","Возьмите штангу хватом сверху, руки чуть шире плеч.","Согните бедра и опустите штангу к земле, сохраняя спину прямой и слегка согнутыми в коленях.","Опускайте штангу до тех пор, пока не почувствуете растяжение подколенных сухожилий.","Задействуйте мышцы задней поверхности бедра и ягодицы, чтобы поднять штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante.","Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.","Flexiona las caderas y baja la barra hacia el suelo, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Baja la barra hasta que sientas un estiramiento en los isquiotibiales.","Activa los isquiotibiales y los glúteos para levantar la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0117","name":"barbell sumo deadlift","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"target":"glutes","image":"images/0117-KgI0tqW.jpg","gif_url":"videos/0117-KgI0tqW.gif","instruction_steps":{"he":["עמדו עם רגליים רחבות מרוחב הכתפיים, קצות האצבעות של הרגליים פונות החוצה.","הניחו מוט על הרצפה לפניכם, ממורכז בין כפות הרגליים.","כופפו ברכיים והורידו את האגן, תוך שמירה על גב ישר וחזה מורם, לאחיזת המוט באחיזה עליונה.","הפעילו את הליבה ודחפו דרך העקבים להרמת המוט מהרצפה, ביישור הירכיים והברכיים בו-זמנית.","תוך כדי ההרמה, שמרו על חזה מורם וגב ישר, ודחפו את האגן קדימה להפעלה מלאה של הישבן.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה, תוך שמירה על שליטה לאורך כל התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Place a barbell on the ground in front of you, centered between your feet.","Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.","Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.","As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."],"ru":["Встаньте, расставив ноги шире плеч, носки наружу.","Положите штангу на землю перед собой по центру между стопами.","Согните ноги в коленях и опустите бедра, держа спину прямо и грудь вверх, чтобы взять штангу хватом сверху.","Напрягите корпус и двигайтесь пятками, чтобы поднять штангу с земли, одновременно вытягивая бедра и колени.","Во время подъема держите грудь и спину прямо, а бедра выдвигайте вперед, чтобы полностью задействовать ягодицы.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение, сохраняя контроль на протяжении всего движения.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera.","Coloca una barra en el suelo frente a ti, centrada entre los pies.","Flexiona las rodillas y baja las caderas, manteniendo la espalda recta y el pecho elevado, para sujetar la barra con agarre prono.","Activa el core y empuja con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas simultáneamente.","Al levantar, mantén el pecho elevado y la espalda recta, y empuja las caderas hacia adelante para activar completamente los glúteos.","Haz una pausa breve en la parte más alta, luego baja lentamente la barra de vuelta a la posición inicial, manteniendo el control durante todo el movimiento.","Repite el número de repeticiones deseado."]}},{"id":"3305","name":"barbell thruster","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","glutes","hamstrings","core"],"target":"delts","image":"images/3305-f7Y9eDZ.jpg","gif_url":"videos/3305-f7Y9eDZ.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים, אוחזים מוט בגובה הכתפיים באחיזה עליונה.","רדו לעמדת סקוואט בכיפוף ברכיים ודחיפת האגן לאחור.","בהגיעכם לנקודה התחתונה של הסקוואט, דחפו בפיצוץ דרך העקבים לעמידה, ובו-זמנית לחצו את המוט מעל הראש.","הורידו את המוט חזרה לגובה הכתפיים תוך כדי הירידה חזרה לעמדת הסקוואט.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.","Lower into a squat position by bending your knees and pushing your hips back.","As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.","Lower the barbell back to shoulder height as you lower back into the squat position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч, удерживая штангу на уровне плеч хватом сверху.","Опуститесь в присед, согнув колени и отведя бедра назад.","Достигнув нижней точки приседа, резко поднимите пятки, чтобы встать, одновременно выжимая штангу над головой.","Опустите штангу обратно на высоту плеч, возвращаясь в положение приседа.","Повторите необходимое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de los hombros, sujetando una barra a la altura de los hombros con agarre prono.","Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Al llegar a la parte más baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando simultáneamente la barra por encima de la cabeza.","Baja la barra de nuevo a la altura de los hombros mientras vuelves a bajar a la posición de sentadilla.","Repite el número de repeticiones deseado."]}},{"id":"0120","name":"barbell upright row","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0120-UDlhcO8.jpg","gif_url":"videos/0120-UDlhcO8.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","תנו למוט להשתלשל מול הירכיים, ידיים ישרות לגמרי.","תוך שמירה על גב ישר וליבה מופעלת, נשפו והרימו את המוט ישר למעלה לכיוון הסנטר, כשהמרפקים מובילים.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу хватом сверху, руки расставлены чуть шире плеч.","Пусть штанга висит перед бедрами, руки полностью выпрямлены.","Удерживая спину прямой и напряженным корпус, выдохните и поднимите штангу прямо вверх к подбородку, ведя локтями.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros.","Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.","Manteniendo la espalda recta y el core activado, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.","Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0119","name":"barbell upright row v. 2","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0119-83HoW9X.jpg","gif_url":"videos/0119-83HoW9X.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","תנו למוט להשתלשל מול הירכיים, ידיים ישרות לגמרי.","תוך שמירה על גב ישר, נשפו והרימו את המוט ישר למעלה לכיוון הסנטר, כשהמרפקים מובילים.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу хватом сверху, руки расставлены чуть шире плеч.","Пусть штанга висит перед бедрами, руки полностью выпрямлены.","Удерживая спину прямо, выдохните и поднимите штангу прямо вверх к подбородку, ведя локтями.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros.","Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.","Manteniendo la espalda recta, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.","Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0121","name":"barbell upright row v. 3","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0121-fI18Rbc.jpg","gif_url":"videos/0121-fI18Rbc.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","תנו למוט להשתלשל מול הירכיים, ידיים ישרות לגמרי.","תוך שמירה על ליבה מופעלת וגב ישר, נשפו תוך הרמת המוט ישר למעלה לכיוון הסנטר, כשהמרפקים מובילים.","עצרו לרגע בנקודה העליונה, ואז שאפו תוך הורדת המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу хватом сверху, руки расставлены чуть шире плеч.","Пусть штанга висит перед бедрами, руки полностью выпрямлены.","Удерживая корпус напряженным и спину прямой, на выдохе поднимайте штангу прямо вверх к подбородку, ведя локтями.","Сделайте паузу на мгновение в верхней точке, затем на вдохе медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros.","Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.","Manteniendo el core activado y la espalda recta, exhala mientras levantas la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.","Haz una pausa breve en la parte más alta, luego inhala mientras bajas lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0122","name":"barbell wide bench press","category":"chest","body_part":"chest","equipment":"barbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0122-JsKq9so.jpg","gif_url":"videos/0122-JsKq9so.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","אחזו במוט באחיזה רחבה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט מהמתקן והחזיקו אותו ישר מעל החזה עם ידיים ישרות לגמרי.","הורידו את המוט באיטיות לכיוון החזה, עם מרפקים פתוחים מעט הצידה.","עצרו לרגע כשהמוט נוגע בחזה, ואז דחפו אותו חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows slightly flared out.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу широким хватом, на расстоянии чуть шире ширины плеч.","Снимите штангу со стойки и держите ее прямо над грудью, полностью вытянув руки.","Медленно опустите штангу к груди, слегка разведя локти.","Сделайте паузу на мгновение, когда штанга коснется вашей груди, затем поднимите ее обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos ligeramente abiertos hacia afuera.","Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1258","name":"barbell wide reverse grip bench press","category":"chest","body_part":"chest","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1258-945zpRg.jpg","gif_url":"videos/1258-945zpRg.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","אחזו במוט באחיזה הפוכה רחבה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט מהמתקן והחזיקו אותו ישר מעל החזה עם ידיים ישרות לגמרי.","הורידו את המוט באיטיות לכיוון החזה, עם מרפקים צמודים ושורשי כף יד ישרים.","עצרו לרגע כשהמוט נוגע בחזה, ואז דחפו אותו חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу широким обратным хватом, на расстоянии чуть шире ширины плеч.","Снимите штангу со стойки и держите ее прямо над грудью, полностью вытянув руки.","Медленно опустите штангу к груди, держа локти согнутыми и запястья прямыми.","Сделайте паузу на мгновение, когда штанга коснется вашей груди, затем поднимите ее обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Sujeta la barra con un agarre supino amplio, un poco más separado que el ancho de los hombros.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo y las muñecas rectas.","Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0124","name":"barbell wide squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0124-s7HX1BY.jpg","gif_url":"videos/0124-s7HX1BY.gif","instruction_steps":{"he":["עמדו עם רגליים רחבות מרוחב הכתפיים, כפות רגליים פונות מעט החוצה.","הניחו את המוט על הגב העליון, על שרירי הטרפז או הדלתא האחורית.","הפעילו את הליבה ושמרו על חזה מורם תוך ירידה לסקוואט, בדחיפת האגן לאחור וכיפוף הברכיים.","רדו עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги шире плеч, носки слегка направлены наружу.","Держите штангу на верхней части спины, опираясь на трапеции или задние дельты.","Напрягите корпус и держите грудь поднятой, опуская тело в присед, отводя бедра назад и сгибая колени.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0123","name":"barbell wide-grip upright row","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0123-RgJDRR1.jpg","gif_url":"videos/0123-RgJDRR1.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מוט באחיזה עליונה, ידיים רחבות מרוחב הכתפיים.","תנו למוט להשתלשל מול הירכיים, ידיים ישרות לגמרי.","תוך שמירה על גב ישר, נשפו והרימו את המוט ישר למעלה לכיוון הסנטר, כשהמרפקים מובילים.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу хватом сверху, руки шире ширины плеч.","Пусть штанга висит перед бедрами, руки полностью выпрямлены.","Удерживая спину прямо, выдохните и поднимите штангу прямо вверх к подбородку, ведя локтями.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros.","Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.","Manteniendo la espalda recta, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.","Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0126","name":"barbell wrist curl","category":"lower arms","body_part":"lower arms","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0126-82LxxkW.jpg","gif_url":"videos/0126-82LxxkW.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והאמות על הירכיים, אוחזים במוט באחיזה תחתונה.","תנו למוט להתגלגל מטה עד קצות האצבעות, תוך שמירה על שורשי כף יד ישרים.","גלגלו באיטיות את המוט למעלה לכיוון האמות על ידי כיפוף שורשי כף היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip.","Allow the barbell to roll down to your fingertips, keeping your wrists straight.","Slowly curl the barbell up towards your forearms by flexing your wrists.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ступни на землю, а предплечья положите на бедра, возьмите штангу хватом снизу.","Позвольте штанге скатиться до кончиков пальцев, сохраняя запястья прямыми.","Медленно поднимите штангу к предплечьям, сгибая запястья.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies planos en el suelo y los antebrazos apoyados sobre los muslos, sujetando una barra con agarre supino.","Deja que la barra ruede hacia las puntas de los dedos, manteniendo las muñecas rectas.","Enrolla lentamente la barra hacia los antebrazos flexionando las muñecas.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0125","name":"barbell wrist curl v. 2","category":"lower arms","body_part":"lower arms","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0125-6kSxYnw.jpg","gif_url":"videos/0125-6kSxYnw.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה וברכיים כפופות.","החזיקו מוט באחיזה תחתונה, כפות ידיים כלפי מעלה, ידיים ברוחב כתפיים.","הניחו את האמות על הירכיים, כששורשי כף היד משתלשלים מעבר לקצה.","גלגלו באיטיות את שורשי כף היד כלפי מעלה, והביאו את המוט לכיוון האמות.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и согните колени.","Держите штангу обратным хватом ладонями вверх, руки на ширине плеч.","Положите предплечья на бедра, позволяя запястьям свисать с края.","Медленно поднимите запястья вверх, поднося штангу к предплечьям.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies planos sobre el suelo y las rodillas flexionadas.","Sujeta una barra con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia los antebrazos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0127","name":"barbell zercher squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/0127-LSTChY9.jpg","gif_url":"videos/0127-LSTChY9.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וכפות רגליים פונות מעט החוצה.","החזיקו את המוט בקפלי המרפקים, כשהידיים אוחזות בו לייצוב.","הפעילו את הליבה ושמרו על חזה מורם תוך הורדת האגן לאחור ולמטה לעמדת סקוואט.","שמרו על הברכיים בקו אחד עם כפות הרגליים ועל המשקל בעקבים.","עצרו לרגע בנקודה התחתונה של הסקוואט, ואז דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка развернув пальцы ног.","Держите штангу на сгибах локтей, обхватив ее руками для устойчивости.","Напрягите корпус и держите грудь поднятой, опуская бедра назад и вниз в положение приседа.","Держите колени на одной линии с пальцами ног, а вес тела перенесите на пятки.","Задержитесь на мгновение в нижней части приседа, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra en el pliegue de los codos, con las manos agarrando la barra para mayor estabilidad.","Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3212","name":"basic toe touch (male)","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","calves"],"target":"glutes","image":"images/3212-BbfB8Gb.jpg","gif_url":"videos/3212-BbfB8Gb.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וידיים לצידי הגוף.","הטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר וברכיים כפופות מעט.","מתחו את הידיים לכיוון קצות האצבעות של הרגליים, כשהרגליים ישרות ככל האפשר.","עצרו לרגע בנקודה התחתונה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your arms by your sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with your hands, keeping your legs as straight as possible.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, руки по бокам.","Наклонитесь вперед в талии, сохраняя спину прямой и слегка согнутыми в коленях.","Потянитесь руками к пальцам ног, сохраняя ноги как можно более прямыми.","Задержитесь на мгновение в нижней точке, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Extiende las manos hacia las puntas de los pies, manteniendo las piernas lo más rectas posible.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0128","name":"battling ropes","category":"shoulders","body_part":"shoulders","equipment":"rope","muscle_group":"forearms","secondary_muscles":["forearms","core"],"target":"delts","image":"images/0128-RJa4tCo.jpg","gif_url":"videos/0128-RJa4tCo.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","החזיקו קצה חבל בכל יד, עם כפות ידיים פונות זו לזו.","הרימו את הידיים לגובה הכתפיים, תוך שמירה על מרפקים כפופים מעט.","התחילו ליצור גלים מתחלפים בחבלים, בהרמה והורדה מהירה של כל יד לסירוגין.","המשיכו למשך הזמן או מספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold one end of the rope in each hand, with your palms facing each other.","Raise your arms to shoulder height, keeping your elbows slightly bent.","Begin making alternating waves with the ropes by rapidly raising and lowering each arm.","Continue for the desired duration or number of repetitions."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Возьмите по одному концу веревки в каждую руку ладонями друг к другу.","Поднимите руки на высоту плеч, слегка согнув локти.","Начните делать попеременные волны с помощью веревок, быстро поднимая и опуская каждую руку.","Продолжайте желаемую продолжительность или количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta un extremo de la cuerda en cada mano, con las palmas mirándose entre sí.","Levanta los brazos hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.","Comienza a hacer ondas alternas con las cuerdas, levantando y bajando rápidamente cada brazo.","Continúa durante el tiempo o el número de repeticiones deseado."]}},{"id":"3360","name":"bear crawl","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"core","secondary_muscles":["core","shoulders","triceps"],"target":"cardiovascular system","image":"images/3360-0Yz8WdV.jpg","gif_url":"videos/3360-0Yz8WdV.gif","instruction_steps":{"he":["התחילו על ארבע, עם ידיים ישר מתחת לכתפיים וברכיים ישר מתחת לאגן.","הרימו את הברכיים מעט מהרצפה, תוך שמירה על גב שטוח וליבה מופעלת.","הזיזו את יד ימין ורגל שמאל קדימה בו-זמנית, ואחריהן יד שמאל ורגל ימין.","המשיכו לזחול קדימה, לסירוגין בתנועות הידיים והרגליים.","שמרו על קצב אחיד ובטן מכווצת לאורך כל התרגיל.","המשיכו למרחק או לזמן הרצוי."],"en":["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Lift your knees slightly off the ground, keeping your back flat and your core engaged.","Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.","Continue crawling forward, alternating your hand and foot movements.","Maintain a steady pace and keep your core tight throughout the exercise.","Continue for the desired distance or time."],"ru":["Встаньте на четвереньки, положив руки прямо под плечи и колени прямо под бедрами.","Слегка поднимите колени от земли, сохраняя спину ровной и напряженным корпус.","Одновременно переместите вперед правую руку и левую ногу, а затем левую руку и правую ногу.","Продолжайте ползти вперед, чередуя движения рук и ног.","Поддерживайте устойчивый темп и держите корпус напряженным на протяжении всего упражнения.","Продолжайте движение желаемое расстояние или время."],"es":["Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.","Levanta las rodillas ligeramente del suelo, manteniendo la espalda plana y el core activado.","Mueve la mano derecha y el pie izquierdo hacia adelante simultáneamente, seguido de la mano izquierda y el pie derecho.","Continúa avanzando a gatas, alternando los movimientos de manos y pies.","Mantén un ritmo constante y el core firme durante todo el ejercicio.","Continúa durante la distancia o el tiempo deseado."]}},{"id":"1259","name":"behind head chest stretch","category":"chest","body_part":"chest","equipment":"assisted","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1259-QoHIhPl.jpg","gif_url":"videos/1259-QoHIhPl.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים.","שלבו את האצבעות מאחורי הראש עם מרפקים פונים החוצה.","כווצו באיטיות את השכמות זו לזו ודחפו את החזה קדימה.","החזיקו את המתיחה 15–30 שניות.","שחררו את המתיחה וחזרו עליה כרצונכם."],"en":["Stand tall with your feet shoulder-width apart.","Interlace your fingers behind your head with your elbows pointing outwards.","Slowly squeeze your shoulder blades together and push your chest forward.","Hold the stretch for 15-30 seconds.","Release the stretch and repeat as desired."],"ru":["Встаньте прямо, ноги на ширине плеч.","Переплетите пальцы за головой так, чтобы локти были направлены наружу.","Медленно сведите лопатки вместе и выдвиньте грудь вперед.","Удерживайте растяжку 15–30 секунд.","Освободите растяжку и повторите по желанию."],"es":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Entrelaza los dedos detrás de la cabeza con los codos apuntando hacia afuera.","Junta lentamente los omóplatos y empuja el pecho hacia adelante.","Mantén el estiramiento durante 15-30 segundos.","Suelta el estiramiento y repite cuantas veces lo desees."]}},{"id":"0129","name":"bench dip (knees bent)","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0129-RrLske5.jpg","gif_url":"videos/0129-RrLske5.gif","instruction_steps":{"he":["שבו על קצה ספסל או כיסא כשהידיים אוחזות בקצה לצידי האגן.","החליקו את הישבן מהספסל ויישרו את הרגליים לפניכם, כשהעקבים על הרצפה.","כופפו מרפקים והורידו את הגוף לכיוון הרצפה, כשהגב קרוב לספסל.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на край скамьи или стула, взявшись руками за край рядом с бедрами.","Оторвите ягодицы от скамьи и выпрямите ноги перед собой, удерживая пятки на земле.","Согните локти и опустите тело к земле, держа спину близко к скамье.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas.","Desliza los glúteos fuera del banco y estira las piernas frente a ti, manteniendo los talones en el suelo.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1399","name":"bench dip on floor","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1399-9RT8oQW.jpg","gif_url":"videos/1399-9RT8oQW.gif","instruction_steps":{"he":["שבו על קצה ספסל או כיסא כשהידיים אוחזות בקצה והאצבעות פונות קדימה.","החליקו את הישבן מהספסל ותמכו במשקל הגוף עם הידיים.","הורידו את הגוף בכיפוף מרפקים עד שהזרועות העליונות מקבילות לרצפה.","דחפו את עצמכם חזרה למעלה לנקודת ההתחלה על ידי יישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Сядьте на край скамьи или стула, взявшись руками за край, пальцами вперед.","Сдвиньте ягодицы со скамьи, поддерживая вес руками.","Опустите тело, сгибая локти, пока плечи не станут параллельны полу.","Вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante.","Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0130","name":"bench hip extension","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"glutes","image":"images/0130-u27Kcdz.jpg","gif_url":"videos/0130-u27Kcdz.gif","instruction_steps":{"he":["שבו על ספסל כשהגב נשען על המשענת וכפות הרגליים על הרצפה.","הניחו את הידיים על הספסל לתמיכה.","הפעילו את הישבן והירך האחורית, והרימו את האגן מהספסל עד שהגוף יוצר קו ישר מהברכיים ועד הכתפיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back against the bench and your feet flat on the ground.","Place your hands on the bench for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, прислонившись спиной к скамье, а ноги поставьте на землю.","Положите руки на скамью для поддержки.","Задействуйте ягодицы и мышцы задней поверхности бедра, затем поднимите бедра со скамьи, пока ваше тело не образует прямую линию от колен до плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda contra el banco y los pies planos en el suelo.","Coloca las manos sobre el banco para apoyarte.","Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3019","name":"bench pull-ups","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/3019-mExgrF9.jpg","gif_url":"videos/3019-mExgrF9.gif","instruction_steps":{"he":["התמקמו מתחת למוט או משטח אופקי יציב בגובה החזה.","אחזו במוט או במשטח באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היתלו עם ידיים ישרות לגמרי וגוף ישר.","משכו את החזה לכיוון המוט או המשטח בכיווץ השכמות זו לזו וכיפוף המרפקים.","המשיכו למשוך עד שהסנטר מעל המוט או המשטח.","הורידו את עצמכם חזרה לנקודת ההתחלה בשליטה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Position yourself under a bar or a sturdy horizontal surface that is at chest height.","Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.","Continue pulling until your chin is above the bar or surface.","Lower yourself back down to the starting position with control.","Repeat for the desired number of repetitions."],"ru":["Расположитесь под перекладиной или прочной горизонтальной поверхностью на уровне груди.","Возьмитесь за перекладину или поверхность хватом сверху, на расстоянии чуть шире плеч.","Висите, полностью вытянув руки и выпрямив тело.","Подтяните грудь к перекладине или поверхности, сведя лопатки вместе и согнув локти.","Продолжайте тянуть, пока подбородок не окажется над перекладиной или поверхностью.","Опуститесь обратно в исходное положение, сохраняя контроль.","Повторите необходимое количество повторений."],"es":["Colócate debajo de una barra o una superficie horizontal resistente que esté a la altura del pecho.","Sujeta la barra o la superficie con agarre prono, un poco más separado que el ancho de los hombros.","Cuélgate con los brazos completamente extendidos y el cuerpo recto.","Lleva el pecho hacia la barra o la superficie juntando los omóplatos y flexionando los codos.","Continúa tirando hasta que la barbilla quede por encima de la barra o la superficie.","Baja de nuevo a la posición inicial con control.","Repite el número de repeticiones deseado."]}},{"id":"3639","name":"bent knee lying twist (male)","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"glutes","image":"images/3639-6sYyrRX.jpg","gif_url":"videos/3639-6sYyrRX.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","מתחו את הידיים לצדדים, ניצבות לגוף.","תוך שמירה על ברכיים צמודות, הורידו אותן באיטיות לצד אחד, במטרה לגעת ברצפה עם הברכיים.","עצרו לרגע, ואז הפעילו את הליבה והרימו באיטיות את הברכיים חזרה לנקודת ההתחלה.","חזרו על התנועה לצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms out to the sides, perpendicular to your body.","Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.","Pause for a moment, then engage your core and slowly lift your knees back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Вытяните руки в стороны перпендикулярно телу.","Держа колени вместе, медленно опустите их в сторону, стараясь коснуться коленями земли.","Сделайте паузу на мгновение, затем задействуйте корпус и медленно поднимите колени обратно в исходное положение.","Повторите движение в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende los brazos hacia los lados, perpendiculares al cuerpo.","Manteniendo las rodillas juntas, bájalas lentamente hacia un lado, intentando tocar el suelo con las rodillas.","Haz una pausa breve, luego activa el core y levanta lentamente las rodillas de vuelta a la posición inicial.","Repite el movimiento hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1770","name":"biceps leg concentration curl","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1770-sJFIDIp.jpg","gif_url":"videos/1770-sJFIDIp.gif","instruction_steps":{"he":["שבו על ספסל עם רגליים פסוקות וכפות רגליים על הרצפה.","החזיקו משקולת יד ביד אחת והניחו את המרפק על החלק הפנימי של הירך, מעט מעל הברך.","עם כף יד כלפי מעלה, כופפו את המשקולת לכיוון הכתף תוך שמירה על הזרוע העליונה ללא תזוזה.","כווצו את הבייספס בנקודה העליונה של התנועה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a bench with your legs spread apart and your feet flat on the ground.","Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.","With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью, раздвинув ноги и поставив ступни на землю.","Возьмите гантель в одну руку и поместите локоть на внутреннюю часть бедра, чуть выше колена.","Поверните ладонь вверх и согните гантель к плечу, сохраняя плечо неподвижным.","Напрягите бицепсы в верхней точке движения, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco con las piernas separadas y los pies planos en el suelo.","Sujeta una mancuerna con una mano y coloca el codo en la parte interna del muslo, justo por encima de la rodilla.","Con la palma hacia arriba, flexiona la mancuerna hacia el hombro manteniendo el brazo superior quieto.","Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0139","name":"biceps narrow pull-ups","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0139-50BETrz.jpg","gif_url":"videos/0139-50BETrz.gif","instruction_steps":{"he":["היתלו על מוט מתח עם כפות ידיים פונות אליכם וידיים ברוחב כתפיים.","הפעילו את שרירי הליבה ומשכו את עצמכם למעלה לכיוון המוט, תוך התמקדות בשרירי הבייספס להרמת הגוף.","עצרו לרגע בנקודה העליונה, ואז הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, повернув ладонями к себе и расставив руки на ширине плеч.","Напрягите корпус и подтяните себя к перекладине, сосредоточившись на использовании бицепсов для подъема тела.","Задержитесь на мгновение в верхней точке, затем медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros.","Activa el core y tira de tu cuerpo hacia la barra, enfocándote en usar los bíceps para levantar el cuerpo.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0140","name":"biceps pull-up","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0140-guT8YnS.jpg","gif_url":"videos/0140-guT8YnS.gif","instruction_steps":{"he":["היתלו על מוט מתח עם כפות ידיים פונות מכם וידיים ברוחב כתפיים.","הפעילו את שרירי הליבה ומשכו את עצמכם למעלה בכיפוף מרפקים, תוך הבאת החזה לכיוון המוט.","עצרו בנקודה העליונה של התנועה, ואז הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.","Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, повернув ладонями от себя и расставив руки на ширине плеч.","Напрягите корпус и подтяните себя, сгибая локти и приближая грудь к перекладине.","Сделайте паузу в верхней точке движения, затем медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos separadas a la altura de los hombros.","Activa el core y tira de tu cuerpo hacia arriba flexionando los codos, llevando el pecho hacia la barra.","Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0137","name":"body-up","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0137-U6G2gk9.jpg","gif_url":"videos/0137-U6G2gk9.gif","instruction_steps":{"he":["התחילו בהנחת הידיים על משטח מוגבה, כמו ספסל או מקבילים, עם כפות ידיים כלפי מטה ואצבעות פונות קדימה.","מתחו את הרגליים לפניכם, כשהעקבים על הרצפה והגוף ישר.","הורידו את הגוף בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף, עד שהזרועות העליונות מקבילות לרצפה.","עצרו לרגע, ואז דחפו דרך כפות הידיים ליישור הידיים והרמת הגוף חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.","Extend your legs out in front of you, keeping your heels on the ground and your body straight.","Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что положите руки на приподнятую поверхность, например на скамью или брусья, ладонями вниз и пальцами вперед.","Вытяните ноги перед собой, удерживая пятки на земле, а тело прямо.","Опустите тело, согнув локти и держа их близко к бокам, пока плечи не станут параллельны земле.","Сделайте паузу на мгновение, затем подтолкните ладони, чтобы выпрямить руки и поднять тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza colocando las manos sobre una superficie elevada, como un banco o unas barras paralelas, con las palmas hacia abajo y los dedos apuntando hacia adelante.","Extiende las piernas frente a ti, manteniendo los talones en el suelo y el cuerpo recto.","Baja el cuerpo flexionando los codos, manteniéndolos cerca del cuerpo, hasta que los brazos superiores queden paralelos al suelo.","Haz una pausa breve, luego empuja con las palmas para extender los brazos y levantar el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3543","name":"bodyweight drop jump squat","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3543-wfotm7S.jpg","gif_url":"videos/3543-wfotm7S.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","רדו לסקוואט בכיפוף ברכיים ודחיפת האגן לאחור.","קפצו למעלה בפיצוץ, תוך יישור הירכיים, הברכיים והקרסוליים.","באוויר, הצמידו במהירות את כפות הרגליים זו לזו.","נחתו ברכות על כריות כפות הרגליים ורדו מיד חזרה לעמדת סקוואט.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump up explosively, extending your hips, knees, and ankles.","While in mid-air, quickly bring your feet together.","Land softly on the balls of your feet and immediately drop back into a squat position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Опустите тело в присед, согнув колени и отведя бедра назад.","Резко подпрыгните вверх, вытягивая бедра, колени и лодыжки.","Находясь в воздухе, быстро сведите ноги вместе.","Мягко приземлитесь на подушечки стоп и сразу же вернитесь в присед.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Salta hacia arriba explosivamente, extendiendo las caderas, las rodillas y los tobillos.","Mientras estás en el aire, junta rápidamente los pies.","Aterriza suavemente sobre las puntas de los pies y de inmediato vuelve a bajar a una posición de sentadilla.","Repite el número de repeticiones deseado."]}},{"id":"3544","name":"bodyweight incline side plank","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","shoulders"],"target":"abs","image":"images/3544-5VXmnV5.jpg","gif_url":"videos/3544-5VXmnV5.gif","instruction_steps":{"he":["התחילו בשכיבה על הצד עם רגליים מתוחות זו על גבי זו.","הניחו את האמה על הרצפה ישר מתחת לכתף, עם מרפק כפוף בזווית של 90 מעלות.","הפעילו את הליבה והרימו את האגן מהרצפה, ביצירת קו ישר מהראש ועד כפות הרגליים.","החזיקו את התנוחה למשך הזמן הרצוי.","הורידו את האגן חזרה לרצפה וחזרו על התנועה בצד השני."],"en":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the ground and repeat on the other side."],"ru":["Начните с того, что лягте на бок, вытянув ноги и положив их друг на друга.","Положите предплечье на землю прямо под плечом, согнув локоть под углом 90 градусов.","Напрягите корпус и поднимите бедра от земли, создавая прямую линию от головы до ступней.","Удерживайте это положение желаемое время.","Опустите бедра обратно на землю и повторите то же самое с другой стороны."],"es":["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.","Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados.","Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.","Mantén esta posición durante el tiempo deseado.","Baja las caderas de nuevo al suelo y repite hacia el otro lado."]}},{"id":"1771","name":"bodyweight kneeling triceps extension","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"triceps","image":"images/1771-s0HKO2I.jpg","gif_url":"videos/1771-s0HKO2I.gif","instruction_steps":{"he":["כרעו על הרצפה עם ברכיים ברוחב אגן.","הניחו את הידיים על הרצפה לפניכם, ברוחב כתפיים, אצבעות פונות קדימה.","מתחו את הרגליים ישר לאחור, באיזון על קצות האצבעות והידיים, ביצירת קו ישר מהראש ועד העקבים.","כופפו מרפקים והורידו את פלג הגוף העליון לכיוון הרצפה, תוך שמירה על מרפקים צמודים לצידי הגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך הידיים ליישורן וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Kneel down on the ground with your knees hip-width apart.","Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.","Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.","Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте на колени на землю, расставив колени на ширине плеч.","Положите руки на пол перед собой на ширине плеч, пальцы направлены вперед.","Вытяните ноги прямо позади себя, балансируя на пальцах ног и руках, образуя прямую линию от головы до пяток.","Согните локти и опустите верхнюю часть тела к земле, держа локти близко к бокам.","Задержитесь на мгновение в нижней точке, затем оттолкнитесь руками, чтобы выпрямить руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de rodillas en el suelo con las rodillas separadas a la altura de las caderas.","Coloca las manos en el suelo frente a ti, separadas a la altura de los hombros, con los dedos apuntando hacia adelante.","Extiende las piernas rectas detrás de ti, equilibrándote sobre las puntas de los pies y las manos, formando una línea recta desde la cabeza hasta los talones.","Flexiona los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo los codos cerca del cuerpo.","Haz una pausa breve en la posición más baja, luego empuja con las manos para extender los brazos y volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1769","name":"bodyweight side lying biceps curl","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1769-gscGLOU.jpg","gif_url":"videos/1769-gscGLOU.gif","instruction_steps":{"he":["שכבו על הצד עם רגליים ישרות והראש נתמך על היד.","הצמידו את הזרוע העליונה לצד הגוף וכופפו את המרפק כדי לגלגל את האמה לכיוון הכתף.","עצרו לרגע בנקודה העליונה, ואז הורידו את האמה באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on your side with your legs extended and your head supported by your arm.","Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на бок, вытянув ноги и подперев голову рукой.","Прижмите плечо к боку и согните локоть, чтобы предплечье приблизилось к плечу.","Задержитесь на мгновение в верхней точке, затем медленно опустите предплечье обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo.","Mantén el brazo superior junto al cuerpo y flexiona el codo para llevar el antebrazo hacia el hombro.","Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3168","name":"bodyweight squatting row","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/3168-3xK09Sk.jpg","gif_url":"videos/3168-3xK09Sk.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים בחפץ יציב או ברצועות אימון עם ידיים מתוחות.","הורידו את הגוף לעמדת סקוואט, תוך שמירה על גב ישר וברכיים מאחורי קצות האצבעות.","מעמדת הסקוואט, משכו את הגוף למעלה לכיוון החפץ או רצועות האימון, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.","Lower your body into a squat position, keeping your back straight and your knees behind your toes.","From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держитесь за прочный предмет или тренажер для подвешивания, вытянув руки.","Опустите тело в положение приседа, сохраняя спину прямой и колени за носками.","Из положения приседа подтяните тело вверх к предмету или тренажеру, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando un objeto resistente o un entrenador de suspensión con los brazos extendidos.","Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies.","Desde la posición de sentadilla, tira del cuerpo hacia arriba en dirección al objeto o al entrenador de suspensión, juntando los omóplatos.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3167","name":"bodyweight squatting row (with towel)","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/3167-BReCuOn.jpg","gif_url":"videos/3167-BReCuOn.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים מגבת לפניכם עם כפות ידיים כלפי מטה.","כופפו ברכיים והורידו את הגוף לעמדת סקוואט, תוך שמירה על גב ישר וחזה מורם.","תוך כדי הירידה לסקוואט, משכו בו-זמנית את המגבת לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של הסקוואט, ואז חזרו באיטיות לנקודת ההתחלה תוך יישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.","Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.","As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите перед собой полотенце ладонями вниз.","Согните ноги в коленях и опустите тело в положение приседа, держа спину прямо и грудь вверх.","Опускаясь в присед, одновременно подтягивайте полотенце к груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части приседа, затем медленно вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una toalla frente a ti con las palmas hacia abajo.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Mientras bajas a la sentadilla, tira simultáneamente de la toalla hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte más baja de la sentadilla, luego vuelve lentamente a la posición inicial mientras extiendes los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1373","name":"bodyweight standing calf raise","category":"lower legs","body_part":"lower legs","equipment":"body weight","muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/1373-bJYHBIN.jpg","gif_url":"videos/1373-bJYHBIN.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, כפות רגליים פונות קדימה.","הניחו את הידיים על קיר או משטח יציב לשיווי משקל.","הרימו באיטיות את העקבים מהרצפה, והעבירו את משקל הגוף לכריות כפות הרגליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a wall or stable surface for balance.","Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки направлены вперед.","Положите руки на стену или устойчивую поверхность для равновесия.","Медленно поднимите пятки от земли, перенеся вес тела на подушечки стоп.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.","Coloca las manos sobre una pared o superficie estable para mantener el equilibrio.","Levanta lentamente los talones del suelo, llevando el peso del cuerpo hacia las puntas de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3156","name":"bodyweight standing close-grip one arm row","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/3156-v2DfH14.jpg","gif_url":"videos/3156-v2DfH14.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, ברכיים כפופות מעט, ואחזו משקולת יד ביד אחת באחיזה ניטרלית.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וליבה מופעלת.","משכו את המשקולת למעלה לכיוון החזה, תוך שמירה על מרפק קרוב לגוף וכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, колени слегка согнуты, в одной руке возьмите гантель нейтральным хватом.","Наклонитесь вперед в бедрах, сохраняя спину прямой и напряженный корпус.","Подтяните гантель к груди, держа локоть близко к телу и сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en una mano con agarre neutro.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"3158","name":"bodyweight standing close-grip row","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/3158-tig3PXb.jpg","gif_url":"videos/3158-tig3PXb.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","הטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר וליבה מופעלת.","מתחו את הידיים ישר לפניכם, אוחזים במוט או בידיות באחיזה צרה.","משכו את המוט או הידיות לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה, ואז שחררו באיטיות וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight in front of you, gripping the bar or handles with a close grip.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Наклонитесь вперед в талии, сохраняя спину прямой и напрягая корпус.","Вытяните руки прямо перед собой, крепко взявшись за перекладину или ручки.","Потяните штангу или ручки к себе, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке движения, затем медленно расслабьтесь и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.","Extiende los brazos rectos frente a ti, sujetando la barra o las agarraderas con un agarre cerrado.","Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos.","Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3162","name":"bodyweight standing one arm row","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/3162-xbkPfaw.jpg","gif_url":"videos/3162-xbkPfaw.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, ברכיים כפופות מעט, ואחזו משקולת יד ביד אחת.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וליבה מופעלת.","תנו למשקולת להשתלשל ישר מטה לפניכם, עם יד ישרה לגמרי.","משכו את המשקולת למעלה לכיוון החזה, תוך שמירה על מרפק קרוב לגוף.","כווצו את השכמות זו לזו בנקודה העליונה של התנועה.","הורידו את המשקולת חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down in front of you, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, колени слегка согнуты, в одной руке возьмите гантель.","Наклонитесь вперед в бедрах, сохраняя спину прямой и напряженный корпус.","Пусть гантель висит прямо перед вами, полностью выпрямив руку.","Подтяните гантель к груди, держа локоть близко к телу.","В верхней точке движения сведите лопатки вместе.","Опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna con una mano.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Deja que la mancuerna cuelgue recta frente a ti, con el brazo completamente extendido.","Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo.","Junta los omóplatos en la parte superior del movimiento.","Baja la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"3161","name":"bodyweight standing one arm row (with towel)","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/3161-O4oIqQD.jpg","gif_url":"videos/3161-O4oIqQD.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, ברכיים כפופות מעט, ואחזו מגבת ביד אחת.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וליבה מופעלת.","משכו את המגבת לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המגבת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Встаньте, ноги на ширине плеч, колени слегка согнуты, одной рукой держите полотенце.","Наклонитесь вперед в бедрах, сохраняя спину прямой и напряженный корпус.","Подтяните полотенце к груди, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите полотенце обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Tira de la toalla hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"3166","name":"bodyweight standing row","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/3166-wd4ds3s.jpg","gif_url":"videos/3166-wd4ds3s.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","אחזו במוט או בידיות באחיזה עליונה, כפות ידיים כלפי מטה.","שמרו על גב ישר וליבה מופעלת.","משכו את המוט או הידיות לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה.","שחררו באיטיות ויישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Grasp a bar or handles with an overhand grip, palms facing down.","Keep your back straight and core engaged.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Возьмите перекладину или ручки верхним хватом ладонями вниз.","Держите спину прямо и напрягите корпус.","Потяните штангу или ручки к себе, сведя лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения.","Медленно расслабьте и вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una barra o las agarraderas con agarre prono, palmas hacia abajo.","Mantén la espalda recta y el core activado.","Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento.","Suelta lentamente y extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3165","name":"bodyweight standing row (with towel)","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/3165-uTv34oq.jpg","gif_url":"videos/3165-uTv34oq.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו מגבת לפניכם בשתי הידיים.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","משכו את המגבת לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите полотенце перед собой обеими руками.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Подтяните полотенце к груди, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una toalla frente a ti con ambas manos.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Tira de la toalla hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0138","name":"bottoms-up","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/0138-CI6baTY.jpg","gif_url":"videos/0138-CI6baTY.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וידיים לצידי הגוף.","כופפו ברכיים והביאו אותן לכיוון החזה, כשכפות הרגליים באוויר.","תוך הפעלת שרירי הבטן, הרימו את האגן מהרצפה, בהבאת הברכיים לכיוון הראש.","עצרו לרגע בנקודה העליונה, ואז הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and bring them towards your chest, keeping your feet off the ground.","Engaging your abs, lift your hips off the ground, bringing your knees towards your head.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, вытянув ноги и положив руки по бокам.","Согните колени и подтяните их к груди, не отрывая ступни от земли.","Включив пресс, поднимите бедра от земли, поднеся колени к голове.","Задержитесь на мгновение в верхней точке, затем медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies fuera del suelo.","Activando el abdomen, levanta las caderas del suelo, llevando las rodillas hacia la cabeza.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1374","name":"box jump down with one leg stabilization","category":"lower legs","body_part":"lower legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes"],"target":"calves","image":"images/1374-iPm26QU.jpg","gif_url":"videos/1374-iPm26QU.gif","instruction_steps":{"he":["עמדו מול קופסה או משטח עם רגליים ברוחב כתפיים.","כופפו ברכיים וקפצו על הקופסה, בנחיתה רכה עם כף רגל אחת על הקופסה והשנייה משתלשלת מהקצה.","התייצבו על הקופסה עם כף הרגל שעליה, תוך שמירה על כף הרגל השנייה באוויר.","החזיקו את התנוחה כמה שניות, בהפעלת שרירי התאומים לשמירה על שיווי משקל.","רדו באיטיות עם כף הרגל שעל הקופסה, בחזרה לנקודת ההתחלה.","חזרו על התרגיל ברגל השנייה."],"en":["Stand in front of a box or platform with your feet shoulder-width apart.","Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.","Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground.","Hold this position for a few seconds, engaging your calf muscles to maintain balance.","Slowly step down with the foot that is on the box, returning to the starting position.","Repeat the exercise with the other leg."],"ru":["Встаньте перед ящиком или платформой, поставив ноги на ширине плеч.","Согните колени и прыгните на ящик, мягко приземлившись, поставив одну ногу на ящик, а другую свесив с края.","Зафиксируйтесь на ящике стоящей на нем ногой, удерживая при этом другую ногу над землей.","Удерживайте это положение несколько секунд, задействуя икроножные мышцы для сохранения равновесия.","Медленно шагните вниз ногой, стоящей на ящике, возвращаясь в исходное положение.","Повторите упражнение с другой ногой."],"es":["Ponte de pie frente a una caja o plataforma con los pies separados a la altura de los hombros.","Flexiona las rodillas y salta sobre la caja, aterrizando suavemente con un pie sobre la caja y el otro pie colgando del borde.","Estabilízate sobre la caja con el pie que está sobre ella, mientras mantienes el otro pie fuera del suelo.","Mantén esta posición durante unos segundos, activando los músculos de la pantorrilla para conservar el equilibrio.","Baja lentamente con el pie que está sobre la caja, volviendo a la posición inicial.","Repite el ejercicio con la otra pierna."]}},{"id":"2466","name":"bridge - mountain climber (cross body)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","quadriceps","hamstrings","shoulders","triceps"],"target":"abs","image":"images/2466-9c6T1YX.jpg","gif_url":"videos/2466-9c6T1YX.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים ישר מתחת לכתפיים והגוף בקו ישר.","הפעילו את הליבה והרימו את כף רגל ימין מהרצפה, בהבאת ברך ימין לכיוון מרפק שמאל.","החזירו את כף רגל ימין לנקודת ההתחלה וחזרו על התנועה עם כף רגל שמאל לכיוון מרפק ימין.","המשיכו להחליף צדדים, בקצב מבוקר.","שמרו על אגן מאוזן, והימנעו מהרמתו גבוה מדי או משקיעתו נמוך מדי.","שמרו על דפוס נשימה אחיד לאורך כל התרגיל.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow.","Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.","Continue alternating sides, moving at a controlled pace.","Keep your hips level and avoid lifting your hips too high or sagging them too low.","Maintain a steady breathing pattern throughout the exercise.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, положив руки прямо под плечи, а тело образуя прямую линию.","Напрягите корпус и поднимите правую ногу от земли, поднеся правое колено к левому локтю.","Верните правую ногу в исходное положение и повторите движение левой ногой к правому локтю.","Продолжайте чередовать стороны, двигаясь в контролируемом темпе.","Держите бедра ровно, не поднимайте бедра слишком высоко и не опускайте их слишком низко.","Поддерживайте ровный ритм дыхания на протяжении всего упражнения.","Повторите необходимое количество повторений."],"es":["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.","Activa el core y levanta el pie derecho del suelo, llevando la rodilla derecha hacia el codo izquierdo.","Vuelve a colocar el pie derecho en la posición inicial y repite el movimiento llevando el pie izquierdo hacia el codo derecho.","Continúa alternando los lados, moviéndote a un ritmo controlado.","Mantén las caderas niveladas y evita levantarlas demasiado alto o dejarlas caer demasiado bajo.","Mantén un patrón de respiración constante durante todo el ejercicio.","Repite el número de repeticiones deseado."]}},{"id":"1160","name":"burpee","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","shoulders","chest"],"target":"cardiovascular system","image":"images/1160-dK9394r.jpg","gif_url":"videos/1160-dK9394r.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים.","רדו לסקוואט בכיפוף ברכיים והניחו את הידיים על הרצפה לפניכם.","קפצו עם הרגליים לאחור לעמדת שכיבת סמיכה.","בצעו שכיבת סמיכה תוך שמירה על גוף בקו ישר.","קפצו עם הרגליים חזרה לעמדת הסקוואט.","קפצו למעלה בפיצוץ, עם ידיים מתוחות מעל הראש.","נחתו ברכות ורדו מיד חזרה לסקוואט לתחילת החזרה הבאה."],"en":["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.","Kick your feet back into a push-up position.","Perform a push-up, keeping your body in a straight line.","Jump your feet back into the squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into a squat position to begin the next repetition."],"ru":["Начните с положения стоя, поставив ноги на ширине плеч.","Опустите тело в присед, согнув колени и положив руки на пол перед собой.","Верните ноги в положение для отжимания.","Выполните отжимание, удерживая тело прямой.","Верните ноги в положение приседа.","Резко подпрыгните вверх, вытянув руки над головой.","Мягко приземлитесь и сразу же опуститесь в присед, чтобы начать следующее повторение."],"es":["Comienza de pie con los pies separados a la altura de los hombros.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y colocando las manos en el suelo frente a ti.","Lleva los pies hacia atrás de una patada hasta una posición de flexión de brazos.","Realiza una flexión de brazos, manteniendo el cuerpo en línea recta.","Salta con los pies de vuelta a la posición de sentadilla.","Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza.","Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición."]}},{"id":"0870","name":"butt-ups","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0870-qcNN2FN.jpg","gif_url":"videos/0870-qcNN2FN.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים לצידי הגוף, כפות ידיים כלפי מטה.","תוך הפעלת שרירי הבטן, הרימו את הרגליים מהרצפה והביאו את הברכיים לכיוון החזה.","בנקודה העליונה של התנועה, כווצו את שרירי הבטן ועצרו לרגע.","הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","At the top of the movement, squeeze your abs and pause for a moment.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки по бокам ладонями вниз.","Включив пресс, поднимите ноги от земли, подтянув колени к груди.","В верхней точке движения напрягите пресс и сделайте паузу на мгновение.","Медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos a los lados, con las palmas hacia abajo.","Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho.","En la parte más alta del movimiento, contrae el abdomen y haz una pausa breve.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1494","name":"butterfly yoga pose","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","groin"],"target":"adductors","image":"images/1494-bWlZvXh.jpg","gif_url":"videos/1494-bWlZvXh.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים מתוחות לפניכם.","כופפו ברכיים והצמידו את כפות הרגליים זו לזו, ותנו לברכיים ליפול לצדדים.","אחזו בקרסוליים או בכפות הרגליים עם הידיים.","שבו זקוף והאריכו את עמוד השדרה.","לחצו בעדינות את הברכיים מטה לכיוון הרצפה, עד תחושת מתיחה בירכיים הפנימיות.","החזיקו את התנוחה כמה נשימות.","לשחרור, החזירו באיטיות את הברכיים למעלה ויישרו את הרגליים."],"en":["Sit on the floor with your legs extended in front of you.","Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides.","Hold onto your ankles or feet with your hands.","Sit up tall and lengthen your spine.","Gently press your knees down towards the floor, feeling a stretch in your inner thighs.","Hold this position for a few breaths.","To release, slowly bring your knees back up and extend your legs."],"ru":["Сядьте на пол, вытянув ноги перед собой.","Согните колени и соедините подошвы ног вместе, позволяя коленям развалиться в стороны.","Держитесь руками за лодыжки или ступни.","Сядьте прямо и удлините позвоночник.","Аккуратно прижмите колени к полу, чувствуя растяжение внутренней поверхности бедер.","Задержитесь в этом положении на несколько вдохов.","Чтобы расслабиться, медленно поднимите колени вверх и выпрямите ноги."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti.","Flexiona las rodillas y junta las plantas de los pies, dejando que las rodillas caigan hacia los lados.","Sujétate los tobillos o los pies con las manos.","Siéntate erguido y alarga la columna.","Presiona suavemente las rodillas hacia el suelo, sintiendo un estiramiento en la parte interna de los muslos.","Mantén esta posición durante unas cuantas respiraciones.","Para liberar, lleva lentamente las rodillas hacia arriba de nuevo y extiende las piernas."]}},{"id":"0148","name":"cable alternate shoulder press","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0148-KHPZL0b.jpg","gif_url":"videos/0148-KHPZL0b.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים ואחזו בידיות מכשיר הכבלים באחיזה עליונה.","מקמו את הידיים בגובה הכתפיים, עם כפות ידיים פונות קדימה.","שמרו על ליבה מופעלת וגב ישר.","לחצו ידית אחת למעלה וקדימה עד יישור מלא של היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידית באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה עם היד השנייה.","החליפו בין הידיים לסירוגין למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip.","Position your hands at shoulder height, with your palms facing forward.","Keep your core engaged and your back straight.","Press one handle up and forward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."],"ru":["Встаньте, расставив ноги на ширине плеч, и возьмитесь за рукоятки канатного тренажера верхним хватом.","Расположите руки на уровне плеч, ладонями вперед.","Держите корпус напряженным, а спину прямой.","Нажмите одну ручку вверх и вперед, пока рука полностью не выпрямится.","Задержитесь на мгновение в верхней точке, затем медленно опустите рукоятку обратно в исходное положение.","Повторите с другой рукой.","Чередуйте руки, выполняя желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas de la máquina de cable con agarre prono.","Coloca las manos a la altura de los hombros, con las palmas mirando hacia adelante.","Mantén el core activado y la espalda recta.","Empuja una agarradera hacia arriba y hacia adelante hasta que el brazo quede completamente extendido.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.","Repite con el otro brazo.","Alterna entre los brazos el número de repeticiones deseado."]}},{"id":"0149","name":"cable alternate triceps extension","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0149-Gchi5Tr.jpg","gif_url":"videos/0149-Gchi5Tr.gif","instruction_steps":{"he":["עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","החזיקו את ידית הכבל ביד ימין והרימו את היד כך שהזרוע העליונה מקבילה לרצפה והמרפק כפוף בזווית של 90 מעלות.","שמרו על הזרוע העליונה ללא תזוזה ויישרו את האמה לאחור, עד יישור מלא של היד.","עצרו לרגע, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התנועה עם יד שמאל.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.","Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.","Pause for a moment, then slowly return to the starting position.","Repeat with your left arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмите рукоятку троса правой рукой и поднимите руку так, чтобы плечо было параллельно земле, а локоть был согнут под углом 90 градусов.","Держите плечо неподвижно и вытяните предплечье назад, полностью выпрямляя руку.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение.","Повторите то же самое с левой рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con la mano derecha y levanta el brazo de modo que el brazo superior quede paralelo al suelo y el codo flexionado en un ángulo de 90 grados.","Mantén el brazo superior quieto y extiende el antebrazo hacia atrás, estirando completamente el brazo.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite con el brazo izquierdo.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"3235","name":"cable assisted inverse leg curl","category":"upper legs","body_part":"upper legs","equipment":"cable","muscle_group":"glutes","secondary_muscles":["glutes","calves"],"target":"hamstrings","image":"images/3235-zHEpuuc.jpg","gif_url":"videos/3235-zHEpuuc.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים כך שרצועת הקרסול בתנוחה הנמוכה ביותר.","שכבו על הבטן על הספסל עם רגליים ישרות ורצועת הקרסול מקובעת לקרסוליים.","אחזו בידיות הספסל לייצוב.","תוך שמירה על פלג גוף עליון ללא תזוזה, נשפו וגלגלו את הרגליים למעלה לכיוון הישבן בכיפוף הברכיים.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הירך האחורית.","שאפו והורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable machine so that the ankle attachment is at the lowest setting.","Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles.","Hold onto the handles of the bench for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте тросовую машину так, чтобы крепление голеностопного сустава было на самом низком уровне.","Лягте лицом вниз на скамью, выпрямите ноги и закрепите фиксатор лодыжки на лодыжках.","Держитесь за ручки скамьи для устойчивости.","Удерживая верхнюю часть тела неподвижно, выдохните и согните ноги к ягодицам, согнув колени.","Задержитесь на мгновение в верхней точке движения, сжимая мышцы задней поверхности бедра.","Вдохните и медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de cable de modo que el accesorio para el tobillo quede en la posición más baja.","Túmbate boca abajo en el banco con las piernas rectas y el accesorio para el tobillo sujeto a los tobillos.","Sujétate de las agarraderas del banco para mantener la estabilidad.","Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales.","Inhala y baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0150","name":"cable bar lateral pulldown","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0150-eYnzaCm.jpg","gif_url":"videos/0150-eYnzaCm.gif","instruction_steps":{"he":["כווננו את גלגלת הכבל לתנוחה גבוהה וחברו מוט ישר.","שבו מול מכשיר הכבלים עם כפות רגליים על הרצפה וברכיים כפופות מעט.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היטו מעט לאחור ושמרו על חזה מורם, עם קשת קלה בגב התחתון.","משכו את המוט מטה לכיוון החזה, כשהמרפקים מובילים וכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, ואז החזירו באיטיות את המוט לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable pulley to a high position and attach a straight bar.","Sit facing the cable machine with your feet flat on the ground and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите тросовый шкив в верхнее положение и прикрепите прямую штангу.","Сядьте лицом к канатной машине, поставьте ступни на землю и слегка согните колени.","Возьмите штангу хватом сверху, на расстоянии чуть шире ширины плеч.","Слегка откиньтесь назад и держите грудь вверх, сохраняя небольшой изгиб в пояснице.","Потяните штангу вниз к груди, ведя локти и сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la polea del cable a una posición alta y coloca una barra recta.","Siéntate frente a la máquina de cable con los pies planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar.","Tira de la barra hacia el pecho, guiando el movimiento con los codos y juntando los omóplatos.","Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0151","name":"cable bench press","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0151-7xI5MXA.jpg","gif_url":"videos/0151-7xI5MXA.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים לגובה החזה וחברו את הידיות.","עמדו עם הגב למכשיר, רגליים ברוחב כתפיים.","אחזו בידיות באחיזה עליונה וצעדו קדימה ליצירת מתח בכבלים.","נטעו את כפות הרגליים היטב ברצפה והפעילו את הליבה.","כופפו מרפקים והביאו את הידיים לגובה הכתפיים, תוך שמירה על מרפקים בזווית של 90 מעלות.","דחפו את הידיות קדימה, עד יישור מלא של הידיים לפניכם.","עצרו לרגע, ואז הפכו באיטיות את התנועה והחזירו את הידיים לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable machine to chest height and attach the handles.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step forward to create tension in the cables.","Position your feet firmly on the ground and engage your core.","Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle.","Push the handles forward, extending your arms fully in front of you.","Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте канатную машину на высоту груди и прикрепите ручки.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмитесь за рукоятки верхним хватом и сделайте шаг вперед, чтобы создать натяжение тросов.","Твердо поставьте ноги на землю и задействуйте корпус.","Согните руки в локтях и поднимите руки на уровень плеч, держа локти под углом 90 градусов.","Выдвиньте рукоятки вперед, полностью вытянув руки перед собой.","Сделайте паузу на мгновение, затем медленно поменяйте направление движения, возвращая руки на уровень плеч.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de cable a la altura del pecho y coloca las agarraderas.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta las agarraderas con agarre prono y da un paso hacia adelante para crear tensión en los cables.","Coloca los pies firmemente en el suelo y activa el core.","Flexiona los codos y lleva las manos a la altura de los hombros, manteniendo los codos en un ángulo de 90 grados.","Empuja las agarraderas hacia adelante, extendiendo completamente los brazos frente a ti.","Haz una pausa breve, luego invierte lentamente el movimiento, llevando las manos de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"1630","name":"cable close grip curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1630-BCGQ6J5.jpg","gif_url":"videos/1630-BCGQ6J5.gif","instruction_steps":{"he":["חברו מוט ישר למכשיר כבלים בגלגלת תחתונה.","עמדו מול המכשיר עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","אחזו במוט באחיזה תחתונה, ידיים ברוחב כתפיים.","שמרו על מרפקים צמודים לצידי הגוף וזרועות עליונות ללא תזוזה לאורך כל התרגיל.","נשפו וכופפו את המוט למעלה לכיוון הכתפיים, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатной машине с низким шкивом.","Встаньте лицом к тренажеру, ноги на ширине плеч и слегка согнуты в коленях.","Возьмитесь за перекладину хватом снизу, руки на ширине плеч.","На протяжении всего упражнения держите локти близко к бокам, а плечи неподвижными.","Выдохните и поднимите штангу к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Вдохните и медленно опустите штангу обратно в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Coloca una barra recta en una máquina de cable con polea baja.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1631","name":"cable concentration curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1631-NvfE43H.jpg","gif_url":"videos/1631-NvfE43H.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם כפות רגליים על הרצפה וברכיים כפופות מעט.","החזיקו את ידית הכבל באחיזה תחתונה והשעינו את המרפק על החלק הפנימי של הירך.","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את ידית הכבל לכיוון הכתף תוך כיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, ואז שאפו והורידו את ידית הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.","Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh.","Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью или стул, поставьте ступни на пол и слегка согните колени.","Возьмите рукоятку троса обратным хватом снизу и прижмите локоть к внутренней стороне бедра.","Удерживая плечо неподвижно, выдохните и согните рукоятку троса к плечу, одновременно напрягая бицепс.","Сделайте паузу на мгновение в верхней точке движения, затем вдохните и медленно опустите рукоятку троса обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco o silla con los pies planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta la agarradera del cable con agarre supino y apoya el codo en la parte interna del muslo.","Manteniendo el brazo superior quieto, exhala y flexiona la agarradera del cable hacia el hombro contrayendo el bíceps.","Haz una pausa breve en la parte más alta del movimiento, luego inhala y baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0152","name":"cable concentration extension (on knee)","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0152-Db7eEgw.jpg","gif_url":"videos/0152-Db7eEgw.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם ברכיים כפופות וכפות רגליים על הרצפה.","החזיקו את ידית הכבל ביד ימין והניחו את המרפק על החלק הפנימי של ברך ימין.","יישרו את היד לגמרי, תוך שמירה על המרפק ללא תזוזה וקרוב לברך.","עצרו לרגע בנקודה העליונה, ואז הורידו את היד באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Sit on a bench or chair with your knees bent and feet flat on the ground.","Hold the cable handle with your right hand and place your elbow on the inside of your right knee.","Extend your arm fully, keeping your elbow stationary and close to your knee.","Pause for a moment at the top, then slowly lower your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Сядьте на скамью или стул, согните колени и поставьте ступни на землю.","Возьмите рукоятку троса правой рукой и поместите локоть на внутреннюю часть правого колена.","Полностью выпрямите руку, держа локоть неподвижно и близко к колену.","Задержитесь на мгновение в верхней точке, затем медленно опустите руку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Siéntate en un banco o silla con las rodillas flexionadas y los pies planos en el suelo.","Sujeta la agarradera del cable con la mano derecha y coloca el codo en la parte interna de la rodilla derecha.","Extiende completamente el brazo, manteniendo el codo quieto y cerca de la rodilla.","Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0153","name":"cable cross-over lateral pulldown","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0153-OQ1otBN.jpg","gif_url":"videos/0153-OQ1otBN.gif","instruction_steps":{"he":["חברו ידית כבל לכל צד של מכשיר הכבלים בגובה הכתפיים.","עמדו במרכז המכשיר עם רגליים ברוחב כתפיים.","אחזו בידיות באחיזה עליונה וצעדו לאחור ליצירת מתח בכבלים.","רכנו מעט קדימה מהירכיים, תוך שמירה על גב ישר וחזה מורם.","משכו את הידיות מטה ובאלכסון על פני הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a cable handle to each side of a cable machine at shoulder height.","Stand in the middle of the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step back to create tension in the cables.","Lean forward slightly from the hips, keeping your back straight and your chest up.","Pull the handles down and across your body, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите рукоятку для троса к каждой стороне канатной машины на высоте плеч.","Встаньте посередине тренажера, поставив ноги на ширине плеч.","Возьмитесь за рукоятки верхним хватом и отступите назад, чтобы создать натяжение тросов.","Слегка наклонитесь вперед от бедер, держа спину прямо и грудь вверх.","Потяните ручки вниз и поперек тела, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca una agarradera de cable en cada lado de una máquina de cable a la altura de los hombros.","Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros.","Sujeta las agarraderas con agarre prono y da un paso hacia atrás para crear tensión en los cables.","Inclínate ligeramente hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Tira de las agarraderas hacia abajo y a través del cuerpo, juntando los omóplatos.","Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0154","name":"cable cross-over revers fly","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"rhomboids","secondary_muscles":["rhomboids","trapezius"],"target":"delts","image":"images/0154-aqvSOQE.jpg","gif_url":"videos/0154-aqvSOQE.gif","instruction_steps":{"he":["חברו ידית D לכל כבל גלגלת תחתונה ועמדו במרכז מכשיר הקרוס-אובר.","אחזו בידיות באחיזה עליונה (כפות ידיים כלפי מטה) וצעדו קדימה, במיקום הרגליים ברוחב כתפיים.","כופפו ברכיים מעט והטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר ובטן מופעלת.","עם ידיים מתוחות לצדדים וכפופות מעט במרפקים, נשפו וכווצו את השכמות זו לזו תוך משיכת הכבלים לאחור ולמעלה בתנועת פרפר הפוך.","עצרו לרגע בשיא הכיווץ, ואז שאפו וחזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.","Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart.","Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.","With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите D-образную рукоятку к каждому тросу нижнего шкива и встаньте в середину машины для пересечения тросов.","Возьмитесь за рукоятки пронированным хватом (ладонями вниз) и сделайте шаг вперед, поставив ноги на ширине плеч.","Слегка согните колени и наклонитесь вперед в талии, сохраняя спину прямой и напряженный пресс.","Вытянув руки в стороны и слегка согнув их в локтях, выдохните и сведите лопатки вместе, одновременно ведя тросы назад и вверх в обратном движении.","Сделайте паузу на мгновение в момент максимального сокращения, затем вдохните и медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca una agarradera en D en cada cable de polea baja y ponte de pie en el centro de la máquina de cable cruzado.","Sujeta las agarraderas con agarre prono (palmas hacia abajo) y da un paso hacia adelante, colocando los pies separados a la altura de los hombros.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el abdomen activado.","Con los brazos extendidos hacia los lados y ligeramente flexionados en los codos, exhala y junta los omóplatos mientras tiras de los cables hacia atrás y hacia arriba en un movimiento de apertura inversa.","Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0155","name":"cable cross-over variation","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0155-0CXGHya.jpg","gif_url":"videos/0155-0CXGHya.gif","instruction_steps":{"he":["כווננו את גלגלות הכבל לגובה החזה.","עמדו במרכז מכשיר הכבלים עם כף רגל אחת לפני השנייה.","אחזו בידיות עם כפות ידיים כלפי מטה וידיים מתוחות לצדדים.","צעדו צעד קדימה, תוך שמירה על ידיים כפופות מעט.","עם כיפוף קל במרפקים, הביאו את הידיים יחד מול החזה.","עצרו לרגע, ואז החזירו את הידיים באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable pulleys to chest height.","Stand in the center of the cable machine with one foot in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Take a step forward, keeping your arms slightly bent.","With a slight bend in your elbows, bring your hands together in front of your chest.","Pause for a moment, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте шкивы троса на высоту груди.","Встаньте в центр канатной машины, поставив одну ногу перед другой.","Возьмитесь за ручки ладонями вниз и вытяните руки в стороны.","Сделайте шаг вперед, держа руки слегка согнутыми.","Слегка согнув локти, соедините руки перед грудью.","Сделайте паузу на мгновение, затем медленно верните руки в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta las poleas del cable a la altura del pecho.","Ponte de pie en el centro de la máquina de cable con un pie delante del otro.","Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados.","Da un paso hacia adelante, manteniendo los brazos ligeramente flexionados.","Con una ligera flexión en los codos, junta las manos frente al pecho.","Haz una pausa breve, luego vuelve lentamente los brazos a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0868","name":"cable curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0868-G08RZcQ.jpg","gif_url":"videos/0868-G08RZcQ.gif","instruction_steps":{"he":["עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","אחזו באביזר הכבל באחיזה תחתונה, כפות ידיים כלפי מעלה.","שמרו על מרפקים צמודים לגוף וזרועות עליונות ללא תזוזה.","נשפו וכופפו את אביזר הכבל לכיוון הכתפיים, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","שאפו והורידו את אביזר הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable attachment with an underhand grip, palms facing up.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмитесь за блочное крепление снизу ладонями вверх.","Держите локти близко к бокам, а плечи неподвижно.","Выдохните и согните трос к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Вдохните и медленно опустите тросовое крепление обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta el accesorio del cable con agarre supino, palmas hacia arriba.","Mantén los codos cerca de los costados y los brazos superiores quietos.","Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0157","name":"cable deadlift","category":"upper legs","body_part":"upper legs","equipment":"cable","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"target":"glutes","image":"images/0157-eGDudUV.jpg","gif_url":"videos/0157-eGDudUV.gif","instruction_steps":{"he":["עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","כופפו ירכיים וברכיים, בהורדת הגו עד שהגב מקביל לרצפה.","אחזו בידיות הכבל באחיזה עליונה, תוך שמירה על ידיים ישרות וכתפיים לאחור.","הפעילו את הישבן והירך האחורית להרמת ידיות הכבל, ביישור הירכיים ועמידה זקופה.","עצרו לרגע בנקודה העליונה, ואז הורידו את ידיות הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing the cable machine with your feet shoulder-width apart.","Bend at the hips and knees, lowering your torso until your back is parallel to the ground.","Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back.","Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight.","Pause for a moment at the top, then slowly lower the cable handles back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Согните бедра и колени, опуская туловище до тех пор, пока спина не станет параллельна земле.","Возьмитесь за рукоятки троса верхним хватом, держа руки прямыми, а плечи отведенными назад.","Задействуйте ягодицы и мышцы задней поверхности бедра, чтобы поднять рукоятки троса, выпрямив бедра и встав прямо.","Задержитесь на мгновение в верхней точке, затем медленно опустите рукоятки троса обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Flexiona las caderas y las rodillas, bajando el torso hasta que la espalda quede paralela al suelo.","Sujeta las agarraderas del cable con agarre prono, manteniendo los brazos rectos y los hombros hacia atrás.","Activa los glúteos y los isquiotibiales para levantar las agarraderas del cable, extendiendo las caderas y poniéndote de pie.","Haz una pausa breve en la parte más alta, luego baja lentamente las agarraderas del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0158","name":"cable decline fly","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0158-7saC5zz.jpg","gif_url":"videos/0158-7saC5zz.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים לתנוחת שיפוע שלילי.","עמדו עם הגב למכשיר, רגליים ברוחב כתפיים.","החזיקו את הידיות עם כפות ידיים פונות קדימה וידיים מתוחות ישר לפניכם.","עם כיפוף קל במרפקים, פתחו את הידיים לצדדים בתנועה מבוקרת.","עצרו לרגע במתיחה המלאה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable machine to a decline position.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the handles with your palms facing forward and your arms extended straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте тросную машину в положение опускания.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмитесь за ручки ладонями вперед и вытяните руки прямо перед собой.","Сохраняя небольшой изгиб в локтях, контролируемым движением разведите руки в стороны.","Задержитесь на мгновение в полностью выпрямленном положении, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de cable a una posición declinada.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta las agarraderas con las palmas hacia adelante y los brazos extendidos rectos frente a ti.","Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado.","Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1260","name":"cable decline one arm press","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1260-KHGNa16.jpg","gif_url":"videos/1260-KHGNa16.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים לתנוחת שיפוע שלילי.","עמדו עם הגב למכשיר ואחזו בידית ביד אחת.","התמקמו כשהגב צמוד לספסל השיפוע השלילי והיד מתוחה ישר לפניכם.","כופפו את המרפק והורידו את הידית לכיוון החזה, תוך שמירה על הזרוע העליונה ללא תזוזה.","עצרו לרגע בנקודה התחתונה, ואז דחפו את הידית חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Adjust the cable machine to a decline position.","Stand facing away from the machine and grab the handle with one hand.","Position yourself with your back against the decline bench and your arm extended straight in front of you.","Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary.","Pause for a moment at the bottom, then push the handle back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Отрегулируйте тросную машину в положение опускания.","Встаньте лицом к машине и возьмитесь за ручку одной рукой.","Встаньте спиной к скамье для наклонов и вытяните руку прямо перед собой.","Согните локоть и опустите рукоятку к груди, сохраняя плечо неподвижным.","Задержитесь на мгновение внизу, затем верните ручку вверх в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ajusta la máquina de cable a una posición declinada.","Ponte de pie de espaldas a la máquina y sujeta la agarradera con una mano.","Colócate con la espalda contra el banco declinado y el brazo extendido recto frente a ti.","Flexiona el codo y baja la agarradera hacia el pecho, manteniendo el brazo superior quieto.","Haz una pausa breve en la parte más baja, luego empuja la agarradera de vuelta hacia la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1261","name":"cable decline press","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1261-2Pya1cP.jpg","gif_url":"videos/1261-2Pya1cP.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים לתנוחת שיפוע שלילי.","שבו על ספסל השיפוע השלילי מול מכשיר הכבלים.","אחזו בידיות באחיזה עליונה ומקמו אותן בגובה החזה.","שמרו על כפות רגליים על הרצפה והגב צמוד היטב לספסל.","נשפו ודחפו את הידיות הרחק מהגוף, עד יישור מלא של הידיים.","עצרו לרגע בסוף התנועה, תוך כיווץ שרירי החזה.","שאפו והחזירו את הידיות באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable machine to a decline position.","Sit on the decline bench facing the cable machine.","Grasp the handles with an overhand grip and position them at chest level.","Keep your feet flat on the ground and your back firmly against the bench.","Exhale and push the handles away from your body, extending your arms fully.","Pause for a moment at the end of the movement, squeezing your chest muscles.","Inhale and slowly return the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте тросную машину в положение опускания.","Сядьте на наклонную скамью лицом к канатной машине.","Возьмитесь за ручки верхним хватом и расположите их на уровне груди.","Держите ноги ровно на земле, а спину крепко прижимайте к скамье.","Выдохните и оттолкните ручки от тела, полностью выпрямляя руки.","В конце движения задержитесь на мгновение, напрягая мышцы груди.","Вдохните и медленно верните ручки в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de cable a una posición declinada.","Siéntate en el banco declinado frente a la máquina de cable.","Sujeta las agarraderas con agarre prono y colócalas a la altura del pecho.","Mantén los pies planos en el suelo y la espalda firmemente apoyada en el banco.","Exhala y empuja las agarraderas alejándolas del cuerpo, extendiendo completamente los brazos.","Haz una pausa breve al final del movimiento, contrayendo los músculos del pecho.","Inhala y vuelve lentamente las agarraderas a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0159","name":"cable decline seated wide-grip row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0159-kesXOpB.jpg","gif_url":"videos/0159-kesXOpB.gif","instruction_steps":{"he":["שבו על ספסל השיפוע השלילי מול מכשיר הכבלים, כשכפות הרגליים מקובעות היטב על משענות הרגליים.","אחזו באביזר הכבל באחיזה עליונה רחבה, כפות ידיים כלפי מטה.","היטו את הגוף מעט לאחור, תוך שמירה על גב ישר וליבה מופעלת.","משכו את הכבל לכיוון החזה התחתון, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא הכיווץ, ואז שחררו באיטיות את הכבל חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the decline bench facing the cable machine with your feet securely placed on the footrests.","Grasp the cable attachment with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на наклонную скамью лицом к канатной машине, надежно поставив ноги на подножки.","Возьмите блочное крепление широким хватом сверху ладонями вниз.","Слегка откиньтесь назад, сохраняя спину прямой и напряженный корпус.","Потяните трос к нижней части груди, сжимая лопатки вместе.","Сделайте паузу на мгновение на пике сокращения, затем медленно отпустите трос обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el banco declinado frente a la máquina de cable con los pies firmemente colocados en los reposapiés.","Sujeta el accesorio del cable con un agarre prono amplio, palmas hacia abajo.","Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado.","Tira del cable hacia la parte inferior del pecho, juntando los omóplatos.","Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1632","name":"cable drag curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1632-dXz8zjF.jpg","gif_url":"videos/1632-dXz8zjF.gif","instruction_steps":{"he":["עמדו מול מכשיר כבלים עם רגליים ברוחב כתפיים.","אחזו באביזר הכבל באחיזה תחתונה, כפות ידיים כלפי מעלה, וידיים ישרות לגמרי.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את אביזר הכבל לכיוון הכתפיים בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","שאפו והורידו את אביזר הכבל באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмитесь за блочное крепление обратным хватом, ладонями вверх и полностью выпрямленными руками.","Удерживая плечи неподвижно, выдохните и согните трос к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Вдохните и медленно опустите трос обратно в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujeta el accesorio del cable con agarre supino, palmas hacia arriba, y los brazos completamente extendidos.","Manteniendo los brazos superiores quietos, exhala y flexiona el accesorio del cable hacia los hombros contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0160","name":"cable floor seated wide-grip row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0160-veXwo0D.jpg","gif_url":"videos/0160-veXwo0D.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים מתוחות וגב ישר.","חברו ידית כבל לגלגלת תחתונה ומקמו את מכשיר הכבלים מאחוריכם.","אחזו בידית באחיזה עליונה רחבה, כפות ידיים כלפי מטה.","היטו מעט לאחור, תוך שמירה על גב ישר וחזה מורם.","משכו את הידית לכיוון המותניים, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה, ואז שחררו באיטיות את הידית חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the floor with your legs extended and your back straight.","Attach a cable handle to a low pulley and position the cable machine behind you.","Grasp the handle with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your chest lifted.","Pull the handle towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на пол, вытянув ноги и выпрямив спину.","Прикрепите рукоятку троса к низкому шкиву и расположите тросовую машину позади себя.","Возьмите рукоятку широким хватом сверху ладонями вниз.","Слегка откиньтесь назад, сохраняя спину прямой и приподняв грудь.","Потяните ручку к талии, сжимая лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения, затем медленно отпустите рукоятку обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el suelo con las piernas extendidas y la espalda recta.","Coloca una agarradera de cable en una polea baja y ubica la máquina de cable detrás de ti.","Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo.","Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado.","Tira de la agarradera hacia la cintura, juntando los omóplatos.","Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0161","name":"cable forward raise","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"triceps","secondary_muscles":["triceps","forearms"],"target":"delts","image":"images/0161-hvHhCv8.jpg","gif_url":"videos/0161-hvHhCv8.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","החזיקו את ידית הכבל באחיזה עליונה, כפות ידיים כלפי מטה, וידיים מתוחות לגמרי לפניכם.","תוך שמירה על ידיים ישרות, הרימו את ידית הכבל לגובה הכתפיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את ידית הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you.","Keeping your arms straight, raise the cable handle up to shoulder level.","Pause for a moment at the top, then slowly lower the cable handle back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Держите рукоятку троса хватом сверху, ладонями вниз, а руки полностью вытянуты перед собой.","Держа руки прямыми, поднимите рукоятку троса до уровня плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите рукоятку троса обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la agarradera del cable con agarre prono, palmas hacia abajo, y los brazos completamente extendidos frente a ti.","Manteniendo los brazos rectos, levanta la agarradera del cable hasta la altura de los hombros.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0162","name":"cable front raise","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"triceps","secondary_muscles":["triceps","forearms"],"target":"delts","image":"images/0162-u2X71Np.jpg","gif_url":"videos/0162-u2X71Np.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים ואחזו בידית הכבל באחיזה עליונה.","שמרו על גב ישר וליבה מופעלת.","הרימו את ידית הכבל לפניכם, תוך שמירה על ידיים ישרות וכפות ידיים כלפי מטה.","המשיכו להרים עד שהידיים מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את ידית הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмитесь за рукоятку троса хватом сверху.","Держите спину прямо, а корпус напряженным.","Поднимите рукоятку троса перед собой, держа руки прямыми и ладонями вниз.","Продолжайте подъем, пока ваши руки не станут параллельны полу.","Задержитесь на мгновение в верхней точке, затем медленно опустите рукоятку троса обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono.","Mantén la espalda recta y el core activado.","Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.","Continúa levantando hasta que los brazos queden paralelos al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0164","name":"cable front shoulder raise","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"trapezius","secondary_muscles":["trapezius","biceps"],"target":"delts","image":"images/0164-mTT3KLn.jpg","gif_url":"videos/0164-mTT3KLn.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים ואחזו בידית הכבל באחיזה עליונה.","שמרו על גב ישר וליבה מופעלת.","הרימו את ידית הכבל לפניכם, תוך שמירה על ידיים ישרות וכפות ידיים כלפי מטה.","המשיכו להרים עד שהידיים מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את ידית הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмитесь за рукоятку троса хватом сверху.","Держите спину прямо, а корпус напряженным.","Поднимите рукоятку троса перед собой, держа руки прямыми и ладонями вниз.","Продолжайте подъем, пока ваши руки не станут параллельны полу.","Задержитесь на мгновение в верхней точке, затем медленно опустите рукоятку троса обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono.","Mantén la espalda recta y el core activado.","Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.","Continúa levantando hasta que los brazos queden paralelos al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0165","name":"cable hammer curl (with rope)","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0165-HPlPoQA.jpg","gif_url":"videos/0165-HPlPoQA.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים וכיפוף קל בברכיים.","אחזו בחבל הכבל באחיזה תחתונה, כפות ידיים פונות זו לזו, וידיים ישרות לגמרי.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את חבל הכבל עד שהבייספס מכווץ במלואו והחבל בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד באיטיות את חבל הכבל חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand upright with your feet shoulder-width apart and a slight bend in your knees.","Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the cable rope attachment back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч и слегка согните колени.","Держите тросовое крепление обратным хватом снизу, ладони обращены друг к другу, руки полностью выпрямлены.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать веревку до тех пор, пока ваши бицепсы полностью не сократятся и веревка не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать трос обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.","Sujeta el accesorio de cuerda del cable con agarre supino, palmas mirándose entre sí, y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando el accesorio de cuerda del cable hasta que los bíceps estén completamente contraídos y la cuerda esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente el accesorio de cuerda del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1722","name":"cable high pulley overhead tricep extension","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1722-1xHyxys.jpg","gif_url":"videos/1722-1xHyxys.gif","instruction_steps":{"he":["חברו חבל לגלגלת עליונה ועמדו עם הגב למכשיר.","אחזו בחבל בשתי ידיים ומתחו את הידיים מעל הראש.","שמרו על מרפקים קרובים לראש וזרועות עליונות ללא תזוזה.","הורידו באיטיות את החבל מאחורי הראש בכיפוף המרפקים.","עצרו לרגע, ואז יישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope to a high pulley and stand facing away from the machine.","Grasp the rope with both hands and extend your arms overhead.","Keep your elbows close to your head and your upper arms stationary.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к высокому шкиву и встаньте лицом от машины.","Возьмите веревку обеими руками и вытяните руки над головой.","Держите локти близко к голове, а плечи неподвижно.","Медленно опустите веревку за голову, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca una cuerda en una polea alta y ponte de pie de espaldas a la máquina.","Sujeta la cuerda con ambas manos y extiende los brazos por encima de la cabeza.","Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil.","Baja lentamente la cuerda detrás de la cabeza flexionando los codos.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0167","name":"cable high row (kneeling)","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0167-ZSJNetl.jpg","gif_url":"videos/0167-ZSJNetl.gif","instruction_steps":{"he":["חברו מוט ישר למכשיר כבלים בגובה החזה.","כרעו מול מכשיר הכבלים ואחזו במוט באחיזה עליונה, ידיים ברוחב כתפיים.","שבו לאחור על העקבים, תוך שמירה על גב ישר וליבה מופעלת.","משכו את המוט לכיוון הבטן העליונה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה, ואז שחררו באיטיות את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to a cable machine at chest height.","Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart.","Sit back on your heels, keeping your back straight and your core engaged.","Pull the bar towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатному тренажеру на уровне груди.","Встаньте на колени перед канатным тренажером и возьмитесь за перекладину хватом сверху, руки на ширине плеч.","Сядьте на пятки, держа спину прямо и напрягая корпус.","Потяните штангу к верхней части живота, сжимая лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения, затем медленно отпустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una barra recta a una máquina de cable a la altura del pecho.","Ponte de rodillas frente a la máquina de cable y agarra la barra con un agarre prono, con las manos separadas a la altura de los hombros.","Siéntate sobre los talones, manteniendo la espalda recta y el core activado.","Jala la barra hacia la parte superior del abdomen, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte más alta del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0168","name":"cable hip adduction","category":"upper legs","body_part":"upper legs","equipment":"cable","muscle_group":"glutes","secondary_muscles":["glutes","quadriceps"],"target":"adductors","image":"images/0168-hBGWILP.jpg","gif_url":"videos/0168-hBGWILP.gif","instruction_steps":{"he":["חברו את רצועת הקרסול לקרסול ועמדו מול מכשיר הכבלים.","התמקמו מספיק רחוק מהמכשיר כך שיהיה מתח בכבל.","הניחו את הידיים על המכשיר לתמיכה.","תוך שמירה על רגל ישרה, הזיזו אותה באיטיות על פני הגוף לכיוון קו האמצע.","עצרו לרגע בסוף התנועה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the ankle cuff to your ankle and stand facing the cable machine.","Position yourself far enough away from the machine so that there is tension on the cable.","Place your hands on the machine for support.","Keeping your leg straight, slowly move your leg across your body towards the midline.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите манжету на лодыжку и встаньте лицом к канатной машине.","Расположитесь достаточно далеко от машины, чтобы трос был натянут.","Положите руки на машину для поддержки.","Удерживая ногу прямой, медленно перемещайте ногу поперек тела к средней линии.","Сделайте небольшую паузу в конце движения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta el manguito de tobillo a tu tobillo y ponte de pie frente a la máquina de cable.","Colócate lo suficientemente alejado de la máquina para que haya tensión en el cable.","Coloca las manos sobre la máquina para apoyarte.","Manteniendo la pierna recta, mueve lentamente la pierna por delante del cuerpo hacia la línea media.","Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0169","name":"cable incline bench press","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0169-Vh0GsK4.jpg","gif_url":"videos/0169-Vh0GsK4.gif","instruction_steps":{"he":["כווננו את הספסל לשיפוע של 45 מעלות.","חברו את ידיות הכבל לגלגלות העליונות.","שבו על הספסל מול מכשיר הכבלים עם כפות רגליים על הרצפה.","אחזו בידיות באחיזה עליונה והביאו אותן לגובה הכתפיים.","דחפו את הידיות קדימה ולמעלה עד יישור מלא של הידיים.","עצרו לרגע, ואז הורידו את הידיות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the bench to a 45-degree incline.","Attach the cable handles to the high pulleys.","Sit on the bench facing the cable machine with your feet flat on the ground.","Grasp the handles with an overhand grip and bring them to shoulder height.","Push the handles forward and upward until your arms are fully extended.","Pause for a moment, then slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте скамью под углом 45 градусов.","Прикрепите ручки троса к высоким шкивам.","Сядьте на скамью лицом к канатной машине, поставив ноги на землю.","Возьмитесь за ручки верхним хватом и поднимите их на высоту плеч.","Толкайте ручки вперед и вверх, пока руки полностью не выпрямятся.","Сделайте паузу на мгновение, затем медленно опустите рукоятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta el banco a una inclinación de 45 grados.","Sujeta las agarraderas del cable a las poleas altas.","Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo.","Sujeta las agarraderas con un agarre prono y llévalas a la altura de los hombros.","Empuja las agarraderas hacia adelante y hacia arriba hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento y luego baja lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1318","name":"cable incline bench row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","rear deltoids"],"target":"upper back","image":"images/1318-yaMIo4D.jpg","gif_url":"videos/1318-yaMIo4D.gif","instruction_steps":{"he":["הכינו ספסל שיפוע בזווית של 45 מעלות וחברו ידית כבל לגלגלת התחתונה.","שבו על הספסל מול מכשיר הכבלים עם כפות רגליים על הרצפה וברכיים כפופות מעט.","אחזו בידית הכבל באחיזה עליונה ומתחו את הידיים לגמרי לפניכם.","רכנו קדימה מהירכיים, תוך שמירה על גב ישר וליבה מופעלת.","משכו את ידית הכבל לכיוון החזה בכיווץ השכמות לאחור וכיפוף המרפקים.","כווצו את שרירי הגב בנקודה העליונה של התנועה, ואז יישרו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.","Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the cable handle with an overhand grip and extend your arms fully in front of you.","Lean forward from your hips while keeping your back straight and your core engaged.","Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows.","Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов и прикрепите тросовую ручку к нижнему шкиву.","Сядьте на скамью лицом к блочному тренажеру, поставьте ступни на пол и слегка согните колени.","Возьмитесь за рукоятку троса верхним хватом и вытяните руки полностью перед собой.","Наклонитесь вперед от бедер, сохраняя при этом спину прямой и напряженный корпус.","Потяните рукоятку троса к груди, сводя лопатки и сгибая локти.","Напрягите мышцы спины в верхней точке движения, затем медленно вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados y sujeta una agarradera de cable a la polea baja.","Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta la agarradera del cable con un agarre prono y extiende los brazos completamente frente a ti.","Inclínate hacia adelante desde las caderas manteniendo la espalda recta y el core activado.","Jala la agarradera del cable hacia el pecho retrayendo los omóplatos y flexionando los codos.","Aprieta los músculos de la espalda en la parte más alta del movimiento y luego extiende lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0171","name":"cable incline fly","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0171-tBWXbIT.jpg","gif_url":"videos/0171-tBWXbIT.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים לתנוחה נמוכה וחברו את הידיות.","שבו על ספסל שיפוע כשהגב צמוד לכרית וכפות הרגליים על הרצפה.","אחזו בידיות באחיזה עליונה ומתחו את הידיים ישר לפניכם.","עם כיפוף קל במרפקים, פתחו את הידיים לצדדים בתנועה מבוקרת.","עצרו לרגע במתיחה המלאה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable machine to a low position and attach the handles.","Sit on an incline bench with your back against the pad and feet flat on the floor.","Grasp the handles with an overhand grip and extend your arms straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите тросовую машину в нижнее положение и прикрепите ручки.","Сядьте на наклонную скамью, прислонившись спиной к подушке, а ступни поставьте на пол.","Возьмитесь за рукоятки верхним хватом и вытяните руки прямо перед собой.","Сохраняя небольшой изгиб в локтях, контролируемым движением разведите руки в стороны.","Задержитесь на мгновение в полностью выпрямленном положении, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de cable a una posición baja y sujeta las agarraderas.","Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo.","Sujeta las agarraderas con un agarre prono y extiende los brazos rectos frente a ti.","Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado.","Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0170","name":"cable incline fly (on stability ball)","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0170-27NNGFr.jpg","gif_url":"videos/0170-27NNGFr.gif","instruction_steps":{"he":["הכינו כדור פיזיו בזווית שיפוע.","חברו את ידיות הכבל לגלגלות העליונות של מכשיר הכבלים.","שבו על כדור הפיזיו עם הגב למכשיר, כשכפות הרגליים נטועות היטב ברצפה.","אחזו בידיות הכבל באחיזה עליונה, כפות ידיים פונות קדימה.","רכנו מעט קדימה, תוך שמירה על גב ישר וליבה מופעלת.","בתנועה מבוקרת, הביאו את הידיים לצדדים, עם כיפוף קל במרפקים.","המשיכו בתנועה עד שהידיים מקבילות לרצפה.","עצרו לרגע, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up a stability ball at an incline angle.","Attach the cable handles to the high pulleys of a cable machine.","Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground.","Grasp the cable handles with an overhand grip, palms facing forward.","Lean forward slightly, keeping your back straight and core engaged.","With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows.","Continue the motion until your arms are parallel to the ground.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите мяч для стабилизации под углом наклона.","Прикрепите рукоятки троса к высоким шкивам канатной машины.","Сядьте на стабилизирующий шар лицом в сторону от машины, твердо поставьте ноги на землю.","Возьмитесь за рукоятки троса верхним хватом, ладонями вперед.","Слегка наклонитесь вперед, сохраняя спину прямой и напряженным корпусом.","Контролируемым движением разведите руки в стороны, сохраняя небольшой изгиб в локтях.","Продолжайте движение, пока ваши руки не станут параллельны земле.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un balón de estabilidad en un ángulo inclinado.","Sujeta las agarraderas del cable a las poleas altas de una máquina de cable.","Siéntate sobre el balón de estabilidad de espaldas a la máquina, con los pies firmemente apoyados en el suelo.","Sujeta las agarraderas del cable con un agarre prono, con las palmas hacia adelante.","Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado.","Con un movimiento controlado, lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos.","Continúa el movimiento hasta que los brazos queden paralelos al suelo.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0172","name":"cable incline pushdown","category":"back","body_part":"back","equipment":"cable","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"lats","image":"images/0172-1PK5Uo3.jpg","gif_url":"videos/0172-1PK5Uo3.gif","instruction_steps":{"he":["חברו מוט ישר לגלגלת עליונה במכשיר הכבלים.","עמדו עם הגב למכשיר, רגליים ברוחב כתפיים.","אחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","רכנו מעט קדימה ושמרו על גב ישר.","משכו את המוט מטה לכיוון הירכיים ביישור המרפקים.","עצרו לרגע בנקודה התחתונה, ואז החזירו באיטיות את המוט לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to a high pulley cable machine.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Lean forward slightly and keep your back straight.","Pull the bar down towards your thighs by extending your elbows.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатной машине с высоким шкивом.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмите перекладину хватом сверху, руки на расстоянии чуть шире плеч.","Слегка наклонитесь вперед и держите спину прямо.","Потяните штангу вниз к бедрам, разгибая локти.","Задержитесь на мгновение в нижней точке, затем медленно верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una barra recta a una máquina de cable con polea alta.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Inclínate ligeramente hacia adelante y mantén la espalda recta.","Jala la barra hacia abajo en dirección a tus muslos extendiendo los codos.","Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0173","name":"cable incline triceps extension","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0173-Hx1WC8I.jpg","gif_url":"videos/0173-Hx1WC8I.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים לתנוחת גלגלת תחתונה.","חברו מוט ישר לכבל.","עמדו עם הגב למכשיר, רגליים ברוחב כתפיים.","אחזו במוט באחיזה עליונה ומתחו את הידיים ישר מעל הראש.","רכנו מעט קדימה, תוך שמירה על גב ישר וליבה מופעלת.","כופפו מרפקים והורידו את המוט מאחורי הראש, תוך שמירה על הזרועות העליונות צמודות לאוזניים.","עצרו לרגע, ואז יישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable machine to a low pulley position.","Attach a straight bar to the cable.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip and extend your arms straight overhead.","Lean forward slightly, keeping your back straight and core engaged.","Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте тросовую машину в нижнее положение шкива.","Прикрепите к кабелю прямую перекладину.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмите штангу хватом сверху и вытяните руки прямо над головой.","Слегка наклонитесь вперед, сохраняя спину прямой и напряженным корпусом.","Согните руки в локтях и опустите штангу за голову, держа плечи близко к ушам.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de cable a una posición de polea baja.","Sujeta una barra recta al cable.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre prono y extiende los brazos rectos por encima de la cabeza.","Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado.","Flexiona los codos y baja la barra detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0174","name":"cable judo flip","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"obliques","secondary_muscles":["obliques","shoulders"],"target":"abs","image":"images/0174-MvQPqVW.jpg","gif_url":"videos/0174-MvQPqVW.gif","instruction_steps":{"he":["עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","החזיקו את ידית הכבל בשתי ידיים בגובה החזה, כפות ידיים כלפי מטה.","הפעילו את הליבה וסובבו את הגו ימינה, במשיכת הכבל על פני הגוף.","תוך כדי הסיבוב, הסתובבו על כף הרגל האחורית ותנו לאגן להסתובב באופן טבעי.","מתחו את הידיים לגמרי וסיימו את התנועה בהעברת ידית הכבל מעל הכתף.","חזרו לנקודת ההתחלה בהיפוך התנועה, בסיבוב הגו חזרה למרכז.","חזרו על התנועה בצד הנגדי.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with both hands at chest level, palms facing down.","Engage your core and rotate your torso to the right, pulling the cable across your body.","As you rotate, pivot your back foot and allow your hips to rotate naturally.","Extend your arms fully and finish the movement by flipping the cable handle over your shoulder.","Return to the starting position by reversing the movement, rotating your torso back to the center.","Repeat the movement on the opposite side.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Держите рукоятку троса обеими руками на уровне груди ладонями вниз.","Включите корпус и поверните туловище вправо, протягивая трос через тело.","Во время вращения поворачивайте заднюю ногу и позволяйте бедрам вращаться естественным образом.","Полностью выпрямите руки и завершите движение, перекинув рукоятку троса через плечо.","Вернитесь в исходное положение, выполнив обратное движение и повернув туловище обратно в центр.","Повторите движение в противоположную сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con ambas manos a la altura del pecho, con las palmas hacia abajo.","Activa el core y rota el torso hacia la derecha, jalando el cable a través del cuerpo.","Mientras rotas, gira el pie de atrás y permite que las caderas roten de forma natural.","Extiende los brazos completamente y termina el movimiento llevando la agarradera del cable por encima del hombro.","Vuelve a la posición inicial revirtiendo el movimiento, rotando el torso de regreso al centro.","Repite el movimiento en el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0860","name":"cable kickback","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0860-HEJ6DIX.jpg","gif_url":"videos/0860-HEJ6DIX.gif","instruction_steps":{"he":["עמדו מול מכשיר כבלים עם רגליים ברוחב כתפיים.","החזיקו את ידית הכבל ביד ימין וצעדו לאחור ליצירת מתח בכבל.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","שמרו על הזרוע העליונה צמודה לגוף והמרפק כפוף בזווית של 90 מעלות.","יישרו את האמה לאחור, עד יישור מלא של היד.","עצרו לרגע, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and step back to create tension in the cable.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your upper arm close to your body and your elbow bent at a 90-degree angle.","Extend your forearm backward, straightening your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмите рукоятку троса правой рукой и отступите назад, чтобы создать натяжение троса.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Держите плечо близко к телу, а локоть согнут под углом 90 градусов.","Вытяните предплечье назад, полностью выпрямляя руку.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con la mano derecha y retrocede un paso para crear tensión en el cable.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Mantén la parte superior del brazo cerca del cuerpo y el codo flexionado en un ángulo de 90 grados.","Extiende el antebrazo hacia atrás, enderezando el brazo por completo.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0175","name":"cable kneeling crunch","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0175-WW95auq.jpg","gif_url":"videos/0175-WW95auq.gif","instruction_steps":{"he":["חברו ידית חבל לגלגלת עליונה וכרעו עם הגב למכשיר.","החזיקו את ידית החבל בשתי ידיים ומקמו אותה מאחורי הראש, עם מרפקים פונים לצדדים.","תוך שמירה על אגן ללא תזוזה, כופפו את המותניים וגלגלו את הגו למטה לכיוון הירכיים.","עצרו לרגע בנקודה התחתונה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope handle to a high pulley and kneel down facing away from the machine.","Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.","Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревочную ручку к высокому шкиву и встаньте на колени лицом от машины.","Возьмите рукоятку веревки обеими руками и поместите ее за голову, держа локти в стороны.","Удерживая бедра неподвижными, согните талию и наклоните туловище к бедрам.","Задержитесь на мгновение внизу, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas de espaldas a la máquina.","Sujeta la agarradera de cuerda con ambas manos y colócala detrás de la cabeza, manteniendo los codos hacia afuera a los lados.","Manteniendo las caderas inmóviles, flexiona la cintura y encoge el torso hacia los muslos.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3697","name":"cable kneeling rear delt row (with rope) (male)","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/3697-G61cXLk.jpg","gif_url":"videos/3697-G61cXLk.gif","instruction_steps":{"he":["חברו ידית חבל לגלגלת כבל תחתונה וכרעו מול המכשיר.","אחזו בחבל באחיזה ניטרלית (כפות ידיים פונות זו לזו) ומתחו את הידיים לגמרי לפניכם.","תוך שמירה על גב ישר וליבה מופעלת, משכו את החבל לכיוון הגוף בכיווץ השכמות לאחור.","כווצו את השכמות זו לזו בסוף התנועה והחזיקו לרגע קצר.","שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope handle to a low cable pulley and kneel down facing the machine.","Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.","Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.","Squeeze your shoulder blades together at the end of the movement and hold for a brief pause.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревочную ручку к низкому шкиву и встаньте на колени лицом к машине.","Возьмите веревку нейтральным хватом (ладони обращены друг к другу) и вытяните руки полностью перед собой.","Удерживая спину прямой и напряженным корпус, потяните веревку к телу, сводя лопатки.","В конце движения сведите лопатки вместе и задержитесь на небольшую паузу.","Медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una agarradera de cuerda a una polea baja y ponte de rodillas frente a la máquina.","Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y extiende los brazos completamente frente a ti.","Manteniendo la espalda recta y el core activado, jala la cuerda hacia el cuerpo retrayendo los omóplatos.","Aprieta los omóplatos al final del movimiento y mantén la posición por una breve pausa.","Libera lentamente la tensión y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0176","name":"cable kneeling triceps extension","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0176-KWdF2JI.jpg","gif_url":"videos/0176-KWdF2JI.gif","instruction_steps":{"he":["חברו ידית חבל לגלגלת עליונה וכרעו מול מכשיר הכבלים.","אחזו בחבל באחיזה ניטרלית (כפות ידיים פונות זו לזו) והביאו את הידיים לצידי הראש.","שמרו על מרפקים קרובים לראש וזרועות עליונות ללא תזוזה לאורך כל התרגיל.","יישרו את האמות בכיווץ הטרייספס עד יישור מלא של הידיים.","עצרו לרגע, ואז חזרו באיטיות לנקודת ההתחלה בכיפוף המרפקים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope handle to a high pulley and kneel down facing the cable machine.","Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Extend your forearms by contracting your triceps until your arms are fully extended.","Pause for a moment, then slowly return to the starting position by bending your elbows.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревочную ручку к высокому блоку и встаньте на колени лицом к канатной машине.","Возьмите веревку нейтральным хватом (ладони обращены друг к другу) и поднимите руки по бокам головы.","На протяжении всего упражнения держите локти близко к голове, а плечи неподвижно.","Разгибайте предплечья, сокращая трицепсы до тех пор, пока руки не выпрямятся полностью.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение, согнув руки в локтях.","Повторите необходимое количество повторений."],"es":["Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas frente a la máquina de cable.","Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y lleva las manos a los lados de la cabeza.","Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio.","Extiende los antebrazos contrayendo los tríceps hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento y luego vuelve lentamente a la posición inicial flexionando los codos.","Repite el número de repeticiones deseado."]}},{"id":"2330","name":"cable lat pulldown full range of motion","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/2330-LEprlgG.jpg","gif_url":"videos/2330-LEprlgG.gif","instruction_steps":{"he":["שבו על מכשיר הפולדאון כשהברכיים ממוקמות מתחת לכריות.","אחזו במוט הכבל באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היטו מעט לאחור ושמרו על חזה מורם, עם קשת קלה בגב התחתון.","משכו את המוט מטה לכיוון החזה העליון, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, ואז שחררו באיטיות את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the lat pulldown machine with your knees positioned under the pads.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на тренажер для тяги широчайших, расположив колени под подушечками.","Возьмитесь за перекладину хватом сверху, на расстоянии чуть шире ширины плеч.","Слегка откиньтесь назад и держите грудь вверх, сохраняя небольшой изгиб в пояснице.","Потяните штангу вниз к верхней части груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно отпустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en la máquina de jalón al pecho con las rodillas colocadas debajo de las almohadillas.","Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros.","Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar.","Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0177","name":"cable lateral pulldown (with rope attachment)","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0177-CuaWCmC.jpg","gif_url":"videos/0177-CuaWCmC.gif","instruction_steps":{"he":["חברו ידית חבל למכשיר הכבלים בתנוחה גבוהה.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו בחבל באחיזה עליונה, כפות ידיים פונות זו לזו.","שמרו על גב ישר והיטו מעט לאחור.","משכו את החבל מטה לכיוון צידי הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה.","שחררו באיטיות את המתח ותנו לחבל לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope attachment to the cable machine at a high position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back.","Pull the rope down towards your sides, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement.","Slowly release the tension and allow the rope to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к канатной машине в высоком положении.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмите веревку хватом сверху, ладони обращены друг к другу.","Держите спину прямо и слегка отклонитесь назад.","Потяните веревку вниз в стороны, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения.","Медленно ослабьте натяжение и дайте веревке вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta un accesorio de cuerda a la máquina de cable en una posición alta.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra.","Mantén la espalda recta e inclínate ligeramente hacia atrás.","Jala la cuerda hacia los costados, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento.","Libera lentamente la tensión y permite que la cuerda vuelva a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2616","name":"cable lateral pulldown with v-bar","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/2616-4c9BhzB.jpg","gif_url":"videos/2616-4c9BhzB.gif","instruction_steps":{"he":["שבו על מכשיר הפולדאון ואחזו בידית ה-V באחיזה עליונה.","כווננו את כרית הברכיים כך שהירכיים מקובעות מתחתיה.","שמרו על גב ישר והיטו מעט לאחור.","משכו את ידית ה-V מטה לכיוון החזה העליון, תוך שמירה על מרפקים צמודים לגוף.","כווצו את שרירי הגב בנקודה התחתונה של התנועה.","החזירו באיטיות את ידית ה-V לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.","Adjust the knee pad so that your thighs are secured under it.","Keep your back straight and lean back slightly.","Pull the v-bar down towards your upper chest while keeping your elbows close to your body.","Squeeze your back muscles at the bottom of the movement.","Slowly return the v-bar to the starting position and repeat for the desired number of repetitions."],"ru":["Сядьте на машину для протягивания троса и возьмитесь за насадку V-образной рукоятки сверху.","Отрегулируйте наколенник так, чтобы ваши бедра были надежно закреплены под ним.","Держите спину прямо и слегка откиньтесь назад.","Потяните V-образную перекладину вниз к верхней части груди, удерживая локти близко к телу.","Напрягите мышцы спины в нижней части движения.","Медленно верните гриф в исходное положение и повторите необходимое количество повторений."],"es":["Siéntate en la máquina de jalón de cable y agarra el accesorio en V con un agarre prono.","Ajusta la almohadilla de rodillas para que tus muslos queden asegurados debajo de ella.","Mantén la espalda recta e inclínate ligeramente hacia atrás.","Jala el accesorio en V hacia la parte superior del pecho manteniendo los codos cerca del cuerpo.","Aprieta los músculos de la espalda en la parte baja del movimiento.","Regresa lentamente el accesorio en V a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"0178","name":"cable lateral raise","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"traps","secondary_muscles":["traps","triceps"],"target":"delts","image":"images/0178-goJ6ezq.jpg","gif_url":"videos/0178-goJ6ezq.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים ואחזו בידיות הכבל באחיזה עליונה.","שמרו על ידיים ישרות וליבה מופעלת.","הרימו את הידיים לצדדים עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.","Keep your arms straight and your core engaged.","Raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмитесь за рукоятки троса хватом сверху.","Держите руки прямыми и напряженным корпусом.","Поднимите руки в стороны, пока они не станут параллельны полу.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas del cable con un agarre prono.","Mantén los brazos rectos y el core activado.","Levanta los brazos hacia los lados hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0179","name":"cable low fly","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0179-FVmZVhk.jpg","gif_url":"videos/0179-FVmZVhk.gif","instruction_steps":{"he":["חברו את הידיות לגלגלות התחתונות של מכשיר הכבלים ובחרו משקל מתאים.","עמדו במרכז המכשיר עם רגליים ברוחב כתפיים וכיפוף קל בברכיים.","אחזו בידיות באחיזה עליונה ומתחו את הידיים לצדדים, עם כיפוף קל במרפקים.","בשליטה, הביאו באיטיות את הידיים קדימה בתנועה גורפת, בהצלבתן מול הגוף.","עצרו לרגע בשיא התנועה, בתחושת המתיחה בשרירי החזה.","הפכו את התנועה והחזירו את הידיים באיטיות לנקודת ההתחלה, תוך שמירה על מתח בשרירי החזה לאורך כל הדרך.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the handles to the low pulleys of a cable machine and select an appropriate weight.","Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows.","Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body.","Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles.","Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ручки к низким шкивам канатной машины и выберите подходящий вес.","Встаньте посередине тренажера, поставив ноги на ширине плеч и слегка согнув колени.","Возьмитесь за рукоятки хватом сверху и вытяните руки в стороны, сохраняя небольшой изгиб в локтях.","Сохраняя контроль, медленно выведите руки вперед и скрестите их перед телом.","Задержитесь на мгновение на пике движения, чувствуя растяжение мышц груди.","Сделайте обратное движение и медленно верните руки в исходное положение, сохраняя напряжение мышц груди.","Повторите необходимое количество повторений."],"es":["Sujeta las agarraderas a las poleas bajas de una máquina de cable y selecciona un peso adecuado.","Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.","Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados, manteniendo una ligera flexión en los codos.","Manteniendo el control, lleva lentamente los brazos hacia adelante con un movimiento amplio, cruzándolos frente al cuerpo.","Haz una pausa por un momento en el punto más alto del movimiento, sintiendo el estiramiento en los músculos del pecho.","Invierte el movimiento y regresa lentamente los brazos a la posición inicial, manteniendo la tensión en los músculos del pecho durante todo el recorrido.","Repite el número de repeticiones deseado."]}},{"id":"0180","name":"cable low seated row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0180-hvV79Si.jpg","gif_url":"videos/0180-hvV79Si.gif","instruction_steps":{"he":["שבו על המכשיר עם כפות רגליים על משענות הרגליים וברכיים כפופות מעט.","אחזו בידיות באחיזה עליונה, כפות ידיים כלפי מטה.","שמרו על גב ישר ורכנו מעט קדימה, תוך שמירה על כיפוף קל במרפקים.","משכו את הידיות לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה, ואז שחררו באיטיות את הידיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на тренажер, поставьте ноги на подножки и слегка согните колени.","Возьмитесь за рукоятки верхним хватом ладонями вниз.","Держите спину прямо и слегка наклонитесь вперед, сохраняя небольшой изгиб в локтях.","Потяните ручки к телу, сведя лопатки вместе.","Задержитесь на мгновение на пике движения, затем медленно отпустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo.","Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos.","Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1634","name":"cable lying bicep curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1634-otqIxU4.jpg","gif_url":"videos/1634-otqIxU4.gif","instruction_steps":{"he":["חברו מוט ישר למכשיר כבלים בגלגלת תחתונה.","שכבו על הגב על ספסל ישר עם כפות רגליים על הרצפה.","אחזו במוט באחיזה תחתונה, ידיים ברוחב כתפיים.","יישרו את הידיים לגמרי, תוך שמירה על מרפקים צמודים לצידי הגוף.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המוט למעלה לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатной машине с низким шкивом.","Лягте лицом вверх на плоскую скамью, положив ступни на землю.","Возьмитесь за перекладину хватом снизу, руки на ширине плеч.","Полностью выпрямите руки, держа локти близко к бокам.","Удерживая плечи неподвижно, выдохните и поднимите штангу к плечам.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите штангу обратно в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Coloca una barra recta en una máquina de cable con polea baja.","Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Extiende los brazos por completo, manteniendo los codos cerca de los costados.","Manteniendo la parte superior de los brazos inmóvil, exhala y curva la barra hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0182","name":"cable lying close-grip curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0182-61GrD55.jpg","gif_url":"videos/0182-61GrD55.gif","instruction_steps":{"he":["חברו מוט ישר למכשיר כבלים בגלגלת תחתונה.","שכבו על הגב על ספסל ישר עם כפות רגליים על הרצפה.","אחזו במוט באחיזה תחתונה, ידיים ברוחב כתפיים.","יישרו את הידיים לגמרי, תוך שמירה על מרפקים צמודים לצידי הגוף.","תוך שמירה על הזרועות העליונות ללא תזוזה, כופפו את המוט לכיוון החזה בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","הורידו את המוט באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатной машине с низким шкивом.","Лягте лицом вверх на плоскую скамью, положив ступни на землю.","Возьмитесь за перекладину хватом снизу, руки на ширине плеч.","Полностью выпрямите руки, держа локти близко к бокам.","Удерживая плечи неподвижно, поднимите штангу к груди, напрягая бицепсы.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Медленно опустите штангу обратно в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Coloca una barra recta en una máquina de cable con polea baja.","Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Extiende los brazos por completo, manteniendo los codos cerca de los costados.","Manteniendo la parte superior de los brazos inmóvil, curva la barra hacia el pecho contrayendo los bíceps.","Haz una pausa breve en la parte alta, apretando los bíceps.","Baja lentamente la barra de vuelta a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."]}},{"id":"0184","name":"cable lying extension pullover (with rope attachment)","category":"back","body_part":"back","equipment":"cable","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"lats","image":"images/0184-Q2Eu1Ax.jpg","gif_url":"videos/0184-Q2Eu1Ax.gif","instruction_steps":{"he":["חברו חבל למכשיר כבלים וכווננו את הגלגלת לתנוחה הגבוהה ביותר.","שכבו על ספסל כשהראש לכיוון מכשיר הכבלים.","החזיקו את החבל בשתי ידיים ומתחו את הידיים ישר מעל החזה.","תוך שמירה על ידיים ישרות, הורידו באיטיות את החבל מאחורי הראש בשליטה.","עצרו לרגע בנקודה התחתונה, ואז הרימו את החבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope to a cable machine and set the pulley at the highest position.","Lie down on a bench with your head towards the cable machine.","Hold the rope with both hands and extend your arms straight up above your chest.","Keeping your arms straight, slowly lower the rope behind your head while maintaining control.","Pause for a moment at the bottom, then slowly raise the rope back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к канатной машине и установите шкив в самое верхнее положение.","Лягте на скамью головой в сторону канатной машины.","Возьмите веревку обеими руками и вытяните руки прямо над грудью.","Держа руки прямыми, медленно опустите веревку за голову, сохраняя контроль.","Задержитесь на мгновение внизу, затем медленно поднимите веревку обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una cuerda a una máquina de cable y coloca la polea en la posición más alta.","Túmbate en un banco con la cabeza orientada hacia la máquina de cable.","Sujeta la cuerda con ambas manos y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos rectos, baja lentamente la cuerda detrás de la cabeza manteniendo el control.","Haz una pausa por un momento en la parte baja y luego sube lentamente la cuerda de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0185","name":"cable lying fly","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0185-lJJ7Yq8.jpg","gif_url":"videos/0185-lJJ7Yq8.gif","instruction_steps":{"he":["חברו את הידיות לכבלים ושכבו על ספסל עם כפות רגליים על הרצפה.","החזיקו את הידיות עם כפות ידיים פונות זו לזו וידיים מתוחות ישר מעל החזה.","תוך שמירה על כיפוף קל במרפקים, הורידו את הידיים לצדדים בקשת רחבה עד שתרגישו מתיחה בחזה.","עצרו לרגע, ואז כווצו את שרירי החזה להחזרת הידיים לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the handles to the cables and lie flat on a bench with your feet flat on the ground.","Hold the handles with your palms facing each other and your arms extended straight above your chest.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ручки к тросам и лягте на скамью, поставив ноги на землю.","Возьмитесь за ручки ладонями друг к другу, а руки вытяните прямо над грудью.","Сохраняя небольшой изгиб в локтях, опустите руки в стороны по широкой дуге, пока не почувствуете растяжение в груди.","Сделайте паузу на мгновение, затем сожмите мышцы груди, чтобы вернуть руки в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta las agarraderas a los cables y túmbate boca arriba en un banco con los pies apoyados planos en el suelo.","Sujeta las agarraderas con las palmas una frente a la otra y los brazos extendidos rectos por encima del pecho.","Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar los brazos a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0186","name":"cable lying triceps extension v. 2","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0186-uxJcFUU.jpg","gif_url":"videos/0186-uxJcFUU.gif","instruction_steps":{"he":["חברו ידית חבל למכשיר כבלים בגלגלת תחתונה.","שכבו על הגב על ספסל ישר, כשהראש לכיוון מכשיר הכבלים.","אחזו בידית החבל בשתי ידיים, כפות ידיים פונות זו לזו, ומתחו את הידיים ישר מעל החזה.","תוך שמירה על הזרועות העליונות ללא תזוזה, הורידו באיטיות את ידית החבל לכיוון המצח בכיפוף המרפקים.","עצרו לרגע בנקודה התחתונה, ואז יישרו את הידיים חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope handle to a low pulley cable machine.","Lie down on a flat bench facing up, with your head towards the cable machine.","Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревочную ручку к канатной машине с низким шкивом.","Лягте на ровную скамью лицом вверх, головой в сторону канатной машины.","Возьмитесь за ручку веревки обеими руками, ладонями друг к другу, и вытяните руки прямо над грудью.","Удерживая плечи неподвижно, медленно опустите рукоятку веревки ко лбу, сгибая локти.","Задержитесь на мгновение в нижней точке, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una agarradera de cuerda a una máquina de cable con polea baja.","Túmbate boca arriba en un banco plano con la cabeza orientada hacia la máquina de cable.","Sujeta la agarradera de cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos por encima del pecho.","Manteniendo la parte superior de los brazos inmóvil, baja lentamente la agarradera de cuerda hacia la frente flexionando los codos.","Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0188","name":"cable middle fly","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0188-xLYSdtg.jpg","gif_url":"videos/0188-xLYSdtg.gif","instruction_steps":{"he":["חברו כבלים לשני צידי מכשיר הכבלים בגובה החזה.","עמדו במרכז המכשיר עם כף רגל אחת מעט לפני השנייה.","אחזו בידיות באחיזה עליונה ומתחו את הידיים לצדדים.","שמרו על כיפוף קל במרפקים והטיה קלה קדימה.","הפעילו את שרירי החזה והביאו את הידיים קדימה בתנועה גורפת.","עצרו לרגע במרכז, ואז החזירו את הידיים באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach cables to both sides of a cable machine at chest height.","Stand in the center of the machine with one foot slightly in front of the other.","Grasp the handles with an overhand grip and extend your arms out to the sides.","Keep a slight bend in your elbows and maintain a slight forward lean.","Engage your chest muscles and bring your arms forward in a sweeping motion.","Pause for a moment at the center, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите кабели к обеим сторонам канатной машины на уровне груди.","Встаньте в центре тренажера, поставив одну ногу немного впереди другой.","Возьмитесь за рукоятки верхним хватом и вытяните руки в стороны.","Сохраняйте небольшой изгиб в локтях и сохраняйте небольшой наклон вперед.","Задействуйте мышцы груди и сделайте размашистое движение руками вперед.","Задержитесь на мгновение в центре, затем медленно верните руки в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta los cables a ambos lados de una máquina de cable a la altura del pecho.","Ponte de pie en el centro de la máquina con un pie ligeramente delante del otro.","Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados.","Mantén una ligera flexión en los codos y conserva una leve inclinación hacia adelante.","Activa los músculos del pecho y lleva los brazos hacia adelante con un movimiento amplio.","Haz una pausa por un momento en el centro y luego regresa lentamente los brazos a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0189","name":"cable one arm bent over row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0189-EIsE3u8.jpg","gif_url":"videos/0189-EIsE3u8.gif","instruction_steps":{"he":["עמדו מול מכשיר כבלים עם רגליים ברוחב כתפיים.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","אחזו בידית הכבל ביד אחת, כף יד פונה פנימה, ויישרו את היד לגמרי.","משכו את ידית הכבל לכיוון הגוף, תוך שמירה על מרפק צמוד לצד, עד שהיד מגיעה לחזה התחתון.","עצרו לרגע, ואז יישרו באיטיות את היד חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand facing a cable machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.","Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest.","Pause for a moment, then slowly extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Возьмитесь за рукоятку троса одной рукой, ладонью внутрь, и полностью вытяните руку.","Потяните рукоятку троса к себе, держа локоть близко к боку, пока рука не достигнет нижней части груди.","Сделайте паузу на мгновение, затем медленно вытяните руку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Sujeta la agarradera del cable con una mano, con la palma hacia adentro, y extiende el brazo por completo.","Jala la agarradera del cable hacia el cuerpo, manteniendo el codo cerca del costado, hasta que la mano llegue a la parte baja del pecho.","Haz una pausa por un momento y luego extiende lentamente el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0190","name":"cable one arm curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0190-YTur5nR.jpg","gif_url":"videos/0190-YTur5nR.gif","instruction_steps":{"he":["עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","אחזו בידית הכבל באחיזה תחתונה, כף יד כלפי מעלה.","שמרו על מרפק צמוד לגוף וגלגלו באיטיות את האמה למעלה לכיוון הכתף.","עצרו לרגע בנקודה העליונה, ואז הורידו את האמה באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing up.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмитесь за рукоятку троса снизу ладонью вверх.","Держите локоть близко к боку и медленно согните предплечье к плечу.","Задержитесь на мгновение в верхней точке, затем медленно опустите предплечье обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con un agarre supino, con la palma hacia arriba.","Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro.","Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1262","name":"cable one arm decline chest fly","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1262-w4dLzSx.jpg","gif_url":"videos/1262-w4dLzSx.gif","instruction_steps":{"he":["חברו ידית D לגלגלת כבל תחתונה וכווננו את הספסל לזווית שיפוע שלילי.","שכבו על הספסל כשהראש לכיוון המכשיר ואחזו בידית ביד ימין.","מתחו את היד ישר מעל החזה, עם כיפוף קל במרפק.","בתנועה מבוקרת, הורידו את היד הצידה עד שכף היד בקו אחד עם הכתף.","עצרו לרגע, ואז הפכו את התנועה והחזירו את היד לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד שמאל וחזרו על התרגיל."],"en":["Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.","Lie down on the bench with your head towards the machine and grab the handle with your right hand.","Extend your arm straight up above your chest, keeping a slight bend in your elbow.","With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then reverse the motion and bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise."],"ru":["Прикрепите D-образную рукоятку к тросовой машине с низким шкивом и установите скамью под углом наклона.","Лягте на скамью головой в сторону станка и возьмитесь за рукоятку правой рукой.","Вытяните руку прямо над грудью, сохраняя небольшой изгиб в локте.","Контролируемым движением опустите руку в сторону, пока она не окажется на одной линии с плечом.","Сделайте паузу на мгновение, затем выполните обратное движение и верните руку в исходное положение.","Повторите необходимое количество повторений, затем переключитесь на левую руку и повторите упражнение."],"es":["Sujeta una agarradera en D a una máquina de cable con polea baja y coloca el banco en un ángulo declinado.","Túmbate en el banco con la cabeza orientada hacia la máquina y agarra la agarradera con la mano derecha.","Extiende el brazo recto por encima del pecho, manteniendo una ligera flexión en el codo.","Con un movimiento controlado, baja el brazo hacia el lado hasta que la mano quede alineada con el hombro.","Haz una pausa por un momento y luego invierte el movimiento para regresar el brazo a la posición inicial.","Repite el número de repeticiones deseado y luego cambia al brazo izquierdo y repite el ejercicio."]}},{"id":"1263","name":"cable one arm fly on exercise ball","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/1263-hHy8tQG.jpg","gif_url":"videos/1263-hHy8tQG.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו ידית כבל ביד אחת ומתחו את היד הצידה, מקבילה לרצפה.","שמרו על מרפק כפוף מעט וכף יד פונה קדימה.","הביאו באיטיות את היד על פני הגוף, בכיווץ שרירי החזה.","עצרו לרגע בסוף התנועה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground.","Keep your elbow slightly bent and your palm facing forward.","Slowly bring your arm across your body, squeezing your chest muscles.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину.","Возьмите рукоятку троса в одну руку и вытяните руку в сторону параллельно земле.","Держите локоть слегка согнутым и ладонью вперед.","Медленно проведите рукой поперек тела, сжимая мышцы груди.","Сделайте небольшую паузу в конце движения, затем медленно вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sujeta una agarradera del cable con una mano y extiende el brazo hacia el lado, paralelo al suelo.","Mantén el codo ligeramente flexionado y la palma hacia adelante.","Lleva lentamente el brazo a través del cuerpo, apretando los músculos del pecho.","Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"1264","name":"cable one arm incline fly on exercise ball","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/1264-P14Dz9D.jpg","gif_url":"videos/1264-P14Dz9D.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה והגב נשען על ספסל שיפוע.","החזיקו ידית כבל ביד אחת עם היד מתוחה וכף היד פונה פנימה.","עם כיפוף קל במרפק, הורידו באיטיות את היד הצידה עד שכף היד בקו אחד עם הכתף.","עצרו לרגע, ואז כווצו את שרירי החזה להחזרת היד לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on an exercise ball with your feet flat on the ground and your back against an incline bench.","Hold a cable handle in one hand with your arm extended and palm facing inward.","Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на мяч для упражнений, поставив ноги на землю, а спиной опираясь на наклонную скамью.","Возьмите рукоятку троса в одну руку, вытянув руку ладонью внутрь.","Сохраняя небольшой изгиб в локте, медленно опустите руку в сторону, пока кисть не окажется на одной линии с плечом.","Сделайте паузу на мгновение, затем сожмите мышцы груди, чтобы вернуть руку в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado.","Sujeta una agarradera del cable con una mano, con el brazo extendido y la palma hacia adentro.","Manteniendo una ligera flexión en el codo, baja lentamente el brazo hacia el lado hasta que la mano quede alineada con el hombro.","Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar el brazo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1265","name":"cable one arm incline press","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/1265-GKEH6jj.jpg","gif_url":"videos/1265-GKEH6jj.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים לתנוחת גלגלת תחתונה.","שבו על ספסל שיפוע עם הגב למכשיר הכבלים.","אחזו בידית ביד אחת והביאו אותה לגובה הכתף.","נטעו את כפות הרגליים היטב ברצפה ושמרו על תנוחה יציבה.","לחצו את הידית קדימה ולמעלה, עד יישור מלא של היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידית באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Adjust the cable machine to a low pulley position.","Sit on an incline bench facing away from the cable machine.","Grasp the handle with one hand and bring it up to shoulder height.","Position your feet firmly on the ground and maintain a stable position.","Press the handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Отрегулируйте тросовую машину в нижнее положение шкива.","Сядьте на наклонную скамью лицом в сторону от канатной машины.","Возьмитесь за ручку одной рукой и поднимите ее на высоту плеч.","Твердо поставьте ноги на землю и сохраняйте устойчивое положение.","Нажмите ручку вперед и вверх, полностью вытянув руку.","Задержитесь на мгновение в верхней точке, затем медленно опустите рукоятку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ajusta la máquina de cable a una posición de polea baja.","Siéntate en un banco inclinado de espaldas a la máquina de cable.","Sujeta la agarradera con una mano y llévala hasta la altura del hombro.","Coloca los pies firmemente en el suelo y mantén una posición estable.","Empuja la agarradera hacia adelante y hacia arriba, extendiendo el brazo por completo.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"1266","name":"cable one arm incline press on exercise ball","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1266-6t00BsF.jpg","gif_url":"videos/1266-6t00BsF.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה והגב נשען על ספסל שיפוע.","החזיקו ידית כבל ביד אחת ומקמו את היד בזווית של 90 מעלות, עם מרפק כפוף.","לחצו את ידית הכבל קדימה ולמעלה, עד יישור מלא של היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את ידית הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench.","Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.","Press the cable handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Сядьте на мяч для упражнений, поставив ноги на землю, а спиной опираясь на наклонную скамью.","Возьмите рукоятку троса в одну руку и поместите руку под углом 90 градусов, согнув локоть.","Нажмите рукоятку троса вперед и вверх, полностью вытянув руку.","Задержитесь на мгновение в верхней точке, затем медленно опустите рукоятку троса обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado.","Sujeta una agarradera del cable con una mano y coloca el brazo en un ángulo de 90 grados con el codo flexionado.","Empuja la agarradera del cable hacia adelante y hacia arriba, extendiendo el brazo por completo.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0191","name":"cable one arm lateral bent-over","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","trapezius"],"target":"pectorals","image":"images/0191-dB07vDu.jpg","gif_url":"videos/0191-dB07vDu.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, מול מכשיר כבלים.","אחזו בידית ביד אחת וצעדו לאחור ליצירת מתח בכבל.","הטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר וליבה מופעלת.","מתחו את היד הצידה, מקבילה לרצפה, עם כיפוף קל במרפק.","החזירו באיטיות את היד לנקודת ההתחלה, תוך שמירה על שליטה לאורך כל התנועה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, facing a cable machine.","Grasp the handle with one hand and step back to create tension on the cable.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow.","Slowly bring your arm back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, поставив ноги на ширине плеч, лицом к канатной машине.","Возьмитесь за ручку одной рукой и отступите назад, чтобы создать натяжение троса.","Наклонитесь вперед в талии, сохраняя спину прямой и напрягая корпус.","Вытяните руку в сторону параллельно земле, слегка согнув ее в локте.","Медленно верните руку в исходное положение, сохраняя контроль на протяжении всего движения.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, frente a una máquina de cable.","Sujeta la agarradera con una mano y retrocede un paso para crear tensión en el cable.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.","Extiende el brazo hacia el lado, paralelo al suelo, con una ligera flexión en el codo.","Regresa lentamente el brazo a la posición inicial, manteniendo el control durante todo el movimiento.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0192","name":"cable one arm lateral raise","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"traps","secondary_muscles":["traps","triceps"],"target":"delts","image":"images/0192-wEulIzp.jpg","gif_url":"videos/0192-wEulIzp.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, מול מכשיר הכבלים.","החזיקו את ידית הכבל ביד אחת, כף יד כלפי מטה, ועמדו מספיק רחוק מהמכשיר כך שיהיה מתח בכבל.","שמרו על יד ישרה והרימו אותה באיטיות הצידה עד שהיא מקבילה לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את היד באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.","Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, поставив ноги на ширине плеч, лицом к канатному тренажеру.","Держите рукоятку троса одной рукой ладонью вниз и стойте на достаточном расстоянии от машины, чтобы трос был натянут.","Держите руку прямо и медленно поднимите ее в сторону, пока она не станет параллельна земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите руку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.","Sujeta la agarradera del cable con una mano, con la palma hacia abajo, y colócate lo suficientemente alejado de la máquina para que haya tensión en el cable.","Mantén el brazo recto y levántalo lentamente hacia el lado hasta que quede paralelo al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"1633","name":"cable one arm preacher curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1633-eHBlPsa.jpg","gif_url":"videos/1633-eHBlPsa.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים כך שכרית הפריצ'ר בגובה החזה.","עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","אחזו בידית הכבל באחיזה תחתונה ומקמו את הזרוע העליונה על כרית הפריצ'ר.","שמרו על גב ישר וליבה מופעלת.","כופפו באיטיות את ידית הכבל לכיוון הכתף, תוך שמירה על הזרוע העליונה צמודה לכרית.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","הורידו את ידית הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי.","החליפו ידיים וחזרו על התרגיל."],"en":["Adjust the cable machine so that the preacher curl pad is at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad.","Keep your back straight and your core engaged.","Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."],"ru":["Отрегулируйте блочный тренажер так, чтобы подушечка для сгибаний проповедника находилась на уровне груди.","Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмите рукоятку троса обратным хватом снизу и прижмите плечо к подушечке для сгибаний проповедника.","Держите спину прямо, а корпус напряженным.","Медленно поверните рукоятку троса к плечу, прижимая плечо к подушке.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Медленно опустите рукоятку троса обратно в исходное положение.","Повторите необходимое количество повторений.","Поменяйте руки и повторите упражнение."],"es":["Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott.","Mantén la espalda recta y el core activado.","Curva lentamente la agarradera del cable hacia el hombro, manteniendo la parte superior del brazo contra la almohadilla.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de brazo y repite el ejercicio."]}},{"id":"1267","name":"cable one arm press on exercise ball","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1267-MKIelrR.jpg","gif_url":"videos/1267-MKIelrR.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו ידית כבל ביד אחת ומקמו את היד בגובה החזה, מרפק כפוף.","הניחו את היד השנייה על המותן לייצוב.","לחצו את ידית הכבל קדימה, עד יישור מלא של היד.","עצרו לרגע, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and position your arm at chest height, elbow bent.","Place your other hand on your hip for stability.","Press the cable handle forward, extending your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину.","Возьмите рукоятку троса в одну руку и поместите руку на уровне груди, согнутую в локте.","Вторую руку положите на бедро для устойчивости.","Нажмите рукоятку троса вперед, полностью вытянув руку.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sujeta una agarradera del cable con una mano y coloca el brazo a la altura del pecho, con el codo flexionado.","Coloca la otra mano en la cadera para mantener el equilibrio.","Empuja la agarradera del cable hacia adelante, extendiendo el brazo por completo.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"3563","name":"cable one arm pulldown","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/3563-U5INZY6.jpg","gif_url":"videos/3563-U5INZY6.gif","instruction_steps":{"he":["חברו ידית בודדת לגלגלת עליונה במכשיר כבלים.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו בידית באחיזה עליונה ומתחו את היד לגמרי.","שמרו על גב ישר וליבה מופעלת.","משכו את הידית מטה לכיוון הצד, תוך שמירה על מרפק קרוב לגוף.","עצרו לרגע בנקודה התחתונה של התנועה, תוך כיווץ רחב הגבי.","שחררו באיטיות את הידית חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי.","החליפו צדדים וחזרו על התרגיל עם היד השנייה."],"en":["Attach a single handle to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip and extend your arm fully.","Keep your back straight and your core engaged.","Pull the handle down towards your side while keeping your elbow close to your body.","Pause for a moment at the bottom of the movement, squeezing your lat muscle.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."],"ru":["Прикрепите одну ручку к канатной машине с высоким шкивом.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмитесь за рукоятку верхним хватом и полностью вытяните руку.","Держите спину прямо, а корпус напряженным.","Потяните ручку вниз в сторону, удерживая локоть близко к телу.","Задержитесь на мгновение в нижней части движения, сжимая широчайшие мышцы.","Медленно отпустите ручку обратно в исходное положение.","Повторите необходимое количество повторений.","Поменяйте сторону и повторите упражнение другой рукой."],"es":["Sujeta una agarradera individual a una máquina de cable con polea alta.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la agarradera con un agarre prono y extiende el brazo por completo.","Mantén la espalda recta y el core activado.","Jala la agarradera hacia abajo en dirección al costado, manteniendo el codo cerca del cuerpo.","Haz una pausa por un momento en la parte baja del movimiento, apretando el dorsal.","Suelta lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de lado y repite el ejercicio con el otro brazo."]}},{"id":"1635","name":"cable one arm reverse preacher curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1635-ZXnjcOQ.jpg","gif_url":"videos/1635-ZXnjcOQ.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים כך שהגלגלת בתנוחה הנמוכה ביותר.","עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","אחזו בידית הכבל באחיזה תחתונה ומקמו את הזרוע העליונה על כרית ספסל הפריצ'ר.","שמרו על גב ישר וליבה מופעלת לאורך כל התרגיל.","כופפו באיטיות את האמה לכיוון הבייספס, תוך שמירה על הזרוע העליונה ללא תזוזה על הכרית.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","הורידו את ידית הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי.","החליפו ידיים וחזרו על התרגיל."],"en":["Adjust the cable machine so that the pulley is at the lowest position.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."],"ru":["Отрегулируйте тросовую машину так, чтобы шкив находился в самом нижнем положении.","Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмитесь за рукоятку троса обратным хватом снизу и прижмите плечо к подушке скамьи проповедника.","На протяжении всего упражнения держите спину прямой и напряженным корпус.","Медленно согните предплечье к бицепсу, удерживая плечо неподвижно на подушечке.","Задержитесь на мгновение в верхней точке движения, сжимая бицепс.","Медленно опустите рукоятку троса обратно в исходное положение.","Повторите необходимое количество повторений.","Поменяйте руки и повторите упражнение."],"es":["Ajusta la máquina de cable de modo que la polea quede en la posición más baja.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Curva lentamente el antebrazo hacia el bíceps, manteniendo la parte superior del brazo inmóvil contra la almohadilla.","Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps.","Baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de brazo y repite el ejercicio."]}},{"id":"0193","name":"cable one arm straight back high row (kneeling)","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0193-WrYPP2g.jpg","gif_url":"videos/0193-WrYPP2g.gif","instruction_steps":{"he":["חברו ידית למכשיר כבלים בגובה המותניים.","כרעו מול מכשיר הכבלים ואחזו בידית ביד אחת.","שמרו על גב ישר וליבה מופעלת.","משכו את הידית לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה.","שחררו באיטיות את הידית חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי.","החליפו צדדים וחזרו על התרגיל עם היד השנייה."],"en":["Attach a handle to a cable machine at waist height.","Kneel down facing the cable machine and grab the handle with one hand.","Keep your back straight and your core engaged.","Pull the handle towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."],"ru":["Прикрепите ручку к канатной машине на уровне талии.","Встаньте на колени лицом к канатной машине и возьмитесь за ручку одной рукой.","Держите спину прямо, а корпус напряженным.","Потяните рукоятку к груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения.","Медленно отпустите ручку обратно в исходное положение.","Повторите необходимое количество повторений.","Поменяйте сторону и повторите упражнение другой рукой."],"es":["Sujeta una agarradera a una máquina de cable a la altura de la cintura.","Ponte de rodillas frente a la máquina de cable y agarra la agarradera con una mano.","Mantén la espalda recta y el core activado.","Jala la agarradera hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta del movimiento.","Suelta lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de lado y repite el ejercicio con el otro brazo."]}},{"id":"1723","name":"cable one arm tricep pushdown","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/1723-qRZ5S1N.jpg","gif_url":"videos/1723-qRZ5S1N.gif","instruction_steps":{"he":["עמדו מול מכשיר כבלים עם מוט ישר מחובר בגובה החזה.","אחזו במוט באחיזה עליונה וצעדו לאחור ליצירת מתח בכבל.","מקמו את כפות הרגליים ברוחב כתפיים וכופפו ברכיים מעט.","שמרו על גב ישר וליבה מופעלת לאורך כל התרגיל.","התחילו עם היד מתוחה לגמרי וניצבת לרצפה.","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו ודחפו את המוט מטה עד יישור מלא של היד.","עצרו לרגע, ואז שאפו וחזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Stand facing a cable machine with a straight bar attachment at chest height.","Grasp the bar with an overhand grip and step back to create tension in the cable.","Position your feet shoulder-width apart and slightly bend your knees.","Keep your back straight and core engaged throughout the exercise.","Start with your arm fully extended and perpendicular to the floor.","Keeping your upper arm stationary, exhale and push the bar down until your arm is fully extended.","Pause for a moment, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Встаньте лицом к канатному тренажеру с прямым грифом на уровне груди.","Возьмите штангу хватом сверху и отступите назад, чтобы создать натяжение троса.","Поставьте ноги на ширине плеч и слегка согните колени.","На протяжении всего упражнения держите спину прямой и напряженным корпус.","Начните с полностью выпрямленной руки, перпендикулярной полу.","Удерживая плечо неподвижно, выдохните и толкните штангу вниз, пока рука полностью не выпрямится.","Сделайте паузу на мгновение, затем вдохните и медленно вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ponte de pie frente a una máquina de cable con un accesorio de barra recta a la altura del pecho.","Sujeta la barra con un agarre prono y retrocede un paso para crear tensión en el cable.","Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Comienza con el brazo completamente extendido y perpendicular al suelo.","Manteniendo la parte superior del brazo inmóvil, exhala y empuja la barra hacia abajo hasta que el brazo quede completamente extendido.","Haz una pausa por un momento, luego inhala y regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1636","name":"cable overhead curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1636-wDUqY2u.jpg","gif_url":"videos/1636-wDUqY2u.gif","instruction_steps":{"he":["חברו מוט ישר לגלגלת עליונה במכשיר הכבלים.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה תחתונה, ידיים ברוחב כתפיים.","שמרו על מרפקים צמודים לגוף וזרועות עליונות ללא תזוזה.","נשפו וכופפו את המוט מטה לכיוון המצח, תוך שמירה על זרועות עליונות ללא תזוזה.","עצרו לרגע בנקודה התחתונה של התנועה, תוך כיווץ הבייספס.","שאפו והחזירו את המוט באיטיות לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатной машине с высоким шкивом.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмитесь за перекладину хватом снизу, руки на ширине плеч.","Держите локти близко к бокам, а плечи неподвижно.","Выдохните и согните штангу ко лбу, сохраняя плечи неподвижными.","Задержитесь на мгновение в нижней части движения, напрягая бицепсы.","Вдохните и медленно верните штангу в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Sujeta una barra recta a una máquina de cable con polea alta.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos.","Exhala y curva la barra hacia la frente, manteniendo la parte superior de los brazos inmóvil.","Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps.","Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."]}},{"id":"1637","name":"cable overhead curl on exercise ball","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1637-ioTf098.jpg","gif_url":"videos/1637-ioTf098.gif","instruction_steps":{"he":["שבו על כדור פיזיו ואחזו בידית הכבל באחיזה תחתונה.","מתחו את הידיים לגמרי מעל הראש, תוך שמירה על מרפקים קרובים לאוזניים.","כופפו באיטיות את הכבל מטה לכיוון המצח, תוך שמירה על זרועות עליונות ללא תזוזה.","עצרו לרגע בנקודה התחתונה של התנועה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an exercise ball and hold the cable handle with an underhand grip.","Extend your arms fully overhead, keeping your elbows close to your ears.","Slowly curl the cable down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч для упражнений и возьмитесь за рукоятку троса хватом снизу.","Вытяните руки полностью над головой, держа локти близко к ушам.","Медленно скрутите трос ко лбу, сохраняя плечи неподвижными.","Сделайте паузу на мгновение в нижней части движения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de ejercicio y sujeta la agarradera del cable con un agarre supino.","Extiende los brazos completamente por encima de la cabeza, manteniendo los codos cerca de las orejas.","Curva lentamente el cable hacia la frente, manteniendo la parte superior de los brazos inmóvil.","Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0194","name":"cable overhead triceps extension (rope attachment)","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0194-2IxROQ1.jpg","gif_url":"videos/0194-2IxROQ1.gif","instruction_steps":{"he":["חברו חבל למכשיר כבלים בתנוחה גבוהה.","עמדו עם הגב למכשיר, רגליים ברוחב כתפיים.","אחזו בחבל בשתי ידיים, כפות ידיים פונות זו לזו, והביאו את הידיים מעל הראש.","שמרו על הזרועות העליונות קרובות לראש והמרפקים פונים קדימה.","הורידו באיטיות את החבל מאחורי הראש בכיפוף המרפקים.","עצרו לרגע, ואז יישרו את הידיים חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope to a cable machine at a high position.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing each other, and bring your hands above your head.","Keep your upper arms close to your head and your elbows pointing forward.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к канатной машине в высоком положении.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмите веревку обеими руками, ладонями друг к другу, и поднимите руки над головой.","Держите плечи близко к голове, а локти направлены вперед.","Медленно опустите веревку за голову, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una cuerda a una máquina de cable en una posición alta.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y lleva las manos por encima de la cabeza.","Mantén la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante.","Baja lentamente la cuerda detrás de la cabeza flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1319","name":"cable palm rotational row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1319-OmQ8w0p.jpg","gif_url":"videos/1319-OmQ8w0p.gif","instruction_steps":{"he":["חברו ידית למכשיר כבלים בגובה המותניים.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו בידית באחיזה עליונה, כפות ידיים כלפי מטה.","צעדו לאחור ליצירת מתח בכבל, תוך שמירה על גב ישר וברכיים כפופות מעט.","משכו את הידית לכיוון הגוף, תוך סיבוב כפות הידיים כלפי מעלה תוך כדי.","כווצו את השכמות זו לזו בסוף התנועה.","שחררו באיטיות את הידית חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a handle to a cable machine at waist height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip, palms facing down.","Step back to create tension on the cable, keeping your back straight and knees slightly bent.","Pull the handle towards your body, rotating your palms to face upwards as you do so.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ручку к канатной машине на уровне талии.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмитесь за рукоятку прямым хватом ладонями вниз.","Сделайте шаг назад, чтобы создать натяжение троса, сохраняя спину прямой и слегка согнутыми в коленях.","Потяните ручку к себе, поворачивая при этом ладони вверх.","В конце движения сведите лопатки вместе.","Медленно отпустите ручку обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una agarradera a una máquina de cable a la altura de la cintura.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la agarradera con un agarre prono, con las palmas hacia abajo.","Retrocede un paso para crear tensión en el cable, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Jala la agarradera hacia el cuerpo, rotando las palmas hacia arriba mientras lo haces.","Aprieta los omóplatos al final del movimiento.","Suelta lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0195","name":"cable preacher curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0195-P2lNrGL.jpg","gif_url":"videos/0195-P2lNrGL.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים כך שכרית הפריצ'ר בגובה החזה.","שבו על ספסל הפריצ'ר והניחו את הזרועות העליונות על הכרית, אוחזים באביזר הכבל באחיזה תחתונה.","שמרו על גב ישר ומרפקים צמודים לצידי הגוף.","כופפו באיטיות את אביזר הכבל למעלה לכיוון הכתפיים, בכיווץ הבייספס בנקודה העליונה של התנועה.","עצרו לרגע, ואז הורידו את אביזר הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable machine so that the preacher curl pad is at chest height.","Sit on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with an underhand grip.","Keep your back straight and your elbows tucked in at your sides.","Slowly curl the cable attachment up towards your shoulders, squeezing your biceps at the top of the movement.","Pause for a moment, then slowly lower the cable attachment back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте блочный тренажер так, чтобы подушечка для сгибаний проповедника находилась на уровне груди.","Сядьте на скамью для сгибаний рук и положите плечи на подушечку, взявшись за блочное крепление обратным хватом снизу.","Держите спину прямо, а локти прижатыми к бокам.","Медленно согните трос к плечам, сжимая бицепсы в верхней части движения.","Сделайте паузу на мгновение, затем медленно опустите крепление троса обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.","Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, agarrando el accesorio del cable con un agarre supino.","Mantén la espalda recta y los codos pegados a los costados.","Curva lentamente el accesorio del cable hacia los hombros, apretando los bíceps en la parte más alta del movimiento.","Haz una pausa por un momento y luego baja lentamente el accesorio del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1268","name":"cable press on exercise ball","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1268-vAwm6rK.jpg","gif_url":"videos/1268-vAwm6rK.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וברכיים בזווית של 90 מעלות.","החזיקו את ידיות הכבל בגובה החזה, עם כפות ידיים כלפי מטה ומרפקים כפופים.","הפעילו את הליבה ולחצו את ידיות הכבל קדימה עד יישור מלא של הידיים.","עצרו לרגע, ואז שחררו באיטיות את המתח והחזירו את ידיות הכבל לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle.","Hold the cable handles at chest height with your palms facing down and your elbows bent.","Engage your core and press the cable handles forward until your arms are fully extended.","Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч для упражнений, поставьте ступни на землю и составьте колени под углом 90 градусов.","Держите рукоятки троса на уровне груди ладонями вниз и согнутыми в локтях.","Напрягите корпус и нажмите рукоятки троса вперед, пока руки полностью не выпрямятся.","Сделайте паузу на мгновение, затем медленно ослабьте натяжение и верните рукоятки троса в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y las rodillas en un ángulo de 90 grados.","Sujeta las agarraderas del cable a la altura del pecho con las palmas hacia abajo y los codos flexionados.","Activa el core y empuja las agarraderas del cable hacia adelante hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento y luego libera lentamente la tensión, regresando las agarraderas del cable a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0196","name":"cable pull through (with rope)","category":"upper legs","body_part":"upper legs","equipment":"cable","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0196-OM46QHm.jpg","gif_url":"videos/0196-OM46QHm.gif","instruction_steps":{"he":["עמדו עם הגב למכשיר הכבלים, רגליים ברוחב כתפיים.","אחזו בידית החבל בשתי ידיים וצעדו קדימה, ליצירת מתח בכבל.","הטו את הגו מהירכיים והורידו את פלג הגוף העליון עד שהוא מקביל לרצפה, תוך שמירה על גב ישר.","הפעילו את הישבן והירך האחורית למשיכת הגוף חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing away from the cable machine with your feet shoulder-width apart.","Grab the rope attachment with both hands and step forward, creating tension in the cable.","Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight.","Engage your glutes and hamstrings to pull your body back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом от блочного тренажера, поставив ноги на ширине плеч.","Возьмите веревку обеими руками и сделайте шаг вперед, создавая натяжение троса.","Согнитесь в бедрах и опустите верхнюю часть тела до тех пор, пока она не станет параллельной земле, сохраняя спину прямой.","Задействуйте ягодицы и мышцы задней поверхности бедра, чтобы вернуть тело в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros.","Agarra el accesorio de cuerda con ambas manos y da un paso hacia adelante, creando tensión en el cable.","Flexiona las caderas y baja la parte superior del cuerpo hasta que quede paralela al suelo, manteniendo la espalda recta.","Activa los glúteos y los isquiotibiales para llevar el cuerpo de vuelta hacia arriba, a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0198","name":"cable pulldown","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0198-RVwzP10.jpg","gif_url":"videos/0198-RVwzP10.gif","instruction_steps":{"he":["כווננו את מכשיר הפולדאון כך שהמושב בגובה נוח וכרית הברכיים מקובעת.","שבו על המושב עם גב ישר וכפות רגליים על הרצפה.","אחזו במוט הכבל באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היטו מעט לאחור והפעילו את הליבה.","משכו את מוט הכבל מטה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, ואז שחררו באיטיות את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured.","Sit on the seat with your back straight and your feet flat on the ground.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and engage your core.","Pull the cable bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте механизм протягивания троса так, чтобы сиденье находилось на удобной высоте, а наколенник был зафиксирован.","Сядьте на сиденье, выпрямив спину и поставив ноги на землю.","Возьмитесь за перекладину хватом сверху, на расстоянии чуть шире ширины плеч.","Слегка откиньтесь назад и задействуйте корпус.","Потяните перекладину вниз к груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно отпустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de jalón de cable de modo que el asiento quede a una altura cómoda y la almohadilla de rodillas esté asegurada.","Siéntate con la espalda recta y los pies apoyados planos en el suelo.","Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros.","Inclínate ligeramente hacia atrás y activa el core.","Jala la barra del cable hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0197","name":"cable pulldown (pro lat bar)","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0197-qdRxqCj.jpg","gif_url":"videos/0197-qdRxqCj.gif","instruction_steps":{"he":["כווננו את גובה המושב כך שהירכיים מקבילות לרצפה וכפות הרגליים על הרצפה.","אחזו במוט הפולדאון באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שבו והיטו מעט לאחור, תוך שמירה על חזה מורם וגב ישר.","משכו את המוט מטה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, ואז שחררו באיטיות את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.","Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart.","Sit down and lean back slightly, keeping your chest up and your back straight.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья так, чтобы бедра были параллельны земле, а ступни стояли на полу.","Возьмитесь за перекладину хватом сверху, на расстоянии чуть шире ширины плеч.","Сядьте и слегка откиньтесь назад, держа грудь вверх и спину прямо.","Потяните штангу вниз к груди, сведя лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно отпустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento para que tus muslos queden paralelos al suelo y tus pies queden apoyados planos en el suelo.","Sujeta la barra de jalón con un agarre prono, un poco más separado que el ancho de los hombros.","Siéntate e inclínate ligeramente hacia atrás, manteniendo el pecho elevado y la espalda recta.","Jala la barra hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1638","name":"cable pulldown bicep curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1638-QTXKWPh.jpg","gif_url":"videos/1638-QTXKWPh.gif","instruction_steps":{"he":["חברו מוט ישר למכשיר הכבלים בגובה הגבוה ביותר.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה תחתונה, ידיים ברוחב כתפיים.","שמרו על מרפקים צמודים לגוף וזרועות עליונות ללא תזוזה.","נשפו וכופפו באיטיות את המוט מטה לכיוון הירכיים, תוך שמירה על שורשי כף יד ישרים.","עצרו לרגע בנקודה התחתונה של התנועה, תוך כיווץ הבייספס.","שאפו והחזירו את המוט באיטיות לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатному станку на самом высоком уровне.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмитесь за перекладину хватом снизу, руки на ширине плеч.","Держите локти близко к бокам, а плечи неподвижно.","Выдохните и медленно согните штангу к бедрам, сохраняя запястья прямыми.","Задержитесь на мгновение в нижней части движения, напрягая бицепсы.","Вдохните и медленно верните штангу в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Sujeta una barra recta a la máquina de cable en el ajuste más alto.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos.","Exhala y curva lentamente la barra hacia los muslos, manteniendo las muñecas rectas.","Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps.","Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."]}},{"id":"0201","name":"cable pushdown","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0201-3ZflifB.jpg","gif_url":"videos/0201-3ZflifB.gif","instruction_steps":{"he":["חברו מוט ישר לגלגלת עליונה במכשיר הכבלים.","עמדו מול המכשיר עם רגליים ברוחב כתפיים וכיפוף קל בברכיים.","אחזו במוט באחיזה עליונה, ידיים ברוחב כתפיים.","שמרו על מרפקים צמודים לגוף וזרועות עליונות ללא תזוזה.","נשפו ודחפו את המוט למטה עד יישור מלא של המרפקים.","עצרו לרגע, ואז שאפו והחזירו את המוט באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and push the bar down until your elbows are fully extended.","Pause for a moment, then inhale and slowly return the bar to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатной машине с высоким шкивом.","Встаньте лицом к тренажеру, ноги на ширине плеч и слегка согните колени.","Возьмите штангу хватом сверху, руки на ширине плеч.","Держите локти близко к бокам, а плечи неподвижно.","Выдохните и опустите штангу вниз, пока локти полностью не выпрямятся.","Сделайте паузу на мгновение, затем вдохните и медленно верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una barra recta a una máquina de cable con polea alta.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.","Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos.","Exhala y empuja la barra hacia abajo hasta que los codos queden completamente extendidos.","Haz una pausa por un momento, luego inhala y regresa lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0199","name":"cable pushdown (straight arm) v. 2","category":"back","body_part":"back","equipment":"cable","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"lats","image":"images/0199-PskORrA.jpg","gif_url":"videos/0199-PskORrA.gif","instruction_steps":{"he":["חברו מוט ישר לגלגלת עליונה במכשיר הכבלים.","עמדו מול המכשיר עם רגליים ברוחב כתפיים וכיפוף קל בברכיים.","אחזו במוט באחיזה עליונה, תוך שמירה על ידיים ישרות וכפות ידיים כלפי מטה.","הפעילו את הליבה ושמרו על גב ישר תוך שאתם נושפים ודוחפים את המוט למטה לכיוון הירכיים.","עצרו לרגע בנקודה התחתונה, ואז החזירו באיטיות את המוט לנקודת ההתחלה תוך שאיפה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Engage your core and keep your back straight as you exhale and push the bar down towards your thighs.","Pause for a moment at the bottom, then slowly return the bar to the starting position while inhaling.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатной машине с высоким шкивом.","Встаньте лицом к тренажеру, ноги на ширине плеч и слегка согните колени.","Возьмите перекладину хватом сверху, держа руки прямыми и ладонями вниз.","Напрягите корпус и держите спину прямо, на выдохе толкайте штангу вниз к бедрам.","Задержитесь на мгновение в нижней точке, затем медленно верните штангу в исходное положение на вдохе.","Повторите необходимое количество повторений."],"es":["Sujeta una barra recta a una máquina de cable con polea alta.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.","Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo.","Activa el core y mantén la espalda recta mientras exhalas y empujas la barra hacia abajo en dirección a los muslos.","Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial mientras inhalas.","Repite el número de repeticiones deseado."]}},{"id":"0200","name":"cable pushdown (with rope attachment)","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0200-dU605di.jpg","gif_url":"videos/0200-dU605di.gif","instruction_steps":{"he":["חברו ידית חבל לגלגלת עליונה במכשיר הכבלים.","עמדו מול המכשיר עם רגליים ברוחב כתפיים וכיפוף קל בברכיים.","אחזו בחבל באחיזה עליונה, כפות ידיים פונות זו לזו.","שמרו על מרפקים צמודים לצידי הגוף וזרועות עליונות ללא תזוזה לאורך כל התרגיל.","נשפו ודחפו את החבל מטה ביישור המרפקים עד יישור מלא של הידיים.","עצרו לרגע, ואז שאפו וחזרו באיטיות לנקודת ההתחלה בכיפוף המרפקים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope attachment to a high pulley on a cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the rope with an overhand grip, palms facing each other.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and push the rope downward by extending your elbows until your arms are fully extended.","Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к высокому блоку канатной машины.","Встаньте лицом к тренажеру, ноги на ширине плеч и слегка согните колени.","Возьмите веревку хватом сверху, ладони обращены друг к другу.","На протяжении всего упражнения держите локти близко к бокам, а плечи неподвижными.","Выдохните и толкните веревку вниз, разгибая локти до тех пор, пока руки полностью не выпрямятся.","Сделайте паузу на мгновение, затем вдохните и медленно вернитесь в исходное положение, сгибая локти.","Повторите необходимое количество повторений."],"es":["Sujeta un accesorio de cuerda a una polea alta en una máquina de cable.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.","Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Exhala y empuja la cuerda hacia abajo extendiendo los codos hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento, luego inhala y regresa lentamente a la posición inicial permitiendo que los codos se flexionen.","Repite el número de repeticiones deseado."]}},{"id":"0202","name":"cable rear delt row (stirrups)","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/0202-yUdIGNs.jpg","gif_url":"videos/0202-yUdIGNs.gif","instruction_steps":{"he":["חברו ידית ארכוף לגלגלת כבל תחתונה ועמדו מול המכשיר.","אחזו בידית ביד שמאל וצעדו לאחור עם כף רגל ימין, במיקום הגוף בזווית קלה.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וליבה מופעלת.","עם יד שמאל מתוחה וכף היד כלפי מטה, משכו את הידית לכיוון החזה בכיווץ השכמה לאחור.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ השכמה.","שחררו באיטיות את הידית חזרה לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי.","החליפו צדדים וחזרו על התרגיל עם יד ימין."],"en":["Attach a stirrup handle to a low cable pulley and stand facing the machine.","Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade.","Pause for a moment at the top of the movement, squeezing your shoulder blade.","Slowly release the handle back to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your right arm."],"ru":["Прикрепите ручку стремени к низкому шкиву троса и встаньте лицом к машине.","Возьмитесь за рукоятку левой рукой и сделайте шаг назад правой ногой, расположив тело под небольшим углом.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой и напряженный корпус.","Вытянув левую руку ладонью вниз, потяните рукоятку к груди, втягивая лопатку.","Задержитесь на мгновение в верхней точке движения, сжимая лопатку.","Медленно отпустите ручку обратно в исходное положение и повторите необходимое количество повторений.","Поменяйте сторону и повторите упражнение правой рукой."],"es":["Sujeta un asa de estribo a una polea de cable baja y ponte de pie frente a la máquina.","Sujeta el asa con la mano izquierda y retrocede un paso con el pie derecho, colocando el cuerpo en un ligero ángulo.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Con el brazo izquierdo extendido y la palma hacia abajo, jala el asa hacia el pecho retrayendo el omóplato.","Haz una pausa por un momento en la parte más alta del movimiento, apretando el omóplato.","Suelta lentamente el asa de vuelta a la posición inicial y repite el número de repeticiones deseado.","Cambia de lado y repite el ejercicio con el brazo derecho."]}},{"id":"0203","name":"cable rear delt row (with rope)","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/0203-wqNPGCg.jpg","gif_url":"videos/0203-wqNPGCg.gif","instruction_steps":{"he":["חברו ידית חבל למכשיר כבלים בגלגלת תחתונה.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו בידית החבל באחיזה עליונה, כפות ידיים פונות זו לזו.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","שמרו על מרפקים כפופים מעט ומשכו את החבל לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה, ואז שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an overhand grip, palms facing each other.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревочную ручку к канатной машине с низким шкивом.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмитесь за ручку веревки верхним хватом, ладони обращены друг к другу.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Держите локти слегка согнутыми и тяните веревку к груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una agarradera de cuerda a una máquina de cable con polea baja.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la agarradera de cuerda con un agarre prono, con las palmas una frente a la otra.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Mantén los codos ligeramente flexionados y jala la cuerda hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte más alta del movimiento y luego libera lentamente la tensión, regresando a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0204","name":"cable rear drive","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"triceps","image":"images/0204-c3QQLPi.jpg","gif_url":"videos/0204-c3QQLPi.gif","instruction_steps":{"he":["חברו ידית למכשיר כבלים בגלגלת תחתונה ועמדו עם הגב למכשיר.","אחזו בידית באחיזה עליונה ומתחו את הידיים ישר לפניכם.","תוך שמירה על מרפקים ללא תזוזה, משכו את הידית לאחור לכיוון הגוף, בכיווץ הטרייספס בסוף התנועה.","החזירו באיטיות את הידית לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a handle to a low pulley cable machine and stand facing away from the machine.","Grasp the handle with an overhand grip and extend your arms straight out in front of you.","Keeping your elbows stationary, pull the handle back towards your body, squeezing your triceps at the end of the movement.","Slowly return the handle to the starting position and repeat for the desired number of repetitions."],"ru":["Прикрепите ручку к машине с тросом с низким шкивом и встаньте лицом в сторону от машины.","Возьмитесь за рукоятку верхним хватом и вытяните руки прямо перед собой.","Удерживая локти неподвижными, потяните рукоятку назад к телу, сжимая трицепсы в конце движения.","Медленно верните рукоятку в исходное положение и повторите необходимое количество повторений."],"es":["Sujeta una agarradera a una máquina de cable con polea baja y ponte de pie de espaldas a la máquina.","Sujeta la agarradera con un agarre prono y extiende los brazos rectos frente a ti.","Manteniendo los codos inmóviles, jala la agarradera de vuelta hacia el cuerpo, apretando los tríceps al final del movimiento.","Regresa lentamente la agarradera a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"0205","name":"cable rear pulldown","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0205-SpsOSXk.jpg","gif_url":"videos/0205-SpsOSXk.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים כך שהגלגלת בתנוחה הגבוהה ביותר.","שבו מול המכשיר עם כפות רגליים על הרצפה וברכיים כפופות מעט.","אחזו באביזר הכבל באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","היטו מעט לאחור, תוך שמירה על גב ישר וחזה מורם.","משכו את אביזר הכבל מטה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, ואז שחררו באיטיות את הכבל חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable machine so that the pulley is at the highest position.","Sit facing the machine with your feet flat on the ground and your knees slightly bent.","Grasp the cable attachment with an overhand grip, hands slightly wider than shoulder-width apart.","Lean back slightly, keeping your back straight and your chest up.","Pull the cable attachment down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the cable back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте тросовую машину так, чтобы шкив находился в самом высоком положении.","Сядьте лицом к машине, поставьте ступни на землю и слегка согните колени.","Возьмитесь за блочное крепление верхним хватом, расставив руки чуть шире плеч.","Слегка откиньтесь назад, держа спину прямо и грудь вверх.","Потяните крепление троса вниз к груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно отпустите трос обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de cable de modo que la polea quede en la posición más alta.","Siéntate frente a la máquina con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta el accesorio del cable con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado.","Jala el accesorio del cable hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente el cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0873","name":"cable reverse crunch","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0873-RqOtqD7.jpg","gif_url":"videos/0873-RqOtqD7.gif","instruction_steps":{"he":["חברו כבל לגלגלת תחתונה ושכבו על הגב על מזרן.","החזיקו את הכבל בשתי ידיים ומתחו את הידיים ישר לכיוון התקרה.","כופפו ברכיים והרימו את הרגליים, בהבאת הירכיים לכיוון החזה.","תוך שמירה על פלג גוף עליון יציב, גלגלו את האגן למעלה לכיוון החזה, בהרמת האגן מהמזרן.","עצרו לרגע בנקודה העליונה, ואז הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a cable to a low pulley and lie down facing up on a mat.","Hold the cable with both hands and extend your arms straight up towards the ceiling.","Bend your knees and lift your legs up, bringing your thighs towards your chest.","While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите трос к низкому блоку и лягте на коврик лицом вверх.","Возьмите трос обеими руками и вытяните руки прямо вверх к потолку.","Согните колени и поднимите ноги вверх, приближая бедра к груди.","Сохраняя устойчивость верхней части тела, поднимите таз к груди, отрывая бедра от коврика.","Задержитесь на мгновение в верхней точке, затем медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta un cable a una polea baja y túmbate boca arriba sobre un tapete.","Sujeta el cable con ambas manos y extiende los brazos rectos hacia el techo.","Flexiona las rodillas y levanta las piernas, llevando los muslos hacia el pecho.","Mientras mantienes la parte superior del cuerpo estable, curva la pelvis hacia el pecho, levantando las caderas del tapete.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0206","name":"cable reverse curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0206-eOG0r6v.jpg","gif_url":"videos/0206-eOG0r6v.gif","instruction_steps":{"he":["חברו מוט ישר למכשיר כבלים בגלגלת תחתונה.","עמדו מול המכשיר עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","אחזו במוט באחיזה תחתונה, ידיים ברוחב כתפיים.","שמרו על מרפקים צמודים לצידי הגוף וזרועות עליונות ללא תזוזה לאורך כל התרגיל.","נשפו וכופפו את המוט למעלה לכיוון הכתפיים, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатной машине с низким шкивом.","Встаньте лицом к тренажеру, ноги на ширине плеч и слегка согнуты в коленях.","Возьмитесь за перекладину хватом снизу, руки на ширине плеч.","На протяжении всего упражнения держите локти близко к бокам, а плечи неподвижными.","Выдохните и поднимите штангу к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите штангу обратно в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Coloca una barra recta en una máquina de cable con polea baja.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"2406","name":"cable reverse grip triceps pushdown (sz-bar) (with arm blaster)","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/2406-ThKP69G.jpg","gif_url":"videos/2406-ThKP69G.gif","instruction_steps":{"he":["חברו מוט ישר למכשיר הכבלים בגובה הגבוה ביותר.","עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה תחתונה, כפות ידיים כלפי מעלה, וידיים ברוחב כתפיים.","שמרו על מרפקים צמודים לצידי הגוף וזרועות עליונות ללא תזוזה לאורך כל התרגיל.","הפעילו את הטרייספס ודחפו באיטיות את המוט מטה עד יישור מלא של הידיים.","עצרו לרגע בנקודה התחתונה, ואז החזירו באיטיות את המוט לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and slowly push the bar down until your arms are fully extended.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатному станку на самом высоком уровне.","Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмите перекладину хватом снизу, ладони вверх, руки на ширине плеч.","На протяжении всего упражнения держите локти близко к бокам, а плечи неподвижными.","Задействуйте трицепсы и медленно толкайте штангу вниз, пока руки полностью не выпрямятся.","Задержитесь на мгновение в нижней точке, затем медленно верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una barra recta a la máquina de cable en el ajuste más alto.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Activa los tríceps y empuja lentamente la barra hacia abajo hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1413","name":"cable reverse one arm curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1413-gVlnLIJ.jpg","gif_url":"videos/1413-gVlnLIJ.gif","instruction_steps":{"he":["עמדו מול מכשיר כבלים עם רגליים ברוחב כתפיים.","אחזו בידית הכבל באחיזה תחתונה, כף יד כלפי מטה.","שמרו על מרפק צמוד לגוף וגלגלו באיטיות את האמה למעלה לכיוון הכתף.","עצרו לרגע בנקודה העליונה, ואז הורידו את האמה באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing down.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмитесь за рукоятку троса снизу ладонью вниз.","Держите локоть близко к боку и медленно согните предплечье к плечу.","Задержитесь на мгновение в верхней точке, затем медленно опустите предплечье обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con un agarre supino, con la palma hacia abajo.","Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro.","Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0209","name":"cable reverse preacher curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0209-IwX5NqK.jpg","gif_url":"videos/0209-IwX5NqK.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים כך שכרית הפריצ'ר בגובה החזה.","שבו על ספסל הפריצ'ר והניחו את הזרועות העליונות על הכרית, עם כפות ידיים כלפי מטה ומרפקים מתוחים לגמרי.","אחזו בידיות הכבל באחיזה תחתונה, ברוחב כתפיים.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את הידיות לכיוון הכתפיים, תוך כיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","שאפו והורידו את הידיות באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של המרפקים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable machine so that the preacher curl pad is at chest height.","Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.","Grab the cable handles with an underhand grip, shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте блочный тренажер так, чтобы подушечка для сгибаний проповедника находилась на уровне груди.","Сядьте на скамью для сгибаний рук и положите плечи на подушечку ладонями вниз и полностью выпрямите локти.","Возьмитесь за рукоятки троса обратным хватом на ширине плеч.","Удерживая плечи неподвижно, выдохните и согните рукоятки к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Вдохните и медленно опустите ручки обратно в исходное положение, полностью разгибая локти.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.","Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, con las palmas hacia abajo y los codos completamente extendidos.","Agarra las agarraderas del cable con un agarre supino, separadas a la altura de los hombros.","Manteniendo la parte superior de los brazos inmóvil, exhala y curva las agarraderas hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente las agarraderas de vuelta a la posición inicial, extendiendo los codos por completo.","Repite el número de repeticiones deseado."]}},{"id":"0210","name":"cable reverse wrist curl","category":"lower arms","body_part":"lower arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms","wrists"],"target":"forearms","image":"images/0210-eYmsEPR.jpg","gif_url":"videos/0210-eYmsEPR.gif","instruction_steps":{"he":["חברו כבל לגלגלת תחתונה ושבו על ספסל מול מכשיר הכבלים.","אחזו בידית הכבל באחיזה עליונה, כפות ידיים כלפי מטה.","השעינו את האמות על הירכיים, כששורשי כף היד משתלשלים מעבר לקצה.","תוך שמירה על אמות ללא תזוזה, נשפו וגלגלו את שורשי כף היד כלפי מעלה עד הסוף.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את שורשי כף היד באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a cable to a low pulley and sit on a bench facing the cable machine.","Grasp the cable handle with an overhand grip, palms facing down.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите трос к низкому шкиву и сядьте на скамью лицом к канатной машине.","Возьмитесь за рукоятку троса сверху, ладонями вниз.","Положите предплечья на бедра так, чтобы запястья свисали с краев.","Удерживая предплечья неподвижно, выдохните и согните запястья вверх как можно дальше.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите запястья обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta un cable a una polea baja y siéntate en un banco frente a la máquina de cable.","Sujeta la agarradera del cable con un agarre prono, con las palmas hacia abajo.","Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde.","Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.","Haz una pausa por un momento en la parte alta, luego inhala y baja lentamente las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0207","name":"cable reverse-grip pushdown","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0207-VjYliFZ.jpg","gif_url":"videos/0207-VjYliFZ.gif","instruction_steps":{"he":["חברו מוט ישר לגלגלת עליונה במכשיר הכבלים.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה תחתונה, כפות ידיים כלפי מעלה, וידיים ברוחב כתפיים.","שמרו על מרפקים צמודים לצידי הגוף וזרועות עליונות ללא תזוזה לאורך כל התרגיל.","בעזרת הטרייספס, דחפו את המוט מטה עד יישור מלא של הידיים וכיווץ הטרייספס.","עצרו לרגע, ואז החזירו באיטיות את המוט לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted.","Pause for a moment, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатной машине с высоким шкивом.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмите перекладину хватом снизу, ладони вверх, руки на ширине плеч.","На протяжении всего упражнения держите локти близко к бокам, а плечи неподвижными.","Используя трицепсы, толкайте штангу вниз до тех пор, пока руки полностью не выпрямятся, а трицепсы не сократятся.","Сделайте паузу на мгновение, затем медленно верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una barra recta a una máquina de cable con polea alta.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Usando los tríceps, empuja la barra hacia abajo hasta que los brazos queden completamente extendidos y los tríceps contraídos.","Haz una pausa por un momento y luego regresa lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0208","name":"cable reverse-grip straight back seated high row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0208-PNtsX17.jpg","gif_url":"videos/0208-PNtsX17.gif","instruction_steps":{"he":["שבו על המושב מול מכשיר הכבלים עם כפות רגליים על הרצפה.","אחזו באביזר הכבל באחיזה תחתונה, כפות ידיים כלפי מעלה, וידיים ברוחב כתפיים.","שמרו על גב ישר ורכנו מעט קדימה מהירכיים.","משכו את הכבל לכיוון הגו בכיווץ השכמות לאחור והפעלת שרירי הגב.","עצרו לרגע בשיא הכיווץ, ואז שחררו באיטיות את הכבל חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the seat facing the cable machine with your feet flat on the floor.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from your hips.","Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на сиденье лицом к блочному тренажеру, поставив ноги на пол.","Возьмитесь за блочное крепление обратным хватом, ладонями вверх, руки на ширине плеч.","Держите спину прямо и слегка наклонитесь вперед от бедер.","Потяните трос к туловищу, сводя лопатки и напрягая мышцы спины.","Сделайте паузу на мгновение на пике сокращения, затем медленно отпустите трос обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate frente a la máquina de cable con los pies apoyados planos en el suelo.","Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.","Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.","Jala el cable hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda.","Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1320","name":"cable rope crossover seated row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1320-UFGF6gk.jpg","gif_url":"videos/1320-UFGF6gk.gif","instruction_steps":{"he":["שבו על מכשיר החתירה עם כפות רגליים על משענות הרגליים וברכיים כפופות מעט.","אחזו בחבלי הכבל באחיזה עליונה, כפות ידיים פונות זו לזו.","היטו את הגוף מעט לאחור, תוך שמירה על גב ישר וליבה מופעלת.","משכו את חבלי הכבל לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה, ואז שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable ropes towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на гребной тренажер, поставьте ноги на подножки и слегка согните колени.","Возьмитесь за канаты верхним хватом, ладони обращены друг к другу.","Слегка откиньтесь назад, сохраняя спину прямой и напряженный корпус.","Потяните тросы к груди, сжимая лопатки вместе.","Задержитесь на мгновение на пике движения, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra.","Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado.","Jala las cuerdas del cable hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1321","name":"cable rope elevated seated row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1321-c8oybX6.jpg","gif_url":"videos/1321-c8oybX6.gif","instruction_steps":{"he":["שבו על המושב המוגבה מול מכשיר הכבלים.","אחזו בידיות חבל הכבל באחיזה עליונה, כפות ידיים פונות זו לזו.","שמרו על גב ישר והיטו מעט לאחור, עם כיפוף קל בברכיים.","משכו את הכבל לכיוון הגוף בכיווץ השכמות לאחור והפעלת שרירי הגב.","עצרו לרגע בתנוחת הכיווץ המלא.","שחררו באיטיות את המתח ויישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the elevated seat facing the cable machine.","Grab the cable rope handles with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back, maintaining a slight bend in your knees.","Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the fully contracted position.","Slowly release the tension and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на возвышение лицом к канатной машине.","Возьмитесь за рукоятки каната верхним хватом, ладони обращены друг к другу.","Держите спину прямо и слегка откиньтесь назад, сохраняя небольшой изгиб в коленях.","Потяните трос к себе, сводя лопатки и напрягая мышцы спины.","Сделайте паузу на мгновение в полностью сокращенном положении.","Медленно ослабьте напряжение и вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el asiento elevado frente a la máquina de cable.","Agarra las agarraderas de cuerda con un agarre prono, con las palmas una frente a la otra.","Mantén la espalda recta e inclínate ligeramente hacia atrás, conservando una ligera flexión en las rodillas.","Jala el cable hacia el cuerpo retrayendo los omóplatos y apretando los músculos de la espalda.","Haz una pausa por un momento en la posición de contracción completa.","Libera lentamente la tensión y extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1322","name":"cable rope extension incline bench row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/1322-MgKwAAo.jpg","gif_url":"videos/1322-MgKwAAo.gif","instruction_steps":{"he":["הכינו ספסל שיפוע בזווית של 45 מעלות וחברו כבל לגלגלת התחתונה.","חברו ידית חבל למכשיר הכבלים ושבו על ספסל השיפוע מול המכשיר.","אחזו בידית החבל באחיזה עליונה ורכנו קדימה, תוך שמירה על גב ישר.","מתחו את הידיים לגמרי, במשיכת החבל לכיוון החזה העליון תוך שמירה על מרפקים צמודים לגוף.","כווצו את השכמות זו לזו בסוף התנועה.","שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.","Attach a rope handle to the cable machine and sit on the incline bench facing the machine.","Grab the rope handle with an overhand grip and lean forward, keeping your back straight.","Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов и прикрепите тросовую машину к нижнему шкиву.","Прикрепите веревочную ручку к канатному тренажеру и сядьте на наклонную скамью лицом к тренажеру.","Возьмитесь за рукоятку веревки верхним хватом и наклонитесь вперед, держа спину прямо.","Полностью выпрямите руки, потянув веревку к верхней части груди, сохраняя при этом локти близко к телу.","В конце движения сведите лопатки вместе.","Медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados y sujeta una máquina de cable a la polea baja.","Sujeta una agarradera de cuerda a la máquina de cable y siéntate en el banco inclinado frente a la máquina.","Agarra la agarradera de cuerda con un agarre prono e inclínate hacia adelante, manteniendo la espalda recta.","Extiende los brazos por completo, jalando la cuerda hacia la parte superior del pecho mientras mantienes los codos cerca del cuerpo.","Aprieta los omóplatos al final del movimiento.","Libera lentamente la tensión y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1639","name":"cable rope hammer preacher curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1639-PcPe0P5.jpg","gif_url":"videos/1639-PcPe0P5.gif","instruction_steps":{"he":["חברו ידית חבל למכשיר כבלים בגלגלת תחתונה.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו בחבל באחיזה ניטרלית (כפות ידיים פונות זו לזו).","הצמידו את הזרועות העליונות לכרית ספסל הפריצ'ר, תוך שמירה על מרפקים כפופים מעט.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את החבל לכיוון הכתפיים בכיווץ הבייספס.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והורידו את החבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope attachment to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with a neutral grip (palms facing each other).","Position your upper arms against the preacher bench pad, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the rope back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к канатной машине с низким шкивом.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмите веревку нейтральным хватом (ладони обращены друг к другу).","Положите плечи на подставку для скамьи проповедника, слегка согнув локти.","Удерживая плечи неподвижно, выдохните и согните скакалку к плечам, напрягая бицепсы.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно опустите веревку обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta un accesorio de cuerda a una máquina de cable con polea baja.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra).","Coloca la parte superior de los brazos contra la almohadilla del banco scott, manteniendo los codos ligeramente flexionados.","Manteniendo la parte superior de los brazos inmóvil, exhala y curva la cuerda hacia los hombros contrayendo los bíceps.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la cuerda de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1724","name":"cable rope high pulley overhead tricep extension","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1724-NN8nSNT.jpg","gif_url":"videos/1724-NN8nSNT.gif","instruction_steps":{"he":["חברו חבל לגלגלת עליונה וכווננו את המשקל בהתאם.","עמדו עם הגב למכשיר הגלגלת, רגליים ברוחב כתפיים.","אחזו בחבל בשתי ידיים, כפות ידיים כלפי מטה, והביאו את הידיים מעל הראש.","שמרו על הזרועות העליונות קרובות לראש וניצבות לרצפה.","הורידו באיטיות את החבל מאחורי הראש בכיפוף המרפקים.","עצרו לרגע, ואז יישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope to a high pulley and adjust the weight accordingly.","Stand facing away from the pulley machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down, and bring your hands above your head.","Keep your upper arms close to your head and perpendicular to the floor.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к высокому блоку и соответствующим образом отрегулируйте вес.","Встаньте лицом от шкива, поставив ноги на ширине плеч.","Возьмите веревку обеими руками ладонями вниз и поднимите руки над головой.","Держите плечи близко к голове и перпендикулярно полу.","Медленно опустите веревку за голову, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una cuerda a una polea alta y ajusta el peso según corresponda.","Ponte de pie de espaldas a la máquina de poleas con los pies separados a la altura de los hombros.","Sujeta la cuerda con ambas manos, con las palmas hacia abajo, y lleva las manos por encima de la cabeza.","Mantén la parte superior de los brazos cerca de la cabeza y perpendicular al suelo.","Baja lentamente la cuerda detrás de la cabeza flexionando los codos.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1725","name":"cable rope incline tricep extension","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1725-ZujAdR9.jpg","gif_url":"videos/1725-ZujAdR9.gif","instruction_steps":{"he":["חברו חבל לגלגלת עליונה וכווננו את ספסל השיפוע לזווית נוחה.","עמדו עם הגב לגלגלת, רגליים ברוחב כתפיים.","אחזו בחבל באחיזה עליונה ומתחו את הידיים ישר מעל הראש.","שמרו על מרפקים קרובים לראש וזרועות עליונות ללא תזוזה לאורך כל התרגיל.","הורידו את החבל מאחורי הראש בכיפוף המרפקים עד שהאמות נוגעות בבייספס.","עצרו לרגע, ואז יישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.","Stand facing away from the pulley with your feet shoulder-width apart.","Grasp the rope with an overhand grip and extend your arms straight overhead.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Lower the rope behind your head by bending your elbows until your forearms touch your biceps.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к высокому блоку и отрегулируйте наклон скамьи под удобным углом.","Встаньте лицом от шкива, поставив ноги на ширине плеч.","Возьмите веревку хватом сверху и вытяните руки прямо над головой.","На протяжении всего упражнения держите локти близко к голове, а плечи неподвижно.","Опустите скакалку за голову, сгибая локти, пока предплечья не коснутся бицепсов.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una cuerda a una polea alta y ajusta el banco inclinado a un ángulo cómodo.","Ponte de pie de espaldas a la polea con los pies separados a la altura de los hombros.","Sujeta la cuerda con un agarre prono y extiende los brazos rectos por encima de la cabeza.","Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio.","Baja la cuerda detrás de la cabeza flexionando los codos hasta que los antebrazos toquen los bíceps.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1726","name":"cable rope lying on floor tricep extension","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1726-U3ffHlY.jpg","gif_url":"videos/1726-U3ffHlY.gif","instruction_steps":{"he":["חברו חבל למכשיר הכבלים וכווננו אותו לתנוחה הנמוכה ביותר.","שכבו על הרצפה על הגב, כשהראש לכיוון מכשיר הכבלים.","אחזו בחבל בשתי ידיים, כפות ידיים פונות זו לזו, ומתחו את הידיים ישר לכיוון התקרה.","שמרו על הזרועות העליונות ללא תזוזה והורידו באיטיות את החבל לכיוון המצח, בכיפוף המרפקים.","עצרו לרגע, ואז יישרו את הידיים חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope to a cable machine and set it to the lowest position.","Lie on the floor facing up, with your head towards the cable machine.","Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling.","Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к канатной машине и установите ее в самое нижнее положение.","Лягте на пол лицом вверх, головой в сторону канатной машины.","Возьмите веревку обеими руками, ладонями друг к другу, и вытяните руки прямо вверх к потолку.","Держите плечи неподвижно и медленно опустите веревку ко лбу, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una cuerda a una máquina de cable y colócala en la posición más baja.","Túmbate en el suelo boca arriba, con la cabeza orientada hacia la máquina de cable.","Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos hacia el techo.","Mantén la parte superior de los brazos inmóvil y baja lentamente la cuerda hacia la frente, flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1640","name":"cable rope one arm hammer preacher curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1640-4hATdoB.jpg","gif_url":"videos/1640-4hATdoB.gif","instruction_steps":{"he":["חברו ידית חבל למכשיר כבלים בגלגלת תחתונה.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו בידית החבל באחיזה תחתונה, כפות ידיים כלפי מעלה.","מקמו את הזרוע העליונה כנגד כרית ספסל הפריצ'ר, תוך שמירה על מרפק כפוף מעט.","שמרו על גב ישר וליבה מופעלת לאורך כל התרגיל.","כופפו באיטיות את ידית החבל לכיוון הכתף, תוך שמירה על הזרוע העליונה ללא תזוזה.","כווצו את הבייספס בנקודה העליונה של התנועה, ואז הורידו את ידית החבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an underhand grip, palms facing up.","Position your upper arm against the preacher bench pad, keeping your elbow slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Прикрепите веревочную ручку к канатной машине с низким шкивом.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмитесь за рукоятку веревки обратным хватом ладонями вверх.","Положите плечо на подушку скамьи проповедника, слегка согнув локоть.","На протяжении всего упражнения держите спину прямой и напряженным корпус.","Медленно согните рукоятку веревки к плечу, сохраняя плечо неподвижным.","Напрягите бицепсы в верхней точке движения, затем медленно опустите рукоятку веревки обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Sujeta una agarradera de cuerda a una máquina de cable con polea baja.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la agarradera de cuerda con un agarre supino, con las palmas hacia arriba.","Coloca la parte superior del brazo contra la almohadilla del banco scott, manteniendo el codo ligeramente flexionado.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Curva lentamente la agarradera de cuerda hacia el hombro, manteniendo la parte superior del brazo inmóvil.","Aprieta el bíceps en la parte más alta del movimiento y luego baja lentamente la agarradera de cuerda de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1323","name":"cable rope seated row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1323-SJqRxOt.jpg","gif_url":"videos/1323-SJqRxOt.gif","instruction_steps":{"he":["שבו על מכשיר החתירה עם כפות רגליים על משענות הרגליים וברכיים כפופות מעט.","אחזו בחבלי הכבל באחיזה עליונה, כפות ידיים פונות זו לזו.","שמרו על גב ישר ורכנו מעט קדימה, תוך שמירה על כיפוף קל במרפקים.","משכו את חבלי הכבל לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה, ואז שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the cable ropes towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на гребной тренажер, поставьте ноги на подножки и слегка согните колени.","Возьмитесь за канаты верхним хватом, ладони обращены друг к другу.","Держите спину прямо и слегка наклонитесь вперед, сохраняя небольшой изгиб в локтях.","Потяните тросы к себе, сжимая лопатки вместе.","Задержитесь на мгновение на пике движения, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra.","Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos.","Jala las cuerdas del cable hacia el cuerpo, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0211","name":"cable russian twists (on stability ball)","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0211-d9Xaxq6.jpg","gif_url":"videos/0211-d9Xaxq6.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","החזיקו את ידית הכבל בשתי ידיים ומתחו את הידיים ישר לפניכם.","הטו את הגוף מעט לאחור תוך שמירה על גב ישר וליבה מופעלת.","סובבו את הגו ימינה, בהבאת ידית הכבל לכיוון מותן ימין.","עצרו לרגע, ואז סובבו את הגו שמאלה, בהבאת ידית הכבל לכיוון מותן שמאל.","המשיכו להחליף סיבובים למספר החזרות הרצוי."],"en":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold the cable handle with both hands and extend your arms straight out in front of you.","Lean back slightly while keeping your back straight and your core engaged.","Twist your torso to the right, bringing the cable handle towards your right hip.","Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip.","Continue alternating twists for the desired number of repetitions."],"ru":["Сядьте на мяч, поставив ступни на землю и согнув колени под углом 90 градусов.","Возьмите рукоятку троса обеими руками и вытяните руки прямо перед собой.","Слегка откиньтесь назад, сохраняя спину прямой и напряженный корпус.","Поверните туловище вправо, поднеся рукоятку троса к правому бедру.","Сделайте паузу на мгновение, затем поверните туловище влево, приближая рукоятку троса к левому бедру.","Продолжайте чередовать скручивания желаемое количество повторений."],"es":["Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti.","Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado.","Gira el torso hacia la derecha, llevando la agarradera del cable hacia la cadera derecha.","Haz una pausa por un momento y luego gira el torso hacia la izquierda, llevando la agarradera del cable hacia la cadera izquierda.","Continúa alternando los giros el número de repeticiones deseado."]}},{"id":"2144","name":"cable seated chest press","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/2144-nIR4Rwl.jpg","gif_url":"videos/2144-nIR4Rwl.gif","instruction_steps":{"he":["כווננו את גובה המושב וידיות הכבל לתנוחה נוחה.","שבו על הספסל עם גב ישר וכפות רגליים על הרצפה.","אחזו בידיות הכבל באחיזה עליונה בגובה הכתפיים.","דחפו את הידיות קדימה והרחק מהגוף, עד יישור מלא של הידיים.","עצרו לרגע, ואז החזירו את הידיות באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and cable handles to a comfortable position.","Sit on the bench with your back straight and feet flat on the floor.","Grasp the cable handles with an overhand grip at shoulder height.","Push the handles forward and away from your body, extending your arms fully.","Pause for a moment, then slowly bring the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и ручки троса в удобное положение.","Сядьте на скамью, выпрямив спину и поставив ступни на пол.","Возьмитесь за рукоятки троса верхним хватом на уровне плеч.","Толкайте рукоятки вперед и в сторону от тела, полностью выпрямляя руки.","Сделайте паузу на мгновение, затем медленно верните ручки в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y las agarraderas del cable a una posición cómoda.","Siéntate en el banco con la espalda recta y los pies apoyados planos en el suelo.","Sujeta las agarraderas del cable con un agarre prono a la altura del hombro.","Empuja las agarraderas hacia adelante y alejándolas del cuerpo, extendiendo los brazos por completo.","Haz una pausa por un momento y luego regresa lentamente las agarraderas a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0212","name":"cable seated crunch","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0212-8xUv4J7.jpg","gif_url":"videos/0212-8xUv4J7.gif","instruction_steps":{"he":["שבו על מכשיר הכבלים עם כפות רגליים על הרצפה וברכיים כפופות.","החזיקו את ידית הכבל בשתי ידיים ומקמו אותה מאחורי הראש.","הפעילו את שרירי הבטן וגלגלו באיטיות את פלג הגוף העליון קדימה, בהבאת החזה לכיוון הברכיים.","עצרו לרגע בנקודה העליונה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a cable machine with your feet flat on the ground and your knees bent.","Hold the cable handle with both hands and position it behind your head.","Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на канатный тренажер, поставив ноги на землю и согнув колени.","Возьмите рукоятку троса обеими руками и поместите ее за голову.","Напрягите пресс и медленно наклоните верхнюю часть тела вперед, приближая грудь к коленям.","Задержитесь на мгновение в верхней точке, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas flexionadas.","Sujeta la agarradera del cable con ambas manos y colócala detrás de la cabeza.","Activa el abdomen y curva lentamente la parte superior del cuerpo hacia adelante, llevando el pecho hacia las rodillas.","Haz una pausa por un momento en la parte alta y luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1641","name":"cable seated curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1641-8oYqOt9.jpg","gif_url":"videos/1641-8oYqOt9.gif","instruction_steps":{"he":["שבו על מכשיר הכבלים עם כפות רגליים על הרצפה וגב ישר.","אחזו באביזר הכבל באחיזה תחתונה, כפות ידיים כלפי מעלה, והידיים ישרות לגמרי.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את אביזר הכבל לכיוון הכתפיים, תוך כיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","שאפו והורידו את אביזר הכבל באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a cable machine with your feet flat on the ground and your back straight.","Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Сядьте на канатный тренажер, поставив ноги на землю и выпрямив спину.","Возьмитесь за блочное крепление обратным хватом, ладонями вверх и полностью выпрямленными руками.","Удерживая плечи неподвижно, выдохните и согните трос к плечам, сокращая бицепсы.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Вдохните и медленно опустите трос обратно в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Siéntate en una máquina de cable con los pies apoyados planos en el suelo y la espalda recta.","Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo la parte superior de los brazos inmóvil, exhala y curva el accesorio del cable hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0213","name":"cable seated high row (v-bar)","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0213-pwt0pnM.jpg","gif_url":"videos/0213-pwt0pnM.gif","instruction_steps":{"he":["שבו על מכשיר הכבלים עם כפות רגליים על הרצפה וברכיים כפופות מעט.","אחזו בידית ה-V באחיזה עליונה, כפות ידיים פונות זו לזו, וידיים ברוחב כתפיים.","שמרו על גב ישר ורכנו מעט קדימה מהירכיים.","משכו את ידית ה-V לכיוון הגו בכיווץ השכמות לאחור והפעלת שרירי הגב.","עצרו לרגע בשיא הכיווץ, ואז שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from the hips.","Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на канатный тренажер, поставьте ступни на пол и слегка согните колени.","Возьмитесь за насадку V-образной перекладины хватом сверху, ладони обращены друг к другу, руки на ширине плеч.","Держите спину прямо и слегка наклонитесь вперед от бедер.","Потяните V-образную планку к туловищу, сводя лопатки и напрягая мышцы спины.","Сделайте паузу на мгновение на пике сокращения, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta el accesorio en V con un agarre prono, con las palmas una frente a la otra y las manos separadas a la altura de los hombros.","Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.","Jala el accesorio en V hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda.","Haz una pausa por un momento en el punto más alto de la contracción, luego libera lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0214","name":"cable seated one arm alternate row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0214-vpp9Ku2.jpg","gif_url":"videos/0214-vpp9Ku2.gif","instruction_steps":{"he":["שבו על ספסל מול מכשיר כבלים עם כפות רגליים על הרצפה וברכיים כפופות מעט.","אחזו בידית ביד אחת ושמרו על היד מתוחה לגמרי לפניכם.","משכו את הידית לכיוון הגוף, בכיווץ השכמה ושמירה על מרפק קרוב לצד.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ שרירי הגב.","שחררו באיטיות את הידית חזרה לנקודת ההתחלה.","חזרו על התנועה עם היד השנייה.","החליפו בין הידיים לסירוגין למספר החזרות הרצוי."],"en":["Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.","Grasp the handle with one hand and keep your arm fully extended in front of you.","Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side.","Pause for a moment at the top of the movement, squeezing your back muscles.","Slowly release the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."],"ru":["Сядьте на скамью лицом к канатной машине, поставьте ступни на землю и слегка согните колени.","Возьмитесь за рукоятку одной рукой и держите руку полностью вытянутой перед собой.","Потяните рукоятку к себе, втягивая лопатку и держа локоть близко к боку.","Задержитесь на мгновение в верхней точке движения, напрягая мышцы спины.","Медленно отпустите ручку обратно в исходное положение.","Повторите с другой рукой.","Чередуйте руки, выполняя желаемое количество повторений."],"es":["Siéntate en un banco frente a una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta la agarradera con una mano y mantén el brazo completamente extendido frente a ti.","Jala la agarradera hacia el cuerpo, retrayendo el omóplato y manteniendo el codo cerca del costado.","Haz una pausa por un momento en la parte más alta del movimiento, apretando los músculos de la espalda.","Suelta lentamente la agarradera de vuelta a la posición inicial.","Repite con el otro brazo.","Alterna entre los brazos el número de repeticiones deseado."]}},{"id":"1642","name":"cable seated one arm concentration curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1642-rZ80Gbp.jpg","gif_url":"videos/1642-rZ80Gbp.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה וגב ישר.","החזיקו ידית כבל ביד אחת והניחו את המרפק על החלק הפנימי של הירך, מעט מעל הברך.","שמרו על הזרוע העליונה ללא תזוזה וכופפו את ידית הכבל לכיוון הכתף תוך נשיפה.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","הורידו את ידית הכבל באיטיות חזרה לנקודת ההתחלה תוך שאיפה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a bench with your feet flat on the floor and your back straight.","Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.","Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position while inhaling.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью, поставив ноги на пол и выпрямив спину.","Возьмите рукоятку троса одной рукой и поместите локоть на внутреннюю часть бедра, чуть выше колена.","Держите плечо неподвижно и на выдохе согните рукоятку троса к плечу.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Медленно опустите рукоятку троса обратно в исходное положение, одновременно вдыхая.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta.","Sujeta una agarradera del cable con una mano y coloca el codo en la parte interna del muslo, justo arriba de la rodilla.","Mantén la parte superior del brazo inmóvil y curva la agarradera del cable hacia el hombro mientras exhalas.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Baja lentamente la agarradera del cable de vuelta a la posición inicial mientras inhalas.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1643","name":"cable seated overhead curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1643-DpWMFP5.jpg","gif_url":"videos/1643-DpWMFP5.gif","instruction_steps":{"he":["שבו על ספסל מול מכשיר הכבלים עם כפות רגליים על הרצפה.","אחזו באביזר הכבל באחיזה תחתונה, כפות ידיים כלפי מעלה, וידיים ברוחב כתפיים.","שמרו על זרועות עליונות ללא תזוזה ומרפקים צמודים לצידי הגוף.","נשפו וכופפו את אביזר הכבל לכיוון הכתפיים, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","שאפו והורידו את אביזר הכבל באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your upper arms stationary and your elbows close to your sides.","Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью лицом к канатной машине, поставив ноги на землю.","Возьмитесь за блочное крепление обратным хватом, ладонями вверх, руки на ширине плеч.","Держите плечи неподвижно, а локти близко к бокам.","Выдохните и согните трос к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Вдохните и медленно опустите трос обратно в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo.","Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.","Mantén la parte superior de los brazos inmóvil y los codos cerca de los costados.","Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0215","name":"cable seated rear lateral raise","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0215-x825CZm.jpg","gif_url":"videos/0215-x825CZm.gif","instruction_steps":{"he":["שבו על ספסל מול מכשיר הכבלים עם כפות רגליים על הרצפה.","אחזו בידיות הכבל באחיזה עליונה ומתחו את הידיים ישר לפניכם.","תוך שמירה על ידיים ישרות, הרימו אותן באיטיות לצדדים עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable handles with an overhand grip and extend your arms straight in front of you.","Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью лицом к канатной машине, поставив ноги на землю.","Возьмитесь за рукоятки троса верхним хватом и вытяните руки прямо перед собой.","Держа руки прямыми, медленно поднимите их в стороны, пока они не станут параллельны полу.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo.","Sujeta las agarraderas del cable con un agarre prono y extiende los brazos rectos frente a ti.","Manteniendo los brazos rectos, levántalos lentamente hacia los lados hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0861","name":"cable seated row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0861-fUBheHs.jpg","gif_url":"videos/0861-fUBheHs.gif","instruction_steps":{"he":["שבו על מכשיר החתירה בכבל עם כפות רגליים על משענות הרגליים וברכיים כפופות מעט.","אחזו בידיות באחיזה עליונה, תוך שמירה על גב ישר וכתפיים רפויות.","משכו את הידיות לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה, ואז שחררו באיטיות את הידיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip, keeping your back straight and your shoulders relaxed.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на тренажер для тяги тросов, поставьте ноги на подножки и слегка согните колени.","Возьмитесь за рукоятки верхним хватом, сохраняя спину прямой, а плечи расслабленными.","Потяните ручки к телу, сведя лопатки вместе.","Задержитесь на мгновение на пике движения, затем медленно отпустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Sujeta las agarraderas con un agarre prono, manteniendo la espalda recta y los hombros relajados.","Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0216","name":"cable seated shoulder internal rotation","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"rotator cuff","secondary_muscles":["rotator cuff","triceps"],"target":"delts","image":"images/0216-YPoVrBi.jpg","gif_url":"videos/0216-YPoVrBi.gif","instruction_steps":{"he":["שבו על ספסל או כיסא מול מכשיר הכבלים עם כפות רגליים על הרצפה.","החזיקו את ידית הכבל עם היד מתוחה ישר לפניכם, מקבילה לרצפה.","שמרו על מרפק כפוף מעט ושכמות משוכות לאחור ולמטה.","סובבו באיטיות את היד פנימה, בהבאת ידית הכבל לכיוון מרכז הגוף.","עצרו לרגע בסוף התנועה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a bench or chair facing the cable machine with your feet flat on the ground.","Hold the cable handle with your arm extended straight out in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back and down.","Slowly rotate your arm inward, bringing the cable handle towards the center of your body.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью или стул лицом к канатной машине, поставив ноги на землю.","Держите рукоятку троса, вытянув руку прямо перед собой, параллельно земле.","Держите локоть слегка согнутым, а лопатки отведенными назад и вниз.","Медленно поверните руку внутрь, приближая рукоятку троса к центру тела.","Сделайте небольшую паузу в конце движения, затем медленно вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco o silla frente a la máquina de cable con los pies apoyados planos en el suelo.","Sujeta la agarradera del cable con el brazo extendido recto frente a ti, paralelo al suelo.","Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás y hacia abajo.","Rota lentamente el brazo hacia adentro, llevando la agarradera del cable hacia el centro del cuerpo.","Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"2399","name":"cable seated twist","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/2399-UEjSrKI.jpg","gif_url":"videos/2399-UEjSrKI.gif","instruction_steps":{"he":["שבו על מכשיר הכבלים עם כפות רגליים על הרצפה וברכיים כפופות מעט.","החזיקו את ידית הכבל בשתי ידיים ומתחו את הידיים ישר לפניכם.","תוך שמירה על ליבה מופעלת, סובבו באיטיות את הגו לצד אחד, במשיכת הכבל על פני הגוף.","עצרו לרגע בסוף טווח התנועה, ואז סובבו באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה בצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Sit on a cable machine with your feet flat on the ground and your knees slightly bent.","Hold the cable handle with both hands and extend your arms straight in front of you.","Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.","Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Сядьте на канатный тренажер, поставьте ступни на землю и слегка согните колени.","Возьмите рукоятку троса обеими руками и вытяните руки прямо перед собой.","Удерживая корпус в напряжении, медленно поверните туловище в сторону, протягивая трос через тело.","Сделайте паузу на мгновение в конце диапазона движения, затем медленно поверните обратно в исходное положение.","Повторите с другой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti.","Manteniendo el core activado, rota lentamente el torso hacia un lado, jalando el cable a través del cuerpo.","Haz una pausa por un momento al final del rango de movimiento y luego rota lentamente de vuelta a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0218","name":"cable seated wide-grip row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0218-qcY50ZD.jpg","gif_url":"videos/0218-qcY50ZD.gif","instruction_steps":{"he":["שבו על מכשיר החתירה בכבל עם כפות רגליים על משענות הרגליים וברכיים כפופות מעט.","אחזו בידית באחיזה עליונה רחבה, כפות ידיים כלפי מטה.","שמרו על גב ישר ורכנו מעט קדימה מהירכיים.","משכו את הידית לכיוון החזה התחתון, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא הכיווץ.","שחררו באיטיות את הידית חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handle with a wide overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the handle towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction.","Slowly release the handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Сядьте на тренажер для тяги тросов, поставьте ноги на подножки и слегка согните колени.","Возьмитесь за рукоятку широким хватом сверху ладонями вниз.","Держите спину прямо и слегка наклонитесь вперед от бедер.","Потяните ручку к нижней части груди, сжимая лопатки вместе.","Сделайте паузу на момент пика сокращения.","Медленно отпустите рукоятку обратно в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo.","Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.","Jala la agarradera hacia la parte baja del pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto más alto de la contracción.","Suelta lentamente la agarradera de vuelta a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."]}},{"id":"0219","name":"cable shoulder press","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0219-PzQanLE.jpg","gif_url":"videos/0219-PzQanLE.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים כך שהידיות בגובה הכתפיים.","עמדו עם הגב למכשיר, רגליים ברוחב כתפיים.","אחזו בידיות באחיזה עליונה והביאו אותן לגובה הכתפיים, עם מרפקים כפופים ופונים החוצה.","לחצו את הידיות כלפי מעלה עד יישור מלא של הידיים מעל הראש.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיות באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable machine so that the handles are at shoulder height.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.","Press the handles upwards until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте канатную машину так, чтобы ручки находились на высоте плеч.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмитесь за рукоятки хватом сверху и поднимите их до уровня плеч, согнув локти и направив их наружу.","Нажимайте рукоятки вверх, пока руки полностью не выпрямятся над головой.","Задержитесь на мгновение в верхней точке, затем медленно опустите ручки обратно до уровня плеч.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de cable de modo que las agarraderas queden a la altura del hombro.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta las agarraderas con un agarre prono y llévalas hasta la altura del hombro, con los codos flexionados y apuntando hacia afuera.","Empuja las agarraderas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa por un momento en la parte alta y luego baja lentamente las agarraderas de vuelta a la altura del hombro.","Repite el número de repeticiones deseado."]}},{"id":"0220","name":"cable shrug","category":"back","body_part":"back","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0220-Eg98Ft9.jpg","gif_url":"videos/0220-Eg98Ft9.gif","instruction_steps":{"he":["עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","אחזו בידיות הכבל באחיזה עליונה ותנו לידיים להשתלשל לפניכם.","עם ידיים ישרות, משכו את הכתפיים למעלה לכיוון האוזניים.","החזיקו את הכיווץ לרגע, ואז הורידו את הכתפיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handles with an overhand grip and let your arms hang down in front of you.","Keeping your arms straight, shrug your shoulders up towards your ears.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмитесь за рукоятки троса верхним хватом и опустите руки перед собой.","Держа руки прямыми, поднимите плечи к ушам.","Удерживайте напряжение на мгновение, затем медленно опустите плечи обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta las agarraderas del cable con un agarre prono y deja que los brazos cuelguen frente a ti.","Manteniendo los brazos rectos, encoge los hombros hacia las orejas.","Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0222","name":"cable side bend","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0222-wPypxFY.jpg","gif_url":"videos/0222-wPypxFY.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים ואחזו בידית הכבל ביד אחת.","שמרו על גב ישר וליבה מופעלת.","הטו באיטיות את הגו הצידה מהמותניים, בהורדת ידית הכבל לכיוון הברך.","עצרו לרגע, ואז חזרו לנקודת ההתחלה.","חזרו על התנועה בצד השני.","החליפו צדדים לסירוגין למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and grasp the cable handle with one hand.","Keep your back straight and your core engaged.","Slowly bend sideways at the waist, lowering the cable handle towards your knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Alternate sides for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, и возьмитесь за рукоятку троса одной рукой.","Держите спину прямо, а корпус напряженным.","Медленно наклонитесь в сторону в талии, опуская рукоятку троса к колену.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите с другой стороны.","Чередуйте стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con una mano.","Mantén la espalda recta y el core activado.","Flexiona lentamente la cintura hacia un lado, bajando la agarradera del cable hacia la rodilla.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite del otro lado.","Alterna los lados durante el número de repeticiones deseado."]}},{"id":"0221","name":"cable side bend crunch (bosu ball)","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0221-qatbkEd.jpg","gif_url":"videos/0221-qatbkEd.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים ידית כבל ביד אחת.","הניחו את היד השנייה על המותן.","הפעילו את הליבה והיטו את הגוף באיטיות הצידה לכיוון היד שאוחזת בכבל, תוך שמירה על גב ישר.","עצרו לרגע בנקודה התחתונה של התנועה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, holding a cable handle in one hand.","Place the other hand on your hip.","Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, в одной руке возьмитесь за рукоятку троса.","Вторую руку положите на бедро.","Напрягите корпус и медленно наклонитесь в сторону руки, держащей трос, сохраняя спину прямой.","Сделайте паузу на мгновение в нижней части движения, затем медленно вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando la agarradera del cable con una mano.","Coloca la otra mano en la cadera.","Activa el core y flexiona lentamente la cintura hacia el lado en que sujetas el cable, manteniendo la espalda recta.","Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0223","name":"cable side crunch","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0223-q2ADGqV.jpg","gif_url":"videos/0223-q2ADGqV.gif","instruction_steps":{"he":["חברו ידית כבל לגלגלת תחתונה ועמדו עם הצד למכשיר.","אחזו בידית עם היד הרחוקה מהמכשיר והניחו את היד השנייה על המותן.","שמרו על רגליים ברוחב כתפיים וברכיים כפופות מעט.","עם שרירי בטן מופעלים, הטו את הגוף הצידה מהמותניים, בהבאת המרפק מטה לכיוון המותן.","עצרו לרגע בנקודה התחתונה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Attach a cable handle to a low pulley and stand sideways to the machine.","Grasp the handle with the hand furthest from the machine and place your other hand on your hip.","Keep your feet shoulder-width apart and your knees slightly bent.","With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Прикрепите тросовую рукоятку к низкому шкиву и встаньте боком к машине.","Возьмитесь за рукоятку рукой, которая находится дальше всего от тренажера, а другую руку положите на бедро.","Держите ноги на ширине плеч, а колени слегка согнуты.","Задействовав пресс, согнитесь в талии в сторону, опустив локоть к бедру.","Задержитесь на мгновение внизу, затем медленно вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Coloca un mango de cable en una polea baja y ponte de pie de lado a la máquina.","Agarra el mango con la mano más alejada de la máquina y coloca la otra mano en tu cadera.","Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.","Con el abdomen activado, flexiona la cintura hacia el lado, bajando el codo hacia la cadera.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"1717","name":"cable squat row (with rope attachment)","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/1717-f7fnAIB.jpg","gif_url":"videos/1717-f7fnAIB.gif","instruction_steps":{"he":["חברו חבל למכשיר כבלים בגובה המותניים.","עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","כופפו ברכיים והורידו את הגוף לעמדת סקוואט, תוך שמירה על גב ישר וחזה מורם.","אחזו בחבל באחיזה עליונה, ידיים ברוחב כתפיים.","הפעילו את הליבה ומשכו את החבל לכיוון הגוף, בכיווץ השכמות זו לזו.","שמרו על מרפקים צמודים לגוף והמשיכו למשוך עד שהידיים מגיעות לחזה.","עצרו לרגע בנקודה העליונה של התנועה, ואז שחררו באיטיות את החבל ויישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope to a cable machine at waist height.","Stand facing the cable machine with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position, keeping your back straight and chest up.","Grasp the rope with an overhand grip, with your hands shoulder-width apart.","Engage your core and pull the rope towards your body, squeezing your shoulder blades together.","Keep your elbows close to your body and continue pulling until your hands reach your chest.","Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к канатному тренажеру на уровне талии.","Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Согните ноги в коленях и опустите тело в положение приседа, держа спину прямо и грудь вверх.","Возьмите веревку хватом сверху, руки на ширине плеч.","Напрягите корпус и потяните веревку к себе, сжимая лопатки вместе.","Держите локти близко к телу и продолжайте тянуть, пока руки не достигнут груди.","Сделайте паузу на мгновение в верхней точке движения, затем медленно отпустите веревку и вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una cuerda a una máquina de cable a la altura de la cintura.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Agarra la cuerda con un agarre prono, con las manos separadas a la altura de los hombros.","Activa el core y tira de la cuerda hacia tu cuerpo, apretando los omóplatos entre sí.","Mantén los codos cerca del cuerpo y continúa tirando hasta que las manos lleguen a tu pecho.","Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente la cuerda y extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1644","name":"cable squatting curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1644-3XFdb1Z.jpg","gif_url":"videos/1644-3XFdb1Z.gif","instruction_steps":{"he":["חברו ידית כבל לתנוחה הנמוכה ביותר במכשיר הכבלים.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","החזיקו את ידית הכבל באחיזה תחתונה, כפות ידיים כלפי מעלה, וידיים מתוחות לגמרי.","הורידו את הגוף לעמדת סקוואט, תוך שמירה על גב ישר וברכיים מאחורי קצות האצבעות.","תוך כדי הירידה לסקוואט, כופפו את ידית הכבל לכיוון הכתפיים, תוך שמירה על מרפקים צמודים לצידי הגוף.","עצרו לרגע בנקודה העליונה של הכפיפה, תוך כיווץ הבייספס.","הורידו את ידית הכבל באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a cable handle to the lowest setting on a cable machine.","Stand facing the machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip, palms facing up, and arms fully extended.","Lower your body into a squat position, keeping your back straight and knees behind your toes.","As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the curl, squeezing your biceps.","Slowly lower the cable handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Прикрепите тросовую рукоятку к самой низкой позиции на тросовой машине.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Держите рукоятку троса обратным хватом ладонями вверх и полностью выпрямленными руками.","Опустите тело в присед, сохраняя спину прямой и колени за носками ног.","Приседая, согните рукоятку троса к плечам, держа локти близко к бокам.","Задержитесь на мгновение в верхней части сгибания, сжимая бицепсы.","Медленно опустите рукоятку троса обратно в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Coloca un mango de cable en el ajuste más bajo de una máquina de cable.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta el mango del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.","Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies.","Mientras te agachas, flexiona el mango del cable hacia los hombros, manteniendo los codos cerca de los costados.","Haz una pausa breve en la parte alta del movimiento, apretando los bíceps.","Baja lentamente el mango del cable de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0224","name":"cable standing back wrist curl","category":"lower arms","body_part":"lower arms","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0224-VhX2JdE.jpg","gif_url":"videos/0224-VhX2JdE.gif","instruction_steps":{"he":["עמדו מול מכשיר כבלים עם רגליים ברוחב כתפיים.","החזיקו את ידית הכבל באחיזה עליונה, כפות ידיים כלפי מטה.","שמרו על ידיים ישרות ומרפקים צמודים לצידי הגוף.","גלגלו באיטיות את שורשי כף היד כלפי מעלה, בהבאת ידית הכבל לכיוון הגוף.","עצרו לרגע בנקודה העליונה, ואז הורידו את ידית הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with an overhand grip, palms facing down.","Keep your arms straight and your elbows close to your sides.","Slowly curl your wrists upward, bringing the cable handle towards your body.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмите рукоятку троса верхним хватом ладонями вниз.","Держите руки прямо, локти близко к бокам.","Медленно согните запястья вверх, приближая рукоятку троса к телу.","Задержитесь на мгновение в верхней точке, затем медленно опустите рукоятку троса обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujeta el mango del cable con un agarre prono, con las palmas hacia abajo.","Mantén los brazos rectos y los codos cerca de los costados.","Flexiona lentamente las muñecas hacia arriba, llevando el mango del cable hacia tu cuerpo.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1375","name":"cable standing calf raise","category":"lower legs","body_part":"lower legs","equipment":"cable","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1375-yl2IYyy.jpg","gif_url":"videos/1375-yl2IYyy.gif","instruction_steps":{"he":["עמדו מול מכשיר כבלים עם רגליים ברוחב כתפיים.","אחזו בידיות מכשיר הכבלים או חברו רצועת קרסול של כבל לקרסוליים.","הרימו את העקבים מהרצפה על ידי יישור הקרסוליים גבוה ככל האפשר.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine handles or attach a cable ankle strap to your ankles.","Raise your heels off the ground by extending your ankles as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Держитесь за ручки канатного тренажера или прикрепите к лодыжкам ремешок с тросом.","Поднимите пятки от земли, вытянув лодыжки как можно выше.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujétate de los mangos de la máquina de cable o coloca una correa de tobillo de cable en tus tobillos.","Levanta los talones del suelo extendiendo los tobillos lo más alto posible.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0225","name":"cable standing cross-over high reverse fly","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","rear deltoids"],"target":"delts","image":"images/0225-P5p0j8B.jpg","gif_url":"videos/0225-P5p0j8B.gif","instruction_steps":{"he":["חברו ידית D לכל צד של מכשיר הכבלים בגובה הכתפיים.","עמדו במרכז מכשיר הכבלים עם רגליים ברוחב כתפיים.","אחזו בידיות באחיזה עליונה ומתחו את הידיים לצדדים, כפות ידיים פונות קדימה.","שמרו על כיפוף קל במרפקים וגב ישר לאורך כל התרגיל.","הפעילו את שרירי הכתפיים וכווצו את השכמות זו לזו תוך משיכת הידיות לכיוון קדמת הגוף.","עצרו לרגע בשיא התנועה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a D-handle to each side of a cable machine at shoulder height.","Stand in the middle of the cable machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward.","Keep a slight bend in your elbows and maintain a straight back throughout the exercise.","Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body.","Pause for a moment at the peak of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите D-образную рукоятку к каждой стороне канатной машины на высоте плеч.","Встаньте посередине канатной машины, поставив ноги на ширине плеч.","Возьмитесь за рукоятки хватом сверху и вытяните руки в стороны ладонями вперед.","Сохраняйте небольшой изгиб в локтях и сохраняйте прямую спину на протяжении всего упражнения.","Напрягите мышцы плеч и сведите лопатки вместе, потянув рукоятки к передней части тела.","Задержитесь на мгновение на пике движения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un mango en D en cada lado de una máquina de cable a la altura de los hombros.","Ponte de pie en el medio de la máquina de cable con los pies separados a la altura de los hombros.","Agarra los mangos con un agarre prono y extiende los brazos hacia los lados, con las palmas hacia adelante.","Mantén una ligera flexión en los codos y conserva la espalda recta durante todo el ejercicio.","Activa los músculos de los hombros y aprieta los omóplatos entre sí mientras tiras de los mangos hacia la parte delantera de tu cuerpo.","Haz una pausa breve en el punto máximo del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0226","name":"cable standing crunch","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0226-jpgqxiS.jpg","gif_url":"videos/0226-jpgqxiS.gif","instruction_steps":{"he":["חברו ידית כבל לגלגלת עליונה ועמדו עם הגב למכשיר.","החזיקו את הידית בשתי ידיים ומקמו אותה מאחורי הראש, עם מרפקים כפופים.","עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","תוך הפעלת שרירי הבטן, נשפו וגלגלו את הגו מטה לכיוון הברכיים, בהבאת המרפקים לכיוון הירכיים.","עצרו לרגע בנקודה התחתונה של התנועה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a cable handle to a high pulley and stand facing away from the machine.","Hold the handle with both hands and place it behind your head, keeping your elbows bent.","Stand with your feet shoulder-width apart and your knees slightly bent.","Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите тросовую рукоятку к высокому шкиву и встаньте лицом от машины.","Возьмите рукоятку обеими руками и поместите ее за голову, держа локти согнутыми.","Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Удерживая пресс в напряжении, выдохните и опустите туловище к коленям, подтягивая локти к бедрам.","Сделайте паузу на мгновение в нижней части движения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un mango de cable en una polea alta y ponte de pie de espaldas a la máquina.","Sujeta el mango con ambas manos y colócalo detrás de la cabeza, manteniendo los codos flexionados.","Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Con el abdomen activado, exhala y flexiona el torso hacia las rodillas, llevando los codos hacia los muslos.","Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0874","name":"cable standing crunch (with rope attachment)","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0874-XU3ePuv.jpg","gif_url":"videos/0874-XU3ePuv.gif","instruction_steps":{"he":["חברו חבל למכשיר כבלים בגובה החזה.","עמדו עם הגב למכשיר, רגליים ברוחב כתפיים.","אחזו בחבל בשתי ידיים והביאו אותו מאחורי הראש, עם מרפקים כפופים.","הפעילו את שרירי הבטן וגלגלו באיטיות את הגו קדימה, בהבאת המרפקים לכיוון הברכיים.","עצרו לרגע בנקודה העליונה של הכפיפה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope to a cable machine at chest height.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the rope with both hands and bring it behind your head, keeping your elbows bent.","Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к канатному тренажеру на уровне груди.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмите веревку обеими руками и заведите ее за голову, держа локти согнутыми.","Напрягите пресс и медленно наклоните туловище вперед, приближая локти к коленям.","Сделайте паузу на мгновение в верхней точке скручивания, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una cuerda a una máquina de cable a la altura del pecho.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta la cuerda con ambas manos y llévala detrás de la cabeza, manteniendo los codos flexionados.","Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando los codos hacia las rodillas.","Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0227","name":"cable standing fly","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0227-Pr9Rhf4.jpg","gif_url":"videos/0227-Pr9Rhf4.gif","instruction_steps":{"he":["חברו את הידיות לכבלים בגובה החזה.","עמדו עם רגליים ברוחב כתפיים, עם הגב למכשיר הכבלים.","אחזו בידיות באחיזה עליונה, כפות ידיים פונות קדימה.","צעדו מעט קדימה ליצירת מתח בכבלים.","שמרו על ליבה מופעלת וגב ישר לאורך כל התרגיל.","עם כיפוף קל במרפקים, הביאו באיטיות את הידיים קדימה ויחד מול החזה.","כווצו את שרירי החזה בשיא התנועה.","הפכו באיטיות את התנועה והחזירו את הידיים לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the handles to the cables at chest height.","Stand with your feet shoulder-width apart, facing away from the cable machine.","Grasp the handles with an overhand grip, palms facing forward.","Step forward slightly to create tension in the cables.","Keep your core engaged and your back straight throughout the exercise.","With a slight bend in your elbows, slowly bring your arms forward and together in front of your chest.","Squeeze your chest muscles at the peak of the movement.","Slowly reverse the movement, returning your arms to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ручки к тросам на уровне груди.","Встаньте, поставив ноги на ширине плеч, лицом в сторону от блочного тренажера.","Возьмитесь за рукоятки хватом сверху, ладонями вперед.","Слегка шагните вперед, чтобы создать натяжение тросов.","На протяжении всего упражнения держите корпус напряженным, а спину прямой.","Слегка согнув локти, медленно сведите руки вперед и вместе перед грудью.","Напрягите мышцы груди на пике движения.","Медленно выполните обратное движение, возвращая руки в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca los mangos en los cables a la altura del pecho.","Ponte de pie con los pies separados a la altura de los hombros, de espaldas a la máquina de cable.","Agarra los mangos con un agarre prono, con las palmas hacia adelante.","Da un paso adelante para crear tensión en los cables.","Mantén el core activado y la espalda recta durante todo el ejercicio.","Con una ligera flexión en los codos, lleva lentamente los brazos hacia adelante y júntalos frente al pecho.","Aprieta los músculos del pecho en el punto máximo del movimiento.","Invierte lentamente el movimiento, regresando los brazos a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0228","name":"cable standing hip extension","category":"upper legs","body_part":"upper legs","equipment":"cable","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/0228-Kpajagk.jpg","gif_url":"videos/0228-Kpajagk.gif","instruction_steps":{"he":["חברו כבל לגלגלת תחתונה ועמדו עם הגב למכשיר.","מקמו את הכבל סביב הקרסול ועמדו עם רגליים ברוחב כתפיים.","שמרו על ליבה מופעלת וגב ישר לאורך כל התרגיל.","מתחו באיטיות את הרגל ישר לאחור, בכיווץ הישבן בנקודה העליונה של התנועה.","עצרו לרגע, ואז חזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי.","החליפו צדדים וחזרו על התרגיל ברגל השנייה."],"en":["Attach a cable to a low pulley and stand facing away from the machine.","Place the cable around your ankle and stand with your feet shoulder-width apart.","Keep your core engaged and your back straight throughout the exercise.","Slowly extend your leg straight back, squeezing your glutes at the top of the movement.","Pause for a moment, then return to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat with the other leg."],"ru":["Прикрепите трос к нижнему шкиву и встаньте лицом от машины.","Оберните трос вокруг лодыжки и встаньте, поставив ноги на ширине плеч.","На протяжении всего упражнения держите корпус напряженным, а спину прямой.","Медленно вытяните ногу прямо назад, сжимая ягодицы в верхней части движения.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите необходимое количество повторений.","Поменяйте сторону и повторите с другой ногой."],"es":["Sujeta un cable a una polea baja y ponte de pie de espaldas a la máquina.","Coloca el cable alrededor de tu tobillo y ponte de pie con los pies separados a la altura de los hombros.","Mantén el core activado y la espalda recta durante todo el ejercicio.","Extiende lentamente la pierna hacia atrás, apretando los glúteos en la parte alta del movimiento.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de lado y repite con la otra pierna."]}},{"id":"0229","name":"cable standing inner curl","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0229-YwnI4ja.jpg","gif_url":"videos/0229-YwnI4ja.gif","instruction_steps":{"he":["עמדו מול מכשיר כבלים עם רגליים ברוחב כתפיים.","אחזו בידית הכבל באחיזה תחתונה, כפות ידיים כלפי מעלה.","שמרו על מרפקים צמודים לגוף וזרועות עליונות ללא תזוזה.","נשפו וכופפו את ידית הכבל לכיוון הכתפיים, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","שאפו והורידו את ידית הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palms facing up.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the cable handle towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмитесь за рукоятку троса обратным хватом ладонями вверх.","Держите локти близко к бокам, а плечи неподвижно.","Выдохните и согните рукоятку троса к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Вдохните и медленно опустите рукоятку троса обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Agarra el mango del cable con un agarre supino, con las palmas hacia arriba.","Mantén los codos cerca de los costados y los brazos superiores quietos.","Exhala y flexiona el mango del cable hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente el mango del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0230","name":"cable standing lift","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0230-qFpAkpP.jpg","gif_url":"videos/0230-qFpAkpP.gif","instruction_steps":{"he":["עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","החזיקו את ידית הכבל בשתי ידיים ומקמו אותה בגובה המותניים.","הפעילו את הליבה ושמרו על גב ישר לאורך כל התרגיל.","תוך שמירה על ידיים ישרות, נשפו והרימו את ידית הכבל למעלה לכיוון הכתף הנגדית, תוך סיבוב הגו.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את ידית הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with both hands and position it at waist height.","Engage your core and maintain a straight back throughout the exercise.","Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso.","Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмите рукоятку троса обеими руками и расположите ее на уровне талии.","Задействуйте корпус и сохраняйте прямую спину на протяжении всего упражнения.","Удерживая руки прямыми, выдохните и поднимите рукоятку троса вверх к противоположному плечу, вращая туловище.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите рукоятку троса обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta el mango del cable con ambas manos y colócalo a la altura de la cintura.","Activa el core y mantén la espalda recta durante todo el ejercicio.","Manteniendo los brazos rectos, exhala y eleva el mango del cable hacia el hombro opuesto, rotando el torso.","Haz una pausa breve en la parte alta, luego inhala y baja lentamente el mango del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0231","name":"cable standing one arm triceps extension","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0231-sYCcnon.jpg","gif_url":"videos/0231-sYCcnon.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, מול מכשיר הכבלים.","החזיקו את ידית הכבל ביד ימין, כף יד כלפי מטה, ומקמו את היד מתוחה לגמרי ומקבילה לרצפה.","שמרו על מרפק ללא תזוזה וצמוד לגוף.","כופפו באיטיות את המרפק, בהורדת ידית הכבל לכיוון העורף.","עצרו לרגע בנקודה התחתונה של התנועה, ואז יישרו את היד חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד ובצעו עם יד שמאל."],"en":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground.","Keep your elbow stationary and close to your body.","Slowly bend your elbow, lowering the cable handle towards the back of your head.","Pause for a moment at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm."],"ru":["Встаньте, поставив ноги на ширине плеч, лицом к канатному тренажеру.","Возьмите рукоятку троса правой рукой ладонью вниз и расположите руку так, чтобы она была полностью выпрямлена и параллельна земле.","Держите локоть неподвижно и близко к телу.","Медленно согните локоть, опуская рукоятку троса к затылку.","Сделайте паузу на мгновение в нижней части движения, затем вытяните руку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону и выполните упражнение левой рукой."],"es":["Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.","Sujeta el mango del cable con la mano derecha, con la palma hacia abajo, y coloca el brazo completamente extendido y paralelo al suelo.","Mantén el codo quieto y cerca del cuerpo.","Flexiona lentamente el codo, bajando el mango del cable hacia la parte de atrás de la cabeza.","Haz una pausa breve en la parte baja del movimiento, luego extiende el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con el brazo izquierdo."]}},{"id":"1376","name":"cable standing one leg calf raise","category":"lower legs","body_part":"lower legs","equipment":"cable","muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/1376-fgc9Xdl.jpg","gif_url":"videos/1376-fgc9Xdl.gif","instruction_steps":{"he":["עמדו מול מכשיר כבלים עם רגליים ברוחב כתפיים.","אחזו במכשיר הכבלים לתמיכה.","הרימו רגל אחת מהרצפה ואזנו על הרגל השנייה.","הרימו באיטיות את העקב מהרצפה, בהרמת הגוף על קצות האצבעות.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקב באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine for support.","Lift one leg off the ground and balance on the other leg.","Slowly raise your heel off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Держитесь за тросовую машину для поддержки.","Поднимите одну ногу от земли и балансируйте на другой ноге.","Медленно поднимите пятку от земли, поднимая тело на носки.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятку обратно в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujétate de la máquina de cable para apoyarte.","Levanta una pierna del suelo y equilíbrate sobre la otra pierna.","Levanta lentamente el talón del suelo, elevando el cuerpo sobre las puntas de los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"0232","name":"cable standing pulldown (with rope)","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0232-CvPn9WV.jpg","gif_url":"videos/0232-CvPn9WV.gif","instruction_steps":{"he":["חברו חבל למכשיר הכבלים בגובה הגבוה ביותר.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו בחבל באחיזה עליונה, כפות ידיים כלפי מטה.","שמרו על גב ישר וליבה מופעלת לאורך כל התרגיל.","משכו את החבל מטה לכיוון הירכיים, תוך כיווץ הבייספס.","עצרו לרגע בנקודה התחתונה, ואז שחררו באיטיות את החבל חזרה למעלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Pull the rope down towards your thighs, squeezing your biceps.","Pause for a moment at the bottom, then slowly release the rope back up.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к канатному станку на самом высоком уровне.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмите веревку прямым хватом ладонями вниз.","На протяжении всего упражнения держите спину прямой и напряженным корпус.","Потяните веревку вниз к бедрам, сжимая бицепсы.","Задержитесь на мгновение внизу, затем медленно отпустите веревку обратно вверх.","Повторите необходимое количество повторений."],"es":["Sujeta una cuerda a la máquina de cable en el ajuste más alto.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Agarra la cuerda con un agarre prono, con las palmas hacia abajo.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Tira de la cuerda hacia abajo, hacia los muslos, apretando los bíceps.","Haz una pausa breve en la parte baja, luego suelta lentamente la cuerda hacia arriba.","Repite el número de repeticiones deseado."]}},{"id":"0233","name":"cable standing rear delt row (with rope)","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/0233-ZfyAGhK.jpg","gif_url":"videos/0233-ZfyAGhK.gif","instruction_steps":{"he":["עמדו מול מכשיר כבלים עם רגליים ברוחב כתפיים.","החזיקו את ידית הכבל בשתי ידיים, כפות ידיים פונות זו לזו, וצעדו לאחור ליצירת מתח בכבל.","שמרו על גב ישר וליבה מופעלת.","משכו את הכבל לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה, ואז שחררו באיטיות את הכבל חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.","Keep your back straight and your core engaged.","Pull the cable towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Удерживая трос обеими руками, ладонями друг к другу, отступите назад, чтобы создать натяжение троса.","Держите спину прямо, а корпус напряженным.","Потяните трос к себе, сжимая лопатки вместе.","Сделайте паузу на мгновение на пике движения, затем медленно отпустите трос обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujeta el accesorio del cable con ambas manos, con las palmas una frente a la otra, y retrocede un paso para crear tensión en el cable.","Mantén la espalda recta y el core activado.","Tira del cable hacia tu cuerpo, apretando los omóplatos entre sí.","Haz una pausa breve en el punto máximo del movimiento, luego suelta lentamente el cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1727","name":"cable standing reverse grip one arm overhead tricep extension","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1727-i11JWU7.jpg","gif_url":"videos/1727-i11JWU7.gif","instruction_steps":{"he":["עמדו עם הגב למכשיר הכבלים, רגליים ברוחב כתפיים.","החזיקו את ידית הכבל באחיזה תחתונה ומתחו את היד מעל הראש, תוך שמירה על מרפק קרוב לראש.","שמרו על הזרוע העליונה ללא תזוזה והורידו באיטיות את ידית הכבל מאחורי הראש בכיפוף המרפק.","עצרו לרגע בנקודה התחתונה, ואז יישרו את היד חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Stand facing away from the cable machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head.","Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Встаньте лицом от блочного тренажера, поставив ноги на ширине плеч.","Возьмите рукоятку троса хватом снизу и вытяните руку над головой, держа локоть близко к голове.","Держите плечо неподвижно и медленно опустите рукоятку троса за голову, сгибая локоть.","Задержитесь на мгновение в нижней точке, затем вытяните руку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta el mango del cable con un agarre supino y extiende el brazo por encima de la cabeza, manteniendo el codo cerca de la cabeza.","Mantén el brazo superior quieto y baja lentamente el mango del cable detrás de la cabeza flexionando el codo.","Haz una pausa breve en la parte baja, luego extiende el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0234","name":"cable standing row (v-bar)","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0234-4f8RXP8.jpg","gif_url":"videos/0234-4f8RXP8.gif","instruction_steps":{"he":["עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","אחזו בידית ה-V באחיזה עליונה, כפות ידיים כלפי מטה.","שמרו על גב ישר וליבה מופעלת.","משכו את ידית ה-V לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה, ואז שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar attachment with an overhand grip, palms facing down.","Keep your back straight and your core engaged.","Pull the v-bar towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмитесь за насадку V-образной рукоятки сверху, ладонями вниз.","Держите спину прямо, а корпус напряженным.","Потяните V-образную штангу к себе, сжимая лопатки вместе.","Задержитесь на мгновение на пике движения, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo.","Mantén la espalda recta y el core activado.","Tira del accesorio en V hacia tu cuerpo, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0235","name":"cable standing shoulder external rotation","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"rotator cuff","secondary_muscles":["rotator cuff","trapezius"],"target":"delts","image":"images/0235-FWdVhcW.jpg","gif_url":"videos/0235-FWdVhcW.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","החזיקו את ידית הכבל עם היד מתוחה לפניכם, מקבילה לרצפה.","שמרו על מרפק כפוף מעט ושכמות משוכות לאחור.","סובבו באיטיות את היד החוצה, הרחק מהגוף, תוך שמירה על המרפק באותה תנוחה.","עצרו לרגע בסוף התנועה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with your arm extended in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back.","Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Держите рукоятку троса, вытянув руку перед собой параллельно земле.","Держите локоть слегка согнутым, а лопатки отведенными назад.","Медленно поверните руку наружу, от тела, сохраняя локоть в том же положении.","Сделайте небольшую паузу в конце движения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta el mango del cable con el brazo extendido frente a ti, paralelo al suelo.","Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás.","Rota lentamente el brazo hacia afuera, alejándolo de tu cuerpo, manteniendo el codo en la misma posición.","Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0236","name":"cable standing twist row (v-bar)","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0236-JOZhu2h.jpg","gif_url":"videos/0236-JOZhu2h.gif","instruction_steps":{"he":["חברו ידית V למכשיר כבלים בגובה החזה.","עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","אחזו בידית ה-V באחיזה עליונה, כפות ידיים כלפי מטה.","צעדו לאחור ליצירת מתח בכבל.","שמרו על גב ישר וליבה מופעלת לאורך כל התרגיל.","משכו את ידית ה-V לכיוון הגו בכיווץ השכמות לאחור וכיפוף המרפקים.","תוך כדי המשיכה, סובבו את הגו לצד אחד, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה, בתחושת הכיווץ בגב העליון.","שחררו באיטיות את המתח וחזרו לנקודת ההתחלה, בסיבוב הגו חזרה.","חזרו על התנועה למספר החזרות הרצוי, בהחלפת כיוון הסיבוב בכל חזרה."],"en":["Attach a v-bar attachment to a cable machine at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down.","Take a step back to create tension in the cable.","Keep your back straight and core engaged throughout the exercise.","Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows.","As you pull, twist your torso to one side, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, feeling the contraction in your upper back.","Slowly release the tension and return to the starting position, untwisting your torso.","Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep."],"ru":["Прикрепите V-образную перекладину к канатному тренажеру на уровне груди.","Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмите V-образную перекладину хватом сверху, ладонями вниз.","Сделайте шаг назад, чтобы создать натяжение троса.","На протяжении всего упражнения держите спину прямой и напряженным корпус.","Потяните V-образную перекладину к туловищу, сводя лопатки и сгибая локти.","Во время тяги поверните туловище в сторону, сжимая лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения, почувствовав напряжение в верхней части спины.","Медленно ослабьте напряжение и вернитесь в исходное положение, раскручивая туловище.","Повторите движение желаемое количество повторений, чередуя направление скручивания при каждом повторении."],"es":["Coloca un accesorio en V en una máquina de cable a la altura del pecho.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo.","Da un paso atrás para crear tensión en el cable.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Tira del accesorio en V hacia tu torso retrayendo los omóplatos y flexionando los codos.","Mientras tiras, gira el torso hacia un lado, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta del movimiento, sintiendo la contracción en la parte alta de la espalda.","Suelta lentamente la tensión y regresa a la posición inicial, deshaciendo el giro del torso.","Repite el movimiento el número de repeticiones deseado, alternando la dirección del giro en cada repetición."]}},{"id":"1269","name":"cable standing up straight crossovers","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/1269-UKWTJWR.jpg","gif_url":"videos/1269-UKWTJWR.gif","instruction_steps":{"he":["עמדו במרכז מכשיר הכבלים עם רגליים ברוחב כתפיים.","החזיקו את ידיות הכבלים עם כפות ידיים כלפי מטה וידיים מתוחות ישר לצדדים.","תוך שמירה על ידיים ישרות, הביאו את הידיים יחד מול הגוף, בהצלבתן זו על זו.","עצרו לרגע, ואז חזרו באיטיות לנקודת ההתחלה, תוך שמירה על ידיים מתוחות.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand in the middle of a cable machine with your feet shoulder-width apart.","Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides.","Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.","Pause for a moment, then slowly return to the starting position, keeping your arms extended.","Repeat for the desired number of repetitions."],"ru":["Встаньте в центр канатной машины, поставив ноги на ширине плеч.","Держите ручки тросов ладонями вниз и вытяните руки в стороны.","Держа руки прямыми, сведите ладони перед собой, скрестив их друг с другом.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение, держа руки вытянутыми.","Повторите необходимое количество повторений."],"es":["Ponte de pie en el medio de una máquina de cable con los pies separados a la altura de los hombros.","Sujeta los mangos de los cables con las palmas hacia abajo y los brazos extendidos hacia los lados.","Manteniendo los brazos rectos, junta las manos frente a tu cuerpo, cruzándolas una sobre la otra.","Haz una pausa breve, luego regresa lentamente a la posición inicial, manteniendo los brazos extendidos.","Repite el número de repeticiones deseado."]}},{"id":"0238","name":"cable straight arm pulldown","category":"back","body_part":"back","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders","biceps"],"target":"lats","image":"images/0238-x69MAlq.jpg","gif_url":"videos/0238-x69MAlq.gif","instruction_steps":{"he":["חברו מוט ישר לגלגלת העליונה של מכשיר הכבלים.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה עליונה, תוך שמירה על ידיים ישרות וכפות ידיים כלפי מטה.","הפעילו את רחב הגבי ומשכו את המוט מטה לכיוון הירכיים, תוך שמירה על ידיים ישרות לאורך כל התנועה.","עצרו לרגע בנקודה התחתונה, ואז החזירו באיטיות את המוט לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to the high pulley of a cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к высокому шкиву канатной машины.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмите перекладину хватом сверху, держа руки прямыми и ладонями вниз.","Напрягите широчайшие и потяните штангу вниз к бедрам, сохраняя руки прямыми на протяжении всего движения.","Задержитесь на мгновение в нижней точке, затем медленно верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca una barra recta en la polea alta de una máquina de cable.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo.","Activa los dorsales y tira de la barra hacia abajo, hacia los muslos, manteniendo los brazos rectos durante todo el movimiento.","Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0237","name":"cable straight arm pulldown (with rope)","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0237-DT14T9T.jpg","gif_url":"videos/0237-DT14T9T.gif","instruction_steps":{"he":["חברו חבל למכשיר הכבלים בגובה הגבוה ביותר.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו בחבל בשתי ידיים, כפות ידיים כלפי מטה.","מתחו את הידיים לגמרי לפניכם, עם כיפוף קל במרפקים.","הפעילו את רחב הגבי ומשכו באיטיות את החבל מטה לכיוון הירכיים, תוך שמירה על ידיים ישרות.","עצרו לרגע בנקודה התחתונה, ואז שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down.","Extend your arms fully in front of you, keeping your elbows slightly bent.","Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к канатному станку на самом высоком уровне.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмите веревку обеими руками ладонями вниз.","Вытяните руки полностью перед собой, держа локти слегка согнутыми.","Напрягите широчайшие и медленно потяните веревку вниз к бедрам, держа руки прямыми.","Задержитесь на мгновение в нижней точке, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una cuerda a la máquina de cable en el ajuste más alto.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Agarra la cuerda con ambas manos, con las palmas hacia abajo.","Extiende completamente los brazos frente a ti, manteniendo los codos ligeramente flexionados.","Activa los dorsales y tira lentamente de la cuerda hacia abajo, hacia los muslos, manteniendo los brazos rectos.","Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0239","name":"cable straight back seated row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms","shoulders"],"target":"upper back","image":"images/0239-Tq6gbK6.jpg","gif_url":"videos/0239-Tq6gbK6.gif","instruction_steps":{"he":["שבו על מכשיר החתירה בכבל עם כפות רגליים על משענות הרגליים וברכיים כפופות מעט.","אחזו בידיות הכבל באחיזה עליונה, כפות ידיים כלפי מטה.","שמרו על גב ישר ורכנו מעט קדימה מהירכיים.","משכו את ידיות הכבל לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה, ואז שחררו באיטיות את הידיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the cable handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на тренажер для тяги тросов, поставьте ноги на подножки и слегка согните колени.","Возьмитесь за рукоятки троса верхним хватом ладонями вниз.","Держите спину прямо и слегка наклонитесь вперед от бедер.","Потяните рукоятки троса к себе, сжимая лопатки вместе.","Задержитесь на мгновение на пике движения, затем медленно отпустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Agarra los mangos del cable con un agarre prono, con las palmas hacia abajo.","Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.","Tira de los mangos del cable hacia tu cuerpo, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0240","name":"cable supine reverse fly","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0240-PQcUlDi.jpg","gif_url":"videos/0240-PQcUlDi.gif","instruction_steps":{"he":["חברו ידית D לגלגלת תחתונה במכשיר הכבלים ושכבו על הבטן על ספסל ישר.","אחזו בידית ה-D בכל יד, כפות ידיים כלפי מטה, ויישרו את הידיים ישר קדימה.","עם ידיים ישרות, הרימו אותן לצדדים עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.","Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите D-образную рукоятку к тренажеру с низким шкивом и лягте лицом вниз на ровную скамью.","Возьмите D-образную рукоятку каждой рукой ладонями вниз и вытяните руки прямо перед собой.","Держа руки прямыми, поднимите их в стороны, пока они не станут параллельны полу.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un mango en D en una máquina de cable con polea baja y túmbate boca abajo en un banco plano.","Agarra el mango en D con cada mano, con las palmas hacia abajo, y extiende los brazos frente a ti.","Manteniendo los brazos rectos, levántalos hacia los lados hasta que estén paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2464","name":"cable thibaudeau kayak row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/2464-ZgwWBoC.jpg","gif_url":"videos/2464-ZgwWBoC.gif","instruction_steps":{"he":["חברו ידית כבל לגלגלת תחתונה ושבו מול המכשיר עם כפות רגליים על הרצפה.","אחזו בידית ביד ימין ומתחו את היד לגמרי, עם כיפוף קל במרפק.","רכנו קדימה מהירכיים, תוך שמירה על גב ישר ובטן מופעלת.","משכו את הידית לכיוון הגו בכיווץ השכמה לאחור וכיפוף המרפק, תוך שמירה על היד קרובה לגוף.","כווצו את שרירי הגב בנקודה העליונה של התנועה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד ובצעו עם יד שמאל."],"en":["Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.","Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.","Lean forward from your hips, keeping your back straight and your abs engaged.","Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body.","Squeeze your back muscles at the top of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform with your left arm."],"ru":["Прикрепите тросовую рукоятку к низкому шкиву и сядьте лицом к машине, поставив ноги на пол.","Возьмитесь за рукоятку правой рукой и полностью вытяните руку, сохраняя небольшой изгиб в локте.","Наклонитесь вперед от бедер, сохраняя спину прямой и напряженный пресс.","Потяните рукоятку к туловищу, втягивая лопатку и сгибая локоть, удерживая руку близко к телу.","Напрягите мышцы спины в верхней точке движения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений, затем поменяйте сторону и выполните упражнение левой рукой."],"es":["Coloca un mango de cable en una polea baja y siéntate frente a la máquina con los pies planos en el suelo.","Agarra el mango con la mano derecha y extiende completamente el brazo, manteniendo una ligera flexión en el codo.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el abdomen activado.","Tira del mango hacia tu torso retrayendo el omóplato y flexionando el codo, manteniendo el brazo cerca del cuerpo.","Aprieta los músculos de la espalda en la parte alta del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con el brazo izquierdo."]}},{"id":"0241","name":"cable triceps pushdown (v-bar)","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0241-gAwDzB3.jpg","gif_url":"videos/0241-gAwDzB3.gif","instruction_steps":{"he":["חברו ידית V למכשיר הכבלים בתנוחה הגבוהה ביותר.","עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","אחזו בידית ה-V באחיזה עליונה, כפות ידיים כלפי מטה, וידיים ברוחב כתפיים.","שמרו על מרפקים צמודים לצידי הגוף וזרועות עליונות ללא תזוזה לאורך כל התרגיל.","הפעילו את הטרייספס ונשפו תוך דחיפת ידית ה-V מטה עד יישור מלא של הידיים.","עצרו לרגע בנקודה התחתונה של התנועה, תוך כיווץ הטרייספס.","שאפו תוך החזרת ידית ה-V באיטיות לנקודת ההתחלה, בשליטה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."],"ru":["Прикрепите V-образную насадку к тросовому станку на самой высокой скорости.","Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмитесь за V-образную перекладину хватом сверху, ладонями вниз, руки на ширине плеч.","На протяжении всего упражнения держите локти близко к бокам, а плечи неподвижными.","Задействуйте трицепсы и на выдохе опускайте V-образную планку вниз, пока руки полностью не выпрямятся.","Задержитесь на мгновение в нижней части движения, напрягая трицепсы.","На вдохе медленно возвращайте V-образную планку в исходное положение, сохраняя контроль.","Повторите необходимое количество повторений."],"es":["Coloca un accesorio en V en la máquina de cable en el ajuste más alto.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos.","Haz una pausa breve en la parte baja del movimiento, apretando los tríceps.","Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control.","Repite el número de repeticiones deseado."]}},{"id":"2405","name":"cable triceps pushdown (v-bar) (with arm blaster)","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/2405-OxJk1fg.jpg","gif_url":"videos/2405-OxJk1fg.gif","instruction_steps":{"he":["חברו ידית V למכשיר הכבלים בתנוחה הגבוהה ביותר.","עמדו מול מכשיר הכבלים עם רגליים ברוחב כתפיים.","אחזו בידית ה-V באחיזה עליונה, כפות ידיים כלפי מטה, וידיים ברוחב כתפיים.","שמרו על מרפקים צמודים לצידי הגוף וזרועות עליונות ללא תזוזה לאורך כל התרגיל.","הפעילו את הטרייספס ונשפו תוך דחיפת ידית ה-V מטה עד יישור מלא של הידיים.","עצרו לרגע בנקודה התחתונה של התנועה, תוך כיווץ הטרייספס.","שאפו תוך החזרת ידית ה-V באיטיות לנקודת ההתחלה, בשליטה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."],"ru":["Прикрепите V-образную насадку к тросовому станку на самой высокой скорости.","Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч.","Возьмитесь за V-образную перекладину хватом сверху, ладонями вниз, руки на ширине плеч.","На протяжении всего упражнения держите локти близко к бокам, а плечи неподвижными.","Задействуйте трицепсы и на выдохе опускайте V-образную планку вниз, пока руки полностью не выпрямятся.","Задержитесь на мгновение в нижней части движения, напрягая трицепсы.","На вдохе медленно возвращайте V-образную планку в исходное положение, сохраняя контроль.","Повторите необходимое количество повторений."],"es":["Coloca un accesorio en V en la máquina de cable en el ajuste más alto.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos.","Haz una pausa breve en la parte baja del movimiento, apretando los tríceps.","Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control.","Repite el número de repeticiones deseado."]}},{"id":"0242","name":"cable tuck reverse crunch","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0242-TXtXc84.jpg","gif_url":"videos/0242-TXtXc84.gif","instruction_steps":{"he":["חברו כבל לגלגלת תחתונה ושכבו על הגב על מזרן.","החזיקו את הכבל בשתי ידיים ומתחו את הידיים ישר מעל החזה.","כופפו ברכיים והרימו את הרגליים, בהבאת הברכיים לכיוון החזה.","בו-זמנית, גלגלו את האגן למעלה לכיוון החזה, בהרמתו מהרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את הרגליים והאגן חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a cable to a low pulley and lie down on a mat facing up.","Hold the cable with both hands and extend your arms straight up above your chest.","Bend your knees and lift your legs up, bringing your knees towards your chest.","At the same time, curl your pelvis up towards your chest, lifting your hips off the ground.","Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите трос к низкому блоку и лягте на коврик лицом вверх.","Возьмите трос обеими руками и вытяните руки прямо над грудью.","Согните ноги в коленях и поднимите ноги вверх, подтягивая колени к груди.","В то же время поднимите таз к груди, отрывая бедра от земли.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги и бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta un cable a una polea baja y túmbate boca arriba sobre una esterilla.","Sujeta el cable con ambas manos y extiende los brazos rectos por encima del pecho.","Flexiona las rodillas y levanta las piernas, llevando las rodillas hacia el pecho.","Al mismo tiempo, eleva la pelvis hacia el pecho, levantando las caderas del suelo.","Haz una pausa breve en la parte alta, luego baja lentamente las piernas y las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0243","name":"cable twist","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0243-aVs3BR3.jpg","gif_url":"videos/0243-aVs3BR3.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, מול מכשיר הכבלים.","החזיקו את ידית הכבל בשתי ידיים מול החזה, תוך שמירה על ידיים כפופות מעט.","הפעילו את הליבה וסובבו את הגו ימינה, במשיכת הכבל על פני הגוף.","עצרו לרגע בסוף התנועה, בהרגשת הכיווץ בשרירי הבטן והאלכסונים.","חזרו באיטיות לנקודת ההתחלה, תוך התנגדות למשיכת הכבל.","חזרו על התנועה לצד שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and twist your torso to the right, pulling the cable across your body.","Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.","Slowly return to the starting position, resisting the cable's pull.","Repeat the movement to the left side.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, лицом к канатному тренажеру.","Держите рукоятку троса обеими руками перед грудью, держа руки слегка согнутыми.","Напрягите корпус и поверните туловище вправо, протягивая трос через тело.","Сделайте паузу на мгновение в конце движения, чувствуя сокращение мышц пресса и косых мышц живота.","Медленно вернитесь в исходное положение, сопротивляясь натяжению троса.","Повторите движение в левую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.","Sujeta el mango del cable con ambas manos frente al pecho, manteniendo los brazos ligeramente flexionados.","Activa el core y gira el torso hacia la derecha, tirando del cable a través de tu cuerpo.","Haz una pausa breve al final del movimiento, sintiendo la contracción en el abdomen y los oblicuos.","Regresa lentamente a la posición inicial, resistiendo la tracción del cable.","Repite el movimiento hacia el lado izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0862","name":"cable twist (up-down)","category":"waist","body_part":"waist","equipment":"cable","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0862-fhZQPlV.jpg","gif_url":"videos/0862-fhZQPlV.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, מול מכשיר הכבלים.","החזיקו את ידית הכבל בשתי ידיים מול החזה, תוך שמירה על ידיים כפופות מעט.","הפעילו את הליבה וסובבו באיטיות את הגו לצד אחד, תוך שמירה על אגן ורגליים יציבים.","עצרו לרגע בסוף הסיבוב, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על הסיבוב לצד הנגדי.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the opposite side.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, лицом к канатному тренажеру.","Держите рукоятку троса обеими руками перед грудью, держа руки слегка согнутыми.","Напрягите корпус и медленно поверните туловище в сторону, сохраняя бедра и ноги устойчивыми.","Сделайте небольшую паузу в конце вращения, затем медленно вернитесь в исходное положение.","Повторите поворот в противоположную сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.","Sujeta el mango del cable con ambas manos frente al pecho, manteniendo los brazos ligeramente flexionados.","Activa el core y gira lentamente el torso hacia un lado, manteniendo las caderas y las piernas estables.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite el giro hacia el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0244","name":"cable twisting pull","category":"back","body_part":"back","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders","biceps"],"target":"lats","image":"images/0244-zCgxPbV.jpg","gif_url":"videos/0244-zCgxPbV.gif","instruction_steps":{"he":["חברו ידית כבל לגלגלת תחתונה ועמדו מול המכשיר.","אחזו בידית ביד שמאל וצעדו הרחק מהמכשיר, במתיחת היד המלאה.","מקמו את כפות הרגליים ברוחב כתפיים, עם ברכיים כפופות מעט.","שמרו על גב ישר וליבה מופעלת לאורך כל התרגיל.","משכו את הידית לכיוון הגוף, תוך סיבוב הגו ימינה תוך כדי.","כווצו את שרירי הגב בסוף התנועה.","חזרו באיטיות לנקודת ההתחלה, תוך שמירה על מתח בכבל.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד ובצעו עם יד ימין."],"en":["Attach a cable handle to a low pulley and stand facing the machine.","Grasp the handle with your left hand and step away from the machine, extending your arm fully.","Position your feet shoulder-width apart, with your knees slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Pull the handle towards your body, rotating your torso to the right as you do so.","Squeeze your back muscles at the end of the movement.","Slowly return to the starting position, keeping tension on the cable.","Repeat for the desired number of repetitions, then switch sides and perform with your right hand."],"ru":["Прикрепите тросовую ручку к низкому шкиву и встаньте лицом к машине.","Возьмитесь за рукоятку левой рукой и отойдите от тренажера, полностью вытянув руку.","Поставьте ноги на ширине плеч, слегка согнув колени.","На протяжении всего упражнения держите спину прямой и напряженным корпус.","Потяните ручку к себе, поворачивая при этом туловище вправо.","В конце движения напрягите мышцы спины.","Медленно вернитесь в исходное положение, сохраняя натяжение троса.","Повторите необходимое количество повторений, затем поменяйте сторону и выполните упражнение правой рукой."],"es":["Coloca un mango de cable en una polea baja y ponte de pie frente a la máquina.","Agarra el mango con la mano izquierda y aléjate de la máquina, extendiendo completamente el brazo.","Coloca los pies separados a la altura de los hombros, con las rodillas ligeramente flexionadas.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Tira del mango hacia tu cuerpo, rotando el torso hacia la derecha al hacerlo.","Aprieta los músculos de la espalda al final del movimiento.","Regresa lentamente a la posición inicial, manteniendo la tensión en el cable.","Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con la mano derecha."]}},{"id":"1645","name":"cable two arm curl on incline bench","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1645-H9y3Dkr.jpg","gif_url":"videos/1645-H9y3Dkr.gif","instruction_steps":{"he":["שבו על ספסל שיפוע כשהגב צמוד לכרית וכפות הרגליים על הרצפה.","אחזו בידיות הכבל באחיזה תחתונה, כפות ידיים כלפי מעלה, וידיים ישרות לגמרי.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את הידיות לכיוון הכתפיים תוך כיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","שאפו והורידו את הידיות באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an incline bench with your back against the pad and your feet flat on the ground.","Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Сядьте на наклонную скамью, прислонившись спиной к подушке, а ступни поставьте на землю.","Возьмитесь за рукоятки троса обратным хватом ладонями вверх и полностью выпрямите руки.","Удерживая плечи неподвижно, выдохните и согните рукоятки к плечам, одновременно напрягая бицепсы.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Вдохните и медленно опустите рукоятки обратно в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo.","Agarra los mangos del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo los brazos superiores quietos, exhala y flexiona los mangos hacia los hombros mientras contraes los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente los mangos de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1728","name":"cable two arm tricep kickback","category":"upper arms","body_part":"upper arms","equipment":"cable","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1728-vvNjDJS.jpg","gif_url":"videos/1728-vvNjDJS.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","החזיקו את ידית הכבל בכל יד, כפות ידיים פונות פנימה וידיים כפופות בזווית של 90 מעלות.","תוך שמירה על הזרועות העליונות ללא תזוזה, יישרו את האמות לאחור עד יישור מלא של הידיים.","עצרו לרגע, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Возьмите рукоятку троса в каждую руку ладонями внутрь и согните руки под углом 90 градусов.","Удерживая плечи неподвижно, вытяните предплечья назад до полного выпрямления рук.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta el mango del cable en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados.","Manteniendo los brazos superiores quietos, extiende los antebrazos hacia atrás hasta que los brazos estén completamente extendidos.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0245","name":"cable underhand pulldown","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0245-xBYcQHj.jpg","gif_url":"videos/0245-xBYcQHj.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים כך שמוט הפולדאון בגובה מעל הראש.","שבו על המושב ואחזו במוט הפולדאון באחיזה תחתונה, ידיים מעט רחבות מרוחב הכתפיים.","שמרו על גב ישר והיטו מעט לאחור.","משכו את המוט מטה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, ואז שחררו באיטיות את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and lean back slightly.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте канатную машину так, чтобы тяговая перекладина находилась на высоте над вашей головой.","Сядьте на сиденье и возьмитесь за перекладину хватом снизу, руки чуть шире плеч.","Держите спину прямо и слегка откиньтесь назад.","Потяните штангу вниз к груди, сведя лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно отпустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de cable de modo que la barra de jalón quede a una altura por encima de tu cabeza.","Siéntate y agarra la barra de jalón con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.","Mantén la espalda recta e inclínate ligeramente hacia atrás.","Jala la barra hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1270","name":"cable upper chest crossovers","category":"chest","body_part":"chest","equipment":"cable","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/1270-j7XMAyn.jpg","gif_url":"videos/1270-j7XMAyn.gif","instruction_steps":{"he":["חברו את הידיות לכבלים בגובה החזה.","עמדו במרכז מכשיר הכבלים עם כף רגל אחת מעט לפני השנייה.","אחזו בידיות עם כפות ידיים כלפי מטה וידיים מתוחות לצדדים.","שמרו על כיפוף קל במרפקים והפעילו את הליבה.","משכו את הכבלים יחד מול החזה, בהצלבתם זה על זה.","כווצו את שרירי החזה בשיא התנועה.","שחררו באיטיות את הכבלים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the handles to the cables at chest height.","Stand in the center of the cable machine with one foot slightly in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Keep a slight bend in your elbows and engage your core.","Pull the cables together in front of your chest, crossing them over each other.","Squeeze your chest muscles at the peak of the movement.","Slowly release the cables back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите ручки к тросам на уровне груди.","Встаньте в центр канатной машины, поставив одну ногу немного впереди другой.","Возьмитесь за ручки ладонями вниз и вытяните руки в стороны.","Сохраняйте небольшой изгиб в локтях и задействуйте корпус.","Стяните тросы вместе перед грудью, пересекая их друг над другом.","Напрягите мышцы груди на пике движения.","Медленно отпустите тросы обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca los mangos en los cables a la altura del pecho.","Ponte de pie en el centro de la máquina de cable con un pie ligeramente delante del otro.","Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados.","Mantén una ligera flexión en los codos y activa el core.","Tira de los cables juntos frente al pecho, cruzándolos uno sobre el otro.","Aprieta los músculos del pecho en el punto máximo del movimiento.","Suelta lentamente los cables de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1324","name":"cable upper row","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/1324-PQStVXH.jpg","gif_url":"videos/1324-PQStVXH.gif","instruction_steps":{"he":["חברו מוט ישר למכשיר כבלים בגובה החזה.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","שמרו על גב ישר וליבה מופעלת.","משכו את המוט לכיוון החזה העליון, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה.","שחררו באיטיות את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to a cable machine at chest height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the bar towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатному тренажеру на уровне груди.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмите перекладину хватом сверху, руки на расстоянии чуть шире плеч.","Держите спину прямо, а корпус напряженным.","Потяните штангу к верхней части груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения.","Медленно отпустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta una barra recta a una máquina de cable a la altura del pecho.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y el core activado.","Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta del movimiento.","Suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0246","name":"cable upright row","category":"shoulders","body_part":"shoulders","equipment":"cable","muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0246-cALKspW.jpg","gif_url":"videos/0246-cALKspW.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, ברכיים כפופות מעט, ואחזו באביזר הכבל באחיזה עליונה.","שמרו על גב ישר וליבה מופעלת לאורך כל התרגיל.","משכו את אביזר הכבל ישר למעלה לכיוון הסנטר, כשהמרפקים מובילים.","עצרו לרגע בנקודה העליונה, תוך כיווץ השכמות זו לזו.","הורידו את אביזר הכבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.","Keep your back straight and your core engaged throughout the exercise.","Pull the cable attachment straight up towards your chin, leading with your elbows.","Pause for a moment at the top, squeezing your shoulder blades together.","Slowly lower the cable attachment back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, слегка согните колени и возьмитесь за крепление троса хватом сверху.","На протяжении всего упражнения держите спину прямой и напряженным корпус.","Потяните блочное крепление прямо вверх к подбородку, ведя локтями.","В верхней точке задержитесь на мгновение, сведя лопатки вместе.","Медленно опустите крепление троса обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta el accesorio del cable con un agarre prono.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Tira del accesorio del cable directamente hacia arriba, hacia tu barbilla, guiando con los codos.","Haz una pausa breve en la parte alta, apretando los omóplatos entre sí.","Baja lentamente el accesorio del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1325","name":"cable wide grip rear pulldown behind neck","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/1325-CmEr4pM.jpg","gif_url":"videos/1325-CmEr4pM.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים כך שמוט הפולדאון בגובה מעל הראש.","שבו על המושב ואחזו במוט הפולדאון באחיזה עליונה רחבה.","שמרו על גב ישר וחזה מורם תוך הטיה קלה לאחור.","משכו את המוט מטה לכיוון החזה העליון, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, ואז שחררו באיטיות את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with a wide overhand grip.","Keep your back straight and your chest up as you lean back slightly.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте канатную машину так, чтобы тяговая перекладина находилась на высоте над вашей головой.","Сядьте на сиденье и возьмитесь за перекладину широким хватом сверху.","Держите спину прямо и грудь вверх, слегка отклоняясь назад.","Потяните штангу вниз к верхней части груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно отпустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de cable de modo que la barra de jalón quede a una altura por encima de tu cabeza.","Siéntate y agarra la barra de jalón con un agarre prono amplio.","Mantén la espalda recta y el pecho elevado mientras te reclinas ligeramente hacia atrás.","Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0247","name":"cable wrist curl","category":"lower arms","body_part":"lower arms","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0247-LrV4s90.jpg","gif_url":"videos/0247-LrV4s90.gif","instruction_steps":{"he":["חברו מוט ישר למכשיר כבלים בגלגלת תחתונה.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה תחתונה, כפות ידיים כלפי מעלה, וידיים ברוחב כתפיים.","השעינו את האמות על ספסל או כרית, כששורשי כף היד משתלשלים מעבר לקצה.","תוך שמירה על אמות ללא תזוזה, נשפו וגלגלו את שורשי כף היד כלפי מעלה עד הסוף.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your forearms on a bench or pad, with your wrists hanging off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите прямую штангу к канатной машине с низким шкивом.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмите перекладину хватом снизу, ладони вверх, руки на ширине плеч.","Положите предплечья на скамью или подушку так, чтобы запястья свисали с края.","Удерживая предплечья неподвижно, выдохните и согните запястья вверх как можно дальше.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca una barra recta en una máquina de cable con polea baja.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.","Apoya los antebrazos en un banco o almohadilla, con las muñecas colgando del borde.","Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.","Haz una pausa breve en la parte alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1407","name":"calf push stretch with hands against wall","category":"lower legs","body_part":"lower legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1407-PzNxakt.jpg","gif_url":"videos/1407-PzNxakt.gif","instruction_steps":{"he":["עמדו מול קיר עם רגליים ברוחב אגן.","הניחו את הידיים על הקיר בגובה הכתפיים.","צעדו לאחור עם רגל אחת, תוך שמירה על העקב על הרצפה והרגל ישרה.","כופפו את הברך הקדמית מעט ורכנו קדימה, עד תחושת מתיחה בתאומים.","החזיקו את המתיחה 20–30 שניות.","החליפו רגליים וחזרו על המתיחה."],"en":["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step back with one foot, keeping your heel on the ground and your leg straight.","Bend your front knee slightly and lean forward, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."],"ru":["Встаньте лицом к стене, поставив ноги на ширине плеч.","Положите руки на стену на уровне плеч.","Сделайте шаг назад одной ногой, удерживая пятку на земле, а ногу прямой.","Слегка согните переднее колено и наклонитесь вперед, чувствуя растяжение в икрах.","Удерживайте растяжку 20–30 секунд.","Поменяйте ноги и повторите растяжку."],"es":["Ponte de pie frente a una pared con los pies separados a la altura de las caderas.","Coloca las manos contra la pared a la altura de los hombros.","Da un paso atrás con un pie, manteniendo el talón en el suelo y la pierna recta.","Flexiona ligeramente la rodilla delantera e inclínate hacia adelante, sintiendo un estiramiento en la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Cambia de pierna y repite el estiramiento."]}},{"id":"1377","name":"calf stretch with hands against wall","category":"lower legs","body_part":"lower legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1377-m0tCHqc.jpg","gif_url":"videos/1377-m0tCHqc.gif","instruction_steps":{"he":["עמדו מול קיר עם רגליים ברוחב אגן.","הניחו את הידיים על הקיר בגובה הכתפיים.","צעדו לאחור עם רגל ימין, תוך שמירה על העקב על הרצפה והרגל ישרה.","כופפו את ברך שמאל ורכנו קדימה, תוך שמירה על הרגל האחורית ישרה והעקב על הרצפה.","החזיקו את המתיחה 20–30 שניות.","החליפו רגליים וחזרו על המתיחה."],"en":["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step your right foot back, keeping your heel on the ground and your leg straight.","Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."],"ru":["Встаньте лицом к стене, поставив ноги на ширине плеч.","Положите руки на стену на уровне плеч.","Сделайте шаг правой ногой назад, удерживая пятку на земле, а ногу прямо.","Согните левое колено и наклонитесь вперед, сохраняя заднюю ногу прямой, а пятку на земле.","Удерживайте растяжку 20–30 секунд.","Поменяйте ноги и повторите растяжку."],"es":["Ponte de pie frente a una pared con los pies separados a la altura de las caderas.","Coloca las manos contra la pared a la altura de los hombros.","Da un paso atrás con el pie derecho, manteniendo el talón en el suelo y la pierna recta.","Flexiona la rodilla izquierda e inclínate hacia adelante, manteniendo la pierna de atrás recta y el talón en el suelo.","Mantén el estiramiento durante 20-30 segundos.","Cambia de pierna y repite el estiramiento."]}},{"id":"1378","name":"calf stretch with rope","category":"lower legs","body_part":"lower legs","equipment":"rope","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1378-1LVFcEn.jpg","gif_url":"videos/1378-1LVFcEn.gif","instruction_steps":{"he":["עמדו מול קיר או חפץ יציב עם רגליים ברוחב אגן.","החזיקו את קצוות החבל בידיים ומקמו את אמצע החבל סביב כרית כף רגל ימין.","צעדו לאחור עם כף רגל שמאל, תוך שמירה על העקב על הרצפה והרגל ישרה.","רכנו קדימה, תוך שמירה על גב ישר, ומשכו בעדינות את החבל למתיחת התאומים.","החזיקו את המתיחה 20–30 שניות, ואז שחררו.","חזרו על התרגיל ברגל השנייה."],"en":["Stand facing a wall or sturdy object with your feet hip-width apart.","Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.","Step back with your left foot, keeping your heel on the ground and your leg straight.","Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf.","Hold the stretch for 20-30 seconds, then release.","Repeat on the other leg."],"ru":["Встаньте лицом к стене или прочному предмету, поставив ноги на ширине плеч.","Возьмите концы веревки в каждую руку и оберните середину веревки вокруг подушечки правой стопы.","Сделайте шаг назад левой ногой, удерживая пятку на земле, а ногу прямой.","Наклонитесь вперед, держа спину прямо, и осторожно потяните за веревку, чтобы растянуть икроножные мышцы.","Удерживайте растяжку 20–30 секунд, затем расслабьтесь.","Повторите на другой ноге."],"es":["Ponte de pie frente a una pared u objeto firme con los pies separados a la altura de las caderas.","Sujeta los extremos de la cuerda con cada mano y coloca el centro de la cuerda alrededor de la planta del pie derecho.","Da un paso atrás con el pie izquierdo, manteniendo el talón en el suelo y la pierna recta.","Inclínate hacia adelante, manteniendo la espalda recta, y tira suavemente de la cuerda para estirar la pantorrilla.","Mantén el estiramiento durante 20-30 segundos, luego suelta.","Repite con la otra pierna."]}},{"id":"0248","name":"cambered bar lying row","category":"back","body_part":"back","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0248-R5swFnc.jpg","gif_url":"videos/0248-R5swFnc.gif","instruction_steps":{"he":["הניחו מוט על הרצפה ושכבו על הבטן על ספסל, כשהחזה מעט מעבר לקצה.","התכופפו ואחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","עם רגליים ישרות וכפות רגליים על הרצפה, הרימו את המוט מהרצפה ביישור הידיים.","משכו את המוט לכיוון החזה, תוך כיווץ השכמות זו לזו.","הורידו את המוט חזרה לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.","Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.","With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."],"ru":["Поставьте штангу на пол и лягте лицом вниз на скамью так, чтобы грудь находилась рядом с краем.","Наклонитесь вниз и возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Поставив ноги прямо и поставив ступни на землю, поднимите штангу от пола, вытянув руки.","Подтяните штангу к груди, сведя лопатки вместе.","Опустите штангу обратно в исходное положение и повторите желаемое количество повторений."],"es":["Coloca una barra en el suelo y túmbate boca abajo en un banco con el pecho justo en el borde.","Estírate hacia abajo y agarra la barra con un agarre prono, un poco más ancho que el ancho de los hombros.","Con las piernas rectas y los pies en el suelo, levanta la barra del suelo extendiendo los brazos.","Tira de la barra hacia el pecho, juntando los omóplatos.","Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"2963","name":"captains chair straight leg raise","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/2963-weoDEpH.jpg","gif_url":"videos/2963-weoDEpH.gif","instruction_steps":{"he":["שבו על כיסא הקפטן עם הגב צמוד למשענת והאמות מונחות על כריות הידיים.","שמרו על פלג גוף עליון יציב וגב ישר.","הפעילו את שרירי הבטן והרימו את הרגליים לפניכם, כשהן ישרות.","המשיכו להרים עד שהרגליים מקבילות לרצפה או עד כמה שנוח לכם.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the captain's chair with your back against the backrest and your forearms resting on the arm pads.","Keep your upper body stable and your back straight.","Engage your abs and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на капитанское кресло, прислонившись спиной к спинке и положив предплечья на подлокотники.","Держите верхнюю часть тела устойчивой, а спину прямой.","Напрягите пресс и поднимите ноги перед собой, сохраняя их прямыми.","Продолжайте поднимать до тех пор, пока ваши ноги не станут параллельны земле или не станут настолько высоко, насколько вы сможете комфортно подняться.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en la silla romana con la espalda apoyada en el respaldo y los antebrazos apoyados en las almohadillas.","Mantén la parte superior del cuerpo estable y la espalda recta.","Activa el abdomen y levanta las piernas frente a ti, manteniéndolas rectas.","Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1548","name":"chair leg extended stretch","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","calves"],"target":"quads","image":"images/1548-xGgAGPm.jpg","gif_url":"videos/1548-xGgAGPm.gif","instruction_steps":{"he":["שבו על קצה כיסא עם גב ישר וכפות רגליים על הרצפה.","מתחו רגל אחת ישר לפניכם, כשהעקב על הרצפה.","רכנו מעט קדימה, עד תחושת מתיחה בארבע ראשי.","החזיקו את התנוחה 20–30 שניות.","החליפו רגליים וחזרו על המתיחה."],"en":["Sit on the edge of a chair with your back straight and feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your quadriceps.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch."],"ru":["Сядьте на край стула, выпрямите спину и поставьте ступни на землю.","Вытяните одну ногу прямо перед собой, удерживая пятку на земле.","Слегка наклонитесь вперед, чувствуя растяжение квадрицепсов.","Удерживайте это положение 20–30 секунд.","Поменяйте ноги и повторите растяжку."],"es":["Siéntate al borde de una silla con la espalda recta y los pies planos en el suelo.","Extiende una pierna recta frente a ti, manteniendo el talón en el suelo.","Inclínate ligeramente hacia adelante, sintiendo un estiramiento en los cuádriceps.","Mantén esta posición durante 20-30 segundos.","Cambia de pierna y repite el estiramiento."]}},{"id":"1271","name":"chest and front of shoulder stretch","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"deltoids","secondary_muscles":["deltoids"],"target":"pectorals","image":"images/1271-Uto7l43.jpg","gif_url":"videos/1271-Uto7l43.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים.","מתחו את הידיים ישר לפניכם בגובה הכתפיים.","הצליבו את הידיים מול הגוף, כשיד ימין מעל יד שמאל.","שלבו את האצבעות ולחצו את כפות הידיים זו לזו.","כווצו בעדינות את השכמות זו לזו ודחפו את הידיים קדימה, עד תחושת מתיחה בחזה ובקדמת הכתפיים.","החזיקו את המתיחה 20–30 שניות, ואז שחררו.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you at shoulder height.","Cross your arms in front of your body, with your right arm on top of your left arm.","Interlace your fingers and press your palms together.","Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.","Hold the stretch for 20-30 seconds, then release.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч.","Вытяните руки прямо перед собой на уровне плеч.","Скрестите руки перед телом, положив правую руку поверх левой.","Переплетите пальцы и сожмите ладони вместе.","Аккуратно сведите лопатки вместе и выдвиньте руки вперед, чувствуя растяжение в груди и передней части плеч.","Удерживайте растяжку 20–30 секунд, затем расслабьтесь.","Повторите необходимое количество повторений."],"es":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende los brazos rectos frente a ti a la altura de los hombros.","Cruza los brazos frente a tu cuerpo, con el brazo derecho sobre el brazo izquierdo.","Entrelaza los dedos y presiona las palmas entre sí.","Aprieta suavemente los omóplatos entre sí y empuja las manos hacia adelante, sintiendo un estiramiento en el pecho y la parte delantera de los hombros.","Mantén el estiramiento durante 20-30 segundos, luego suelta.","Repite el número de repeticiones deseado."]}},{"id":"0251","name":"chest dip","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0251-9WTm7dq.jpg","gif_url":"videos/0251-9WTm7dq.gif","instruction_steps":{"he":["התמקמו על המקבילים עם ידיים ישרות לגמרי וגוף ישר.","הורידו את הגוף בכיפוף מרפקים עד שהכתפיים מתחת למרפקים.","דחפו את עצמכם חזרה למעלה לנקודת ההתחלה על ידי יישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Position yourself on parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Встаньте на параллельные брусья, полностью вытянув руки и выпрямив тело.","Опускайте корпус, сгибая локти, пока плечи не окажутся ниже локтей.","Вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Colócate en las barras paralelas con los brazos completamente extendidos y el cuerpo recto.","Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos.","Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1430","name":"chest dip (on dip-pull-up cage)","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1430-XgWyAiA.jpg","gif_url":"videos/1430-XgWyAiA.gif","instruction_steps":{"he":["כווננו את מוטות הדיפים לגובה שמאפשר לאחוז בהם בנוחות.","עמדו בין המוטות והניחו יד על כל מוט, מעט רחב מרוחב הכתפיים.","קפצו למעלה ויישרו את הידיים, בתמיכת משקל הגוף על המוטות.","כופפו ברכיים והצליבו את הקרסוליים מאחוריכם.","הורידו את הגוף בכיפוף מרפקים, תוך שמירה על חזה מורם וכתפיים מטה.","המשיכו לרדת עד שהכתפיים מתחת למרפקים או עד תחושת מתיחה בחזה.","דחפו דרך כפות הידיים ויישרו מרפקים להרמת הגוף חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the dip bars to a height that allows you to comfortably grip them.","Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.","Jump up and straighten your arms, supporting your body weight on the bars.","Bend your knees and cross your ankles behind you.","Lower your body by bending your elbows, keeping your chest up and your shoulders down.","Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.","Push through your palms and extend your elbows to raise your body back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте поручни на такую ​​высоту, чтобы вам было удобно их держать.","Встаньте между перекладинами и положите руки на каждую перекладину на расстоянии чуть шире ширины плеч.","Подпрыгните и выпрямите руки, удерживая вес тела на перекладинах.","Согните колени и скрестите лодыжки позади себя.","Опустите тело, согнув локти, удерживая грудь вверху, а плечи опущенными.","Продолжайте опускаться до тех пор, пока ваши плечи не окажутся ниже локтей или пока вы не почувствуете растяжение в груди.","Оттолкнитесь ладонями и выпрямите локти, чтобы поднять тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta las barras de fondos a una altura que te permita agarrarlas cómodamente.","Ponte de pie entre las barras y coloca las manos en cada barra, un poco más separadas que el ancho de los hombros.","Salta y estira los brazos, sosteniendo el peso de tu cuerpo sobre las barras.","Flexiona las rodillas y cruza los tobillos detrás de ti.","Baja el cuerpo flexionando los codos, manteniendo el pecho elevado y los hombros bajos.","Continúa bajando hasta que los hombros queden por debajo de los codos o hasta que sientas un estiramiento en el pecho.","Empuja con las palmas y extiende los codos para subir el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2462","name":"chest dip on straight bar","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/2462-LQFOrMn.jpg","gif_url":"videos/2462-LQFOrMn.gif","instruction_steps":{"he":["אחזו במקבילים עם כפות ידיים כלפי מטה וידיים ישרות לגמרי.","כופפו ברכיים והצליבו את הקרסוליים.","הורידו את הגוף בכיפוף ידיים עד שהכתפיים מתחת למרפקים.","דחפו את עצמכם חזרה למעלה לנקודת ההתחלה על ידי יישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Grab the parallel bars with your palms facing down and your arms fully extended.","Bend your knees and cross your ankles.","Lower your body by bending your arms until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Возьмитесь за параллельные брусья ладонями вниз и полностью выпрямите руки.","Согните колени и скрестите лодыжки.","Опускайте тело, сгибая руки, пока плечи не окажутся ниже локтей.","Вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Agarra las barras paralelas con las palmas hacia abajo y los brazos completamente extendidos.","Flexiona las rodillas y cruza los tobillos.","Baja el cuerpo flexionando los brazos hasta que los hombros queden por debajo de los codos.","Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1272","name":"chest stretch with exercise ball","category":"chest","body_part":"chest","equipment":"stability ball","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1272-ykA5tU7.jpg","gif_url":"videos/1272-ykA5tU7.gif","instruction_steps":{"he":["שבו על כדור הפיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו את כדור הפיזיו בשתי ידיים ומתחו את הידיים ישר לפניכם.","קרבו באיטיות את כדור הפיזיו לכיוון החזה, עד תחושת מתיחה בשרירי החזה.","החזיקו את המתיחה כמה שניות, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the exercise ball with both hands and extend your arms straight out in front of you.","Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч, поставив ноги на землю и выпрямив спину.","Возьмите мяч для упражнений обеими руками и вытяните руки прямо перед собой.","Медленно поднесите мяч к груди, чувствуя растяжение мышц груди.","Удерживайте растяжку несколько секунд, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta.","Sujeta el balón de ejercicio con ambas manos y extiende los brazos rectos frente a ti.","Lleva lentamente el balón de ejercicio hacia tu pecho, sintiendo un estiramiento en los músculos del pecho.","Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3216","name":"chest tap push-up (male)","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/3216-7E06s6d.jpg","gif_url":"videos/3216-7E06s6d.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים מעט רחבות מרוחב הכתפיים והגוף בקו ישר.","הורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף.","תוך כדי הירידה, געו בחזה עם יד ימין.","דחפו את עצמכם חזרה למעלה לנקודת ההתחלה.","חזרו על התנועה, הפעם געו בחזה עם יד שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower yourself, tap your chest with your right hand.","Push yourself back up to the starting position.","Repeat the movement, this time tapping your chest with your left hand.","Continue alternating sides for the desired number of repetitions."],"ru":["Начните с положения высокой планки, расставив руки чуть шире плеч, а тело образуя прямую линию.","Опустите тело к земле, согнув локти и держа их близко к бокам.","Опускаясь, постучите правой рукой по груди.","Вернитесь в исходное положение.","Повторите движение, на этот раз постукивая левой рукой по груди.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Mientras te bajas, toca tu pecho con la mano derecha.","Empújate de vuelta hacia arriba hasta la posición inicial.","Repite el movimiento, esta vez tocando tu pecho con la mano izquierda.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1326","name":"chin-up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1326-T2mxWqc.jpg","gif_url":"videos/1326-T2mxWqc.gif","instruction_steps":{"he":["היתלו על מוט מתח עם כפות ידיים פונות אליכם וידיים ברוחב כתפיים.","הפעילו את הליבה ומשכו את הגוף למעלה לכיוון המוט, כשהחזה מוביל את התנועה.","המשיכו למשוך עד שהסנטר מעל המוט.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, повернув ладонями к себе и расставив руки на ширине плеч.","Напрягите корпус и подтяните тело к перекладине, ведя грудью.","Продолжайте тянуть, пока подбородок не окажется над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros.","Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0253","name":"chin-ups (narrow parallel grip)","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0253-G70mEAJ.jpg","gif_url":"videos/0253-G70mEAJ.gif","instruction_steps":{"he":["היתלו על מוט מתח באחיזה מקבילה צרה, כפות ידיים פונות זו לזו.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון המוט, תוך שמירה על מרפקים קרובים לגוף.","המשיכו למשוך עד שהסנטר מעל המוט.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине узким параллельным хватом, ладонями к себе.","Напрягите мышцы спины и подтяните тело к перекладине, держа локти близко к телу.","Продолжайте тянуть, пока подбородок не окажется над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con un agarre paralelo estrecho, con las palmas hacia ti.","Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0257","name":"circles knee stretch","category":"lower legs","body_part":"lower legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/0257-X7jbxra.jpg","gif_url":"videos/0257-X7jbxra.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וידיים על המותניים.","כופפו ברכיים מעט והרימו את העקבים מהרצפה, באיזון על כריות כפות הרגליים.","עם ברכיים כפופות, סובבו את הברכיים בתנועה מעגלית, קודם עם כיוון השעון ואז נגדו.","בצעו את התנועה למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your hands on your hips.","Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.","Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise.","Perform the movement for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, руки на бедрах.","Слегка согните колени и оторвите пятки от земли, балансируя на подушечках стоп.","Держа колени согнутыми, вращайте коленями круговые движения сначала по часовой стрелке, а затем против часовой стрелки.","Выполните движение необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas.","Flexiona ligeramente las rodillas y levanta los talones del suelo, equilibrándote sobre las puntas de los pies.","Manteniendo las rodillas flexionadas, gira las rodillas en un movimiento circular, primero en el sentido de las agujas del reloj y luego en sentido contrario.","Realiza el movimiento el número de repeticiones deseado."]}},{"id":"1273","name":"clap push up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1273-wigSg76.jpg","gif_url":"videos/1273-wigSg76.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים מעט רחבות מרוחב הכתפיים.","הורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה על ליבה מופעלת.","דחפו דרך כפות הידיים בפיצוץ כדי להעיף את הגוף מהרצפה.","באוויר, מחאו כפיים לפני הנחיתה חזרה בנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push through your palms explosively to propel your body off the ground.","While in mid-air, clap your hands together before landing back in the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, расставив руки чуть шире плеч.","Опустите тело к земле, сгибая локти, сохраняя при этом корпус напряженным.","Резко оттолкнитесь ладонями, чтобы оторвать тело от земли.","Находясь в воздухе, хлопните в ладоши, прежде чем приземлиться обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.","Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado.","Empuja con las palmas de forma explosiva para impulsar tu cuerpo fuera del suelo.","Mientras estás en el aire, junta las manos en un aplauso antes de aterrizar de vuelta en la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0258","name":"clock push-up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0258-CMAxnsG.jpg","gif_url":"videos/0258-CMAxnsG.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים ישר מתחת לכתפיים והגוף בקו ישר.","הורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף.","תוך כדי הירידה, סובבו את הגוף שמאלה, במתיחת יד שמאל ישר הצידה.","דחפו חזרה למעלה לנקודת ההתחלה, תוך סיבוב הגוף חזרה למרכז.","חזרו על שכיבת הסמיכה, הפעם בסיבוב הגוף ימינה ומתיחת יד ימין הצידה.","המשיכו להחליף צדדים בכל חזרה."],"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower, rotate your body to the left, extending your left arm straight out to the side.","Push back up to the starting position, while rotating your body to the center.","Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.","Continue alternating sides with each repetition."],"ru":["Начните с позиции высокой планки, положив руки прямо под плечи, а тело образуя прямую линию.","Опустите тело к земле, согнув локти и держа их близко к бокам.","Опускаясь, поверните тело влево, вытягивая левую руку прямо в сторону.","Вернитесь в исходное положение, одновременно поворачивая тело к центру.","Повторите отжимание, на этот раз повернув тело вправо и вытянув правую руку в сторону.","Продолжайте чередовать стороны с каждым повторением."],"es":["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Mientras bajas, gira el cuerpo hacia la izquierda, extendiendo el brazo izquierdo recto hacia el lado.","Empuja de vuelta hacia arriba hasta la posición inicial, mientras giras el cuerpo hacia el centro.","Repite la flexión de brazos, esta vez girando el cuerpo hacia la derecha y extendiendo el brazo derecho hacia el lado.","Continúa alternando lados en cada repetición."]}},{"id":"1327","name":"close grip chin-up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1327-VnfUNW7.jpg","gif_url":"videos/1327-VnfUNW7.gif","instruction_steps":{"he":["אחזו במוט המתח עם כפות ידיים פונות אליכם וידיים ברוחב כתפיים.","היתלו על המוט עם ידיים ישרות לגמרי וכפות רגליים באוויר.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון המוט, תוך שמירה על מרפקים קרובים לגוף.","המשיכו למשוך עד שהסנטר מעל המוט.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Возьмитесь за турник ладонями к себе и руками на ширине плеч.","Повисните на перекладине, полностью вытянув руки и оторвав ноги от земли.","Напрягите мышцы спины и подтяните тело к перекладине, держа локти близко к телу.","Продолжайте тянуть, пока подбородок не окажется над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Agarra la barra de dominadas con las palmas hacia ti y las manos separadas a la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo.","Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0259","name":"close-grip push-up","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0259-x6KpKpq.jpg","gif_url":"videos/0259-x6KpKpq.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים קרובות זו לזו, ישר מתחת לכתפיים.","הפעילו את הליבה והורידו את הגוף לכיוון הרצפה, תוך שמירה על מרפקים צמודים לצידי הגוף.","דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands placed close together, directly under your shoulders.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, положив руки близко друг к другу, прямо под плечами.","Напрягите корпус и опустите тело к земле, держа локти близко к бокам.","Оттолкнитесь ладонями, чтобы вытянуть руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de plancha alta con las manos juntas, directamente debajo de los hombros.","Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2398","name":"close-grip push-up (on knees)","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/2398-v3vLFW0.jpg","gif_url":"videos/2398-v3vLFW0.gif","instruction_steps":{"he":["התחילו על ארבע, עם ידיים ברוחב כתפיים וברכיים ברוחב אגן.","הורידו את פלג הגוף העליון לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף.","עצרו לרגע כשהחזה מעט מעל הרצפה.","דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.","Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.","Pause for a moment when your chest is just above the ground.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте на четвереньки, поставив руки на ширине плеч и колени на ширине бедер.","Опустите верхнюю часть тела к земле, сгибая локти и держа их близко к бокам.","Сделайте паузу на мгновение, когда ваша грудь окажется чуть выше земли.","Оттолкнитесь ладонями, чтобы выпрямить руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza apoyándote sobre las manos y las rodillas, con las manos separadas a la altura de los hombros y las rodillas separadas a la altura de las caderas.","Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Haz una pausa breve cuando tu pecho esté justo por encima del suelo.","Empuja con las palmas para estirar los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0260","name":"cocoons","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0260-SLKj2pX.jpg","gif_url":"videos/0260-SLKj2pX.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1468","name":"crab twist toe touch","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/1468-xgsGFVM.jpg","gif_url":"videos/1468-xgsGFVM.gif","instruction_steps":{"he":["התחילו בישיבה על הרצפה עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחוריכם, אצבעות פונות לכיוון כפות הרגליים, והרימו את האגן מהרצפה.","מתחו רגל אחת ישר לפניכם ובו-זמנית הושיטו את היד הנגדית לכיוון קצות האצבעות של הרגל.","חזרו לנקודת ההתחלה וחזרו על התנועה בצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Start by sitting on the ground with your knees bent and feet flat on the floor.","Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.","Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Начните с того, что сядьте на землю, согнув колени и поставив ступни на пол.","Положите руки позади себя, пальцы направлены к ногам, и поднимите бедра от земли.","Вытяните одну ногу прямо перед собой, одновременно протягивая противоположную руку к пальцам ног.","Вернитесь в исходное положение и повторите то же самое в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Comienza sentado en el suelo con las rodillas flexionadas y los pies planos en el suelo.","Coloca las manos detrás de ti, con los dedos apuntando hacia los pies, y levanta las caderas del suelo.","Extiende una pierna recta frente a ti mientras al mismo tiempo llevas la mano contraria hacia los dedos del pie.","Regresa a la posición inicial y repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0262","name":"cross body crunch","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0262-rbu5UUb.jpg","gif_url":"videos/0262-rbu5UUb.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו את פלג הגוף העליון מהרצפה וסובבו כדי להביא את מרפק ימין לכיוון ברך שמאל.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התנועה בצד השני, בהבאת מרפק שמאל לכיוון ברך ימין.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat on the other side, bringing your left elbow towards your right knee.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, поднимите верхнюю часть тела от земли и повернитесь, чтобы поднести правый локоть к левому колену.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите то же самое с другой стороны, поднеся левый локоть к правому колену.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta la parte superior del cuerpo del suelo y gira para llevar el codo derecho hacia la rodilla izquierda.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite en el otro lado, llevando el codo izquierdo hacia la rodilla derecha.","Repite el número de repeticiones deseado."]}},{"id":"0267","name":"crunch (hands overhead)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0267-kjJ3VoQ.jpg","gif_url":"videos/0267-kjJ3VoQ.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","מתחו את הידיים ישר מעל הראש.","תוך הפעלת שרירי הבטן, הרימו את פלג הגוף העליון מהרצפה, בגלגול קדימה לכיוון הברכיים.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight above your head.","Engaging your abs, lift your upper body off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Вытяните руки прямо над головой.","Включив пресс, поднимите верхнюю часть тела от земли, наклонившись вперед к коленям.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende los brazos rectos por encima de la cabeza.","Activando el abdomen, levanta la parte superior del cuerpo del suelo, flexionándote hacia adelante en dirección a las rodillas.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0271","name":"crunch (on stability ball)","category":"waist","body_part":"waist","equipment":"stability ball","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0271-MCUhf1F.jpg","gif_url":"videos/0271-MCUhf1F.gif","instruction_steps":{"he":["שבו על כדור הפיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","שכבו לאחור על הכדור עד שהגב התחתון נתמך ופלג הגוף העליון מקביל לרצפה.","מקמו את הידיים מאחורי הראש או מוצלבות על החזה.","הפעילו את שרירי הבטן והרימו את פלג הגוף העליון לכיוון הברכיים, בגלגול הגו קדימה.","עצרו לרגע בנקודה העליונה של התנועה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso forward.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч для стабилизации, поставьте ступни на землю и согните колени под углом 90 градусов.","Лягте на мяч так, чтобы нижняя часть спины получила поддержку, а верхняя часть тела оказалась параллельна полу.","Положите руки за голову или на грудь.","Напрягите пресс и поднимите верхнюю часть тела к коленям, наклоняя туловище вперед.","Сделайте паузу на мгновение в верхней точке движения, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Reclínate sobre el balón hasta que la zona lumbar esté apoyada y la parte superior del cuerpo quede paralela al suelo.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso hacia adelante.","Haz una pausa breve en la parte alta del movimiento, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0272","name":"crunch (on stability ball, arms straight)","category":"waist","body_part":"waist","equipment":"stability ball","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0272-Sn8wxAI.jpg","gif_url":"videos/0272-Sn8wxAI.gif","instruction_steps":{"he":["שבו על כדור הפיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","שכבו לאחור על הכדור עד שהגב התחתון נתמך ופלג הגוף העליון מקביל לרצפה.","מקמו את הידיים מאחורי הראש או הצליבו אותן על החזה.","הפעילו את שרירי הבטן והרימו את פלג הגוף העליון מהכדור, בגלגול הכתפיים לכיוון האגן.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч для стабилизации, поставьте ступни на землю и согните колени под углом 90 градусов.","Лягте на мяч так, чтобы нижняя часть спины получила поддержку, а верхняя часть тела оказалась параллельна полу.","Заведите руки за голову или скрестите их на груди.","Напрягите пресс и поднимите верхнюю часть тела от мяча, подтягивая плечи к бедрам.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Reclínate sobre el balón hasta que la zona lumbar esté apoyada y la parte superior del cuerpo quede paralela al suelo.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el abdomen y levanta la parte superior del cuerpo del balón, flexionando los hombros hacia las caderas.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0274","name":"crunch floor","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0274-TFqbd8t.jpg","gif_url":"videos/0274-TFqbd8t.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","הפעילו את שרירי הבטן והרימו את הכתפיים מהרצפה, בגלגול קדימה לכיוון הברכיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הכתפיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your shoulders off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Напрягите пресс и поднимите плечи от земли, наклонившись вперед к коленям.","Задержитесь на мгновение в верхней точке, затем медленно опустите плечи обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activa el abdomen y levanta los hombros del suelo, flexionándote hacia adelante en dirección a las rodillas.","Haz una pausa breve en la parte alta, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3016","name":"curl-up","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3016-g2oKspu.jpg","gif_url":"videos/3016-g2oKspu.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3769","name":"curtsey squat","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3769-gUjqdei.jpg","gif_url":"videos/3769-gUjqdei.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","צעדו באלכסון לאחור ועל פני הגוף עם כף רגל ימין, בהצלבתה מאחורי רגל שמאל.","כופפו את שתי הברכיים כמו בקידה, בהורדת הגוף לכיוון הרצפה.","שמרו על גו זקוף והמשקל על כף הרגל הקדמית.","דחפו דרך כף הרגל הקדמית לחזרה לנקודת ההתחלה.","חזרו על התנועה בצד השני, בצעד אלכסוני לאחור ועל פני הגוף עם כף רגל שמאל."],"en":["Stand with your feet shoulder-width apart.","Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.","Bend both knees as if you were curtsying, lowering your body towards the ground.","Keep your torso upright and your weight on your front foot.","Push through your front foot to return to the starting position.","Repeat on the other side, stepping diagonally behind and across your body with your left foot."],"ru":["Встаньте, ноги на ширине плеч.","Сделайте шаг по диагонали позади и поперек тела правой ногой, скрестив ее за левой ногой.","Согните оба колена, как будто вы делаете реверанс, опуская тело к земле.","Держите туловище в вертикальном положении, а вес тела перенесите на переднюю ногу.","Оттолкнитесь передней ногой, чтобы вернуться в исходное положение.","Повторите то же самое с другой стороны, шагая левой ногой по диагонали позади и поперек тела."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso en diagonal hacia atrás y a través de tu cuerpo con el pie derecho, cruzándolo detrás de la pierna izquierda.","Flexiona ambas rodillas como si hicieras una reverencia, bajando el cuerpo hacia el suelo.","Mantén el torso erguido y el peso sobre el pie delantero.","Empuja con el pie delantero para regresar a la posición inicial.","Repite en el otro lado, dando un paso en diagonal hacia atrás y a través de tu cuerpo con el pie izquierdo."]}},{"id":"2331","name":"cycle cross trainer","category":"cardio","body_part":"cardio","equipment":"leverage machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes"],"target":"cardiovascular system","image":"images/2331-XSCHmiI.jpg","gif_url":"videos/2331-XSCHmiI.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על אופני הקרוס-טריינר.","הניחו את כפות הרגליים על הדוושות ואחזו בכידון.","התחילו לדווש בתנועה חלקה ומבוקרת.","שמרו על קצב אחיד והגבירו את ההתנגדות לפי הצורך.","המשיכו לדווש למשך הזמן הרצוי של אימון האירובי."],"en":["Adjust the seat height and position yourself on the cycle cross trainer.","Place your feet on the pedals and grip the handlebars.","Start pedaling in a smooth and controlled motion.","Maintain a steady pace and increase the resistance if desired.","Continue pedaling for the desired duration of your cardio workout."],"ru":["Отрегулируйте высоту сиденья и расположитесь на велотренажере.","Поставьте ноги на педали и возьмитесь за руль.","Начните крутить педали плавными и контролируемыми движениями.","Поддерживайте устойчивый темп и при желании увеличивайте сопротивление.","Продолжайте крутить педали в течение желаемой продолжительности кардио-тренировки."],"es":["Ajusta la altura del asiento y colócate en la bicicleta elíptica.","Coloca los pies en los pedales y sujeta el manillar.","Comienza a pedalear con un movimiento suave y controlado.","Mantén un ritmo constante y aumenta la resistencia si lo deseas.","Continúa pedaleando durante la duración deseada de tu entrenamiento cardiovascular."]}},{"id":"0276","name":"dead bug","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0276-iny3m5y.jpg","gif_url":"videos/0276-iny3m5y.gif","instruction_steps":{"he":["שכבו על הגב עם ידיים מתוחות לכיוון התקרה.","כופפו ברכיים והרימו את הרגליים מהרצפה, ביצירת זווית של 90 מעלות בירכיים ובברכיים.","הפעילו את הליבה והגב התחתון ללחיצת הגב התחתון לרצפה.","הורידו באיטיות את יד ימין ורגל שמאל לכיוון הרצפה, כשהן ישרות ומרחפות מעט מעל הרצפה.","עצרו לרגע, ואז חזרו לנקודת ההתחלה.","חזרו על התנועה עם יד שמאל ורגל ימין.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Lie flat on your back with your arms extended towards the ceiling.","Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.","Engage your core and lower back to press your lower back into the ground.","Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.","Pause for a moment, then return to the starting position.","Repeat the movement with your left arm and right leg.","Continue alternating sides for the desired number of repetitions."],"ru":["Лягте на спину, вытянув руки к потолку.","Согните колени и оторвите ноги от земли, создавая угол в 90 градусов в бедрах и коленях.","Напрягите корпус и поясницу, чтобы прижать поясницу к земле.","Медленно опустите правую руку и левую ногу к земле, сохраняя их прямыми и зависая над полом.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите движение левой рукой и правой ногой.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Túmbate boca arriba con los brazos extendidos hacia el techo.","Flexiona las rodillas y levanta las piernas del suelo, formando un ángulo de 90 grados en las caderas y las rodillas.","Activa el core y la zona lumbar para presionar la zona lumbar contra el suelo.","Baja lentamente el brazo derecho y la pierna izquierda hacia el suelo, manteniéndolos rectos y justo por encima del suelo.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite el movimiento con el brazo izquierdo y la pierna derecha.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0277","name":"decline crunch","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0277-9Ap7miY.jpg","gif_url":"videos/0277-9Ap7miY.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשכפות הרגליים מקובעות והברכיים כפופות בזווית של 90 מעלות.","מקמו את הידיים מאחורי הראש או מוצלבות על החזה.","הפעילו את שרירי הבטן והרימו את פלג הגוף העליון לכיוון הברכיים, בגלגול הגו.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, зафиксируйте ноги и согните колени под углом 90 градусов.","Положите руки за голову или на грудь.","Напрягите пресс и поднимите верхнюю часть тела к коленям, сгибая туловище.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas en un ángulo de 90 grados.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0279","name":"decline push-up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0279-i5cEhka.jpg","gif_url":"videos/0279-i5cEhka.gif","instruction_steps":{"he":["הניחו את הידיים על הרצפה מעט רחב מרוחב הכתפיים, כשכפות הרגליים מוגבהות על משטח יציב.","שמרו על הגוף בקו ישר מהראש ועד כפות הרגליים, תוך הפעלת שרירי הליבה.","הורידו את החזה לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם קרובים לגוף.","דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface.","Keep your body in a straight line from head to toe, engaging your core muscles.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Поставьте руки на землю чуть шире ширины плеч, приподняв ноги на устойчивой поверхности.","Держите тело прямой линией от головы до пят, задействуя мышцы корпуса.","Опустите грудь к земле, согнув локти и удерживая их близко к телу.","Оттолкнитесь ладонями, чтобы вытянуть руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca las manos en el suelo un poco más separadas que el ancho de los hombros, con los pies elevados sobre una superficie estable.","Mantén el cuerpo en línea recta de la cabeza a los pies, activando los músculos del core.","Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0282","name":"decline sit-up","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0282-QLL2gdc.jpg","gif_url":"videos/0282-QLL2gdc.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשכפות הרגליים מקובעות והברכיים כפופות.","מקמו את הידיים מאחורי הראש או מוצלבות על החזה.","הפעילו את שרירי הבטן והרימו את פלג הגוף העליון מהספסל, בגלגול קדימה לכיוון הברכיים.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on a decline bench with your feet secured and your knees bent.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, зафиксировав ноги и согнув колени.","Положите руки за голову или на грудь.","Напрягите пресс и поднимите верхнюю часть тела со скамьи, наклонившись вперед к коленям.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el abdomen y levanta la parte superior del cuerpo del banco, flexionándote hacia adelante en dirección a las rodillas.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1274","name":"deep push up","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1274-vptOQ4N.jpg","gif_url":"videos/1274-vptOQ4N.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים מעט רחבות מרוחב הכתפיים והגוף בקו ישר.","הורידו את החזה לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם קרובים לגוף.","דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с положения высокой планки, расставив руки чуть шире плеч, а тело образуя прямую линию.","Опустите грудь к земле, согнув локти и удерживая их близко к телу.","Оттолкнитесь ладонями, чтобы вытянуть руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta.","Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0283","name":"diamond push-up","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0283-soIB2rj.jpg","gif_url":"videos/0283-soIB2rj.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים קרובות זו לזו, ביצירת צורת יהלום עם האגודלים והאצבעות המורות.","שמרו על הגוף בקו ישר מהראש ועד כפות הרגליים, תוך הפעלת הליבה והישבן.","הורידו את החזה לכיוון צורת היהלום שיוצרות הידיים, תוך שמירה על מרפקים קרובים לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.","Keep your body in a straight line from head to toe, engaging your core and glutes.","Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с положения высокой планки, сложив руки вместе, образуя ромбовидную форму большими и указательными пальцами.","Держите тело прямой линией от головы до пят, задействуя корпус и ягодицы.","Опустите грудь в сторону ромбовидной формы, образованной руками, держа локти близко к телу.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de plancha alta con las manos juntas, formando una figura de diamante con los pulgares y los índices.","Mantén el cuerpo en línea recta de la cabeza a los pies, activando el core y los glúteos.","Baja el pecho hacia la figura de diamante formada por tus manos, manteniendo los codos cerca del cuerpo.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0284","name":"donkey calf raise","category":"lower legs","body_part":"lower legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/0284-u5ESqzH.jpg","gif_url":"videos/0284-u5ESqzH.gif","instruction_steps":{"he":["עמדו עם קצות האצבעות של הרגליים על משטח מוגבה, כמו מדרגה או קופסה.","הניחו את הידיים על משטח יציב, כמו קיר או מעקה, לשיווי משקל.","הרימו את העקבים גבוה ככל האפשר, בהעברת משקל הגוף לכריות כפות הרגליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your toes on an elevated surface, such as a step or block.","Place your hands on a stable support, such as a wall or railing, for balance.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте пальцами ног на возвышенную поверхность, например на ступеньку или блок.","Для равновесия положите руки на устойчивую опору, например стену или перила.","Поднимите пятки как можно выше, перенеся вес тела на подушечки стоп.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con las puntas de los pies sobre una superficie elevada, como un escalón o un bloque.","Coloca las manos en un soporte estable, como una pared o un pasamanos, para mantener el equilibrio.","Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1275","name":"drop push up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1275-Q497lAE.jpg","gif_url":"videos/1275-Q497lAE.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים מעט רחבות מרוחב הכתפיים.","הורידו את החזה לכיוון הרצפה, תוך שמירה על מרפקים קרובים לגוף.","כשהחזה מעט מעל הרצפה, הורידו במהירות את הברכיים לרצפה.","דחפו את עצמכם חזרה למעלה לנקודת ההתחלה על ידי יישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, quickly drop your knees to the ground.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, расставив руки чуть шире плеч.","Опустите грудь к земле, держа локти близко к телу.","Как только ваша грудь окажется чуть выше земли, быстро опустите колени на землю.","Вернитесь в исходное положение, вытянув руки.","Повторите необходимое количество повторений."],"es":["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.","Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.","Una vez que tu pecho esté justo por encima del suelo, baja rápidamente las rodillas al suelo.","Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0285","name":"dumbbell alternate biceps curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0285-BU15nH4.jpg","gif_url":"videos/0285-BU15nH4.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות קדימה וידיים ישרות.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, לסירוגין בין הידיים."],"en":["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."],"ru":["Встаньте прямо, взяв в каждую руку по гантели, ладони направлены вперед, руки полностью выпрямлены.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите желаемое количество повторений, чередуя руки."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado, alternando los brazos."]}},{"id":"2403","name":"dumbbell alternate biceps curl (with arm blaster)","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2403-CfKsRbG.jpg","gif_url":"videos/2403-CfKsRbG.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד, כפות ידיים פונות קדימה.","הניחו את הארם-בלאסטר על הזרועות העליונות, וודאו התאמה יציבה.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו משקולת אחת למעלה לכיוון הכתף תוך כיווץ הבייספס.","המשיכו להרים את המשקולת עד שהבייספס מכווץ במלואו והמשקולת בגובה הכתף.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה עם היד הנגדית.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place the arm blaster on your upper arms, ensuring a secure fit.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями вперед.","Поместите армбластер на плечи, обеспечив надежную фиксацию.","Удерживая плечи неподвижно, выдохните и поднимите одну гантель к плечу, одновременно напрягая бицепсы.","Продолжайте поднимать гантель до тех пор, пока ваши бицепсы полностью не сократятся и гантель не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно опустите гантель обратно в исходное положение.","Повторите движение противоположной рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.","Coloca el soporte para brazos en la parte superior de tus brazos, asegurándote de que quede bien ajustado.","Manteniendo los brazos superiores quietos, exhala y flexiona una mancuerna hacia el hombro mientras contraes el bíceps.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el movimiento con el brazo contrario.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"1646","name":"dumbbell alternate hammer preacher curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1646-fy7Tgy4.jpg","gif_url":"videos/1646-fy7Tgy4.gif","instruction_steps":{"he":["שבו על ספסל פריצ'ר עם משקולת יד בכל יד, כפות ידיים פונות לגו וידיים ישרות לגמרי.","שמרו על הזרועות העליונות ללא תזוזה ונשפו תוך כיפוף המשקולות בכיווץ הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות המומלץ."],"en":["Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"ru":["Сядьте на скамью для проповедника, взяв в каждую руку по гантели, ладони обращены к туловищу, руки полностью выпрямлены.","Держите плечи неподвижно и выдыхайте, сгибая штангу и одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите рекомендованное количество повторений."],"es":["Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos completamente extendidos.","Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones recomendado."]}},{"id":"1647","name":"dumbbell alternate preacher curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1647-NlfIbzq.jpg","gif_url":"videos/1647-NlfIbzq.gif","instruction_steps":{"he":["שבו על ספסל פריצ'ר עם משקולת יד בכל יד, כפות ידיים כלפי מעלה.","השעינו את הזרועות העליונות על כרית ספסל הפריצ'ר, ותנו לידיים להתיישר לגמרי.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המשקולת ביד ימין תוך כיווץ הבייספס.","המשיכו לכופף את המשקולת עד שהבייספס מכווץ במלואו והמשקולת בגובה הכתף.","עצרו לרגע, ואז שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה עם יד שמאל.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Sit on a preacher bench with a dumbbell in each hand, palms facing up.","Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend.","Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps.","Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Сядьте на скамью для проповедника, взяв в каждую руку по гантели ладонями вверх.","Положите плечи на подушку скамьи проповедника, позволяя им полностью выпрямиться.","Удерживая плечи неподвижно, выдохните и согните гантель в правой руке, одновременно сокращая бицепсы.","Продолжайте сгибать гантель до тех пор, пока ваши бицепсы полностью не сократятся и гантель не окажется на уровне плеч.","Сделайте паузу на мгновение, затем вдохните и медленно опустите гантель обратно в исходное положение.","Повторите движение левой рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba.","Apoya la parte superior de los brazos en la almohadilla del banco scott, permitiendo que los brazos se extiendan completamente.","Manteniendo los brazos superiores quietos, exhala y flexiona la mancuerna en tu mano derecha mientras contraes el bíceps.","Continúa flexionando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el movimiento con el brazo izquierdo.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"1648","name":"dumbbell alternate seated hammer curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1648-6em2Dxj.jpg","gif_url":"videos/1648-6em2Dxj.gif","instruction_steps":{"he":["שבו על ספסל עם משקולת יד בכל יד, כפות ידיים פונות לגו וידיים מתוחות מטה.","שמרו על גב ישר ומרפקים צמודים לגו.","נשפו וכופפו את המשקולת ביד ימין לכיוון הכתף, תוך שמירה על הזרוע העליונה ללא תזוזה.","המשיכו להרים את המשקולת עד שהבייספס מכווץ במלואו והמשקולת בגובה הכתף.","עצרו לרגע קצר, ואז שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה עם יד שמאל.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Сядьте на скамью, взяв в каждую руку по гантели, ладони обращены к туловищу, руки вытянуты вниз.","Держите спину прямо, а локти близко к туловищу.","Выдохните и согните гантель в правой руке к плечу, сохраняя плечо неподвижным.","Продолжайте поднимать гантель до тех пор, пока ваши бицепсы полностью не сократятся и гантель не окажется на уровне плеч.","Сделайте короткую паузу, затем вдохните и медленно опустите гантель обратно в исходное положение.","Повторите движение левой рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos hacia abajo.","Mantén la espalda recta y los codos cerca del torso.","Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el movimiento con el brazo izquierdo.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"0286","name":"dumbbell alternate side press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0286-izMnLqz.jpg","gif_url":"videos/0286-izMnLqz.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במשקולת יד בכל יד בגובה הכתפיים.","לחצו משקולת אחת מעל הראש, תוך שמירה על המשקולת השנייה בגובה הכתף.","הורידו את המשקולת שנלחצה חזרה לגובה הכתף, ובו-זמנית לחצו את המשקולת השנייה מעל הראש.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height.","Press one dumbbell overhead while keeping the other dumbbell at shoulder height.","Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гантели на уровне плеч.","Выжмите одну гантель над головой, удерживая другую на уровне плеч.","Опустите отжатую гантель обратно на высоту плеч, одновременно выжимая другую гантель над головой.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros.","Empuja una mancuerna por encima de la cabeza mientras mantienes la otra mancuerna a la altura del hombro.","Baja la mancuerna empujada de vuelta a la altura del hombro mientras empujas la otra mancuerna por encima de la cabeza.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1649","name":"dumbbell alternating bicep curl with leg raised on exercise ball","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1649-Zwiw7XR.jpg","gif_url":"videos/1649-Zwiw7XR.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד, כפות ידיים פונות קדימה.","הניחו כדור פיזיו מאחוריכם ומקמו כף רגל אחת עליו, תוך שמירה על שיווי משקל.","עם ידיים ישרות לגמרי ומרפקים צמודים לצידי הגוף, כופפו משקולת אחת לכיוון הכתף תוך שמירה על הזרוע העליונה ללא תזוזה.","הורידו את המשקולת חזרה לנקודת ההתחלה וחזרו על התנועה עם היד השנייה.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place an exercise ball behind you and position one foot on top of it, keeping your balance.","With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary.","Lower the dumbbell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями вперед.","Положите позади себя гимнастический мяч и поставьте на него одну ногу, сохраняя равновесие.","Полностью выпрямив руки и прижав локти к бокам, согните одну гантель к плечу, сохраняя плечо неподвижным.","Опустите гантель обратно в исходное положение и повторите то же самое с другой рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.","Coloca un balón de ejercicio detrás de ti y apoya un pie sobre él, manteniendo el equilibrio.","Con los brazos completamente extendidos y los codos cerca de los costados, flexiona una mancuerna hacia el hombro mientras mantienes el brazo superior quieto.","Baja la mancuerna de vuelta a la posición inicial y repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"1650","name":"dumbbell alternating seated bicep curl on exercise ball","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1650-J74XlNf.jpg","gif_url":"videos/1650-J74XlNf.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד בכל יד, כפות ידיים פונות קדימה וידיים ישרות לגמרי.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו משקולת אחת תוך סיבוב האמה עד שכף היד פונה לכתף.","שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על הכפיפה עם היד השנייה.","המשיכו בכפיפות לסירוגין למספר החזרות הרצוי."],"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with the other arm.","Continue alternating curls for the desired number of repetitions."],"ru":["Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину.","Возьмите в каждую руку по гантели ладонями вперед и полностью выпрямленными руками.","Удерживая плечи неподвижно, выдохните и согните одну гантель, одновременно вращая предплечье, пока ладонь не окажется лицом к плечу.","Вдохните и медленно опустите гантель обратно в исходное положение.","Повторите сгибание другой рукой.","Продолжайте чередовать сгибания рук желаемое количество повторений."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores quietos, exhala y flexiona una mancuerna mientras rotas el antebrazo hasta que la palma quede frente al hombro.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite la flexión con el otro brazo.","Continúa alternando flexiones el número de repeticiones deseado."]}},{"id":"2137","name":"dumbbell arnold press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","upper chest"],"target":"delts","image":"images/2137-Xy4jlWA.jpg","gif_url":"videos/2137-Xy4jlWA.gif","instruction_steps":{"he":["שבו על ספסל עם משענת גב והחזיקו משקולת יד בכל יד בגובה הכתפיים, כפות ידיים פונות לגוף ומרפקים כפופים.","לחצו את המשקולות כלפי מעלה עד יישור מלא של הידיים וכפות הידיים פונות קדימה.","סובבו את שורשי כף היד תוך כדי ההרמה, כך שכפות הידיים פונות קדימה בנקודה העליונה של התנועה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью с поддержкой спины и держите по гантели в каждой руке на уровне плеч, ладони обращены к телу, локти согнуты.","Выжимайте гантели вверх до тех пор, пока руки полностью не выпрямятся и ладони не повернутся вперед.","Во время подъема вращайте запястья так, чтобы ладони были направлены вперед в верхней точке движения.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con respaldo y sujeta una mancuerna en cada mano a la altura del hombro, con las palmas hacia tu cuerpo y los codos flexionados.","Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos y las palmas miren hacia adelante.","Rota las muñecas mientras levantas, de modo que las palmas miren hacia adelante en la parte alta del movimiento.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0287","name":"dumbbell arnold press v. 2","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","upper chest"],"target":"delts","image":"images/0287-eOrFCnx.jpg","gif_url":"videos/0287-eOrFCnx.gif","instruction_steps":{"he":["שבו על ספסל עם משענת גב והחזיקו משקולת יד בכל יד בגובה הכתפיים, כפות ידיים פונות לגוף ומרפקים כפופים.","לחצו את המשקולות כלפי מעלה עד יישור מלא של הידיים וכפות הידיים פונות קדימה.","סובבו את שורשי כף היד תוך כדי ההרמה, כך שכפות הידיים יפנו קדימה בנקודה העליונה של התנועה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью с поддержкой спины и держите по гантели в каждой руке на уровне плеч, ладони обращены к телу, локти согнуты.","Выжимайте гантели вверх до тех пор, пока руки полностью не выпрямятся и ладони не повернутся вперед.","Во время подъема вращайте запястья так, чтобы в верхней точке движения ладони были обращены вперед.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con respaldo y sujeta una mancuerna en cada mano a la altura del hombro, con las palmas hacia tu cuerpo y los codos flexionados.","Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos y las palmas miren hacia adelante.","Rota las muñecas mientras levantas, de modo que las palmas terminen mirando hacia adelante en la parte alta del movimiento.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0288","name":"dumbbell around pullover","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","latissimus dorsi"],"target":"pectorals","image":"images/0288-vi8EhoE.jpg","gif_url":"videos/0288-vi8EhoE.gif","instruction_steps":{"he":["שכבו על ספסל כשהראש בקצה אחד וכפות הרגליים נטועות היטב על הרצפה.","החזיקו משקולת יד בשתי הידיים ומתחו את הידיים ישר מעל החזה.","תוך שמירה על ידיים ישרות, הורידו באיטיות את המשקולת מאחורי הראש בתנועת קשת.","עצרו לרגע בנקודה התחתונה, ואז הרימו את המשקולת חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your head at one end and your feet firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion.","Pause for a moment at the bottom, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив голову на один конец и твердо поставив ноги на землю.","Возьмите гантель обеими руками и вытяните руки прямо над грудью.","Держа руки прямыми, медленно опустите гантель за голову по дуге.","Задержитесь на мгновение в нижней точке, затем поднимите гантель обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo.","Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza en un movimiento de arco.","Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0289","name":"dumbbell bench press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0289-SpYC0Kp.jpg","gif_url":"videos/0289-SpYC0Kp.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","החזיקו משקולת יד בכל יד, כפות ידיים פונות קדימה וידיים מיושרות מעל החזה.","הורידו את המשקולות באיטיות לצידי החזה, תוך שמירה על זווית של 90 מעלות במרפקים.","עצרו לרגע, ואז דחפו את המשקולות חזרה למעלה לנקודת ההתחלה עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand, with your palms facing forward and your arms extended above your chest.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Pause for a moment, then push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите по гантели в каждую руку ладонями вперед и руками, вытянутыми над грудью.","Медленно опустите гантели по бокам груди, держа локти под углом 90 градусов.","Сделайте паузу на мгновение, затем верните гантели в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Sujeta una mancuerna en cada mano, con las palmas hacia adelante y los brazos extendidos por encima del pecho.","Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.","Haz una pausa breve, luego empuja las mancuernas de vuelta hacia arriba hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0290","name":"dumbbell bench seated press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0290-3d7wHyd.jpg","gif_url":"videos/0290-3d7wHyd.gif","instruction_steps":{"he":["שבו על ספסל עם משקולת יד בכל יד, מונחות על הירכיים.","הישענו לאחור ומקמו את המשקולות לצידי החזה, כפות ידיים פונות קדימה.","לחצו את המשקולות כלפי מעלה עד יישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with a dumbbell in each hand, resting on your thighs.","Lean back and position the dumbbells to the sides of your chest, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, взяв в каждую руку по гантели, положив их на бедра.","Откиньтесь назад и расположите гантели по бокам груди ладонями вперед.","Выжмите гантели вверх, пока руки полностью не выпрямятся.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con una mancuerna en cada mano, apoyadas en los muslos.","Reclínate hacia atrás y coloca las mancuernas a los lados del pecho, con las palmas hacia adelante.","Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0291","name":"dumbbell bench squat","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0291-mnzcrIB.jpg","gif_url":"videos/0291-mnzcrIB.gif","instruction_steps":{"he":["הניחו משקולת יד על הרצפה מול ספסל.","עמדו עם הגב לספסל, רגליים ברוחב כתפיים.","כופפו ברכיים וירכיים לירידה לכיוון הספסל, תוך שמירה על חזה מורם וגב ישר.","כשהישבן נוגע בספסל, דחפו דרך העקבים לחזרה לעמידה בנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place a dumbbell on the ground in front of a bench.","Stand facing away from the bench with your feet shoulder-width apart.","Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight.","Once your glutes touch the bench, push through your heels to stand back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Положите гантель на землю перед скамьей.","Встаньте лицом от скамьи, поставив ноги на ширине плеч.","Согните колени и бедра, чтобы опуститься к скамье, держа грудь вверх и спину прямо.","Как только ваши ягодицы коснутся скамьи, оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca una mancuerna en el suelo frente a un banco.","Ponte de pie de espaldas al banco con los pies separados a la altura de los hombros.","Flexiona las rodillas y las caderas para bajar hacia el banco, manteniendo el pecho elevado y la espalda recta.","Una vez que los glúteos toquen el banco, empuja con los talones para volver a ponerte de pie en la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0293","name":"dumbbell bent over row","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0293-BJ0Hz5L.jpg","gif_url":"videos/0293-BJ0Hz5L.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, ברכיים כפופות מעט, ואחזו משקולת יד בכל יד עם כפות ידיים פונות לגוף.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וליבה מופעלת.","תנו לידיים להשתלשל ישר מטה לכיוון הרצפה, עם כיפוף קל במרפקים.","משכו את המשקולות למעלה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Let your arms hang straight down towards the floor, with your elbows slightly bent.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, колени слегка согнуты, в каждой руке держите по гантели ладонями к телу.","Наклонитесь вперед в бедрах, сохраняя спину прямой и напряженный корпус.","Пусть ваши руки свисают прямо к полу, слегка согнутые в локтях.","Подтяните гантели к груди, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Deja que los brazos cuelguen rectos hacia el suelo, con los codos ligeramente flexionados.","Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1651","name":"dumbbell bicep curl lunge with bowling motion","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1651-1VpF8db.jpg","gif_url":"videos/1651-1VpF8db.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד בכל יד עם כפות ידיים פונות קדימה.","צעדו קדימה עם כף רגל ימין, בכיפוף ברך ימין והורדת הגוף לעמדת מספריים.","תוך כדי המספריים קדימה, כופפו את המשקולות למעלה לכיוון הכתפיים, תוך שמירה על מרפקים צמודים לגוף.","בנקודה התחתונה של המספריים, סובבו את הגו ימינה, כאילו אתם מגלגלים כדור באולינג.","הפכו את התנועה — צעדו לאחור עם כף רגל ימין וחזרו לנקודת ההתחלה תוך הורדת המשקולות חזרה.","חזרו על תנועת המספריים והכפיפה, הפעם בסיבוב הגו שמאלה.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position.","As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body.","At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball.","Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down.","Repeat the lunge and curl motion, this time rotating your torso to the left.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, держа в каждой руке по гантели ладонями вперед.","Сделайте шаг вперед правой ногой, согнув правое колено и опустив тело в положение выпада.","Делая выпад вперед, поднимите гантели к плечам, держа локти близко к телу.","В нижней части выпада поверните туловище вправо, как если бы вы бросали мяч.","Выполните обратное движение, отступив правой ногой и вернувшись в исходное положение, одновременно опуская гантели вниз.","Повторите выпад и сгибание рук, на этот раз повернув туловище влево.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante.","Da un paso adelante con el pie derecho, flexionando la rodilla derecha y bajando el cuerpo a una posición de zancada.","Mientras avanzas en la zancada, flexiona las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo.","En la parte baja de la zancada, gira el torso hacia la derecha, como si estuvieras lanzando una bola de boliche.","Invierte el movimiento, retrocediendo con el pie derecho y regresando a la posición inicial mientras bajas las mancuernas de nuevo.","Repite el movimiento de zancada y flexión, esta vez girando el torso hacia la izquierda.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1652","name":"dumbbell bicep curl on exercise ball with leg raised","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1652-2NImIAG.jpg","gif_url":"videos/1652-2NImIAG.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד בכל יד, כפות ידיים פונות קדימה וידיים ישרות לגמרי.","כופפו באיטיות את המשקולות לכיוון הכתפיים, תוך שמירה על מרפקים צמודים לצידי הגוף.","עצרו לרגע בנקודה העליונה של התנועה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","תוך כדי ביצוע כפיפת הבייספס, הרימו רגל אחת מהרצפה והחזיקו אותה באוויר לאורך כל התרגיל.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגליים וחזרו על התרגיל."],"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position.","While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise.","Repeat for the desired number of repetitions, then switch legs and repeat."],"ru":["Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину.","Возьмите в каждую руку по гантели ладонями вперед и полностью выпрямленными руками.","Медленно поднимите гантели к плечам, держа локти близко к бокам.","Сделайте паузу на мгновение в верхней точке движения, затем медленно опустите гантели обратно в исходное положение.","Выполняя сгибание рук на бицепс, поднимите одну ногу от земли и удерживайте ее в воздухе на протяжении всего упражнения.","Повторите необходимое количество повторений, затем поменяйте ногу и повторите."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.","Flexiona lentamente las mancuernas hacia los hombros, manteniendo los codos cerca de los costados.","Haz una pausa breve en la parte alta del movimiento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Mientras realizas el curl de bíceps, levanta una pierna del suelo y mantenla en el aire durante todo el ejercicio.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."]}},{"id":"1653","name":"dumbbell bicep curl with stork stance","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1653-uSkDMYl.jpg","gif_url":"videos/1653-uSkDMYl.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד, כפות ידיים פונות קדימה.","מתחו רגל אחת לאחור, באיזון על קצות האצבעות של אותה רגל.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגליים וחזרו על התרגיל."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Extend one leg behind you, balancing on the toes of that foot.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями вперед.","Вытяните одну ногу позади себя, балансируя на пальцах этой стопы.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу и повторите."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.","Extiende una pierna hacia atrás, equilibrándote sobre los dedos de ese pie.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."]}},{"id":"0294","name":"dumbbell biceps curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0294-NbVPDMW.jpg","gif_url":"videos/0294-NbVPDMW.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות קדימה וידיים ישרות.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, взяв в каждую руку по гантели, ладони направлены вперед, руки полностью выпрямлены.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2401","name":"dumbbell biceps curl (with arm blaster)","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2401-nlJsbkW.jpg","gif_url":"videos/2401-nlJsbkW.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות קדימה.","שמרו על מרפקים צמודים לגוף וזרועות עליונות ללא תזוזה.","נשפו וכופפו את המשקולות תוך כיווץ הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, взяв в каждую руку по гантели ладонями вперед.","Держите локти близко к туловищу, а плечи неподвижны.","Выдохните и согните штангу, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.","Mantén los codos cerca del torso y los brazos superiores quietos.","Exhala y flexiona las pesas mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1654","name":"dumbbell biceps curl reverse","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1654-nFc4FyV.jpg","gif_url":"videos/1654-nFc4FyV.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים כלפי מטה וידיים ישרות לגמרי.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, взяв в каждую руку по гантели, ладонями вниз и полностью выпрямленными руками.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1655","name":"dumbbell biceps curl squat","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1655-niXESDw.jpg","gif_url":"videos/1655-niXESDw.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד בכל יד עם כפות ידיים פונות קדימה.","תוך שמירה על גב ישר ומרפקים צמודים לצידי הגוף, נשפו וכופפו את המשקולות למעלה לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, держа в каждой руке по гантели ладонями вперед.","Держа спину прямой и локти близко к бокам, выдохните и поднимите гантели к плечам.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante.","Manteniendo la espalda recta y los codos cerca de los costados, exhala y flexiona las mancuernas hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1656","name":"dumbbell biceps curl v sit on bosu ball","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1656-H1XAdpk.jpg","gif_url":"videos/1656-H1XAdpk.gif","instruction_steps":{"he":["שבו על כדור בוסו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","החזיקו משקולת יד בכל יד, כפות ידיים פונות קדימה וידיים ישרות לגמרי לצידי הגוף.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч босу, ​​поставив ступни на землю и согнув колени под углом 90 градусов.","Возьмите по гантели в каждую руку ладонями вперед и полностью выпрямив руки по бокам.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un bosu con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos hacia abajo a los lados.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1201","name":"dumbbell burpee","category":"cardio","body_part":"cardio","equipment":"dumbbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","shoulders","triceps","core"],"target":"cardiovascular system","image":"images/1201-0JtKWum.jpg","gif_url":"videos/1201-0JtKWum.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים ומשקולת יד בכל יד.","הורידו את הגוף לעמדת סקוואט, בהנחת המשקולות על הרצפה לפניכם.","בעטו את הרגליים לאחור לעמדת שכיבת סמיכה, תוך שמירה על גוף בקו ישר.","בצעו שכיבת סמיכה — כופפו מרפקים והורידו את החזה לכיוון הרצפה.","קפצו עם הרגליים חזרה לכיוון הידיים, בנחיתה בעמדת סקוואט.","עמדו בפיצוץ, בהרמת המשקולות מהרצפה והבאתן לכתפיים.","לחצו את המשקולות מעל הראש, עד יישור מלא של הידיים.","הורידו את המשקולות חזרה לכתפיים וחזרו על הרצף המלא למספר החזרות הרצוי."],"en":["Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand.","Lower your body into a squat position, placing the dumbbells on the ground in front of you.","Kick your feet back into a push-up position, keeping your body in a straight line.","Perform a push-up, bending your elbows and lowering your chest towards the ground.","Jump your feet back towards your hands, landing in a squat position.","Stand up explosively, lifting the dumbbells off the ground and bringing them to your shoulders.","Press the dumbbells overhead, fully extending your arms.","Lower the dumbbells back to your shoulders and repeat the entire sequence for the desired number of repetitions."],"ru":["Начните в положении стоя, ноги на ширине плеч, в каждой руке по гантели.","Опустите тело в присед, положив гантели на пол перед собой.","Верните ноги в положение для отжимания, сохраняя тело прямой линией.","Выполните отжимание, сгибая локти и опуская грудь к земле.","Прыгните ногами назад к рукам и приземлитесь в приседе.","Резко встаньте, подняв гантели от земли и поднеся их к плечам.","Выжмите гантели над головой, полностью выпрямляя руки.","Опустите гантели обратно на плечи и повторите всю последовательность желаемое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de los hombros y una mancuerna en cada mano.","Baja el cuerpo a una posición de sentadilla, colocando las mancuernas en el suelo frente a ti.","Lleva los pies hacia atrás a una posición de flexión de brazos, manteniendo el cuerpo en línea recta.","Realiza una flexión de brazos, flexionando los codos y bajando el pecho hacia el suelo.","Salta con los pies hacia tus manos, aterrizando en una posición de sentadilla.","Ponte de pie de forma explosiva, levantando las mancuernas del suelo y llevándolas a los hombros.","Empuja las mancuernas por encima de la cabeza, extendiendo completamente los brazos.","Baja las mancuernas de vuelta a los hombros y repite toda la secuencia el número de repeticiones deseado."]}},{"id":"0295","name":"dumbbell clean","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","calves"],"target":"glutes","image":"images/0295-7Hg55JG.jpg","gif_url":"videos/0295-7Hg55JG.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד באחיזה עליונה.","כופפו ברכיים והורידו את האגן לעמדת סקוואט, תוך שמירה על גב ישר וחזה מורם.","יישרו ירכיים וברכיים בפיצוץ, בדחיפה דרך העקבים לקפיצה מהרצפה.","תוך כדי הקפיצה, משכו כתפיים והרימו את המשקולות למעלה לכיוון הכתפיים, כשהן צמודות לגוף.","תפסו את המשקולות בגובה הכתפיים, עם מרפקים פונים קדימה וכפות ידיים כלפי מעלה.","הורידו את המשקולות חזרה לנקודת ההתחלה בהיפוך התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips and knees, driving through your heels to jump off the ground.","As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body.","Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up.","Lower the dumbbells back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите по гантели в каждой руке хватом сверху.","Согните ноги в коленях и опустите бедра в положение приседа, держа спину прямо и грудь вверх.","Взрывно выпрямите бедра и колени, задействуя пятки, чтобы оторваться от земли.","Во время прыжка пожимайте плечами и подтягивайте гантели к плечам, удерживая их близко к телу.","Возьмите гантели на уровне плеч, локти должны быть направлены вперед, а ладони — вверх.","Опустите гантели обратно в исходное положение, выполняя движение в обратном направлении.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Extiende las caderas y las rodillas de forma explosiva, empujando con los talones para saltar del suelo.","Mientras saltas, encoge los hombros y tira de las mancuernas hacia arriba, hacia los hombros, manteniéndolas cerca del cuerpo.","Atrapa las mancuernas a la altura de los hombros, con los codos apuntando hacia adelante y las palmas hacia arriba.","Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento.","Repite el número de repeticiones deseado."]}},{"id":"1731","name":"dumbbell close grip press","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1731-7jGOBF3.jpg","gif_url":"videos/1731-7jGOBF3.gif","instruction_steps":{"he":["שבו על ספסל ישר עם משקולת יד בכל יד, מונחות על הירכיים.","היעזרו בירכיים להרמת המשקולות, אחת בכל פעם, כך שתחזיקו אותן לפניכם ברוחב כתפיים.","בהגיע המשקולות לרוחב כתפיים, סובבו את שורשי כף היד קדימה כך שכפות הידיים פונות מכם. זוהי נקודת ההתחלה.","תוך שאיפה, הורידו את המשקולות באיטיות לצדדים עד שהן בערך בגובה החזה.","תוך נשיפה, השתמשו בטרייספס להרמת המשקולות חזרה לנקודת ההתחלה. הקפידו להשתמש רק בטרייספס, בלי עזרת האמות או הבייספס.","אחרי עצירה של שנייה בתנוחה המכווצת, חזרו על התנועה למספר החזרות המומלץ."],"en":["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"ru":["Сядьте на ровную скамью, взяв в каждую руку по гантели, положив их на бедра.","Используя бедра для поднятия гантелей, поднимайте гантели по одной так, чтобы вы могли держать их перед собой на ширине плеч.","Оказавшись на ширине плеч, поверните запястья вперед так, чтобы ладони были обращены от вас. Это будет ваша исходная позиция.","На вдохе медленно опустите гантели в сторону, пока они не окажутся примерно на уровне груди.","На выдохе с помощью трицепсов поднимите гантели обратно в исходное положение. Обязательно задействуйте только трицепсы и не задействуйте предплечья или бицепсы для подъема гантелей.","После второй паузы в сокращенном положении повторите движение заданное количество повторений."],"es":["Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos.","Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros.","Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti. Esta será tu posición inicial.","Mientras inhalas, baja lentamente las mancuernas hacia tu lado hasta que queden aproximadamente a la altura del pecho.","Mientras exhalas, usa los tríceps para levantar las mancuernas de vuelta a la posición inicial. Asegúrate de usar solo los tríceps y no usar los antebrazos ni los bíceps para ayudar a levantar las mancuernas.","Después de una pausa de un segundo en la posición contraída, repite el movimiento el número de repeticiones prescrito."]}},{"id":"0296","name":"dumbbell close-grip press","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0296-RxayqAZ.jpg","gif_url":"videos/0296-RxayqAZ.gif","instruction_steps":{"he":["שבו על ספסל ישר עם משקולת יד בכל יד, מונחות על הירכיים.","היעזרו בירכיים להרמת המשקולות, אחת בכל פעם, כך שתחזיקו אותן לפניכם ברוחב כתפיים.","בהגיע המשקולות לרוחב כתפיים, סובבו את שורשי כף היד קדימה כך שכפות הידיים פונות מכם. זוהי נקודת ההתחלה.","תוך שאיפה, הורידו את המשקולות באיטיות לצדדים עד שהן בערך בגובה החזה.","תוך נשיפה, השתמשו בטרייספס להרמת המשקולות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на ровную скамью, взяв в каждую руку по гантели, положив их на бедра.","Используя бедра для поднятия гантелей, поднимайте гантели по одной так, чтобы вы могли держать их перед собой на ширине плеч.","Оказавшись на ширине плеч, поверните запястья вперед так, чтобы ладони были обращены от вас. Это будет ваша исходная позиция.","На вдохе медленно опустите гантели в сторону, пока они не окажутся примерно на уровне груди.","На выдохе с помощью трицепсов поднимите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos.","Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros.","Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti. Esta será tu posición inicial.","Mientras inhalas, baja lentamente las mancuernas hacia tu lado hasta que queden aproximadamente a la altura del pecho.","Mientras exhalas, usa los tríceps para levantar las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0297","name":"dumbbell concentration curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0297-gvsWLQw.jpg","gif_url":"videos/0297-gvsWLQw.gif","instruction_steps":{"he":["שבו על ספסל עם רגליים פסוקות ומשקולת יד ביד אחת, כשהמרפק נשען על החלק הפנימי של הירך.","מתחו את היד לגמרי והחזיקו את המשקולת באחיזה תחתונה.","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את המשקל למעלה לכיוון הכתף תוך כיווץ הבייספס.","המשיכו להרים את המשקולת עד שהבייספס מכווץ במלואו והמשקולת בגובה הכתף.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh.","Fully extend your arm and hold the dumbbell with an underhand grip.","Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью, раздвиньте ноги и возьмите в одну руку гантель, положив локоть на внутреннюю часть бедра.","Полностью выпрямите руку и возьмите гантель обратным хватом.","Удерживая плечо неподвижно, выдохните и поднимите вес к плечу, одновременно сокращая бицепсы.","Продолжайте поднимать гантель до тех пор, пока ваши бицепсы полностью не сократятся и гантель не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco con las piernas separadas y una mancuerna en una mano, apoyando el codo en la parte interna del muslo.","Extiende completamente el brazo y sujeta la mancuerna con un agarre supino.","Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro mientras contraes el bíceps.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"3635","name":"dumbbell contralateral forward lunge","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3635-ecl28tP.jpg","gif_url":"videos/3635-ecl28tP.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד.","צעדו קדימה עם רגל ימין, תוך שמירה על גב ישר וליבה מופעלת.","הורידו את הגוף בכיפוף שתי הברכיים עד שירך ימין מקבילה לרצפה.","דחפו דרך עקב ימין כדי לחזור לנקודת ההתחלה.","חזרו על התנועה עם רגל שמאל.","החליפו רגליים לסירוגין למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, keeping your back straight and core engaged.","Lower your body by bending both knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гантели.","Сделайте шаг вперед правой ногой, сохраняя спину прямой и напряженным корпусом.","Опустите тело, согнув оба колена, пока правое бедро не станет параллельно земле.","Оттолкнитесь правой пяткой, чтобы вернуться в исходное положение.","Повторите с левой ногой.","Чередуйте ноги необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Da un paso adelante con el pie derecho, manteniendo la espalda recta y el core activado.","Baja el cuerpo flexionando ambas rodillas hasta que el muslo derecho quede paralelo al suelo.","Empuja con el talón derecho para regresar a la posición inicial.","Repite con la pierna izquierda.","Alterna las piernas el número de repeticiones deseado."]}},{"id":"0298","name":"dumbbell cross body hammer curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0298-Qyk5J3p.jpg","gif_url":"videos/0298-Qyk5J3p.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות לגוף.","שמרו על מרפקים צמודים לגוף וזרועות עליונות ללא תזוזה.","נשפו וכופפו את המשקולות תוך כיווץ הבייספס, והביאו את המשקולות באלכסון לכיוון הכתף הנגדית.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, возьмите в каждую руку по гантели, ладони обращены к телу.","Держите локти близко к туловищу, а плечи неподвижны.","Выдохните и согните гантели, напрягая бицепсы, перемещая гантели поперек тела к противоположному плечу.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Mantén los codos cerca del torso y los brazos superiores quietos.","Exhala y flexiona los brazos contrayendo los bíceps, llevando las mancuernas a través del cuerpo hacia el hombro opuesto.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1657","name":"dumbbell cross body hammer curl v. 2","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1657-HDYiZcY.jpg","gif_url":"videos/1657-HDYiZcY.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות לגוף.","שמרו על מרפקים צמודים לגוף וזרועות עליונות ללא תזוזה.","נשפו וכופפו את המשקולות תוך כיווץ הבייספס, והביאו את המשקולות קרוב ככל האפשר לכתף הנגדית.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells as close to your opposite shoulder as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, возьмите в каждую руку по гантели, ладони обращены к телу.","Держите локти близко к туловищу, а плечи неподвижны.","Выдохните и согните гантели, напрягая бицепсы, поднося гантели как можно ближе к противоположному плечу.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Mantén los codos cerca del torso y los brazos superiores quietos.","Exhala y flexiona los brazos contrayendo los bíceps, acercando las mancuernas lo más posible al hombro opuesto.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0299","name":"dumbbell cuban press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0299-QfAKy1G.jpg","gif_url":"videos/0299-QfAKy1G.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד בכל יד בגובה הכתפיים עם כפות ידיים כלפי מטה.","תוך שמירה על ליבה מופעלת ומרפקים כפופים מעט, לחצו את המשקולות למעלה ומעל הראש עד יישור מלא של הידיים.","סובבו את שורשי כף היד כך שכפות הידיים פונות קדימה.","הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה, בסיבוב שורשי כף היד חזרה תוך כדי.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended.","Rotate your wrists so that your palms are facing forward.","Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, держа в каждой руке по гантели на уровне плеч ладонями вниз.","Удерживая корпус напряженным и слегка согнутыми в локтях, поднимите гантели вверх и над головой, пока руки полностью не выпрямятся.","Поверните запястья так, чтобы ладони были направлены вперед.","Медленно опустите гантели обратно в исходное положение, поворачивая при этом запястья обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros con las palmas hacia abajo.","Manteniendo el core activado y los codos ligeramente flexionados, empuja las mancuernas hacia arriba por encima de la cabeza hasta que los brazos queden completamente extendidos.","Gira las muñecas de modo que las palmas queden mirando hacia adelante.","Baja lentamente las mancuernas a la posición inicial, girando las muñecas de vuelta a la posición inicial mientras lo haces.","Repite el número de repeticiones deseado."]}},{"id":"2136","name":"dumbbell cuban press v. 2","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/2136-BqgCRif.jpg","gif_url":"videos/2136-BqgCRif.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד בכל יד בגובה הכתפיים עם כפות ידיים כלפי מטה.","תוך שמירה על ליבה מופעלת וגב ישר, לחצו את המשקולות ישר מעל הראש עד יישור מלא של הידיים.","סובבו את שורשי כף היד כך שכפות הידיים פונות קדימה.","הורידו את המשקולות חזרה לגובה הכתפיים, בסיבוב שורשי כף היד חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended.","Rotate your wrists so that your palms are facing forward.","Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, держа в каждой руке по гантели на уровне плеч ладонями вниз.","Удерживая корпус напряженным, а спину прямой, поднимите гантели прямо над головой, пока руки полностью не выпрямятся.","Поверните запястья так, чтобы ладони были направлены вперед.","Опустите гантели обратно на высоту плеч, повернув запястья обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros con las palmas hacia abajo.","Manteniendo el core activado y la espalda recta, empuja las mancuernas directamente hacia arriba por encima de la cabeza hasta que los brazos queden completamente extendidos.","Gira las muñecas de modo que las palmas queden mirando hacia adelante.","Baja las mancuernas de nuevo hasta la altura de los hombros, girando las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0300","name":"dumbbell deadlift","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0300-nUwVh7b.jpg","gif_url":"videos/0300-nUwVh7b.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, כפות רגליים פונות קדימה.","החזיקו משקולת יד בכל יד, כפות ידיים פונות לגוף, ידיים מתוחות כלפי מטה.","כופפו ירכיים וברכיים, והורידו את המשקולות לכיוון הרצפה תוך שמירה על גב ישר.","דחפו דרך העקבים ויישרו ירכיים וברכיים, בהרמת המשקולות חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, toes pointing forward.","Hold a dumbbell in each hand, palms facing your body, arms extended downwards.","Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight.","Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки направлены вперед.","Возьмите по гантели в каждую руку ладонями к телу, руки вытянуты вниз.","Согните бедра и колени, опуская гантели к земле, сохраняя при этом спину прямой.","Оттолкнитесь пятками и выпрямите бедра и колени, поднимая гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.","Sostén una mancuerna en cada mano, con las palmas hacia el cuerpo y los brazos extendidos hacia abajo.","Flexiona las caderas y las rodillas, bajando las mancuernas hacia el suelo mientras mantienes la espalda recta.","Empuja con los talones y extiende las caderas y las rodillas, levantando las mancuernas de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0301","name":"dumbbell decline bench press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0301-DwhEmmE.jpg","gif_url":"videos/0301-DwhEmmE.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשכפות הרגליים מקובעות והראש נמוך מהאגן.","החזיקו משקולת יד בכל יד ומתחו את הידיים ישר מעל החזה, כפות ידיים פונות קדימה.","הורידו את המשקולות באיטיות לצידי החזה, תוך שמירה על זווית של 90 מעלות במרפקים.","דחפו את המשקולות חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie down on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, зафиксировав ноги и опустив голову ниже бедер.","Возьмите по гантели в каждую руку и вытяните руки прямо над грудью ладонями вперед.","Медленно опустите гантели по бокам груди, держа локти под углом 90 градусов.","Верните гантели в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Sostén una mancuerna en cada mano y extiende los brazos rectos hacia arriba por encima del pecho, con las palmas hacia adelante.","Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.","Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0302","name":"dumbbell decline fly","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/0302-xXm4nYq.jpg","gif_url":"videos/0302-xXm4nYq.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשכפות הרגליים מקובעות והראש נמוך מהאגן.","החזיקו משקולת יד בכל יד, כפות ידיים פונות זו לזו וידיים מתוחות מעל החזה.","הורידו את המשקולות לצדדים בקשת רחבה עד שתרגישו מתיחה בחזה.","עצרו לרגע, ואז כווצו את שרירי החזה להחזרת המשקולות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, зафиксировав ноги и опустив голову ниже бедер.","Возьмите в каждую руку по гантели, ладони обращены друг к другу, руки вытянуты над грудью.","Опускайте гантели в стороны по широкой дуге, пока не почувствуете растяжение в груди.","Сделайте паузу на мгновение, затем сожмите мышцы груди, чтобы вернуть гантели в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho.","Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0303","name":"dumbbell decline hammer press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0303-1qrWgZ2.jpg","gif_url":"videos/0303-1qrWgZ2.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשכפות הרגליים מקובעות והראש נמוך מהאגן.","החזיקו משקולת יד בכל יד, כפות ידיים פונות זו לזו וידיים מתוחות מעל החזה.","הורידו את המשקולות לצידי החזה, עם כיפוף קל במרפקים.","לחצו את המשקולות חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, зафиксировав ноги и опустив голову ниже бедер.","Возьмите в каждую руку по гантели, ладони обращены друг к другу, руки вытянуты над грудью.","Опустите гантели по бокам груди, слегка согнув локти.","Верните гантели в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho.","Baja las mancuernas a los lados del pecho, manteniendo los codos ligeramente flexionados.","Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1276","name":"dumbbell decline one arm fly","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/1276-NL6YBwN.jpg","gif_url":"videos/1276-NL6YBwN.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי עם משקולת יד ביד אחת, מונחת על הירך.","היעזרו בירך להרמת המשקולת לרוחב כתפיים, עם כף היד פונה לגו.","סובבו את שורש כף היד כך שכף היד פונה קדימה.","תוך שאיפה, הורידו את המשקולת באיטיות הצידה עד לתחושת מתיחה בחזה.","נשפו והשתמשו בשרירי החזה להחזרת המשקולת למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.","Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.","Rotate your wrist so that the palm of your hand is facing forward.","As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest.","Exhale and use your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Лягте на наклонную скамью с гантелью в одной руке, положив ее на бедро.","Используя бедро, чтобы поднять гантель, поднимите ее до ширины плеч ладонью к туловищу.","Поверните запястье так, чтобы ладонь была обращена вперед.","На вдохе медленно опустите гантель в сторону, пока не почувствуете растяжение в груди.","Выдохните и задействуйте мышцы груди, чтобы вернуть гантель в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Túmbate en un banco declinado con una mancuerna en una mano, apoyándola sobre el muslo.","Usando el muslo para ayudar a levantar la mancuerna, álzala hasta la altura de los hombros con la palma mirando hacia el torso.","Gira la muñeca de modo que la palma de la mano quede mirando hacia adelante.","Mientras inhalas, baja la mancuerna lentamente hacia el lado hasta sentir un estiramiento en el pecho.","Exhala y usa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1617","name":"dumbbell decline one arm hammer press","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1617-SHUMp5H.jpg","gif_url":"videos/1617-SHUMp5H.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי עם משקולת יד ביד אחת, מונחת על החזה.","מתחו את היד ישר למעלה, עם כיפוף קל במרפק.","הורידו את המשקולת לכיוון הכתף, תוך שמירה על מרפק קרוב לגוף.","לחצו את המשקולת חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Extend your arm straight up, keeping your elbow slightly bent.","Lower the dumbbell down towards your shoulder, keeping your elbow close to your body.","Press the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Лягте на наклонную скамью с гантелью в одной руке, положив ее на грудь.","Вытяните руку прямо вверх, слегка согнув локоть.","Опустите гантель к плечу, держа локоть близко к телу.","Выжмите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho.","Extiende el brazo recto hacia arriba, manteniendo el codo ligeramente flexionado.","Baja la mancuerna hacia el hombro, manteniendo el codo cerca del cuerpo.","Empuja la mancuerna de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0305","name":"dumbbell decline shrug","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","rhomboids"],"target":"traps","image":"images/0305-cwsAI4G.jpg","gif_url":"videos/0305-cwsAI4G.gif","instruction_steps":{"he":["כווננו ספסל שיפוע שלילי לזווית של 45 מעלות.","שכבו על הבטן על הספסל, כשהחזה והבטן נשענים עליו.","החזיקו משקולת יד בכל יד עם ידיים מתוחות לגמרי לכיוון הרצפה.","תוך שמירה על ידיים ישרות, הרימו את הכתפיים לכיוון האוזניים גבוה ככל האפשר.","החזיקו את הכיווץ לרגע, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a dumbbell in each hand with your arms fully extended towards the floor.","Keeping your arms straight, raise your shoulders towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте лицом вниз на скамью, прижавшись к ней грудью и животом.","Возьмите по гантели в каждую руку, полностью вытянув руки к полу.","Держа руки прямыми, поднимите плечи к ушам как можно выше.","Задержите сокращение на мгновение, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta un banco declinado a un ángulo de 45 grados.","Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.","Sostén una mancuerna en cada mano con los brazos completamente extendidos hacia el suelo.","Manteniendo los brazos rectos, levanta los hombros hacia las orejas lo más alto posible.","Mantén la contracción por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0304","name":"dumbbell decline shrug v. 2","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","rhomboids"],"target":"traps","image":"images/0304-bRlbdjK.jpg","gif_url":"videos/0304-bRlbdjK.gif","instruction_steps":{"he":["כווננו ספסל שיפוע שלילי לזווית של 45 מעלות.","שכבו על הבטן על הספסל, כשהחזה והבטן נשענים עליו.","החזיקו משקולת יד בכל יד, כפות ידיים פונות זו לזו וידיים ישרות לגמרי.","תוך שמירה על ידיים ישרות, הרימו את הכתפיים גבוה ככל האפשר תוך כיווץ השכמות זו לזו.","החזיקו את הכיווץ לרגע קצר, ואז הורידו את המשקולות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting on it.","Hold a dumbbell in each hand with your palms facing each other and your arms fully extended.","Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together.","Hold the contraction for a brief pause, then lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте лицом вниз на скамью, положив на нее грудь и живот.","Возьмите по гантели в каждую руку ладонями друг к другу и полностью выпрямите руки.","Держа руки прямыми, поднимите плечи как можно выше, сводя лопатки вместе.","Удерживайте сокращение на короткую паузу, затем опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta un banco declinado a un ángulo de 45 grados.","Túmbate boca abajo en el banco con el pecho y el abdomen apoyados sobre él.","Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos completamente extendidos.","Manteniendo los brazos rectos, levanta los hombros lo más alto posible mientras juntas los omóplatos.","Mantén la contracción durante una breve pausa, luego baja las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0306","name":"dumbbell decline triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0306-OTgkHwR.jpg","gif_url":"videos/0306-OTgkHwR.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשהראש נמוך מהרגליים והחזיקו משקולת יד בכל יד, כפות ידיים פונות זו לזו.","יישרו את הידיים לגמרי, תוך שמירה על מרפקים קרובים לראש.","הורידו את המשקולות באיטיות מאחורי הראש, בכיפוף המרפקים.","עצרו לרגע, ואז הרימו את המשקולות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.","Extend your arms fully, keeping your elbows close to your head.","Lower the dumbbells slowly behind your head, bending your elbows.","Pause for a moment, then raise the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, опустив голову ниже ног, возьмите в каждую руку по гантели, ладони обращены друг к другу.","Полностью выпрямите руки, держа локти близко к голове.","Медленно опустите гантели за голову, сгибая локти.","Сделайте паузу на мгновение, затем поднимите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con la cabeza más baja que los pies y sostén una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende completamente los brazos, manteniendo los codos cerca de la cabeza.","Baja lentamente las mancuernas detrás de la cabeza, flexionando los codos.","Haz una pausa por un momento, luego levanta las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0307","name":"dumbbell decline twist fly","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0307-reFHapa.jpg","gif_url":"videos/0307-reFHapa.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשהראש נמוך מהאגן.","החזיקו משקולת יד בכל יד, כפות ידיים פונות זו לזו וידיים מתוחות ישר מעל החזה.","הורידו את המשקולות לצדדים בקשת רחבה עד שתרגישו מתיחה בחזה.","תוך כדי הורדת המשקולות, סובבו את שורשי כף היד כך שכפות הידיים יפנו קדימה בנקודה התחתונה של התנועה.","הפכו את התנועה והחזירו את המשקולות למעלה לנקודת ההתחלה, בכיווץ שרירי החזה בנקודה העליונה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie down on a decline bench with your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью так, чтобы голова была ниже бедер.","Возьмите по гантели в каждую руку ладонями друг к другу, а руки вытяните прямо над грудью.","Опускайте гантели в стороны по широкой дуге, пока не почувствуете растяжение в груди.","Опуская гантели, поверните запястья так, чтобы ладони смотрели вперед в нижней части движения.","Сделайте обратное движение и верните гантели в исходное положение, напрягая мышцы груди в верхней части.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con la cabeza más baja que las caderas.","Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho.","Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento.","Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior.","Repite el número de repeticiones deseado."]}},{"id":"1437","name":"dumbbell finger curls","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"wrist flexors","secondary_muscles":["wrist flexors","wrist extensors"],"target":"forearms","image":"images/1437-mtXengz.jpg","gif_url":"videos/1437-mtXengz.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד ביד אחת באחיזה תחתונה, כשהאמה נשענת על הירך וכף היד כלפי מעלה.","תנו למשקולת להתגלגל מטה עד קצות האצבעות, ואז גלגלו אותה חזרה בכיפוף האצבעות.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.","Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.","Repeat for the desired number of repetitions, then switch to the other hand."],"ru":["Сядьте на скамью или стул, поставив ноги на землю и выпрямив спину.","Возьмите гантель в одну руку обратным хватом, положив предплечье на бедро ладонью вверх.","Позвольте гантеле скатиться до кончиков пальцев, затем снова согните ее, согнув пальцы.","Повторите необходимое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta.","Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo, con la palma hacia arriba.","Deja que la mancuerna ruede hacia las puntas de los dedos, luego flexiona los dedos para volver a enrollarla hacia arriba.","Repite el número de repeticiones deseado, luego cambia a la otra mano."]}},{"id":"0308","name":"dumbbell fly","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/0308-yz9nUhF.jpg","gif_url":"videos/0308-yz9nUhF.gif","instruction_steps":{"he":["שכבו על ספסל עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","יישרו את הידיים למעלה מעל החזה, עם כיפוף קל במרפקים.","תוך שמירה על כיפוף קל במרפקים, הורידו את הידיים לצדדים בקשת רחבה עד שתרגישו מתיחה בחזה.","עצרו לרגע, ואז הפכו את התנועה והחזירו את המשקולות למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, взяв в каждую руку по гантели, ладони обращены друг к другу.","Вытяните руки прямо вверх над грудью, слегка согнув их в локтях.","Сохраняя небольшой изгиб в локтях, опустите руки в стороны по широкой дуге, пока не почувствуете растяжение в груди.","Сделайте паузу на мгновение, затем поменяйте направление движения и верните гантели в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.","Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1277","name":"dumbbell fly on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1277-Lt3iWnf.jpg","gif_url":"videos/1277-Lt3iWnf.gif","instruction_steps":{"he":["שבו על כדור פיזיו והחזיקו משקולת יד בכל יד.","צעדו עם כפות הרגליים קדימה וגלגלו את הגוף מטה עד שהראש, הצוואר והגב העליון נתמכים על הכדור.","מתחו את הידיים ישר מעל החזה, כפות ידיים פונות זו לזו.","כופפו מרפקים מעט והורידו את הידיים לצדדים בקשת רחבה עד לתחושת מתיחה בחזה.","עצרו לרגע, ואז הפכו את התנועה וכווצו את שרירי החזה תוך החזרת המשקולות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an exercise ball and hold a dumbbell in each hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.","Extend your arms straight up above your chest, palms facing each other.","Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на гимнастический мяч и возьмите в каждую руку по гантели.","Пройдите ногами вперед и перекатывайте тело вниз, пока ваша голова, шея и верхняя часть спины не будут поддержаны мячом.","Вытяните руки прямо над грудью, ладони обращены друг к другу.","Слегка согните локти и опустите руки в стороны по широкой дуге, пока не почувствуете растяжение в груди.","Сделайте паузу на мгновение, затем поменяйте направление движения и напрягите мышцы груди, возвращая гантели в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de estabilidad y sostén una mancuerna en cada mano.","Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Extiende los brazos rectos por encima del pecho, con las palmas enfrentadas entre sí.","Flexiona ligeramente los codos y baja los brazos hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento, luego invierte el movimiento y contrae los músculos del pecho mientras llevas las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1732","name":"dumbbell forward lunge triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"triceps","image":"images/1732-XalXcvM.jpg","gif_url":"videos/1732-XalXcvM.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד.","צעדו קדימה עם רגל ימין והורידו את הגוף לעמדת מספריים (לאנג').","שמרו על גב ישר וחזה מורם.","מתחו את הידיים ישר מעל הראש, תוך שמירה על מרפקים קרובים לאוזניים.","הורידו את המשקולות מאחורי הראש בכיפוף המרפקים.","עצרו לרגע, ואז יישרו את הידיים לחזרה לנקודת ההתחלה.","חזרו על התנועה למספר החזרות הרצוי, ואז החליפו רגליים וחזרו על התרגיל."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up.","Extend your arms straight overhead, keeping your elbows close to your ears.","Lower the dumbbells behind your head by bending your elbows.","Pause for a moment, then straighten your arms to return to the starting position.","Repeat the movement for the desired number of repetitions, then switch legs and repeat."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гантели.","Сделайте шаг вперед правой ногой, опуская тело в положение выпада.","Держите спину прямо и грудь вверх.","Вытяните руки прямо над головой, держа локти близко к ушам.","Опустите гантели за голову, согнув руки в локтях.","Сделайте паузу на мгновение, затем выпрямите руки и вернитесь в исходное положение.","Повторите движение желаемое количество повторений, затем поменяйте ноги и повторите."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Mantén la espalda recta y el pecho elevado.","Extiende los brazos rectos por encima de la cabeza, manteniendo los codos cerca de las orejas.","Baja las mancuernas detrás de la cabeza flexionando los codos.","Haz una pausa por un momento, luego estira los brazos para volver a la posición inicial.","Repite el movimiento el número de repeticiones deseado, luego cambia de pierna y repite."]}},{"id":"0310","name":"dumbbell front raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","trapezius"],"target":"delts","image":"images/0310-3eGE2JC.jpg","gif_url":"videos/0310-3eGE2JC.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במשקולת יד בכל יד עם כפות ידיים פונות לירכיים.","תוך שמירה על ידיים ישרות, נשפו והרימו את המשקולות לפניכם עד גובה הכתפיים.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите по гантели в каждой руке ладонями к бедрам.","Держа руки прямыми, выдохните и поднимите гантели перед собой до уровня плеч.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos.","Manteniendo los brazos rectos, exhala y levanta las mancuernas frente a ti hasta que queden a la altura de los hombros.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0309","name":"dumbbell front raise v. 2","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","biceps"],"target":"delts","image":"images/0309-Rr7S3yg.jpg","gif_url":"videos/0309-Rr7S3yg.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במשקולת יד בכל יד עם כפות ידיים פונות לירכיים.","שמרו על גב ישר והפעילו את שרירי הליבה.","הרימו באיטיות את המשקולות לפניכם, עם ידיים ישרות, עד גובה הכתפיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keep your back straight and engage your core.","Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите по гантели в каждой руке ладонями к бедрам.","Держите спину прямо и задействуйте корпус.","Медленно поднимите гантели перед собой, выпрямив руки, пока они не окажутся на уровне плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos.","Mantén la espalda recta y activa el core.","Levanta lentamente las mancuernas frente a ti, con los brazos rectos, hasta que queden a la altura de los hombros.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0311","name":"dumbbell full can lateral raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","rotator cuff"],"target":"delts","image":"images/0311-AQ0mC4Y.jpg","gif_url":"videos/0311-AQ0mC4Y.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במשקולת יד בכל יד עם כפות ידיים פונות לגוף.","שמרו על גב ישר והפעילו את שרירי הליבה.","הרימו את הידיים לצדדים, עם כיפוף קל במרפקים, עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите в каждой руке по гантели ладонями к телу.","Держите спину прямо и задействуйте корпус.","Поднимите руки в стороны, сохраняя небольшой изгиб в локтях, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo.","Mantén la espalda recta y activa el core.","Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1760","name":"dumbbell goblet squat","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/1760-yn8yg1r.jpg","gif_url":"videos/1760-yn8yg1r.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד אנכית צמוד לחזה בשתי הידיים.","שמרו על חזה מורם וליבה מופעלת, ורדו לסקוואט על ידי דחיפת האגן לאחור וכיפוף הברכיים.","המשיכו לרדת עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands.","Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, удерживая гантель вертикально у груди обеими руками.","Удерживая грудь поднятой и напряженным корпус, опустите тело в присед, отведя бедра назад и согнув колени.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna verticalmente contra el pecho con ambas manos.","Manteniendo el pecho erguido y el core activado, baja el cuerpo a una posición de sentadilla empujando las caderas hacia atrás y flexionando las rodillas.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0313","name":"dumbbell hammer curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0313-slDvUAU.jpg","gif_url":"videos/0313-slDvUAU.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות לגו.","שמרו על מרפקים צמודים לגו וסובבו את כפות הידיים עד שהן פונות קדימה.","זוהי נקודת ההתחלה שלכם.","כעת, תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המשקולות תוך כיווץ הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","לאחר מכן, שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות המומלץ."],"en":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"ru":["Встаньте прямо, возьмите в каждую руку по гантели, ладони обращены к туловищу.","Держите локти близко к туловищу и поворачивайте ладони рук так, чтобы они смотрели вперед.","Это будет ваша исходная позиция.","Теперь, удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Затем вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите рекомендованное количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.","Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.","Esta será tu posición inicial.","Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones recomendado."]}},{"id":"1659","name":"dumbbell hammer curl on exercise ball","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1659-fY68AyX.jpg","gif_url":"videos/1659-fY68AyX.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד בכל יד, כפות ידיים פונות לגוף וידיים ישרות לגמרי.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המשקולות תוך כיווץ הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину.","Возьмите по гантели в каждую руку ладонями к телу и полностью выпрямленными руками.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно напрягая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos.","Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0312","name":"dumbbell hammer curl v. 2","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0312-2NpxjC1.jpg","gif_url":"videos/0312-2NpxjC1.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות לגו.","שמרו על מרפקים צמודים לגו וסובבו את כפות הידיים עד שהן פונות קדימה.","זוהי נקודת ההתחלה שלכם.","כעת, תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המשקולות תוך כיווץ הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","לאחר מכן, שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות המומלץ."],"en":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"ru":["Встаньте прямо, возьмите в каждую руку по гантели, ладони обращены к туловищу.","Держите локти близко к туловищу и поворачивайте ладони рук так, чтобы они смотрели вперед.","Это будет ваша исходная позиция.","Теперь, удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Затем вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите рекомендованное количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.","Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.","Esta será tu posición inicial.","Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones recomendado."]}},{"id":"2402","name":"dumbbell hammer curls (with arm blaster)","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2402-GNhAeJ0.jpg","gif_url":"videos/2402-GNhAeJ0.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות לגו.","שמרו על מרפקים צמודים לגו וסובבו את כפות הידיים עד שהן פונות קדימה.","זוהי נקודת ההתחלה שלכם.","כעת, תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את המשקולות תוך כיווץ הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","לאחר מכן, שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות המומלץ."],"en":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"ru":["Встаньте прямо, возьмите в каждую руку по гантели, ладони обращены к туловищу.","Держите локти близко к туловищу и поворачивайте ладони рук так, чтобы они смотрели вперед.","Это будет ваша исходная позиция.","Теперь, удерживая плечо неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Затем вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите рекомендованное количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.","Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.","Esta será tu posición inicial.","Ahora, manteniendo el brazo superior quieto, exhala y flexiona los brazos contrayendo los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones recomendado."]}},{"id":"1664","name":"dumbbell high curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1664-qAmNMJY.jpg","gif_url":"videos/1664-qAmNMJY.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות קדימה.","שמרו על הזרועות העליונות ללא תזוזה וכופפו את המשקולות גבוה ככל האפשר תוך כיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, взяв в каждую руку по гантели ладонями вперед.","Держите плечи неподвижно и поднимайте гантели как можно выше, одновременно напрягая бицепсы.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.","Mantén los brazos superiores quietos y flexiona las mancuernas lo más alto posible contrayendo los bíceps.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3545","name":"dumbbell incline alternate press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/3545-TVdivgY.jpg","gif_url":"videos/3545-TVdivgY.gif","instruction_steps":{"he":["שבו על ספסל בשיפוע חיובי עם משקולת יד בכל יד, מונחות על הירכיים.","הישענו לאחור על הספסל והיעזרו בירכיים להרמת המשקולות לגובה הכתפיים, כפות ידיים פונות קדימה.","בהגיעכם לגובה הכתפיים, סובבו את שורשי כף היד כך שכפות הידיים פונות קדימה.","דחפו את המשקולות למעלה בעזרת החזה והכתפיים, עד יישור מלא של הידיים.","הורידו את המשקולות חזרה לנקודת ההתחלה, תוך שמירה על מרפקים כפופים מעט.","חזרו על התרגיל למספר החזרות הרצוי, לסירוגין בין הידיים."],"en":["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.","Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward.","Push the dumbbells up with your chest and shoulders, extending your arms fully.","Lower the dumbbells back down to the starting position, keeping your elbows slightly bent.","Repeat for the desired number of repetitions, alternating arms."],"ru":["Сядьте на наклонную скамью, взяв в каждую руку по гантели, положив их на бедра.","Откиньтесь на скамью и с помощью бедер поднимите гантели на высоту плеч, ладони смотрят вперед.","Оказавшись на высоте плеч, поверните запястья так, чтобы ладони были обращены вперед.","Поднимите гантели вверх грудью и плечами, полностью выпрямляя руки.","Опустите гантели обратно в исходное положение, слегка согнув локти.","Повторите желаемое количество повторений, чередуя руки."],"es":["Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos.","Recuéstate en el banco y usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.","Una vez a la altura de los hombros, gira las muñecas de modo que las palmas de las manos queden mirando hacia adelante.","Empuja las mancuernas hacia arriba con el pecho y los hombros, extendiendo completamente los brazos.","Baja las mancuernas de nuevo hasta la posición inicial, manteniendo los codos ligeramente flexionados.","Repite el número de repeticiones deseado, alternando los brazos."]}},{"id":"0314","name":"dumbbell incline bench press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0314-ns0SIbU.jpg","gif_url":"videos/0314-ns0SIbU.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שבו על הספסל עם כפות רגליים על הרצפה והגב צמוד היטב למשענת.","החזיקו משקולת יד בכל יד, כפות ידיים פונות קדימה, והרימו אותן לגובה הכתפיים.","הורידו באיטיות את המשקולות לצידי החזה, תוך שמירה על מרפקים בזווית של 90 מעלות.","דחפו את המשקולות חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench.","Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height.","Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Сядьте на скамью, поставьте ноги на землю и плотно прижмите спину к скамье.","Возьмите по гантели в каждую руку ладонями вперед и поднимите их на высоту плеч.","Медленно опустите гантели по бокам груди, держа локти под углом 90 градусов.","Верните гантели в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con los pies apoyados en el suelo y la espalda firmemente apoyada contra el banco.","Sostén una mancuerna en cada mano, con las palmas hacia adelante, y levántalas hasta la altura de los hombros.","Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.","Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0315","name":"dumbbell incline biceps curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0315-F3xgbjF.jpg","gif_url":"videos/0315-F3xgbjF.gif","instruction_steps":{"he":["שבו על ספסל בשיפוע חיובי עם משקולת יד בכל יד, כפות ידיים פונות קדימה, וידיים ישרות לגמרי.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на наклонную скамью, взяв в каждую руку по гантели, ладонями вперед и полностью выпрямив руки.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0316","name":"dumbbell incline breeding","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0316-B3Rxp6L.jpg","gif_url":"videos/0316-B3Rxp6L.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שבו על הספסל כשהגב צמוד לכרית וכפות הרגליים על הרצפה.","החזיקו משקולת יד בכל יד באחיזה עליונה, כפות ידיים פונות קדימה.","התחילו עם ידיים מתוחות לגמרי, ניצבות לרצפה.","הורידו את המשקולות באיטיות לצידי החזה, תוך שמירה על זווית של 90 מעלות במרפקים.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המשקולות חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing forward.","Start with your arms fully extended, perpendicular to the ground.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Сядьте на скамью, прислонившись спиной к подушке, а ступни поставьте на землю.","Возьмите по гантели в каждую руку хватом сверху, ладонями вперед.","Начните с полностью выпрямленных рук перпендикулярно земле.","Медленно опустите гантели по бокам груди, держа локти под углом 90 градусов.","Задержитесь на мгновение в нижней точке, затем верните гантели в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.","Sostén una mancuerna en cada mano con agarre prono, con las palmas hacia adelante.","Comienza con los brazos completamente extendidos, perpendiculares al suelo.","Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.","Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0318","name":"dumbbell incline curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0318-ae9UoXQ.jpg","gif_url":"videos/0318-ae9UoXQ.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות ושבו עליו עם משקולת יד בכל יד, כפות ידיים פונות קדימה.","השעינו את הזרועות העליונות על ספסל השיפוע ותנו למרפקים להשתלשל, עם ידיים ישרות לגמרי.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward.","Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов и сядьте на нее, взяв в каждую руку по гантели ладонями вперед.","Положите плечи на наклонную скамью и позвольте локтям свисать вниз, полностью выпрямляя руки.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adelante.","Apoya los brazos superiores en el banco inclinado y deja que los codos cuelguen hacia abajo, extendiendo completamente los brazos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0317","name":"dumbbell incline curl v. 2","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0317-RaflbWD.jpg","gif_url":"videos/0317-RaflbWD.gif","instruction_steps":{"he":["שבו על ספסל בשיפוע חיובי עם משקולת יד בכל יד, כפות ידיים פונות קדימה וידיים ישרות לגמרי.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на наклонную скамью, взяв в каждую руку по гантели, ладонями вперед и полностью выпрямленными руками.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0319","name":"dumbbell incline fly","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/0319-ESOd5Pl.jpg","gif_url":"videos/0319-ESOd5Pl.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שבו על הספסל עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","שכבו לאחור על הספסל ולחצו את המשקולות למעלה לנקודת ההתחלה, ישר מעל החזה.","הורידו את המשקולות לצדדים בקשת רחבה עד שתרגישו מתיחה בחזה.","עצרו לרגע, ואז כווצו את שרירי החזה להחזרת המשקולות למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set an incline bench to a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Сядьте на скамью, взяв в каждую руку по гантели, ладони обращены друг к другу.","Лягте на скамью и выжмите гантели в исходное положение, прямо над грудью.","Опускайте гантели в стороны по широкой дуге, пока не почувствуете растяжение в груди.","Сделайте паузу на мгновение, затем сожмите мышцы груди, чтобы вернуть гантели в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho.","Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1278","name":"dumbbell incline fly on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/1278-HYe1ZqR.jpg","gif_url":"videos/1278-HYe1ZqR.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שבו על כדור פיזיו והתגלגלו קדימה עד שהגב העליון נשען על ספסל השיפוע.","החזיקו משקולת יד בכל יד, כפות ידיים פונות זו לזו וידיים מתוחות מעל החזה.","הורידו את המשקולות לצדדים בקשת רחבה עד שתרגישו מתיחה בחזה.","עצרו לרגע, ואז כווצו את שרירי החזה להחזרת המשקולות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Sit on an exercise ball and roll forward until your upper back is resting on the incline bench.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Сядьте на мяч для упражнений и перекатитесь вперед, пока верхняя часть спины не окажется на наклонной скамье.","Возьмите в каждую руку по гантели, ладони обращены друг к другу, руки вытянуты над грудью.","Опускайте гантели в стороны по широкой дуге, пока не почувствуете растяжение в груди.","Сделайте паузу на мгновение, затем сожмите мышцы груди, чтобы вернуть гантели в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el banco inclinado.","Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho.","Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0320","name":"dumbbell incline hammer curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0320-ByX0WxV.jpg","gif_url":"videos/0320-ByX0WxV.gif","instruction_steps":{"he":["שבו על ספסל בשיפוע חיובי עם משקולת יד בכל יד, כפות ידיים פונות לגו וידיים ישרות לגמרי.","שמרו על הגב צמוד לספסל וכפות הרגליים על הרצפה.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המשקולות תוך כיווץ הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Keep your back against the bench and your feet flat on the floor.","While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на наклонную скамью, взяв в каждую руку по гантели, ладони обращены к туловищу, руки полностью выпрямлены.","Держите спину на скамье, а ноги на полу.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia el torso y los brazos completamente extendidos.","Mantén la espalda contra el banco y los pies apoyados en el suelo.","Manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0321","name":"dumbbell incline hammer press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0321-PG1kcIb.jpg","gif_url":"videos/0321-PG1kcIb.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות ושבו עליו עם משקולת יד בכל יד, מונחות על הירכיים.","שכבו על הספסל ומקמו את המשקולות בגובה הכתפיים, כפות ידיים פונות זו לזו.","לחצו את המשקולות למעלה והרחק מהגוף עד יישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.","Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.","Press the dumbbells up and away from your body until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов и сядьте на нее, держа в каждой руке по гантели, опираясь на бедра.","Лягте на скамью и расположите гантели на уровне плеч ладонями друг к другу.","Выжмите гантели вверх и в сторону от тела, пока руки полностью не выпрямятся.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, apoyadas sobre los muslos.","Recuéstate en el banco y coloca las mancuernas a la altura de los hombros con las palmas enfrentadas entre sí.","Empuja las mancuernas hacia arriba y alejándolas del cuerpo hasta que los brazos queden completamente extendidos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1618","name":"dumbbell incline hammer press on exercise ball","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1618-wkgnGfb.jpg","gif_url":"videos/1618-wkgnGfb.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","צעדו עם כפות הרגליים קדימה וגלגלו את הגוף מטה על הכדור עד שהראש, הצוואר והגב העליון נתמכים עליו.","החזיקו את המשקולות בגובה הכתפיים, מרפקים כפופים ופונים לצדדים.","לחצו את המשקולות למעלה ומעט פנימה, תוך שמירה על כפות ידיים פונות זו לזו.","יישרו את הידיים לגמרי, בכיווץ הטרייספס בנקודה העליונה של התנועה.","הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells up and slightly inward, keeping your palms facing each other.","Extend your arms fully, squeezing your triceps at the top of the movement.","Slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на гимнастический мяч, взяв в каждую руку по гантели, ладонями друг к другу.","Пройдите ногами вперед и катите тело вниз по мячу, пока ваша голова, шея и верхняя часть спины не окажутся на мяче.","Держите гантели на уровне плеч, локти согнуты и направлены в стороны.","Поднимите гантели вверх и слегка внутрь, держа ладони лицом друг к другу.","Полностью выпрямите руки, сжимая трицепсы в верхней точке движения.","Медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Camina con los pies hacia adelante y baja el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados.","Empuja las mancuernas hacia arriba y ligeramente hacia adentro, manteniendo las palmas enfrentadas entre sí.","Extiende completamente los brazos, contrayendo los tríceps en la parte superior del movimiento.","Baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0322","name":"dumbbell incline inner biceps curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0322-LCtQPn8.jpg","gif_url":"videos/0322-LCtQPn8.gif","instruction_steps":{"he":["שבו על ספסל בשיפוע חיובי עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","השעינו את הזרועות העליונות על הספסל, תנו למרפקים להשתלשל וכפות הידיים פונות קדימה.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an incline bench with a dumbbell in each hand, palms facing each other.","Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на наклонную скамью, взяв в каждую руку по гантели ладонями друг к другу.","Положите плечи на скамью так, чтобы локти свисали вниз, а ладони смотрели вперед.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Apoya los brazos superiores en el banco, permitiendo que los codos cuelguen hacia abajo y las palmas miren hacia adelante.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1279","name":"dumbbell incline one arm fly","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/1279-Gw2HFvW.jpg","gif_url":"videos/1279-Gw2HFvW.gif","instruction_steps":{"he":["כווננו את ספסל השיפוע לזווית של 30–45 מעלות.","שבו על הספסל עם משקולת יד ביד אחת, מונחת על הירך.","שכבו לאחור על הספסל, עם כפות רגליים על הרצפה.","החזיקו את המשקולת עם היד מתוחה ישר מעל החזה.","הורידו את המשקולת הצידה בקשת רחבה, עם כיפוף קל במרפק.","עצרו כשהיד מקבילה לרצפה, ואז הפכו את התנועה והחזירו את המשקולת לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Adjust the incline bench to a 30-45 degree angle.","Sit on the bench with a dumbbell in one hand, resting it on your thigh.","Lie back on the bench, keeping your feet flat on the ground.","Hold the dumbbell with your arm extended straight up over your chest.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Отрегулируйте наклон скамьи под углом 30-45 градусов.","Сядьте на скамью с гантелью в одной руке, положив ее на бедро.","Лягте на скамью, держа ноги на земле.","Держите гантель, вытянув руку прямо над грудью.","Опустите гантель в сторону по широкой дуге, сохраняя небольшой изгиб в локте.","Сделайте паузу, когда ваша рука окажется параллельна земле, затем выполните обратное движение, чтобы вернуть гантель в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ajusta el banco inclinado a un ángulo de 30-45 grados.","Siéntate en el banco con una mancuerna en una mano, apoyándola sobre el muslo.","Recuéstate en el banco, manteniendo los pies apoyados en el suelo.","Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho.","Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo.","Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento para llevar la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1280","name":"dumbbell incline one arm fly on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/1280-LLNh6q5.jpg","gif_url":"videos/1280-LLNh6q5.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם משקולת יד ביד אחת.","צעדו עם כפות הרגליים קדימה וגלגלו את הגוף מטה עד שהראש, הצוואר והגב העליון נתמכים על הכדור.","החזיקו את המשקולת עם היד מתוחה ישר מעל החזה, כף יד פונה פנימה.","הורידו את המשקולת באיטיות הצידה, עם כיפוף קל במרפק.","עצרו לרגע כשהיד מקבילה לרצפה.","הפעילו את שרירי החזה להחזרת המשקולת למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на гимнастический мяч с гантелью в одной руке.","Пройдите ногами вперед и перекатывайтесь вниз, пока голова, шея и верхняя часть спины не окажутся на мяче.","Держите гантель, вытянув руку вверх над грудью ладонью внутрь.","Медленно опустите гантель в сторону, сохраняя небольшой изгиб в локте.","Сделайте паузу на мгновение, когда ваша рука будет параллельна земле.","Задействуйте мышцы груди, чтобы вернуть гантель в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate sobre un balón de estabilidad con una mancuerna en una mano.","Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho, con la palma hacia adentro.","Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo.","Haz una pausa por un momento cuando el brazo esté paralelo al suelo.","Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1619","name":"dumbbell incline one arm hammer press","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"triceps","image":"images/1619-LL1UiTX.jpg","gif_url":"videos/1619-LL1UiTX.gif","instruction_steps":{"he":["שבו על ספסל בשיפוע חיובי עם משקולת יד ביד אחת, מונחת על הירך.","הישענו לאחור על הספסל והיעזרו בירך להרמת המשקולת לגובה הכתף.","סובבו את שורש כף היד כך שכף היד פונה פנימה, לכיוון הגוף.","לחצו את המשקולת למעלה והרחק מהגוף, עד יישור מלא של היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height.","Rotate your wrist so that your palm is facing inward, towards your body.","Press the dumbbell up and away from your body, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на наклонную скамью с гантелью в одной руке, положив ее на бедро.","Откиньтесь на скамью и с помощью бедра поднимите гантель до уровня плеч.","Поверните запястье так, чтобы ладонь была обращена внутрь, к телу.","Поднимите гантель вверх и от себя, полностью выпрямляя руку.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo.","Recuéstate en el banco y usa el muslo para ayudar a levantar la mancuerna hasta la altura de los hombros.","Gira la muñeca de modo que la palma quede mirando hacia adentro, hacia el cuerpo.","Empuja la mancuerna hacia arriba y alejándola del cuerpo, extendiendo completamente el brazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1620","name":"dumbbell incline one arm hammer press on exercise ball","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"triceps","image":"images/1620-jDnrkar.jpg","gif_url":"videos/1620-jDnrkar.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם משקולת יד ביד אחת.","צעדו עם כפות הרגליים קדימה וגלגלו את הגוף מטה עד שהראש, הצוואר והגב העליון נתמכים על הכדור.","החזיקו את המשקולת עם כף היד פונה פנימה והמרפק כפוף בזווית של 90 מעלות.","לחצו את המשקולת למעלה לכיוון התקרה, ביישור היד.","הורידו את המשקולת חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle.","Press the dumbbell up towards the ceiling, straightening your arm.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на гимнастический мяч с гантелью в одной руке.","Пройдите ногами вперед и перекатывайтесь вниз, пока голова, шея и верхняя часть спины не окажутся на мяче.","Держите гантель ладонью внутрь, а локоть согнут под углом 90 градусов.","Поднимите гантель к потолку, выпрямляя руку.","Опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate sobre un balón de estabilidad con una mancuerna en una mano.","Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Sostén la mancuerna con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados.","Empuja la mancuerna hacia el techo, estirando el brazo.","Baja la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0323","name":"dumbbell incline one arm lateral raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","triceps"],"target":"delts","image":"images/0323-aTNKZiC.jpg","gif_url":"videos/0323-aTNKZiC.gif","instruction_steps":{"he":["שבו על ספסל שיפוע עם משקולת יד ביד אחת, מונחת על הירך.","רכנו קדימה ומקמו את הזרוע העליונה כנגד החלק הפנימי של הירך.","הרימו את המשקולת הצידה, תוך שמירה על יד כפופה מעט וכף יד כלפי מטה.","המשיכו להרים עד שהיד מקבילה לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.","Lean forward and position your upper arm against the inside of your thigh.","Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down.","Continue lifting until your arm is parallel to the floor.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Сядьте на наклонную скамью с гантелью в одной руке, положив ее на бедро.","Наклонитесь вперед и прижмите плечо к внутренней стороне бедра.","Поднимите гантель в сторону, держа руку слегка согнутой и ладонью вниз.","Продолжайте поднимать, пока ваша рука не станет параллельна полу.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate en un banco inclinado con una mancuerna en una mano, apoyándola sobre el muslo.","Inclínate hacia adelante y coloca el brazo superior contra la parte interna del muslo.","Levanta la mancuerna hacia el lado, manteniendo el brazo ligeramente flexionado y la palma hacia abajo.","Continúa levantando hasta que el brazo quede paralelo al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"1281","name":"dumbbell incline one arm press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1281-rDAiRf9.jpg","gif_url":"videos/1281-rDAiRf9.gif","instruction_steps":{"he":["שבו על ספסל בשיפוע חיובי עם משקולת יד ביד אחת, מונחת על הירך.","שכבו על הספסל ומקמו את המשקולת בגובה הכתף, כף יד פונה קדימה.","לחצו את המשקולת כלפי מעלה ומעט פנימה, עד יישור מלא של היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Lie back on the bench and position the dumbbell at shoulder level, palm facing forward.","Press the dumbbell upward and slightly inward, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Сядьте на наклонную скамью с гантелью в одной руке, положив ее на бедро.","Лягте на скамью и расположите гантель на уровне плеч ладонью вперед.","Нажмите гантель вверх и слегка внутрь, полностью выпрямляя руку.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo.","Recuéstate en el banco y coloca la mancuerna a la altura del hombro, con la palma hacia adelante.","Empuja la mancuerna hacia arriba y ligeramente hacia adentro, extendiendo completamente el brazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"1282","name":"dumbbell incline one arm press on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1282-Bg5JKSH.jpg","gif_url":"videos/1282-Bg5JKSH.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם משקולת יד ביד אחת, כפות רגליים על הרצפה.","צעדו באיטיות עם כפות הרגליים קדימה, בגלגול הכדור עד שהראש, הצוואר והגב העליון נתמכים עליו.","החזיקו את המשקולת בגובה הכתף, כף יד פונה קדימה.","לחצו את המשקולת כלפי מעלה עד יישור מלא של היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.","Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbell at shoulder height with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Сядьте на гимнастический мяч с гантелью в одной руке, поставьте ступни на землю.","Медленно пройдите ногами вперед, перекатывая мяч до тех пор, пока ваша голова, шея и верхняя часть спины не окажутся на мяче.","Держите гантель на уровне плеч ладонью вперед.","Нажмите гантель вверх, пока рука полностью не выпрямится.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate sobre un balón de estabilidad con una mancuerna en una mano, con los pies apoyados en el suelo.","Camina lentamente con los pies hacia adelante, haciendo rodar el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Sostén la mancuerna a la altura del hombro con la palma hacia adelante.","Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0324","name":"dumbbell incline palm-in press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0324-OVLmUuL.jpg","gif_url":"videos/0324-OVLmUuL.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שבו על הספסל עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","נטעו את כפות הרגליים היטב על הרצפה ושמרו על הגב ישר וצמוד לספסל.","התחילו עם המשקולות בגובה הכתפיים, מרפקים כפופים וכפות ידיים פונות זו לזו.","לחצו את המשקולות למעלה והרחק מהגוף, עד יישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Plant your feet firmly on the ground and keep your back straight against the bench.","Start with the dumbbells at shoulder level, elbows bent and palms facing each other.","Press the dumbbells up and away from your body, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Сядьте на скамью, взяв в каждую руку по гантели, ладони обращены друг к другу.","Твердо поставьте ноги на землю и держите спину прямо, прислонившись к скамье.","Начните с гантелей на уровне плеч, локти согнуты, ладони обращены друг к другу.","Выжмите гантели вверх и в сторону от тела, полностью выпрямляя руки.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Planta los pies firmemente en el suelo y mantén la espalda recta contra el banco.","Comienza con las mancuernas a la altura de los hombros, con los codos flexionados y las palmas enfrentadas entre sí.","Empuja las mancuernas hacia arriba y alejándolas del cuerpo, extendiendo completamente los brazos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1283","name":"dumbbell incline press on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1283-bfiHMpI.jpg","gif_url":"videos/1283-bfiHMpI.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם משקולת יד בכל יד, כפות ידיים פונות קדימה.","צעדו באיטיות עם כפות הרגליים קדימה, בגלגול הגוף מטה על הכדור עד שהראש, הצוואר והגב העליון נתמכים עליו.","החזיקו את המשקולות בגובה הכתפיים, מרפקים כפופים ופונים לצדדים.","לחצו את המשקולות כלפי מעלה, עד יישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an exercise ball with a dumbbell in each hand, palms facing forward.","Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells upward, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч для упражнений, взяв в каждую руку по гантели ладонями вперед.","Медленно пройдите ногами вперед, катя тело вниз по мячу, пока ваша голова, шея и верхняя часть спины не окажутся на мяче.","Держите гантели на уровне плеч, локти согнуты и направлены в стороны.","Выжмите гантели вверх, полностью выпрямляя руки.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas hacia adelante.","Camina lentamente con los pies hacia adelante, bajando el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados.","Empuja las mancuernas hacia arriba, extendiendo completamente los brazos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0325","name":"dumbbell incline raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","triceps"],"target":"delts","image":"images/0325-nxW6BkN.jpg","gif_url":"videos/0325-nxW6BkN.gif","instruction_steps":{"he":["שבו על ספסל בשיפוע חיובי עם משקולת יד בכל יד, מונחות על הירכיים.","הישענו לאחור על הספסל והרימו את המשקולות לגובה הכתפיים, כפות ידיים פונות קדימה.","תוך שמירה על הגב צמוד לספסל, נשפו והרימו את המשקולות מעל הראש, עד יישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המשקולות באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward.","Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."],"ru":["Сядьте на наклонную скамью, взяв в каждую руку по гантели, положив их на бедра.","Откиньтесь на скамью и поднимите гантели на высоту плеч ладонями вперед.","Упираясь спиной в скамью, выдохните и поднимите гантели над головой, полностью выпрямляя руки.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантели обратно на высоту плеч.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos.","Recuéstate en el banco y levanta las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.","Manteniendo la espalda contra el banco, exhala y levanta las mancuernas por encima de la cabeza, extendiendo completamente los brazos.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"0326","name":"dumbbell incline rear lateral raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0326-vYk8lqw.jpg","gif_url":"videos/0326-vYk8lqw.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שבו על הספסל כשהחזה צמוד למשענת והחזיקו משקולת יד בכל יד.","מתחו את הידיים ישר כלפי מטה, כשכפות הידיים פונות זו לזו.","עם כיפוף קל במרפקים, הרימו את הידיים לצדדים עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and hold a dumbbell in each hand.","Extend your arms straight down with your palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Сядьте на скамью, прижав грудь к спинке, и возьмите в каждую руку по гантели.","Вытяните руки прямо вниз ладонями друг к другу.","Сохраняя небольшой изгиб в локтях, поднимите руки в стороны, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con el pecho contra el respaldo y sostén una mancuerna en cada mano.","Extiende los brazos rectos hacia abajo con las palmas enfrentadas entre sí.","Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0327","name":"dumbbell incline row","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0327-7vG5o25.jpg","gif_url":"videos/0327-7vG5o25.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","קחו משקולת יד בכל יד ושבו על הספסל כשהחזה צמוד לשיפוע.","יישרו את הידיים לגמרי, ותנו למשקולות להשתלשל ישר מטה מהכתפיים.","משכו את המשקולות למעלה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Grab a dumbbell in each hand and sit on the bench with your chest against the incline.","Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Возьмите в каждую руку по гантели и сядьте на скамью, прижав грудь к наклону.","Полностью выпрямите руки, позволяя гантелям свисать прямо с плеч.","Подтяните гантели к груди, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Toma una mancuerna en cada mano y siéntate en el banco con el pecho apoyado contra la inclinación.","Extiende completamente los brazos, dejando que las mancuernas cuelguen rectas hacia abajo desde los hombros.","Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0328","name":"dumbbell incline shoulder raise","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"deltoids","secondary_muscles":["deltoids","trapezius"],"target":"serratus anterior","image":"images/0328-6e2DcYX.jpg","gif_url":"videos/0328-6e2DcYX.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות ושבו עליו עם משקולת יד בכל יד, כפות ידיים כלפי מטה.","הניחו את המשקולות על הירכיים והישענו לאחור על הספסל.","היעזרו בירכיים להרמת המשקולות לגובה הכתפיים, ואז סובבו את שורשי כף היד כך שכפות הידיים פונות קדימה.","נשפו והרימו באיטיות את המשקולות מעל הראש, עם כיפוף קל במרפקים.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המשקולות באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.","Rest the dumbbells on your thighs and lean back onto the bench.","Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward.","Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов и сядьте на нее, взяв в каждую руку по гантели ладонями вниз.","Положите гантели на бедра и откиньтесь на скамью.","Используйте бедра, чтобы поднять гантели на высоту плеч, затем поверните запястья так, чтобы ладони были направлены вперед.","Выдохните и медленно поднимите гантели над головой, сохраняя небольшой изгиб в локтях.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантели обратно на высоту плеч.","Повторите необходимое количество повторений."],"es":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia abajo.","Apoya las mancuernas sobre los muslos y recuéstate en el banco.","Usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia adelante.","Exhala y levanta lentamente las mancuernas por encima de la cabeza, manteniendo una ligera flexión en los codos.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"0329","name":"dumbbell incline shrug","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0329-JymLInS.jpg","gif_url":"videos/0329-JymLInS.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות ושבו עליו עם משקולת יד בכל יד.","הניחו את כפות הרגליים על הרצפה ותנו לידיים להשתלשל ישר מטה, כפות ידיים פונות לגוף.","תוך שמירה על ידיים ישרות, משכו את הכתפיים למעלה לכיוון האוזניים גבוה ככל האפשר.","החזיקו את הכיווץ לרגע, ואז הורידו את הכתפיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.","Place your feet flat on the ground and let your arms hang straight down with your palms facing your body.","Keeping your arms straight, shrug your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов и сядьте на нее, взяв в каждую руку по гантели.","Поставьте ноги на землю и позвольте рукам свисать прямо вниз ладонями к телу.","Держа руки прямыми, поднимите плечи как можно выше к ушам.","Удерживайте напряжение на мгновение, затем медленно опустите плечи обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano.","Coloca los pies planos sobre el suelo y deja que los brazos cuelguen rectos hacia abajo con las palmas hacia el cuerpo.","Manteniendo los brazos rectos, encoge los hombros hacia las orejas lo más alto posible.","Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3542","name":"dumbbell incline t-raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/3542-jgbvVJ0.jpg","gif_url":"videos/3542-jgbvVJ0.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות ושבו עליו עם משקולת יד בכל יד, כפות ידיים פונות פנימה.","רכנו קדימה ותנו לידיים להשתלשל ישר מטה, ניצבות לרצפה.","תוך שמירה על ידיים ישרות, הרימו אותן לצדדים עד שהן מקבילות לרצפה, ביצירת צורת T עם הגוף.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward and let your arms hang straight down, perpendicular to the floor.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a 'T' shape with your body.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов и сядьте на нее, взяв в каждую руку по гантели ладонями внутрь.","Наклонитесь вперед и позвольте рукам свисать прямо вниз, перпендикулярно полу.","Держа руки прямыми, поднимите их в стороны, пока они не станут параллельны полу, образуя с телом Т-образную форму.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro.","Inclínate hacia adelante y deja que los brazos cuelguen rectos hacia abajo, perpendiculares al suelo.","Manteniendo los brazos rectos, levántalos hacia los lados hasta que queden paralelos al suelo, formando una 'T' con el cuerpo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0330","name":"dumbbell incline triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0330-OVIKwsd.jpg","gif_url":"videos/0330-OVIKwsd.gif","instruction_steps":{"he":["שבו על ספסל שיפוע עם משקולת יד בכל יד, כפות ידיים פונות פנימה.","מתחו את הידיים לגמרי מעל הראש, תוך שמירה על מרפקים קרובים לראש.","הורידו את המשקולות מאחורי הראש בכיפוף מרפקים, תוך שמירה על זרועות עליונות ללא תזוזה.","עצרו לרגע, ואז הרימו את המשקולות חזרה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an incline bench with a dumbbell in each hand, palms facing inwards.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then raise the dumbbells back to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"ru":["Сядьте на наклонную скамью, взяв в каждую руку по гантели ладонями внутрь.","Вытяните руки полностью над головой, держа локти близко к голове.","Опустите гантели за голову, согнув локти, сохраняя плечи неподвижными.","Сделайте паузу на мгновение, затем поднимите гантели обратно в исходное положение, вытянув руки.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adentro.","Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de la cabeza.","Baja las mancuernas detrás de la cabeza flexionando los codos, manteniendo los brazos superiores quietos.","Haz una pausa por un momento, luego levanta las mancuernas de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0331","name":"dumbbell incline twisted flyes","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0331-1PLE8e9.jpg","gif_url":"videos/0331-1PLE8e9.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות ושבו עליו עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","שכבו לאחור על הספסל ולחצו את המשקולות למעלה לנקודת ההתחלה, ישר מעל החזה, עם ידיים מתוחות.","הורידו את המשקולות לצדדים בקשת רחבה עד שתרגישו מתיחה בחזה.","תוך כדי הורדת המשקולות, סובבו את שורשי כף היד כך שכפות הידיים פונות קדימה בנקודה התחתונה של התנועה.","הפכו את התנועה והחזירו את המשקולות למעלה לנקודת ההתחלה, בכיווץ שרירי החזה יחד בנקודה העליונה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов и сядьте на нее, взяв в каждую руку по гантели, ладонями друг к другу.","Лягте на скамью и выжмите гантели в исходное положение прямо над грудью, вытянув руки.","Опускайте гантели в стороны по широкой дуге, пока не почувствуете растяжение в груди.","Опуская гантели, поворачивайте запястья так, чтобы ладони смотрели вперед в нижней части движения.","Сделайте обратное движение и верните гантели в исходное положение, сжимая мышцы груди вместе в верхней части.","Повторите необходимое количество повторений."],"es":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho, con los brazos extendidos.","Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento.","Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior.","Repite el número de repeticiones deseado."]}},{"id":"1733","name":"dumbbell incline two arm extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1733-U7D9Fx3.jpg","gif_url":"videos/1733-U7D9Fx3.gif","instruction_steps":{"he":["שבו על ספסל בשיפוע חיובי עם משקולת יד בכל יד, מונחות על הירכיים.","שכבו לאחור באיטיות על הספסל, תוך שמירה על המשקולות קרובות לחזה.","כשאתם שכובים לגמרי, מתחו את הידיים ישר לכיוון התקרה, עם כיפוף קל במרפקים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Slowly lie back on the bench, keeping the dumbbells close to your chest.","Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на наклонную скамью, взяв в каждую руку по гантели, положив их на бедра.","Медленно лягте на скамью, держа гантели близко к груди.","Как только вы полностью ляжете, вытяните руки прямо вверх к потолку, слегка согнутыми в локтях.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos.","Recuéstate lentamente en el banco, manteniendo las mancuernas cerca del pecho.","Una vez completamente recostado, extiende los brazos rectos hacia el techo, manteniendo los codos ligeramente flexionados.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3541","name":"dumbbell incline y-raise","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","rear deltoids"],"target":"upper back","image":"images/3541-PbzNu7c.jpg","gif_url":"videos/3541-PbzNu7c.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות ושבו עליו עם משקולת יד בכל יד, כפות ידיים פונות פנימה.","רכנו מעט קדימה ותנו לידיים להשתלשל ישר מטה, עם כיפוף קל במרפקים.","הרימו את הידיים לצדדים ולמעלה בצורת Y עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.","Raise your arms out to the sides and up in a Y shape until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов и сядьте на нее, взяв в каждую руку по гантели ладонями внутрь.","Слегка наклонитесь вперед и позвольте рукам свисать прямо вниз, сохраняя небольшой изгиб в локтях.","Поднимите руки в стороны и вверх в форме буквы Y, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro.","Inclínate ligeramente hacia adelante y deja que los brazos cuelguen rectos hacia abajo, manteniendo una ligera flexión en los codos.","Levanta los brazos hacia los lados y hacia arriba formando una Y hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0332","name":"dumbbell iron cross","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0332-cALkHHX.jpg","gif_url":"videos/0332-cALkHHX.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במשקולת יד בכל יד לצידי הגוף.","הרימו את הידיים לצדדים עד שהן מקבילות לרצפה, ביצירת צורת T עם הגוף.","עצרו לרגע, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.","Pause for a moment, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа по гантели в каждой руке по бокам.","Поднимите руки в стороны, пока они не станут параллельны земле, образуя с телом Т-образную форму.","Сделайте паузу на мгновение, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.","Levanta los brazos hacia los lados hasta que queden paralelos al suelo, formando una T con el cuerpo.","Haz una pausa por un momento, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0333","name":"dumbbell kickback","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0333-W6PxUkg.jpg","gif_url":"videos/0333-W6PxUkg.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","הצמידו את הזרועות העליונות לצידי הגוף, עם מרפקים כפופים בזווית של 90 מעלות.","יישרו את הידיים ישר לאחור, וכווצו את הטרייספס בנקודה העליונה של התנועה.","עצרו לרגע, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Поднесите плечи к бокам, согнув локти под углом 90 градусов.","Вытяните руки прямо назад, сжимая трицепсы в верхней точке движения.","Сделайте паузу на мгновение, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Acerca los brazos superiores a los costados, con los codos flexionados en un ángulo de 90 grados.","Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.","Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1734","name":"dumbbell kickbacks on exercise ball","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"triceps","image":"images/1734-cAvTaSg.jpg","gif_url":"videos/1734-cAvTaSg.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד בכל יד, כפות ידיים פונות פנימה וידיים כפופות בזווית של 90 מעלות.","יישרו את הידיים ישר לאחור, וכווצו את הטרייספס בנקודה העליונה של התנועה.","עצרו לרגע, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину.","Возьмите по гантели в каждую руку ладонями внутрь и согните руки под углом 90 градусов.","Вытяните руки прямо назад, сжимая трицепсы в верхней точке движения.","Сделайте паузу на мгновение, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados.","Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.","Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1660","name":"dumbbell kneeling bicep curl exercise ball","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1660-2JCuFTU.jpg","gif_url":"videos/1660-2JCuFTU.gif","instruction_steps":{"he":["כרעו על הרצפה עם כדור פיזיו לפניכם.","הניחו את המרפקים על כדור הפיזיו, והחזיקו משקולת יד בכל יד עם כפות ידיים כלפי מעלה.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המשקולות תוך כיווץ הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Kneel on the floor with an exercise ball in front of you.","Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте на колени на пол, положив перед собой мяч для упражнений.","Положите локти на гимнастический мяч, держа в каждой руке по гантели ладонями вверх.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно напрягая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Arrodíllate en el suelo con un balón de estabilidad frente a ti.","Coloca los codos sobre el balón de estabilidad, sosteniendo una mancuerna en cada mano con las palmas hacia arriba.","Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0334","name":"dumbbell lateral raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps"],"target":"delts","image":"images/0334-DsgkuIt.jpg","gif_url":"videos/0334-DsgkuIt.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד, כפות ידיים פונות לגוף.","שמרו על גב ישר והפעילו את שרירי הליבה.","הרימו את הידיים לצדדים עד שהן מקבילות לרצפה, תוך שמירה על כיפוף קל במרפקים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями к телу.","Держите спину прямо и задействуйте корпус.","Поднимите руки в стороны до тех пор, пока они не станут параллельны полу, сохраняя небольшой изгиб в локтях.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.","Mantén la espalda recta y activa el core.","Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0335","name":"dumbbell lateral to front raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","biceps"],"target":"delts","image":"images/0335-xMjBKwn.jpg","gif_url":"videos/0335-xMjBKwn.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במשקולת יד בכל יד עם כפות ידיים פונות לגוף.","שמרו על גב ישר והפעילו את שרירי הליבה.","הרימו את הידיים לצדדים עד שהן מקבילות לרצפה, עם כיפוף קל במרפקים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","לאחר מכן, הרימו את הידיים לפניכם עד שהן מקבילות לרצפה, שוב עם כיפוף קל במרפקים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите в каждой руке по гантели ладонями к телу.","Держите спину прямо и задействуйте корпус.","Поднимите руки в стороны до тех пор, пока они не станут параллельны земле, сохраняя небольшой изгиб в локтях.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Затем поднимите руки перед собой, пока они не станут параллельны земле, снова сохраняя небольшой изгиб в локтях.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo.","Mantén la espalda recta y activa el core.","Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Luego, levanta los brazos frente a ti hasta que queden paralelos al suelo, manteniendo nuevamente una ligera flexión en los codos.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0336","name":"dumbbell lunge","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0336-RRWFUcw.jpg","gif_url":"videos/0336-RRWFUcw.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד.","צעדו קדימה עם רגל ימין והורידו את הגוף לעמדת מספריים (לאנג').","שמרו על גב ישר וחזה מורם תוך כדי הירידה.","דחפו דרך עקב ימין כדי לחזור לנקודת ההתחלה.","חזרו על התנועה עם רגל שמאל.","החליפו רגליים לסירוגין למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up as you lower your body.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гантели.","Сделайте шаг вперед правой ногой, опуская тело в положение выпада.","При опускании тела держите спину прямо и грудь вверх.","Оттолкнитесь правой пяткой, чтобы вернуться в исходное положение.","Повторите с левой ногой.","Чередуйте ноги необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Mantén la espalda recta y el pecho erguido mientras bajas el cuerpo.","Empuja con el talón derecho para regresar a la posición inicial.","Repite con la pierna izquierda.","Alterna las piernas el número de repeticiones deseado."]}},{"id":"1658","name":"dumbbell lunge with bicep curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings"],"target":"biceps","image":"images/1658-Mz6lLcW.jpg","gif_url":"videos/1658-Mz6lLcW.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד בכל יד עם כפות ידיים פונות קדימה.","צעדו קדימה עם רגל ימין והורידו את הגוף לעמדת מספריים. ברך ימין צריכה להיות כפופה בזווית של 90 מעלות וברך שמאל מרחפת מעט מעל הרצפה.","תוך כדי הצעד קדימה, כופפו בו-זמנית את המשקולות לכיוון הכתפיים, תוך שמירה על מרפקים צמודים לגוף.","עצרו לרגע בנקודה התחתונה של המספריים, ואז דחפו דרך עקב ימין לחזרה לנקודת ההתחלה, בהורדת המשקולות חזרה לצידי הגוף.","חזרו על המספריים וכפיפת הבייספס בצד הנגדי, בצעד קדימה עם רגל שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.","As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.","Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.","Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, держа в каждой руке по гантели ладонями вперед.","Сделайте шаг вперед правой ногой, опуская тело в положение выпада. Правое колено должно быть согнуто под углом 90 градусов, а левое колено должно парить над землей.","Делая выпад вперед, одновременно подтягивайте гантели к плечам, держа локти близко к телу.","Задержитесь на мгновение в нижней части выпада, затем оттолкнитесь правой пяткой, чтобы вернуться в исходное положение, опуская гантели обратно в стороны.","Повторите выпад и сгибание бицепса на противоположной стороне, шагнув вперед левой ногой.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. La rodilla derecha debe quedar flexionada en un ángulo de 90 grados y la rodilla izquierda debe quedar justo por encima del suelo.","Mientras avanzas en la zancada, flexiona simultáneamente las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo.","Haz una pausa por un momento en la parte baja de la zancada, luego empuja con el talón derecho para volver a la posición inicial, bajando las mancuernas de nuevo a los costados.","Repite la zancada y el curl de bíceps en el lado opuesto, dando un paso adelante con el pie izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0337","name":"dumbbell lying extension (across face)","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0337-L2V5Nan.jpg","gif_url":"videos/0337-L2V5Nan.gif","instruction_steps":{"he":["שכבו על ספסל עם כפות רגליים על הרצפה והראש בקצה הספסל.","החזיקו משקולת יד בשתי הידיים ומתחו את הידיים ישר מעל החזה, כפות ידיים פונות זו לזו.","תוך שמירה על הזרועות העליונות ללא תזוזה, הורידו באיטיות את המשקולת בקשת מאחורי הראש עד שהאמות מקבילות לרצפה.","עצרו לרגע, ואז כווצו את הטרייספס להחזרת המשקולת לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.","Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.","Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Возьмите гантель обеими руками и вытяните руки прямо над грудью ладонями друг к другу.","Удерживая плечи неподвижно, медленно опустите гантель по дуге за голову, пока предплечья не станут параллельны земле.","Сделайте паузу на мгновение, затем напрягите трицепс, чтобы вернуть гантель в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho, con las palmas enfrentadas entre sí.","Manteniendo los brazos superiores quietos, baja lentamente la mancuerna describiendo un arco detrás de la cabeza hasta que los antebrazos queden paralelos al suelo.","Haz una pausa por un momento, luego contrae los tríceps para llevar la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1729","name":"dumbbell lying alternate extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1729-NfP83rA.jpg","gif_url":"videos/1729-NfP83rA.gif","instruction_steps":{"he":["שכבו על ספסל עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","מתחו את הידיים ישר מעל החזה, עם כיפוף קל במרפקים.","הורידו משקולת אחת לכיוון הראש בכיפוף המרפק, תוך שמירה על היד השנייה מתוחה.","עצרו לרגע בנקודה התחתונה, ואז הרימו את המשקולת חזרה למעלה לנקודת ההתחלה.","חזרו על התנועה עם היד השנייה, לסירוגין בין הצדדים למספר החזרות הרצוי."],"en":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.","Pause for a moment at the bottom, then raise the dumbbell back up to the starting position.","Repeat with the other arm, alternating sides for the desired number of repetitions."],"ru":["Лягте на скамью, взяв в каждую руку по гантели, ладони обращены друг к другу.","Вытяните руки прямо вверх над грудью, сохраняя небольшой изгиб в локтях.","Опустите одну гантель к голове, сгибая в локте, сохраняя при этом другую руку вытянутой.","Задержитесь на мгновение в нижней точке, затем поднимите гантель обратно в исходное положение.","Повторите то же самое с другой рукой, чередуя стороны, необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.","Baja una mancuerna hacia la cabeza, flexionando el codo, mientras mantienes el otro brazo extendido.","Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial.","Repite con el otro brazo, alternando lados el número de repeticiones deseado."]}},{"id":"0338","name":"dumbbell lying elbow press","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0338-eOCOwIR.jpg","gif_url":"videos/0338-eOCOwIR.gif","instruction_steps":{"he":["שכבו על ספסל עם משקולת יד בכל יד, כפות ידיים פונות זו לזו וידיים מתוחות ישר מעל החזה.","הורידו את המשקולות לכיוון הכתפיים בכיפוף מרפקים, תוך שמירה על זרועות עליונות ללא תזוזה.","עצרו לרגע בנקודה התחתונה, ואז לחצו את המשקולות חזרה למעלה לנקודת ההתחלה ביישור המרפקים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.","Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, взяв в каждую руку по гантели, ладони обращены друг к другу, руки вытянуты прямо над грудью.","Опустите гантели к плечам, сгибая локти, сохраняя плечи неподвижными.","Задержитесь на мгновение в нижней точке, затем верните гантели в исходное положение, разгибая локти.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho.","Baja las mancuernas hacia los hombros flexionando los codos, manteniendo los brazos superiores quietos.","Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial extendiendo los codos.","Repite el número de repeticiones deseado."]}},{"id":"0863","name":"dumbbell lying external shoulder rotation","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"rotator cuff","secondary_muscles":["rotator cuff","triceps"],"target":"delts","image":"images/0863-bmBf7LN.jpg","gif_url":"videos/0863-bmBf7LN.gif","instruction_steps":{"he":["שכבו על הצד על ספסל ישר, כשהזרוע העליונה צמודה לגוף והמרפק כפוף בזווית של 90 מעלות.","החזיקו משקולת יד ביד, כף יד כלפי מטה.","תוך שמירה על הזרוע העליונה צמודה לגוף, סובבו באיטיות את האמה כלפי מעלה רחוק ככל האפשר.","עצרו לרגע בנקודה העליונה, ואז הורידו את האמה באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.","Hold a dumbbell in your hand with your palm facing down.","Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Лягте на бок на ровную скамью, прижав плечо к боку и согнув локоть на 90 градусов.","Возьмите в руку гантель ладонью вниз.","Прижимая плечо к боку, медленно поверните предплечье вверх как можно дальше.","Задержитесь на мгновение в верхней точке, затем медленно опустите предплечье обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Túmbate de lado en un banco plano con el brazo superior contra el costado y el codo flexionado a 90 grados.","Sostén una mancuerna en la mano con la palma hacia abajo.","Manteniendo el brazo superior contra el costado, gira lentamente el antebrazo hacia arriba lo más posible.","Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0339","name":"dumbbell lying femoral","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"glutes","secondary_muscles":["glutes"],"target":"hamstrings","image":"images/0339-FkBIE6a.jpg","gif_url":"videos/0339-FkBIE6a.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות ומשקולת יד מונחת על הבטן התחתונה.","כופפו ברכיים והביאו את המשקולת לכיוון הישבן, תוך שמירה על כפות רגליים על הרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.","Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, вытянув ноги и положив гантель на нижнюю часть живота.","Согните ноги в коленях и поднесите гантель к ягодицам, удерживая ступни на земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba con las piernas extendidas y una mancuerna apoyada sobre el abdomen bajo.","Flexiona las rodillas y lleva la mancuerna hacia los glúteos, manteniendo los pies apoyados en el suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0340","name":"dumbbell lying hammer press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0340-7gdLIXa.jpg","gif_url":"videos/0340-7gdLIXa.gif","instruction_steps":{"he":["שכבו על ספסל עם משקולת יד בכל יד, כפות ידיים פונות זו לזו וידיים מתוחות ישר למעלה.","הורידו את המשקולות לצידי החזה, תוך שמירה על מרפקים בזווית של 90 מעלות.","לחצו את המשקולות חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.","Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, взяв в каждую руку по гантели, ладони обращены друг к другу, руки вытянуты вверх.","Опустите гантели по бокам груди, держа локти под углом 90 градусов.","Верните гантели в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba.","Baja las mancuernas a los lados del pecho, manteniendo los codos en un ángulo de 90 grados.","Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"2470","name":"dumbbell lying on floor rear delt raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/2470-Ion0XWz.jpg","gif_url":"videos/2470-Ion0XWz.gif","instruction_steps":{"he":["שכבו על הבטן על הרצפה עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","מתחו את הידיים ישר לפניכם, עם כיפוף קל במרפקים.","תוך הפעלת שרירי הכתפיים, הרימו את הידיים למעלה ולצדדים, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie face down on the floor with a dumbbell in each hand, palms facing each other.","Extend your arms straight out in front of you, keeping a slight bend in your elbows.","Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на пол лицом вниз, возьмите в каждую руку по гантели, ладони обращены друг к другу.","Вытяните руки прямо перед собой, сохраняя небольшой изгиб в локтях.","Задействуя мышцы плеч, поднимите руки вверх и в стороны, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo en el suelo con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende los brazos rectos frente a ti, manteniendo una ligera flexión en los codos.","Activando los músculos de los hombros, levanta los brazos hacia arriba y hacia los lados, juntando los omóplatos.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0341","name":"dumbbell lying one arm deltoid rear","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0341-gSw59a4.jpg","gif_url":"videos/0341-gSw59a4.gif","instruction_steps":{"he":["שכבו על הבטן על ספסל ישר עם משקולת יד ביד אחת, כף יד פונה פנימה.","מתחו את היד ישר מטה לכיוון הרצפה, כשהיא קרובה לגוף.","הרימו את היד למעלה ולאחור, בכיווץ השכמה לכיוון עמוד השדרה.","עצרו לרגע בנקודה העליונה, ואז הורידו את היד באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.","Extend your arm straight down towards the floor, keeping it close to your body.","Raise your arm up and back, squeezing your shoulder blade towards your spine.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Лягте лицом вниз на плоскую скамью с гантелью в одной руке ладонью внутрь.","Вытяните руку прямо вниз к полу, держа ее близко к телу.","Поднимите руку вверх и назад, прижимая лопатку к позвоночнику.","Задержитесь на мгновение в верхней точке, затем медленно опустите руку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia adentro.","Extiende el brazo recto hacia el suelo, manteniéndolo cerca del cuerpo.","Levanta el brazo hacia arriba y hacia atrás, acercando el omóplato hacia la columna.","Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0343","name":"dumbbell lying one arm press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0343-zGSIWQi.jpg","gif_url":"videos/0343-zGSIWQi.gif","instruction_steps":{"he":["שכבו על ספסל עם משקולת יד ביד אחת וכפות רגליים על הרצפה.","החזיקו את המשקולת בגובה הכתף, עם כף יד פונה קדימה.","לחצו את המשקולת כלפי מעלה עד יישור מלא של היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.","Hold the dumbbell at shoulder level with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Лягте на скамью с гантелью в одной руке, поставив ноги на землю.","Держите гантель на уровне плеч ладонью вперед.","Нажмите гантель вверх, пока рука полностью не выпрямится.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Túmbate boca arriba en un banco con una mancuerna en una mano y los pies apoyados en el suelo.","Sostén la mancuerna a la altura del hombro con la palma hacia adelante.","Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0342","name":"dumbbell lying one arm press v. 2","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0342-K3dIO25.jpg","gif_url":"videos/0342-K3dIO25.gif","instruction_steps":{"he":["שכבו על ספסל כשהגב נתמך וכפות הרגליים על הרצפה.","החזיקו משקולת יד ביד אחת, כשכף היד פונה לכיוון כפות הרגליים.","מתחו את היד ישר למעלה לכיוון התקרה, עם כיפוף קל במרפק.","הורידו את המשקולת באיטיות לכיוון החזה, תוך שמירה על מרפק קרוב לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המשקולת חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Lie flat on a bench with your back supported and feet flat on the ground.","Hold a dumbbell in one hand with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.","Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Лягте на скамью, поддерживая спину и поставив ступни на землю.","Возьмите гантель в одну руку ладонью к ногам.","Вытяните руку прямо вверх к потолку, слегка согнув локоть.","Медленно опустите гантель к груди, держа локоть близко к телу.","Задержитесь на мгновение в нижней точке, затем верните гантель в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Túmbate boca arriba en un banco con la espalda apoyada y los pies planos sobre el suelo.","Sostén una mancuerna en una mano con la palma hacia los pies.","Extiende el brazo recto hacia el techo, manteniendo el codo ligeramente flexionado.","Baja lentamente la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo.","Haz una pausa por un momento en la parte inferior, luego empuja la mancuerna de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0344","name":"dumbbell lying one arm pronated triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0344-wyaqzOS.jpg","gif_url":"videos/0344-wyaqzOS.gif","instruction_steps":{"he":["שכבו על ספסל עם הגב והראש נתמכים, וכפות הרגליים על הרצפה.","החזיקו משקולת יד ביד אחת עם כף יד כלפי מטה, ומתחו את היד ישר מעל הכתף.","תוך שמירה על הזרוע העליונה ללא תזוזה, הורידו באיטיות את המשקולת מאחורי הראש בכיפוף המרפק.","עצרו לרגע בנקודה התחתונה, ואז יישרו את היד חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Лягте на скамью, поддерживая спину и голову, а ноги поставьте на землю.","Возьмите гантель в одну руку ладонью вниз и вытяните руку прямо над плечом.","Удерживая плечо неподвижно, медленно опустите гантель за голову, сгибая локоть.","Задержитесь на мгновение в нижней точке, затем вытяните руку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo.","Sostén una mancuerna en una mano con la palma hacia abajo, y extiende el brazo recto por encima del hombro.","Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo.","Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0345","name":"dumbbell lying one arm rear lateral raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0345-KwFGiEP.jpg","gif_url":"videos/0345-KwFGiEP.gif","instruction_steps":{"he":["שכבו על הבטן על ספסל ישר עם משקולת יד ביד אחת, משתלשלת לכיוון הרצפה.","שמרו על יד ישרה והרימו את המשקולת הצידה, הרחק מהגוף.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor.","Keep your arm straight and lift the dumbbell out to the side, away from your body.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Лягте лицом вниз на ровную скамью с гантелью в одной руке, свисающей к полу.","Держите руку прямо и поднимите гантель в сторону, подальше от тела.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Túmbate boca abajo en un banco plano con una mancuerna en una mano, colgando hacia el suelo.","Mantén el brazo recto y levanta la mancuerna hacia el lado, alejándola del cuerpo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0346","name":"dumbbell lying one arm supinated triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0346-zZlORz6.jpg","gif_url":"videos/0346-zZlORz6.gif","instruction_steps":{"he":["שכבו על ספסל עם הגב והראש נתמכים, וכפות הרגליים על הרצפה.","החזיקו משקולת יד ביד אחת באחיזה תחתונה, ומתחו את היד ישר מעל הכתף.","תוך שמירה על הזרוע העליונה ללא תזוזה, הורידו באיטיות את המשקולת מאחורי הראש בכיפוף המרפק.","עצרו לרגע בנקודה התחתונה, ואז יישרו את היד חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Лягте на скамью, поддерживая спину и голову, а ноги поставьте на землю.","Возьмите гантель в одну руку обратным хватом и вытяните руку прямо над плечом.","Удерживая плечо неподвижно, медленно опустите гантель за голову, сгибая локоть.","Задержитесь на мгновение в нижней точке, затем вытяните руку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo.","Sostén una mancuerna en una mano con agarre supino, y extiende el brazo recto por encima del hombro.","Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo.","Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0347","name":"dumbbell lying pronation","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/0347-mym4hJo.jpg","gif_url":"videos/0347-mym4hJo.gif","instruction_steps":{"he":["שכבו על הבטן על ספסל ישר עם הידיים מתוחות ישר מטה, אוחזים משקולת יד בכל יד.","סובבו את כפות הידיים כך שהן פונות כלפי מעלה.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המשקולות תוך סיבוב כפות הידיים כלפי מטה.","שאפו והורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.","Rotate your palms so they are facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down.","Inhale and slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью грудью вниз и вытяните руки вниз, держа в каждой руке по гантели.","Поверните ладони так, чтобы они были направлены вверх.","Удерживая плечи неподвижно, выдохните и согните гантели, поворачивая ладони лицом вниз.","Вдохните и медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo en un banco con el pecho hacia abajo y los brazos extendidos rectos hacia abajo, sosteniendo una mancuerna en cada mano.","Gira las palmas de modo que queden mirando hacia arriba.","Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas mientras giras las palmas hacia abajo.","Inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2705","name":"dumbbell lying pronation on floor","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"forearms","image":"images/2705-7RWNjiB.jpg","gif_url":"videos/2705-7RWNjiB.gif","instruction_steps":{"he":["שכבו על הבטן על הרצפה עם ידיים מתוחות ישר לפניכם, אוחזים משקולת יד בכל יד.","סובבו את כפות הידיים כך שהן פונות מטה לכיוון הרצפה.","תוך שמירה על ידיים ישרות, הרימו את המשקולות מהרצפה בכיווץ האמות.","המשיכו להרים עד שהאמות מכווצות במלואן והמשקולות בגובה הכתפיים.","החזיקו לרגע, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.","Rotate your palms so they are facing down towards the floor.","Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms.","Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.","Hold for a moment, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на пол лицом вниз и вытяните руки прямо перед собой, держа в каждой руке по гантели.","Поверните ладони так, чтобы они были направлены вниз к полу.","Держа руки прямыми, поднимите гантели от пола, напрягая предплечья.","Продолжайте поднимать до тех пор, пока предплечья не сократятся полностью и гантели не окажутся на уровне плеч.","Задержитесь на мгновение, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo en el suelo con los brazos extendidos rectos frente a ti, sosteniendo una mancuerna en cada mano.","Gira las palmas de modo que queden mirando hacia el suelo.","Manteniendo los brazos rectos, levanta las mancuernas del suelo contrayendo los antebrazos.","Continúa levantando hasta que los antebrazos estén completamente contraídos y las mancuernas queden a la altura de los hombros.","Mantén la posición por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1284","name":"dumbbell lying pullover on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","back"],"target":"pectorals","image":"images/1284-iK59oEA.jpg","gif_url":"videos/1284-iK59oEA.gif","instruction_steps":{"he":["שבו על כדור פיזיו והתגלגלו קדימה עד שהגב העליון נשען על הכדור.","החזיקו משקולת יד בשתי הידיים ומתחו את הידיים ישר מעל החזה.","הורידו באיטיות את המשקולת מאחורי הראש תוך שמירה על ידיים ישרות.","עצרו לרגע, ואז הרימו את המשקולת חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an exercise ball and roll forward until your upper back is resting on the ball.","Hold a dumbbell with both hands and extend your arms straight up over your chest.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч для упражнений и перекатывайтесь вперед, пока верхняя часть спины не окажется на мяче.","Возьмите гантель обеими руками и вытяните руки прямо над грудью.","Медленно опустите гантель за голову, сохраняя руки прямыми.","Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el balón.","Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho.","Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1328","name":"dumbbell lying rear delt row","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","biceps"],"target":"upper back","image":"images/1328-XUUD0Fs.jpg","gif_url":"videos/1328-XUUD0Fs.gif","instruction_steps":{"he":["שכבו על הבטן על ספסל ישר עם משקולת יד בכל יד, כפות ידיים פונות פנימה.","מתחו את הידיים ישר כלפי הרצפה, עם כיפוף קל במרפקים.","תוך הפעלת שרירי הגב, הרימו את המשקולות לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.","Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте лицом вниз на плоскую скамью, взяв в каждую руку по гантели ладонями внутрь.","Вытяните руки прямо вниз к полу, сохраняя небольшой изгиб в локтях.","Задействуя мышцы спины, поднимите гантели к груди, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas hacia adentro.","Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos.","Activando los músculos de la espalda, levanta las mancuernas hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0348","name":"dumbbell lying rear lateral raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0348-53Ttlck.jpg","gif_url":"videos/0348-53Ttlck.gif","instruction_steps":{"he":["שכבו על הבטן על ספסל ישר עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","מתחו את הידיים ישר כלפי הרצפה, עם כיפוף קל במרפקים.","תוך הפעלת שרירי הכתפיים, הרימו את הידיים לצדדים עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте лицом вниз на плоскую скамью, взяв в каждую руку по гантели, ладони обращены друг к другу.","Вытяните руки прямо вниз к полу, сохраняя небольшой изгиб в локтях.","Задействуя мышцы плеч, поднимите руки в стороны, пока они не станут параллельны полу.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos.","Activando los músculos de los hombros, levanta los brazos hacia los lados hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1735","name":"dumbbell lying single extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1735-6MfS53i.jpg","gif_url":"videos/1735-6MfS53i.gif","instruction_steps":{"he":["שכבו על ספסל עם משקולת יד ביד אחת והיד מתוחה לגמרי מעל החזה.","הורידו את המשקולת בשליטה לכיוון המצח, תוך שמירה על הזרוע העליונה ללא תזוזה.","עצרו קצרות בנקודה התחתונה של התנועה, ואז יישרו את היד חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.","Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary.","Pause briefly at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Лягте на скамью, возьмите в одну руку гантель и полностью вытяните руку над грудью.","Контролируемо опустите гантель ко лбу, сохраняя плечо неподвижным.","Сделайте короткую паузу в конце движения, затем вытяните руку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Túmbate boca arriba en un banco con una mancuerna en una mano y el brazo completamente extendido por encima del pecho.","Baja la mancuerna de manera controlada hacia la frente, manteniendo el brazo superior quieto.","Haz una breve pausa en la parte inferior del movimiento, luego extiende el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0349","name":"dumbbell lying supination","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/0349-M2Pm3zj.jpg","gif_url":"videos/0349-M2Pm3zj.gif","instruction_steps":{"he":["שכבו על ספסל עם כפות רגליים על הרצפה.","החזיקו משקולת יד בכל יד, כפות ידיים כלפי מעלה וידיים ישרות לגמרי.","תוך שמירה על הזרועות העליונות ללא תזוזה, כופפו את המשקולות לכיוון הכתפיים בכיווץ האמות.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив ноги на землю.","Возьмите по гантели в каждую руку ладонями вверх и полностью выпрямите руки.","Удерживая плечи неподвижно, согните гантели к плечам, напрягая предплечья.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo.","Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo los brazos superiores quietos, flexiona las mancuernas hacia los hombros contrayendo los antebrazos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2706","name":"dumbbell lying supination on floor","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/2706-rEhi2o5.jpg","gif_url":"videos/2706-rEhi2o5.gif","instruction_steps":{"he":["שכבו על הגב על הרצפה עם רגליים ישרות וידיים לצידי הגוף, אוחזים משקולת יד בכל יד.","סובבו את כפות הידיים כלפי מעלה, תוך שמירה על מרפקים צמודים לצידי הגוף.","כופפו באיטיות את המשקולות לכיוון הכתפיים, בכיווץ האמות.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.","Rotate your palms to face up, keeping your elbows close to your sides.","Slowly curl the dumbbells towards your shoulders, squeezing your forearms.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину на пол, вытянув ноги и положив руки по бокам, держа в каждой руке по гантели.","Поверните ладони вверх, держа локти близко к бокам.","Медленно поднимите гантели к плечам, сжимая предплечья.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en el suelo con las piernas extendidas y los brazos a los costados, sosteniendo una mancuerna en cada mano.","Gira las palmas hacia arriba, manteniendo los codos cerca de los costados.","Flexiona lentamente las mancuernas hacia los hombros, contrayendo los antebrazos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1661","name":"dumbbell lying supine biceps curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1661-XVzF3iZ.jpg","gif_url":"videos/1661-XVzF3iZ.gif","instruction_steps":{"he":["שכבו על ספסל עם הגב והראש נתמכים, וכפות הרגליים על הרצפה.","החזיקו משקולת יד בכל יד, כפות ידיים כלפי מעלה וידיים ישרות לגמרי.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поддерживая спину и голову, а ноги поставьте на землю.","Возьмите по гантели в каждую руку ладонями вверх и полностью выпрямите руки.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo.","Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0350","name":"dumbbell lying supine curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0350-KUaZst7.jpg","gif_url":"videos/0350-KUaZst7.gif","instruction_steps":{"he":["שכבו על ספסל עם משקולת יד בכל יד, כפות ידיים כלפי מעלה וידיים ישרות לגמרי.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, взяв в каждую руку по гантели, ладонями вверх и полностью выпрямив руки.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0351","name":"dumbbell lying triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0351-mpKZGWz.jpg","gif_url":"videos/0351-mpKZGWz.gif","instruction_steps":{"he":["שכבו על ספסל עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","מתחו את הידיים ישר מעל החזה, תוך שמירה על מרפקים קרובים לגוף.","הורידו את המשקולות לכיוון המצח, בכיפוף מרפקים.","עצרו לרגע, ואז יישרו את הידיים חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping your elbows close to your body.","Lower the dumbbells down towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, взяв в каждую руку по гантели, ладони обращены друг к другу.","Вытяните руки прямо вверх над грудью, держа локти близко к телу.","Опустите гантели ко лбу, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende los brazos rectos hacia arriba sobre el pecho, manteniendo los codos cerca del cuerpo.","Baja las mancuernas hacia la frente, flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1662","name":"dumbbell lying wide curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1662-qm9veZw.jpg","gif_url":"videos/1662-qm9veZw.gif","instruction_steps":{"he":["שכבו על ספסל עם משקולת יד בכל יד, כפות ידיים כלפי מעלה וידיים ישרות לגמרי.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, взяв в каждую руку по гантели, ладонями вверх и полностью выпрямив руки.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0352","name":"dumbbell neutral grip bench press","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0352-pP8wP2P.jpg","gif_url":"videos/0352-pP8wP2P.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","החזיקו משקולת יד בכל יד באחיזה ניטרלית (כפות ידיים פונות זו לזו) וידיים מתוחות ישר מעל החזה.","הורידו באיטיות את המשקולות לכיוון החזה, תוך שמירה על מרפקים קרובים לגוף.","עצרו לרגע בנקודה התחתונה, ואז לחצו את המשקולות חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.","Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите по гантели в каждую руку нейтральным хватом (ладони обращены друг к другу), вытянув руки прямо вверх над грудью.","Медленно опустите гантели вниз к груди, держа локти близко к телу.","Задержитесь на мгновение в нижней точке, затем верните гантели в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Sostén una mancuerna en cada mano con agarre neutro (palmas enfrentadas entre sí) y los brazos extendidos rectos hacia arriba sobre el pecho.","Baja lentamente las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1285","name":"dumbbell one arm bench fly","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/1285-o5Jsk92.jpg","gif_url":"videos/1285-o5Jsk92.gif","instruction_steps":{"he":["שבו על ספסל ישר עם משקולת יד ביד אחת, מונחת על הירך.","שכבו לאחור על הספסל, תוך שמירה על המשקולת צמודה לירך.","בעזרת היד הפנויה, סייעו בהרמת המשקולת לנקודת ההתחלה.","החזיקו את המשקולת ישר מעל הכתף, עם היד מתוחה וכף היד פונה פנימה.","הורידו את המשקולת הצידה בקשת רחבה, עם כיפוף קל במרפק.","עצרו כשהיד מקבילה לרצפה, ואז הפכו את התנועה והחזירו את המשקולת לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים וחזרו."],"en":["Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.","Lie back on the bench, keeping the dumbbell pressed against your thigh.","Using your free hand, help lift the dumbbell up to the starting position.","Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."],"ru":["Сядьте на ровную скамью с гантелью в одной руке, положив ее на бедро.","Лягте на скамью, прижав гантель к бедру.","Свободной рукой помогите поднять гантель в исходное положение.","Держите гантель прямо над плечом, вытянув руку ладонью внутрь.","Опустите гантель в сторону по широкой дуге, сохраняя небольшой изгиб в локте.","Сделайте паузу, когда ваша рука окажется параллельна земле, затем поменяйте направление движения и верните гантель в исходное положение.","Повторите необходимое количество повторений, затем поменяйте руки и повторите."],"es":["Siéntate en un banco plano con una mancuerna en una mano, apoyándola sobre el muslo.","Recuéstate en el banco, manteniendo la mancuerna presionada contra el muslo.","Usando la mano libre, ayuda a levantar la mancuerna hasta la posición inicial.","Sostén la mancuerna directamente sobre el hombro con el brazo extendido y la palma hacia adentro.","Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo.","Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento y lleva la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo y repite."]}},{"id":"0292","name":"dumbbell one arm bent-over row","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0292-C0MA9bC.jpg","gif_url":"videos/0292-C0MA9bC.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד ביד אחת עם כף יד פונה לגוף.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וליבה מופעלת.","תנו למשקולת להשתלשל ישר מטה לכיוון הרצפה, עם יד ישרה לגמרי.","משכו את המשקולת למעלה לכיוון החזה, תוך שמירה על מרפק קרוב לגוף וכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down towards the floor, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, держите гантель в одной руке ладонью к телу.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой и напряженный корпус.","Пусть гантель свисает прямо к полу, полностью выпрямив руку.","Подтяните гантель к груди, держа локоть близко к телу и сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Deja que la mancuerna cuelgue recta hacia el suelo, con el brazo completamente extendido.","Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"1286","name":"dumbbell one arm chest fly on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1286-Bpkf41o.jpg","gif_url":"videos/1286-Bpkf41o.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם משקולת יד ביד אחת וכפות רגליים על הרצפה.","צעדו עם כפות הרגליים קדימה, בגלגול הכדור עד שהגב העליון נתמך עליו והראש, הצוואר והכתפיים מחוץ לכדור.","מתחו את היד עם המשקולת ישר מעל החזה, כף יד פונה פנימה.","הורידו את המשקולת באיטיות הצידה, עם כיפוף קל במרפק.","עצרו לרגע כשהיד מקבילה לרצפה.","הפעילו את שרירי החזה להחזרת המשקולת למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inward.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на мяч для упражнений, возьмите в одну руку гантель, поставьте ноги на землю.","Идите ногами вперед, катя мяч до тех пор, пока верхняя часть спины не окажется на мяче, а голова, шея и плечи не оторвутся от мяча.","Вытяните руку с гантелью прямо над грудью, ладонью внутрь.","Медленно опустите гантель в сторону, сохраняя небольшой изгиб в локте.","Сделайте паузу на мгновение, когда ваша рука будет параллельна земле.","Задействуйте мышцы груди, чтобы вернуть гантель в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate sobre un balón de estabilidad con una mancuerna en una mano y los pies apoyados en el suelo.","Camina con los pies hacia adelante, haciendo rodar el balón hasta que la parte superior de la espalda quede apoyada en el balón y la cabeza, el cuello y los hombros queden fuera de él.","Extiende el brazo con la mancuerna recto hacia arriba sobre el pecho, con la palma hacia adentro.","Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo.","Haz una pausa por un momento cuando el brazo esté paralelo al suelo.","Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0353","name":"dumbbell one arm concentration curl (on stability ball)","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0353-k5IpyHg.jpg","gif_url":"videos/0353-k5IpyHg.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","החזיקו משקולת יד ביד אחת, כף יד כלפי מעלה והיד מתוחה מטה לכיוון הרצפה.","השעינו את המרפק על החלק הפנימי של הירך, מעט מעל הברך.","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את המשקולת למעלה לכיוון הכתף תוך כיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, ואז שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים וחזרו."],"en":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."],"ru":["Сядьте на мяч, поставив ступни на землю и согнув колени под углом 90 градусов.","Возьмите гантель в одну руку ладонью вверх и вытяните руку вниз к полу.","Положите локоть на внутреннюю часть бедра, чуть выше колена.","Удерживая плечо неподвижно, выдохните и поднимите гантель к плечу, одновременно напрягая бицепс.","Сделайте паузу на мгновение в верхней точке движения, затем вдохните и медленно опустите гантель обратно в исходное положение.","Повторите необходимое количество повторений, затем поменяйте руки и повторите."],"es":["Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sostén una mancuerna en una mano con la palma hacia arriba y el brazo extendido hacia el suelo.","Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.","Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Haz una pausa por un momento en la parte superior del movimiento, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo y repite."]}},{"id":"1287","name":"dumbbell one arm decline chest press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1287-REGM1dE.jpg","gif_url":"videos/1287-REGM1dE.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי עם משקולת יד ביד אחת, מונחת על החזה.","הניחו את כפות הרגליים על הרצפה ושמרו על הגב צמוד לספסל.","יישרו את היד ולחצו את המשקולת למעלה לכיוון התקרה, עד יישור מלא של המרפק.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Place your feet flat on the ground and keep your back pressed against the bench.","Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Лягте на наклонную скамью с гантелью в одной руке, положив ее на грудь.","Поставьте ноги на землю и прижмите спину к скамье.","Вытяните руку и поднимите гантель вверх к потолку, полностью выпрямляя локоть.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho.","Coloca los pies planos sobre el suelo y mantén la espalda presionada contra el banco.","Extiende el brazo y empuja la mancuerna hacia el techo, extendiendo completamente el codo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"1288","name":"dumbbell one arm fly on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1288-Am02iPd.jpg","gif_url":"videos/1288-Am02iPd.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם משקולת יד ביד אחת וכפות רגליים על הרצפה.","צעדו עם כפות הרגליים קדימה וגלגלו את הגוף מטה עד שהגב העליון נשען על כדור הפיזיו.","מתחו את היד עם המשקולת ישר מעל החזה, כשכף היד פונה פנימה.","הורידו את המשקולת באיטיות הצידה, עם כיפוף קל במרפק.","עצרו לרגע, ואז כווצו את שרירי החזה להחזרת המשקולת לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward and roll your body down until your upper back is resting on the exercise ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на мяч для упражнений, возьмите в одну руку гантель, поставьте ноги на землю.","Пройдите ногами вперед и перекатывайтесь вниз, пока верхняя часть спины не окажется на мяче для упражнений.","Вытяните руку с гантелью прямо над грудью ладонью внутрь.","Медленно опустите гантель в сторону, сохраняя небольшой изгиб в локте.","Сделайте паузу на мгновение, затем сожмите мышцы груди, чтобы вернуть гантель в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate sobre un balón de estabilidad con una mancuerna en una mano y los pies apoyados en el suelo.","Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la parte superior de la espalda quede apoyada sobre el balón de estabilidad.","Extiende el brazo con la mancuerna recto hacia arriba sobre el pecho, con la palma hacia adentro.","Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo.","Haz una pausa por un momento, luego contrae los músculos del pecho para llevar la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1736","name":"dumbbell one arm french press on exercise ball","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1736-ziFKQXP.jpg","gif_url":"videos/1736-ziFKQXP.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד ביד אחת, כף יד כלפי מעלה ומרפק כפוף בזווית של 90 מעלות.","מתחו את היד ישר למעלה לכיוון התקרה, תוך שמירה על מרפק ללא תזוזה.","הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.","Extend your arm straight up towards the ceiling, keeping your elbow stationary.","Slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину.","Возьмите гантель в одну руку ладонью вверх и согните локоть под углом 90 градусов.","Вытяните руку прямо вверх к потолку, сохраняя локоть неподвижным.","Медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en una mano con la palma hacia arriba y el codo flexionado en un ángulo de 90 grados.","Extiende el brazo recto hacia el techo, manteniendo el codo quieto.","Baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1663","name":"dumbbell one arm hammer preacher curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1663-4dF3maG.jpg","gif_url":"videos/1663-4dF3maG.gif","instruction_steps":{"he":["שבו על ספסל פריצ'ר עם משקולת יד ביד אחת והזרוע העליונה מונחת על הכרית.","החזיקו את המשקולת באחיזה ניטרלית (כפות ידיים פונות לגוף).","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את המשקולת למעלה לכיוון הכתף.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.","Hold the dumbbell with a neutral grip (palms facing your body).","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью для проповедника с гантелью в одной руке и положите плечо на подушечку.","Держите гантель нейтральным хватом (ладони обращены к телу).","Удерживая плечо неподвижно, выдохните и поднимите гантель к плечу.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco scott con una mancuerna en una mano y el brazo superior apoyado sobre la almohadilla.","Sostén la mancuerna con agarre neutro (palmas hacia el cuerpo).","Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1621","name":"dumbbell one arm hammer press on exercise ball","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"triceps","image":"images/1621-VYmYxK5.jpg","gif_url":"videos/1621-VYmYxK5.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד ביד אחת, כף יד פונה פנימה ומרפק כפוף בזווית של 90 מעלות.","הניחו את היד השנייה על המותן לייצוב.","לחצו את המשקולת כלפי מעלה, עד יישור מלא של היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.","Place your other hand on your hip for stability.","Press the dumbbell upwards, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину.","Возьмите гантель в одну руку ладонью внутрь и согните локоть под углом 90 градусов.","Вторую руку положите на бедро для устойчивости.","Выжмите гантель вверх, полностью выпрямляя руку.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en una mano con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados.","Coloca la otra mano en la cadera para mantener el equilibrio.","Empuja la mancuerna hacia arriba, extendiendo completamente el brazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1289","name":"dumbbell one arm incline chest press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1289-PDaMuyV.jpg","gif_url":"videos/1289-PDaMuyV.gif","instruction_steps":{"he":["כווננו את ספסל השיפוע לזווית של 45 מעלות.","שבו על הספסל כשהגב צמוד לכרית וכפות הרגליים על הרצפה.","החזיקו משקולת יד ביד אחת באחיזה עליונה, מונחת על הכתף.","דחפו את המשקולת למעלה והרחק מהגוף, עד יישור מלא של היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Adjust the incline bench to a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, resting it on your shoulder.","Push the dumbbell up and away from your body, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Отрегулируйте наклон скамьи под углом 45 градусов.","Сядьте на скамью, прислонившись спиной к подушке, а ступни поставьте на землю.","Возьмите гантель в одну руку верхним хватом, положив ее на плечо.","Поднимите гантель вверх и от тела, полностью выпрямляя руку.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Ajusta el banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.","Sostén una mancuerna en una mano con agarre prono, apoyándola sobre el hombro.","Empuja la mancuerna hacia arriba y alejándola del cuerpo, extendiendo completamente el brazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0354","name":"dumbbell one arm kickback","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0354-bQy2Eni.jpg","gif_url":"videos/0354-bQy2Eni.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד ביד ימין.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","הרימו את מרפק ימין לצד הגוף, כשהוא כפוף בזווית של 90 מעלות.","יישרו את יד ימין ישר לאחור, וכווצו את הטרייספס בנקודה העליונה של התנועה.","הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps at the top of the movement.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, возьмите в правую руку гантель.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Поднимите правый локоть в сторону, сохраняя его согнутым под углом 90 градусов.","Вытяните правую руку прямо назад, сжимая трицепс в верхней точке движения.","Медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados.","Extiende el brazo derecho recto hacia atrás, contrayendo el tríceps en la parte superior del movimiento.","Baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0355","name":"dumbbell one arm lateral raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","triceps"],"target":"delts","image":"images/0355-n5cWCsI.jpg","gif_url":"videos/0355-n5cWCsI.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד ביד אחת עם כף יד פונה לגוף.","שמרו על גב ישר וליבה מופעלת לאורך כל התרגיל.","הרימו את המשקולת הצידה, תוך שמירה על יד ישרה וכף יד כלפי מטה.","המשיכו להרים עד שהיד מקבילה לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Keep your back straight and your core engaged throughout the exercise.","Raise the dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Встаньте, ноги на ширине плеч, держите гантель в одной руке ладонью к телу.","На протяжении всего упражнения держите спину прямой и напряженным корпус.","Поднимите гантель в сторону, держа руку прямой ладонью вниз.","Продолжайте поднимать, пока ваша рука не станет параллельна земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo.","Continúa levantando hasta que el brazo quede paralelo al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0356","name":"dumbbell one arm lateral raise with support","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","rotator cuff"],"target":"delts","image":"images/0356-Yg7MJAT.jpg","gif_url":"videos/0356-Yg7MJAT.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד ביד אחת, עם כף יד פונה לגוף.","הניחו את היד השנייה על משטח יציב, כמו ספסל או קיר, לתמיכה.","שמרו על גב ישר והפעילו את שרירי הליבה.","הרימו את המשקולת הצידה, תוך שמירה על יד ישרה וכף יד כלפי מטה.","המשיכו להרים עד שהיד מקבילה לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.","Place your other hand on a stable surface, such as a bench or wall, for support.","Keep your back straight and engage your core.","Raise the dumbbell out to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, возьмите в одну руку гантель ладонью к телу.","Другую руку положите на устойчивую поверхность, например на скамью или стену, для поддержки.","Держите спину прямо и задействуйте корпус.","Поднимите гантель в сторону, держа руку прямой ладонью вниз.","Продолжайте поднимать, пока ваша рука не станет параллельна земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano, con la palma hacia el cuerpo.","Coloca la otra mano sobre una superficie estable, como un banco o una pared, para apoyarte.","Mantén la espalda recta y activa el core.","Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo.","Continúa levantando hasta que el brazo quede paralelo al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"1290","name":"dumbbell one arm press on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","core"],"target":"pectorals","image":"images/1290-QZFv5ui.jpg","gif_url":"videos/1290-QZFv5ui.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","החזיקו משקולת יד ביד אחת ומקמו אותה בגובה הכתף, עם מרפק כפוף וכף יד פונה קדימה.","לחצו באיטיות את המשקולת כלפי מעלה עד יישור מלא של היד, תוך הפעלת הליבה ושמירה על שיווי משקל על כדור הפיזיו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward.","Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Сядьте на гимнастический мяч, поставьте ступни на землю и согните колени под углом 90 градусов.","Возьмите гантель в одну руку и расположите ее на уровне плеч, согнув локоть и ладонь вперед.","Медленно поднимите гантель вверх, пока рука не будет полностью выпрямлена, сохраняя при этом корпус напряженным и сохраняя баланс на мяче для упражнений.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sostén una mancuerna en una mano y colócala a la altura del hombro, con el codo flexionado y la palma hacia adelante.","Empuja lentamente la mancuerna hacia arriba hasta que el brazo quede completamente extendido, manteniendo el core activado y el equilibrio sobre el balón de estabilidad.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"1665","name":"dumbbell one arm prone curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1665-JWjujiY.jpg","gif_url":"videos/1665-JWjujiY.gif","instruction_steps":{"he":["שכבו על הבטן על ספסל ישר עם משקולת יד ביד אחת, כף יד כלפי מטה.","יישרו את היד לגמרי, ותנו לה להשתלשל ישר מטה לכיוון הרצפה.","תוך שמירה על הזרוע העליונה ללא תזוזה, כופפו את המשקולת למעלה לכיוון הכתף בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Lie face down on a flat bench with a dumbbell in one hand, palm facing down.","Extend your arm fully, letting it hang straight down towards the floor.","Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Лягте лицом вниз на плоскую скамью с гантелью в одной руке ладонью вниз.","Полностью вытяните руку, позволяя ей свисать прямо к полу.","Удерживая плечо неподвижно, поднимите гантель к плечу, напрягая бицепс.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia abajo.","Extiende completamente el brazo, dejando que cuelgue recto hacia el suelo.","Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1666","name":"dumbbell one arm prone hammer curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1666-LIGZSTA.jpg","gif_url":"videos/1666-LIGZSTA.gif","instruction_steps":{"he":["שכבו על הבטן על ספסל ישר עם משקולת יד ביד אחת, כף יד פונה לגוף ויד ישרה לגמרי.","שמרו על הזרוע העליונה ללא תזוזה וכופפו את המשקולת לכיוון הכתף, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Лягте лицом вниз на плоскую скамью с гантелью в одной руке, ладонью к телу и полностью выпрямленной рукой.","Держите плечо неподвижно и поднимите гантель к плечу, напрягая бицепс.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo y el brazo completamente extendido.","Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, contrayendo el bíceps.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1291","name":"dumbbell one arm pullover on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","latissimus dorsi","rhomboids"],"target":"pectorals","image":"images/1291-bQHPBU3.jpg","gif_url":"videos/1291-bQHPBU3.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","החזיקו משקולת יד ביד אחת ומתחו את היד ישר מעל החזה.","הורידו באיטיות את המשקולת מאחורי הראש תוך שמירה על יד ישרה.","עצרו לרגע, ואז הרימו את המשקולת חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with one hand and extend your arm straight up above your chest.","Slowly lower the dumbbell behind your head while keeping your arm straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на гимнастический мяч, поставьте ступни на землю и согните колени под углом 90 градусов.","Возьмите гантель одной рукой и вытяните руку прямо над грудью.","Медленно опустите гантель за голову, сохраняя руку прямой.","Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sostén una mancuerna con una mano y extiende el brazo recto hacia arriba sobre el pecho.","Baja lentamente la mancuerna detrás de la cabeza manteniendo el brazo recto.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0358","name":"dumbbell one arm reverse wrist curl","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"wrist extensors","secondary_muscles":["wrist extensors"],"target":"forearms","image":"images/0358-BwSNDGt.jpg","gif_url":"videos/0358-BwSNDGt.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם כפות רגליים על הרצפה.","החזיקו משקולת יד ביד אחת באחיזה עליונה, כף יד כלפי מטה.","השעינו את האמה על הירך, עם שורש כף היד משתלשל מעבר לקצה.","הורידו את המשקולת באיטיות לכיוון הרצפה בכיפוף שורש כף היד.","עצרו לרגע בנקודה התחתונה, ואז כופפו באיטיות את שורש כף היד חזרה למעלה לכיוון הגוף.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, palm facing down.","Rest your forearm on your thigh, with your wrist hanging off the edge.","Slowly lower the dumbbell towards the ground by flexing your wrist.","Pause for a moment at the bottom, then slowly curl your wrist back up towards your body.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Сядьте на скамью или стул, поставив ноги на землю.","Возьмите гантель в одну руку хватом сверху ладонью вниз.","Положите предплечье на бедро так, чтобы запястье свисало с края.","Медленно опустите гантель на землю, сгибая запястье.","Задержитесь на мгновение в нижней точке, затем медленно согните запястье обратно к телу.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate en un banco o silla con los pies apoyados en el suelo.","Sostén una mancuerna en una mano con agarre prono, con la palma hacia abajo.","Apoya el antebrazo sobre el muslo, con la muñeca colgando fuera del borde.","Baja lentamente la mancuerna hacia el suelo flexionando la muñeca.","Haz una pausa por un momento en la parte inferior, luego flexiona lentamente la muñeca de vuelta hacia el cuerpo.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0359","name":"dumbbell one arm reverse fly (with support)","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0359-e25F58f.jpg","gif_url":"videos/0359-e25F58f.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד ביד אחת, כף יד פונה פנימה.","רכנו קדימה והניחו את היד הפנויה על הספסל לתמיכה.","שמרו על היד כפופה מעט והרימו אותה הצידה עד שהיא מקבילה לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את היד באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a bench with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards.","Lean forward and place your free hand on the bench for support.","Keep your arm slightly bent and raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью, поставив ноги на землю и выпрямив спину.","Возьмите гантель в одну руку ладонью внутрь.","Наклонитесь вперед и положите свободную руку на скамью для поддержки.","Держите руку слегка согнутой и поднимите ее в сторону, пока она не станет параллельна земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите руку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en una mano con la palma hacia adentro.","Inclínate hacia adelante y coloca la mano libre sobre el banco para apoyarte.","Mantén el brazo ligeramente flexionado y levántalo hacia el lado hasta que quede paralelo al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1622","name":"dumbbell one arm reverse grip press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1622-Ze7MoIb.jpg","gif_url":"videos/1622-Ze7MoIb.gif","instruction_steps":{"he":["שבו על ספסל ישר עם משקולת יד ביד אחת, כף יד פונה לגוף.","הניחו את כפות הרגליים על הרצפה ושמרו על גב ישר.","הרימו את המשקולת לגובה הכתף, תוך שמירה על מרפק קרוב לגוף.","לחצו את המשקולת כלפי מעלה עד יישור מלא של היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on a flat bench with a dumbbell in one hand, palm facing towards your body.","Place your feet flat on the ground and keep your back straight.","Raise the dumbbell to shoulder height, keeping your elbow close to your body.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Сядьте на ровную скамью с гантелью в одной руке ладонью к телу.","Поставьте ноги на землю и держите спину прямо.","Поднимите гантель на высоту плеч, держа локоть близко к телу.","Нажмите гантель вверх, пока рука полностью не выпрямится.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo.","Coloca los pies planos sobre el suelo y mantén la espalda recta.","Levanta la mancuerna hasta la altura del hombro, manteniendo el codo cerca del cuerpo.","Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"1414","name":"dumbbell one arm reverse preacher curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1414-bWxq4op.jpg","gif_url":"videos/1414-bWxq4op.gif","instruction_steps":{"he":["שבו על ספסל פריצ'ר כשהחזה צמוד לכרית והיד מתוחה מעבר לקצה, אוחזת משקולת יד באחיזה תחתונה.","הורידו את המשקולת באיטיות עד יישור מלא של היד.","כופפו את המשקולת חזרה למעלה לכיוון הכתף, תוך שמירה על הזרוע העליונה ללא תזוזה.","כווצו את הבייספס בנקודה העליונה של התנועה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip.","Lower the dumbbell slowly until your arm is fully extended.","Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью для проповедника, прижав грудь к подушке и вытянув руку через край скамьи, держа гантель обратным хватом снизу.","Медленно опускайте гантель, пока рука полностью не выпрямится.","Поднимите гантель обратно к плечу, сохраняя плечо неподвижным.","Напрягите бицепсы в верхней точке движения, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco scott con el pecho contra la almohadilla y el brazo extendido sobre el borde del banco, sosteniendo una mancuerna con agarre supino.","Baja lentamente la mancuerna hasta que el brazo quede completamente extendido.","Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto.","Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1667","name":"dumbbell one arm reverse spider curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1667-VdLZ3nB.jpg","gif_url":"videos/1667-VdLZ3nB.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד ביד אחת, כף יד כלפי מטה ויד ישרה לגמרי.","תוך שמירה על הזרוע העליונה ללא תזוזה, כופפו את המשקולת לכיוון הכתף בכיפוף המרפק.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Встаньте прямо, возьмите гантель в одну руку ладонью вниз и полностью выпрямите руку.","Удерживая плечо неподвижно, поднимите гантель к плечу, сгибая локоть.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ponte de pie con una mancuerna en una mano, con la palma hacia abajo y el brazo completamente extendido.","Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro flexionando el codo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1668","name":"dumbbell one arm seated bicep curl on exercise ball","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1668-s999Hdo.jpg","gif_url":"videos/1668-s999Hdo.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד ביד אחת, כף יד כלפי מעלה ויד ישרה לגמרי.","תוך שמירה על הזרוע העליונה ללא תזוזה, כופפו את המשקולת לכיוון הכתף בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину.","Возьмите гантель в одну руку ладонью вверх и полностью выпрямите руку.","Удерживая плечо неподвижно, поднимите гантель к плечу, напрягая бицепс.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido.","Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1669","name":"dumbbell one arm seated hammer curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1669-jK2hZ6n.jpg","gif_url":"videos/1669-jK2hZ6n.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו משקולת יד ביד אחת באחיזה ניטרלית (כפות ידיים פונות זו לזו).","השעינו את המרפק על החלק הפנימי של הירך, מעט מעל הברך.","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את המשקולת למעלה לכיוון הכתף.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand with a neutral grip (palms facing each other).","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите гантель в одну руку нейтральным хватом (ладони обращены друг к другу).","Положите локоть на внутреннюю часть бедра, чуть выше колена.","Удерживая плечо неподвижно, выдохните и поднимите гантель к плечу.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sostén una mancuerna en una mano con agarre neutro (palmas enfrentadas entre sí).","Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.","Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1415","name":"dumbbell one arm seated neutral wrist curl","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/1415-YtaCTYl.jpg","gif_url":"videos/1415-YtaCTYl.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו משקולת יד ביד אחת, כף יד כלפי מעלה.","השעינו את האמה על הירך, כששורש כף היד משתלשל מעבר לקצה.","תוך שמירה על האמה ללא תזוזה, כופפו את שורש כף היד כלפי מעלה רחוק ככל האפשר.","עצרו לרגע בנקודה העליונה, ואז הורידו את שורש כף היד באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your forearm on your thigh, allowing your wrist to hang off the edge.","Keeping your forearm stationary, curl your wrist upward as far as possible.","Pause for a moment at the top, then slowly lower your wrist back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other hand."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в одну руку гантель ладонью вверх.","Положите предплечье на бедро, позволяя запястью свисать с края.","Удерживая предплечье неподвижно, согните запястье вверх как можно дальше.","Задержитесь на мгновение в верхней точке, затем медленно опустите запястье обратно в исходное положение.","Повторите необходимое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba.","Apoya el antebrazo sobre el muslo, dejando que la muñeca cuelgue fuera del borde.","Manteniendo el antebrazo quieto, flexiona la muñeca hacia arriba lo más posible.","Haz una pausa por un momento en la parte superior, luego baja lentamente la muñeca de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia a la otra mano."]}},{"id":"0361","name":"dumbbell one arm shoulder press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0361-84RyJf8.jpg","gif_url":"videos/0361-84RyJf8.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד ביד אחת בגובה הכתף, כף יד פונה קדימה.","לחצו את המשקולת כלפי מעלה עד יישור מלא של היד מעל הראש.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Press the dumbbell upward until your arm is fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Встаньте, ноги на ширине плеч, в одной руке держите гантель на уровне плеч ладонью вперед.","Нажмите гантель вверх, пока ваша рука полностью не выпрямится над головой.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante.","Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido por encima de la cabeza.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0360","name":"dumbbell one arm shoulder press v. 2","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0360-1TkiAFK.jpg","gif_url":"videos/0360-1TkiAFK.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד ביד אחת בגובה הכתף, כף יד פונה קדימה.","הפעילו את הליבה ולחצו את המשקולת ישר מעל הראש, עד יישור מלא של היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לגובה הכתף.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Engage your core and press the dumbbell straight up overhead, fully extending your arm.","Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Встаньте, ноги на ширине плеч, в одной руке держите гантель на уровне плеч ладонью вперед.","Напрягите корпус и поднимите гантель прямо над головой, полностью выпрямляя руку.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно на уровень плеч.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante.","Activa el core y empuja la mancuerna directamente hacia arriba por encima de la cabeza, extendiendo completamente el brazo.","Haz una pausa por un momento en la parte superior, luego baja lentamente la mancuerna de vuelta a la altura del hombro.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"3888","name":"dumbbell one arm snatch","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","core"],"target":"glutes","image":"images/3888-6pTkI99.jpg","gif_url":"videos/3888-6pTkI99.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד ביד אחת באחיזה עליונה.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וחזה מורם.","הורידו את המשקולת לכיוון הרצפה, כשהיא צמודה לגוף.","יישרו ירכיים, ברכיים וקרסוליים בפיצוץ, בדחיפת המשקולת כלפי מעלה בקו ישר.","כשהמשקולת מגיעה לגובה הכתף, סובבו במהירות את היד ודחפו אותה מעל הראש, עד יישור מלא של היד.","תפסו את המשקולת מעל הראש עם כיפוף קל בברכיים ובירכיים.","הורידו את המשקולת חזרה לנקודת ההתחלה בשליטה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Lower the dumbbell towards the ground, keeping it close to your body.","Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line.","As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm.","Catch the dumbbell overhead with a slight bend in your knees and hips.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Встаньте, ноги на ширине плеч, держите гантель в одной руке хватом сверху.","Слегка согните колени и наклонитесь вперед в бедрах, держа спину прямо и грудь вверх.","Опустите гантель к земле, держа ее близко к телу.","Взрывно выпрямите бедра, колени и лодыжки, поднимая гантель вверх по прямой линии.","Когда гантель достигнет высоты плеч, быстро поверните руку и ударьте ею над головой, полностью выпрямляя руку.","Возьмите гантель над головой, слегка согнув колени и бедра.","Контролируемым образом опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Baja la mancuerna hacia el suelo, manteniéndola cerca del cuerpo.","Extiende explosivamente las caderas, las rodillas y los tobillos, impulsando la mancuerna hacia arriba en línea recta.","Cuando la mancuerna alcance la altura del hombro, gira rápidamente la mano y empújala por encima de la cabeza, extendiendo completamente el brazo.","Recibe la mancuerna por encima de la cabeza con una ligera flexión en las rodillas y las caderas.","Baja la mancuerna de nuevo a la posición inicial de manera controlada.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"1670","name":"dumbbell one arm standing curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1670-ffQsyBj.jpg","gif_url":"videos/1670-ffQsyBj.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד ביד אחת, כף יד פונה קדימה ויד ישרה לגמרי.","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את המשקל כלפי מעלה תוך כיווץ הבייספס.","המשיכו להרים את המשקולת עד שהבייספס מכווץ במלואו והמשקולת בגובה הכתף.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended.","Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Встаньте прямо, возьмите гантель в одну руку, ладонь вперед и полностью выпрямите руку.","Удерживая плечо неподвижно, выдохните и поднимите вес вверх, одновременно сокращая бицепсы.","Продолжайте поднимать гантель до тех пор, пока ваши бицепсы полностью не сократятся и гантель не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ponte de pie con una mancuerna en una mano, con la palma hacia adelante y el brazo completamente extendido.","Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia arriba contrayendo el bíceps.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1671","name":"dumbbell one arm standing hammer curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1671-2sQGZ5b.jpg","gif_url":"videos/1671-2sQGZ5b.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות לגו.","שמרו על מרפקים צמודים לגוף וזרועות עליונות ללא תזוזה.","נשפו וכופפו את המשקולות תוך כיווץ הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, возьмите в каждую руку по гантели, ладони обращены к туловищу.","Держите локти близко к туловищу, а плечи неподвижны.","Выдохните и согните штангу, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.","Mantén los codos cerca del torso y los brazos superiores quietos.","Exhala y flexiona las pesas mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0362","name":"dumbbell one arm triceps extension (on bench)","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0362-nAuHPcD.jpg","gif_url":"videos/0362-nAuHPcD.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו משקולת יד ביד אחת והניחו את היד השנייה על הספסל לתמיכה.","הרימו את המשקולת מעל הראש, תוך שמירה על הזרוע העליונה קרובה לראש והמרפק פונה קדימה.","הורידו את המשקולת מאחורי הראש בכיפוף המרפק, תוך שמירה על הזרוע העליונה ללא תזוזה.","יישרו את היד חזרה למעלה לנקודת ההתחלה, עד יישור מלא של המרפק.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand and place your other hand on the bench for support.","Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Extend your arm back up to the starting position, fully straightening your elbow.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите гантель в одну руку, а другую руку положите на скамью для поддержки.","Поднимите гантель над головой, держа плечо близко к голове и локоть направленным вперед.","Опустите гантель за голову, согнув локоть, сохраняя плечо неподвижным.","Вытяните руку обратно в исходное положение, полностью выпрямляя локоть.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sostén una mancuerna en una mano y coloca la otra mano sobre el banco para apoyarte.","Levanta la mancuerna por encima de la cabeza, manteniendo el brazo superior cerca de la cabeza y el codo apuntando hacia adelante.","Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto.","Extiende el brazo de vuelta a la posición inicial, estirando completamente el codo.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0363","name":"dumbbell one arm upright row","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0363-6cKQC5E.jpg","gif_url":"videos/0363-6cKQC5E.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד ביד אחת באחיזה עליונה.","תנו למשקולת להשתלשל בידיים ישרות מול הירכיים, עם כף יד פונה לגוף.","תוך שמירה על גב ישר וליבה מופעלת, נשפו והרימו את המשקולת ישר למעלה לכיוון הסנטר, כשהמרפק מוביל.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Let the dumbbell hang at arm's length in front of your thighs, with your palm facing your body.","Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Встаньте, ноги на ширине плеч, держите гантель в одной руке хватом сверху.","Пусть гантель висит на расстоянии вытянутой руки перед бедрами, ладонью к телу.","Удерживая спину прямой и напрягая корпус, выдохните и поднимите гантель прямо вверх к подбородку, ведя локтем.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono.","Deja que la mancuerna cuelgue a la distancia de un brazo frente a los muslos, con la palma hacia el cuerpo.","Manteniendo la espalda recta y el core activado, exhala y levanta la mancuerna recta hacia la barbilla, guiando con el codo.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0364","name":"dumbbell one arm wrist curl","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0364-q8aHNoF.jpg","gif_url":"videos/0364-q8aHNoF.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם כפות רגליים על הרצפה.","החזיקו משקולת יד ביד אחת באחיזה תחתונה, כשהאמה נשענת על הירך.","תנו לשורש כף היד להתיישר, ותנו למשקולת להתגלגל מטה לכיוון האצבעות.","כופפו באיטיות את שורש כף היד חזרה למעלה, בהבאת המשקולת לכיוון האמה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh.","Allow your wrist to extend, letting the dumbbell roll down towards your fingers.","Slowly curl your wrist back up, bringing the dumbbell towards your forearm.","Repeat for the desired number of repetitions, then switch to the other hand."],"ru":["Сядьте на скамью или стул, поставив ноги на землю.","Возьмите гантель в одну руку обратным хватом, положив предплечье на бедро.","Позвольте запястью выпрямиться, позволив гантеле скатиться вниз к вашим пальцам.","Медленно согните запястье вверх, поднося гантель к предплечью.","Повторите необходимое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate en un banco o silla con los pies apoyados en el suelo.","Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo.","Permite que la muñeca se extienda, dejando que la mancuerna ruede hacia los dedos.","Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo.","Repite el número de repeticiones deseado, luego cambia a la otra mano."]}},{"id":"1672","name":"dumbbell one arm zottman preacher curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1672-sxY5Biu.jpg","gif_url":"videos/1672-sxY5Biu.gif","instruction_steps":{"he":["שבו על ספסל פריצ'ר והחזיקו משקולת יד ביד אחת באחיזה תחתונה.","השעינו את הזרוע העליונה על כרית ספסל הפריצ'ר, ותנו ליד להתיישר לגמרי.","כופפו את המשקולת למעלה לכיוון הכתף, תוך שמירה על הזרוע העליונה ללא תזוזה.","בנקודה העליונה של הכפיפה, סובבו את שורש כף היד כך שכף היד פונה כלפי מעלה.","הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה, בסיבוב שורש כף היד חזרה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip.","Rest your upper arm on the preacher bench pad, allowing your arm to fully extend.","Curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","At the top of the curl, rotate your wrist so that your palm faces up.","Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью для сгибаний рук и возьмите гантель в одну руку обратным хватом.","Положите плечо на подушку скамьи проповедника, позволяя руке полностью выпрямиться.","Поднимите гантель к плечу, сохраняя плечо неподвижным.","В верхней части сгиба поверните запястье ладонью вверх.","Медленно опустите гантель обратно в исходное положение, поворачивая запястье обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco scott y sostén una mancuerna en una mano con agarre supino.","Apoya el brazo superior sobre la almohadilla del banco scott, permitiendo que el brazo se extienda completamente.","Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto.","En la parte superior del curl, gira la muñeca de modo que la palma quede hacia arriba.","Baja lentamente la mancuerna de vuelta a la posición inicial, girando la muñeca de regreso a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1292","name":"dumbbell one leg fly on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1292-pH2x2jj.jpg","gif_url":"videos/1292-pH2x2jj.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","הניחו כף רגל אחת על הרצפה ומתחו את הרגל השנייה ישר לפניכם.","רכנו מעט קדימה והביאו את הידיים לצדדים, עם כיפוף קל במרפקים.","הורידו את המשקולות באיטיות מטה ולצדדים, עד תחושת מתיחה בחזה.","עצרו לרגע בנקודה התחתונה, ואז כווצו את שרירי החזה להחזרת המשקולות למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגליים וחזרו על התרגיל."],"en":["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Place one foot on the ground and extend the other leg straight out in front of you.","Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows.","Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest.","Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"ru":["Сядьте на гимнастический мяч, взяв в каждую руку по гантели, ладонями друг к другу.","Поставьте одну ногу на землю и вытяните другую ногу прямо перед собой.","Слегка наклонитесь вперед и разведите руки в стороны, сохраняя небольшой изгиб в локтях.","Медленно опустите гантели вниз и в стороны, чувствуя растяжение в груди.","Задержитесь на мгновение в нижней точке, затем сожмите мышцы груди, чтобы вернуть гантели в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу и повторите."],"es":["Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Coloca un pie en el suelo y extiende la otra pierna recta hacia adelante.","Inclínate ligeramente hacia adelante y lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos.","Baja lentamente las mancuernas hacia abajo y hacia los lados, sintiendo un estiramiento en el pecho.","Haz una pausa por un momento en la parte inferior, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."]}},{"id":"0365","name":"dumbbell over bench neutral wrist curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0365-BKa8dmT.jpg","gif_url":"videos/0365-BKa8dmT.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו משקולת יד בכל יד, כפות ידיים כלפי מעלה.","הניחו את האמות על הספסל, כששורשי כף היד משתלשלים מעבר לקצה.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המשקולות למעלה לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в каждую руку по гантели ладонями вверх.","Положите предплечья на скамью так, чтобы запястья свисали с края.","Удерживая плечи неподвижно, выдохните и поднимите гантели к плечам.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.","Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.","Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas hacia los hombros.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0366","name":"dumbbell over bench one arm neutral wrist curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0366-IvV6C9M.jpg","gif_url":"videos/0366-IvV6C9M.gif","instruction_steps":{"he":["שבו על ספסל עם משקולת יד ביד אחת והיד מתוחה מעבר לספסל, כף יד כלפי מעלה.","שמרו על הזרוע העליונה ללא תזוזה וכופפו את המשקולת לכיוון הכתף, תוך שמירה על שורש כף יד ניטרלי.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью, взяв в одну руку гантель, вытянув руку над скамьей ладонью вверх.","Держите плечо неподвижно и согните гантель к плечу, сохраняя запястье в нейтральном положении.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco con una mancuerna en una mano y el brazo extendido sobre el banco, con la palma hacia arriba.","Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, manteniendo la muñeca en posición neutra.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1441","name":"dumbbell over bench one arm reverse wrist curl","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/1441-4Jc36XM.jpg","gif_url":"videos/1441-4Jc36XM.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו משקולת יד ביד אחת, כף יד כלפי מטה.","השעינו את האמה על הספסל, כששורש כף היד משתלשל מעבר לקצה.","גלגלו באיטיות את שורש כף היד כלפי מעלה, בהבאת המשקולת לכיוון האמה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Сядьте на скамью, поставьте ноги на землю и держите гантель в одной руке ладонью вниз.","Положите предплечье на скамью так, чтобы запястье свисало с края.","Медленно согните запястье вверх, поднося гантель к предплечью.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo.","Apoya el antebrazo en el banco con la muñeca colgando del borde.","Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0367","name":"dumbbell over bench one arm wrist curl","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/0367-KI1DjNN.jpg","gif_url":"videos/0367-KI1DjNN.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו משקולת יד ביד אחת, כף יד כלפי מטה.","השעינו את האמה על הספסל, כששורש כף היד משתלשל מעבר לקצה.","גלגלו באיטיות את שורש כף היד כלפי מעלה, בהבאת המשקולת לכיוון האמה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Сядьте на скамью, поставьте ноги на землю и держите гантель в одной руке ладонью вниз.","Положите предплечье на скамью так, чтобы запястье свисало с края.","Медленно согните запястье вверх, поднося гантель к предплечью.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo.","Apoya el antebrazo en el banco con la muñeca colgando del borde.","Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0368","name":"dumbbell over bench revers wrist curl","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0368-3tAXPQ6.jpg","gif_url":"videos/0368-3tAXPQ6.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו משקולת יד בכל יד, כפות ידיים כלפי מטה.","הניחו את האמות על הספסל, כששורשי כף היד משתלשלים מעבר לקצה.","גלגלו באיטיות את שורשי כף היד כלפי מעלה, בהבאת המשקולות לכיוון הגוף.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в каждую руку по гантели ладонями вниз.","Положите предплечья на скамью так, чтобы запястья свисали с края.","Медленно поднимите запястья вверх, приближая гантели к телу.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas hacia abajo.","Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.","Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0369","name":"dumbbell over bench wrist curl","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0369-D1xYJAU.jpg","gif_url":"videos/0369-D1xYJAU.gif","instruction_steps":{"he":["שבו על ספסל כשהאמות מונחות עליו וכפות הידיים כלפי מעלה, אוחזים משקולת יד בכל יד.","תנו לשורשי כף היד להשתלשל מעבר לקצה הספסל.","גלגלו באיטיות את שורשי כף היד כלפי מעלה, בכיווץ האמות בנקודה העליונה של התנועה.","עצרו לרגע, ואז הורידו את שורשי כף היד באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.","Allow your wrists to hang over the edge of the bench.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, положив предплечья на скамью ладонями вверх, держа в каждой руке по гантели.","Пусть ваши запястья свисают с края скамьи.","Медленно поднимите запястья вверх, сжимая предплечья в верхней точке движения.","Сделайте паузу на мгновение, затем медленно опустите запястья обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los antebrazos apoyados en él y las palmas hacia arriba, sujetando una mancuerna en cada mano.","Deja que tus muñecas cuelguen del borde del banco.","Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento.","Haz una pausa por un momento y luego baja lentamente las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1329","name":"dumbbell palm rotational bent over row","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1329-wt6rwjk.jpg","gif_url":"videos/1329-wt6rwjk.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד באחיזה עליונה.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וברכיים כפופות מעט.","תנו לידיים להשתלשל ישר מטה, כפות ידיים פונות לגוף.","הפעילו את הליבה ומשכו את המשקולות למעלה לכיוון החזה, תוך שמירה על מרפקים צמודים לגוף.","תוך כדי משיכת המשקולות למעלה, סובבו את כפות הידיים כך שהן פונות מהגוף.","כווצו את השכמות זו לזו בנקודה העליונה של התנועה.","הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה, בסיבוב כפות הידיים חזרה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Bend forward at the hips, keeping your back straight and your knees slightly bent.","Let your arms hang straight down, palms facing your body.","Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.","As you pull the dumbbells up, rotate your palms so they face away from your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите по гантели в каждой руке хватом сверху.","Наклонитесь вперед в бедрах, сохраняя спину прямой и слегка согнутыми в коленях.","Пусть ваши руки свисают прямо вниз, ладони обращены к телу.","Напрягите корпус и подтяните гантели к груди, держа локти близко к телу.","Подтягивая гантели вверх, поверните ладони так, чтобы они были направлены от тела.","В верхней точке движения сведите лопатки вместе.","Медленно опустите гантели обратно в исходное положение, поворачивая ладони обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Deja que los brazos cuelguen rectos hacia abajo, con las palmas hacia tu cuerpo.","Activa el core y tira de las mancuernas hacia tu pecho, manteniendo los codos cerca del cuerpo.","Mientras subes las mancuernas, gira las palmas para que queden mirando hacia afuera, alejadas de tu cuerpo.","Junta los omóplatos en la parte superior del movimiento.","Baja lentamente las mancuernas hasta la posición inicial, girando las palmas de vuelta a su posición original.","Repite el número de repeticiones deseado."]}},{"id":"1623","name":"dumbbell palms in incline bench press","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1623-8eqjhOl.jpg","gif_url":"videos/1623-8eqjhOl.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שבו על הספסל כשהגב צמוד למשענת וכפות הרגליים על הרצפה.","החזיקו משקולת יד בכל יד באחיזה עליונה, כפות ידיים פונות פנימה.","מתחו את הידיים ישר מעל החזה, עם כיפוף קל במרפקים.","הורידו את המשקולות באיטיות לכיוון הכתפיים, תוך שמירה על מרפקים צמודים לגוף.","עצרו לרגע בנקודה התחתונה, ואז לחצו את המשקולות חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the backrest and feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing inwards.","Extend your arms straight up above your chest, keeping a slight bend in your elbows.","Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body.","Pause for a moment at the bottom, then press the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Сядьте на скамью, прислонившись спиной к спинке и поставив ступни на землю.","Возьмите по гантели в каждую руку хватом сверху, ладонями внутрь.","Вытяните руки прямо над грудью, сохраняя небольшой изгиб в локтях.","Медленно опустите гантели к плечам, держа локти близко к телу.","Задержитесь на мгновение в нижней точке, затем верните гантели в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos en el suelo.","Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia adentro.","Extiende los brazos rectos hacia arriba, por encima del pecho, manteniendo una ligera flexión en los codos.","Baja las mancuernas lentamente hacia los hombros, manteniendo los codos cerca del cuerpo.","Haz una pausa por un momento en la posición más baja y luego presiona las mancuernas de vuelta hacia arriba, hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0370","name":"dumbbell peacher hammer curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0370-F1KxjBa.jpg","gif_url":"videos/0370-F1KxjBa.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות לגו.","שמרו על מרפקים צמודים לגו וסובבו את כפות הידיים עד שהן פונות קדימה.","זוהי נקודת ההתחלה שלכם.","כעת, תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המשקולות תוך כיווץ הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","לאחר מכן, שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות המומלץ."],"en":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"ru":["Встаньте прямо, возьмите в каждую руку по гантели, ладони обращены к туловищу.","Держите локти близко к туловищу и поворачивайте ладони рук так, чтобы они смотрели вперед.","Это будет ваша исходная позиция.","Теперь, удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Затем вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите рекомендованное количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.","Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.","Esta será tu posición inicial.","Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones recomendado."]}},{"id":"0371","name":"dumbbell plyo squat","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0371-S4pwGlc.jpg","gif_url":"videos/0371-S4pwGlc.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במשקולת יד בכל יד לצידי הגוף.","רדו לסקוואט בכיפוף ברכיים ודחיפת האגן לאחור.","בהגיעכם לנקודה התחתונה של הסקוואט, התפרצו כלפי מעלה בקפיצה מהרצפה.","באוויר, החליפו במהירות את מיקום כפות הרגליים, ונחתו עם הרגל הנגדית קדימה.","הורידו מיד את הגוף חזרה לעמדת סקוואט וחזרו על הקפיצה, בהחלפת רגליים נוספת.","המשיכו להחליף את מיקום כפות הרגליים בכל קפיצה למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you reach the bottom of the squat, explode upward, jumping off the ground.","While in the air, quickly switch the position of your feet, landing with your opposite foot forward.","Immediately lower your body back into a squat position and repeat the jump, switching your feet again.","Continue alternating the position of your feet with each jump for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа по гантели в каждой руке по бокам.","Опустите тело в присед, согнув колени и отведя бедра назад.","Достигнув нижней точки приседа, резко взлетайте вверх, отпрыгивая от земли.","Находясь в воздухе, быстро поменяйте положение ног, приземлившись противоположной ногой вперед.","Немедленно опустите тело обратно в положение приседа и повторите прыжок, снова поменяв ноги.","Продолжайте менять положение ног при каждом прыжке желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Cuando llegues al punto más bajo de la sentadilla, impúlsate explosivamente hacia arriba, saltando del suelo.","Mientras estás en el aire, cambia rápidamente la posición de los pies, aterrizando con el pie opuesto adelante.","Baja inmediatamente el cuerpo de vuelta a la posición de sentadilla y repite el salto, cambiando de nuevo los pies.","Continúa alternando la posición de los pies en cada salto durante el número de repeticiones deseado."]}},{"id":"0372","name":"dumbbell preacher curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0372-jivWf8n.jpg","gif_url":"videos/0372-jivWf8n.gif","instruction_steps":{"he":["שבו על ספסל פריצ'ר כשהזרועות העליונות מונחות על הכרית והחזה צמוד אליה.","החזיקו משקולת יד בכל יד, כפות ידיים כלפי מעלה וידיים ישרות לגמרי.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью для сгибаний рук для проповедника, положив плечи на подушечку и прижавшись к ней грудью.","Возьмите по гантели в каждую руку ладонями вверх и полностью выпрямите руки.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco scott con la parte superior de los brazos apoyada en la almohadilla y el pecho contra ella.","Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1673","name":"dumbbell preacher curl over exercise ball","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1673-hwygydB.jpg","gif_url":"videos/1673-hwygydB.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד ביד אחת באחיזה תחתונה, כשהמרפק נשען על כדור הפיזיו.","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את המשקולת למעלה לכיוון הכתף.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину.","Возьмите гантель в одну руку обратным хватом, положив локоть на мяч для упражнений.","Удерживая плечо неподвижно, выдохните и поднимите гантель к плечу.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sujeta una mancuerna con una mano con agarre supino, apoyando el codo sobre el balón de estabilidad.","Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.","Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1293","name":"dumbbell press on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1293-O8o7q4d.jpg","gif_url":"videos/1293-O8o7q4d.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה ומשקולת יד בכל יד, מונחות על הירכיים.","צעדו באיטיות עם כפות הרגליים קדימה, בגלגול כדור הפיזיו עד שהגב התחתון נתמך על הכדור והברכיים בזווית של 90 מעלות.","הרימו את המשקולות לגובה הכתפיים, כפות ידיים פונות קדימה.","לחצו את המשקולות כלפי מעלה עד יישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.","Raise the dumbbells to shoulder height, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на гимнастический мяч, поставьте ноги на землю и возьмите в каждую руку по гантели, положив их на бедра.","Медленно пройдите ногами вперед, перекатывая мяч для упражнений до тех пор, пока нижняя часть спины не окажется на мяче, а колени не окажутся под углом 90 градусов.","Поднимите гантели на высоту плеч, ладони смотрят вперед.","Выжмите гантели вверх, пока руки полностью не выпрямятся.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de estabilidad con los pies planos en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.","Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad hasta que tu zona lumbar quede apoyada sobre el balón y tus rodillas formen un ángulo de 90 grados.","Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.","Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0373","name":"dumbbell pronate-grip triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0373-bpJL2Qs.jpg","gif_url":"videos/0373-bpJL2Qs.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם גב ישר וכפות רגליים על הרצפה.","החזיקו משקולת יד בשתי הידיים, כפות ידיים כלפי מטה, ומתחו את הידיים ישר מעל הראש.","תוך שמירה על הזרועות העליונות קרובות לראש ומרפקים פונים קדימה, הורידו באיטיות את המשקולת מאחורי הראש בכיפוף המרפקים.","עצרו לרגע, ואז יישרו את הידיים חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench or chair with your back straight and feet flat on the ground.","Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.","Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью или стул, выпрямив спину и поставив ступни на землю.","Возьмите гантель обеими руками ладонями вниз и вытяните руки вверх.","Держа плечи близко к голове и локти направленными вперед, медленно опустите гантель за голову, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo.","Sujeta una mancuerna con ambas manos, con las palmas hacia abajo, y extiende los brazos rectos por encima de la cabeza.","Manteniendo la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante, baja lentamente la mancuerna detrás de la cabeza flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0374","name":"dumbbell prone incline curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0374-mwpPcr1.jpg","gif_url":"videos/0374-mwpPcr1.gif","instruction_steps":{"he":["כווננו את הספסל לשיפוע של 45 מעלות.","שכבו על הבטן על הספסל, כשהחזה והבטן נשענים עליו.","החזיקו משקולת יד בכל יד, כפות ידיים כלפי מטה וידיים ישרות לגמרי.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the bench to a 45-degree incline.","Lie face down on the bench with your chest and stomach resting against it.","Hold a dumbbell in each hand with your palms facing down and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте скамью под углом 45 градусов.","Лягте лицом вниз на скамью, прижавшись к ней грудью и животом.","Возьмите по гантели в каждую руку ладонями вниз и полностью выпрямите руки.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta el banco a una inclinación de 45 grados.","Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.","Sujeta una mancuerna en cada mano con las palmas hacia abajo y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1674","name":"dumbbell prone incline hammer curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1674-cWemPG8.jpg","gif_url":"videos/1674-cWemPG8.gif","instruction_steps":{"he":["כווננו את הספסל לשיפוע של 45 מעלות.","שכבו על הבטן על הספסל עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","תנו לידיים להשתלשל ישר לכיוון הרצפה, עם כיפוף קל במרפקים.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the bench to a 45-degree incline.","Lie face down on the bench with a dumbbell in each hand, palms facing each other.","Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте скамью под углом 45 градусов.","Лягте лицом вниз на скамью, взяв в каждую руку по гантели, ладони обращены друг к другу.","Позвольте рукам свисать прямо к полу, слегка согнутыми в локтях.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta el banco a una inclinación de 45 grados.","Túmbate boca abajo en el banco con una mancuerna en cada mano, con las palmas mirándose entre sí.","Deja que los brazos cuelguen rectos hacia el suelo, manteniendo los codos ligeramente flexionados.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0375","name":"dumbbell pullover","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"latissimus dorsi","secondary_muscles":["latissimus dorsi","triceps"],"target":"pectorals","image":"images/0375-9XjtHvS.jpg","gif_url":"videos/0375-9XjtHvS.gif","instruction_steps":{"he":["שכבו על ספסל כשהראש בקצה אחד וכפות הרגליים על הרצפה.","החזיקו משקולת יד בשתי הידיים ומתחו את הידיים ישר מעל החזה.","עם כיפוף קל במרפקים, הורידו באיטיות את המשקולת מאחורי הראש עד לתחושת מתיחה בחזה ובכתפיים.","עצרו לרגע, ואז הרימו את המשקולת חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив голову на один конец и поставив ноги на пол.","Возьмите гантель обеими руками и вытяните руки прямо над грудью.","Сохраняя небольшой изгиб в локтях, медленно опускайте гантель за голову, пока не почувствуете растяжение в груди и плечах.","Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.","Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho.","Manteniendo una ligera flexión en los codos, baja lentamente la mancuerna detrás de la cabeza hasta sentir un estiramiento en el pecho y los hombros.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1294","name":"dumbbell pullover hip extension on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/1294-lI7easp.jpg","gif_url":"videos/1294-lI7easp.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה והמשקולת מונחת על הירכיים.","צעדו באיטיות עם כפות הרגליים קדימה, בגלגול כדור הפיזיו לאורך הגב עד שהראש, הצוואר והגב העליון נתמכים על הכדור.","החזיקו את המשקולת בשתי ידיים ומתחו את הידיים ישר מעל החזה, עם כיפוף קל במרפקים.","הורידו את המשקולת מאחורי הראש, תוך שמירה על ידיים ישרות ושליטה.","עצרו לרגע, ואז הרימו את המשקולת חזרה לנקודת ההתחלה.","תוך שמירה על ידיים מתוחות, הרימו את האגן מהרצפה, בכיווץ הישבן והפעלת הליבה.","הורידו את האגן חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbell behind your head, keeping your arms straight and maintaining control.","Pause for a moment, then raise the dumbbell back to the starting position.","While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.","Lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч для упражнений, поставьте ноги на землю, а гантель положите на бедра.","Медленно пройдите ногами вперед, катя мяч для упражнений вниз по спине, пока ваша голова, шея и верхняя часть спины не окажутся на мяче.","Возьмите гантель обеими руками и вытяните руки прямо вверх над грудью, сохраняя небольшой изгиб в локтях.","Опустите гантель за голову, держа руки прямыми и сохраняя контроль.","Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение.","Держа руки вытянутыми, поднимите бедра от земли, сжимая ягодицы и задействуя корпус.","Опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de estabilidad con los pies planos en el suelo y la mancuerna apoyada sobre los muslos.","Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad por tu espalda hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Sujeta la mancuerna con ambas manos y extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos.","Baja la mancuerna detrás de la cabeza, manteniendo los brazos rectos y con control total.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Manteniendo los brazos extendidos, levanta las caderas del suelo, apretando los glúteos y activando el core.","Baja las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1295","name":"dumbbell pullover on exercise ball","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","latissimus dorsi"],"target":"pectorals","image":"images/1295-FSD6PGL.jpg","gif_url":"videos/1295-FSD6PGL.gif","instruction_steps":{"he":["שבו על כדור פיזיו והחזיקו משקולת יד בשתי הידיים מעל החזה, ידיים מתוחות.","הורידו באיטיות את המשקולת מאחורי הראש תוך שמירה על ידיים ישרות.","עצרו לרגע, ואז הרימו את המשקולת חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на гимнастический мяч и держите гантель обеими руками над грудью, вытянув руки.","Медленно опустите гантель за голову, сохраняя руки прямыми.","Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de estabilidad y sujeta una mancuerna con ambas manos por encima del pecho, con los brazos extendidos.","Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1700","name":"dumbbell push press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/1700-FS63wTN.jpg","gif_url":"videos/1700-FS63wTN.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד בכל יד בגובה הכתפיים.","כופפו ברכיים מעט ורדו קלות עם הגוף, ואז יישרו את הרגליים בפיצוץ ולחצו את המשקולות מעל הראש.","נעלו את הידיים בנקודה העליונה של התנועה, ואז הורידו את המשקולות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.","Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.","Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гантели на уровне плеч.","Слегка согните ноги в коленях и опустите тело вниз, затем резко выпрямите ноги и выжмите гантели над головой.","Зафиксируйте руки в верхней точке движения, затем опустите гантели обратно на уровень плеч.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros.","Flexiona ligeramente las rodillas y baja el cuerpo, luego extiende las piernas de forma explosiva y presiona las mancuernas por encima de la cabeza.","Bloquea los brazos en la parte superior del movimiento, luego baja las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"0376","name":"dumbbell raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0376-c9MnDRp.jpg","gif_url":"videos/0376-c9MnDRp.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד, כפות ידיים פונות לגוף.","שמרו על גב ישר והפעילו את שרירי הליבה.","הרימו את הידיים לצדדים עד שהן מקבילות לרצפה, תוך שמירה על כיפוף קל במרפקים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями к телу.","Держите спину прямо и задействуйте корпус.","Поднимите руки в стороны до тех пор, пока они не станут параллельны полу, сохраняя небольшой изгиб в локтях.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.","Mantén la espalda recta y activa el core.","Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2292","name":"dumbbell rear delt raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/2292-mu5Guxt.jpg","gif_url":"videos/2292-mu5Guxt.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד, כפות ידיים פונות לגוף.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","הרימו את הידיים לצדדים, עם כיפוף קל במרפקים, עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями к телу.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Поднимите руки в стороны, сохраняя небольшой изгиб в локтях, пока они не станут параллельны полу.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0377","name":"dumbbell rear delt row_shoulder","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0377-EKXOMEh.jpg","gif_url":"videos/0377-EKXOMEh.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","החזיקו משקולת יד בכל יד, כפות ידיים פונות לגוף.","הטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר וליבה מופעלת.","מתחו את הידיים ישר כלפי הרצפה, עם כיפוף קל במרפקים.","הרימו את המשקולות לצדדים, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with your palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight down towards the floor, with a slight bend in your elbows.","Raise the dumbbells out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Возьмите по гантели в каждую руку ладонями к телу.","Наклонитесь вперед в талии, сохраняя спину прямой и напрягая корпус.","Вытяните руки прямо вниз к полу, слегка согнув их в локтях.","Поднимите гантели в стороны, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.","Extiende los brazos rectos hacia el suelo, con una ligera flexión en los codos.","Levanta las mancuernas hacia los lados, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0378","name":"dumbbell rear fly","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0378-8DiFDVA.jpg","gif_url":"videos/0378-8DiFDVA.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","מתחו את הידיים ישר כלפי מטה לכיוון הרצפה, כפות ידיים פונות זו לזו.","עם כיפוף קל במרפקים, הרימו את הידיים לצדדים וכווצו את השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down towards the ground, palms facing each other.","Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Вытяните руки прямо вниз к земле, ладони обращены друг к другу.","Сохраняя небольшой изгиб в локтях, поднимите руки в стороны и сведите лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Extiende los brazos rectos hacia el suelo, con las palmas mirándose entre sí.","Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados y aprieta los omóplatos entre sí.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0380","name":"dumbbell rear lateral raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0380-v1qBec9.jpg","gif_url":"videos/0380-v1qBec9.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד, כפות ידיים פונות לגוף.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וליבה מופעלת.","הרימו את הידיים לצדדים, עם כיפוף קל במרפקים, עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями к телу.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой и напряженным корпусом.","Поднимите руки в стороны, сохраняя небольшой изгиб в локтях, пока они не станут параллельны полу.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0379","name":"dumbbell rear lateral raise (support head)","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0379-UzkLrem.jpg","gif_url":"videos/0379-UzkLrem.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","הרימו את הידיים לצדדים, עם כיפוף קל במרפקים, עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Поднимите руки в стороны, сохраняя небольшой изгиб в локтях, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0381","name":"dumbbell rear lunge","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0381-SSsBDwB.jpg","gif_url":"videos/0381-SSsBDwB.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד.","צעדו לאחור עם רגל ימין, בהורדת הגוף לעמדת מספריים.","כופפו את ברך שמאל והורידו את הגוף עד שירך שמאל מקבילה לרצפה.","עצרו לרגע, ואז דחפו דרך עקב שמאל לחזרה לנקודת ההתחלה.","חזרו על התנועה בצד השני, בצעד לאחור עם רגל שמאל."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step backward with your right foot, lowering your body into a lunge position.","Bend your left knee and lower your body until your left thigh is parallel to the ground.","Pause for a moment, then push through your left heel to return to the starting position.","Repeat on the other side, stepping back with your left foot."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гантели.","Сделайте шаг назад правой ногой, опуская тело в положение выпада.","Согните левое колено и опустите тело до тех пор, пока левое бедро не станет параллельно земле.","Сделайте паузу на мгновение, затем оттолкнитесь левой пяткой, чтобы вернуться в исходное положение.","Повторите то же самое в другую сторону, отступив левой ногой назад."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Da un paso hacia atrás con el pie derecho, bajando el cuerpo a una posición de zancada.","Flexiona la rodilla izquierda y baja el cuerpo hasta que el muslo izquierdo quede paralelo al suelo.","Haz una pausa por un momento, luego empuja con el talón izquierdo para volver a la posición inicial.","Repite del otro lado, dando un paso hacia atrás con el pie izquierdo."]}},{"id":"0382","name":"dumbbell revers grip biceps curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0382-e4ojVhP.jpg","gif_url":"videos/0382-e4ojVhP.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים כלפי מטה וידיים ישרות לגמרי.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, взяв в каждую руку по гантели, ладонями вниз и полностью выпрямленными руками.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1624","name":"dumbbell reverse bench press","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1624-UIbGx6H.jpg","gif_url":"videos/1624-UIbGx6H.gif","instruction_steps":{"he":["שכבו על הגב על ספסל ישר עם כפות רגליים על הרצפה וברכיים כפופות.","החזיקו משקולת יד בכל יד באחיזה עליונה, כפות ידיים פונות לכיוון כפות הרגליים.","מתחו את הידיים ישר לכיוון התקרה, עם כיפוף קל במרפקים.","הורידו את המשקולות באיטיות לכיוון החזה, ותנו למרפקים להיפתח לצדדים.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המשקולות חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your knees bent.","Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.","Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.","Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и согните колени.","Возьмите по гантели в каждую руку хватом сверху, ладонями к ногам.","Вытяните руки прямо вверх к потолку, сохраняя небольшой изгиб в локтях.","Медленно опустите гантели к груди, позволяя локтям развестися в стороны.","Задержитесь на мгновение в нижней точке, затем верните гантели в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con los pies apoyados en el suelo y las rodillas flexionadas.","Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tus pies.","Extiende los brazos rectos hacia el techo, manteniendo una ligera flexión en los codos.","Baja lentamente las mancuernas hacia el pecho, permitiendo que los codos se abran hacia los lados.","Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0383","name":"dumbbell reverse fly","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0383-EAs3xL9.jpg","gif_url":"videos/0383-EAs3xL9.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","מתחו את הידיים ישר כלפי מטה לפניכם, כפות ידיים פונות זו לזו.","עם כיפוף קל במרפקים, הרימו את הידיים לצדדים עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down in front of you, palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Вытяните руки прямо перед собой, ладони обращены друг к другу.","Сохраняя небольшой изгиб в локтях, поднимите руки в стороны, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí.","Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1330","name":"dumbbell reverse grip incline bench one arm row","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/1330-ZIViNh1.jpg","gif_url":"videos/1330-ZIViNh1.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","הניחו משקולת יד על הרצפה ליד הספסל.","עמדו מול הספסל עם רגליים ברוחב כתפיים.","הטו את הגו והניחו את ברך שמאל ויד שמאל על הספסל לתמיכה.","הרימו את המשקולת ביד ימין באחיזה הפוכה (כף יד כלפי מטה).","שמרו על גב ישר וליבה מופעלת.","משכו את המשקולת למעלה לכיוון החזה, תוך שמירה על מרפק קרוב לגוף.","כווצו את שרירי הגב בנקודה העליונה של התנועה.","הורידו את המשקולת חזרה לנקודת ההתחלה בשליטה.","חזרו על התרגיל למספר החזרות הרצוי.","החליפו צדדים וחזרו על התרגיל עם יד שמאל."],"en":["Set up an incline bench at a 45-degree angle.","Place a dumbbell on the floor next to the bench.","Stand facing the bench with your feet shoulder-width apart.","Bend at the waist and place your left knee and left hand on the bench for support.","Pick up the dumbbell with your right hand using a reverse grip (palm facing down).","Keep your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your back muscles at the top of the movement.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your left arm."],"ru":["Установите наклонную скамью под углом 45 градусов.","Положите гантель на пол рядом со скамейкой.","Встаньте лицом к скамье, поставив ноги на ширине плеч.","Согнитесь в талии и положите левое колено и левую руку на скамью для поддержки.","Возьмите гантель правой рукой обратным хватом (ладонью вниз).","Держите спину прямо, а корпус напряженным.","Подтяните гантель к груди, держа локоть близко к телу.","Напрягите мышцы спины в верхней точке движения.","Контролируемым образом опустите гантель обратно в исходное положение.","Повторите необходимое количество повторений.","Поменяйте сторону и повторите упражнение левой рукой."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Coloca una mancuerna en el suelo junto al banco.","Ponte de pie frente al banco con los pies separados a la altura de los hombros.","Inclínate desde la cintura y coloca la rodilla izquierda y la mano izquierda sobre el banco para apoyarte.","Toma la mancuerna con la mano derecha usando un agarre inverso (con la palma hacia abajo).","Mantén la espalda recta y el core activado.","Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo.","Aprieta los músculos de la espalda en la parte superior del movimiento.","Baja la mancuerna de nuevo a la posición inicial de manera controlada.","Repite el número de repeticiones deseado.","Cambia de lado y repite el ejercicio con el brazo izquierdo."]}},{"id":"1331","name":"dumbbell reverse grip incline bench two arm row","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1331-9pQSkH8.jpg","gif_url":"videos/1331-9pQSkH8.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שבו על הספסל כשהחזה צמוד למשענת וכפות הרגליים על הרצפה.","החזיקו משקולת יד בכל יד באחיזה תחתונה.","רכנו קדימה ותנו לידיים להשתלשל ישר מטה, מתוחות לגמרי.","משכו את המשקולות למעלה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and your feet flat on the ground.","Hold a dumbbell in each hand with an underhand grip.","Lean forward and let your arms hang straight down, fully extended.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Сядьте на скамью, прижав грудь к спинке, а ноги поставьте на землю.","Возьмите в каждую руку по гантели обратным хватом.","Наклонитесь вперед и позвольте рукам свисать прямо вниз, полностью выпрямившись.","Подтяните гантели к груди, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con el pecho apoyado en el respaldo y los pies planos en el suelo.","Sujeta una mancuerna en cada mano con agarre supino.","Inclínate hacia adelante y deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos.","Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2327","name":"dumbbell reverse grip row (female)","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/2327-Nh3mvOO.jpg","gif_url":"videos/2327-Nh3mvOO.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","החזיקו משקולת יד בכל יד באחיזה עליונה, כפות ידיים פונות לגוף.","הטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר וליבה מופעלת.","תנו לידיים להשתלשל ישר מטה, מתוחות לגמרי, עם כיפוף קל במרפקים.","משכו את המשקולות למעלה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with an overhand grip, palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Let your arms hang straight down, fully extended, with a slight bend in your elbows.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Возьмите по гантели в каждую руку хватом сверху, ладонями к телу.","Наклонитесь вперед в талии, сохраняя спину прямой и напрягая корпус.","Пусть ваши руки свисают прямо вниз, полностью выпрямлены, слегка согнуты в локтях.","Подтяните гантели к груди, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tu cuerpo.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.","Deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos, con una ligera flexión en los codos.","Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0384","name":"dumbbell reverse preacher curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0384-O8Aq69u.jpg","gif_url":"videos/0384-O8Aq69u.gif","instruction_steps":{"he":["שבו על ספסל פריצ'ר כשהזרועות העליונות מונחות על הכרית והחזה צמוד למשענת.","החזיקו משקולת יד בכל יד באחיזה תחתונה, כפות ידיים כלפי מעלה.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המשקולות תוך כיווץ הבייספס.","המשיכו לכופף את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Hold a dumbbell in each hand with an underhand grip, palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps.","Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью для проповедника, положив плечи на подушку и грудь на опору.","Возьмите в каждую руку по гантели обратным хватом ладонями вверх.","Удерживая плечи неподвижно, выдохните и согните гантели, сокращая бицепсы.","Продолжайте сгибать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte.","Sujeta una mancuerna en cada mano con agarre supino, con las palmas hacia arriba.","Manteniendo la parte superior de los brazos fija, exhala y flexiona las mancuernas mientras contraes los bíceps.","Continúa flexionando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1675","name":"dumbbell reverse spider curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1675-6sMAmNv.jpg","gif_url":"videos/1675-6sMAmNv.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות לגוף וידיים ישרות לגמרי.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, взяв в каждую руку по гантели, ладони обращены к телу, руки полностью выпрямлены.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con la espalda recta, con una mancuerna en cada mano, las palmas hacia tu cuerpo y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0385","name":"dumbbell reverse wrist curl","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0385-BLCvwr2.jpg","gif_url":"videos/0385-BLCvwr2.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם כפות רגליים על הרצפה.","החזיקו משקולת יד בכל יד באחיזה עליונה, כפות ידיים כלפי מטה.","הניחו את האמות על הירכיים, כששורשי כף היד משתלשלים מעבר לקצה.","גלגלו באיטיות את שורשי כף היד כלפי מעלה, בהבאת המשקולות לכיוון הגוף.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью или стул, поставив ноги на землю.","Возьмите по гантели в каждую руку хватом сверху, ладонями вниз.","Положите предплечья на бедра, позволяя запястьям свисать с края.","Медленно поднимите запястья вверх, приближая гантели к телу.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco o silla con los pies apoyados en el suelo.","Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia abajo.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1459","name":"dumbbell romanian deadlift","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1459-rR0LJzx.jpg","gif_url":"videos/1459-rR0LJzx.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד באחיזה עליונה.","תוך שמירה על גב ישר וליבה מופעלת, הטו את הגו מהירכיים והורידו את המשקולות לכיוון הרצפה, עם כיפוף קל בברכיים.","הורידו את המשקולות עד שתרגישו מתיחה בירך האחורית, ואז דחפו דרך העקבים והפעילו את הישבן כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly.","Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите по гантели в каждой руке хватом сверху.","Удерживая спину прямой, а корпус напряженным, наклонитесь в бедрах и опустите гантели к земле, слегка согнув колени.","Опускайте гантели до тех пор, пока не почувствуете растяжение подколенных сухожилий, затем надавите на пятки и задействуйте ягодицы, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que las rodillas se flexionen ligeramente.","Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego empuja con los talones y activa los glúteos para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0386","name":"dumbbell rotation reverse fly","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0386-prbWx1D.jpg","gif_url":"videos/0386-prbWx1D.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד, כפות ידיים פונות פנימה.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וחזה מורם.","הרימו את הידיים לצדדים, עם כיפוף קל במרפקים, עד שהן מקבילות לרצפה.","סובבו את הידיים כך שכפות הידיים פונות כלפי מטה.","הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Rotate your arms so that your palms are facing downwards.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями внутрь.","Слегка согните колени и наклонитесь вперед в бедрах, держа спину прямо и грудь вверх.","Поднимите руки в стороны, сохраняя небольшой изгиб в локтях, пока они не станут параллельны полу.","Поверните руки так, чтобы ладони были направлены вниз.","Медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adentro.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.","Gira los brazos de modo que las palmas queden mirando hacia abajo.","Baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2397","name":"dumbbell scott press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/2397-5vfAI0I.jpg","gif_url":"videos/2397-5vfAI0I.gif","instruction_steps":{"he":["שבו על ספסל עם משקולת יד בכל יד, כפות ידיים פונות קדימה.","הרימו את המשקולות לגובה הכתפיים, עם מרפקים כפופים וכפות ידיים פונות קדימה.","לחצו את המשקולות כלפי מעלה עד יישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, взяв в каждую руку по гантели ладонями вперед.","Поднимите гантели на высоту плеч, согнув локти и повернув ладони вперед.","Выжмите гантели вверх, пока руки полностью не выпрямятся.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante.","Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.","Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0387","name":"dumbbell seated alternate front raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","biceps"],"target":"delts","image":"images/0387-gH5fRsC.jpg","gif_url":"videos/0387-gH5fRsC.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו משקולת יד בכל יד, כפות ידיים פונות לגוף וידיים מתוחות לצידי הגוף.","תוך שמירה על ידיים ישרות, הרימו משקולת אחת לפניכם עד שהיא מקבילה לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה עם היד השנייה.","החליפו בין הידיים לסירוגין למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.","Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите по гантели в каждую руку ладонями к телу, а руки вытяните вниз по бокам.","Держа руки прямыми, поднимите одну гантель перед собой до тех пор, пока она не станет параллельна земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите с другой рукой.","Чередуйте руки, выполняя желаемое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos extendidos hacia abajo a los lados.","Manteniendo los brazos rectos, levanta una mancuerna frente a ti hasta que quede paralela al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite con el otro brazo.","Alterna entre los brazos el número de repeticiones deseado."]}},{"id":"1676","name":"dumbbell seated alternate hammer curl on exercise ball","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1676-QLRmNeT.jpg","gif_url":"videos/1676-QLRmNeT.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד בכל יד, כפות ידיים פונות לגוף וידיים ישרות לגמרי.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו משקולת אחת למעלה לכיוון הכתף, כשכף היד פונה לגוף.","המשיכו להרים את המשקולת עד שהבייספס מכווץ במלואו והמשקולת בגובה הכתף.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה עם היד הנגדית.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину.","Возьмите по гантели в каждую руку ладонями к телу и полностью выпрямленными руками.","Удерживая плечи неподвижно, выдохните и согните одну гантель к плечу, держа ладонь к телу.","Продолжайте поднимать гантель до тех пор, пока ваши бицепсы полностью не сократятся и гантель не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно опустите гантель обратно в исходное положение.","Повторите движение противоположной рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos.","Manteniendo la parte superior de los brazos fija, exhala y flexiona una mancuerna hacia el hombro mientras mantienes la palma hacia tu cuerpo.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el movimiento con el brazo contrario.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"0388","name":"dumbbell seated alternate press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0388-QT5Q0nK.jpg","gif_url":"videos/0388-QT5Q0nK.gif","instruction_steps":{"he":["שבו על ספסל עם משקולת יד בכל יד, כפות ידיים פונות קדימה.","הרימו את המשקולות לגובה הכתפיים, עם מרפקים כפופים וכפות ידיים פונות קדימה.","לחצו משקולת אחת למעלה מעל הראש, עד יישור מלא של היד.","הורידו את המשקולת חזרה לגובה הכתף.","חזרו על התנועה עם היד השנייה.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press one dumbbell up overhead, fully extending your arm.","Lower the dumbbell back down to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Сядьте на скамью, взяв в каждую руку по гантели ладонями вперед.","Поднимите гантели на высоту плеч, согнув локти и повернув ладони вперед.","Выжмите одну гантель над головой, полностью выпрямляя руку.","Опустите гантель обратно на высоту плеч.","Повторите с другой рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante.","Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.","Presiona una mancuerna hacia arriba, por encima de la cabeza, extendiendo completamente el brazo.","Baja la mancuerna de vuelta a la altura de los hombros.","Repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"3546","name":"dumbbell seated alternate shoulder","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/3546-q7qkONO.jpg","gif_url":"videos/3546-q7qkONO.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו משקולת יד בכל יד, כפות ידיים פונות פנימה, והרימו אותן לגובה הכתפיים.","לחצו משקולת אחת למעלה מעל הראש, תוך שמירה על המשקולת השנייה בגובה הכתף.","הורידו את המשקולת המורמת חזרה לגובה הכתף ובו-זמנית לחצו את המשקולת השנייה מעל הראש.","המשיכו להחליף בין הידיים למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.","Press one dumbbell up overhead while keeping the other dumbbell at shoulder height.","Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead.","Continue alternating between arms for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите по гантели в каждую руку ладонями внутрь и поднимите их на высоту плеч.","Поднимите одну гантель над головой, удерживая другую на уровне плеч.","Опустите поднятую гантель обратно на высоту плеч, одновременно поднимая другую гантель над головой.","Продолжайте чередовать руки необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna en cada mano, con las palmas hacia adentro, y levántalas a la altura de los hombros.","Presiona una mancuerna hacia arriba, por encima de la cabeza, mientras mantienes la otra mancuerna a la altura de los hombros.","Baja la mancuerna levantada de vuelta a la altura de los hombros mientras presionas simultáneamente la otra mancuerna por encima de la cabeza.","Continúa alternando entre los brazos durante el número de repeticiones deseado."]}},{"id":"0389","name":"dumbbell seated bench extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0389-JhYSVwT.jpg","gif_url":"videos/0389-JhYSVwT.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו משקולת יד בשתי הידיים ומתחו את הידיים ישר מעל הראש.","הורידו באיטיות את המשקולת מאחורי הראש, תוך שמירה על מרפקים קרובים לאוזניים.","עצרו לרגע, ואז הרימו את המשקולת חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up above your head.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите гантель обеими руками и вытяните руки прямо над головой.","Медленно опустите гантель за голову, держа локти близко к ушам.","Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza.","Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas.","Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2317","name":"dumbbell seated bent arm lateral raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/2317-JzQbv7J.jpg","gif_url":"videos/2317-JzQbv7J.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו משקולת יד בכל יד, כפות ידיים פונות לגוף וידיים כפופות בזווית של 90 מעלות.","עם מרפקים כפופים, הרימו את הידיים לצדדים עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.","Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите по гантели в каждую руку ладонями к телу, руки согнуты под углом 90 градусов.","Сохраняя локти согнутыми, поднимите руки в стороны, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos flexionados en un ángulo de 90 grados.","Manteniendo los codos flexionados, levanta los brazos hacia los lados hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1730","name":"dumbbell seated bent over alternate kickback","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"triceps","image":"images/1730-x0lwvfq.jpg","gif_url":"videos/1730-x0lwvfq.gif","instruction_steps":{"he":["שבו על ספסל עם משקולת יד בכל יד, כפות ידיים פונות פנימה.","הטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר ומקביל לרצפה.","יישרו יד אחת ישר לאחור, קרוב לגוף, עד יישור מלא של היד.","עצרו לרגע, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה עם היד השנייה.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Sit on a bench with a dumbbell in each hand, palms facing inwards.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend one arm straight back, keeping it close to your body, until your arm is fully extended.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Сядьте на скамью, взяв в каждую руку по гантели ладонями внутрь.","Наклонитесь вперед в талии, сохраняя спину прямой и параллельной земле.","Вытяните одну руку прямо назад, держа ее близко к телу, пока рука не выпрямится полностью.","Сделайте паузу на мгновение, затем медленно опустите гантель обратно в исходное положение.","Повторите с другой рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adentro.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo.","Extiende un brazo recto hacia atrás, manteniéndolo cerca de tu cuerpo, hasta que el brazo esté completamente extendido.","Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"1737","name":"dumbbell seated bent over triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"triceps","image":"images/1737-4ievMJ9.jpg","gif_url":"videos/1737-4ievMJ9.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו משקולת יד בכל יד.","הטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר וראש מורם.","יישרו את הידיים ישר לאחור, תוך שמירה על מרפקים קרובים לראש.","עצרו לרגע, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your head up.","Extend your arms straight back, keeping your elbows close to your head.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в каждую руку по гантели.","Наклонитесь вперед в талии, держа спину прямо и голову вверх.","Вытяните руки прямо назад, держа локти близко к голове.","Сделайте паузу на мгновение, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y la cabeza erguida.","Extiende los brazos rectos hacia atrás, manteniendo los codos cerca de la cabeza.","Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1677","name":"dumbbell seated bicep curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1677-xiA6lRr.jpg","gif_url":"videos/1677-xiA6lRr.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו משקולת יד בכל יד, כפות ידיים כלפי מעלה.","שמרו על גב ישר ומרפקים צמודים לגו.","נשפו וכופפו את המשקולות למעלה לכיוון הכתפיים, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в каждую руку по гантели ладонями вверх.","Держите спину прямо, а локти близко к туловищу.","Выдохните и поднимите гантели к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.","Mantén la espalda recta y los codos cerca del torso.","Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0390","name":"dumbbell seated biceps curl (on stability ball)","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0390-WgJnBH5.jpg","gif_url":"videos/0390-WgJnBH5.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד בכל יד, כפות ידיים פונות קדימה וידיים ישרות לגמרי.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המשקולות תוך כיווץ הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч, поставив ноги на землю и выпрямив спину.","Возьмите в каждую руку по гантели ладонями вперед и полностью выпрямленными руками.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно напрягая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.","Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3547","name":"dumbbell seated biceps curl to shoulder press","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"biceps","image":"images/3547-OeL23VY.jpg","gif_url":"videos/3547-OeL23VY.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו משקולת יד בכל יד עם כפות ידיים פונות קדימה וידיים מתוחות לגמרי.","תוך שמירה על מרפקים צמודים לצידי הגוף, כופפו את המשקולות למעלה לכיוון הכתפיים.","כשהאמות אנכיות, סובבו את שורשי כף היד כך שכפות הידיים פונות קדימה.","לחצו את המשקולות מעל הראש עד יישור מלא של הידיים.","הורידו את המשקולות חזרה לנקודת ההתחלה בהיפוך התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing forward and arms fully extended.","Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders.","Once your forearms are vertical, rotate your wrists so that your palms are facing forward.","Press the dumbbells overhead until your arms are fully extended.","Lower the dumbbells back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите по гантели в каждую руку ладонями вперед и полностью выпрямленными руками.","Держа локти близко к бокам, поднимите гантели к плечам.","Как только предплечья станут вертикальными, поверните запястья так, чтобы ладони смотрели вперед.","Выжмите гантели над головой, пока руки полностью не выпрямятся.","Опустите гантели обратно в исходное положение, выполняя движение в обратном направлении.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los codos cerca de tus costados, flexiona las mancuernas hacia los hombros.","Una vez que tus antebrazos estén verticales, gira las muñecas de modo que las palmas queden hacia adelante.","Presiona las mancuernas por encima de la cabeza hasta que los brazos estén completamente extendidos.","Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento.","Repite el número de repeticiones deseado."]}},{"id":"1379","name":"dumbbell seated calf raise","category":"lower legs","body_part":"lower legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1379-r29jP7S.jpg","gif_url":"videos/1379-r29jP7S.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם כפות רגליים על הרצפה ומשקולת יד מונחת על הירכיים.","הניחו את כריות כפות הרגליים על משטח מוגבה כמו מדרגה או קופסה, כשהעקבים משתלשלים מעבר לקצה.","אחזו במשקולת לייצוב.","הרימו את העקבים גבוה ככל האפשר, בהעברת משקל הגוף לכריות כפות הרגליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.","Hold onto the dumbbell for stability.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью или стул, поставьте ступни на землю и положите гантель на бедра.","Поставьте подушечки стоп на приподнятую поверхность, например, на ступеньку или блок, так, чтобы пятки свисали с края.","Держитесь за гантель для устойчивости.","Поднимите пятки как можно выше, перенеся вес тела на подушечки стоп.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos.","Coloca la punta de los pies sobre una superficie elevada, como un escalón o un bloque, con los talones colgando del borde.","Sujétate de la mancuerna para mantener la estabilidad.","Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0391","name":"dumbbell seated curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0391-TiaZTxx.jpg","gif_url":"videos/0391-TiaZTxx.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה ומשקולת יד בכל יד, כפות ידיים פונות קדימה.","שמרו על גב ישר ומרפקים צמודים לגו.","נשפו וכופפו את המשקולות למעלה לכיוון הכתפיים, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ступни на землю и возьмите в каждую руку по гантели, ладонями вперед.","Держите спину прямо, а локти близко к туловищу.","Выдохните и поднимите гантели к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, con las palmas hacia adelante.","Mantén la espalda recta y los codos cerca del torso.","Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0392","name":"dumbbell seated front raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","biceps"],"target":"delts","image":"images/0392-Ys97II0.jpg","gif_url":"videos/0392-Ys97II0.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה ומשקולת יד בכל יד, מונחות על הירכיים.","שמרו על גב ישר וליבה מופעלת.","הרימו את המשקולות לפניכם, עם כפות ידיים כלפי מטה, עד גובה הכתפיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в каждую руку по гантели, положив их на бедра.","Держите спину прямо и напрягите корпус.","Поднимите гантели перед собой ладонями вниз, пока они не окажутся на уровне плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.","Mantén la espalda recta y el core activado.","Levanta las mancuernas frente a ti, con las palmas hacia abajo, hasta que queden a la altura de los hombros.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1678","name":"dumbbell seated hammer curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1678-IGtBdNT.jpg","gif_url":"videos/1678-IGtBdNT.gif","instruction_steps":{"he":["שבו על ספסל עם משקולת יד בכל יד, כפות ידיים פונות לגוף וידיים ישרות כלפי מטה.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, взяв в каждую руку по гантели, ладони обращены к туловищу, руки вытянуты прямо вниз.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos rectos hacia abajo.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0393","name":"dumbbell seated inner biceps curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0393-KXyoEtA.jpg","gif_url":"videos/0393-KXyoEtA.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו משקולת יד בכל יד, כפות ידיים כלפי מעלה.","השעינו את הזרועות העליונות על הירכיים, ותנו למשקולות להשתלשל מטה.","תוך שמירה על הזרועות העליונות ללא תזוזה, כופפו את המשקולות למעלה לכיוון הכתפיים בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your upper arms on your thighs, allowing the dumbbells to hang down.","Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в каждую руку по гантели ладонями вверх.","Положите плечи на бедра, позволяя гантелям свисать.","Удерживая плечи неподвижно, поднимите гантели к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.","Apoya la parte superior de los brazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo.","Manteniendo la parte superior de los brazos fija, flexiona las mancuernas hacia los hombros contrayendo los bíceps.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0394","name":"dumbbell seated kickback","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0394-en550rk.jpg","gif_url":"videos/0394-en550rk.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו משקולת יד בכל יד.","כופפו ברכיים מעט ורכנו קדימה מהירכיים, תוך שמירה על גב ישר.","הצמידו את הזרועות העליונות לצידי הגוף ושמרו על מרפקים כפופים בזווית של 90 מעלות.","יישרו את הידיים ישר לאחור, וכווצו את הטרייספס בנקודה העליונה של התנועה.","עצרו לרגע, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend your knees slightly and lean forward from your hips, keeping your back straight.","Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в каждую руку по гантели.","Слегка согните ноги в коленях и наклонитесь вперед от бедер, сохраняя спину прямой.","Поднесите плечи к бокам и держите локти согнутыми под углом 90 градусов.","Вытяните руки прямо назад, сжимая трицепсы в верхней точке движения.","Сделайте паузу на мгновение, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Acerca la parte superior de los brazos a tus costados y mantén los codos flexionados en un ángulo de 90 grados.","Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.","Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0396","name":"dumbbell seated lateral raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","upper back"],"target":"delts","image":"images/0396-hxyTtWj.jpg","gif_url":"videos/0396-hxyTtWj.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה ומשקולת יד בכל יד, מונחות על הירכיים.","שמרו על גב ישר וליבה מופעלת.","הרימו את המשקולות לצדדים עם כיפוף קל במרפקים, עד שהידיים מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в каждую руку по гантели, положив их на бедра.","Держите спину прямо и напрягите корпус.","Поднимите гантели в стороны, слегка согнув локти, пока руки не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.","Mantén la espalda recta y el core activado.","Levanta las mancuernas hacia los lados con una ligera flexión en los codos, hasta que tus brazos queden paralelos al suelo.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0395","name":"dumbbell seated lateral raise v. 2","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","triceps"],"target":"delts","image":"images/0395-hrrS0Ed.jpg","gif_url":"videos/0395-hrrS0Ed.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה ומשקולת יד בכל יד, מונחות על הירכיים.","שמרו על גב ישר וליבה מופעלת.","הרימו את המשקולות לצדדים עם כיפוף קל במרפקים, עד שהידיים מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в каждую руку по гантели, положив их на бедра.","Держите спину прямо и напрягите корпус.","Поднимите гантели в стороны, слегка согнув локти, пока руки не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.","Mantén la espalda recta y el core activado.","Levanta las mancuernas hacia los lados con una ligera flexión en los codos, hasta que tus brazos queden paralelos al suelo.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0397","name":"dumbbell seated neutral wrist curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0397-uJmK7Z1.jpg","gif_url":"videos/0397-uJmK7Z1.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו משקולת יד בכל יד, כפות ידיים פונות זו לזו.","השעינו את האמות על הירכיים, ותנו למשקולות להשתלשל מטה.","תוך שמירה על שורשי כף יד בתנוחה ניטרלית, כופפו את המשקולות למעלה לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.","Rest your forearms on your thighs, allowing the dumbbells to hang down.","Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в каждую руку по гантели, ладони обращены друг к другу.","Положите предплечья на бедра, позволяя гантелям свисать.","Удерживая запястья в нейтральном положении, поднимите гантели к плечам.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas mirándose entre sí.","Apoya los antebrazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo.","Manteniendo las muñecas en posición neutra, flexiona las mancuernas hacia los hombros.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1679","name":"dumbbell seated one arm bicep curl on exercise ball with leg raised","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1679-84sESNy.jpg","gif_url":"videos/1679-84sESNy.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד ביד אחת, כף יד כלפי מעלה ויד ישרה לגמרי.","הניחו את היד השנייה על המותן לייצוב.","כופפו באיטיות את המשקולת לכיוון הכתף, תוך שמירה על הזרוע העליונה ללא תזוזה.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי.","החליפו ידיים וחזרו על התרגיל."],"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Place your other hand on your hip for stability.","Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."],"ru":["Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину.","Возьмите гантель в одну руку ладонью вверх и полностью выпрямите руку.","Вторую руку положите на бедро для устойчивости.","Медленно поднимите гантель к плечу, сохраняя плечо неподвижным.","Задержитесь на мгновение в верхней точке движения, сжимая бицепс.","Медленно опустите гантель обратно в исходное положение.","Повторите необходимое количество повторений.","Поменяйте руки и повторите упражнение."],"es":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido.","Coloca la otra mano en la cadera para mantener el equilibrio.","Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo.","Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps.","Baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de brazo y repite el ejercicio."]}},{"id":"0398","name":"dumbbell seated one arm kickback","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0398-VQ3sNCn.jpg","gif_url":"videos/0398-VQ3sNCn.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו משקולת יד ביד אחת.","הטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר ומקביל לרצפה.","יישרו את היד ישר לאחור, תוך שמירה על מרפק קרוב לגוף.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.","Bend your torso forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в одну руку гантель.","Наклоните туловище вперед в талии, сохраняя спину прямой и параллельной земле.","Вытяните руку прямо назад, держа локоть близко к телу.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano.","Inclina el torso hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo.","Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0399","name":"dumbbell seated one arm rotate","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","biceps"],"target":"forearms","image":"images/0399-7f2jsqP.jpg","gif_url":"videos/0399-7f2jsqP.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר והחזיקו משקולת יד ביד אחת, מונחת על הירך.","הרימו את המשקולת לגובה הכתף, תוך שמירה על מרפק קרוב לגוף.","סובבו את האמה החוצה, הרחק מהגוף, תוך שמירה על הזרוע העליונה ללא תזוזה.","עצרו לרגע בנקודה העליונה, ואז סובבו באיטיות את האמה חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.","Raise the dumbbell up to shoulder height, keeping your elbow close to your body.","Rotate your forearm outward, away from your body, while keeping your upper arm stationary.","Pause for a moment at the top, then slowly rotate your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Сядьте на скамью с прямой спиной и возьмите в одну руку гантель, положив ее на бедро.","Поднимите гантель до уровня плеч, держа локоть близко к телу.","Поверните предплечье наружу, от тела, сохраняя при этом плечо неподвижным.","Задержитесь на мгновение в верхней точке, затем медленно поверните предплечье обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Siéntate en un banco con la espalda recta y sujeta una mancuerna con una mano, apoyándola sobre el muslo.","Sube la mancuerna hasta la altura del hombro, manteniendo el codo cerca de tu cuerpo.","Gira el antebrazo hacia afuera, alejándolo de tu cuerpo, mientras mantienes fija la parte superior del brazo.","Haz una pausa por un momento en la parte superior, luego gira lentamente el antebrazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0400","name":"dumbbell seated one leg calf raise","category":"lower legs","body_part":"lower legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/0400-Ia7tumC.jpg","gif_url":"videos/0400-Ia7tumC.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם כפות רגליים על הרצפה ומשקולת יד מונחת על ירך ימין.","מתחו את רגל שמאל ישר לפניכם, עם כף רגל מכופפת.","הניחו את כרית כף רגל ימין על משטח מוגבה, כמו מדרגה או פלטת משקל.","בעזרת שרירי התאומים, הרימו את עקב ימין גבוה ככל האפשר.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקב באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh.","Extend your left leg straight out in front of you, keeping your foot flexed.","Place the ball of your right foot on an elevated surface, such as a step or weight plate.","Using your calf muscles, raise your right heel as high as possible.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Сядьте на скамью или стул, поставьте ступни на землю и положите гантель на правое бедро.","Вытяните левую ногу прямо перед собой, сохраняя ступню согнутой.","Поставьте подушечку правой стопы на возвышенную поверхность, например на ступеньку или блин.","Используя икроножные мышцы, поднимите правую пятку как можно выше.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятку обратно в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre el muslo derecho.","Extiende la pierna izquierda recta hacia adelante, manteniendo el pie flexionado.","Coloca la punta del pie derecho sobre una superficie elevada, como un escalón o un disco de peso.","Usando los músculos de la pantorrilla, eleva el talón derecho lo más alto posible.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"1380","name":"dumbbell seated one leg calf raise - hammer grip","category":"lower legs","body_part":"lower legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1380-FxhcxUW.jpg","gif_url":"videos/1380-FxhcxUW.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם כפות רגליים על הרצפה ומשקולת יד מונחת על הירכיים.","הניחו כף רגל אחת על משטח מוגבה, כמו מדרגה או בלוק, כשהעקב משתלשל מעבר לקצה.","החזיקו את המשקולת באחיזת פטיש — כפות הידיים פונות זו לזו והאצבעות עוטפות את הידית.","תוך שמירה על ליבה מופעלת וגב ישר, הרימו באיטיות את העקב גבוה ככל האפשר בדחיפה דרך כרית כף הרגל.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקב באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו לרגל השנייה."],"en":["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.","Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.","Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."],"ru":["Сядьте на скамью или стул, поставьте ступни на землю и положите гантель на бедра.","Поставьте одну ногу на возвышение, например на ступеньку или блок, свесив пятку с края.","Держите гантель молоткообразным хватом, то есть ладони обращены друг к другу, а пальцы обхватывают рукоятку.","Удерживая корпус напряженным, а спину прямой, медленно поднимите пятку как можно выше, толкая подушечки стопы.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятку обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую ногу."],"es":["Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos.","Coloca un pie sobre una superficie elevada, como un escalón o un bloque, con el talón colgando del borde.","Sujeta la mancuerna con agarre neutro, es decir, con las palmas mirándose entre sí y los dedos envolviendo la barra.","Manteniendo el core activado y la espalda recta, eleva lentamente el talón lo más alto posible empujando con la punta del pie.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia a la otra pierna."]}},{"id":"1381","name":"dumbbell seated one leg calf raise - palm up","category":"lower legs","body_part":"lower legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1381-VW88JNd.jpg","gif_url":"videos/1381-VW88JNd.gif","instruction_steps":{"he":["שבו על ספסל או כיסא עם גב ישר וכפות רגליים על הרצפה.","החזיקו משקולת יד ביד אחת והניחו אותה על הירך, כף יד כלפי מעלה.","הרימו רגל אחת מהרצפה ומתחו אותה לפניכם, עם ברך כפופה מעט.","הרימו את העקב גבוה ככל האפשר בדחיפה דרך כרית כף הרגל.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקב באיטיות חזרה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגליים וחזרו על התרגיל."],"en":["Sit on a bench or chair with your back straight and your feet flat on the ground.","Hold a dumbbell in one hand and place it on top of your thigh, palm facing up.","Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent.","Raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs and repeat."],"ru":["Сядьте на скамью или стул, выпрямив спину и поставив ноги на землю.","Возьмите гантель в одну руку и положите ее на бедро ладонью вверх.","Поднимите одну ногу от земли и вытяните ее перед собой, слегка согнув колено.","Поднимите пятку как можно выше, толкая подушечку стопы.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятку обратно вниз.","Повторите необходимое количество повторений, затем поменяйте ногу и повторите."],"es":["Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo.","Sujeta una mancuerna con una mano y colócala sobre el muslo, con la palma hacia arriba.","Levanta una pierna del suelo y extiéndela frente a ti, manteniendo la rodilla ligeramente flexionada.","Eleva el talón lo más alto posible empujando con la punta del pie.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."]}},{"id":"0401","name":"dumbbell seated palms up wrist curl","category":"lower arms","body_part":"lower arms","equipment":"dumbbell","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/0401-2dImyQ8.jpg","gif_url":"videos/0401-2dImyQ8.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו משקולת יד בכל יד, כפות ידיים כלפי מעלה.","הניחו את האמות על הירכיים, כששורשי כף היד משתלשלים מעבר לקצה.","גלגלו באיטיות את שורשי כף היד כלפי מעלה, בכיווץ האמות בנקודה העליונה של התנועה.","עצרו לרגע, ואז הורידו את שורשי כף היד חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в каждую руку по гантели ладонями вверх.","Положите предплечья на бедра, позволяя запястьям свисать с края.","Медленно поднимите запястья вверх, сжимая предплечья в верхней точке движения.","Сделайте паузу на мгновение, затем опустите запястья обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento.","Haz una pausa por un momento y luego baja las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0402","name":"dumbbell seated preacher curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0402-7D5bgLT.jpg","gif_url":"videos/0402-7D5bgLT.gif","instruction_steps":{"he":["שבו על ספסל פריצ'ר עם כפות רגליים על הרצפה.","החזיקו משקולת יד ביד אחת באחיזה תחתונה, כשהזרוע העליונה נשענת על כרית הפריצ'ר.","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את המשקולת למעלה לכיוון הכתף.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a preacher curl bench with your feet flat on the floor.","Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью для проповедника, поставив ноги на пол.","Держите гантель в одной руке обратным хватом, опираясь плечом на коврик для проповедника.","Удерживая плечо неподвижно, выдохните и поднимите гантель к плечу.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco scott con los pies apoyados en el suelo.","Sujeta una mancuerna con una mano con agarre supino, apoyando la parte superior del brazo en la almohadilla del banco scott.","Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0403","name":"dumbbell seated revers grip concentration curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0403-lyKCLmK.jpg","gif_url":"videos/0403-lyKCLmK.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו משקולת יד ביד אחת, כף יד כלפי מעלה.","השעינו את המרפק על החלק הפנימי של הירך, מעט מעל הברך.","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את המשקולת לכיוון הכתף.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите в одну руку гантель ладонью вверх.","Положите локоть на внутреннюю часть бедра, чуть выше колена.","Удерживая плечо неподвижно, выдохните и согните гантель к плечу.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba.","Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.","Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1738","name":"dumbbell seated reverse grip one arm overhead tricep extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1738-5fKX7wi.jpg","gif_url":"videos/1738-5fKX7wi.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו משקולת יד באחיזה תחתונה ומתחו את היד ישר מעל הראש.","הורידו את המשקולת מאחורי הראש בכיפוף המרפק, תוך שמירה על הזרוע העליונה ללא תזוזה.","עצרו לרגע, ואז יישרו את היד חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with an underhand grip and extend your arm straight up overhead.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Pause for a moment, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите гантель обратным хватом и вытяните руку прямо над головой.","Опустите гантель за голову, согнув локоть, сохраняя плечо неподвижным.","Сделайте паузу на мгновение, затем вытяните руку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna con agarre supino y extiende el brazo recto por encima de la cabeza.","Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto.","Haz una pausa por un momento, luego extiende el brazo de vuelta hacia arriba, hasta la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0405","name":"dumbbell seated shoulder press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0405-znQUdHY.jpg","gif_url":"videos/0405-znQUdHY.gif","instruction_steps":{"he":["שבו על ספסל עם משקולת יד בכל יד, מונחות על הירכיים.","הרימו את המשקולות לגובה הכתפיים, כפות ידיים פונות קדימה.","לחצו את המשקולות כלפי מעלה עד יישור מלא של הידיים מעל הראש.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with a dumbbell in each hand, resting on your thighs.","Raise the dumbbells to shoulder height, palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, взяв в каждую руку по гантели, положив их на бедра.","Поднимите гантели на высоту плеч, ладони смотрят вперед.","Выжмите гантели вверх, пока руки полностью не выпрямятся над головой.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно на высоту плеч.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con una mancuerna en cada mano, apoyadas en los muslos.","Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.","Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"0404","name":"dumbbell seated shoulder press (parallel grip)","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0404-f1jf47L.jpg","gif_url":"videos/0404-f1jf47L.gif","instruction_steps":{"he":["שבו על ספסל עם משקולת יד בכל יד, כפות ידיים פונות פנימה.","הרימו את המשקולות לגובה הכתפיים, מרפקים כפופים וכפות ידיים פונות קדימה.","לחצו את המשקולות כלפי מעלה עד יישור מלא של הידיים מעל הראש.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with a dumbbell in each hand, palms facing inward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, взяв в каждую руку по гантели ладонями внутрь.","Поднимите гантели на высоту плеч, локти согнуты, ладони обращены вперед.","Выжмите гантели вверх, пока руки полностью не выпрямятся над головой.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно на высоту плеч.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adentro.","Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.","Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"2188","name":"dumbbell seated triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/2188-kont8Ut.jpg","gif_url":"videos/2188-kont8Ut.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו משקולת יד בשתי הידיים ומתחו את הידיים ישר מעל הראש.","כופפו מרפקים והורידו את המשקולת מאחורי הראש, תוך שמירה על הזרועות העליונות צמודות לאוזניים.","עצרו לרגע, ואז יישרו את הידיים וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up overhead.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Pause for a moment, then straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите гантель обеими руками и вытяните руки прямо над головой.","Согните руки в локтях и опустите гантель за голову, держа плечи близко к ушам.","Сделайте паузу на мгновение, затем выпрямите руки и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza.","Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.","Haz una pausa por un momento, luego endereza los brazos y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0406","name":"dumbbell shrug","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0406-NJzBsGJ.jpg","gif_url":"videos/0406-NJzBsGJ.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד עם כפות ידיים פונות לגוף.","שמרו על ידיים ישרות ותנו למשקולות להשתלשל לצידי הגוף.","הרימו את הכתפיים גבוה ככל האפשר, כאילו אתם מנסים לגעת באוזניים עם הכתפיים.","החזיקו את הכיווץ שנייה, ואז הורידו את הכתפיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Keep your arms straight and let the dumbbells hang by your sides.","Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders.","Hold the contraction for a second, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями к телу.","Держите руки прямо и позвольте гантелям висеть по бокам.","Поднимите плечи как можно выше, как будто пытаетесь коснуться плечами ушей.","Удерживайте напряжение в течение секунды, затем медленно опустите плечи обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.","Mantén los brazos rectos y deja que las mancuernas cuelguen a tus costados.","Eleva los hombros lo más alto posible, como si intentaras tocarte las orejas con ellos.","Mantén la contracción durante un segundo, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0407","name":"dumbbell side bend","category":"waist","body_part":"waist","equipment":"dumbbell","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0407-IpONWYv.jpg","gif_url":"videos/0407-IpONWYv.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו משקולת יד ביד אחת, משתלשלת לצד הגוף.","תוך שמירה על גב ישר וליבה מופעלת, הטו באיטיות את הגו הצידה לכיוון הנגדי למשקולת, בהורדת המשקל רחוק ככל שנוח לכם.","עצרו לרגע, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד וחזרו על התרגיל."],"en":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side.","Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите в одну руку гантель и позвольте ей свисать сбоку.","Удерживая спину прямой и напрягая корпус, медленно согнитесь в талии в сторону противоположной стороны гантели, опуская вес настолько, насколько вам удобно.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений, затем поменяйте сторону и повторите."],"es":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano y dejando que cuelgue a tu costado.","Manteniendo la espalda recta y el core activado, inclínate lentamente hacia el lado opuesto de la mancuerna, bajando el peso tanto como te sea posible con comodidad.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado y repite."]}},{"id":"0408","name":"dumbbell side lying one hand raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0408-fTlkJop.jpg","gif_url":"videos/0408-fTlkJop.gif","instruction_steps":{"he":["שכבו על הצד עם רגליים ישרות והראש נתמך על היד.","החזיקו משקולת יד ביד העליונה, כף יד כלפי מטה.","תוך שמירה על יד ישרה, הרימו את המשקולת לגובה הכתף.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Lie on your side with your legs extended and your head supported by your arm.","Hold a dumbbell in your top hand with your palm facing down.","Keeping your arm straight, raise the dumbbell up to shoulder height.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Лягте на бок, вытянув ноги и подперев голову рукой.","Держите гантель в верхней руке ладонью вниз.","Держа руку прямой, поднимите гантель до уровня плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo.","Sujeta una mancuerna con la mano de arriba, con la palma hacia abajo.","Manteniendo el brazo recto, sube la mancuerna hasta la altura del hombro.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"3664","name":"dumbbell side plank with rear fly","category":"back","body_part":"back","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"upper back","image":"images/3664-X6ytgYZ.jpg","gif_url":"videos/3664-X6ytgYZ.gif","instruction_steps":{"he":["התחילו בשכיבה על הצד עם רגליים מתוחות זו על גבי זו.","הניחו את האמה על הרצפה ישר מתחת לכתף, תוך שמירה על מרפק כפוף בזווית של 90 מעלות.","החזיקו משקולת יד ביד העליונה, עם היד מתוחה ישר מטה לכיוון הרצפה.","הפעילו את הליבה והרימו את האגן מהרצפה, ביצירת קו ישר מהראש ועד העקבים.","תוך שמירה על תנוחת הפלאנק הצדי, הרימו את המשקולת למעלה לכיוון התקרה, בכיווץ השכמות זו לזו.","הורידו את המשקולת חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.","Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.","Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.","While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Начните с того, что лягте на бок, вытянув ноги и положив их друг на друга.","Положите предплечье на землю прямо под плечом, держа локоть согнутым под углом 90 градусов.","Держите гантель в верхней руке, вытянув руку прямо вниз к земле.","Напрягите корпус и поднимите бедра от земли, создавая прямую линию от головы до пяток.","Сохраняя положение боковой планки, поднимите гантель к потолку, сведя лопатки вместе.","Опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.","Coloca el antebrazo en el suelo, justo debajo del hombro, manteniendo el codo flexionado en un ángulo de 90 grados.","Sujeta una mancuerna con la mano de arriba, con el brazo extendido recto hacia el suelo.","Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los talones.","Manteniendo la posición de plancha lateral, levanta la mancuerna hacia el techo, apretando los omóplatos entre sí.","Baja la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"3548","name":"dumbbell single arm overhead carry","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","core"],"target":"delts","image":"images/3548-mWBtgmb.jpg","gif_url":"videos/3548-mWBtgmb.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים, אוחזים משקולת יד ביד אחת.","הרימו את המשקולת מעל הראש, עד יישור מלא של היד.","הפעילו את הליבה ושמרו על גב ישר תוך הליכה קדימה, כשהמשקולת נשארת מעל הראש.","המשיכו ללכת למרחק או לזמן הרצוי.","החליפו ידיים וחזרו על התרגיל."],"en":["Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead.","Continue walking for the desired distance or time.","Switch hands and repeat the exercise."],"ru":["Встаньте прямо, ноги на ширине плеч, в одной руке держите гантель.","Поднимите гантель над головой, полностью выпрямляя руку.","Напрягите корпус и держите спину прямо, когда идете вперед, удерживая гантель над головой.","Продолжайте идти желаемое расстояние или время.","Поменяйте руки и повторите упражнение."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano.","Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo.","Activa el core y mantén la espalda recta mientras caminas hacia adelante, sosteniendo la mancuerna por encima de la cabeza.","Continúa caminando durante la distancia o el tiempo deseado.","Cambia de mano y repite el ejercicio."]}},{"id":"0409","name":"dumbbell single leg calf raise","category":"lower legs","body_part":"lower legs","equipment":"dumbbell","muscle_group":"ankles","secondary_muscles":["ankles"],"target":"calves","image":"images/0409-1kB3Wmk.jpg","gif_url":"videos/0409-1kB3Wmk.gif","instruction_steps":{"he":["עמדו על קצה מדרגה או משטח כשהעקבים משתלשלים וקצות האצבעות של הרגליים על המדרגה.","החזיקו משקולת יד ביד אחת והניחו את היד השנייה על קיר או מעקה לתמיכה.","הרימו את העקב גבוה ככל האפשר, בהרמת הגוף על קצות האצבעות.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקב באיטיות חזרה מתחת למדרגה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו לרגל השנייה."],"en":["Stand on the edge of a step or platform with your heels hanging off and your toes on the step.","Hold a dumbbell in one hand and place your other hand on a wall or railing for support.","Raise your heel as high as possible, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heel back down below the step.","Repeat for the desired number of repetitions, then switch to the other leg."],"ru":["Встаньте на край ступеньки или платформы, свесив пятки и положив пальцы ног на ступеньку.","Возьмите гантель в одну руку, а другую руку положите на стену или перила для поддержки.","Поднимите пятку как можно выше, поднимая тело на носки.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятку обратно под ступеньку.","Повторите желаемое количество повторений, затем переключитесь на другую ногу."],"es":["Ponte de pie en el borde de un escalón o plataforma, con los talones colgando y la punta de los pies sobre el escalón.","Sujeta una mancuerna con una mano y coloca la otra mano sobre una pared o barandilla para apoyarte.","Eleva el talón lo más alto posible, levantando el cuerpo sobre la punta de los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón por debajo del nivel del escalón.","Repite el número de repeticiones deseado, luego cambia a la otra pierna."]}},{"id":"1757","name":"dumbbell single leg deadlift","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1757-gKozT8X.jpg","gif_url":"videos/1757-gKozT8X.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן, אוחזים משקולת יד ביד ימין.","העבירו את המשקל לרגל שמאל והרימו את כף רגל ימין מעט מהרצפה.","תוך שמירה על גב ישר, הטו את הגו מהירכיים והורידו את המשקולת לכיוון הרצפה.","בו-זמנית, מתחו את רגל ימין ישר לאחור, תוך שמירה על כיפוף קל בברך שמאל.","הורידו את המשקולת עד שהגו ורגל ימין מקבילים לרצפה.","עצרו לרגע, ואז הפעילו את הישבן והירך האחורית לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Shift your weight onto your left leg and lift your right foot slightly off the ground.","Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.","At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.","Lower the dumbbell until your torso and right leg are parallel to the ground.","Pause for a moment, then engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, в правой руке держите гантель.","Перенесите вес тела на левую ногу и слегка поднимите правую ногу от земли.","Сохраняя спину прямой, наклонитесь вперед в бедрах и опустите гантель к земле.","В то же время вытяните правую ногу прямо позади себя, сохраняя небольшой изгиб в левом колене.","Опускайте гантель до тех пор, пока туловище и правая нога не станут параллельны земле.","Сделайте паузу на мгновение, затем напрягите ягодицы и мышцы задней поверхности бедра, чтобы вернуться в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha.","Traslada tu peso a la pierna izquierda y levanta el pie derecho ligeramente del suelo.","Manteniendo la espalda recta, inclínate hacia adelante desde las caderas y baja la mancuerna hacia el suelo.","Al mismo tiempo, extiende la pierna derecha recta hacia atrás, manteniendo una ligera flexión en la rodilla izquierda.","Baja la mancuerna hasta que tu torso y tu pierna derecha queden paralelos al suelo.","Haz una pausa por un momento, luego activa los glúteos y los isquiotibiales para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"2805","name":"dumbbell single leg deadlift with stepbox support","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/2805-daBmy1Y.jpg","gif_url":"videos/2805-daBmy1Y.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן, אוחזים משקולת יד ביד ימין.","הניחו את כף רגל שמאל על מדרגה או משטח מוגבה מאחוריכם.","תוך שמירה על גב ישר וליבה מופעלת, הטו את הגו מהירכיים והורידו את המשקולת לכיוון הרצפה.","תוך כדי הורדת המשקולת, הרימו בו-זמנית את רגל שמאל לאחור, תוך שמירה על קו ישר מהראש ועד העקב.","הורידו את המשקולת עד לתחושת מתיחה בירך האחורית הימנית, ואז חזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Place your left foot on a stepbox or elevated surface behind you.","Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground.","As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel.","Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, в правой руке держите гантель.","Поставьте левую ногу на ступеньку или возвышенную поверхность позади себя.","Удерживая спину прямой и напряженным корпус, наклонитесь вперед в бедрах, опуская гантель к земле.","Опуская гантель, одновременно поднимите левую ногу позади себя, сохраняя прямую линию от головы до пятки.","Опускайте гантель до тех пор, пока не почувствуете растяжение правого задней поверхности бедра, затем вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha.","Coloca el pie izquierdo sobre un cajón de step o una superficie elevada detrás de ti.","Manteniendo la espalda recta y el core activado, inclínate hacia adelante desde las caderas, bajando la mancuerna hacia el suelo.","Mientras bajas la mancuerna, levanta al mismo tiempo la pierna izquierda detrás de ti, manteniendo una línea recta desde la cabeza hasta el talón.","Baja la mancuerna hasta sentir un estiramiento en el isquiotibial derecho, luego vuelve a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0410","name":"dumbbell single leg split squat","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0410-qx4fgX7.jpg","gif_url":"videos/0410-qx4fgX7.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד.","צעדו קדימה עם רגל אחת ומקמו את כפות הרגליים כך שהרגל הקדמית שטוחה על הרצפה והרגל האחורית מוגבהת על ספסל או מדרגה.","הורידו את הגוף בכיפוף הברך והירך הקדמיות, תוך שמירה על ברך אחורית כפופה מעט ועקב אחורי מורם.","המשיכו לרדת עד שהירך הקדמית מקבילה לרצפה, ואז דחפו דרך העקב הקדמי לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגליים וחזרו על התרגיל."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.","Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.","Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гантели.","Сделайте шаг вперед одной ногой и расположите ступни так, чтобы передняя ступня стояла ровно на земле, а задняя нога была приподнята на скамье или ступеньке.","Опустите тело, согнув переднее колено и бедро, сохраняя слегка согнутым заднее колено и заднюю пятку над землей.","Продолжайте опускаться до тех пор, пока переднее бедро не станет параллельно земле, затем оттолкнитесь передней пяткой, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу и повторите."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Da un paso hacia adelante con un pie y coloca los pies de modo que el pie delantero quede plano en el suelo y el pie trasero quede elevado sobre un banco o escalón.","Baja el cuerpo flexionando la rodilla y la cadera delanteras, manteniendo la rodilla trasera ligeramente flexionada y el talón trasero levantado del suelo.","Continúa bajando hasta que el muslo delantero quede paralelo al suelo, luego empuja con el talón delantero para volver a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."]}},{"id":"0411","name":"dumbbell single leg squat","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0411-H6ybluc.jpg","gif_url":"videos/0411-H6ybluc.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד.","מתחו רגל אחת קדימה והשאירו אותה מורמת לאורך כל התרגיל.","כופפו את רגל העמידה והורידו את הגוף כאילו אתם מתיישבים לאחור על כיסא.","שמרו על חזה מורם וגב ישר.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקב לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Extend one leg forward and keep it off the ground throughout the exercise.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Pause for a moment at the bottom, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гантели.","Вытяните одну ногу вперед и держите ее над землей на протяжении всего упражнения.","Согните стоящую ногу и опустите тело вниз, как будто садитесь на стул.","Держите грудь поднятой, а спину прямой.","Задержитесь на мгновение в нижней точке, затем оттолкнитесь пяткой, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Extiende una pierna hacia adelante y mantenla levantada del suelo durante todo el ejercicio.","Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla.","Mantén el pecho arriba y la espalda recta.","Haz una pausa por un momento en la posición más baja, luego empuja con el talón para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"0413","name":"dumbbell squat","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0413-HsvHqgf.jpg","gif_url":"videos/0413-HsvHqgf.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במשקולת יד בכל יד לצידי הגוף.","תוך שמירה על חזה מורם וליבה מופעלת, הורידו את הגוף בכיפוף ברכיים וירכיים, כאילו אתם מתיישבים לאחור על כיסא.","המשיכו לרדת עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа по гантели в каждой руке по бокам.","Удерживая грудь поднятой и напряженным корпусом, опустите тело вниз, сгибая колени и бедра, как будто садитесь на стул.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.","Manteniendo el pecho arriba y el core activado, baja el cuerpo flexionando las rodillas y las caderas, como si te sentaras en una silla.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3560","name":"dumbbell standing alternate hammer curl and press","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/3560-LeaZOIz.jpg","gif_url":"videos/3560-LeaZOIz.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות לגוף.","שמרו על מרפקים צמודים לגו וגב ישר.","נשפו וכופפו את המשקולת ביד ימין לכיוון הכתף, תוך שמירה על הזרוע העליונה ללא תזוזה.","המשיכו להרים את המשקולת עד שהבייספס מכווץ במלואו והמשקולת בגובה הכתף.","שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על הכפיפה עם יד שמאל.","אחרי השלמת הכפיפה ביד שמאל, נשפו ולחצו את המשקולת ביד ימין מעל הראש.","מתחו את היד לגמרי ועצרו לרגע בנקודה העליונה.","שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על הלחיצה עם יד שמאל.","המשיכו להחליף בין כפיפות ללחיצות למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your back straight.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with your left hand.","After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead.","Extend your arm fully and hold for a moment at the top.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the press with your left hand.","Continue alternating between curls and presses for the desired number of repetitions."],"ru":["Встаньте прямо, возьмите в каждую руку по гантели, ладони обращены к телу.","Держите локти близко к туловищу, а спину держите прямо.","Выдохните и согните гантель в правой руке к плечу, сохраняя плечо неподвижным.","Продолжайте поднимать гантель до тех пор, пока ваши бицепсы полностью не сократятся и гантель не окажется на уровне плеч.","Вдохните и медленно опустите гантель обратно в исходное положение.","Повторите сгибание левой рукой.","Завершив сгибание левой рукой, выдохните и нажмите гантель в правой руке над головой.","Полностью вытяните руку и задержитесь на мгновение в верхней точке.","Вдохните и медленно опустите гантель обратно в исходное положение.","Повторите нажатие левой рукой.","Продолжайте чередовать сгибания и жимы желаемое количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Mantén los codos cerca del torso y la espalda recta.","Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el curl con la mano izquierda.","Después de completar el curl con la mano izquierda, exhala y presiona la mancuerna de la mano derecha por encima de la cabeza.","Extiende completamente el brazo y mantén la posición por un momento en la parte superior.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el press con la mano izquierda.","Continúa alternando entre curls y press durante el número de repeticiones deseado."]}},{"id":"0414","name":"dumbbell standing alternate overhead press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0414-bBi35y3.jpg","gif_url":"videos/0414-bBi35y3.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד בכל יד בגובה הכתפיים עם כפות ידיים פונות קדימה.","לחצו משקולת אחת מעל הראש, עד יישור מלא של היד.","הורידו את המשקולת חזרה לגובה הכתף.","חזרו על התנועה עם היד השנייה.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press one dumbbell overhead, fully extending your arm.","Lower the dumbbell back to shoulder level.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, держа в каждой руке по гантели на уровне плеч ладонями вперед.","Выжмите одну гантель над головой, полностью выпрямляя руку.","Опустите гантель обратно на уровень плеч.","Повторите с другой рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante.","Presiona una mancuerna por encima de la cabeza, extendiendo completamente el brazo.","Baja la mancuerna de vuelta a la altura de los hombros.","Repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"0415","name":"dumbbell standing alternate raise","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","forearms"],"target":"delts","image":"images/0415-SxHteRW.jpg","gif_url":"videos/0415-SxHteRW.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במשקולת יד בכל יד עם כפות ידיים פונות לגוף.","שמרו על גב ישר וליבה מופעלת.","הרימו משקולת אחת הצידה, תוך שמירה על יד ישרה וכף יד כלפי מטה.","המשיכו להרים עד שהיד מקבילה לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה עם היד השנייה.","החליפו בין הידיים לסירוגין למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and your core engaged.","Raise one dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите в каждой руке по гантели ладонями к телу.","Держите спину прямо, а корпус напряженным.","Поднимите одну гантель в сторону, держа руку прямой ладонью вниз.","Продолжайте поднимать, пока ваша рука не станет параллельна земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите с другой рукой.","Чередуйте руки, выполняя желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo.","Mantén la espalda recta y el core activado.","Levanta una mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo.","Continúa levantando hasta que el brazo quede paralelo al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite con el otro brazo.","Alterna entre los brazos el número de repeticiones deseado."]}},{"id":"1739","name":"dumbbell standing alternating tricep kickback","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1739-Gi2BXfK.jpg","gif_url":"videos/1739-Gi2BXfK.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","יישרו את הידיים ישר לאחור, תוך שמירה על מרפקים צמודים לגוף.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה עם היד השנייה, לסירוגין בין הצדדים בכל חזרה."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, keeping your elbows close to your body.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat with the other arm, alternating sides with each repetition."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гантели.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Вытяните руки прямо назад, держа локти близко к телу.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите то же самое с другой рукой, чередуя стороны при каждом повторении."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite con el otro brazo, alternando lados en cada repetición."]}},{"id":"2143","name":"dumbbell standing around world","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","forearms"],"target":"delts","image":"images/2143-RSOsp5d.jpg","gif_url":"videos/2143-RSOsp5d.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד.","מתחו את הידיים ישר לצדדים בגובה הכתפיים, כפות ידיים כלפי מטה.","תוך שמירה על ידיים ישרות, סובבו אותן באיטיות בתנועה מעגלית, בהבאת המשקולות מול הגוף ואז מעל הראש.","המשיכו בתנועה המעגלית, בהחזרת המשקולות למטה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Extend your arms straight out to the sides at shoulder height, palms facing down.","Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead.","Continue the circular motion, bringing the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели.","Вытяните руки прямо в стороны на уровне плеч ладонями вниз.","Держа руки прямыми, медленно вращайте ими круговыми движениями, поднимая гантели перед собой, а затем над головой.","Продолжайте круговые движения, возвращая гантели в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Extiende los brazos rectos hacia los lados a la altura de los hombros, con las palmas hacia abajo.","Manteniendo los brazos rectos, gira lentamente los brazos en un movimiento circular, llevando las mancuernas frente al cuerpo y luego por encima de la cabeza.","Continúa el movimiento circular, bajando las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1740","name":"dumbbell standing bent over one arm triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"triceps","image":"images/1740-CJwa0vD.jpg","gif_url":"videos/1740-CJwa0vD.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד ביד אחת.","הטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר ומקביל לרצפה.","יישרו את היד ישר לאחור, תוך שמירה על מרפק קרוב לגוף.","הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Встаньте, ноги на ширине плеч, в одной руке возьмите гантель.","Наклонитесь вперед в талии, сохраняя спину прямой и параллельной земле.","Вытяните руку прямо назад, держа локоть близко к телу.","Медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo.","Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo.","Baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1741","name":"dumbbell standing bent over two arm triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"triceps","image":"images/1741-3T12T87.jpg","gif_url":"videos/1741-3T12T87.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד.","הטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר וברכיים כפופות מעט.","יישרו את הידיים ישר לאחור, תוך שמירה על מרפקים צמודים לגוף.","הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Extend your arms straight back, keeping your elbows close to your body.","Slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели.","Наклонитесь вперед в талии, сохраняя спину прямой и слегка согнутыми в коленях.","Вытяните руки прямо назад, держа локти близко к телу.","Медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo.","Baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0416","name":"dumbbell standing biceps curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0416-3s4NnTh.jpg","gif_url":"videos/0416-3s4NnTh.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות קדימה וידיים ישרות.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, взяв в каждую руку по гантели, ладони направлены вперед, руки полностью выпрямлены.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0417","name":"dumbbell standing calf raise","category":"lower legs","body_part":"lower legs","equipment":"dumbbell","muscle_group":"ankles","secondary_muscles":["ankles"],"target":"calves","image":"images/0417-dPmaUaU.jpg","gif_url":"videos/0417-dPmaUaU.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד.","הרימו את העקבים מהרצפה גבוה ככל האפשר, בעזרת שרירי התאומים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гантели.","Поднимите пятки от земли как можно выше, используя икроножные мышцы.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Levanta los talones del suelo lo más alto posible, usando las pantorrillas.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0418","name":"dumbbell standing concentration curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0418-7inpWch.jpg","gif_url":"videos/0418-7inpWch.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד ביד אחת, עם יד ישרה לגמרי וכף יד פונה פנימה.","הניחו את היד הנגדית על הירך לתמיכה.","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את המשקולת לכיוון הכתף בכיווץ הבייספס.","המשיכו להרים את המשקולת עד שהבייספס מכווץ במלואו והמשקולת בגובה הכתף.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards.","Place your opposite hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Встаньте, поставив ноги на ширине плеч, и возьмите гантель в одну руку, полностью вытянув руку и ладонью внутрь.","Положите противоположную руку на бедро для поддержки.","Удерживая плечо неподвижно, выдохните и поднимите гантель к плечу, напрягая бицепс.","Продолжайте поднимать гантель до тех пор, пока ваши бицепсы полностью не сократятся и гантель не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano, con el brazo completamente extendido y la palma hacia adentro.","Apoya la otra mano sobre el muslo para mayor estabilidad.","Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0419","name":"dumbbell standing front raise above head","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"trapezius","secondary_muscles":["trapezius","biceps"],"target":"delts","image":"images/0419-laVRfDf.jpg","gif_url":"videos/0419-laVRfDf.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד באחיזה עליונה.","שמרו על ידיים ישרות והרימו את המשקולות לפניכם, עד מעל הראש.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keep your arms straight and lift the dumbbells in front of you, raising them above your head.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите по гантели в каждой руке хватом сверху.","Держите руки прямо и поднимите гантели перед собой, подняв их над головой.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Mantén los brazos rectos y levanta las mancuernas frente a ti, elevándolas por encima de la cabeza.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2321","name":"dumbbell standing inner biceps curl v. 2","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2321-vKilzz3.jpg","gif_url":"videos/2321-vKilzz3.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות לגו.","שמרו על מרפקים צמודים לגו וסובבו את כפות הידיים עד שהן פונות קדימה.","תוך שמירה על הזרועות העליונות ללא תזוזה, כופפו את המשקולות תוך כיווץ הבייספס.","המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","התחילו להחזיר את המשקולות באיטיות לנקודת ההתחלה תוך שאיפה.","חזרו על התרגיל למספר החזרות המומלץ."],"en":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","While holding your upper arms stationary, curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"ru":["Встаньте прямо, возьмите в каждую руку по гантели, ладони обращены к туловищу.","Держите локти близко к туловищу и поворачивайте ладони рук так, чтобы они смотрели вперед.","Удерживая плечи неподвижно, согните гири, напрягая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","На вдохе медленно начинайте возвращать гантели в исходное положение.","Повторите рекомендованное количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.","Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.","Manteniendo fija la parte superior de los brazos, flexiona los pesos mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Comienza a llevar lentamente las mancuernas de vuelta a la posición inicial mientras inhalas.","Repite el número de repeticiones recomendado."]}},{"id":"0420","name":"dumbbell standing kickback","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0420-UmpPAAe.jpg","gif_url":"videos/0420-UmpPAAe.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","יישרו את הידיים ישר לאחור, וכווצו את הטרייספס בנקודה העליונה של התנועה.","עצרו לרגע, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Вытяните руки прямо назад, сжимая трицепсы в верхней точке движения.","Сделайте паузу на мгновение, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.","Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0421","name":"dumbbell standing one arm concentration curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0421-8fgqP5a.jpg","gif_url":"videos/0421-8fgqP5a.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו משקולת יד ביד אחת, כף יד כלפי מעלה.","הניחו את היד הפנויה על הירך לתמיכה.","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את המשקולת לכיוון הכתף בכיווץ הבייספס.","המשיכו להרים את המשקולת עד שהבייספס מכווץ במלואו והמשקולת בגובה הכתף.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.","Place your free hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите в одну руку гантель ладонью вверх.","Положите свободную руку на бедро для поддержки.","Удерживая плечо неподвижно, выдохните и поднимите гантель к плечу, напрягая бицепс.","Продолжайте поднимать гантель до тех пор, пока ваши бицепсы полностью не сократятся и гантель не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia arriba.","Coloca la mano libre sobre el muslo para apoyarte.","Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0422","name":"dumbbell standing one arm curl (over incline bench)","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0422-BIb1tGo.jpg","gif_url":"videos/0422-BIb1tGo.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד ביד אחת עם כף יד פונה קדימה.","הניחו את היד השנייה על ספסל שיפוע לתמיכה.","תוך שמירה על הזרוע העליונה ללא תזוזה, נשפו וכופפו את המשקולת לכיוון הכתף בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Встаньте, ноги на ширине плеч, в одной руке держите гантель ладонью вперед.","Другую руку положите на наклонную скамью для поддержки.","Удерживая плечо неподвижно, выдохните и поднимите гантель к плечу, напрягая бицепс.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia adelante.","Coloca la otra mano sobre un banco inclinado para apoyarte.","Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1680","name":"dumbbell standing one arm curl over incline bench","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1680-EmlJR2y.jpg","gif_url":"videos/1680-EmlJR2y.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד ביד אחת.","הניחו את היד השנייה על ספסל שיפוע לתמיכה.","תוך שמירה על הזרוע העליונה ללא תזוזה, כופפו את המשקולת לכיוון הכתף בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Встаньте, ноги на ширине плеч, в одной руке держите гантель.","Другую руку положите на наклонную скамью для поддержки.","Удерживая плечо неподвижно, поднимите гантель к плечу, напрягая бицепс.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano.","Coloca la otra mano sobre un banco inclinado para apoyarte.","Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"0423","name":"dumbbell standing one arm extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0423-BCUR88E.jpg","gif_url":"videos/0423-BCUR88E.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד ביד אחת.","הרימו את המשקולת מעל הראש, עד יישור מלא של היד.","שמרו על הזרוע העליונה קרובה לראש וניצבת לרצפה.","הורידו באיטיות את המשקולת מאחורי הראש, בכיפוף המרפק.","עצרו לרגע, ואז הרימו את המשקולת חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Keep your upper arm close to your head and perpendicular to the ground.","Slowly lower the dumbbell behind your head, bending your elbow.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, в одной руке держите гантель.","Поднимите гантель над головой, полностью выпрямляя руку.","Держите плечо близко к голове и перпендикулярно земле.","Медленно опустите гантель за голову, сгибая локоть.","Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano.","Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo.","Mantén la parte superior del brazo cerca de la cabeza y perpendicular al suelo.","Baja lentamente la mancuerna detrás de la cabeza, flexionando el codo.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0424","name":"dumbbell standing one arm palm in press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0424-ocYc6Db.jpg","gif_url":"videos/0424-ocYc6Db.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד ביד אחת בגובה הכתף עם כף יד פונה פנימה.","הפעילו את הליבה ושמרו על גב ישר.","לחצו את המשקולת כלפי מעלה עד יישור מלא של היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards.","Engage your core and keep your back straight.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Встаньте, ноги на ширине плеч, держите гантель в одной руке на уровне плеч ладонью внутрь.","Напрягите корпус и держите спину прямо.","Нажмите гантель вверх, пока рука полностью не выпрямится.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano a la altura del hombro, con la palma hacia adentro.","Activa el core y mantén la espalda recta.","Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0425","name":"dumbbell standing one arm reverse curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0425-DU5Kkj2.jpg","gif_url":"videos/0425-DU5Kkj2.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו משקולת יד ביד אחת באחיזה עליונה.","שמרו על היד ישרה לגמרי וקרובה לגוף, עם כף יד כלפי מטה.","כופפו באיטיות את המשקולת למעלה לכיוון הכתף, תוך שמירה על הזרוע העליונה ללא תזוזה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip.","Keep your arm fully extended and close to your body, with your palm facing down.","Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите гантель в одну руку хватом сверху.","Держите руку полностью вытянутой и близко к телу ладонью вниз.","Медленно поднимите гантель к плечу, сохраняя плечо неподвижным.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano con agarre prono.","Mantén el brazo completamente extendido y cerca del cuerpo, con la palma hacia abajo.","Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0426","name":"dumbbell standing overhead press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0426-A6wtbuL.jpg","gif_url":"videos/0426-A6wtbuL.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקולת יד בכל יד בגובה הכתפיים עם כפות ידיים פונות קדימה.","לחצו את המשקולות כלפי מעלה עד יישור מלא של הידיים מעל הראש.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, держа в каждой руке по гантели на уровне плеч ладонями вперед.","Выжмите гантели вверх, пока руки полностью не выпрямятся над головой.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно до уровня плеч.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante.","Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"0427","name":"dumbbell standing palms in press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0427-UilDHSs.jpg","gif_url":"videos/0427-UilDHSs.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במשקולת יד בכל יד בגובה הכתפיים, כפות ידיים פונות פנימה.","תוך שמירה על ליבה מופעלת וגב ישר, לחצו את המשקולות כלפי מעלה עד יישור מלא של הידיים מעל הראש.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards.","Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите по гантели в каждой руке на уровне плеч ладонями внутрь.","Удерживая корпус напряженным, а спину прямой, жмите гантели вверх, пока руки полностью не выпрямятся над головой.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adentro.","Manteniendo el core activado y la espalda recta, presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0428","name":"dumbbell standing preacher curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0428-hq2hyDH.jpg","gif_url":"videos/0428-hq2hyDH.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד, כפות ידיים פונות קדימה.","השעינו את גב הזרועות העליונות על ספסל הפריצ'ר או ספסל בשיפוע חיובי, עם כיפוף קל במרפקים.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המשקולות עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями вперед.","Положите тыльную часть рук на скамью проповедника или наклонную скамью, слегка согнув локти.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.","Apoya la parte posterior de la parte superior de los brazos contra el banco scott o un banco inclinado, con los codos ligeramente flexionados.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0429","name":"dumbbell standing reverse curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0429-0IgNjSM.jpg","gif_url":"videos/0429-0IgNjSM.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד, כפות ידיים פונות לגוף.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המשקולות תוך כיווץ הבייספס. המשיכו להרים עד שהבייספס מכווץ במלואו והמשקולות בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями к телу.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы. Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Manteniendo fija la parte superior de los brazos, exhala y flexiona los pesos mientras contraes los bíceps. Continúa subiendo los pesos hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0430","name":"dumbbell standing triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0430-PdmaD0N.jpg","gif_url":"videos/0430-PdmaD0N.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד ביד אחת.","הרימו את המשקולת מעל הראש, תוך שמירה על יד ישרה.","כופפו את המרפק והורידו את המשקולת מאחורי הראש, תוך שמירה על הזרוע העליונה ללא תזוזה.","יישרו את היד חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Raise the dumbbell overhead, keeping your arm straight.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary.","Extend your arm back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, в одной руке возьмите гантель.","Поднимите гантель над головой, держа руку прямо.","Согните локоть и опустите гантель за голову, сохраняя плечо неподвижным.","Вытяните руку обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano.","Levanta la mancuerna por encima de la cabeza, manteniendo el brazo recto.","Flexiona el codo y baja la mancuerna detrás de la cabeza, manteniendo fija la parte superior del brazo.","Extiende el brazo de vuelta hacia arriba, hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2293","name":"dumbbell standing zottman preacher curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2293-P2nRiUa.jpg","gif_url":"videos/2293-P2nRiUa.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות קדימה.","הצמידו את הזרועות העליונות לספסל הפריצ'ר ושמרו על מרפקים כפופים מעט.","כופפו את המשקולות למעלה לכיוון הכתפיים תוך שמירה על זרועות עליונות ללא תזוזה.","בנקודה העליונה של התנועה, סובבו את שורשי כף היד כך שכפות הידיים פונות כלפי מטה.","הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה, בסיבוב שורשי כף היד חזרה גם כן.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing forward.","Place your upper arms against the preacher bench and keep your elbows slightly bent.","Curl the dumbbells up towards your shoulders while keeping your upper arms stationary.","At the top of the movement, rotate your wrists so that your palms are facing downward.","Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, взяв в каждую руку по гантели ладонями вперед.","Положите плечи на скамью проповедника и держите локти слегка согнутыми.","Поднимите гантели к плечам, сохраняя плечи неподвижными.","В верхней точке движения поверните запястья так, чтобы ладони были направлены вниз.","Медленно опустите гантели обратно в исходное положение, также поворачивая запястья обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.","Apoya la parte superior de los brazos contra el banco scott y mantén los codos ligeramente flexionados.","Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos.","En la parte superior del movimiento, gira las muñecas de modo que las palmas queden hacia abajo.","Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original.","Repite el número de repeticiones deseado."]}},{"id":"1684","name":"dumbbell step up single leg balance with bicep curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","glutes","hamstrings"],"target":"biceps","image":"images/1684-76vfTdU.jpg","gif_url":"videos/1684-76vfTdU.gif","instruction_steps":{"he":["עמדו מול מדרגה או משטח עם משקולת יד בכל יד, כפות ידיים פונות לגוף.","הניחו את כף רגל ימין על המדרגה, וודאו שכל כף הרגל נוגעת במשטח.","הפעילו את הליבה ודחפו דרך עקב ימין להעלאת הגוף על המדרגה, בהבאת ברך שמאל לכיוון החזה.","בנקודה העליונה של התנועה, בצעו כפיפת בייספס — כופפו מרפקים והביאו את המשקולות לכיוון הכתפיים.","הורידו את המשקולות חזרה ובו-זמנית הורידו את כף רגל שמאל חזרה לרצפה.","חזרו על התנועה בצד הנגדי, בעלייה עם כף רגל שמאל וכפיפת המשקולות.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.","Place your right foot on the step, ensuring your entire foot is in contact with the surface.","Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.","At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.","Lower the dumbbells back down and simultaneously lower your left foot back to the ground.","Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте перед ступенькой или платформой, держа в каждой руке по гантели, ладонями к телу.","Поставьте правую ногу на ступеньку так, чтобы вся стопа касалась поверхности.","Напрягите корпус и толкните правую пятку, чтобы поднять тело на ступеньку, подтягивая левое колено к груди.","В верхней точке движения выполните подъем на бицепс, согнув руки в локтях и поднеся гантели к плечам.","Опустите гантели обратно вниз и одновременно опустите левую ногу обратно на землю.","Повторите движение на противоположную сторону, поднимая левую ногу и сгибая гантели.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté en contacto con la superficie.","Activa el core y empuja con el talón derecho para subir el cuerpo sobre el escalón, llevando la rodilla izquierda hacia el pecho.","En la parte superior del movimiento, realiza un curl de bíceps flexionando los codos y llevando las mancuernas hacia los hombros.","Baja las mancuernas y, al mismo tiempo, baja el pie izquierdo de vuelta al suelo.","Repite el movimiento del lado contrario, subiendo con el pie izquierdo y flexionando las mancuernas.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0431","name":"dumbbell step-up","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0431-aXtJhlg.jpg","gif_url":"videos/0431-aXtJhlg.gif","instruction_steps":{"he":["עמדו מול ספסל או מדרגה עם משקולת יד בכל יד, כפות ידיים פונות לגוף.","הניחו את רגל ימין על הספסל, וודאו שכל כף הרגל נוגעת במשטח.","דחפו דרך עקב ימין והעלו את הגוף על הספסל תוך יישור רגל ימין.","העלו גם את רגל שמאל על הספסל ועמדו זקוף.","רדו לאחור עם רגל שמאל ואחריה רגל ימין, חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your right heel and lift your body up onto the bench or step, straightening your right leg.","Bring your left foot up onto the bench or step, standing fully upright.","Step back down with your left foot, followed by your right foot, returning to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Встаньте перед скамьей или сделайте шаг вперед, взяв в каждую руку по гантели ладонями к телу.","Поставьте правую ногу на скамью или ступеньку так, чтобы вся ступня касалась поверхности.","Оттолкнитесь правой пяткой и поднимите тело на скамью или ступеньку, выпрямляя правую ногу.","Поднимите левую ногу на скамью или ступеньку, встав полностью вертикально.","Сделайте шаг назад левой ногой, затем правой ногой, возвращаясь в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie.","Empuja con el talón derecho y sube el cuerpo sobre el banco o escalón, enderezando la pierna derecha.","Sube el pie izquierdo hasta el banco o escalón, quedando completamente erguido.","Baja con el pie izquierdo, seguido del pie derecho, volviendo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"2796","name":"dumbbell step-up lunge","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/2796-gFyFj9z.jpg","gif_url":"videos/2796-gFyFj9z.gif","instruction_steps":{"he":["עמדו מול מדרגה או משטח עם משקולת יד בכל יד, כפות ידיים פונות לצידי הגוף.","הניחו את כף רגל ימין על המדרגה, וודאו שכל כף הרגל על המשטח.","דחפו דרך עקב ימין והעלו את הגוף על המדרגה, בהעלאת כף רגל שמאל גם כן.","כששתי כפות הרגליים על המדרגה, הורידו את כף רגל שמאל חזרה לנקודת ההתחלה, תוך שמירה על כף רגל ימין על המדרגה.","חזרו על התנועה, בהחלפת הרגל שעולה בכל פעם.","המשיכו למספר החזרות הרצוי."],"en":["Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.","Place your right foot on the step, ensuring your entire foot is on the surface.","Push through your right heel and lift your body up onto the step, bringing your left foot up as well.","Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.","Repeat the movement, alternating which foot you step up with each time.","Continue for the desired number of repetitions."],"ru":["Встаньте перед ступенькой или платформой, держа в каждой руке по гантели, ладонями в стороны.","Поставьте правую ногу на ступеньку так, чтобы вся стопа находилась на поверхности.","Надавите на правую пятку и поднимите тело на ступеньку, одновременно поднимая левую ногу.","Как только обе ноги окажутся на ступеньке, опустите левую ногу обратно в исходное положение, удерживая правую ногу на ступеньке.","Повторите движение, каждый раз чередуя ногу, на которую вы наступаете.","Продолжайте необходимое количество повторений."],"es":["Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tus costados.","Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté sobre la superficie.","Empuja con el talón derecho y sube el cuerpo sobre el escalón, llevando también el pie izquierdo hacia arriba.","Una vez que ambos pies estén sobre el escalón, baja el pie izquierdo de vuelta a la posición inicial, manteniendo el pie derecho sobre el escalón.","Repite el movimiento, alternando el pie con el que subes cada vez.","Continúa durante el número de repeticiones deseado."]}},{"id":"2812","name":"dumbbell step-up split squat","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/2812-QjE2DcA.jpg","gif_url":"videos/2812-QjE2DcA.gif","instruction_steps":{"he":["עמדו מול ספסל או מדרגה עם משקולת יד בכל יד, כפות ידיים פונות לגוף.","הניחו את רגל ימין על הספסל, וודאו שכל כף הרגל נוגעת במשטח.","עלו על הספסל או המדרגה עם כף רגל ימין, בדחיפה דרך העקב להרמת הגוף.","תוך כדי העלייה, הרימו בו-זמנית את ברך שמאל לכיוון החזה.","עצרו בנקודה העליונה של התנועה, ואז הורידו את כף רגל שמאל באיטיות חזרה לרצפה, תוך שמירה על כף רגל ימין על הספסל או המדרגה.","חזרו על התנועה עם כף רגל שמאל על הספסל או המדרגה.","המשיכו להחליף בין כף רגל ימין ושמאל למספר החזרות הרצוי."],"en":["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Step up onto the bench or step with your right foot, pushing through your heel to lift your body up.","As you step up, simultaneously lift your left knee towards your chest.","Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step.","Repeat the movement with your left foot on the bench or step.","Continue alternating between your right and left foot for the desired number of repetitions."],"ru":["Встаньте перед скамьей или сделайте шаг вперед, взяв в каждую руку по гантели ладонями к телу.","Поставьте правую ногу на скамью или ступеньку так, чтобы вся ступня касалась поверхности.","Встаньте на скамью или шагните правой ногой, отталкиваясь пяткой, чтобы поднять тело вверх.","Делая шаг вперед, одновременно поднимите левое колено к груди.","Сделайте паузу в верхней части движения, затем медленно опустите левую ногу обратно на землю, удерживая правую ногу на скамье или ступеньке.","Повторите движение, поставив левую ногу на скамью или ступеньку.","Продолжайте чередовать правую и левую ногу необходимое количество повторений."],"es":["Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie.","Sube al banco o escalón con el pie derecho, empujando con el talón para levantar el cuerpo.","Mientras subes, levanta al mismo tiempo la rodilla izquierda hacia el pecho.","Haz una pausa en la parte superior del movimiento, luego baja lentamente el pie izquierdo de vuelta al suelo mientras mantienes el pie derecho sobre el banco o escalón.","Repite el movimiento con el pie izquierdo sobre el banco o escalón.","Continúa alternando entre el pie derecho y el izquierdo durante el número de repeticiones deseado."]}},{"id":"0432","name":"dumbbell stiff leg deadlift","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0432-5eLRITT.jpg","gif_url":"videos/0432-5eLRITT.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד באחיזה עליונה.","תוך שמירה על גב ישר וליבה מופעלת, הטו את הגו מהירכיים והורידו את המשקולות לכיוון הרצפה, עם כיפוף קל בברכיים.","הורידו את המשקולות עד שתרגישו מתיחה בירך האחורית, ואז כווצו את הישבן ודחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees.","Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите по гантели в каждой руке хватом сверху.","Удерживая спину прямой и напряженным корпус, наклонитесь в бедрах и опустите гантели к земле, слегка согнув колени.","Опускайте гантели до тех пор, пока не почувствуете растяжение подколенных сухожилий, затем сожмите ягодицы и толкните пятки, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo una ligera flexión en las rodillas.","Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego aprieta los glúteos y empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0433","name":"dumbbell straight arm pullover","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"latissimus dorsi","secondary_muscles":["latissimus dorsi","triceps"],"target":"pectorals","image":"images/0433-i8BdLTK.jpg","gif_url":"videos/0433-i8BdLTK.gif","instruction_steps":{"he":["שכבו על ספסל כשהראש בקצה אחד וכפות הרגליים נטועות היטב על הרצפה.","החזיקו משקולת יד בשתי הידיים ומתחו את הידיים ישר מעל החזה.","תוך שמירה על ידיים ישרות, הורידו באיטיות את המשקולת מאחורי הראש בתנועה קשתית.","עצרו לרגע, ואז הרימו את המשקולת חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your head at one end and your feet planted firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив голову на один конец и твердо поставив ноги на землю.","Возьмите гантель обеими руками и вытяните руки прямо над грудью.","Держа руки прямыми, медленно опустите гантель за голову дугообразным движением.","Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo.","Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza con un movimiento en forma de arco.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0434","name":"dumbbell straight leg deadlift","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0434-oom75KC.jpg","gif_url":"videos/0434-oom75KC.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד באחיזה עליונה.","תוך שמירה על גב ישר וליבה מופעלת, הטו את הגו מהירכיים והורידו את המשקולות לכיוון הרצפה, כשהגו נוטה קדימה.","המשיכו להוריד את המשקולות עד לתחושת מתיחה בירך האחורית, תוך שמירה על ברכיים כפופות מעט.","עצרו לרגע בנקודה התחתונה, ואז הפעילו את הישבן והירך האחורית להרמת הגו חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward.","Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите по гантели в каждой руке хватом сверху.","Удерживая спину прямой и напряженным корпус, наклонитесь в бедрах и опустите гантели к земле, позволяя туловищу наклониться вперед.","Продолжайте опускать гантели, пока не почувствуете растяжение подколенных сухожилий, сохраняя колени слегка согнутыми.","Задержитесь на мгновение в нижней точке, затем задействуйте ягодицы и мышцы задней поверхности бедра, чтобы поднять туловище обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que el torso se incline hacia adelante.","Continúa bajando las mancuernas hasta sentir un estiramiento en los isquiotibiales, manteniendo las rodillas ligeramente flexionadas.","Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2808","name":"dumbbell sumo pull through","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","core"],"target":"glutes","image":"images/2808-BmrwWzo.jpg","gif_url":"videos/2808-BmrwWzo.gif","instruction_steps":{"he":["עמדו עם רגליים רחבות מרוחב הכתפיים, קצות האצבעות פונות החוצה.","החזיקו משקולת יד בשתי ידיים מול הגוף, עם ידיים מתוחות.","כופפו ברכיים והורידו את האגן לעמדת סקוואט, תוך שמירה על גב ישר.","הורידו את המשקולת בין הרגליים, תוך שמירה על ידיים ישרות.","דחפו דרך העקבים ויישרו את הירכיים קדימה, במשיכת המשקולת למעלה ומול הגוף.","כווצו את הישבן בנקודה העליונה של התנועה, ואז הורידו את המשקולת חזרה בין הרגליים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet wider than shoulder-width apart, toes pointed outwards.","Hold a dumbbell with both hands in front of your body, arms extended.","Bend your knees and lower your hips down into a squat position, keeping your back straight.","Lower the dumbbell down between your legs, keeping your arms straight.","Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.","Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги шире плеч, носки направлены наружу.","Держите гантель обеими руками перед телом, руки вытянуты.","Согните колени и опустите бедра в положение приседа, сохраняя спину прямой.","Опустите гантель между ног, держа руки прямыми.","Проведите пятками и вытяните бедра вперед, подтягивая гантель вверх и перед собой.","Сожмите ягодицы в верхней точке движения, затем опустите гантель обратно между ног.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies más separados que la altura de los hombros, con las puntas de los pies hacia afuera.","Sujeta una mancuerna con ambas manos frente a tu cuerpo, con los brazos extendidos.","Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta.","Baja la mancuerna entre las piernas, manteniendo los brazos rectos.","Empuja con los talones y extiende las caderas hacia adelante, llevando la mancuerna hacia arriba y frente a tu cuerpo.","Aprieta los glúteos en la parte superior del movimiento, luego baja la mancuerna de vuelta entre las piernas.","Repite el número de repeticiones deseado."]}},{"id":"2803","name":"dumbbell supported squat","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/2803-r5DgrW9.jpg","gif_url":"videos/2803-r5DgrW9.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במשקולת יד בכל יד לצידי הגוף.","תוך שמירה על חזה מורם וליבה מופעלת, הורידו את הגוף באיטיות בכיפוף ברכיים ודחיפת האגן לאחור.","המשיכו לרדת עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа по гантели в каждой руке по бокам.","Удерживая грудь поднятой и напряженным корпусом, медленно опустите тело вниз, сгибая колени и отводя бедра назад.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.","Manteniendo el pecho arriba y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0436","name":"dumbbell tate press","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0436-s5PdDyY.jpg","gif_url":"videos/0436-s5PdDyY.gif","instruction_steps":{"he":["שבו על ספסל ישר עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","הרימו את המשקולות לגובה הכתפיים, ואז סובבו את שורשי כף היד כך שכפות הידיים פונות מכם.","לחצו את המשקולות למעלה עד יישור מלא של הידיים, ואז הורידו אותן חזרה לגובה הכתפיים.","סובבו את שורשי כף היד חזרה לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a flat bench with a dumbbell in each hand, palms facing each other.","Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you.","Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height.","Rotate your wrists back to the starting position and repeat for the desired number of repetitions."],"ru":["Сядьте на ровную скамью, взяв в каждую руку по гантели, ладони обращены друг к другу.","Поднимите гантели на высоту плеч, затем поверните запястья так, чтобы ладони были направлены от вас.","Выжимайте гантели вверх до тех пор, пока руки полностью не выпрямятся, затем опустите их обратно на высоту плеч.","Верните запястья в исходное положение и повторите желаемое количество повторений."],"es":["Siéntate en un banco plano con una mancuerna en cada mano, con las palmas mirándose entre sí.","Sube las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia afuera.","Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos, luego bájalas de vuelta a la altura de los hombros.","Gira las muñecas de vuelta a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"1742","name":"dumbbell tricep kickback with stork stance","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1742-wOLmCXc.jpg","gif_url":"videos/1742-wOLmCXc.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד ביד ימין.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","הרימו את מרפק ימין לצד הגוף, כשהוא כפוף בזווית של 90 מעלות.","יישרו את יד ימין ישר לאחור, תוך כיווץ הטרייספס.","עצרו לרגע, ואז הורידו את המשקולת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, возьмите в правую руку гантель.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Поднимите правый локоть в сторону, сохраняя его согнутым под углом 90 градусов.","Вытяните правую руку прямо назад, сжимая трицепс.","Сделайте паузу на мгновение, затем медленно опустите гантель обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados.","Extiende el brazo derecho recto hacia atrás, apretando el tríceps.","Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"1743","name":"dumbbell twisting bench press","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1743-z6TAHoT.jpg","gif_url":"videos/1743-z6TAHoT.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","החזיקו משקולת יד בכל יד באחיזה עליונה, כפות ידיים פונות מכם.","מתחו את הידיים ישר מעל החזה, עם כיפוף קל במרפקים.","הורידו את המשקולות לכיוון החזה, תוך שמירה על מרפקים צמודים לגוף.","תוך כדי הורדת המשקולות, סובבו את שורשי כף היד כך שכפות הידיים פונות אליכם בנקודה התחתונה של התנועה.","עצרו לרגע בנקודה התחתונה, ואז הפכו את התנועה בלחיצת המשקולות חזרה למעלה לנקודת ההתחלה.","תוך כדי לחיצת המשקולות למעלה, סובבו את שורשי כף היד חזרה לנקודת ההתחלה, עם כפות ידיים פונות מכם.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with an overhand grip, palms facing away from you.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbells down towards your chest, keeping your elbows close to your body.","As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement.","Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position.","As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите по гантели в каждую руку хватом сверху, ладонями от себя.","Вытяните руки прямо вверх над грудью, сохраняя небольшой изгиб в локтях.","Опустите гантели вниз к груди, держа локти близко к телу.","Опуская гантели, поверните запястья так, чтобы ладони были обращены к вам в нижней части движения.","Сделайте небольшую паузу в нижней точке, затем поменяйте направление движения, вернув гантели в исходное положение.","Выжимая гантели вверх, верните запястья в исходное положение ладонями от себя.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Sujeta una mancuerna en cada mano con agarre prono, con las palmas alejadas de ti.","Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.","Baja las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo.","Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden hacia ti en la parte más baja del movimiento.","Haz una pausa por un momento en la parte más baja, luego invierte el movimiento presionando las mancuernas de vuelta hacia arriba, hasta la posición inicial.","Mientras presionas las mancuernas hacia arriba, gira las muñecas de vuelta a la posición inicial con las palmas alejadas de ti.","Repite el número de repeticiones deseado."]}},{"id":"0437","name":"dumbbell upright row","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0437-ainizkb.jpg","gif_url":"videos/0437-ainizkb.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד באחיזה עליונה.","תנו למשקולות להשתלשל מול הירכיים, עם ידיים ישרות לגמרי.","תוך שמירה על גב ישר וליבה מופעלת, נשפו והרימו את המשקולות ישר למעלה לכיוון הסנטר, כשהמרפקים מובילים.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Let the dumbbells hang in front of your thighs, with your arms fully extended.","Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите по гантели в каждой руке хватом сверху.","Пусть гантели висят перед бедрами, руки полностью выпрямлены.","Удерживая спину прямой и напрягая корпус, выдохните и поднимите гантели прямо вверх к подбородку, ведя локтями.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Deja que las mancuernas cuelguen frente a tus muslos, con los brazos completamente extendidos.","Manteniendo la espalda recta y el core activado, exhala y levanta las mancuernas rectas hacia tu barbilla, guiando el movimiento con los codos.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1765","name":"dumbbell upright row (back pov)","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/1765-Iptlv6x.jpg","gif_url":"videos/1765-Iptlv6x.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, משקולת יד בכל יד באחיזה עליונה.","תנו למשקולות להשתלשל מול הירכיים, עם ידיים ישרות לגמרי וכפות ידיים פונות לגוף.","תוך שמירה על גב ישר וליבה מופעלת, נשפו והרימו את המשקולות ישר למעלה לכיוון הסנטר, כשהמרפקים מובילים.","המשיכו להרים עד שהמשקולות בגובה הכתפיים, עם מרפקים פונים החוצה לצדדים.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body.","Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите по гантели в каждой руке хватом сверху.","Пусть гантели висят перед бедрами, руки полностью вытянуты, ладони обращены к телу.","Удерживая спину прямой и напрягая корпус, выдохните и поднимите гантели прямо вверх к подбородку, ведя локтями.","Продолжайте поднимать гантели до тех пор, пока гантели не окажутся на уровне плеч, локти будут направлены в стороны.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Deja que las mancuernas cuelguen frente a tus muslos, con los brazos completamente extendidos y las palmas hacia tu cuerpo.","Manteniendo la espalda recta y el core activado, exhala y levanta las mancuernas rectas hacia tu barbilla, guiando el movimiento con los codos.","Continúa subiendo hasta que las mancuernas estén a la altura de los hombros, con los codos apuntando hacia los lados.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0864","name":"dumbbell upright shoulder external rotation","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"rotator cuff","secondary_muscles":["rotator cuff","trapezius"],"target":"delts","image":"images/0864-x306lCW.jpg","gif_url":"videos/0864-x306lCW.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד עם כפות ידיים פונות לגוף.","הרימו את הידיים לצדדים עד שהן מקבילות לרצפה, תוך שמירה על מרפקים כפופים מעט.","סובבו את הידיים החוצה, בהבאת המשקולות למעלה לכיוון הראש תוך שמירה על המרפקים באותה תנוחה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent.","Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями к телу.","Поднимите руки в стороны до тех пор, пока они не станут параллельны земле, сохраняя локти слегка согнутыми.","Поверните руки наружу, поднеся гантели к голове, сохраняя при этом локти в том же положении.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.","Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo los codos ligeramente flexionados.","Gira los brazos hacia afuera, llevando las mancuernas hacia la cabeza mientras mantienes los codos en la misma posición.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"5201","name":"dumbbell waiter biceps curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/5201-KOpzGBL.jpg","gif_url":"videos/5201-KOpzGBL.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות קדימה.","שמרו על הזרועות העליונות קרובות לגוף ומרפקים צמודים.","כופפו באיטיות את המשקולות למעלה לכיוון הכתפיים, תוך שמירה על שורשי כף יד ישרים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms close to your body and your elbows tucked in.","Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, взяв в каждую руку по гантели ладонями вперед.","Держите плечи близко к телу, а локти согнутыми.","Медленно поднимите гантели к плечам, сохраняя запястья прямыми.","Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.","Mantén la parte superior de los brazos cerca del cuerpo y los codos pegados.","Flexiona lentamente las mancuernas hacia los hombros, manteniendo las muñecas rectas.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0438","name":"dumbbell w-press","category":"shoulders","body_part":"shoulders","equipment":"dumbbell","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0438-vmwLyCg.jpg","gif_url":"videos/0438-vmwLyCg.gif","instruction_steps":{"he":["שבו על ספסל עם משקולת יד בכל יד, כפות ידיים פונות קדימה.","הרימו את המשקולות לגובה הכתפיים, מרפקים כפופים וכפות ידיים פונות קדימה.","לחצו את המשקולות כלפי מעלה עד יישור מלא של הידיים מעל הראש.","הורידו את המשקולות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, взяв в каждую руку по гантели ладонями вперед.","Поднимите гантели на высоту плеч, локти согнуты, ладони обращены вперед.","Выжмите гантели вверх, пока руки полностью не выпрямятся над головой.","Опустите гантели обратно на высоту плеч.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante.","Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.","Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Baja las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"0439","name":"dumbbell zottman curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0439-kXaIn5A.jpg","gif_url":"videos/0439-kXaIn5A.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות לגוף.","שמרו על מרפקים צמודים לגו וסובבו את כפות הידיים לפנים.","כופפו את המשקולות למעלה לכתפיים תוך שמירה על זרועות עליונות ללא תזוזה.","בנקודה העליונה של התנועה, סובבו את שורשי כף היד כך שכפות הידיים פונות מהגוף.","הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה, בסיבוב כפות הידיים חזרה לכיוון הגוף.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and rotate your palms to face forward.","Curl the dumbbells up to your shoulders while keeping your upper arms stationary.","At the top of the movement, rotate your wrists so that your palms are facing away from your body.","Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, возьмите в каждую руку по гантели, ладони обращены к телу.","Держите локти близко к туловищу и поверните ладони лицом вперед.","Поднимите гантели к плечам, сохраняя плечи неподвижными.","В верхней точке движения поверните запястья так, чтобы ладони были направлены от тела.","Медленно опустите гантели обратно в исходное положение, поворачивая ладони обратно к телу.","Повторите необходимое количество повторений."],"es":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Mantén los codos cerca del torso y gira las palmas para que queden hacia adelante.","Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos.","En la parte superior del movimiento, gira las muñecas de modo que las palmas queden alejadas de tu cuerpo.","Baja lentamente las mancuernas de vuelta a la posición inicial, girando las palmas de nuevo hacia tu cuerpo.","Repite el número de repeticiones deseado."]}},{"id":"2294","name":"dumbbell zottman preacher curl","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2294-y5U5B9Y.jpg","gif_url":"videos/2294-y5U5B9Y.gif","instruction_steps":{"he":["שבו על ספסל פריצ'ר עם משקולת יד בכל יד, כפות ידיים כלפי מעלה ומרפקים מונחים על הכרית.","כופפו את המשקולות למעלה לכיוון הכתפיים, תוך שמירה על זרועות עליונות ללא תזוזה וכפות ידיים כלפי מעלה.","בנקודה העליונה של הכפיפה, סובבו את שורשי כף היד כך שכפות הידיים פונות כלפי מטה.","הורידו את המשקולות באיטיות חזרה לנקודת ההתחלה, בסיבוב שורשי כף היד חזרה תוך כדי.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.","Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up.","At the top of the curl, rotate your wrists so that your palms are facing down.","Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью для проповедника, взяв в каждую руку по гантели, ладонями вверх и локтями на подушечку.","Поднимите гантели к плечам, сохраняя плечи неподвижными и ладонями вверх.","В верхней части сгибания поверните запястья так, чтобы ладони были направлены вниз.","Медленно опустите гантели обратно в исходное положение, поворачивая при этом запястья обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba y los codos apoyados en la almohadilla.","Flexiona las mancuernas hacia los hombros, manteniendo fija la parte superior de los brazos y las palmas hacia arriba.","En la parte superior del curl, gira las muñecas de modo que las palmas queden hacia abajo.","Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original mientras lo haces.","Repite el número de repeticiones deseado."]}},{"id":"2189","name":"dumbbells seated triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/2189-FQXdXzY.jpg","gif_url":"videos/2189-FQXdXzY.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו משקולת יד בשתי הידיים באחיזה עליונה, והרימו אותה מעל הראש.","כופפו מרפקים והורידו את המשקולת מאחורי הראש, תוך שמירה על הזרועות העליונות צמודות לאוזניים.","יישרו את הידיים והרימו את המשקולת חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in both hands with an overhand grip, and raise it above your head.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Extend your arms and raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите гантель обеими руками прямым хватом и поднимите ее над головой.","Согните руки в локтях и опустите гантель за голову, держа плечи близко к ушам.","Вытяните руки и поднимите гантель обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna con ambas manos con agarre prono y levántala por encima de la cabeza.","Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.","Extiende los brazos y sube la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1167","name":"dynamic chest stretch (male)","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1167-3uj0Ozg.jpg","gif_url":"videos/1167-3uj0Ozg.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים.","מתחו את הידיים ישר לצדדים, מקבילות לרצפה.","הביאו באיטיות את הידיים קדימה, בהצלבתן מול הגוף.","הרגישו את המתיחה בשרירי החזה.","החזיקו את המתיחה 10–30 שניות.","חזרו לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out to the sides, parallel to the ground.","Slowly bring your arms forward, crossing them in front of your body.","Feel the stretch in your chest muscles.","Hold the stretch for 10-30 seconds.","Return to the starting position and repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч.","Вытяните руки прямо в стороны, параллельно земле.","Медленно вытяните руки вперед, скрестив их перед телом.","Почувствуйте растяжение мышц груди.","Удерживайте растяжку 10–30 секунд.","Вернитесь в исходное положение и повторите необходимое количество повторений."],"es":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende los brazos hacia los lados, paralelos al suelo.","Lleva lentamente los brazos hacia adelante, cruzándolos frente al cuerpo.","Siente el estiramiento en los músculos del pecho.","Mantén el estiramiento durante 10-30 segundos.","Vuelve a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"3287","name":"elbow dips","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/3287-LkoAWAE.jpg","gif_url":"videos/3287-LkoAWAE.gif","instruction_steps":{"he":["שבו על קצה ספסל או כיסא כשהידיים אוחזות בקצה לצידי האגן.","החליקו את האגן קדימה מהספסל ויישרו את הרגליים, כשהעקבים על הרצפה.","כופפו מרפקים והורידו את הגוף לכיוון הרצפה, כשהגב קרוב לספסל.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך כפות הידיים ליישור הידיים והרמת הגוף חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на край скамьи или стула, взявшись руками за край рядом с бедрами.","Сдвиньте бедра вперед со скамьи и выпрямите ноги, удерживая пятки на земле.","Согните локти и опустите тело к земле, держа спину близко к скамье.","Задержитесь на мгновение в нижней точке, затем подтолкните руки, чтобы выпрямить руки и поднять тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas.","Desliza las caderas hacia adelante, fuera del banco, y estira las piernas, manteniendo los talones en el suelo.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.","Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1772","name":"elbow lift - reverse push-up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"upper back","image":"images/1772-wbUYILZ.jpg","gif_url":"videos/1772-wbUYILZ.gif","instruction_steps":{"he":["התחילו בשכיבה על הבטן על הרצפה עם רגליים מתוחות וידיים ישר מתחת לכתפיים.","הפעילו את הליבה ודחפו דרך כפות הידיים להרמת פלג הגוף העליון מהרצפה, תוך שמירה על מרפקים צמודים לצידי הגוף.","עצרו לרגע בנקודה העליונה, תוך כיווץ שרירי הגב העליון.","הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.","Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.","Pause at the top for a moment, squeezing your upper back muscles.","Slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что лягте на землю лицом вниз, вытянув ноги и положив руки прямо под плечи.","Напрягите корпус и надавите ладонями, чтобы оторвать верхнюю часть тела от земли, держа локти близко к бокам.","Задержитесь на мгновение в верхней точке, напрягая мышцы верхней части спины.","Медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza tumbado boca abajo en el suelo con las piernas extendidas y las manos colocadas justo debajo de los hombros.","Activa el core y presiona con las palmas para levantar la parte superior del cuerpo del suelo, manteniendo los codos cerca de los costados.","Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda alta.","Baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0443","name":"elbow-to-knee","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0443-jvp6DiD.jpg","gif_url":"videos/0443-jvp6DiD.gif","instruction_steps":{"he":["התחילו בשכיבה על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","הפעילו את שרירי הבטן והרימו את פלג הגוף העליון מהרצפה, בהבאת מרפק ימין לכיוון ברך שמאל.","בו-זמנית, הביאו את ברך שמאל לכיוון מרפק ימין, ביצירת תנועת סיבוב.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון ויישרו את הרגליים חזרה לנקודת ההתחלה.","חזרו על התנועה, הפעם בהבאת מרפק שמאל לכיוון ברך ימין וברך ימין לכיוון מרפק שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Start by lying flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, bring your left knee towards your right elbow, creating a twisting motion.","Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."],"ru":["Начните с того, что лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Напрягите пресс и поднимите верхнюю часть тела от земли, поднеся правый локоть к левому колену.","В то же время поднесите левое колено к правому локтю, создавая скручивающее движение.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела и вытяните ноги обратно в исходное положение.","Повторите движение, на этот раз поднеся левый локоть к правому колену, а правое колено к левому локтю.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Comienza tumbado boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda.","Al mismo tiempo, lleva la rodilla izquierda hacia el codo derecho, creando un movimiento de torsión.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo y extiende las piernas de vuelta a la posición inicial.","Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y la rodilla derecha hacia el codo izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"3292","name":"elevator","category":"back","body_part":"back","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","trapezius"],"target":"upper back","image":"images/3292-zYmNaoY.jpg","gif_url":"videos/3292-zYmNaoY.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","הניחו את הידיים על המותניים או הצליבו אותן מול החזה.","תוך שמירה על גב ישר, הטו באיטיות את הגו קדימה מהמותניים, בהורדת פלג הגוף העליון לכיוון הרצפה.","עצרו לרגע בנקודה התחתונה, ואז הרימו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or cross them in front of your chest.","Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground.","Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Положите руки на бедра или скрестите их перед грудью.","Сохраняя спину прямой, медленно наклонитесь вперед в талии, опуская верхнюю часть тела к земле.","Задержитесь на мгновение в нижней точке, затем медленно поднимите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Coloca las manos sobre las caderas o crúzalas frente al pecho.","Manteniendo la espalda recta, inclínate lentamente hacia adelante desde la cintura, bajando la parte superior del cuerpo hacia el suelo.","Haz una pausa por un momento en la posición más baja, luego sube lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1332","name":"exercise ball alternating arm ups","category":"back","body_part":"back","equipment":"stability ball","muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"lats","image":"images/1332-EyLrNC2.jpg","gif_url":"videos/1332-EyLrNC2.gif","instruction_steps":{"he":["שבו על כדור הפיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד בכל יד, כפות ידיים פונות פנימה וידיים מתוחות לצידי הגוף.","הפעילו את הליבה והרימו באיטיות יד אחת לכיוון הכתף, תוך שמירה על כיפוף קל במרפק.","עצרו לרגע בנקודה העליונה, ואז הורידו את היד באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה עם היד השנייה.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.","Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat the movement with the other arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Сядьте на мяч, поставив ноги на землю и выпрямив спину.","Возьмите по гантели в каждую руку ладонями внутрь и вытяните руки по бокам.","Напрягите корпус и медленно поднимите одну руку к плечу, слегка согнув локоть.","Задержитесь на мгновение в верхней точке, затем медленно опустите руку обратно в исходное положение.","Повторите движение другой рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta.","Sujeta una mancuerna en cada mano con las palmas hacia adentro y los brazos extendidos hacia abajo a los lados.","Activa el core y levanta lentamente un brazo hacia el hombro, manteniendo el codo ligeramente flexionado.","Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.","Repite el movimiento con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"1333","name":"exercise ball back extension with arms extended","category":"back","body_part":"back","equipment":"stability ball","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1333-PERjVm8.jpg","gif_url":"videos/1333-PERjVm8.gif","instruction_steps":{"he":["הניחו את כדור הפיזיו על הרצפה ושכבו עליו על הבטן, כשהאגן נשען על הכדור וכפות הרגליים נשענות על קיר לייצוב.","מתחו את הידיים ישר לפניכם, עם כפות ידיים כלפי מטה.","הפעילו את הליבה והרימו באיטיות את פלג הגוף העליון מהכדור, תוך שמירה על גב ישר וצוואר בקו אחד עם עמוד השדרה.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Extend your arms straight out in front of you, with your palms facing down.","Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Положите мяч на землю и лягте на него лицом вниз, положив бедра на мяч, а ступни упираясь в стену для устойчивости.","Вытяните руки прямо перед собой ладонями вниз.","Напрягите корпус и медленно поднимите верхнюю часть тела с мяча, сохраняя спину прямой, а шею на одной линии с позвоночником.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad.","Extiende los brazos rectos hacia adelante, con las palmas hacia abajo.","Activa el core y levanta lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta y el cuello alineado con la columna.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1334","name":"exercise ball back extension with hands behind head","category":"back","body_part":"back","equipment":"stability ball","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1334-o1HGDSq.jpg","gif_url":"videos/1334-o1HGDSq.gif","instruction_steps":{"he":["הניחו את כדור הפיזיו על הרצפה ושכבו עליו על הבטן, כשהאגן נשען על הכדור.","השעינו את כפות הרגליים על קיר או משטח יציב אחר לתמיכה.","הצליבו את הידיים מאחורי הראש, כשהידיים נוגעות בעורף.","הפעילו את הליבה והרימו באיטיות את פלג הגוף העליון מהכדור, ביישור הגב עד שהגוף יוצר קו ישר מהראש ועד האגן.","עצרו לרגע בנקודה העליונה של התנועה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.","Position your feet against a wall or other stable surface for support.","Cross your arms behind your head, with your hands touching the back of your head.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Положите мяч на землю и лягте на него лицом вниз, опираясь бедрами на мяч.","Поставьте ноги напротив стены или другой устойчивой поверхности для поддержки.","Скрестите руки за головой, касаясь ладонями затылка.","Напрягите корпус и медленно поднимите верхнюю часть тела с мяча, вытягивая спину до тех пор, пока тело не образует прямую линию от головы до бедер.","Сделайте паузу на мгновение в верхней точке движения, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él con las caderas apoyadas en el balón.","Coloca los pies contra una pared u otra superficie estable para apoyarte.","Cruza los brazos detrás de la cabeza, con las manos tocando la parte de atrás de la cabeza.","Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta las caderas.","Haz una pausa breve en la parte alta del movimiento, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1335","name":"exercise ball back extension with knees off ground","category":"back","body_part":"back","equipment":"stability ball","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1335-WME869U.jpg","gif_url":"videos/1335-WME869U.gif","instruction_steps":{"he":["הניחו את כדור הפיזיו על הרצפה ושכבו עליו על הבטן, כשהאגן נשען על הכדור וכפות הרגליים נשענות על קיר לייצוב.","מקמו את הידיים מאחורי הראש או מוצלבות על החזה.","הפעילו את הליבה והרימו באיטיות את פלג הגוף העליון מהכדור, ביישור הגב עד שהגוף יוצר קו ישר מהראש ועד העקבים.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Положите мяч на землю и лягте на него лицом вниз, положив бедра на мяч, а ступни упираясь в стену для устойчивости.","Положите руки за голову или скрестите на груди.","Напрягите корпус и медленно поднимите верхнюю часть тела с мяча, вытягивая спину до тех пор, пока тело не образует прямую линию от головы до пяток.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1336","name":"exercise ball back extension with rotation","category":"back","body_part":"back","equipment":"stability ball","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1336-WVD66ff.jpg","gif_url":"videos/1336-WVD66ff.gif","instruction_steps":{"he":["התחילו בשכיבה על הבטן על כדור הפיזיו, כשהאגן נשען על הכדור וכפות הרגליים נטועות היטב ברצפה.","מקמו את הידיים מאחורי הראש או הצליבו אותן על החזה.","הפעילו את הליבה והרימו באיטיות את פלג הגוף העליון מהכדור, ביישור הגב עד שהגוף יוצר קו ישר מהראש ועד העקבים.","עצרו לרגע בנקודה העליונה, ואז סובבו באיטיות את הגו לצד אחד, תוך שמירה על אגן ורגליים יציבים.","חזרו למרכז וחזרו על הסיבוב לצד השני.","הורידו את פלג הגוף העליון חזרה לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable.","Return to the center and repeat the rotation to the other side.","Lower your upper body back down to the starting position and repeat for the desired number of repetitions."],"ru":["Начните с того, что лягте на мяч лицом вниз, положив бедра на мяч и твердо поставив ступни на землю.","Заведите руки за голову или скрестите их на груди.","Напрягите корпус и медленно поднимите верхнюю часть тела с мяча, вытягивая спину до тех пор, пока тело не образует прямую линию от головы до пяток.","Задержитесь на мгновение в верхней точке, затем медленно поверните туловище в сторону, сохраняя бедра и ноги устойчивыми.","Вернитесь в центр и повторите вращение в другую сторону.","Опустите верхнюю часть тела обратно в исходное положение и повторите желаемое количество повторений."],"es":["Comienza tumbado boca abajo sobre el balón de estabilidad, con las caderas apoyadas en el balón y los pies firmemente apoyados en el suelo.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.","Haz una pausa por un momento en la parte superior, luego gira lentamente el torso hacia un lado, manteniendo las caderas y las piernas estables.","Vuelve al centro y repite el giro hacia el otro lado.","Baja la parte superior del cuerpo de vuelta a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"1744","name":"exercise ball dip","category":"upper arms","body_part":"upper arms","equipment":"stability ball","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1744-kprile3.jpg","gif_url":"videos/1744-kprile3.gif","instruction_steps":{"he":["שבו על כדור הפיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","הניחו את הידיים על הכדור לצידי האגן, אצבעות פונות קדימה.","הפעילו את הטרייספס ודחפו דרך הידיים להרמת הגוף מהכדור, ביישור הידיים.","הורידו את הגוף חזרה למטה בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the ball beside your hips, fingers pointing forward.","Engage your triceps and push through your hands to lift your body off the ball, straightening your arms.","Lower your body back down by bending your elbows, keeping them close to your sides.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч для стабилизации, поставьте ступни на землю и согните колени под углом 90 градусов.","Положите руки на мяч рядом с бедрами, пальцы направлены вперед.","Задействуйте трицепсы и толкайте руки, чтобы оторвать тело от мяча, выпрямляя руки.","Опустите тело обратно вниз, сгибая локти и держа их близко к бокам.","Повторите необходимое количество повторений."],"es":["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Coloca las manos sobre el balón junto a las caderas, con los dedos apuntando hacia adelante.","Activa el tríceps y empuja con las manos para levantar el cuerpo del balón, enderezando los brazos.","Baja el cuerpo flexionando los codos, manteniéndolos cerca de los costados.","Repite el número de repeticiones deseado."]}},{"id":"1559","name":"exercise ball hip flexor stretch","category":"upper legs","body_part":"upper legs","equipment":"stability ball","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings"],"target":"glutes","image":"images/1559-2LQkNPW.jpg","gif_url":"videos/1559-2LQkNPW.gif","instruction_steps":{"he":["הניחו את כדור הפיזיו על הרצפה וכרעו מולו.","הניחו את כף רגל ימין על כדור הפיזיו, עם ברך כפופה בזווית של 90 מעלות.","מתחו את רגל שמאל לאחור, כשהיא ישרה.","רכנו קדימה, בדחיפת האגן לכיוון כדור הפיזיו, עד תחושת מתיחה בכופף ירך ימין.","החזיקו את המתיחה 20–30 שניות, ואז החליפו צד וחזרו על התרגיל."],"en":["Place the stability ball on the ground and kneel in front of it.","Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.","Extend your left leg behind you, keeping it straight.","Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.","Hold the stretch for 20-30 seconds, then switch sides and repeat."],"ru":["Положите мяч на землю и встаньте перед ним на колени.","Поставьте правую ногу на фитбол, согнув колено под углом 90 градусов.","Вытяните левую ногу позади себя, сохраняя ее прямой.","Наклонитесь вперед, подталкивая бедра к мячу, пока не почувствуете растяжение в сгибателе правого бедра.","Удерживайте растяжку 20–30 секунд, затем поменяйте сторону и повторите."],"es":["Coloca el balón de estabilidad en el suelo y arrodíllate frente a él.","Coloca el pie derecho sobre el balón de estabilidad, con la rodilla flexionada en un ángulo de 90 grados.","Extiende la pierna izquierda hacia atrás, manteniéndola recta.","Inclínate hacia adelante, empujando las caderas hacia el balón de estabilidad, hasta sentir un estiramiento en el flexor de la cadera derecha.","Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."]}},{"id":"1338","name":"exercise ball hug","category":"back","body_part":"back","equipment":"stability ball","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"spine","image":"images/1338-d7z1Y7V.jpg","gif_url":"videos/1338-d7z1Y7V.gif","instruction_steps":{"he":["שבו על כדור הפיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו את כדור הפיזיו בשתי ידיים, בחיבוקו קרוב לחזה.","הפעילו את שרירי הליבה והיטו את הגוף לאחור באיטיות, תוך שמירה על גב ישר וכפות רגליים נטועות ברצפה.","המשיכו להטות לאחור עד לתחושת מתיחה בשרירי הגב.","החזיקו את התנוחה כמה שניות, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the stability ball with both hands, hugging it close to your chest.","Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.","Continue leaning back until you feel a stretch in your back muscles.","Hold the position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч, поставив ноги на землю и выпрямив спину.","Держите мяч обеими руками, прижимая его к груди.","Задействуйте мышцы корпуса и медленно откиньтесь назад, держа спину прямо, а ноги на земле.","Продолжайте откидываться назад, пока не почувствуете растяжение мышц спины.","Удерживайте положение несколько секунд, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta.","Sujeta el balón de estabilidad con ambas manos, abrazándolo cerca del pecho.","Activa los músculos del core y reclínate lentamente hacia atrás, manteniendo la espalda recta y los pies apoyados en el suelo.","Continúa reclinándote hacia atrás hasta sentir un estiramiento en los músculos de la espalda.","Mantén la posición durante unos segundos, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1339","name":"exercise ball lat stretch","category":"back","body_part":"back","equipment":"stability ball","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"lats","image":"images/1339-sM84pE4.jpg","gif_url":"videos/1339-sM84pE4.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד ביד אחת ומתחו את היד ישר מעל הראש.","רכנו באיטיות לצד הנגדי, עד תחושת מתיחה ברחב הגבי.","החזיקו את המתיחה 20–30 שניות, ואז חזרו לנקודת ההתחלה.","חזרו על התנועה בצד השני."],"en":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up overhead.","Slowly lean to the opposite side, feeling a stretch in your lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."],"ru":["Сядьте на мяч, поставив ноги на землю и выпрямив спину.","Возьмите гантель в одну руку и вытяните руку прямо над головой.","Медленно наклонитесь в противоположную сторону, чувствуя растяжение широчайших мышц.","Удерживайте растяжку 20–30 секунд, затем вернитесь в исходное положение.","Повторите с другой стороны."],"es":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.","Sujeta una mancuerna con una mano y extiende el brazo recto por encima de la cabeza.","Inclínate lentamente hacia el lado opuesto, sintiendo un estiramiento en el músculo dorsal.","Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.","Repite del otro lado."]}},{"id":"1341","name":"exercise ball lower back stretch (pyramid)","category":"back","body_part":"back","equipment":"stability ball","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"lats","image":"images/1341-yU7w7CA.jpg","gif_url":"videos/1341-yU7w7CA.gif","instruction_steps":{"he":["שבו על כדור הפיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","צעדו באיטיות עם כפות הרגליים קדימה, בגלגול הכדור לאורך הגב עד שהגב התחתון נשען על הכדור.","מקמו את הידיים מאחורי הראש או הצליבו אותן על החזה.","הפעילו את הליבה והורידו באיטיות את פלג הגוף העליון לכיוון הרצפה, ותנו לגב התחתון להימתח מעל הכדור.","החזיקו את המתיחה כמה שניות, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч для стабилизации, поставьте ступни на землю и согните колени под углом 90 градусов.","Медленно пройдите ногами вперед, катя мяч по спине, пока нижняя часть спины не окажется на мяче.","Заведите руки за голову или скрестите их на груди.","Напрягите корпус и медленно опустите верхнюю часть тела к земле, позволяя нижней части спины растянуться над мячом.","Удерживайте растяжку несколько секунд, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Camina lentamente hacia adelante con los pies, haciendo rodar el balón por tu espalda hasta que tu zona lumbar quede apoyada sobre el balón.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, permitiendo que tu zona lumbar se estire sobre el balón.","Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1342","name":"exercise ball lying side lat stretch","category":"back","body_part":"back","equipment":"stability ball","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"lats","image":"images/1342-rTbyBYV.jpg","gif_url":"videos/1342-rTbyBYV.gif","instruction_steps":{"he":["שכבו על הצד עם רגליים ישרות והראש נתמך על כדור הפיזיו.","הניחו את היד העליונה על הכדור לייצוב.","מתחו את היד העליונה מעל הראש ותנו לגו להסתובב מעט.","הרגישו את המתיחה ברחב הגבי בצד הגוף.","החזיקו את המתיחה 20–30 שניות, ואז החליפו צד וחזרו על התרגיל."],"en":["Lie on your side with your legs extended and your head supported by the stability ball.","Place your top arm on the ball for stability.","Reach your top arm overhead and allow your torso to rotate slightly.","Feel the stretch in your lat muscles on the side of your body.","Hold the stretch for 20-30 seconds, then switch sides and repeat."],"ru":["Лягте на бок, вытянув ноги и подперев голову мячом-стабилизатором.","Положите верхнюю руку на фитбол.","Вытяните верхнюю руку над головой и позвольте туловищу слегка повернуться.","Почувствуйте растяжение широчайших мышц по бокам тела.","Удерживайте растяжку 20–30 секунд, затем поменяйте сторону и повторите."],"es":["Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el balón de estabilidad.","Coloca el brazo de arriba sobre el balón para mantener la estabilidad.","Extiende el brazo de arriba por encima de la cabeza y permite que tu torso gire ligeramente.","Siente el estiramiento en los músculos dorsales del costado de tu cuerpo.","Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."]}},{"id":"1382","name":"exercise ball on the wall calf raise","category":"lower legs","body_part":"lower legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/1382-xo6sENf.jpg","gif_url":"videos/1382-xo6sENf.gif","instruction_steps":{"he":["עמדו עם הגב לקיר והניחו כדור פיזיו בין הגב התחתון לקיר.","מקמו את כפות הרגליים ברוחב כתפיים, כשקצות האצבעות פונות קדימה.","החזיקו משקולת יד בכל יד, עם ידיים מתוחות לצידי הגוף.","הרימו את העקבים מהרצפה, בהעברת משקל הגוף לכריות כפות הרגליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart, with your toes pointing forward.","Hold a dumbbell in each hand, with your arms extended by your sides.","Raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте спиной к стене и поместите мяч для упражнений между поясницей и стеной.","Поставьте ноги на ширине плеч, носки ног направлены вперед.","Возьмите по гантели в каждую руку, вытянув руки по бокам.","Поднимите пятки от земли, перенеся вес тела на подушечки стоп.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con la espalda contra una pared y coloca un balón de ejercicio entre tu zona lumbar y la pared.","Coloca los pies separados a la altura de los hombros, con la punta de los pies hacia adelante.","Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados.","Levanta los talones del suelo, llevando el peso de tu cuerpo hacia la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3241","name":"exercise ball on the wall calf raise (tennis ball between ankles)","category":"lower legs","body_part":"lower legs","equipment":"dumbbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/3241-FY3UdNT.jpg","gif_url":"videos/3241-FY3UdNT.gif","instruction_steps":{"he":["עמדו מול קיר עם רגליים ברוחב כתפיים.","הניחו כדור פיזיו בין הקיר לגב התחתון.","החזיקו משקולת יד בכל יד, עם ידיים מתוחות לצידי הגוף.","הניחו כדור טניס בין הקרסוליים.","הרימו את העקבים מהרצפה, בהרמת הגוף על קצות האצבעות.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing a wall with your feet shoulder-width apart.","Place an exercise ball between the wall and your lower back.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your ankles.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к стене, ноги на ширине плеч.","Поместите мяч для упражнений между стеной и поясницей.","Возьмите по гантели в каждую руку, вытянув руки по бокам.","Поместите теннисный мяч между лодыжками.","Поднимите пятки от земли, поднимая тело на носки.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a una pared con los pies separados a la altura de los hombros.","Coloca un balón de ejercicio entre la pared y tu zona lumbar.","Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados.","Coloca una pelota de tenis entre los tobillos.","Levanta los talones del suelo, elevando el cuerpo sobre la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3240","name":"exercise ball on the wall calf raise (tennis ball between knees)","category":"lower legs","body_part":"lower legs","equipment":"dumbbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings"],"target":"calves","image":"images/3240-j74M6Zn.jpg","gif_url":"videos/3240-j74M6Zn.gif","instruction_steps":{"he":["עמדו עם הגב לקיר והניחו כדור פיזיו בין הגב התחתון לקיר.","מקמו את כפות הרגליים ברוחב כתפיים ומעט לפניכם.","החזיקו משקולת יד בכל יד, עם ידיים מתוחות לצידי הגוף.","הניחו כדור טניס בין הברכיים.","הרימו את העקבים מהרצפה, בהרמת הגוף על קצות האצבעות.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart and slightly in front of you.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your knees.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте спиной к стене и поместите мяч для упражнений между поясницей и стеной.","Поставьте ноги на ширине плеч и немного впереди себя.","Возьмите по гантели в каждую руку, вытянув руки по бокам.","Поместите теннисный мяч между коленями.","Поднимите пятки от земли, поднимая тело на носки.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con la espalda contra una pared y coloca un balón de ejercicio entre tu zona lumbar y la pared.","Coloca los pies separados a la altura de los hombros y ligeramente por delante de ti.","Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados.","Coloca una pelota de tenis entre las rodillas.","Levanta los talones del suelo, elevando el cuerpo sobre la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1416","name":"exercise ball one leg prone lower body rotation","category":"upper legs","body_part":"upper legs","equipment":"stability ball","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","core"],"target":"glutes","image":"images/1416-M72BExt.jpg","gif_url":"videos/1416-M72BExt.gif","instruction_steps":{"he":["שכבו על הבטן על כדור הפיזיו כשהאגן נשען על הכדור והרגליים מתוחות ישר לאחור.","הניחו את הידיים על הרצפה לפניכם לתמיכה.","הפעילו את הישבן ושרירי הליבה לייצוב הגוף.","הרימו באיטיות רגל אחת מהרצפה, כשהיא ישרה ומקבילה לרצפה.","סובבו את הרגל החוצה, הרחק מהגוף, תוך שמירה על אגן ופלג גוף עליון יציבים.","עצרו לרגע בסוף הסיבוב, ואז החזירו באיטיות את הרגל לנקודת ההתחלה.","חזרו על הסיבוב עם הרגל השנייה.","המשיכו להחליף רגליים למספר החזרות הרצוי."],"en":["Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for support.","Engage your glutes and core muscles to stabilize your body.","Slowly lift one leg off the ground, keeping it straight and parallel to the floor.","Rotate your leg outward, away from your body, while keeping your hips and upper body stable.","Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.","Repeat the rotation with the other leg.","Continue alternating legs for the desired number of repetitions."],"ru":["Лягте на мяч лицом вниз, положив бедра на мяч и вытянув ноги прямо позади себя.","Положите руки на землю перед собой для поддержки.","Задействуйте ягодицы и мышцы корпуса, чтобы стабилизировать тело.","Медленно поднимите одну ногу с земли, держа ее прямой и параллельной полу.","Поверните ногу наружу, от тела, сохраняя при этом бедра и верхнюю часть тела устойчивыми.","Сделайте небольшую паузу в конце вращения, затем медленно верните ногу в исходное положение.","Повторите вращение другой ногой.","Продолжайте чередовать ноги желаемое количество повторений."],"es":["Túmbate boca abajo sobre el balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti.","Coloca las manos en el suelo frente a ti para mayor apoyo.","Activa los glúteos y el abdomen para estabilizar el cuerpo.","Levanta lentamente una pierna del suelo, manteniéndola recta y paralela al piso.","Gira la pierna hacia afuera, alejándola del cuerpo, mientras mantienes las caderas y la parte superior del cuerpo estables.","Haz una pausa al final de la rotación, luego regresa lentamente la pierna a la posición inicial.","Repite la rotación con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."]}},{"id":"1417","name":"exercise ball one legged diagonal kick hamstring curl","category":"upper legs","body_part":"upper legs","equipment":"stability ball","muscle_group":"hamstrings","secondary_muscles":["hamstrings","calves"],"target":"glutes","image":"images/1417-GOJKFfO.jpg","gif_url":"videos/1417-GOJKFfO.gif","instruction_steps":{"he":["התחילו בשכיבה על הגב עם רגליים מתוחות והעקבים מונחים על כדור הפיזיו.","הניחו את הידיים לצידי הגוף לייצוב.","הפעילו את הישבן ושרירי הליבה להרמת האגן מהרצפה, ביצירת קו ישר מהכתפיים ועד העקבים.","כופפו את ברך ימין והביאו אותה לכיוון החזה, תוך שמירה על רגל שמאל מתוחה וכף הרגל מכופפת.","בעטו את רגל ימין באלכסון על פני הגוף, במתיחתה המלאה והפעלת הירך האחורית.","החזירו באיטיות את רגל ימין לנקודת ההתחלה, תוך שמירה על שליטה ויציבות.","חזרו על התנועה עם רגל שמאל, לסירוגין בין הצדדים למספר החזרות הרצוי."],"en":["Start by lying on your back with your legs extended and your heels resting on top of the stability ball.","Place your arms by your sides for stability.","Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels.","Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed.","Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings.","Slowly return your right leg to the starting position, maintaining control and stability.","Repeat the movement with your left leg, alternating sides for the desired number of repetitions."],"ru":["Начните с того, что лягте на спину, вытянув ноги и положив пятки на мяч для стабилизации.","Положите руки по бокам для устойчивости.","Задействуйте ягодицы и мышцы корпуса, чтобы оторвать бедра от земли, создавая прямую линию от плеч до пяток.","Согните правое колено и поднесите его к груди, сохраняя левую ногу вытянутой, а ступню согнутой.","Ударьте правой ногой по диагонали через тело, полностью выпрямляя ее и задействуя мышцы задней поверхности бедра.","Медленно верните правую ногу в исходное положение, сохраняя контроль и устойчивость.","Повторите движение левой ногой, чередуя стороны необходимое количество повторений."],"es":["Comienza acostado sobre la espalda con las piernas extendidas y los talones apoyados sobre el balón de estabilidad.","Coloca los brazos a los lados del cuerpo para mantener el equilibrio.","Activa los glúteos y el abdomen para levantar las caderas del suelo, formando una línea recta desde los hombros hasta los talones.","Dobla la rodilla derecha y llévala hacia el pecho, manteniendo la pierna izquierda extendida y el pie en flexión.","Lleva la pierna derecha en diagonal a través del cuerpo, extendiéndola por completo y activando los isquiotibiales.","Regresa lentamente la pierna derecha a la posición inicial, manteniendo el control y el equilibrio.","Repite el movimiento con la pierna izquierda, alternando los lados durante el número de repeticiones deseado."]}},{"id":"1296","name":"exercise ball pike push up","category":"chest","body_part":"chest","equipment":"stability ball","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","core"],"target":"pectorals","image":"images/1296-sVvXT5J.jpg","gif_url":"videos/1296-sVvXT5J.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם הידיים על הרצפה והשוקיים מונחות על כדור הפיזיו.","הפעילו את הליבה והרימו את האגן לכיוון התקרה, בגלגול הכדור לכיוון הידיים.","שמרו על רגליים ישרות וגוף בתנוחת פייק, ביצירת צורת V הפוכה.","כופפו מרפקים והורידו את פלג הגוף העליון לכיוון הרצפה, תוך שמירה על הראש בקו אחד עם הידיים.","דחפו דרך הידיים ויישרו אותן לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands on the floor and your shins resting on the stability ball.","Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands.","Keep your legs straight and your body in a pike position, forming an inverted V shape.","Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции для отжиманий, положив руки на пол и положив голени на мяч для стабилизации.","Напрягите корпус и поднимите бедра к потолку, катя мяч к рукам.","Держите ноги прямыми, а тело в положении пики, образуя перевернутую V-образную форму.","Согните локти и опустите верхнюю часть тела к полу, удерживая голову на одной линии с руками.","Оттолкнитесь руками и вытяните руки, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de flexión de brazos con las manos en el suelo y las espinillas apoyadas sobre el balón de estabilidad.","Activa el core y levanta las caderas hacia el techo, haciendo rodar el balón hacia las manos.","Mantén las piernas rectas y el cuerpo en posición de pica, formando una V invertida.","Dobla los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo la cabeza alineada con las manos.","Empuja con las manos y extiende los brazos para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1343","name":"exercise ball prone leg raise","category":"back","body_part":"back","equipment":"stability ball","muscle_group":"abdominals","secondary_muscles":["abdominals","glutes"],"target":"spine","image":"images/1343-lCKm4Rs.jpg","gif_url":"videos/1343-lCKm4Rs.gif","instruction_steps":{"he":["שכבו על הבטן על מזרן עם רגליים ישרות וקצות האצבעות של הרגליים על כדור הפיזיו.","הניחו את הידיים על הרצפה, ברוחב כתפיים, והפעילו את שרירי הליבה.","תוך שמירה על רגליים ישרות, הרימו אותן באיטיות מהרצפה, בעזרת הגב התחתון והישבן, גבוה ככל האפשר.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.","Place your hands on the ground, shoulder-width apart, and engage your core muscles.","Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте лицом вниз на коврик, вытянув ноги и положив пальцы ног на мяч для стабилизации.","Положите руки на пол на ширине плеч и задействуйте мышцы корпуса.","Держа ноги прямыми, медленно поднимите их от земли, используя поясницу и ягодицы, чтобы поднять их как можно выше.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo sobre una esterilla con las piernas extendidas y los dedos de los pies apoyados sobre el balón de estabilidad.","Coloca las manos en el suelo, separadas a la altura de los hombros, y activa el abdomen.","Manteniendo las piernas rectas, levántalas lentamente del suelo, usando la zona lumbar y los glúteos para elevarlas tan alto como sea posible.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1560","name":"exercise ball seated hamstring stretch","category":"upper legs","body_part":"upper legs","equipment":"stability ball","muscle_group":"glutes","secondary_muscles":["glutes","lower back"],"target":"hamstrings","image":"images/1560-yRYyfdA.jpg","gif_url":"videos/1560-yRYyfdA.gif","instruction_steps":{"he":["שבו על כדור הפיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","גלגלו באיטיות את הכדור קדימה, בצעידה עם כפות הרגליים החוצה, עד שהגב העליון נשען על הכדור והרגליים מתוחות ישר לפניכם.","הניחו את הידיים על המותניים לתמיכה.","הפעילו את הליבה והורידו באיטיות את פלג הגוף העליון לכיוון הרצפה, תוך שמירה על גב ישר וחזה מורם.","עצרו כשתרגישו מתיחה בירך האחורית, והחזיקו את התנוחה 20–30 שניות.","חזרו באיטיות לנקודת ההתחלה בדחיפה דרך העקבים ושימוש בירך האחורית למשיכת הגוף חזרה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.","Place your hands on your hips for support.","Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted.","Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds.","Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч для стабилизации, поставьте ступни на землю и согните колени под углом 90 градусов.","Медленно катите мяч вперед, вытягивая ноги вперед, пока верхняя часть спины не окажется на мяче, а ноги не вытянуты прямо перед собой.","Положите руки на бедра для поддержки.","Напрягите корпус и медленно опустите верхнюю часть тела к земле, сохраняя спину прямой и грудь приподнятой.","Остановитесь, когда почувствуете растяжение подколенных сухожилий, и удерживайте это положение 20–30 секунд.","Медленно вернитесь в исходное положение, отталкиваясь пятками и используя мышцы задней поверхности бедра, чтобы подтянуться обратно.","Повторите необходимое количество повторений."],"es":["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Haz rodar el balón lentamente hacia adelante, caminando con los pies hacia afuera hasta que la parte superior de la espalda quede apoyada sobre el balón y las piernas queden extendidas rectas frente a ti.","Coloca las manos en las caderas para mayor apoyo.","Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, manteniendo la espalda recta y el pecho elevado.","Detente cuando sientas un estiramiento en los isquiotibiales y mantén la posición durante 20-30 segundos.","Regresa lentamente a la posición inicial empujando con los talones y usando los isquiotibiales para volver a subir.","Repite el número de repeticiones deseado."]}},{"id":"1745","name":"exercise ball seated triceps stretch","category":"upper arms","body_part":"upper arms","equipment":"stability ball","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1745-7ePTw4B.jpg","gif_url":"videos/1745-7ePTw4B.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו משקולת יד ביד אחת ומתחו את היד ישר מעל הראש.","כופפו את המרפק והורידו את המשקולת מאחורי הראש, תוך שמירה על הזרוע העליונה צמודה לאוזן.","החזיקו את המתיחה כמה שניות, ואז חזרו לנקודת ההתחלה.","חזרו על התנועה עם היד השנייה."],"en":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up above your head.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear.","Hold the stretch for a few seconds, then return to the starting position.","Repeat with the other arm."],"ru":["Сядьте на мяч, поставив ноги на землю и выпрямив спину.","Возьмите гантель в одну руку и вытяните руку прямо над головой.","Согните локоть и опустите гантель за голову, держа плечо близко к уху.","Удерживайте растяжку несколько секунд, затем вернитесь в исходное положение.","Повторите с другой рукой."],"es":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.","Sostén una mancuerna con una mano y extiende el brazo recto por encima de la cabeza.","Dobla el codo y baja la mancuerna detrás de la cabeza, manteniendo el brazo cerca de la oreja.","Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial.","Repite con el otro brazo."]}},{"id":"1746","name":"exercise ball supine triceps extension","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1746-Gm2Uv1z.jpg","gif_url":"videos/1746-Gm2Uv1z.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","החזיקו משקולת יד בשתי הידיים ומתחו את הידיים ישר לכיוון התקרה.","הורידו באיטיות את המשקולת מאחורי הראש, תוך שמירה על מרפקים קרובים לאוזניים.","עצרו לרגע, ואז הרימו את המשקולת חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with both hands and extend your arms straight up towards the ceiling.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на гимнастический мяч, поставьте ступни на землю и согните колени под углом 90 градусов.","Возьмите гантель обеими руками и вытяните руки прямо вверх к потолку.","Медленно опустите гантель за голову, держа локти близко к ушам.","Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia el techo.","Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas.","Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1747","name":"ez bar french press on exercise ball","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1747-CFN9P8G.jpg","gif_url":"videos/1747-CFN9P8G.gif","instruction_steps":{"he":["שבו על כדור פיזיו והחזיקו מוט EZ באחיזה עליונה.","מתחו את הידיים ישר למעלה, תוך שמירה על מרפקים קרובים לראש.","הורידו באיטיות את המוט מאחורי הראש בכיפוף מרפקים.","עצרו לרגע, ואז יישרו את הידיים חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on an exercise ball and hold an EZ barbell with an overhand grip.","Extend your arms straight up, keeping your elbows close to your head.","Slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на гимнастический мяч и возьмите штангу EZ хватом сверху.","Вытяните руки прямо вверх, держа локти близко к голове.","Медленно опустите штангу за голову, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de ejercicio y sostén una barra EZ con agarre prono.","Extiende los brazos rectos hacia arriba, manteniendo los codos cerca de la cabeza.","Baja lentamente la barra detrás de la cabeza doblando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3010","name":"ez bar lying bent arms pullover","category":"back","body_part":"back","equipment":"ez barbell","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"lats","image":"images/3010-nDK1HJ0.jpg","gif_url":"videos/3010-nDK1HJ0.gif","instruction_steps":{"he":["שכבו על ספסל כשהראש בקצה אחד וכפות הרגליים על הרצפה.","החזיקו את מוט ה-EZ באחיזה עליונה (כפות ידיים פונות מכם) וידיים ברוחב כתפיים.","מתחו את הידיים ישר מעל החזה, עם כיפוף קל במרפקים.","הורידו את המוט בתנועה קשתית מאחורי הראש, תוך שמירה על הכיפוף הקל במרפקים.","עצרו לרגע, ואז החזירו את המוט לנקודת ההתחלה בהיפוך תנועת הקשת.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart.","Extend your arms straight above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows.","Pause for a moment, then return the barbell to the starting position by reversing the arc motion.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив голову на один конец и поставив ноги на пол.","Держите штангу EZ пронированным хватом (ладонями от себя), руки на ширине плеч.","Вытяните руки прямо над грудью, сохраняя небольшой изгиб в локтях.","Опустите штангу дугообразным движением за голову, сохраняя небольшой изгиб в локтях.","Сделайте паузу на мгновение, затем верните штангу в исходное положение, изменив движение по дуге.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.","Sostén la barra EZ con agarre prono (palmas hacia afuera) y las manos separadas a la altura de los hombros.","Extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos.","Baja la barra describiendo un arco detrás de la cabeza, manteniendo la ligera flexión en los codos.","Haz una pausa breve, luego regresa la barra a la posición inicial invirtiendo el movimiento del arco.","Repite el número de repeticiones deseado."]}},{"id":"1748","name":"ez bar lying close grip triceps extension behind head","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1748-6CKUx7o.jpg","gif_url":"videos/1748-6CKUx7o.gif","instruction_steps":{"he":["שכבו על ספסל עם כפות רגליים על הרצפה והראש בקצה הספסל.","החזיקו את מוט ה-EZ באחיזה צרה, כפות ידיים כלפי מעלה, ומתחו את הידיים ישר מעל החזה.","תוך שמירה על הזרועות העליונות ללא תזוזה, הורידו באיטיות את המוט מאחורי הראש בכיפוף מרפקים.","עצרו לרגע, ואז יישרו את הידיים חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Возьмите штангу ez узким хватом ладонями вверх и вытяните руки прямо над грудью.","Удерживая плечи неподвижно, медленно опустите штангу за голову, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sostén la barra EZ con agarre cerrado, palmas hacia arriba, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1344","name":"ez bar reverse grip bent over row","category":"back","body_part":"back","equipment":"ez barbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1344-G8dXpNG.jpg","gif_url":"videos/1344-G8dXpNG.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","החזיקו את מוט ה-EZ באחיזה תחתונה, כפות ידיים כלפי מעלה, וידיים ברוחב כתפיים.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וחזה מורם, עד שהגו כמעט מקביל לרצפה.","משכו את מוט ה-EZ לכיוון החזה התחתון, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את מוט ה-EZ באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the ez barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Держите штангу ez обратным хватом ладонями вверх, руки на ширине плеч.","Наклонитесь вперед в бедрах, держа спину прямо и грудь вверх, пока туловище не станет почти параллельно полу.","Потяните штангу EZ к нижней части груди, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу EZ обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros.","Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo.","Tira de la barra EZ hacia la parte baja del pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte superior, luego baja lentamente la barra EZ a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1682","name":"ez bar seated close grip concentration curl","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1682-Dsfz0Id.jpg","gif_url":"videos/1682-Dsfz0Id.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו מוט EZ באחיזה תחתונה.","השעינו את המרפק על החלק הפנימי של הירך, מעט מעל הברך.","כופפו את המוט למעלה לכיוון הכתף, תוך שמירה על הזרוע העליונה ללא תזוזה.","כווצו את הבייספס בנקודה העליונה של התנועה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.","Rest your elbow on the inside of your thigh, just above the knee.","Curl the barbell up towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите штангу EZ хватом снизу.","Положите локоть на внутреннюю часть бедра, чуть выше колена.","Поднимите штангу к плечу, сохраняя плечо неподвижным.","Напрягите бицепсы в верхней точке движения, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados en el suelo y sostén una barra EZ con agarre supino.","Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.","Sube la barra curvando el brazo hacia el hombro mientras mantienes el brazo superior inmóvil.","Contrae los bíceps en la parte superior del movimiento, luego baja lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1749","name":"ez bar standing french press","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1749-1cTf2Ux.jpg","gif_url":"videos/1749-1cTf2Ux.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את מוט ה-EZ באחיזה עליונה.","הרימו את המוט מעל הראש, עד יישור מלא של הידיים.","תוך שמירה על הזרועות העליונות קרובות לראש, הורידו באיטיות את המוט מאחורי הראש בכיפוף המרפקים.","עצרו לרגע, ואז יישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, и возьмите штангу ez хватом сверху.","Поднимите штангу над головой, полностью выпрямив руки.","Держа плечи близко к голове, медленно опустите штангу за голову, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre prono.","Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.","Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0445","name":"ez barbell anti gravity press","category":"shoulders","body_part":"shoulders","equipment":"ez barbell","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0445-fprd84i.jpg","gif_url":"videos/0445-fprd84i.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים, אוחזים את מוט ה-EZ באחיזה עליונה.","הרימו את המוט לגובה הכתפיים, עם מרפקים כפופים מעט וכפות ידיים פונות קדימה.","לחצו את המוט מעל הראש, עד יישור מלא של הידיים.","הורידו את המוט חזרה לגובה הכתפיים וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip.","Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, расставив ноги на ширине плеч, и возьмите штангу ez хватом сверху.","Поднимите штангу на высоту плеч, держа локти слегка согнутыми и ладонями вперед.","Выжмите штангу над головой, полностью выпрямив руки.","Опустите штангу обратно на высоту плеч и повторите необходимое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de los hombros y sosteniendo la barra EZ con agarre prono.","Eleva la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y las palmas hacia adelante.","Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.","Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado."]}},{"id":"1627","name":"ez barbell close grip preacher curl","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1627-hacCyUv.jpg","gif_url":"videos/1627-hacCyUv.gif","instruction_steps":{"he":["שבו על ספסל הפריצ'ר והניחו את הזרועות העליונות על הכרית, אוחזים את מוט ה-EZ באחיזה תחתונה.","השעינו את הטרייספס על הכרית ומתחו את הידיים לגמרי, תוך שמירה על גב ישר.","כופפו באיטיות את המוט לכיוון הכתפיים, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","הורידו את המוט חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.","Rest your triceps on the pad and fully extend your arms, keeping your back straight.","Slowly curl the barbell towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью для сгибаний рук и положите плечи на подушечку, возьмите штангу обратным хватом.","Положите трицепсы на подушку и полностью выпрямите руки, сохраняя спину прямой.","Медленно поднимите штангу к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Опустите штангу обратно в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco scott y coloca los brazos superiores sobre la almohadilla, sujetando la barra EZ con agarre supino.","Apoya los tríceps sobre la almohadilla y extiende los brazos por completo, manteniendo la espalda recta.","Sube lentamente la barra hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte alta, apretando los bíceps.","Baja la barra a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."]}},{"id":"0446","name":"ez barbell close-grip curl","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0446-V4ryaZa.jpg","gif_url":"videos/0446-V4ryaZa.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו את מוט ה-EZ באחיזה תחתונה, ידיים ברוחב כתפיים.","שמרו על מרפקים צמודים לגו וזרועות עליונות ללא תזוזה לאורך כל התנועה.","כופפו את המוט למעלה לכיוון הכתפיים, תוך כיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу обратным хватом, руки на ширине плеч.","Держите локти близко к туловищу, а плечи неподвижно на протяжении всего движения.","Поднимите штангу к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos separadas a la altura de los hombros.","Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.","Sube la barra hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0447","name":"ez barbell curl","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0447-6TG6x2w.jpg","gif_url":"videos/0447-6TG6x2w.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו את מוט ה-EZ באחיזה תחתונה, כפות ידיים כלפי מעלה.","שמרו על מרפקים צמודים לגו וזרועות עליונות ללא תזוזה לאורך כל התנועה.","נשפו תוך כיפוף המוט למעלה לכיוון הכתפיים, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז שאפו תוך הורדת המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Exhale as you curl the barbell up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу обратным хватом ладонями вверх.","Держите локти близко к туловищу, а плечи неподвижно на протяжении всего движения.","На выдохе поднимите штангу к плечам, напрягая бицепсы.","Сделайте паузу на мгновение в верхней точке, затем на вдохе медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba.","Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.","Exhala mientras subes la barra hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta, luego inhala mientras bajas lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0448","name":"ez barbell decline close grip face press","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0448-DgZQ11d.jpg","gif_url":"videos/0448-DgZQ11d.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשהראש נמוך מהרגליים.","אחזו במוט ה-EZ באחיזה צרה, כפות ידיים פונות זו לזו.","מתחו את הידיים ישר מעל החזה, תוך שמירה על מרפקים קרובים לגוף.","הורידו את המוט לכיוון המצח בכיפוף המרפקים.","עצרו לרגע, ואז לחצו את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on a decline bench with your head lower than your feet.","Grasp the ez barbell with a close grip, palms facing each other.","Extend your arms straight up above your chest, keeping your elbows close to your body.","Lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then press the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью так, чтобы голова была ниже ног.","Возьмите штангу ez узким хватом, ладони обращены друг к другу.","Вытяните руки прямо над грудью, держа локти близко к телу.","Опустите штангу ко лбу, согнув локти.","Сделайте паузу на мгновение, затем верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con la cabeza más baja que los pies.","Sujeta la barra EZ con agarre cerrado, palmas una frente a la otra.","Extiende los brazos rectos por encima del pecho, manteniendo los codos cerca del cuerpo.","Baja la barra hacia la frente doblando los codos.","Haz una pausa breve, luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2186","name":"ez barbell decline triceps extension","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/2186-CQHoDm0.jpg","gif_url":"videos/2186-CQHoDm0.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשהראש נמוך מהרגליים וכפות הרגליים מקובעות.","החזיקו את מוט ה-EZ באחיזה עליונה, ידיים ברוחב כתפיים.","יישרו את הידיים לגמרי, תוך שמירה על מרפקים קרובים לראש.","הורידו את המוט באיטיות לכיוון המצח, בכיפוף המרפקים.","עצרו לרגע, ואז יישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on a decline bench with your head lower than your feet and your feet secured.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your head.","Lower the barbell slowly towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, опустив голову ниже ног и закрепив ступни.","Держите штангу ez хватом сверху, руки на ширине плеч.","Полностью выпрямите руки, держа локти близко к голове.","Медленно опустите штангу ко лбу, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco declinado con la cabeza más baja que los pies y los pies asegurados.","Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros.","Extiende completamente los brazos, manteniendo los codos cerca de la cabeza.","Baja la barra lentamente hacia la frente, doblando los codos.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0449","name":"ez barbell incline triceps extension","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0449-KyLtiLT.jpg","gif_url":"videos/0449-KyLtiLT.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שבו על הספסל כשהגב צמוד לכרית והחזיקו את מוט ה-EZ באחיזה עליונה.","מתחו את הידיים לגמרי מעל הראש, תוך שמירה על מרפקים קרובים לראש.","הורידו את המוט מאחורי הראש בכיפוף מרפקים, תוך שמירה על זרועות עליונות ללא תזוזה.","עצרו לרגע, ואז יישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Сядьте на скамью, прислонившись спиной к подушке, и возьмите штангу ez верхним хватом.","Вытяните руки полностью над головой, держа локти близко к голове.","Опустите штангу за голову, согнув локти, сохраняя плечи неподвижными.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con la espalda apoyada en el respaldo y sostén la barra EZ con agarre prono.","Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de la cabeza.","Baja la barra detrás de la cabeza doblando los codos, manteniendo los brazos superiores inmóviles.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0450","name":"ez barbell jm bench press","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0450-hnOYgH3.jpg","gif_url":"videos/0450-hnOYgH3.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","אחזו במוט ה-EZ באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הורידו את המוט לחזה, עם מרפקים צמודים לגוף.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу ez хватом сверху, на расстоянии чуть шире плеч.","Опустите штангу к груди, держа локти близко к телу.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Sujeta la barra EZ con agarre prono, ligeramente más ancho que la altura de los hombros.","Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0451","name":"ez barbell reverse grip curl","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0451-Y5X65IB.jpg","gif_url":"videos/0451-Y5X65IB.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו את מוט ה-EZ באחיזה תחתונה.","שמרו על מרפקים צמודים לגו וזרועות עליונות ללא תזוזה לאורך כל התרגיל.","כופפו את המוט כלפי מעלה בכיווץ הבייספס, תוך נשיפה.","המשיכו להרים את המוט עד שהבייספס מכווץ במלואו והוא בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","התחילו להחזיר את המוט באיטיות לנקודת ההתחלה תוך שאיפה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip.","Keep your elbows close to your torso and your upper arms stationary throughout the exercise.","Curl the barbell upwards by contracting your biceps, while exhaling.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the barbell back to the starting position as you inhale.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч и возьмите штангу обратным хватом.","На протяжении всего упражнения держите локти близко к туловищу, а плечи — неподвижно.","Поднимите штангу вверх, напрягая бицепсы и выдыхая.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Медленно на вдохе начните возвращать штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino.","Mantén los codos cerca del torso y los brazos superiores inmóviles durante todo el ejercicio.","Sube la barra contrayendo los bíceps, mientras exhalas.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Comienza a regresar la barra lentamente a la posición inicial mientras inhalas.","Repite el número de repeticiones deseado."]}},{"id":"0452","name":"ez barbell reverse grip preacher curl","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0452-vBNyir7.jpg","gif_url":"videos/0452-vBNyir7.gif","instruction_steps":{"he":["שבו על ספסל פריצ'ר כשהחזה צמוד לכרית וכפות הרגליים על הרצפה.","אחזו במוט ה-EZ באחיזה תחתונה, ידיים ברוחב כתפיים.","השעינו את הזרועות העליונות על הכרית, ותנו לאמות להשתלשל מטה.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המוט למעלה לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a preacher bench with your chest against the pad and your feet flat on the floor.","Grasp the ez barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms on the pad, allowing your forearms to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью для проповедника, прижав грудь к подушке и поставив ноги на пол.","Возьмите штангу ez обратным хватом, руки на ширине плеч.","Положите плечи на подушку так, чтобы предплечья свисали вниз.","Удерживая плечи неподвижно, выдохните и поднимите штангу к плечам.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco scott con el pecho apoyado en la almohadilla y los pies planos sobre el suelo.","Sujeta la barra EZ con agarre supino, manos separadas a la altura de los hombros.","Apoya los brazos superiores en la almohadilla, dejando que los antebrazos cuelguen hacia abajo.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.","Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1458","name":"ez barbell seated curls","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1458-jtFKbt5.jpg","gif_url":"videos/1458-jtFKbt5.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה וגב ישר.","החזיקו את מוט ה-EZ באחיזה תחתונה, כפות ידיים כלפי מעלה, וידיים ברוחב כתפיים.","השעינו את הזרועות העליונות על הירכיים, ותנו למוט ה-EZ להשתלשל לפניכם.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את מוט ה-EZ למעלה לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את מוט ה-EZ באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and your back straight.","Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you.","Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставив ноги на землю и выпрямив спину.","Держите штангу ez обратным хватом ладонями вверх, руки на ширине плеч.","Положите плечи на бедра, позволяя штанге свисать перед вами.","Удерживая плечи неподвижно, выдохните и поднимите штангу вверх к плечам.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите штангу EZ в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta.","Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros.","Apoya los brazos superiores en los muslos, dejando que la barra EZ cuelgue frente a ti.","Manteniendo los brazos superiores inmóviles, exhala y sube la barra EZ hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra EZ a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0453","name":"ez barbell seated triceps extension","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0453-iaapw0g.jpg","gif_url":"videos/0453-iaapw0g.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו את מוט ה-EZ באחיזה עליונה, ידיים ברוחב כתפיים.","הרימו את המוט מעל הראש, עד יישור מלא של הידיים.","תוך שמירה על הזרועות העליונות ללא תזוזה, הורידו את המוט מאחורי הראש בכיפוף המרפקים.","עצרו לרגע, ואז הרימו את המוט חזרה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Держите штангу ez хватом сверху, руки на ширине плеч.","Поднимите штангу над головой, полностью выпрямив руки.","Удерживая плечи неподвижно, опустите штангу за голову, согнув локти.","Сделайте паузу на мгновение, затем поднимите штангу обратно в исходное положение, вытянув руки.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros.","Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.","Manteniendo los brazos superiores inmóviles, baja la barra detrás de la cabeza doblando los codos.","Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0454","name":"ez barbell spider curl","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0454-Ye5Qxb0.jpg","gif_url":"videos/0454-Ye5Qxb0.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את מוט ה-EZ באחיזה תחתונה, כפות ידיים כלפי מעלה.","השעינו את הזרועות העליונות על ספסל פריצ'ר או כדור פיזיו, ותנו למרפקים להשתלשל מטה.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המוט למעלה לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу обратным хватом ладонями вверх.","Положите плечи на скамью проповедника или мяч для стабилизации, позволяя локтям свисать вниз.","Удерживая плечи неподвижно, выдохните и поднимите штангу к плечам.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba.","Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1628","name":"ez barbell spider curl","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1628-2kattbR.jpg","gif_url":"videos/1628-2kattbR.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את מוט ה-EZ באחיזה תחתונה, כפות ידיים כלפי מעלה.","השעינו את הזרועות העליונות על ספסל פריצ'ר או כדור פיזיו, ותנו למרפקים להשתלשל מטה.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את המוט למעלה לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу обратным хватом ладонями вверх.","Положите плечи на скамью проповедника или мяч для стабилизации, позволяя локтям свисать вниз.","Удерживая плечи неподвижно, выдохните и поднимите штангу к плечам.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba.","Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2404","name":"ez-bar biceps curl (with arm blaster)","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2404-tJ5nYqo.jpg","gif_url":"videos/2404-tJ5nYqo.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו את מוט ה-EZ באחיזה תחתונה, כפות ידיים כלפי מעלה.","הצמידו את הזרועות העליונות לארם-בלאסטר, תוך שמירה עליהן ללא תזוזה לאורך כל התרגיל.","תוך שמירה על מרפקים קרובים לגוף, נשפו וכופפו את המוט למעלה לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping them stationary throughout the exercise.","Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу обратным хватом ладонями вверх.","Прижмите плечи к армбластеру, сохраняя их неподвижными на протяжении всего упражнения.","Держа локти близко к телу, выдохните и поднимите штангу к плечам.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите штангу обратно в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba.","Coloca los brazos superiores contra el soporte de aislamiento de brazos, manteniéndolos inmóviles durante todo el ejercicio.","Manteniendo los codos cerca del cuerpo, exhala y sube la barra hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"2432","name":"ez-bar close-grip bench press","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/2432-da4cXST.jpg","gif_url":"videos/2432-da4cXST.gif","instruction_steps":{"he":["שכבו על הספסל עם כפות רגליים על הרצפה והגב צמוד לספסל.","אחזו במוט ה-EZ באחיזה צרה, ידיים ברוחב כתפיים, כפות ידיים פונות קדימה.","הרימו את המוט מהמתקן והחזיקו אותו ישר מעל החזה עם ידיים ישרות לגמרי.","הורידו את המוט באיטיות לכיוון החזה, תוך שמירה על מרפקים קרובים לגוף.","עצרו לרגע כשהמוט נוגע בחזה.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу ez узким хватом, руки на ширине плеч, ладони смотрят вперед.","Снимите штангу со стойки и держите ее прямо над грудью, полностью вытянув руки.","Медленно опустите штангу к груди, держа локти близко к телу.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Sujeta la barra EZ con agarre cerrado, manos separadas a la altura de los hombros, palmas hacia adelante.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"2741","name":"ez-barbell standing wide grip biceps curl","category":"upper arms","body_part":"upper arms","equipment":"ez barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2741-OVTZ65k.jpg","gif_url":"videos/2741-OVTZ65k.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו את מוט ה-EZ באחיזה תחתונה, ידיים רחבות מרוחב הכתפיים.","שמרו על מרפקים צמודים לגו וזרועות עליונות ללא תזוזה לאורך כל התנועה.","כופפו את המוט למעלה לכיוון הכתפיים בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу обратным хватом, руки шире ширины плеч.","Держите локти близко к туловищу, а плечи неподвижно на протяжении всего движения.","Поднимите штангу к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos más separadas que la altura de los hombros.","Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.","Sube la barra hacia los hombros contrayendo los bíceps.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2133","name":"farmers walk","category":"upper legs","body_part":"upper legs","equipment":"dumbbell","muscle_group":"calves","secondary_muscles":["calves","forearms","core"],"target":"quads","image":"images/2133-qPEzJjA.jpg","gif_url":"videos/2133-qPEzJjA.gif","instruction_steps":{"he":["עמדו זקוף עם משקולת יד בכל יד, כפות ידיים פונות לצידי הגוף.","שמרו על גב ישר וכתפיים לאחור.","צעדו צעדים קטנים ומבוקרים קדימה, תוך שמירה על יציבה זקופה.","המשיכו ללכת למרחק או לזמן הרצוי.","לסיום, עצרו את ההליכה והורידו בזהירות את המשקולות לצידי הגוף."],"en":["Stand up straight with a dumbbell in each hand, palms facing your sides.","Keep your back straight and your shoulders back.","Take small, controlled steps forward, maintaining an upright posture.","Continue walking for the desired distance or time.","To finish, stop walking and carefully lower the dumbbells to your sides."],"ru":["Встаньте прямо, возьмите в каждую руку по гантели, ладони повернуты в стороны.","Держите спину прямо, а плечи отведите назад.","Делайте небольшие контролируемые шаги вперед, сохраняя вертикальное положение.","Продолжайте идти желаемое расстояние или время.","В завершение остановитесь и осторожно опустите гантели в стороны."],"es":["Ponte de pie con una mancuerna en cada mano, palmas hacia los costados.","Mantén la espalda recta y los hombros hacia atrás.","Da pasos pequeños y controlados hacia adelante, manteniendo una postura erguida.","Continúa caminando durante la distancia o el tiempo deseado.","Para terminar, deja de caminar y baja con cuidado las mancuernas a los costados."]}},{"id":"0455","name":"finger curls","category":"lower arms","body_part":"lower arms","equipment":"barbell","muscle_group":"wrist flexors","secondary_muscles":["wrist flexors","grip muscles"],"target":"forearms","image":"images/0455-awG04cF.jpg","gif_url":"videos/0455-awG04cF.gif","instruction_steps":{"he":["שבו על ספסל עם כפות רגליים על הרצפה והחזיקו מוט באחיזה תחתונה, כפות ידיים כלפי מעלה.","הניחו את האמות על הירכיים, כששורשי כף היד משתלשלים מעבר לקצה.","גלגלו באיטיות את האצבעות לכיוון כפות הידיים, תוך לחיצה חזקה על המוט.","החזיקו את הכיווץ לרגע, ואז שחררו את האצבעות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your fingers towards your palms, squeezing the barbell tightly.","Hold the contraction for a moment, then slowly release your fingers back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, поставьте ступни на землю и возьмите штангу обратным хватом ладонями вверх.","Положите предплечья на бедра, позволяя запястьям свисать с края.","Медленно согните пальцы к ладоням, крепко сжимая штангу.","Удерживайте напряжение на мгновение, затем медленно отпустите пальцы и верните их в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Curva lentamente los dedos hacia las palmas, apretando la barra con fuerza.","Mantén la contracción por un momento, luego suelta lentamente los dedos hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3303","name":"flag","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","shoulders"],"target":"abs","image":"images/3303-pQ0Mx1Z.jpg","gif_url":"videos/3303-pQ0Mx1Z.gif","instruction_steps":{"he":["התחילו באחיזת מוט אנכי בשתי ידיים, כפות ידיים פונות זו לזו, וידיים ישרות לגמרי.","הפעילו את הליבה והרימו את הרגליים מהרצפה, כשהן ישרות.","בעזרת כוח הליבה ופלג הגוף העליון, הרימו את הרגליים עד שהן מקבילות לרצפה.","החזיקו את התנוחה כמה שיותר זמן, תוך שמירה על קו גוף ישר.","הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.","Engage your core and lift your legs off the ground, keeping them straight.","Using your core and upper body strength, raise your legs until they are parallel to the ground.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с захвата вертикального шеста обеими руками, ладони обращены друг к другу, руки полностью выпрямлены.","Напрягите корпус и поднимите ноги от земли, сохраняя их прямыми.","Используя силу корпуса и верхней части тела, поднимите ноги, пока они не станут параллельны земле.","Удерживайте это положение как можно дольше, сохраняя прямую линию тела.","Медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza sujetando un poste vertical con ambas manos, palmas una frente a la otra, y los brazos completamente extendidos.","Activa el core y levanta las piernas del suelo, manteniéndolas rectas.","Usando la fuerza del core y de la parte superior del cuerpo, levanta las piernas hasta que queden paralelas al suelo.","Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0456","name":"flexion leg sit up (bent knee)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0456-AR0ig3o.jpg","gif_url":"videos/0456-AR0ig3o.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","בו-זמנית, הרימו את הרגליים מהרצפה, בכיפוף ברכיים והבאתן לכיוון החזה.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון והרגליים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","В то же время отрывайте ноги от земли, сгибая колени и приближая их к груди.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела и ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Al mismo tiempo, levanta las piernas del suelo, doblando las rodillas y llevándolas hacia el pecho.","Haz una pausa breve en la parte superior, luego baja lentamente la parte superior del cuerpo y las piernas a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0457","name":"flexion leg sit up (straight arm)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","quadriceps"],"target":"abs","image":"images/0457-KZn52RC.jpg","gif_url":"videos/0457-KZn52RC.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וידיים מתוחות מעל הראש.","תוך הפעלת שרירי הבטן, הרימו את פלג הגוף העליון מהרצפה ובו-זמנית הרימו את הרגליים לכיוון החזה.","מתחו את הידיים לכיוון קצות האצבעות של הרגליים תוך הרמת פלג הגוף העליון והרגליים.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון והרגליים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs extended and arms straight above your head.","Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest.","Reach your hands towards your toes as you lift your upper body and legs.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, вытянув ноги и выпрямив руки над головой.","Включив пресс, поднимите верхнюю часть тела от земли, одновременно поднимая ноги к груди.","Протяните руки к пальцам ног, поднимая верхнюю часть тела и ноги.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела и ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba con las piernas extendidas y los brazos rectos por encima de la cabeza.","Activando el abdomen, levanta la parte superior del cuerpo del suelo mientras al mismo tiempo levantas las piernas hacia el pecho.","Extiende las manos hacia los dedos de los pies mientras levantas la parte superior del cuerpo y las piernas.","Haz una pausa breve en la parte superior, luego baja lentamente la parte superior del cuerpo y las piernas a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0458","name":"floor fly (with barbell)","category":"chest","body_part":"chest","equipment":"barbell","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0458-neonEDL.jpg","gif_url":"videos/0458-neonEDL.gif","instruction_steps":{"he":["שכבו על הגב על הרצפה עם ברכיים כפופות וכפות רגליים על הרצפה.","החזיקו מוט באחיזה עליונה, ידיים מתוחות ישר מעל החזה.","הורידו את המוט באיטיות לצדדים, עם כיפוף קל במרפקים.","הורידו את המוט עד שהידיים מקבילות לרצפה, עד תחושת מתיחה בחזה.","עצרו לרגע, ואז כווצו את שרירי החזה להחזרת המוט לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold a barbell with an overhand grip, arms extended straight up over your chest.","Slowly lower the barbell out to the sides, keeping a slight bend in your elbows.","Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину на пол, согните колени и поставьте ступни на землю.","Держите штангу хватом сверху, руки вытянуты прямо над грудью.","Медленно опустите штангу в стороны, сохраняя небольшой изгиб в локтях.","Опускайте штангу до тех пор, пока руки не станут параллельны полу, чувствуя растяжение в груди.","Сделайте паузу на мгновение, затем сожмите мышцы груди, чтобы вернуть штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.","Sostén una barra con agarre prono, brazos extendidos rectos por encima del pecho.","Baja lentamente la barra hacia los lados, manteniendo una ligera flexión en los codos.","Baja la barra hasta que los brazos queden paralelos al suelo, sintiendo un estiramiento en el pecho.","Haz una pausa breve, luego contrae los músculos del pecho para llevar la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0459","name":"flutter kicks","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower abs"],"target":"glutes","image":"images/0459-UVo2Qs2.jpg","gif_url":"videos/0459-UVo2Qs2.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וידיים לצידי הגוף.","הפעילו את הליבה והרימו את הרגליים כ-15 ס\"מ מהרצפה.","תוך שמירה על רגליים ישרות, הרימו לסירוגין רגל אחת מעט גבוה מהשנייה.","המשיכו בתנועת הרפרוף למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs extended and your hands by your sides.","Engage your core and lift your legs off the ground about 6 inches.","Keeping your legs straight, alternate lifting one leg slightly higher than the other.","Continue this fluttering motion for the desired number of repetitions."],"ru":["Лягте на спину, вытянув ноги и положив руки по бокам.","Напрягите корпус и поднимите ноги над землей примерно на 6 дюймов.","Удерживая ноги прямыми, поочередно поднимайте одну ногу немного выше другой.","Продолжайте это порхающее движение желаемое количество повторений."],"es":["Túmbate boca arriba con las piernas extendidas y las manos a los costados.","Activa el core y levanta las piernas del suelo unos 15 centímetros.","Manteniendo las piernas rectas, alterna levantando una pierna ligeramente más alto que la otra.","Continúa este movimiento de aleteo durante el número de repeticiones deseado."]}},{"id":"1472","name":"forward jump","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"calves","secondary_muscles":["calves","hamstrings","glutes"],"target":"quads","image":"images/1472-uZKq7lo.jpg","gif_url":"videos/1472-uZKq7lo.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","כופפו ברכיים והורידו את הגוף לעמדת סקוואט.","הניפו את הידיים לאחור לתנופה.","קפצו קדימה בפיצוץ, תוך יישור הירכיים, הברכיים והקרסוליים.","נחתו ברכות על כריות כפות הרגליים והמשיכו מיד לקפיצה הבאה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Swing your arms back for momentum.","Jump forward explosively, extending your hips, knees, and ankles.","Land softly on the balls of your feet and immediately go into the next jump.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Согните колени и опустите тело в присед.","Отведите руки назад для придания импульса.","Резко прыгните вперед, выпрямляя бедра, колени и лодыжки.","Мягко приземлитесь на подушечки стоп и сразу же переходите к следующему прыжку.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.","Balancea los brazos hacia atrás para generar impulso.","Salta hacia adelante de forma explosiva, extendiendo las caderas, las rodillas y los tobillos.","Aterriza suavemente sobre la punta de los pies y pasa de inmediato al siguiente salto.","Repite el número de repeticiones deseado."]}},{"id":"3470","name":"forward lunge (male)","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3470-kMzUs9Y.jpg","gif_url":"videos/3470-kMzUs9Y.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן וידיים על המותניים.","צעדו צעד גדול קדימה עם כף רגל ימין, בהורדת הגוף לעמדת מספריים.","כופפו את ברך ימין לזווית של כ-90 מעלות, תוך שמירה על הברך בקו אחד עם הקרסול.","דחפו עם כף רגל ימין וחזרו לנקודת ההתחלה.","חזרו על התנועה עם רגל שמאל, לסירוגין בין הצדדים למספר החזרות הרצוי."],"en":["Stand with your feet hip-width apart and hands on your hips.","Take a big step forward with your right foot, lowering your body into a lunge position.","Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.","Push off with your right foot and return to the starting position.","Repeat with your left leg, alternating sides for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, руки на бедрах.","Сделайте большой шаг вперед правой ногой, опуская тело в положение выпада.","Согните правое колено примерно на 90 градусов, удерживая колено на одном уровне с лодыжкой.","Оттолкнитесь правой ногой и вернитесь в исходное положение.","Повторите то же самое с левой ногой, чередуя стороны, необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas.","Da un paso grande hacia adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Dobla la rodilla derecha hasta unos 90 grados, manteniendo la rodilla alineada con el tobillo.","Empuja con el pie derecho y vuelve a la posición inicial.","Repite con la pierna izquierda, alternando los lados durante el número de repeticiones deseado."]}},{"id":"3194","name":"frankenstein squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3194-bdWcbaU.jpg","gif_url":"videos/3194-bdWcbaU.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את המוט מול הגוף עם ידיים ישרות.","תוך שמירה על גב ישר, הורידו את הגוף בכיפוף ברכיים וירכיים, כאילו אתם מתיישבים לאחור על כיסא.","המשיכו לרדת עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","עצרו לרגע, ואז דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms.","Keeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, и держите штангу перед собой прямыми руками.","Сохраняя спину прямой, опустите тело, сгибая колени и бедра, как будто садитесь на стул.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Сделайте паузу на мгновение, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra frente al cuerpo con los brazos rectos.","Manteniendo la espalda recta, baja el cuerpo flexionando las rodillas y las caderas, como si fueras a sentarte en una silla.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2429","name":"frog crunch","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/2429-FFRP97T.jpg","gif_url":"videos/2429-FFRP97T.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו את פלג הגוף העליון מהרצפה, בגלגול קדימה עד שהגו בזווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, поднимите верхнюю часть тела от земли, наклонившись вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3301","name":"frog planche","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","chest","triceps"],"target":"abs","image":"images/3301-rQhGcin.jpg","gif_url":"videos/3301-rQhGcin.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים ברוחב כתפיים ורגליים צמודות.","כופפו מרפקים והורידו את הגוף לכיוון הרצפה, תוך שמירה על גב ישר.","תוך כדי הורדת הגוף, הרימו את כפות הרגליים מהרצפה והביאו את הברכיים לכיוון החזה.","החזיקו את התנוחה כמה שניות, ואז מתחו את הרגליים חזרה ודחפו את עצמכם למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands shoulder-width apart and your feet together.","Bend your elbows and lower your body towards the ground, keeping your back straight.","As you lower your body, lift your feet off the ground and bring your knees towards your chest.","Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции для отжиманий, поставив руки на ширине плеч, а ноги вместе.","Согните руки в локтях и опустите тело к земле, сохраняя спину прямой.","Опуская тело, поднимите ноги от земли и подтяните колени к груди.","Удерживайте это положение несколько секунд, затем вытяните ноги и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los pies juntos.","Dobla los codos y baja el cuerpo hacia el suelo, manteniendo la espalda recta.","Mientras bajas el cuerpo, levanta los pies del suelo y lleva las rodillas hacia el pecho.","Mantén esta posición durante unos segundos, luego extiende las piernas de nuevo y empújate hacia arriba a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3296","name":"front lever","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"lats","secondary_muscles":["lats","shoulders","forearms"],"target":"abs","image":"images/3296-PkCN2lv.jpg","gif_url":"videos/3296-PkCN2lv.gif","instruction_steps":{"he":["התחילו בתלייה על מוט מתח באחיזה עליונה, ידיים ברוחב כתפיים.","הפעילו את הליבה ומשכו את השכמות מטה ולאחור.","כופפו ברכיים ואספו אותן לכיוון החזה.","בו-זמנית, הרימו את הרגליים ומתחו אותן ישר לפניכם, תוך שמירה על הגוף מקביל לרצפה.","החזיקו את התנוחה כמה שיותר זמן, בשאיפה לפרונט-ליבר מלא.","לשחרור, הורידו את הרגליים באיטיות וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.","Hold this position for as long as you can, aiming for a full front lever position.","To release, slowly lower your legs back down and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с подвешивания на перекладине хватом сверху, руки на ширине плеч.","Напрягите корпус и потяните лопатки вниз и назад.","Согните колени и подтяните их к груди.","Одновременно поднимите ноги вверх и вытяните их прямо перед собой, сохраняя тело параллельно земле.","Удерживайте это положение как можно дольше, стремясь к полному положению переднего рычага.","Чтобы расслабиться, медленно опустите ноги вниз и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza colgado de una barra de dominadas con agarre prono, manos separadas a la altura de los hombros.","Activa el core y lleva los omóplatos hacia abajo y atrás.","Flexiona las rodillas y llévalas hacia el pecho.","Al mismo tiempo, levanta las piernas y extiéndelas rectas frente a ti, manteniendo el cuerpo paralelo al suelo.","Mantén esta posición todo el tiempo que puedas, intentando lograr una posición completa de palanca frontal.","Para soltar, baja lentamente las piernas y regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3295","name":"front lever reps","category":"back","body_part":"back","equipment":"body weight","muscle_group":"core","secondary_muscles":["core","shoulders"],"target":"upper back","image":"images/3295-hbY9wqG.jpg","gif_url":"videos/3295-hbY9wqG.gif","instruction_steps":{"he":["היתלו על מוט מתח באחיזה עליונה, כפות ידיים פונות מכם.","הפעילו את הליבה ומשכו את השכמות מטה ולאחור.","תוך שמירה על גוף ישר, הרימו את הרגליים עד שהן מקבילות לרצפה.","החזיקו את התנוחה כמה שיותר זמן, עם יעד של 10–20 שניות.","הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with an overhand grip, palms facing away from you.","Engage your core and pull your shoulder blades down and back.","Keeping your body straight, lift your legs up until they are parallel to the ground.","Hold this position for as long as you can, aiming for 10-20 seconds.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине хватом сверху, ладонями от себя.","Напрягите корпус и потяните лопатки вниз и назад.","Сохраняя тело прямым, поднимите ноги вверх, пока они не станут параллельны земле.","Удерживайте это положение как можно дольше, стараясь удержаться в течение 10–20 секунд.","Медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con agarre prono, palmas hacia afuera.","Activa el core y lleva los omóplatos hacia abajo y atrás.","Manteniendo el cuerpo recto, levanta las piernas hasta que queden paralelas al suelo.","Mantén esta posición todo el tiempo que puedas, intentando llegar a 10-20 segundos.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0464","name":"front plank with twist","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","shoulders"],"target":"abs","image":"images/0464-CosupLu.jpg","gif_url":"videos/0464-CosupLu.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים ישר מתחת לכתפיים והגוף בקו ישר מהראש ועד כפות הרגליים.","הפעילו את הליבה והישבן לשמירה על תנוחה יציבה.","סובבו את הגו ימינה, בהרמת יד ימין ומתיחתה לכיוון התקרה.","שמרו על אגן ורגליים יציבים תוך כדי הסיבוב.","החזיקו לרגע, ואז חזרו לנקודת ההתחלה.","חזרו על הסיבוב לצד שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and glutes to maintain a stable position.","Rotate your torso to the right, lifting your right arm and extending it towards the ceiling.","Keep your hips and legs stable as you twist.","Hold for a moment, then return to the starting position.","Repeat the twist on the left side.","Continue alternating sides for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, положив руки прямо под плечи, а тело образуя прямую линию от головы до пят.","Задействуйте корпус и ягодицы, чтобы сохранить устойчивое положение.","Поверните туловище вправо, подняв правую руку и вытянув ее к потолку.","Во время поворотов сохраняйте устойчивость бедер и ног.","Задержитесь на мгновение, затем вернитесь в исходное положение.","Повторите поворот с левой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies.","Activa el core y los glúteos para mantener una posición estable.","Gira el torso hacia la derecha, levantando el brazo derecho y extendiéndolo hacia el techo.","Mantén las caderas y las piernas estables mientras giras.","Mantén la posición por un momento, luego regresa a la posición inicial.","Repite el giro hacia el lado izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"3315","name":"full maltese","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"abs","image":"images/3315-YRaCa5Y.jpg","gif_url":"videos/3315-YRaCa5Y.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים וידיים מתוחות ישר לצדדים.","רכנו באיטיות קדימה, תוך שמירה על ידיים ישרות, עד שפלג הגוף העליון מקביל לרצפה.","הפעילו את הליבה והחזיקו את התנוחה כמה שניות.","חזרו לנקודת ההתחלה בדחיפה דרך כפות הרגליים ועמידה חזרה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.","Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.","Engage your core and hold this position for a few seconds.","Return to the starting position by pushing through your feet and standing back up.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и вытянув руки в стороны.","Медленно наклонитесь вперед, держа руки прямыми, пока верхняя часть тела не станет параллельна земле.","Напрягите корпус и удерживайте это положение в течение нескольких секунд.","Вернитесь в исходное положение, оттолкнувшись ногами и снова встав.","Повторите необходимое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos rectos hacia los lados.","Inclínate lentamente hacia adelante, manteniendo los brazos rectos, hasta que la parte superior del cuerpo quede paralela al suelo.","Activa el core y mantén esta posición durante unos segundos.","Regresa a la posición inicial empujando con los pies y volviendo a ponerte de pie.","Repite el número de repeticiones deseado."]}},{"id":"3299","name":"full planche","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","chest","triceps"],"target":"abs","image":"images/3299-YZ4961r.jpg","gif_url":"videos/3299-YZ4961r.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים ברוחב כתפיים ואצבעות פונות קדימה.","הפעילו את הליבה והעבירו באיטיות את המשקל קדימה, בהרמת כפות הרגליים מהרצפה.","המשיכו להעביר את המשקל קדימה עד שהגוף מקביל לרצפה, באיזון על הידיים.","החזיקו את התנוחה כמה שיותר זמן, תוך שמירה על קו גוף ישר.","הורידו את כפות הרגליים באיטיות חזרה לרצפה וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.","Engage your core and slowly shift your weight forward, lifting your feet off the ground.","Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your feet back to the ground and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции для отжиманий, поставив руки на ширине плеч и пальцы направлены вперед.","Напрягите корпус и медленно перенесите вес вперед, отрывая ноги от земли.","Продолжайте переносить вес вперед, пока ваше тело не станет параллельно земле, балансируя на руках.","Удерживайте это положение как можно дольше, сохраняя прямую линию тела.","Медленно опустите ноги обратно на землю и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los dedos apuntando hacia adelante.","Activa el core y desplaza lentamente el peso hacia adelante, levantando los pies del suelo.","Continúa desplazando el peso hacia adelante hasta que el cuerpo quede paralelo al suelo, equilibrándote sobre las manos.","Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta.","Baja lentamente los pies de nuevo al suelo y regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3327","name":"full planche push-up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","core"],"target":"pectorals","image":"images/3327-gw9PqGk.jpg","gif_url":"videos/3327-gw9PqGk.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים מעט רחבות מרוחב הכתפיים.","הפעילו את הליבה והורידו את הגוף לכיוון הרצפה, תוך שמירה על מרפקים צמודים לצידי הגוף.","תוך כדי הירידה, הטו את הגוף קדימה והרימו את כפות הרגליים מהרצפה, באיזון על הידיים.","המשיכו להוריד את הגוף עד שהחזה מעט מעל הרצפה.","דחפו דרך הידיים ויישרו אותן להרמת הגוף חזרה לנקודת ההתחלה.","שמרו על קו ישר מהראש ועד העקבים לאורך כל התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands placed slightly wider than shoulder-width apart.","Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.","As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.","Continue to lower your body until your chest is just above the ground.","Push through your hands and extend your arms to lift your body back up to the starting position.","Maintain a straight line from your head to your heels throughout the movement.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции отжимания, поставив руки чуть шире плеч.","Напрягите корпус и опустите тело вниз к земле, держа локти близко к бокам.","Опускаясь, наклоните тело вперед и оторвите ноги от земли, балансируя на руках.","Продолжайте опускать тело до тех пор, пока грудь не окажется чуть выше земли.","Оттолкнитесь руками и вытяните руки, чтобы поднять тело обратно в исходное положение.","На протяжении всего движения сохраняйте прямую линию от головы до пят.","Повторите необходимое количество повторений."],"es":["Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros.","Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.","Mientras te bajas, inclina el cuerpo hacia adelante y levanta los pies del suelo, equilibrándote sobre las manos.","Continúa bajando el cuerpo hasta que el pecho quede justo por encima del suelo.","Empuja con las manos y extiende los brazos para volver a subir el cuerpo a la posición inicial.","Mantén una línea recta desde la cabeza hasta los talones durante todo el movimiento.","Repite el número de repeticiones deseado."]}},{"id":"0466","name":"gironda sternum chin","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0466-IL0JUxR.jpg","gif_url":"videos/0466-IL0JUxR.gif","instruction_steps":{"he":["עמדו מול מוט גבוה עם רגליים ברוחב כתפיים.","הושיטו ידיים למעלה ואחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היתלו על המוט עם ידיים ישרות לגמרי וגוף ישר.","הפעילו את רחב הגבי והבייספס למשיכת החזה למעלה לכיוון המוט, כשעצם החזה מובילה את התנועה.","עצרו לרגע בנקודה העליונה, ואז הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing a high bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к высокой перекладине, ноги на ширине плеч.","Потянитесь вверх и возьмите перекладину хватом сверху, на расстоянии чуть шире ширины плеч.","Повисните на перекладине, полностью вытянув руки и выпрямив тело.","Задействуйте широчайшие и бицепсы, чтобы подтянуть грудь к перекладине, ведущей вперед грудиной.","Задержитесь на мгновение в верхней точке, затем медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a una barra alta con los pies separados a la altura de los hombros.","Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.","Activa los dorsales y los bíceps para llevar el pecho hacia la barra, guiando con el esternón.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3561","name":"glute bridge march","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/3561-GibBPPg.jpg","gif_url":"videos/3561-GibBPPg.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הפעילו את הישבן והרימו את האגן מהרצפה, ביצירת קו ישר מהברכיים ועד הכתפיים.","תוך שמירה על אגן מורם, הרימו כף רגל אחת מהרצפה והביאו את הברך לכיוון החזה.","הורידו את כף הרגל חזרה לרצפה וחזרו על התנועה עם הרגל השנייה.","המשיכו להחליף רגליים בתנועת צעידה תוך שמירה על תנוחת הגשר.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.","Lower your foot back to the ground and repeat the movement with the other leg.","Continue alternating legs in a marching motion while maintaining the bridge position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Напрягите ягодицы и поднимите бедра от земли, образуя прямую линию от колен до плеч.","Удерживая бедра приподнятыми, оторвите одну ногу от земли и поднесите колено к груди.","Опустите ногу обратно на землю и повторите движение другой ногой.","Продолжайте чередовать ноги марширующим движением, сохраняя положение мостика.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.","Manteniendo las caderas elevadas, levanta un pie del suelo y lleva la rodilla hacia el pecho.","Baja el pie de nuevo al suelo y repite el movimiento con la otra pierna.","Continúa alternando las piernas con un movimiento de marcha mientras mantienes la posición de puente.","Repite el número de repeticiones deseado."]}},{"id":"3523","name":"glute bridge two legs on bench (male)","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","core"],"target":"glutes","image":"images/3523-aWedzZX.jpg","gif_url":"videos/3523-aWedzZX.gif","instruction_steps":{"he":["שבו על קצה ספסל כשהגב נשען עליו וכפות הרגליים על הרצפה.","הניחו את הידיים על הספסל לצידי האגן לתמיכה.","הפעילו את הישבן והירך האחורית, והרימו את האגן מהספסל עד שהגוף יוצר קו ישר מהברכיים ועד הכתפיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the edge of a bench with your back against it and your feet flat on the ground.","Place your hands on the bench beside your hips for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на край скамьи, прислонившись к ней спиной и поставив ноги на землю.","Положите руки на скамью рядом с бедрами для поддержки.","Задействуйте ягодицы и мышцы задней поверхности бедра, затем поднимите бедра со скамьи, пока ваше тело не образует прямую линию от колен до плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el borde de un banco con la espalda apoyada en él y los pies planos sobre el suelo.","Coloca las manos en el banco junto a las caderas para mayor apoyo.","Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3193","name":"glute-ham raise","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","lower back"],"target":"hamstrings","image":"images/3193-Vvwjz6N.jpg","gif_url":"videos/3193-Vvwjz6N.gif","instruction_steps":{"he":["כווננו את מכונת הגלוט-האם לגוף שלכם.","התמקמו על הבטן על המכשיר כשהקרסוליים מקובעים.","הניחו את הידיים על החזה או הצליבו אותן עליו.","הפעילו את הירך האחורית והישבן להרמת פלג הגוף העליון לכיוון התקרה.","המשיכו להרים עד שהגוף בקו ישר מהראש ועד העקבים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the glute-ham raise machine to fit your body.","Position yourself face down on the machine with your ankles secured.","Place your hands on your chest or cross them over your chest.","Engage your hamstrings and glutes to lift your upper body up towards the ceiling.","Continue lifting until your body is in a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте тренажер для подъема ягодичных мышц так, чтобы он соответствовал вашему телу.","Расположитесь на тренажере лицом вниз, зафиксировав лодыжки.","Положите руки на грудь или скрестите их на груди.","Задействуйте мышцы задней поверхности бедра и ягодицы, чтобы поднять верхнюю часть тела к потолку.","Продолжайте поднимать, пока ваше тело не станет прямой линией от головы до пяток.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de extensión de glúteos e isquiotibiales para que se adapte a tu cuerpo.","Colócate boca abajo en la máquina con los tobillos asegurados.","Coloca las manos sobre el pecho o crúzalas sobre el pecho.","Activa los isquiotibiales y los glúteos para levantar la parte superior del cuerpo hacia el techo.","Continúa levantando hasta que el cuerpo forme una línea recta desde la cabeza hasta los talones.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0467","name":"gorilla chin","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"forearms","secondary_muscles":["forearms","biceps"],"target":"abs","image":"images/0467-bmwlYvD.jpg","gif_url":"videos/0467-bmwlYvD.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","אחזו במוט מתח באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היתלו על המוט עם ידיים ישרות לגמרי וכפות ידיים פונות מכם.","הפעילו את הליבה ומשכו את הגוף למעלה לכיוון המוט, בהבאת הסנטר מעל המוט.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your palms facing away from you.","Engage your core and pull your body up towards the bar, bringing your chin above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Возьмитесь за перекладину хватом сверху, на расстоянии чуть шире ширины плеч.","Повисните на перекладине, полностью вытянув руки и повернув ладони от себя.","Напрягите корпус и подтяните тело к перекладине, поднимая подбородок над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una barra de dominadas con agarre prono, ligeramente más ancho que la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y las palmas hacia afuera.","Activa el core y tira del cuerpo hacia la barra, llevando la barbilla por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0469","name":"groin crunch","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","inner thighs"],"target":"abs","image":"images/0469-mWppALS.jpg","gif_url":"videos/0469-mWppALS.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו את הרגליים מהרצפה והביאו את הברכיים לכיוון החזה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, поднимите ноги от земли, подтянув колени к груди.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1383","name":"hack calf raise","category":"lower legs","body_part":"lower legs","equipment":"sled machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1383-2ORFMoR.jpg","gif_url":"videos/1383-2ORFMoR.gif","instruction_steps":{"he":["כווננו את מכונת המזחלת למשקל נוח.","עמדו על מכונת המזחלת כשקצות האצבעות של הרגליים על המשטח והעקבים משתלשלים.","אחזו בידיות לייצוב.","הרימו את העקבים גבוה ככל האפשר בדחיפה דרך כריות כפות הרגליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the sled machine to a comfortable weight.","Stand on the sled machine with your toes on the platform and your heels hanging off.","Hold onto the handles for stability.","Raise your heels as high as possible by pushing through the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сани до удобного веса.","Встаньте на санки, положив пальцы ног на платформу и свесив пятки.","Держитесь за ручки для устойчивости.","Поднимите пятки как можно выше, толкая подушечки стоп.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de trineo a un peso adecuado.","Ponte de pie sobre la máquina de trineo con la punta de los pies en la plataforma y los talones colgando.","Sujétate de las asas para mantener el equilibrio.","Levanta los talones lo más alto posible empujando con la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1384","name":"hack one leg calf raise","category":"lower legs","body_part":"lower legs","equipment":"sled machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1384-AxFoqAD.jpg","gif_url":"videos/1384-AxFoqAD.gif","instruction_steps":{"he":["כווננו את מכונת המזחלת למשקל מתאים.","עמדו על מכונת המזחלת עם רגל אחת, כשהרגל השנייה באוויר.","אחזו בידיות לייצוב.","הרימו את העקב גבוה ככל האפשר, בהרמת הגוף על כרית כף הרגל.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקב באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי.","החליפו רגליים וחזרו על התרגיל."],"en":["Adjust the sled machine to an appropriate weight.","Stand on the sled machine with one foot, keeping the other foot off the ground.","Hold onto the handles for stability.","Raise your heel as high as possible, lifting your body up on the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions.","Switch legs and repeat the exercise."],"ru":["Отрегулируйте салазки до подходящего веса.","Встаньте на салазки одной ногой, не отрывая другую от земли.","Держитесь за ручки для устойчивости.","Поднимите пятку как можно выше, поднимая тело на подушечку стопы.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятку обратно в исходное положение.","Повторите необходимое количество повторений.","Поменяйте ноги и повторите упражнение."],"es":["Ajusta la máquina de trineo a un peso adecuado.","Ponte de pie sobre la máquina de trineo con un pie, manteniendo el otro pie levantado del suelo.","Sujétate de las asas para mantener el equilibrio.","Levanta el talón lo más alto posible, elevando el cuerpo sobre la punta del pie.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de pierna y repite el ejercicio."]}},{"id":"3221","name":"half knee bends (male)","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes"],"target":"cardiovascular system","image":"images/3221-ia6kIIl.jpg","gif_url":"videos/3221-ia6kIIl.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","כופפו ברכיים והורידו את הגוף כאילו אתם מתיישבים לאחור על כיסא.","שמרו על חזה מורם ועל המשקל בעקבים.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body down as if you were sitting back into a chair.","Keep your chest up and your weight in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Согните колени и опустите тело вниз, как будто вы сидите на стуле.","Держите грудь поднятой, а вес тела переносите на пятки.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Dobla las rodillas y baja el cuerpo como si te fueras a sentar en una silla.","Mantén el pecho elevado y el peso en los talones.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3202","name":"half sit-up (male)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3202-iQ241UP.jpg","gif_url":"videos/3202-iQ241UP.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1511","name":"hamstring stretch","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes"],"target":"hamstrings","image":"images/1511-99rWm7w.jpg","gif_url":"videos/1511-99rWm7w.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","צעדו קדימה עם רגל ימין והעבירו את המשקל לרגל ימין.","תוך שמירה על גב ישר, הטו באיטיות את הגו קדימה מהירכיים, במתיחת שתי הידיים לכיוון כף רגל ימין.","החזיקו את המתיחה 20–30 שניות, ואז חזרו לנקודת ההתחלה.","חזרו על התנועה בצד השני."],"en":["Stand with your feet shoulder-width apart.","Step forward with your right foot and shift your weight onto your right leg.","Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."],"ru":["Встаньте, ноги на ширине плеч.","Сделайте шаг вперед правой ногой и перенесите вес тела на правую ногу.","Сохраняя спину прямой, медленно наклонитесь вперед в бедрах, потянув обе руки к правой ступне.","Удерживайте растяжку 20–30 секунд, затем вернитесь в исходное положение.","Повторите с другой стороны."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con el pie derecho y traslada el peso hacia la pierna derecha.","Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas, alcanzando el pie derecho con ambas manos.","Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.","Repite del otro lado."]}},{"id":"2139","name":"hands bike","category":"chest","body_part":"chest","equipment":"upper body ergometer","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/2139-pAIWRGu.jpg","gif_url":"videos/2139-pAIWRGu.gif","instruction_steps":{"he":["כווננו את גובה המושב ומיקום הכידון לרמה נוחה.","שבו על הארגומטר עם גב ישר וכפות רגליים על הדוושות.","אחזו בידיות ומקמו את הידיים בזווית של 90 מעלות.","התחילו לדווש עם הידיים, בדחיפה ומשיכה של הידיות בתנועה מבוקרת.","המשיכו לדווש למשך הזמן או מספר החזרות הרצוי."],"en":["Adjust the seat height and handlebar position to a comfortable level.","Sit on the ergometer with your back straight and feet on the pedals.","Grasp the handles with your hands and position your arms at a 90-degree angle.","Start pedaling with your hands, pushing and pulling the handles in a controlled motion.","Continue pedaling for the desired duration or number of repetitions."],"ru":["Отрегулируйте высоту сиденья и положение руля до удобного уровня.","Сядьте на эргометр, спина прямая, ноги на педалях.","Возьмитесь за ручки руками и расположите руки под углом 90 градусов.","Начните крутить педали руками, толкая и тянув ручки контролируемым движением.","Продолжайте крутить педали желаемую продолжительность или количество повторений."],"es":["Ajusta la altura del asiento y la posición del manillar a un nivel cómodo.","Siéntate en el ergómetro con la espalda recta y los pies sobre los pedales.","Sujeta las asas con las manos y coloca los brazos en un ángulo de 90 grados.","Comienza a pedalear con las manos, empujando y tirando de las asas con un movimiento controlado.","Continúa pedaleando durante el tiempo o el número de repeticiones deseado."]}},{"id":"3218","name":"hands clasped circular toe touch (male)","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","calves"],"target":"glutes","image":"images/3218-B5xca8s.jpg","gif_url":"videos/3218-B5xca8s.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וידיים שלובות יחד מול החזה.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","הורידו את הידיים לכיוון קצות האצבעות בתנועה מעגלית, והגיעו רחוק ככל האפשר בלי להתאמץ יתר על המידה.","עצרו לרגע בנקודה התחתונה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your hands towards your toes in a circular motion, reaching as far as you can without straining.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, руки сомкнуты перед грудью.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Опустите руки к пальцам ног круговыми движениями, дотягиваясь как можно дальше, не напрягаясь.","Задержитесь на мгновение в нижней точке, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las manos entrelazadas frente al pecho.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Baja las manos hacia los dedos de los pies con un movimiento circular, llegando tan lejos como puedas sin forzar.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3215","name":"hands reversed clasped circular toe touch (male)","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","calves"],"target":"glutes","image":"images/3215-yq3GAJX.jpg","gif_url":"videos/3215-yq3GAJX.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וידיים מתוחות לצדדים.","הטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר וברכיים כפופות מעט.","הושיטו את הידיים מטה ושלבו אותן יחד מאחורי הרגליים.","הרימו באיטיות את הידיים למעלה ומעל הראש בתנועה מעגלית, תוך שמירה על רגליים ישרות.","המשיכו בתנועה המעגלית עד שהידיים נוגעות בקצות האצבעות של הרגליים.","הפכו את התנועה והחזירו את הידיים מטה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down with your hands and clasp them together behind your legs.","Slowly raise your hands up and over your head in a circular motion, keeping your legs straight.","Continue the circular motion until your hands touch your toes.","Reverse the motion and bring your hands back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, руки вытянуты в стороны.","Наклонитесь вперед в талии, сохраняя спину прямой и слегка согнутыми в коленях.","Потяните руки вниз и соедините их за ногами.","Медленно поднимите руки вверх и над головой круговыми движениями, держа ноги прямыми.","Продолжайте круговые движения, пока руки не коснутся пальцев ног.","Сделайте обратное движение и верните руки в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Extiende las manos hacia abajo y entrelázalas detrás de las piernas.","Sube lentamente las manos en un movimiento circular por encima de la cabeza, manteniendo las piernas rectas.","Continúa el movimiento circular hasta que las manos toquen los dedos de los pies.","Invierte el movimiento y regresa las manos a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3302","name":"handstand","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"triceps","image":"images/3302-XooAdhl.jpg","gif_url":"videos/3302-XooAdhl.gif","instruction_steps":{"he":["מצאו מקום פתוח עם מספיק מרחב לעמידת ידיים.","הניחו את הידיים על הרצפה ברוחב כתפיים, אצבעות פונות קדימה.","בעטו את הרגליים למעלה לכיוון הקיר, בעזרת הליבה והכתפיים לשמירה על שיווי משקל.","בעמידת ידיים, הפעילו את הטרייספס לתמיכה במשקל הגוף.","החזיקו את עמידת הידיים כמה שאתם מצליחים לשמור על שיווי משקל.","לירידה, הורידו את הרגליים באיטיות חזרה לרצפה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Find an open space with enough room to perform a handstand.","Place your hands on the ground shoulder-width apart, fingers pointing forward.","Kick your legs up towards the wall, using your core and shoulders to maintain balance.","Once in a handstand position, engage your triceps to support your body weight.","Hold the handstand for as long as you can maintain balance.","To come down, slowly lower your legs back to the ground.","Repeat for the desired number of repetitions."],"ru":["Найдите открытое пространство, в котором достаточно места для стойки на руках.","Положите руки на пол на ширине плеч, пальцы направлены вперед.","Поднимите ноги к стене, используя корпус и плечи для поддержания равновесия.","В стойке на руках задействуйте трицепсы, чтобы поддерживать вес тела.","Удерживайте стойку на руках столько, сколько сможете сохранить равновесие.","Чтобы опуститься, медленно опустите ноги обратно на землю.","Повторите необходимое количество повторений."],"es":["Busca un espacio abierto con suficiente espacio para hacer un pino.","Coloca las manos en el suelo separadas a la altura de los hombros, con los dedos apuntando hacia adelante.","Lanza las piernas hacia la pared, usando el core y los hombros para mantener el equilibrio.","Una vez en posición de pino, activa los tríceps para sostener el peso corporal.","Mantén el pino el mayor tiempo posible mientras conserves el equilibrio.","Para bajar, lleva lentamente las piernas de vuelta al suelo.","Repite el número de repeticiones deseado."]}},{"id":"0471","name":"handstand push-up","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","chest","core"],"target":"triceps","image":"images/0471-rQxwMxO.jpg","gif_url":"videos/0471-rQxwMxO.gif","instruction_steps":{"he":["מצאו קיר ועמדו עם הגב אליו, במרחק כמה צעדים.","הניחו את הידיים על הרצפה ברוחב כתפיים ובעטו את הרגליים למעלה כנגד הקיר, לעמידת ידיים.","כופפו מרפקים והורידו את הראש לכיוון הרצפה, תוך שמירה על גוף בקו ישר.","דחפו דרך הידיים ויישרו אותן לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Find a wall and face away from it, standing a few feet away.","Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position.","Bend your elbows and lower your head towards the ground, keeping your body in a straight line.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Найдите стену и отвернитесь от нее, стоя на расстоянии нескольких футов.","Поставьте руки на пол на ширине плеч и поднимите ноги к стене, приняв положение стойки на руках.","Согните локти и опустите голову к земле, сохраняя тело прямой.","Оттолкнитесь руками и вытяните руки, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Busca una pared y colócate de espaldas a ella, de pie a unos pasos de distancia.","Coloca las manos en el suelo separadas a la altura de los hombros y lanza los pies hacia la pared, llegando a una posición de pino.","Dobla los codos y baja la cabeza hacia el suelo, manteniendo el cuerpo en línea recta.","Empuja con las manos y extiende los brazos para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1764","name":"hanging leg hip raise","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/1764-VEcJRo2.jpg","gif_url":"videos/1764-VEcJRo2.gif","instruction_steps":{"he":["היתלו על מוט מתח עם ידיים ישרות לגמרי וכפות ידיים פונות מכם.","הפעילו את שרירי הליבה והרימו את הרגליים בכיפוף ירכיים וברכיים עד שהירכיים מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, полностью вытянув руки и повернув ладони от себя.","Напрягите корпус и поднимите ноги вверх, сгибая бедра и колени, пока бедра не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las piernas flexionando las caderas y las rodillas hasta que los muslos queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0472","name":"hanging leg raise","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0472-I3tsCnC.jpg","gif_url":"videos/0472-I3tsCnC.gif","instruction_steps":{"he":["היתלו על מוט מתח עם ידיים ישרות לגמרי וכפות ידיים פונות מכם.","הפעילו את שרירי הליבה והרימו את הרגליים לפניכם, כשהן ישרות.","המשיכו להרים עד שהרגליים מקבילות לרצפה או עד כמה שנוח לכם.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, полностью вытянув руки и повернув ладони от себя.","Напрягите корпус и поднимите ноги перед собой, сохраняя их прямыми.","Продолжайте поднимать до тех пор, пока ваши ноги не станут параллельны земле или не станут настолько высоко, насколько вы сможете комфортно подняться.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.","Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1761","name":"hanging oblique knee raise","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/1761-BaE7O6U.jpg","gif_url":"videos/1761-BaE7O6U.gif","instruction_steps":{"he":["היתלו על מוט מתח עם ידיים ישרות לגמרי וכפות ידיים פונות מכם.","הפעילו את הליבה והרימו את הברכיים לכיוון החזה, תוך סיבוב הגו הצידה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה בצד השני, בסיבוב הגו לכיוון הנגדי.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat on the other side, twisting your torso in the opposite direction.","Continue alternating sides for the desired number of repetitions."],"ru":["Повисните на перекладине, полностью вытянув руки и повернув ладони от себя.","Напрягите корпус и поднимите колени к груди, поворачивая при этом туловище в сторону.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите то же самое с другой стороны, поворачивая туловище в противоположном направлении.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las rodillas hacia el pecho, girando el torso hacia un lado mientras lo haces.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite hacia el otro lado, girando el torso en la dirección opuesta.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0473","name":"hanging pike","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","shoulders"],"target":"abs","image":"images/0473-nuBF9MO.jpg","gif_url":"videos/0473-nuBF9MO.gif","instruction_steps":{"he":["היתלו על מוט מתח עם ידיים ישרות לגמרי וכפות ידיים פונות מכם.","הפעילו את הליבה והרימו את הרגליים למעלה לכיוון המוט, כשהן ישרות.","המשיכו להרים עד שהגוף יוצר צורת V, כשהרגליים מקבילות לרצפה.","החזיקו את התנוחה לרגע, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up towards the bar, keeping them straight.","Continue lifting until your body forms a 'V' shape, with your legs parallel to the ground.","Hold the position for a moment, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, полностью вытянув руки и повернув ладони от себя.","Напрягите корпус и поднимите ноги к перекладине, сохраняя их прямыми.","Продолжайте поднимать, пока ваше тело не примет V-образную форму, а ноги параллельны земле.","Задержитесь на мгновение в этом положении, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las piernas hacia la barra, manteniéndolas rectas.","Continúa levantando hasta que el cuerpo forme una 'V', con las piernas paralelas al suelo.","Mantén la posición por un momento, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0474","name":"hanging straight leg hip raise","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0474-pj0X0tF.jpg","gif_url":"videos/0474-pj0X0tF.gif","instruction_steps":{"he":["היתלו על מוט מתח עם ידיים ישרות לגמרי וכפות ידיים פונות מכם.","הפעילו את שרירי הליבה והרימו את הרגליים לפניכם עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, полностью вытянув руки и повернув ладони от себя.","Напрягите корпус и поднимите ноги перед собой, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0475","name":"hanging straight leg raise","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0475-4Ml7QFO.jpg","gif_url":"videos/0475-4Ml7QFO.gif","instruction_steps":{"he":["היתלו על מוט מתח עם ידיים ישרות לגמרי וכפות ידיים פונות מכם.","הפעילו את שרירי הליבה והרימו את הרגליים לפניכם, כשהן ישרות.","המשיכו להרים עד שהרגליים מקבילות לרצפה או עד כמה שנוח לכם.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, полностью вытянув руки и повернув ладони от себя.","Напрягите корпус и поднимите ноги перед собой, сохраняя их прямыми.","Продолжайте поднимать до тех пор, пока ваши ноги не станут параллельны земле или не станут настолько высоко, насколько вы сможете комфортно подняться.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.","Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0476","name":"hanging straight twisting leg hip raise","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/0476-Q6bvyen.jpg","gif_url":"videos/0476-Q6bvyen.gif","instruction_steps":{"he":["היתלו על מוט מתח עם ידיים ישרות לגמרי ורגליים ישרות.","הפעילו את הליבה והרימו את הרגליים לכיוון החזה, כשהן ישרות.","כשהרגליים מקבילות לרצפה, סובבו את האגן לצד אחד, בהבאת הרגליים לכיוון אותו צד.","עצרו לרגע, ואז חזרו לנקודת ההתחלה.","חזרו על התנועה, אך הפעם סובבו את האגן לצד הנגדי.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your arms fully extended and your legs straight.","Engage your core and lift your legs up towards your chest, keeping them straight.","Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.","Pause for a moment, then return to the starting position.","Repeat the movement, but this time twist your hips to the opposite side.","Continue alternating sides for the desired number of repetitions."],"ru":["Повисните на перекладине, полностью вытянув руки и выпрямив ноги.","Напрягите корпус и поднимите ноги к груди, сохраняя их прямыми.","Как только ваши ноги станут параллельны земле, поверните бедра в одну сторону, перемещая ноги в эту сторону.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите движение, но на этот раз поверните бедра в противоположную сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas rectas.","Activa el core y levanta las piernas hacia el pecho, manteniéndolas rectas.","Cuando las piernas queden paralelas al suelo, gira las caderas hacia un lado, llevando las piernas hacia ese lado.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite el movimiento, pero esta vez gira las caderas hacia el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"3636","name":"high knee against wall","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/3636-ealLwvX.jpg","gif_url":"videos/3636-ealLwvX.gif","instruction_steps":{"he":["עמדו מול קיר עם רגליים ברוחב אגן.","הניחו את הידיים על הקיר לתמיכה.","הפעילו את הליבה והרימו את ברך ימין לכיוון החזה, תוך שמירה על כף רגל שמאל על הרצפה.","החליפו רגליים במהירות — הביאו את ברך שמאל לכיוון החזה והורידו את כף רגל ימין חזרה.","המשיכו להחליף רגליים בתנועת ריצה, בהרמת הברכיים גבוה ככל האפשר.","שמרו על קצב מהיר ופלג גוף עליון יציב לאורך כל התרגיל.","המשיכו למשך הזמן או מספר החזרות הרצוי."],"en":["Stand facing a wall with your feet hip-width apart.","Place your hands on the wall for support.","Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.","Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down.","Continue alternating legs in a running motion, bringing your knees up as high as possible.","Maintain a fast pace and keep your upper body stable throughout the exercise.","Repeat for the desired duration or number of repetitions."],"ru":["Встаньте лицом к стене, поставив ноги на ширине плеч.","Положите руки на стену для поддержки.","Напрягите корпус и поднимите правое колено к груди, удерживая левую ногу на земле.","Быстро поменяйте ноги, поднеся левое колено к груди и опустив правую ногу обратно вниз.","Продолжайте чередовать ноги бегущим движением, поднимая колени как можно выше.","Поддерживайте быстрый темп и сохраняйте устойчивость верхней части тела на протяжении всего упражнения.","Повторяйте желаемую продолжительность или количество повторений."],"es":["Ponte de pie frente a una pared con los pies separados a la altura de las caderas.","Coloca las manos en la pared para mayor apoyo.","Activa el core y levanta la rodilla derecha hacia el pecho, mientras mantienes el pie izquierdo en el suelo.","Cambia rápidamente de pierna, llevando la rodilla izquierda hacia el pecho y bajando el pie derecho de nuevo.","Continúa alternando las piernas con un movimiento de carrera, llevando las rodillas lo más alto posible.","Mantén un ritmo rápido y la parte superior del cuerpo estable durante todo el ejercicio.","Repite durante la duración o el número de repeticiones deseado."]}},{"id":"0484","name":"hip raise (bent knee)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"abs","image":"images/0484-196HJGw.jpg","gif_url":"videos/0484-196HJGw.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים לצידי הגוף, כפות ידיים כלפי מטה.","הפעילו את הליבה והישבן, והרימו את האגן מהרצפה עד שהגוף יוצר קו ישר מהברכיים ועד הכתפיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки по бокам ладонями вниз.","Задействуйте корпус и ягодицы, затем поднимите бедра от земли, пока ваше тело не образует прямую линию от колен до плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos a los lados, con las palmas hacia abajo.","Activa el core y los glúteos, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1418","name":"hug keens to chest","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/1418-znP9SIh.jpg","gif_url":"videos/1418-znP9SIh.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים.","כופפו ברכיים והורידו את הגוף לעמדת סקוואט.","תוך כדי הירידה לסקוואט, הביאו את הברכיים לכיוון החזה וחבקו אותן בידיים.","החזיקו את התנוחה לרגע, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position.","As you squat down, bring your knees up towards your chest and hug them with your arms.","Hold this position for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч.","Согните колени и опустите тело в присед.","Приседая, подтяните колени к груди и обхватите их руками.","Задержитесь на мгновение в этом положении, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.","Al ponerte en cuclillas, lleva las rodillas hacia el pecho y abrázalas con los brazos.","Mantén esta posición por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3234","name":"hyght dumbbell fly","category":"chest","body_part":"chest","equipment":"dumbbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/3234-P9ZRyLT.jpg","gif_url":"videos/3234-P9ZRyLT.gif","instruction_steps":{"he":["שכבו על ספסל עם משקולת יד בכל יד, כפות ידיים פונות זו לזו.","יישרו את הידיים למעלה מעל החזה, עם כיפוף קל במרפקים.","עם כיפוף קל במרפקים, הורידו את המשקולות לצדדים בקשת רחבה עד שתרגישו מתיחה בחזה.","עצרו לרגע, ואז הפכו את התנועה והחזירו את המשקולות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на скамью, взяв в каждую руку по гантели, ладони обращены друг к другу.","Вытяните руки прямо вверх над грудью, слегка согнув их в локтях.","Сохраняя небольшой изгиб в локтях, опустите гантели в стороны по широкой дуге, пока не почувствуете растяжение в груди.","Сделайте паузу на мгновение, затем поменяйте направление движения и верните гантели в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.","Manteniendo una ligera flexión en los codos, baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0489","name":"hyperextension","category":"back","body_part":"back","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/0489-zhMwOwE.jpg","gif_url":"videos/0489-zhMwOwE.gif","instruction_steps":{"he":["כווננו את ספסל ההיפראקסטנשן כך שהירכיים העליונות מונחות על הכרית וכפות הרגליים מקובעות.","הצליבו את הידיים על החזה או הניחו אותן מאחורי הראש.","הורידו את פלג הגוף העליון לכיוון הרצפה תוך שמירה על גב ישר.","עצרו לרגע בנקודה התחתונה, ואז הרימו את פלג הגוף העליון חזרה עד שהוא בקו אחד עם הרגליים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте скамью для гиперэкстензии так, чтобы верхняя часть бедер опиралась на подушку, а ступни были зафиксированы.","Скрестите руки на груди или заведите руки за голову.","Опустите верхнюю часть тела к земле, сохраняя спину прямой.","Задержитесь на мгновение в нижней точке, затем снова поднимите верхнюю часть тела вверх, пока она не окажется на одной линии с ногами.","Повторите необходимое количество повторений."],"es":["Ajusta el banco de hiperextensiones para que la parte superior de los muslos quede apoyada en la almohadilla y los pies queden asegurados.","Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza.","Baja la parte superior del cuerpo hacia el suelo manteniendo la espalda recta.","Haz una pausa breve en la parte baja, luego eleva la parte superior del cuerpo hasta que quede alineada con las piernas.","Repite el número de repeticiones deseado."]}},{"id":"0488","name":"hyperextension (on bench)","category":"back","body_part":"back","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/0488-zkgRrbK.jpg","gif_url":"videos/0488-zkgRrbK.gif","instruction_steps":{"he":["כווננו את ספסל ההיפראקסטנשן כך שהאגן מונח בנוחות על הכרית וכפות הרגליים מקובעות.","הצליבו את הידיים על החזה או הניחו אותן מאחורי הראש.","הורידו באיטיות את פלג הגוף העליון לכיוון הרצפה תוך שמירה על גב ישר.","עצרו לרגע בנקודה התחתונה, ואז הרימו את פלג הגוף העליון חזרה עד שהוא בקו אחד עם הרגליים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Slowly lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте скамью для гиперэкстензии так, чтобы ваши бедра удобно лежали на подушке, а ступни были зафиксированы.","Скрестите руки на груди или заведите руки за голову.","Медленно опустите верхнюю часть тела к земле, сохраняя спину прямой.","Задержитесь на мгновение в нижней точке, затем снова поднимите верхнюю часть тела вверх, пока она не окажется на одной линии с ногами.","Повторите необходимое количество повторений."],"es":["Ajusta el banco de hiperextensiones para que las caderas queden apoyadas cómodamente en la almohadilla y los pies queden asegurados.","Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza.","Baja lentamente la parte superior del cuerpo hacia el suelo manteniendo la espalda recta.","Haz una pausa breve en la parte baja, luego eleva la parte superior del cuerpo hasta que quede alineada con las piernas.","Repite el número de repeticiones deseado."]}},{"id":"3289","name":"impossible dips","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/3289-05Cf2v8.jpg","gif_url":"videos/3289-05Cf2v8.gif","instruction_steps":{"he":["התמקמו בין שני מקבילים עם ידיים ישרות לגמרי והגוף תלוי באוויר.","כופפו ברכיים והצליבו את הקרסוליים.","הורידו את הגוף בכיפוף מרפקים עד שהזרועות העליונות מקבילות לרצפה.","עצרו לרגע, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.","Bend your knees and cross your ankles.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Встаньте между двумя параллельными брусьями, полностью вытянув руки и подвешивая тело в воздухе.","Согните колени и скрестите лодыжки.","Опустите тело, сгибая локти, пока плечи не станут параллельны земле.","Сделайте паузу на мгновение, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo suspendido en el aire.","Flexiona las rodillas y cruza los tobillos.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1471","name":"inchworm","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","hamstrings"],"target":"abs","image":"images/1471-ZgsNQ6d.jpg","gif_url":"videos/1471-ZgsNQ6d.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב אגן.","הטו את הגו קדימה מהמותניים והניחו את הידיים על הרצפה לפניכם.","צעדו עם הידיים קדימה עד שאתם בעמדת פלאנק גבוה, עם הגוף בקו ישר מהראש ועד כפות הרגליים.","עצרו לרגע, ואז צעדו עם הידיים חזרה לכיוון כפות הרגליים, תוך שמירה על רגליים ישרות ככל האפשר.","כשהידיים מגיעות לכפות הרגליים, עמדו חזרה בנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible.","Once your hands reach your feet, stand back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с положения стоя, поставив ноги на ширине плеч.","Наклонитесь вперед в талии и положите руки на пол перед собой.","Вытяните руки вперед, пока не окажетесь в положении высокой планки, при этом тело будет составлять прямую линию от головы до пят.","Сделайте паузу на мгновение, затем верните руки назад к ногам, сохраняя ноги как можно более прямыми.","Как только ваши руки достигнут ног, вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de las caderas.","Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti.","Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies.","Haz una pausa breve, luego camina con las manos de vuelta hacia los pies, manteniendo las piernas lo más rectas posible.","Cuando las manos lleguen a los pies, ponte de pie de nuevo en la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3698","name":"inchworm v. 2","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","hamstrings"],"target":"abs","image":"images/3698-TV87DNB.jpg","gif_url":"videos/3698-TV87DNB.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב אגן.","הטו את הגו קדימה מהמותניים והניחו את הידיים על הרצפה לפניכם.","צעדו עם הידיים קדימה עד שאתם בעמדת פלאנק גבוה, עם הגוף בקו ישר מהראש ועד כפות הרגליים.","תוך שמירה על רגליים ישרות, צעדו עם כפות הרגליים לכיוון הידיים, בהרמת האגן לכיוון התקרה.","המשיכו ללכת עם הידיים קדימה, וחזרו על התנועה למספר החזרות הרצוי."],"en":["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling.","Continue walking your hands forward, repeating the movement for the desired number of repetitions."],"ru":["Начните с положения стоя, поставив ноги на ширине плеч.","Наклонитесь вперед в талии и положите руки на пол перед собой.","Вытяните руки вперед, пока не окажетесь в положении высокой планки, при этом тело будет составлять прямую линию от головы до пят.","Держа ноги прямыми, подтяните ступни к рукам, подтягивая бедра к потолку.","Продолжайте шагать руками вперед, повторяя движение желаемое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de las caderas.","Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti.","Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies.","Manteniendo las piernas rectas, camina con los pies hacia las manos, llevando las caderas hacia el techo.","Continúa caminando con las manos hacia adelante, repitiendo el movimiento durante el número de repeticiones deseado."]}},{"id":"0490","name":"incline close-grip push-up","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0490-1YB40kg.jpg","gif_url":"videos/0490-1YB40kg.gif","instruction_steps":{"he":["הניחו את הידיים על משטח מוגבה, כמו ספסל או מדרגה, מעט רחב מרוחב הכתפיים.","מתחו את הרגליים לאחור, נשענים על כריות כפות הרגליים, כשהגוף יוצר קו ישר מהראש ועד העקבים.","הורידו את החזה לכיוון המשטח המוגבה בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.","Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Положите руки на возвышенную поверхность, например на скамью или ступеньку, на расстоянии чуть шире ширины плеч.","Вытяните ноги позади себя, опираясь на подушечки стоп, при этом тело образует прямую линию от головы до пяток.","Опустите грудь к возвышенной поверхности, согнув локти и держа их близко к бокам.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros.","Extiende las piernas detrás de ti, apoyándote en la punta de los pies, con el cuerpo formando una línea recta desde la cabeza hasta los talones.","Baja el pecho hacia la superficie elevada doblando los codos, manteniéndolos cerca de los costados.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0491","name":"incline leg hip raise (leg straight)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0491-eVxAzgz.jpg","gif_url":"videos/0491-eVxAzgz.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע חיובי כשהגב צמוד לספסל והרגליים מתוחות ישר לפניכם.","הניחו את הידיים על צידי הספסל לתמיכה.","תוך הפעלת שרירי הבטן, הרימו את הרגליים מהספסל, גבוה ככל האפשר כשהן ישרות.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.","Place your hands on the sides of the bench for support.","Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, прижав спину к скамье и вытянув ноги прямо перед собой.","Положите руки по бокам скамьи для поддержки.","Включив пресс, поднимите ноги со скамьи, подняв их как можно выше, сохраняя при этом прямыми.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco inclinado con la espalda apoyada plana en el banco y las piernas extendidas rectas frente a ti.","Coloca las manos a los lados del banco para apoyarte.","Activando el abdomen, levanta las piernas del banco, elevándolas tan alto como puedas mientras las mantienes rectas.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0492","name":"incline push up depth jump","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0492-CB8WET1.jpg","gif_url":"videos/0492-CB8WET1.gif","instruction_steps":{"he":["מצאו משטח מוגבה, כמו ספסל או מדרגה, והניחו את הידיים ברוחב כתפיים על הקצה.","צעדו עם כפות הרגליים לאחור, תוך שמירה על גוף בקו ישר מהראש ועד העקבים.","הורידו את החזה לכיוון קצה המשטח, בכיפוף המרפקים ושמירה על גוף מיושר.","דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","קפצו מקצה המשטח, בנחיתה רכה עם ברכיים כפופות מעט.","חזרו על רצף שכיבת הסמיכה וקפיצת העומק למספר החזרות הרצוי."],"en":["Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge.","Step your feet back, keeping your body in a straight line from head to heels.","Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned.","Push through your palms to extend your arms and return to the starting position.","Jump off the edge of the surface, landing softly with your knees slightly bent.","Repeat the push-up and depth jump for the desired number of repetitions."],"ru":["Найдите возвышенную поверхность, например скамью или ступеньку, и поставьте на край руки на ширине плеч.","Отведите ноги назад, удерживая тело от головы до пяток на прямой линии.","Опустите грудь к краю поверхности, сгибая локти и удерживая тело ровным.","Оттолкнитесь ладонями, чтобы вытянуть руки и вернуться в исходное положение.","Спрыгните с края поверхности, мягко приземлившись, слегка согнув колени.","Повторите отжимание и прыжок в глубину необходимое количество повторений."],"es":["Busca una superficie elevada, como un banco o un escalón, y coloca las manos separadas a la altura de los hombros en el borde.","Da un paso hacia atrás con los pies, manteniendo el cuerpo en línea recta desde la cabeza hasta los talones.","Baja el pecho hacia el borde de la superficie, doblando los codos y manteniendo el cuerpo alineado.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Salta desde el borde de la superficie, aterrizando suavemente con las rodillas ligeramente flexionadas.","Repite la flexión de brazos y el salto en profundidad durante el número de repeticiones deseado."]}},{"id":"0493","name":"incline push-up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0493-B1EVP9F.jpg","gif_url":"videos/0493-B1EVP9F.gif","instruction_steps":{"he":["הניחו את הידיים על משטח מוגבה, כמו ספסל או מדרגה, מעט רחב מרוחב הכתפיים.","מתחו את הרגליים לאחור, נשענים על כריות כפות הרגליים, ביצירת קו ישר מהראש ועד העקבים.","הורידו את החזה לכיוון המשטח המוגבה בכיפוף מרפקים, תוך שמירה על גוף בקו ישר.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Положите руки на возвышенную поверхность, например на скамью или ступеньку, на расстоянии чуть шире ширины плеч.","Вытяните ноги позади себя, опираясь на подушечки стоп, создавая прямую линию от головы до пяток.","Опустите грудь к возвышению, сгибая локти, сохраняя тело прямой линией.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros.","Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones.","Baja el pecho hacia la superficie elevada doblando los codos, manteniendo el cuerpo en línea recta.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"3785","name":"incline push-up (on box)","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/3785-F7vjXqT.jpg","gif_url":"videos/3785-F7vjXqT.gif","instruction_steps":{"he":["הניחו את הידיים על קצה קופסה או משטח מוגבה, מעט רחב מרוחב הכתפיים.","מתחו את הרגליים לאחור, נשענים על כריות כפות הרגליים, ביצירת קו ישר מהראש ועד העקבים.","הורידו את החזה לכיוון הקופסה בכיפוף מרפקים, תוך שמירה על גוף בקו ישר.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the box by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Положите руки на край коробки или возвышенной поверхности, на расстоянии чуть шире плеч.","Вытяните ноги позади себя, опираясь на подушечки стоп, создавая прямую линию от головы до пяток.","Опустите грудь к ящику, согнув локти, сохраняя тело прямой.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Coloca las manos en el borde de una caja o una superficie elevada, ligeramente más separadas que la altura de los hombros.","Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones.","Baja el pecho hacia la caja doblando los codos, manteniendo el cuerpo en línea recta.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0494","name":"incline reverse grip push-up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0494-XaaRnRn.jpg","gif_url":"videos/0494-XaaRnRn.gif","instruction_steps":{"he":["הניחו את הידיים על קצה ספסל או משטח מוגבה, מעט רחב מרוחב הכתפיים.","מתחו את הרגליים לאחור, נשענים על כריות כפות הרגליים, ביצירת קו ישר מהראש ועד העקבים.","הורידו את החזה לכיוון הספסל בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the bench by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"ru":["Положите руки на край скамьи или возвышенной поверхности, на расстоянии чуть шире ширины плеч.","Вытяните ноги позади себя, опираясь на подушечки стоп, создавая прямую линию от головы до пяток.","Опустите грудь к скамье, согнув локти и держа их близко к бокам.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение, вытянув руки.","Повторите необходимое количество повторений."],"es":["Coloca las manos en el borde de un banco o una superficie elevada, ligeramente más separadas que la altura de los hombros.","Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones.","Baja el pecho hacia el banco doblando los codos, manteniéndolos cerca de los costados.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"3011","name":"incline scapula push up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"serratus anterior","image":"images/3011-GdMa1ET.jpg","gif_url":"videos/3011-GdMa1ET.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","הניחו את הידיים על הספסל, מעט רחב מרוחב הכתפיים.","מקמו את כפות הרגליים על הרצפה, ברוחב אגן.","הורידו את החזה לכיוון הספסל, תוך שמירה על מרפקים צמודים.","תוך כדי הירידה, כווצו את השכמות לאחור, בלחיצתן זו לזו.","דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Place your hands on the bench slightly wider than shoulder-width apart.","Position your feet on the ground, hip-width apart.","Lower your chest towards the bench, keeping your elbows tucked in.","As you lower, retract your shoulder blades, squeezing your scapulae together.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Положите руки на скамью чуть шире ширины плеч.","Поставьте ноги на землю, на ширине плеч.","Опустите грудь к скамье, держа локти прижатыми.","Опускаясь, сводите лопатки, сжимая лопатки вместе.","Оттолкнитесь ладонями, чтобы вытянуть руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Coloca las manos en el banco, ligeramente más separadas que la altura de los hombros.","Coloca los pies en el suelo, separados a la altura de las caderas.","Baja el pecho hacia el banco, manteniendo los codos pegados al cuerpo.","Mientras bajas, retrae los omóplatos, apretándolos entre sí.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0495","name":"incline twisting sit-up","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0495-9ZGZuOD.jpg","gif_url":"videos/0495-9ZGZuOD.gif","instruction_steps":{"he":["כווננו ספסל שיפוע לזווית של 45 מעלות.","שכבו על הספסל כשכפות הרגליים מקובעות מתחת לכריות הרגליים.","מקמו את הידיים מאחורי הראש או מוצלבות על החזה.","הפעילו את שרירי הבטן והרימו את פלג הגוף העליון מהספסל, בגלגול קדימה.","תוך כדי הגלגול למעלה, סובבו את הגו לצד אחד, בהבאת המרפק לכיוון הברך הנגדית.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התנועה, הפעם בסיבוב הגו לצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward.","As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat the movement, this time twisting your torso to the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте на скамью, зафиксировав ноги под подушечками для ног.","Положите руки за голову или на грудь.","Напрягите пресс и поднимите верхнюю часть тела со скамьи, наклонившись вперед.","Сгибаясь, поверните туловище в одну сторону, поднося локоть к противоположному колену.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите движение, на этот раз повернув туловище в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el abdomen y levanta la parte superior del cuerpo del banco, curvándote hacia adelante.","Mientras te incorporas, gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el movimiento, esta vez girando el torso hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1564","name":"intermediate hip flexor and quad stretch","category":"upper legs","body_part":"upper legs","equipment":"rope","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"quads","image":"images/1564-tFGKm99.jpg","gif_url":"videos/1564-tFGKm99.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים.","אחזו בחפץ יציב לתמיכה.","כופפו את ברך ימין והביאו את כף רגל ימין לכיוון הישבן, אוחזים בחבל ביד ימין.","משכו באיטיות את כף רגל ימין לכיוון הישבן, עד תחושת מתיחה בארבע ראשי הימני.","החזיקו את המתיחה 20–30 שניות.","שחררו את המתיחה וחזרו עליה בצד שמאל."],"en":["Stand upright with your feet shoulder-width apart.","Hold onto a stable object for support.","Bend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand.","Slowly pull your right foot towards your glutes, feeling a stretch in your right quad.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the left side."],"ru":["Встаньте прямо, ноги на ширине плеч.","Держитесь за устойчивый объект для поддержки.","Согните правое колено и поднесите правую ногу к ягодицам, захватив веревку правой рукой.","Медленно подтяните правую ногу к ягодицам, чувствуя растяжение правого квадрицепса.","Удерживайте растяжку 20–30 секунд.","Освободите растяжку и повторите с левой стороны."],"es":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Sujétate de un objeto estable para mayor apoyo.","Dobla la rodilla derecha y lleva el pie derecho hacia los glúteos, sujetando la cuerda con la mano derecha.","Tira lentamente del pie derecho hacia los glúteos, sintiendo un estiramiento en el cuádriceps derecho.","Mantén el estiramiento durante 20-30 segundos.","Suelta el estiramiento y repite en el lado izquierdo."]}},{"id":"0496","name":"inverse leg curl (bench support)","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","calves"],"target":"hamstrings","image":"images/0496-ms7tjSG.jpg","gif_url":"videos/0496-ms7tjSG.gif","instruction_steps":{"he":["שכבו על הבטן על ספסל כשהאגן בקצה והרגליים מתוחות ישר לאחור.","אחזו בספסל לתמיכה.","תוך שמירה על פלג גוף עליון ללא תזוזה, כופפו ברכיים וגלגלו את הרגליים לכיוון הישבן.","עצרו לרגע בנקודה העליונה, ואז יישרו באיטיות את הרגליים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie face down on a bench with your hips at the edge and your legs extended straight behind you.","Hold onto the bench for support.","Keeping your upper body still, bend your knees and curl your legs towards your glutes.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте лицом вниз на скамью, прижав бедра к краю и вытянув ноги прямо позади себя.","Держитесь за скамью для поддержки.","Удерживая верхнюю часть тела неподвижно, согните колени и согните ноги к ягодицам.","Задержитесь на мгновение в верхней точке, затем медленно вытяните ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo en un banco con las caderas en el borde y las piernas extendidas rectas detrás de ti.","Sujétate del banco para mayor apoyo.","Manteniendo la parte superior del cuerpo quieta, dobla las rodillas y curva las piernas hacia los glúteos.","Haz una pausa breve en la parte superior, luego extiende lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2400","name":"inverse leg curl (on pull-up cable machine)","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","calves"],"target":"hamstrings","image":"images/2400-0rHfvy9.jpg","gif_url":"videos/2400-0rHfvy9.gif","instruction_steps":{"he":["כווננו את מכשיר הכבלים כך שרצועות הקרסול בתנוחה הנמוכה ביותר.","שכבו על הבטן על הספסל עם רגליים מתוחות ורצועות הקרסול מחוברות לכפות הרגליים.","אחזו בידיות הספסל לייצוב.","כופפו ברכיים וגלגלו את הרגליים לכיוון הישבן, בכיווץ הירך האחורית.","עצרו לרגע בנקודה העליונה של התנועה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the cable machine so that the ankle straps are at the lowest setting.","Lie face down on the bench with your legs extended and the ankle straps attached to your feet.","Hold onto the handles of the bench for stability.","Bend your knees and curl your legs towards your glutes, squeezing your hamstrings.","Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте блочный тренажер так, чтобы ремни на щиколотках находились в самом нижнем положении.","Лягте лицом вниз на скамью, вытянув ноги и прикрепив к ступням ремни на щиколотках.","Держитесь за ручки скамьи для устойчивости.","Согните колени и согните ноги к ягодицам, сжимая мышцы задней поверхности бедра.","Сделайте паузу на мгновение в верхней точке движения, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de cable para que las correas de tobillo estén en el ajuste más bajo.","Túmbate boca abajo en el banco con las piernas extendidas y las correas de tobillo sujetas a los pies.","Sujétate de las agarraderas del banco para mantener la estabilidad.","Dobla las rodillas y curva las piernas hacia los glúteos, contrayendo los isquiotibiales.","Haz una pausa breve en la parte superior del movimiento, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0499","name":"inverted row","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0499-bZGHsAZ.jpg","gif_url":"videos/0499-bZGHsAZ.gif","instruction_steps":{"he":["הכינו מוט בגובה המותניים או השתמשו ברצועות אימון.","עמדו מול המוט או רצועות האימון, עם רגליים ברוחב כתפיים.","אחזו במוט או בידיות באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היטו לאחור, תוך שמירה על גוף ישר והעקבים על הרצפה.","משכו את החזה לכיוון המוט או הידיות, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up a bar at waist height or use a suspension trainer.","Stand facing the bar or suspension trainer, with your feet shoulder-width apart.","Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите перекладину на уровне талии или используйте тренажер для подвешивания.","Встаньте лицом к штанге или тренажеру для отягощения, поставив ноги на ширине плеч.","Возьмитесь за перекладину или ручки хватом сверху, на расстоянии чуть шире ширины плеч.","Откиньтесь назад, держа тело прямо, а пятки на земле.","Подтяните грудь к перекладине или ручкам, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca una barra a la altura de la cintura o usa un entrenador de suspensión.","Ponte de pie frente a la barra o al entrenador de suspensión, con los pies separados a la altura de los hombros.","Agarra la barra o las asas con agarre prono, ligeramente más ancho que la altura de los hombros.","Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo.","Tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2300","name":"inverted row bent knees","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/2300-VPPtusI.jpg","gif_url":"videos/2300-VPPtusI.gif","instruction_steps":{"he":["הכינו מוט בגובה המותניים ושכבו מתחתיו.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","מקמו את הגוף כך שהעקבים על הרצפה והגוף ישר.","משכו את החזה למעלה לכיוון המוט בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up a bar at waist height and lie underneath it.","Grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your body is straight.","Pull your chest up towards the bar by squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите перекладину на уровне талии и лягте под нее.","Возьмите штангу хватом сверху, на расстоянии чуть шире ширины плеч.","Расположите свое тело так, чтобы пятки стояли на земле, а тело было прямым.","Подтяните грудь к перекладине, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca una barra a la altura de la cintura y túmbate debajo de ella.","Agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros.","Coloca el cuerpo de manera que los talones queden en el suelo y el cuerpo esté recto.","Tira del pecho hacia arriba en dirección a la barra apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2298","name":"inverted row on bench","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/2298-Mxa7Cr8.jpg","gif_url":"videos/2298-Mxa7Cr8.gif","instruction_steps":{"he":["הכינו ספסל בגובה שמאפשר לגוף להיתלות בחופשיות מתחתיו.","שכבו על הגב על הרצפה כשהראש לכיוון הספסל.","הושיטו ידיים ואחזו בספסל באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","מקמו את הגוף כך שהעקבים על הרצפה והידיים מתוחות לגמרי.","הפעילו את הליבה וכווצו את השכמות זו לזו תוך משיכת החזה למעלה לכיוון הספסל.","עצרו לרגע בנקודה העליונה של התנועה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up a bench at a height that allows your body to hang freely underneath it.","Lie face up on the ground with your head towards the bench.","Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your arms are fully extended.","Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите скамью на высоте, позволяющей вашему телу свободно висеть под ней.","Лягте на землю лицом вверх, головой к скамье.","Потянитесь и возьмитесь за скамью хватом сверху, на расстоянии чуть шире плеч.","Расположите свое тело так, чтобы пятки были на земле, а руки полностью выпрямлены.","Напрягите корпус и сведите лопатки вместе, одновременно подтягивая грудь к скамье.","Сделайте паузу на мгновение в верхней точке движения, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un banco a una altura que permita que el cuerpo cuelgue libremente debajo de él.","Túmbate boca arriba en el suelo con la cabeza hacia el banco.","Estira los brazos hacia arriba y agarra el banco con agarre prono, ligeramente más ancho que la altura de los hombros.","Coloca el cuerpo de manera que los talones queden en el suelo y los brazos completamente extendidos.","Activa el core y aprieta los omóplatos entre sí mientras tiras del pecho hacia el banco.","Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0497","name":"inverted row v. 2","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0497-uX3sUBz.jpg","gif_url":"videos/0497-uX3sUBz.gif","instruction_steps":{"he":["הכינו מוט בגובה המותניים במכונת סמית' או השתמשו ברצועות אימון.","עמדו מול המוט או רצועות האימון ואחזו בו באחיזה עליונה, ידיים ברוחב כתפיים.","צעדו עם כפות הרגליים קדימה, בהטיה לאחור עד שהגוף בזווית קלה.","שמרו על גוף ישר ומשכו את החזה למעלה לכיוון המוט או הידיות, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up a bar at waist height on a Smith machine or use a suspension trainer.","Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart.","Walk your feet forward, leaning back until your body is at a slight angle.","Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите штангу на уровне талии на тренажере Смита или используйте тренажер с подвеской.","Встаньте лицом к штанге или тренажеру для отягощения и возьмитесь за нее хватом сверху, руки на ширине плеч.","Пройдите ногами вперед, отклоняясь назад, пока ваше тело не окажется под небольшим углом.","Держите тело прямо и подтяните грудь к перекладине или ручкам, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca una barra a la altura de la cintura en una máquina Smith o usa un entrenador de suspensión.","Ponte de pie frente a la barra o al entrenador de suspensión y agárrala con agarre prono, manos separadas a la altura de los hombros.","Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en un ligero ángulo.","Mantén el cuerpo recto y tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0498","name":"inverted row with straps","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0498-jdiExfW.jpg","gif_url":"videos/0498-jdiExfW.gif","instruction_steps":{"he":["הכינו רצועות אימון בגובה החזה.","עמדו מול נקודת העיגון ואחזו בידיות באחיזה עליונה.","צעדו עם כפות הרגליים קדימה, בהטיה לאחור עד שהגוף בזווית.","שמרו על גוף ישר והפעילו את הליבה.","משכו את החזה לכיוון הידיות, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up a suspension trainer or straps at chest height.","Stand facing the anchor point and grab the handles with an overhand grip.","Walk your feet forward, leaning back until your body is at an angle.","Keep your body straight and engage your core.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите тренажер для подвешивания или ремни на уровне груди.","Встаньте лицом к точке крепления и возьмитесь за ручки хватом сверху.","Пройдите ногами вперед, отклоняясь назад, пока ваше тело не окажется под углом.","Держите тело прямо и задействуйте корпус.","Подтяните грудь к ручкам, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un entrenador de suspensión o correas a la altura del pecho.","Ponte de pie frente al punto de anclaje y agarra las asas con agarre prono.","Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en ángulo.","Mantén el cuerpo recto y activa el core.","Tira del pecho hacia las asas, apretando los omóplatos entre sí.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1419","name":"iron cross stretch","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/1419-pZwUsKB.jpg","gif_url":"videos/1419-pZwUsKB.gif","instruction_steps":{"he":["שכבו על הגב עם ידיים מתוחות לצדדים.","הרימו את הרגליים לכיוון התקרה, כשהן ישרות.","הורידו באיטיות את הרגליים לצד אחד, במטרה לגעת ברצפה עם כפות הרגליים.","החזיקו את המתיחה כמה שניות, ואז החזירו את הרגליים לנקודת ההתחלה.","חזרו על המתיחה בצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Lie flat on your back with your arms extended out to the sides.","Raise your legs up towards the ceiling, keeping them straight.","Slowly lower your legs to one side, aiming to touch the floor with your feet.","Hold the stretch for a few seconds, then return your legs to the starting position.","Repeat the stretch on the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Лягте на спину, вытянув руки в стороны.","Поднимите ноги к потолку, сохраняя их прямыми.","Медленно опустите ноги в сторону, стараясь коснуться ступнями пола.","Удерживайте растяжку несколько секунд, затем верните ноги в исходное положение.","Повторите растяжку с другой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Túmbate boca arriba con los brazos extendidos hacia los lados.","Levanta las piernas hacia el techo, manteniéndolas rectas.","Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies.","Mantén el estiramiento durante unos segundos, luego regresa las piernas a la posición inicial.","Repite el estiramiento en el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1297","name":"isometric chest squeeze","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1297-HbSG1Pw.jpg","gif_url":"videos/1297-HbSG1Pw.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","מתחו את הידיים ישר לפניכם, מקבילות לרצפה, עם כפות ידיים פונות זו לזו.","כווצו את שרירי החזה יחד חזק ככל האפשר, תוך שמירה על ידיים ישרות.","החזיקו את התנוחה כמה שניות, בהתמקדות בכיווץ שרירי החזה.","שחררו את הכיווץ והרפו את שרירי החזה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other.","Squeeze your chest muscles together as hard as you can, while keeping your arms straight.","Hold this position for a few seconds, focusing on contracting your chest muscles.","Release the squeeze and relax your chest muscles.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Вытяните руки прямо перед собой, параллельно земле, ладонями друг к другу.","Сожмите мышцы груди как можно сильнее, сохраняя при этом руки прямыми.","Удерживайте это положение несколько секунд, сосредоточив внимание на сокращении мышц груди.","Ослабьте сжатие и расслабьте мышцы груди.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Extiende los brazos rectos frente a ti, paralelos al suelo, con las palmas una frente a la otra.","Aprieta los músculos del pecho con la mayor fuerza posible, manteniendo los brazos rectos.","Mantén esta posición durante unos segundos, concentrándote en contraer los músculos del pecho.","Suelta la contracción y relaja los músculos del pecho.","Repite el número de repeticiones deseado."]}},{"id":"0500","name":"isometric wipers","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","core"],"target":"pectorals","image":"images/0500-11wrviz.jpg","gif_url":"videos/0500-11wrviz.gif","instruction_steps":{"he":["התחילו בשכיבה על הגב על מזרן או ספסל.","מתחו את הידיים ישר לצדדים, ניצבות לגוף.","הפעילו את הליבה והרימו את שתי הרגליים מהרצפה, כשהן צמודות וישרות.","הורידו באיטיות את הרגליים לצד אחד, במטרה לגעת ברצפה עם כפות הרגליים תוך שמירה על שליטה.","עצרו לרגע, ואז השתמשו בליבה להרמת הרגליים חזרה לנקודת ההתחלה.","חזרו על התנועה, הפעם בהורדת הרגליים לצד הנגדי.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Start by lying flat on your back on a mat or bench.","Extend your arms straight out to the sides, perpendicular to your body.","Engage your core and lift both legs off the ground, keeping them together and straight.","Slowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control.","Pause for a moment, then use your core to lift your legs back to the starting position.","Repeat the movement, this time lowering your legs to the opposite side.","Continue alternating sides for the desired number of repetitions."],"ru":["Начните с того, что лягте на спину на коврик или скамью.","Вытяните руки прямо в стороны, перпендикулярно телу.","Напрягите корпус и поднимите обе ноги от земли, держа их вместе и прямо.","Медленно опустите ноги в сторону, стараясь коснуться ступнями земли, сохраняя при этом контроль.","Сделайте паузу на мгновение, затем с помощью корпуса поднимите ноги обратно в исходное положение.","Повторите движение, на этот раз опуская ноги в противоположную сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Comienza acostado boca arriba en una esterilla o un banco.","Extiende los brazos hacia los lados, perpendiculares al cuerpo.","Activa el core y levanta ambas piernas del suelo, manteniéndolas juntas y rectas.","Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies mientras mantienes el control.","Haz una pausa breve, luego usa el core para llevar las piernas de vuelta a la posición inicial.","Repite el movimiento, esta vez bajando las piernas hacia el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0501","name":"jack burpee","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","shoulders","triceps","core"],"target":"cardiovascular system","image":"images/0501-mr7pkqP.jpg","gif_url":"videos/0501-mr7pkqP.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים.","הורידו את הגוף לעמדת סקוואט, בהנחת הידיים על הרצפה לפניכם.","בעטו את הרגליים לאחור, בנחיתה בעמדת שכיבת סמיכה.","בצעו שכיבת סמיכה — הורידו את החזה לרצפה ודחפו חזרה למעלה.","קפצו עם הרגליים קדימה, בנחיתה בעמדת סקוואט.","קפצו למעלה בפיצוץ, עם ידיים מתוחות מעל הראש.","נחתו ברכות וחזרו מיד לעמדת הסקוואט לתחילת החזרה הבאה."],"en":["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position, placing your hands on the ground in front of you.","Kick your feet back, landing in a push-up position.","Perform a push-up, lowering your chest to the ground and then pushing back up.","Jump your feet forward, landing in a squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into the squat position to begin the next repetition."],"ru":["Начните с положения стоя, поставив ноги на ширине плеч.","Опустите тело в присед, положив руки на пол перед собой.","Отведите ноги назад, приземлившись в положение для отжимания.","Выполните отжимание, опуская грудь на землю, а затем снова поднимаясь вверх.","Прыгните ногами вперед и приземлитесь в приседе.","Резко подпрыгните вверх, вытянув руки над головой.","Мягко приземлитесь и сразу же опуститесь обратно в положение приседа, чтобы начать следующее повторение."],"es":["Comienza de pie con los pies separados a la altura de los hombros.","Baja el cuerpo a una posición de sentadilla, colocando las manos en el suelo frente a ti.","Lanza los pies hacia atrás, aterrizando en posición de flexión de brazos.","Realiza una flexión de brazos, bajando el pecho hacia el suelo y luego empujando de nuevo hacia arriba.","Salta con los pies hacia adelante, aterrizando en posición de sentadilla.","Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza.","Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición."]}},{"id":"3224","name":"jack jump (male)","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","calves"],"target":"cardiovascular system","image":"images/3224-1g5bPpA.jpg","gif_url":"videos/3224-1g5bPpA.gif","instruction_steps":{"he":["עמדו עם רגליים צמודות וידיים לצידי הגוף.","קפצו למעלה, בפתיחת הרגליים לצדדים והרמת הידיים מעל הראש.","עם הנחיתה, קפצו במהירות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet together and your arms by your sides.","Jump up, spreading your feet apart and raising your arms above your head.","As you land, quickly jump back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги вместе, руки по бокам.","Подпрыгните вверх, разведя ноги в стороны и подняв руки над головой.","Приземлившись, быстро вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies juntos y los brazos a los costados.","Salta, separando los pies y levantando los brazos por encima de la cabeza.","Al aterrizar, salta rápidamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0507","name":"jackknife sit-up","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0507-mbkgB44.jpg","gif_url":"videos/0507-mbkgB44.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וידיים מתוחות מעל הראש.","הפעילו את שרירי הליבה והרימו את הרגליים ופלג הגוף העליון בו-זמנית, עם ידיים נמתחות לכיוון כפות הרגליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים ופלג הגוף העליון באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs extended and your arms overhead.","Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, вытянув ноги и подняв руки над головой.","Напрягите корпус и одновременно поднимите ноги и верхнюю часть тела, дотягиваясь руками до пальцев ног.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги и верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba con las piernas extendidas y los brazos por encima de la cabeza.","Activa el core y levanta las piernas y la parte superior del cuerpo al mismo tiempo, llevando las manos hacia los dedos de los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0508","name":"janda sit-up","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0508-1GPHRyK.jpg","gif_url":"videos/0508-1GPHRyK.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2612","name":"jump rope","category":"cardio","body_part":"cardio","equipment":"rope","muscle_group":"calves","secondary_muscles":["calves","quadriceps","hamstrings","glutes"],"target":"cardiovascular system","image":"images/2612-e1e76I2.jpg","gif_url":"videos/2612-e1e76I2.gif","instruction_steps":{"he":["החזיקו את ידיות חבל הקפיצה בידיים, כפות ידיים פונות פנימה.","עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","הניפו את החבל מעל הראש וקפצו מעליו כשהוא מגיע לכיוון כפות הרגליים.","נחתו ברכות על כריות כפות הרגליים וחזרו על הקפיצה כשהחבל מגיע שוב.","המשיכו לקפוץ למשך הזמן או מספר החזרות הרצוי."],"en":["Hold the handles of the jump rope with your hands, palms facing inward.","Stand with your feet shoulder-width apart and knees slightly bent.","Swing the rope over your head and jump over it as it comes towards your feet.","Land softly on the balls of your feet and repeat the jump as the rope comes around again.","Continue jumping for the desired duration or number of repetitions."],"ru":["Возьмитесь руками за ручки скакалки ладонями внутрь.","Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Перекиньте веревку над головой и перепрыгните через нее, когда она приблизится к вашим ногам.","Мягко приземлитесь на подушечки ног и повторите прыжок, когда веревка снова закрутится.","Продолжайте прыгать желаемую продолжительность или количество повторений."],"es":["Sujeta las asas de la cuerda de saltar con las manos, palmas hacia adentro.","Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Balancea la cuerda por encima de la cabeza y salta sobre ella cuando se acerque a los pies.","Aterriza suavemente sobre la punta de los pies y repite el salto cuando la cuerda vuelva a pasar.","Continúa saltando durante el tiempo o el número de repeticiones deseado."]}},{"id":"0514","name":"jump squat","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0514-LIlE5Tn.jpg","gif_url":"videos/0514-LIlE5Tn.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","רדו לסקוואט בכיפוף ברכיים ודחיפת האגן לאחור.","קפצו מהרצפה בפיצוץ, תוך יישור ירכיים, ברכיים וקרסוליים.","באוויר, הביאו במהירות את הידיים קדימה לשיווי משקל.","נחתו ברכות על כריות כפות הרגליים והמשיכו מיד לחזרה הבאה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively off the ground, extending your hips, knees, and ankles.","While in mid-air, quickly bring your arms forward for balance.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Опустите тело в присед, согнув колени и отведя бедра назад.","Резко подпрыгните от земли, выпрямляя бедра, колени и лодыжки.","Находясь в воздухе, быстро вытяните руки вперед для равновесия.","Мягко приземлитесь на подушечки стоп и сразу же переходите к следующему повторению.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Salta de forma explosiva desde el suelo, extendiendo las caderas, las rodillas y los tobillos.","Mientras estás en el aire, lleva rápidamente los brazos hacia adelante para mantener el equilibrio.","Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición.","Repite el número de repeticiones deseado."]}},{"id":"0513","name":"jump squat v. 2","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0513-TDYiji6.jpg","gif_url":"videos/0513-TDYiji6.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","רדו לסקוואט בכיפוף ברכיים ודחיפת האגן לאחור.","קפצו בפיצוץ, תוך יישור מלא של הירכיים והברכיים.","נחתו ברכות על כריות כפות הרגליים ורדו מיד חזרה לעמדת סקוואט.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively, extending your hips and knees fully.","Land softly on the balls of your feet and immediately lower your body back into a squat position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Опустите тело в присед, согнув колени и отведя бедра назад.","Прыгайте взрывно, полностью выпрямляя бедра и колени.","Мягко приземлитесь на подушечки стоп и сразу же опустите тело обратно в присед.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Salta de forma explosiva, extendiendo por completo las caderas y las rodillas.","Aterriza suavemente sobre la punta de los pies y de inmediato baja el cuerpo de nuevo a una posición de sentadilla.","Repite el número de repeticiones deseado."]}},{"id":"0517","name":"kettlebell advanced windmill","category":"waist","body_part":"waist","equipment":"kettlebell","muscle_group":"obliques","secondary_muscles":["obliques","shoulders"],"target":"abs","image":"images/0517-Kal9cQQ.jpg","gif_url":"videos/0517-Kal9cQQ.gif","instruction_steps":{"he":["עמדו עם רגליים רחבות מרוחב הכתפיים, כפות רגליים פונות מעט החוצה.","החזיקו קטלבל ביד ימין, עם היד מתוחה מעל הראש וכף היד פונה קדימה.","סובבו את כף רגל שמאל מעט ימינה, והעבירו את המשקל לרגל שמאל.","כופפו את ברך שמאל והטו את הגו מהירך, בהורדת הגו לצד שמאל.","שמרו על יד ימין מתוחה מעל הראש והעיניים על הקטלבל.","תוך כדי הורדת הגו, תנו לרגל ימין להתיישר ולכף רגל ימין להסתובב מעט.","הורידו את הגו עד לתחושת מתיחה בירך האחורית השמאלית ויד ימין מצביעה לכיוון הרצפה.","עצרו לרגע, ואז הפעילו את הליבה ודחפו דרך עקב שמאל לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.","Rotate your left foot slightly to the right, and shift your weight onto your left leg.","Bend your left knee and hinge at the hip, lowering your torso towards the left side.","Keep your right arm extended overhead and your eyes on the kettlebell.","As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly.","Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground.","Pause for a moment, then engage your core and push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, поставив ноги шире ширины плеч, носки слегка направлены наружу.","Возьмите гирю в правую руку, вытянув руку над головой и ладонью вперед.","Слегка поверните левую ногу вправо и перенесите вес тела на левую ногу.","Согните левое колено и согнитесь в бедре, опуская туловище влево.","Держите правую руку вытянутой над головой и смотрите на гирю.","Опуская туловище, позвольте правой ноге выпрямиться, а правой ступне слегка повернуться.","Опускайте туловище до тех пор, пока не почувствуете растяжение левого задней поверхности бедра и правую руку, направленную к земле.","Сделайте паузу на мгновение, затем задействуйте корпус и толкните левую пятку, чтобы вернуться в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.","Sostén una pesa rusa en la mano derecha, con el brazo extendido por encima de la cabeza y la palma hacia adelante.","Gira el pie izquierdo ligeramente hacia la derecha y traslada el peso hacia la pierna izquierda.","Dobla la rodilla izquierda y flexiona la cadera, bajando el torso hacia el lado izquierdo.","Mantén el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa.","Mientras bajas el torso, permite que la pierna derecha se enderece y que el pie derecho gire ligeramente.","Baja el torso hasta sentir un estiramiento en el isquiotibial izquierdo y que el brazo derecho apunte hacia el suelo.","Haz una pausa breve, luego activa el core y empuja con el talón izquierdo para regresar a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0518","name":"kettlebell alternating hang clean","category":"lower arms","body_part":"lower arms","equipment":"kettlebell","muscle_group":"shoulders","secondary_muscles":["shoulders","traps","core"],"target":"forearms","image":"images/0518-I4tibZG.jpg","gif_url":"videos/0518-I4tibZG.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל בכל יד באחיזה עליונה.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וחזה מורם.","תנו לקטלבלים להשתלשל מול הגוף עם ידיים מתוחות לגמרי.","בתנועה רציפה אחת, יישרו ירכיים בפיצוץ, משכו כתפיים, ומשכו את הקטלבלים למעלה לכיוון הכתפיים.","כשהקטלבלים מגיעים לגובה הכתפיים, סובבו את שורשי כף היד ותפסו אותם בתנוחת ראק, עם כפות ידיים פונות פנימה והקטלבלים מונחים על החלק החיצוני של האמות.","הורידו את הקטלבלים חזרה לנקודת ההתחלה וחזרו על התנועה עם היד השנייה.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang in front of your body with your arms fully extended.","In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms.","Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гире хватом сверху.","Слегка согните колени и наклонитесь вперед в бедрах, держа спину прямо и грудь вверх.","Позвольте гирям висеть перед вашим телом, полностью вытянув руки.","Одним плавным движением резко выпрямите бедра, пожмите плечами и подтяните гири к плечам.","Когда гири достигнут высоты плеч, поверните запястья и поймайте гири в положении стойки, ладонями внутрь, а гирями — на внешней стороне предплечий.","Опустите гири обратно в исходное положение и повторите движение противоположной рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Deja que las pesas rusas cuelguen frente al cuerpo con los brazos completamente extendidos.","En un solo movimiento fluido, extiende las caderas de forma explosiva, encoge los hombros y tira de las pesas rusas hacia los hombros.","Cuando las pesas rusas alcancen la altura de los hombros, gira las muñecas y atrápalas en posición de descanso, con las palmas hacia adentro y las pesas rusas apoyadas en la parte externa de los antebrazos.","Baja las pesas rusas de nuevo a la posición inicial y repite el movimiento con el brazo opuesto.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"0520","name":"kettlebell alternating press","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0520-5KLbZWx.jpg","gif_url":"videos/0520-5KLbZWx.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל בכל יד בגובה הכתפיים.","לחצו קטלבל אחד מעל הראש, עד יישור מלא של היד.","הורידו את הקטלבל חזרה לגובה הכתף.","חזרו על התנועה עם היד השנייה.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Press one kettlebell overhead, fully extending your arm.","Lower the kettlebell back to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гире на уровне плеч.","Выжмите одну гирю над головой, полностью выпрямляя руку.","Опустите гирю обратно на высоту плеч.","Повторите с другой рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros.","Empuja una pesa rusa por encima de la cabeza, extendiendo el brazo por completo.","Baja la pesa rusa de nuevo a la altura de los hombros.","Repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"0519","name":"kettlebell alternating press on floor","category":"chest","body_part":"chest","equipment":"kettlebell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0519-7w6i0vE.jpg","gif_url":"videos/0519-7w6i0vE.gif","instruction_steps":{"he":["התחילו בשכיבה על הגב על הרצפה עם ברכיים כפופות וכפות רגליים על הרצפה.","החזיקו קטלבל בכל יד, כשכפות הידיים פונות לכיוון כפות הרגליים והידיים מתוחות ישר לכיוון התקרה.","הורידו קטלבל אחד לכיוון הכתף, תוך שמירה על הקטלבל השני מתוח ישר למעלה.","לחצו את הקטלבל שהורד חזרה למעלה לנקודת ההתחלה ובו-זמנית הורידו את הקטלבל השני לכיוון הכתף.","המשיכו להחליף את תנועת הלחיצה בין הקטלבלים למספר החזרות הרצוי."],"en":["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling.","Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up.","Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder.","Continue alternating the press motion with each kettlebell for the desired number of repetitions."],"ru":["Начните с того, что лягте на спину на пол, согните колени и поставьте ступни на землю.","Возьмите в каждую руку по гире, ладонями к ногам, а руками вытянутыми вверх к потолку.","Опустите одну гирю вниз к плечу, удерживая другую гирю вытянутой прямо вверх.","Верните опущенную гирю в исходное положение, одновременно опуская другую гирю вниз к плечу.","Продолжайте чередовать движения жима каждой гири желаемое количество повторений."],"es":["Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo.","Sostén una pesa rusa en cada mano, con las palmas hacia los pies y los brazos extendidos rectos hacia el techo.","Baja una pesa rusa hacia el hombro mientras mantienes la otra pesa rusa extendida recta hacia arriba.","Empuja la pesa rusa bajada de vuelta hacia la posición inicial mientras al mismo tiempo bajas la otra pesa rusa hacia el hombro.","Continúa alternando el movimiento de empuje con cada pesa rusa durante el número de repeticiones deseado."]}},{"id":"0521","name":"kettlebell alternating renegade row","category":"back","body_part":"back","equipment":"kettlebell","muscle_group":"core","secondary_muscles":["core","shoulders"],"target":"upper back","image":"images/0521-b9kqlBy.jpg","gif_url":"videos/0521-b9kqlBy.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם הידיים אוחזות בקטלבלים ורגליים ברוחב אגן.","הפעילו את הליבה ושמרו על הגוף בקו ישר מהראש ועד העקבים.","משכו קטלבל אחד למעלה לכיוון החזה, תוך שמירה על מרפק קרוב לגוף.","הורידו את הקטלבל חזרה לנקודת ההתחלה וחזרו על התנועה עם היד השנייה.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Pull one kettlebell up towards your chest, keeping your elbow close to your body.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, держа руками гири и расставив ноги на ширине плеч.","Напрягите корпус и держите тело на прямой линии от головы до пяток.","Подтяните одну гирю к груди, держа локоть близко к телу.","Опустите гирю обратно в исходное положение и повторите то же самое с другой рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Comienza en posición de plancha alta con las manos sujetando las pesas rusas y los pies separados a la altura de las caderas.","Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones.","Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo.","Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"0522","name":"kettlebell alternating row","category":"back","body_part":"back","equipment":"kettlebell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0522-Ca76jUE.jpg","gif_url":"videos/0522-Ca76jUE.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, ברכיים כפופות מעט, ואחזו קטלבל בכל יד עם כפות ידיים פונות לגוף.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וליבה מופעלת.","משכו קטלבל אחד למעלה לכיוון החזה, תוך שמירה על מרפק קרוב לגוף וכיווץ השכמות זו לזו.","הורידו את הקטלבל חזרה לנקודת ההתחלה וחזרו על התנועה עם היד השנייה.","המשיכו להחליף ידיים לסירוגין למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, колени слегка согнуты, в каждой руке держите по гире ладонями к телу.","Наклонитесь вперед в бедрах, сохраняя спину прямой и напряженный корпус.","Подтяните одну гирю к груди, держа локоть близко к телу и сжимая лопатки вместе.","Опустите гирю обратно в исходное положение и повторите то же самое с другой рукой.","Продолжайте чередовать руки желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y apretando los omóplatos entre sí.","Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."]}},{"id":"0523","name":"kettlebell arnold press","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0523-UM8mgyG.jpg","gif_url":"videos/0523-UM8mgyG.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל בכל יד בגובה הכתפיים עם כפות ידיים פונות אליכם.","הפעילו את הליבה ולחצו את הקטלבלים מעל הראש, תוך סיבוב כפות הידיים לפנים במהלך יישור הידיים.","עצרו בנקודה העליונה של התנועה, ואז הורידו את הקטלבלים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you.","Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms.","Pause at the top of the movement, then slowly lower the kettlebells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, держа в каждой руке по гире на уровне плеч ладонями к себе.","Напрягите корпус и выжмите гири над головой, поворачивая ладони лицом вперед и вытягивая руки.","Сделайте паузу в верхней точке движения, затем медленно опустите гири обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros con las palmas hacia ti.","Activa el core y empuja las pesas rusas por encima de la cabeza, girando las palmas hacia adelante mientras extiendes los brazos.","Haz una pausa en la parte superior del movimiento, luego baja lentamente las pesas rusas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0524","name":"kettlebell bent press","category":"waist","body_part":"waist","equipment":"kettlebell","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","obliques"],"target":"abs","image":"images/0524-kjE55n5.jpg","gif_url":"videos/0524-kjE55n5.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל ביד ימין.","כופפו ברכיים מעט ולחצו את הקטלבל מעל הראש עם יד ימין, תוך שמירה על מרפק נעול.","סובבו את הגו שמאלה, בהעברת המשקל לכף רגל שמאל.","כופפו את ברך שמאל והורידו את הגו לכיוון הרצפה, תוך שמירה על יד ימין מתוחה מעל הראש.","תוך כדי הירידה, שמרו על העיניים על הקטלבל והחזה מורם.","כשיד שמאל נוגעת ברצפה, דחפו דרך כף רגל שמאל ויישרו את רגל שמאל, בדחיפת הירכיים קדימה.","תוך דחיפת הירכיים קדימה, השתמשו בליבה וביד ימין ללחיצת הקטלבל חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.","Rotate your torso to the left, shifting your weight onto your left foot.","Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead.","As you lower, keep your eyes on the kettlebell and your chest lifted.","Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward.","As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, в правой руке держите гирю.","Слегка согните колени и нажмите гирю над головой правой рукой, держа локоть зафиксированным.","Поверните туловище влево, перенеся вес тела на левую ногу.","Согните левое колено и опустите туловище к земле, держа правую руку вытянутой над головой.","Опускаясь, следите за гирей, а грудь приподнимайте.","Как только ваша левая рука коснется земли, оттолкнитесь левой ступней и выпрямите левую ногу, направляя бедра вперед.","Когда вы двигаете бедрами вперед, используйте корпус и правую руку, чтобы вернуть гирю в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha.","Dobla ligeramente las rodillas y empuja la pesa rusa por encima de la cabeza con el brazo derecho, manteniendo el codo bloqueado.","Rota el torso hacia la izquierda, trasladando tu peso al pie izquierdo.","Flexiona la rodilla izquierda y baja el torso hacia el suelo, manteniendo el brazo derecho extendido por encima de la cabeza.","Mientras bajas, mantén la mirada en la pesa rusa y el pecho elevado.","Cuando tu mano izquierda toque el suelo, empuja con el pie izquierdo y estira la pierna izquierda, llevando las caderas hacia adelante.","Mientras llevas las caderas hacia adelante, usa el core y el brazo derecho para empujar la pesa rusa de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0525","name":"kettlebell bottoms up clean from the hang position","category":"upper arms","body_part":"upper arms","equipment":"kettlebell","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0525-4KJEpzb.jpg","gif_url":"videos/0525-4KJEpzb.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל ביד אחת באחיזה עליונה.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וחזה מורם.","תנו לקטלבל להשתלשל בין הרגליים, עם היד מתוחה לגמרי.","בתנועה רציפה אחת, יישרו ירכיים וברכיים בפיצוץ תוך משיכת הקטלבל למעלה לכיוון הכתף.","כשהקטלבל מגיע לגובה הכתף, סובבו את שורש כף היד כך שתחתית הקטלבל פונה כלפי מעלה.","תפסו את הקטלבל בגובה הכתף עם מרפק כפוף וכף יד כלפי מעלה.","הורידו את הקטלבל חזרה לנקודת ההתחלה בהיפוך התנועה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebell to hang down between your legs, with your arm fully extended.","In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up.","Catch the kettlebell at shoulder height with your elbow bent and your palm facing up.","Lower the kettlebell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, держите гирю в одной руке хватом сверху.","Слегка согните колени и наклонитесь вперед в бедрах, держа спину прямо и грудь вверх.","Позвольте гире свисать между ног, полностью вытянув руку.","Одним плавным движением резко выпрямите бедра и колени, одновременно подтягивая гирю к плечу.","Когда гиря достигнет уровня плеч, поверните запястье так, чтобы нижняя часть гири была обращена вверх.","Возьмите гирю на уровне плеч, согнув локоть и повернув ладонь вверх.","Опустите гирю обратно в исходное положение, выполняя движение в обратном направлении.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Deja que la pesa rusa cuelgue entre tus piernas, con el brazo completamente extendido.","En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras tiras de la pesa rusa hacia el hombro.","Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca de modo que la base de la pesa rusa quede hacia arriba.","Atrapa la pesa rusa a la altura del hombro con el codo flexionado y la palma hacia arriba.","Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0526","name":"kettlebell double alternating hang clean","category":"upper arms","body_part":"upper arms","equipment":"kettlebell","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0526-a4F9Oyc.jpg","gif_url":"videos/0526-a4F9Oyc.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל בכל יד באחיזה עליונה.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וחזה מורם.","תנו לקטלבלים להשתלשל ישר מטה מול הגוף.","בתנועה רציפה אחת, יישרו ירכיים וברכיים בפיצוץ תוך משיכת כתפיים.","כשהקטלבלים עולים, משכו אותם למעלה לכיוון הכתפיים, תוך שמירה על מרפקים גבוהים ופונים לצדדים.","תפסו את הקטלבלים בגובה הכתפיים, עם כפות ידיים פונות פנימה ומרפקים פונים קדימה.","הורידו את הקטלבלים חזרה לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang straight down in front of your body.","In one fluid motion, explosively extend your hips and knees while shrugging your shoulders.","As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides.","Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гире хватом сверху.","Слегка согните колени и наклонитесь вперед в бедрах, держа спину прямо и грудь вверх.","Позвольте гирям свисать прямо перед вашим телом.","Одним плавным движением резко выпрямите бедра и колени, одновременно пожимая плечами.","Когда гири поднимутся, подтяните их к плечам, держа локти высоко и в стороны.","Возьмите гири на уровне плеч, ладонями внутрь, а локтями вперед.","Опустите гири обратно в исходное положение и повторите желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Deja que las pesas rusas cuelguen rectas frente a tu cuerpo.","En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras encoges los hombros.","Mientras las pesas rusas suben, tira de ellas hacia los hombros, manteniendo los codos altos y hacia los lados.","Atrapa las pesas rusas a la altura del hombro, con las palmas hacia adentro y los codos apuntando hacia adelante.","Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"0527","name":"kettlebell double jerk","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0527-tznL2Ad.jpg","gif_url":"videos/0527-tznL2Ad.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל בכל יד בגובה הכתפיים.","כופפו ברכיים מעט והפעילו את הליבה.","לחצו את הקטלבלים מעל הראש, עד יישור מלא של הידיים.","כופפו ברכיים ורדו במהירות לסקוואט חלקי.","יישרו ירכיים וברכיים בפיצוץ, בדחיפת הקטלבלים מעל הראש.","נעלו את הידיים ותפסו את הקטלבלים מעל הראש עם ברכיים כפופות מעט.","עמדו זקוף וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebells overhead, fully extending your arms.","Bend your knees and quickly drop into a partial squat.","Explosively extend your hips and knees, driving the kettlebells overhead.","Lock out your arms and catch the kettlebells overhead with your knees slightly bent.","Stand up straight and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гире на уровне плеч.","Слегка согните колени и задействуйте корпус.","Жмите гири над головой, полностью выпрямляя руки.","Согните колени и быстро опуститесь в частичное приседание.","Резко выпрямите бедра и колени, поднимая гири над головой.","Выпрямите руки и поймайте гири над головой, слегка согнув колени.","Встаньте прямо и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros.","Flexiona ligeramente las rodillas y activa el core.","Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.","Flexiona las rodillas y baja rápidamente a una sentadilla parcial.","Extiende explosivamente las caderas y las rodillas, impulsando las pesas rusas hacia arriba.","Bloquea los brazos y atrapa las pesas rusas por encima de la cabeza con las rodillas ligeramente flexionadas.","Ponte de pie recto y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0528","name":"kettlebell double push press","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0528-I4KkPdl.jpg","gif_url":"videos/0528-I4KkPdl.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים, אוחזים קטלבל בכל יד בגובה הכתפיים.","כופפו ברכיים מעט והפעילו את הליבה.","התחילו את התנועה ביישור ירכיים, ברכיים וקרסוליים בפיצוץ, בדחיפת הקטלבלים מעל הראש.","כשהקטלבלים מגיעים לנקודה העליונה, לחצו אותם עד הסוף מעל הראש, בנעילת הידיים.","הורידו את הקטלבלים חזרה לנקודת ההתחלה בכיפוף המרפקים והחזרתם לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead.","As the kettlebells reach the top, press them fully overhead, locking out your arms.","Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч, держа в каждой руке по гире на уровне плеч.","Слегка согните колени и задействуйте корпус.","Начните движение, резко выпрямляя бедра, колени и лодыжки, поднимая гири над головой.","Когда гири достигнут верха, полностью выжмите их над головой, заблокировав руки.","Опустите гири обратно в исходное положение, согнув локти и вернув их на высоту плеч.","Повторите необходимое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro.","Flexiona ligeramente las rodillas y activa el core.","Inicia el movimiento extendiendo explosivamente las caderas, las rodillas y los tobillos, impulsando las pesas rusas por encima de la cabeza.","Cuando las pesas rusas lleguen arriba, presiónalas completamente por encima de la cabeza, bloqueando los brazos.","Baja las pesas rusas a la posición inicial flexionando los codos y llevándolas de vuelta a la altura del hombro.","Repite el número de repeticiones deseado."]}},{"id":"0529","name":"kettlebell double snatch","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"trapezius","secondary_muscles":["trapezius","forearms","core"],"target":"delts","image":"images/0529-M74kdvm.jpg","gif_url":"videos/0529-M74kdvm.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל בכל יד מול הירכיים בידיים מתוחות.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב שטוח וחזה מורם.","בתנועת פיצוץ אחת, יישרו ירכיים, ברכיים וקרסוליים, ובו-זמנית משכו את הקטלבלים למעלה לכיוון הכתפיים.","כשהקטלבלים מגיעים לגובה הכתפיים, סובבו את שורשי כף היד ודחפו אותם מעל הראש, עד יישור מלא של הידיים.","הורידו את הקטלבלים חזרה לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm's length in front of your thighs.","Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.","In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа гирю в каждой руке на расстоянии вытянутой руки перед бедрами.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину ровной и грудь поднятой.","Одним взрывным движением вытяните бедра, колени и лодыжки и одновременно подтяните гири к плечам.","Когда гири достигнут уровня плеч, поверните запястья и ударьте гирями над головой, полностью выпрямляя руки.","Опустите гири обратно в исходное положение и повторите желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano con el brazo extendido frente a los muslos.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","En un solo movimiento explosivo, extiende las caderas, las rodillas y los tobillos, y al mismo tiempo tira de las pesas rusas hacia los hombros.","Cuando las pesas rusas lleguen a la altura del hombro, rota las muñecas y lanza las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.","Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"0530","name":"kettlebell double windmill","category":"waist","body_part":"waist","equipment":"kettlebell","muscle_group":"shoulders","secondary_muscles":["shoulders","hamstrings"],"target":"abs","image":"images/0530-OaE7CpD.jpg","gif_url":"videos/0530-OaE7CpD.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל ביד ימין.","מתחו את יד ימין מעל הראש, תוך שמירה על העיניים על הקטלבל.","סובבו את כף רגל שמאל 45 מעלות שמאלה ואת כף רגל ימין 90 מעלות ימינה.","הטו את הגו שמאלה מהמותניים, תוך שמירה על יד ימין מתוחה מעל הראש.","הורידו את הקטלבל לכיוון הרצפה, בהושטה לכיוון כף רגל שמאל.","עצרו לרגע, ואז הפעילו את הליבה ודחפו דרך כף רגל ימין לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Extend your right arm overhead, keeping your eyes on the kettlebell.","Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right.","Bend at the waist to the left, keeping your right arm extended overhead.","Lower the kettlebell towards the ground, reaching towards your left foot.","Pause for a moment, then engage your core and push through your right foot to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, в правой руке держите гирю.","Вытяните правую руку над головой, не отрывая глаз от гири.","Поверните левую ногу на 45 градусов влево, а правую — на 90 градусов вправо.","Согнитесь в талии влево, удерживая правую руку вытянутой над головой.","Опустите гирю к земле, дотягиваясь до левой ноги.","Сделайте паузу на мгновение, затем задействуйте корпус и толкните правую ногу, чтобы вернуться в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha.","Extiende el brazo derecho por encima de la cabeza, manteniendo la mirada en la pesa rusa.","Rota el pie izquierdo 45 grados hacia la izquierda y el pie derecho 90 grados hacia la derecha.","Flexiona la cintura hacia la izquierda, manteniendo el brazo derecho extendido por encima de la cabeza.","Baja la pesa rusa hacia el suelo, extendiéndote hacia el pie izquierdo.","Haz una pausa breve, luego activa el core y empuja con el pie derecho para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0531","name":"kettlebell extended range one arm press on floor","category":"chest","body_part":"chest","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0531-rseLfH3.jpg","gif_url":"videos/0531-rseLfH3.gif","instruction_steps":{"he":["התחילו בשכיבה על הגב על הרצפה עם ברכיים כפופות וכפות רגליים על הרצפה.","החזיקו קטלבל ביד אחת, כשכף היד פונה לכיוון כפות הרגליים.","מתחו את היד ישר למעלה לכיוון התקרה, תוך שמירה על מרפק נעול ושורש כף יד ישר.","הורידו את הקטלבל באיטיות חזרה לנקודת ההתחלה, תוך שמירה על שליטה לאורך כל התנועה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in one hand, with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.","Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Начните с того, что лягте на спину на пол, согните колени и поставьте ступни на землю.","Возьмите гирю в одну руку ладонью к ногам.","Вытяните руку прямо вверх к потолку, сохраняя локоть зафиксированным, а запястье прямым.","Медленно опустите гирю обратно в исходное положение, сохраняя контроль на протяжении всего движения.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo.","Sujeta una pesa rusa con una mano, con la palma hacia los pies.","Extiende el brazo recto hacia el techo, manteniendo el codo bloqueado y la muñeca recta.","Baja lentamente la pesa rusa de vuelta a la posición inicial, manteniendo el control durante todo el movimiento.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0532","name":"kettlebell figure 8","category":"waist","body_part":"waist","equipment":"kettlebell","muscle_group":"shoulders","secondary_muscles":["shoulders","forearms"],"target":"abs","image":"images/0532-L4ay0PW.jpg","gif_url":"videos/0532-L4ay0PW.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל ביד אחת.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","העבירו את הקטלבל בין הרגליים, בהחלפת ידיים כשהוא מגיע לחלק האחורי של הרגליים.","כשהקטלבל נע קדימה, העבירו אותו ליד השנייה בין הרגליים.","המשיכו להעביר את הקטלבל בין הרגליים בתנועת 8.","שמרו על קצב אחיד והפעילו את הליבה לאורך כל התרגיל.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pass the kettlebell between your legs, switching hands as it reaches the back of your legs.","As the kettlebell comes forward, pass it to the other hand between your legs.","Continue passing the kettlebell between your legs in a figure 8 motion.","Maintain a steady pace and engage your core throughout the exercise.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, в одной руке держите гирю.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Пропустите гирю между ног, меняя руки, когда она достигает задней части ног.","Когда гиря выйдет вперед, передайте ее в другую руку между ног.","Продолжайте передавать гирю между ног, совершая движения в форме восьмерки.","Поддерживайте устойчивый темп и задействуйте мышцы корпуса на протяжении всего упражнения.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Pasa la pesa rusa entre las piernas, cambiándola de mano cuando llegue detrás de las piernas.","Cuando la pesa rusa vuelva hacia adelante, pásala a la otra mano entre las piernas.","Continúa pasando la pesa rusa entre las piernas con un movimiento en forma de ocho.","Mantén un ritmo constante y activa el core durante todo el ejercicio.","Repite el número de repeticiones deseado."]}},{"id":"0533","name":"kettlebell front squat","category":"upper legs","body_part":"upper legs","equipment":"kettlebell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0533-DB0n8AG.jpg","gif_url":"videos/0533-DB0n8AG.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, כפות הרגליים פונות מעט החוצה.","החזיקו את הקטלבל בשתי ידיים מול החזה, קרוב לגוף.","הפעילו את הליבה ושמרו על חזה מורם תוך הורדת האגן למטה ולאחור, כאילו אתם מתיישבים על כיסא.","רדו עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","דחפו דרך העקבים כדי לחזור לעמידה, וכווצו את הישבן בנקודה העליונה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the kettlebell with both hands in front of your chest, close to your body.","Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Держите гирю обеими руками перед грудью, близко к телу.","Напрягите корпус и держите грудь поднятой, опуская бедра вниз и назад, как будто вы садитесь на стул.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Протолкните пятки, чтобы встать, сжимая ягодицы вверху.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la pesa rusa con ambas manos frente al pecho, cerca del cuerpo.","Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta.","Repite el número de repeticiones deseado."]}},{"id":"0534","name":"kettlebell goblet squat","category":"upper legs","body_part":"upper legs","equipment":"kettlebell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0534-ZA8b5hc.jpg","gif_url":"videos/0534-ZA8b5hc.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים בקטלבל צמוד לחזה בשתי הידיים.","תוך שמירה על חזה מורם וליבה מופעלת, הורידו את הגוף לעמדת סקוואט בכיפוף ברכיים וירכיים.","המשיכו לרדת עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.","Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите гирю обеими руками близко к груди.","Удерживая грудь поднятой и напряженным корпус, опустите тело в присед, сгибая колени и бедра.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa cerca del pecho con ambas manos.","Manteniendo el pecho elevado y el core activado, baja el cuerpo a una posición de sentadilla flexionando las rodillas y las caderas.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0535","name":"kettlebell hang clean","category":"upper legs","body_part":"upper legs","equipment":"kettlebell","muscle_group":"glutes","secondary_muscles":["glutes","quadriceps","calves"],"target":"hamstrings","image":"images/0535-LHWF7us.jpg","gif_url":"videos/0535-LHWF7us.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל מול הירכיים.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","הורידו את הקטלבל לכיוון הרצפה, ותנו לו להתנדנד בין הרגליים.","יישרו ירכיים וברכיים במהירות, בעזרת התנופה להנפת הקטלבל לגובה הכתף.","כשהקטלבל מגיע לגובה הכתף, סובבו את שורשי כף היד ותפסו אותו בתנוחת ראק — מרפק צמוד והקטלבל מונח על האמה.","הורידו את הקטלבל חזרה לנקודת ההתחלה בין הרגליים, וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower the kettlebell towards the ground, allowing it to swing between your legs.","Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height.","As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm.","Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа гирю перед бедрами.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Опустите гирю к земле, позволяя ей покачиваться между ног.","Быстро выпрямите бедра и колени, используя инерцию, чтобы поднять гирю на высоту плеч.","Когда гиря достигнет уровня плеч, поверните запястья и поймайте гирю в положении стойки, прижав локоть к себе и положив гирю на предплечье.","Опустите гирю обратно в исходное положение между ног и повторите желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Baja la pesa rusa hacia el suelo, dejando que se balancee entre las piernas.","Extiende rápidamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro.","Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con el codo pegado al cuerpo y la pesa rusa apoyada en el antebrazo.","Baja la pesa rusa de vuelta a la posición inicial entre las piernas y repite el número de repeticiones deseado."]}},{"id":"0536","name":"kettlebell lunge pass through","category":"upper legs","body_part":"upper legs","equipment":"kettlebell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0536-WKMQzCD.jpg","gif_url":"videos/0536-WKMQzCD.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל מול החזה בשתי ידיים.","צעדו קדימה עם רגל ימין והורידו את הגוף לעמדת מספריים (לאנג').","תוך כדי המספריים קדימה, העבירו את הקטלבל מתחת לירך ימין ליד שמאל.","דחפו עם כף רגל ימין לחזרה לנקודת ההתחלה, ובו-זמנית העבירו את הקטלבל חזרה ליד ימין.","חזרו על המספריים בצד הנגדי, בהעברת הקטלבל מתחת לירך שמאל.","המשיכו להחליף מספריים ולהעביר את הקטלבל בין הידיים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand.","Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand.","Repeat the lunge on the opposite side, passing the kettlebell under your left thigh.","Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, удерживая гирю перед грудью обеими руками.","Сделайте шаг вперед правой ногой, опуская тело в положение выпада.","Делая выпад вперед, пропустите гирю под правое бедро и перенесите ее в левую руку.","Оттолкнитесь правой ногой, чтобы вернуться в исходное положение, одновременно передавая гирю обратно в правую руку.","Повторите выпад на противоположную сторону, проведя гирю под левым бедром.","Продолжайте чередовать выпады и передавать гирю между руками желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Mientras avanzas en la zancada, pasa la pesa rusa por debajo del muslo derecho y trasládala a la mano izquierda.","Empuja con el pie derecho para volver a la posición inicial, mientras pasas la pesa rusa de vuelta a la mano derecha al mismo tiempo.","Repite la zancada en el lado opuesto, pasando la pesa rusa por debajo del muslo izquierdo.","Continúa alternando zancadas y pasando la pesa rusa entre las manos durante el número de repeticiones deseado."]}},{"id":"0537","name":"kettlebell one arm clean and jerk","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0537-vzAxBtt.jpg","gif_url":"videos/0537-vzAxBtt.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל ביד אחת באחיזה עליונה.","כופפו ברכיים מעט והטו את הגו מהירכיים, בהורדת הקטלבל בין הרגליים.","יישרו ירכיים, ברכיים וקרסוליים בפיצוץ, בעזרת התנופה להנפת הקטלבל לגובה הכתף.","כשהקטלבל מגיע לגובה הכתף, סובבו את שורש כף היד ודחפו את היד ישר למעלה, בנעילת היד מעל הראש.","הורידו את הקטלבל חזרה לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.","Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height.","As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите гирю в одной руке хватом сверху.","Слегка согните колени и наклонитесь в бедрах, опуская гирю между ног.","Резко выпрямите бедра, колени и лодыжки, используя инерцию, чтобы поднять гирю на высоту плеч.","Когда гиря достигнет уровня плеч, поверните запястье и поднимите руку прямо вверх, зафиксировав руку над головой.","Опустите гирю обратно в исходное положение и повторите желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono.","Flexiona ligeramente las rodillas y inclínate desde las caderas, bajando la pesa rusa entre las piernas.","Extiende explosivamente las caderas, las rodillas y los tobillos, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro.","Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca y lanza la mano recta hacia arriba, bloqueando el brazo por encima de la cabeza.","Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"1298","name":"kettlebell one arm floor press","category":"chest","body_part":"chest","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1298-rg59QCH.jpg","gif_url":"videos/1298-rg59QCH.gif","instruction_steps":{"he":["שכבו על הגב על הרצפה עם ברכיים כפופות וכפות רגליים על הרצפה.","החזיקו את הקטלבל ביד אחת עם כף היד פונה לכיוון כפות הרגליים והיד מתוחה ישר למעלה לכיוון התקרה.","הורידו באיטיות את הקטלבל לכיוון החזה בכיפוף המרפק, תוך שמירה על הזרוע העליונה קרובה לגוף.","עצרו לרגע כשהקטלבל מעט מעל החזה, ואז דחפו אותו חזרה למעלה לנקודת ההתחלה ביישור המרפק.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling.","Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body.","Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Лягте на спину на пол, согните колени и поставьте ступни на землю.","Держите гирю в одной руке ладонью к ногам, а руку вытяните прямо к потолку.","Медленно опустите гирю к груди, согнув локоть, держа плечо близко к телу.","Сделайте паузу на мгновение, когда гиря окажется чуть выше груди, затем поднимите ее обратно в исходное положение, вытянув локоть.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.","Sujeta la pesa rusa con una mano con la palma hacia los pies y el brazo extendido recto hacia el techo.","Baja lentamente la pesa rusa hacia el pecho flexionando el codo, manteniendo el brazo superior cerca del cuerpo.","Haz una pausa cuando la pesa rusa esté justo encima del pecho, luego empújala de vuelta hacia arriba a la posición inicial extendiendo el codo.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0538","name":"kettlebell one arm jerk","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0538-S37C94C.jpg","gif_url":"videos/0538-S37C94C.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל ביד אחת בגובה הכתף.","כופפו ברכיים מעט והפעילו את הליבה.","לחצו את הקטלבל מעל הראש בקו ישר, עד יישור מלא של היד.","תוך כדי לחיצת הקטלבל מעל הראש, כופפו מעט ברכיים ויישרו אותן במהירות ליצירת תנופה.","כשהקטלבל מגיע לנקודה הגבוהה ביותר, רדו מתחתיו במהירות בכיפוף ברכיים וירכיים.","תפסו את הקטלבל עם כיפוף קל בברכיים ובירכיים, והיד מתוחה לגמרי מעל הראש.","עמדו זקוף, ביישור מלא של הברכיים והירכיים, וייצבו את הקטלבל מעל הראש.","הורידו את הקטלבל חזרה לנקודת ההתחלה בכיפוף ברכיים וירכיים, וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebell overhead in a straight line, fully extending your arm.","As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum.","As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips.","Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead.","Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead.","Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа гирю в одной руке на уровне плеч.","Слегка согните колени и задействуйте корпус.","Выжмите гирю над головой по прямой линии, полностью выпрямляя руку.","Жмя гирю над головой, одновременно опускайте колени и быстро выпрямляйте их, чтобы создать импульс.","Когда гиря достигнет высшей точки, быстро опуститесь под нее, согнув колени и бедра.","Возьмите гирю, слегка согнув колени и бедра и полностью вытянув руку над головой.","Встаньте прямо, полностью выпрямив колени и бедра, и зафиксируйте гирю над головой.","Опустите гирю обратно в исходное положение, сгибая колени и бедра, и повторите желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro.","Flexiona ligeramente las rodillas y activa el core.","Presiona la pesa rusa por encima de la cabeza en línea recta, extendiendo el brazo por completo.","Mientras presionas la pesa rusa por encima de la cabeza, flexiona las rodillas simultáneamente y estíralas rápidamente para generar impulso.","Cuando la pesa rusa llegue a su punto más alto, baja rápidamente por debajo de ella flexionando las rodillas y las caderas.","Atrapa la pesa rusa con una ligera flexión de rodillas y caderas, y el brazo completamente extendido por encima de la cabeza.","Ponte de pie recto, extendiendo por completo las rodillas y las caderas, y estabiliza la pesa rusa por encima de la cabeza.","Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y las caderas, y repite el número de repeticiones deseado."]}},{"id":"0539","name":"kettlebell one arm military press to the side","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0539-yCvYdi7.jpg","gif_url":"videos/0539-yCvYdi7.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל ביד אחת בגובה הכתף.","הפעילו את הליבה ושמרו על גב ישר.","לחצו את הקטלבל מעל הראש, עד יישור מלא של היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את הקטלבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Engage your core and keep your back straight.","Press the kettlebell overhead, extending your arm fully.","Pause for a moment at the top, then slowly lower the kettlebell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, держа гирю в одной руке на уровне плеч.","Напрягите корпус и держите спину прямо.","Жмите гирю над головой, полностью выпрямляя руку.","Задержитесь на мгновение в верхней точке, затем медленно опустите гирю обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro.","Activa el core y mantén la espalda recta.","Presiona la pesa rusa por encima de la cabeza, extendiendo el brazo por completo.","Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0540","name":"kettlebell one arm push press","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0540-osdXT3K.jpg","gif_url":"videos/0540-osdXT3K.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל ביד אחת בגובה הכתף.","כופפו ברכיים מעט והפעילו את הליבה.","לחצו את הקטלבל מעל הראש ביישור היד ויישור מלא של הרגליים.","הורידו את הקטלבל חזרה לנקודת ההתחלה בכיפוף ברכיים והחזרתו לכתף.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level.","Bend your knees slightly and engage your core.","Press the kettlebell overhead by extending your arm and fully extending your legs.","Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, держа гирю в одной руке на уровне плеч.","Слегка согните колени и задействуйте корпус.","Нажмите гирю над головой, вытянув руку и полностью вытянув ноги.","Опустите гирю обратно в исходное положение, согнув колени и вернув гирю на плечо.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro.","Flexiona ligeramente las rodillas y activa el core.","Presiona la pesa rusa por encima de la cabeza extendiendo el brazo y estirando por completo las piernas.","Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y devolviendo la pesa rusa al hombro.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0541","name":"kettlebell one arm row","category":"back","body_part":"back","equipment":"kettlebell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0541-g9AsZ8P.jpg","gif_url":"videos/0541-g9AsZ8P.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל ביד אחת באחיזה עליונה.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וליבה מופעלת.","משכו את הקטלבל למעלה לכיוון החזה, תוך שמירה על מרפק קרוב לגוף וכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את הקטלבל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד וחזרו עם היד השנייה."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."],"ru":["Встаньте, ноги на ширине плеч, держите гирю в одной руке хватом сверху.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой и напряженный корпус.","Подтяните гирю к груди, держа локоть близко к телу и сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите гирю обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону и повторите с другой рукой."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Tira de la pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.","Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo."]}},{"id":"0542","name":"kettlebell one arm snatch","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"trapezius","secondary_muscles":["trapezius","forearms","core"],"target":"delts","image":"images/0542-aXcUyKb.jpg","gif_url":"videos/0542-aXcUyKb.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל ביד אחת בין הרגליים.","כופפו ברכיים מעט והטו את הגו מהירכיים, בהורדת הקטלבל לכיוון הרצפה.","יישרו ירכיים וברכיים בפיצוץ, בעזרת התנופה להנפת הקטלבל למעלה לכיוון הכתף.","כשהקטלבל מגיע לגובה הכתף, סובבו את היד ודחפו אותו ישר מעל הראש, עד יישור מלא של היד.","הורידו את הקטלבל חזרה בין הרגליים וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm.","Lower the kettlebell back down between your legs and repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа гирю в одной руке между ног.","Слегка согните колени и наклонитесь в бедрах, опуская гирю к земле.","Резко выпрямите бедра и колени, используя инерцию, чтобы подвести гирю к плечу.","Когда гиря достигнет уровня плеч, поверните руку и ударьте ее прямо над головой, полностью выпрямляя руку.","Опустите гирю обратно между ног и повторите желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano entre las piernas.","Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo.","Extiende explosivamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hacia el hombro.","Cuando la pesa rusa llegue a la altura del hombro, rota la mano y lánzala recta hacia arriba por encima de la cabeza, extendiendo el brazo por completo.","Baja la pesa rusa de vuelta entre las piernas y repite el número de repeticiones deseado."]}},{"id":"0543","name":"kettlebell pirate supper legs","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","forearms"],"target":"delts","image":"images/0543-kuXhl0o.jpg","gif_url":"videos/0543-kuXhl0o.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל ביד אחת.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","הרימו את הקטלבל לגובה הכתף, תוך שמירה על מרפק קרוב לגוף.","מתחו את היד לגמרי מעל הראש, ביישור המרפק.","הורידו את הקטלבל חזרה לגובה הכתף, ואז חזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the kettlebell up to shoulder height, keeping your elbow close to your body.","Extend your arm fully overhead, straightening your elbow.","Lower the kettlebell back down to shoulder height, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, в одной руке держите гирю.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Поднимите гирю до уровня плеч, держа локоть близко к телу.","Вытяните руку полностью над головой, выпрямляя локоть.","Опустите гирю обратно на высоту плеч, затем вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Levanta la pesa rusa hasta la altura del hombro, manteniendo el codo cerca del cuerpo.","Extiende el brazo por completo por encima de la cabeza, enderezando el codo.","Baja la pesa rusa de vuelta a la altura del hombro, luego vuelve a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0544","name":"kettlebell pistol squat","category":"upper legs","body_part":"upper legs","equipment":"kettlebell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0544-5bpPTHv.jpg","gif_url":"videos/0544-5bpPTHv.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל מול החזה בשתי ידיים.","הרימו את כף רגל שמאל מהרצפה ומתחו אותה קדימה, מקבילה לרצפה.","הורידו את הגוף באיטיות לעמדת סקוואט, תוך שמירה על כף רגל ימין שטוחה על הרצפה ורגל שמאל מתוחה.","עצרו לרגע בנקודה התחתונה של הסקוואט, ואז דחפו דרך עקב ימין לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Lift your left foot off the ground and extend it forward, keeping it parallel to the ground.","Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended.","Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Встаньте, ноги на ширине плеч, удерживая гирю перед грудью обеими руками.","Поднимите левую ногу от земли и вытяните ее вперед, удерживая параллельно земле.","Медленно опустите тело в положение приседа, удерживая правую ногу на земле, а левую ногу вытянув.","Задержитесь на мгновение в нижней части приседа, затем оттолкнитесь правой пяткой, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos.","Levanta el pie izquierdo del suelo y extiéndelo hacia adelante, manteniéndolo paralelo al suelo.","Baja lentamente el cuerpo a una posición de sentadilla, manteniendo el pie derecho plano en el suelo y la pierna izquierda extendida.","Haz una pausa breve en la parte baja de la sentadilla, luego empuja con el talón derecho para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"0545","name":"kettlebell plyo push-up","category":"chest","body_part":"chest","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0545-ktf3nvW.jpg","gif_url":"videos/0545-ktf3nvW.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם הידיים על הקטלבלים, ברוחב כתפיים.","הורידו את החזה לכיוון הרצפה, תוך שמירה על מרפקים קרובים לגוף.","דחפו דרך הידיים בפיצוץ, בהרמת הידיים מהקטלבלים ויישורן המלא.","נחתו ברכות חזרה על הקטלבלים והורידו מיד את החזה מטה לחזרה הבאה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands on the kettlebells, shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully.","Land softly back on the kettlebells and immediately lower your chest back down for the next repetition.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, положив руки на гири на ширине плеч.","Опустите грудь к земле, держа локти близко к телу.","Резко оттолкнитесь руками, отрывая руки от гири и полностью выпрямляя руки.","Мягко приземлитесь на гири и сразу же опустите грудь вниз для следующего повторения.","Повторите необходимое количество повторений."],"es":["Comienza en una posición de plancha alta con las manos sobre las pesas rusas, separadas a la altura de los hombros.","Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.","Empuja con las manos de forma explosiva, levantándolas de las pesas rusas y extendiendo los brazos por completo.","Aterriza suavemente sobre las pesas rusas y baja el pecho de inmediato para la siguiente repetición.","Repite el número de repeticiones deseado."]}},{"id":"0546","name":"kettlebell seated press","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0546-BkxB8LW.jpg","gif_url":"videos/0546-BkxB8LW.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו קטלבל בכל יד בגובה הכתפיים, כפות ידיים פונות קדימה.","לחצו את הקטלבלים מעל הראש, עד יישור מלא של הידיים.","הורידו את הקטלבלים חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a kettlebell in each hand at shoulder height, palms facing forward.","Press the kettlebells overhead, fully extending your arms.","Lower the kettlebells back to shoulder height.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Держите гирю в каждой руке на уровне плеч, ладонями вперед.","Жмите гири над головой, полностью выпрямляя руки.","Опустите гири обратно на высоту плеч.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una pesa rusa en cada mano a la altura del hombro, con las palmas hacia adelante.","Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.","Baja las pesas rusas de vuelta a la altura del hombro.","Repite el número de repeticiones deseado."]}},{"id":"1438","name":"kettlebell seated two arm military press","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/1438-ZEkjZDi.jpg","gif_url":"videos/1438-ZEkjZDi.gif","instruction_steps":{"he":["שבו על ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו קטלבל בכל יד בגובה הכתפיים, עם כפות ידיים פונות קדימה.","לחצו את הקטלבלים מעל הראש ביישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הקטלבלים באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a kettlebell in each hand at shoulder level with your palms facing forward.","Press the kettlebells overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Держите гирю в каждой руке на уровне плеч ладонями вперед.","Выжмите гири над головой, полностью выпрямив руки.","Задержитесь на мгновение в верхней точке, затем медленно опустите гири обратно на уровень плеч.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante.","Presiona las pesas rusas por encima de la cabeza extendiendo los brazos por completo.","Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la altura del hombro.","Repite el número de repeticiones deseado."]}},{"id":"0547","name":"kettlebell seesaw press","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0547-UDm6cGl.jpg","gif_url":"videos/0547-UDm6cGl.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל בכל יד בגובה הכתפיים.","לחצו קטלבל אחד מעל הראש, תוך שמירה על הקטלבל השני בגובה הכתף.","הורידו את הקטלבל שנלחץ חזרה לגובה הכתף ובו-זמנית לחצו את הקטלבל השני מעל הראש.","המשיכו להחליף את תנועת הלחיצה, ביצירת תנועת נדנדה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Press one kettlebell overhead while keeping the other kettlebell at shoulder height.","Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead.","Continue alternating the pressing motion, creating a seesaw-like movement.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гире на уровне плеч.","Выжмите одну гирю над головой, удерживая другую гирю на уровне плеч.","Опустите отжатую гирю обратно на высоту плеч, одновременно выжимая другую гирю над головой.","Продолжайте чередовать нажимающие движения, создавая движение, напоминающее качели.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros.","Presiona una pesa rusa por encima de la cabeza mientras mantienes la otra pesa rusa a la altura del hombro.","Baja la pesa rusa presionada de vuelta a la altura del hombro mientras presionas simultáneamente la otra pesa rusa por encima de la cabeza.","Continúa alternando el movimiento de presión, creando un movimiento similar a un balancín.","Repite el número de repeticiones deseado."]}},{"id":"0548","name":"kettlebell sumo high pull","category":"back","body_part":"back","equipment":"kettlebell","muscle_group":"shoulders","secondary_muscles":["shoulders","glutes","hamstrings"],"target":"traps","image":"images/0548-8ARQ9Hw.jpg","gif_url":"videos/0548-8ARQ9Hw.gif","instruction_steps":{"he":["עמדו עם רגליים רחבות מרוחב הכתפיים, קצות האצבעות של הרגליים פונות החוצה.","החזיקו קטלבל בשתי ידיים מול הגוף, עם ידיים מתוחות כלפי מטה.","כופפו ברכיים והורידו את האגן לעמדת סקוואט, תוך שמירה על גב ישר.","דחפו דרך העקבים ויישרו ירכיים וברכיים בפיצוץ, במשיכת הקטלבל למעלה לכיוון הסנטר.","תוך כדי משיכת הקטלבל למעלה, שמרו על מרפקים גבוהים ורחבים, וכווצו את השכמות זו לזו.","הורידו את הקטלבל חזרה לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Hold a kettlebell with both hands in front of your body, arms extended downwards.","Bend your knees and lower your hips into a squat position, keeping your back straight.","Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin.","As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."],"ru":["Встаньте, расставив ноги шире плеч, носки наружу.","Держите гирю обеими руками перед телом, руки вытянуты вниз.","Согните ноги в коленях и опустите бедра в положение приседа, сохраняя спину прямой.","Проведите пятками и резко выпрямите бедра и колени, подтягивая гирю к подбородку.","Подтягивая гирю вверх, держите локти высоко и широко, а лопатки сведите вместе.","Опустите гирю обратно в исходное положение и повторите желаемое количество повторений."],"es":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera.","Sujeta una pesa rusa con ambas manos frente al cuerpo, con los brazos extendidos hacia abajo.","Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta.","Empuja con los talones y extiende explosivamente las caderas y las rodillas, tirando de la pesa rusa hacia la barbilla.","Mientras tiras de la pesa rusa hacia arriba, mantén los codos altos y abiertos, y junta los omóplatos.","Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"0549","name":"kettlebell swing","category":"upper legs","body_part":"upper legs","equipment":"kettlebell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","core"],"target":"glutes","image":"images/0549-UHJlbu3.jpg","gif_url":"videos/0549-UHJlbu3.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, קצות האצבעות פונות מעט החוצה.","החזיקו את הקטלבל בשתי ידיים מול הגוף, עם ידיים מתוחות.","כופפו ברכיים מעט והטו את הגו מהירכיים, בדחיפת הישבן לאחור.","הניפו את הקטלבל לאחור בין הרגליים, תוך שמירה על ידיים ישרות וגב שטוח.","דחפו את הירכיים קדימה והניפו את הקטלבל לגובה הכתפיים, בעזרת התנופה שנוצרת מהירכיים.","תנו לקטלבל להתנדנד חזרה בין הרגליים וחזרו על התנועה למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, toes pointed slightly outward.","Hold the kettlebell with both hands in front of your body, arms extended.","Bend your knees slightly and hinge at the hips, pushing your butt back.","Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back.","Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips.","Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","Держите гирю обеими руками перед телом, руки вытянуты.","Слегка согните колени и наклонитесь в бедрах, отводя ягодицы назад.","Поверните гирю назад между ног, держа руки прямыми и сохраняя ровную спину.","Поднимите бедра вперед и поднимите гирю на высоту плеч, используя инерцию, создаваемую бедрами.","Позвольте гире опуститься между ног и повторите движение желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la pesa rusa con ambas manos frente al cuerpo, con los brazos extendidos.","Flexiona ligeramente las rodillas e inclínate desde las caderas, empujando los glúteos hacia atrás.","Lleva la pesa rusa hacia atrás entre las piernas, manteniendo los brazos rectos y la espalda plana.","Lleva las caderas hacia adelante y haz que la pesa rusa suba hasta la altura del hombro, usando el impulso generado por las caderas.","Deja que la pesa rusa se balancee de vuelta hacia abajo entre las piernas y repite el movimiento el número de repeticiones deseado."]}},{"id":"0550","name":"kettlebell thruster","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","glutes","core"],"target":"delts","image":"images/0550-yWxMvB5.jpg","gif_url":"videos/0550-yWxMvB5.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים, אוחזים קטלבל מול החזה בשתי ידיים, כפות ידיים פונות זו לזו.","רדו לעמדת סקוואט בכיפוף ברכיים ודחיפת האגן לאחור, תוך שמירה על חזה מורם וגב ישר.","בהגיעכם לנקודה התחתונה של הסקוואט, דחפו בפיצוץ דרך העקבים לעמידה, ובו-זמנית לחצו את הקטלבל מעל הראש.","נעלו את הידיים בנקודה העליונה של התנועה, ביישור מלא של המרפקים.","הורידו את הקטלבל חזרה לנקודת ההתחלה בהיפוך התנועה, בכיפוף המרפקים והחזרת המשקל לחזה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other.","Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.","As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead.","Lock out your arms at the top of the movement, fully extending your elbows.","Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч, держа гирю перед грудью обеими руками, ладони обращены друг к другу.","Опуститесь в присед, согнув колени и отведя бедра назад, сохраняя грудь поднятой, а спину прямой.","Достигнув нижней точки приседа, резко поднимите пятки, чтобы встать, одновременно нажимая гирю над головой.","Зафиксируйте руки в верхней точке движения, полностью разгибая локти.","Опустите гирю обратно в исходное положение, изменив движение, согнув локти и опустив вес обратно на грудь.","Повторите необходимое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos, con las palmas una frente a la otra.","Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás, manteniendo el pecho elevado y la espalda recta.","Al llegar a la parte baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando al mismo tiempo la pesa rusa por encima de la cabeza.","Bloquea los brazos en la parte alta del movimiento, extendiendo los codos por completo.","Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento, flexionando los codos y bajando el peso de vuelta al pecho.","Repite el número de repeticiones deseado."]}},{"id":"0551","name":"kettlebell turkish get up (squat style)","category":"upper legs","body_part":"upper legs","equipment":"kettlebell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","core"],"target":"glutes","image":"images/0551-Ha7SZ3y.jpg","gif_url":"videos/0551-Ha7SZ3y.gif","instruction_steps":{"he":["התחילו בשכיבה על הגב עם רגליים מתוחות והקטלבל ביד ימין, עם היד מתוחה לגמרי מעל הכתף.","כופפו את ברך ימין והניחו את כף רגל ימין שטוחה על הרצפה, תוך שמירה על רגל שמאל מתוחה.","בדחיפה דרך כף רגל ימין, הרימו את האגן מהרצפה, למעבר לתנוחת גשר.","החליקו את רגל שמאל מתחת לגוף, בכיפוף ברך שמאל והנחת כף רגל שמאל שטוחה על הרצפה.","סובבו את הגו שמאלה, בהבאת יד שמאל לרצפה לתמיכה.","בדחיפה דרך כף רגל ימין ויד שמאל, הרימו את הגו מהרצפה, למעבר לתנוחת כריעה.","מתנוחת הכריעה, עמדו, תוך שמירה על הקטלבל מתוח מעל הראש.","הפכו את התנועה לחזרה לנקודת ההתחלה.","חזרו על התרגיל בצד השני, בהתחלה עם הקטלבל ביד שמאל."],"en":["Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder.","Bend your right knee and place your right foot flat on the ground, keeping your left leg extended.","Pressing through your right foot, lift your hips off the ground, coming into a bridge position.","Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground.","Rotate your torso to the left, bringing your left hand to the ground for support.","Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position.","From the kneeling position, stand up, keeping the kettlebell extended overhead.","Reverse the movement to return to the starting position.","Repeat the exercise on the other side, starting with the kettlebell in your left hand."],"ru":["Начните с того, что лягте на спину, вытянув ноги и держа гирю в правой руке, рука полностью вытянута над плечом.","Согните правое колено и поставьте правую ступню на землю, сохраняя левую ногу вытянутой.","Нажимая правой ногой, поднимите бедра от земли, приняв положение мостика.","Подведите левую ногу под тело, согнув левое колено и поставив левую ступню на землю.","Поверните туловище влево, опустив левую руку на землю для поддержки.","Опираясь на правую ногу и левую руку, поднимите туловище от земли и встаньте на колени.","Из положения стоя на коленях встаньте, держа гирю вытянутой над головой.","Выполните обратное движение, чтобы вернуться в исходное положение.","Повторите упражнение в другую сторону, начиная с гири в левой руке."],"es":["Comienza tumbado boca arriba con las piernas extendidas y la pesa rusa sostenida en la mano derecha, con el brazo completamente extendido por encima del hombro.","Flexiona la rodilla derecha y coloca el pie derecho plano en el suelo, manteniendo la pierna izquierda extendida.","Presionando con el pie derecho, levanta las caderas del suelo, llegando a una posición de puente.","Desliza la pierna izquierda por debajo del cuerpo, flexionando la rodilla izquierda y colocando el pie izquierdo plano en el suelo.","Rota el torso hacia la izquierda, llevando la mano izquierda al suelo como apoyo.","Presionando con el pie derecho y la mano izquierda, levanta el torso del suelo, llegando a una posición de rodillas.","Desde la posición de rodillas, ponte de pie, manteniendo la pesa rusa extendida por encima de la cabeza.","Invierte el movimiento para volver a la posición inicial.","Repite el ejercicio en el otro lado, comenzando con la pesa rusa en la mano izquierda."]}},{"id":"0552","name":"kettlebell two arm clean","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"traps","secondary_muscles":["traps","forearms"],"target":"delts","image":"images/0552-7Ba7bQ2.jpg","gif_url":"videos/0552-7Ba7bQ2.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל מול הירכיים בשתי ידיים, כפות ידיים פונות אליכם.","כופפו ברכיים מעט והטו את הגו מהירכיים, בהורדת הקטלבל לכיוון הרצפה.","יישרו ירכיים וברכיים בפיצוץ, בעזרת התנופה למשיכת הקטלבל למעלה לכיוון הכתפיים.","כשהקטלבל מגיע לגובה הכתף, סובבו את שורשי כף היד ותפסו את הקטלבל בתנוחת ראק — מרפקים צמודים והקטלבל מונח על גב האמה.","הורידו את הקטלבל חזרה לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders.","As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите гирю перед бедрами обеими руками, ладонями к себе.","Слегка согните колени и наклонитесь в бедрах, опуская гирю к земле.","Резко выпрямите бедра и колени, используя инерцию, чтобы подтянуть гирю к плечам.","Когда гиря достигнет уровня плеч, поверните запястья и поймайте гирю в стойке, согнув локти и положив гирю на тыльную сторону предплечья.","Опустите гирю обратно в исходное положение и повторите желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos con ambas manos, con las palmas hacia ti.","Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo.","Extiende explosivamente las caderas y las rodillas, usando el impulso para tirar de la pesa rusa hacia los hombros.","Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con los codos pegados al cuerpo y la pesa rusa apoyada en la parte posterior del antebrazo.","Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"0553","name":"kettlebell two arm military press","category":"shoulders","body_part":"shoulders","equipment":"kettlebell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0553-blBXysN.jpg","gif_url":"videos/0553-blBXysN.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל בכל יד בגובה הכתפיים עם כפות ידיים פונות קדימה.","הפעילו את הליבה ולחצו את הקטלבלים מעל הראש, עד יישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הקטלבלים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward.","Engage your core and press the kettlebells overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the kettlebells back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, держа в каждой руке по гире на уровне плеч ладонями вперед.","Напрягите корпус и выжмите гири над головой, полностью выпрямляя руки.","Задержитесь на мгновение в верхней точке, затем медленно опустите гири обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante.","Activa el core y presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.","Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1345","name":"kettlebell two arm row","category":"back","body_part":"back","equipment":"kettlebell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1345-wf24o8S.jpg","gif_url":"videos/1345-wf24o8S.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, ברכיים כפופות מעט, ואחזו קטלבל בכל יד עם כפות ידיים פונות לגוף.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וליבה מופעלת.","משכו את הקטלבלים למעלה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את הקטלבלים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, колени слегка согнуты, в каждой руке держите по гире ладонями к телу.","Наклонитесь вперед в бедрах, сохраняя спину прямой и напряженный корпус.","Подтяните гири к груди, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите гири обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Tira de las pesas rusas hacia el pecho, juntando los omóplatos.","Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0554","name":"kettlebell windmill","category":"waist","body_part":"waist","equipment":"kettlebell","muscle_group":"obliques","secondary_muscles":["obliques","shoulders"],"target":"abs","image":"images/0554-9Tkqa9O.jpg","gif_url":"videos/0554-9Tkqa9O.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים קטלבל ביד ימין מעל הראש.","סובבו את כף רגל שמאל החוצה בכ-45 מעלות ושמרו על כף רגל ימין פונה קדימה.","הטו את הגו שמאלה, תוך שמירה על יד ימין מתוחה מעל הראש והעיניים על הקטלבל.","הורידו את הגו רחוק ככל האפשר, תוך שמירה על יד ימין ישרה ויד שמאל מתוחה הצידה.","עצרו לרגע, ואז חזרו לנקודת ההתחלה בדחיפה דרך כף רגל ימין והפעלת האלכסונים.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead.","Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.","Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell.","Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side.","Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Встаньте, ноги на ширине плеч, держа гирю в правой руке над головой.","Поверните левую ногу наружу примерно на 45 градусов и держите правую ногу направленной вперед.","Наклоните туловище в левую сторону, держа правую руку вытянутой над головой и глядя на гирю.","Опустите туловище как можно ниже, сохраняя правую руку прямой, а левую — вытянутой в сторону.","Сделайте паузу на мгновение, затем вернитесь в исходное положение, отталкивая правую ногу и задействуя косые мышцы живота.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en la mano derecha por encima de la cabeza.","Rota el pie izquierdo hacia afuera unos 45 grados y mantén el pie derecho apuntando hacia adelante.","Inclina el torso hacia el lado izquierdo, manteniendo el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa.","Baja el torso tanto como puedas mientras mantienes el brazo derecho recto y el brazo izquierdo extendido hacia el lado.","Haz una pausa breve, luego vuelve a la posición inicial empujando con el pie derecho y activando los oblicuos.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0555","name":"kick out sit","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","glutes"],"target":"hamstrings","image":"images/0555-v7p5bYl.jpg","gif_url":"videos/0555-v7p5bYl.gif","instruction_steps":{"he":["שבו על קצה ספסל או כיסא עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","היטו את הגוף מעט לאחור והניחו את הידיים על קצה הספסל או הכיסא לתמיכה.","תוך הפעלת הירך האחורית, הרימו את כפות הרגליים מהרצפה ומתחו את הרגליים ישר לפניכם.","עצרו לרגע בנקודה העליונה, ואז כופפו באיטיות ברכיים והחזירו את כפות הרגליים לכיוון הגוף.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.","Lean back slightly and place your hands on the edge of the bench or chair for support.","Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you.","Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body.","Repeat for the desired number of repetitions."],"ru":["Сядьте на край скамьи или стула, поставьте ступни на землю и согните колени под углом 90 градусов.","Слегка откиньтесь назад и положите руки на край скамьи или стула для поддержки.","Задействуя мышцы задней поверхности бедра, оторвите ступни от земли и вытяните ноги прямо перед собой.","Задержитесь на мгновение в верхней точке, затем медленно согните колени и верните ступни назад к телу.","Повторите необходимое количество повторений."],"es":["Siéntate en el borde de un banco o una silla con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Inclínate ligeramente hacia atrás y coloca las manos en el borde del banco o la silla como apoyo.","Activando los isquiotibiales, levanta los pies del suelo y extiende las piernas rectas hacia adelante.","Haz una pausa breve en lo alto, luego flexiona lentamente las rodillas y lleva los pies de vuelta hacia el cuerpo.","Repite el número de repeticiones deseado."]}},{"id":"0558","name":"kipping muscle up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","triceps","shoulders","core"],"target":"lats","image":"images/0558-pM07UxU.jpg","gif_url":"videos/0558-pM07UxU.gif","instruction_steps":{"he":["התחילו בתלייה על מוט מתח באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","הפעילו את הליבה והשתמשו בתנועת נדנוד ליצירת תנופה.","בתנופה קדימה, משכו את החזה לכיוון המוט, בעזרת רחב הגבי והבייספס להתחלת התנועה.","המשיכו בתנועה כלפי מעלה עד שהחזה מגיע למוט, ואז עברו לתנוחת דיפ בדחיפה על המוט ויישור הידיים.","הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה בכיפוף הידיים ובשליטה על הירידה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and use a swinging motion to generate momentum.","As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement.","Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms.","Lower yourself back down to the starting position by bending your arms and controlling the descent.","Repeat for the desired number of repetitions."],"ru":["Начните с подвешивания на перекладине хватом сверху, руки чуть шире плеч.","напрягите мышцы кора ​​и используйте раскачивающие движения, чтобы создать импульс.","Делая поворот вперед, подтяните грудь к перекладине, используя широчайшие и бицепсы, чтобы начать движение.","Продолжайте движение вверх, пока ваша грудь не достигнет перекладины, затем перейдите в положение для отжиманий, надавив на перекладину вниз и вытянув руки.","Опуститесь обратно в исходное положение, сгибая руки и контролируя опускание.","Повторите необходимое количество повторений."],"es":["Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Activa el core y usa un movimiento de balanceo para generar impulso.","Mientras te balanceas hacia adelante, tira del pecho hacia la barra, usando los dorsales y los bíceps para iniciar el movimiento.","Continúa el movimiento ascendente hasta que el pecho llegue a la barra, luego pasa a una posición de fondos empujando hacia abajo en la barra y extendiendo los brazos.","Bájate de vuelta a la posición inicial flexionando los brazos y controlando el descenso.","Repite el número de repeticiones deseado."]}},{"id":"3640","name":"knee touch crunch","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3640-dTg95eZ.jpg","gif_url":"videos/3640-dTg95eZ.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו את השכמות מהרצפה ומתחו את יד ימין לכיוון ברך שמאל.","חזרו לנקודת ההתחלה וחזרו על התנועה, הפעם במתיחת יד שמאל לכיוון ברך ימין.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee.","Return to the starting position and repeat, this time reaching your left hand towards your right knee.","Continue alternating sides for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, поднимите лопатки от земли и протяните правую руку к левому колену.","Вернитесь в исходное положение и повторите, на этот раз дотянув левую руку до правого колена.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta los omóplatos del suelo y extiende la mano derecha hacia la rodilla izquierda.","Vuelve a la posición inicial y repite, esta vez extendiendo la mano izquierda hacia la rodilla derecha.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1420","name":"kneeling jump squat","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1420-UgDm3oy.jpg","gif_url":"videos/1420-UgDm3oy.gif","instruction_steps":{"he":["התחילו בכריעה על הרצפה עם רגליים ברוחב אגן וקצות האצבעות פונות קדימה.","הניחו מוט על הגב העליון, מונח על הכתפיים.","הפעילו את הליבה והישבן, ואז קפצו בפיצוץ לאוויר, ביישור הירכיים והברכיים.","תוך כדי הקפיצה, דחפו דרך קצות האצבעות ויישרו לגמרי קרסוליים, ברכיים וירכיים.","נחתו ברכות חזרה על הרצפה, בכיפוף ברכיים לבלימת הנחיתה.","עברו מיד לחזרה הבאה, בחזרה על תנועת קפיצת הסקוואט."],"en":["Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward.","Hold a barbell across your upper back, resting it on your shoulders.","Engage your core and glutes, then explosively jump up into the air, extending your hips and knees.","As you jump, push through your toes and fully extend your ankles, knees, and hips.","Land softly back on the ground, bending your knees to absorb the impact.","Immediately go into the next repetition, repeating the jump squat motion."],"ru":["Начните с того, что встаньте на колени на землю, поставив ноги на ширине плеч и направив пальцы ног вперед.","Держите штангу через верхнюю часть спины, положив ее на плечи.","Задействуйте корпус и ягодицы, затем резко подпрыгните в воздух, выпрямляя бедра и колени.","Во время прыжка надавите на пальцы ног и полностью выпрямите лодыжки, колени и бедра.","Мягко приземлитесь на землю, согнув колени, чтобы поглотить удар.","Сразу же переходите к следующему повторению, повторяя движение приседа с выпрыгиванием."],"es":["Comienza arrodillado en el suelo con los pies separados a la altura de las caderas y los dedos de los pies apuntando hacia adelante.","Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros.","Activa el core y los glúteos, luego salta explosivamente hacia arriba, extendiendo las caderas y las rodillas.","Mientras saltas, empuja con los dedos de los pies y extiende por completo los tobillos, las rodillas y las caderas.","Aterriza suavemente de vuelta en el suelo, flexionando las rodillas para absorber el impacto.","Pasa de inmediato a la siguiente repetición, repitiendo el movimiento de sentadilla con salto."]}},{"id":"1346","name":"kneeling lat stretch","category":"back","body_part":"back","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"lats","image":"images/1346-f38OEuO.jpg","gif_url":"videos/1346-f38OEuO.gif","instruction_steps":{"he":["כרעו על הרצפה עם ברכיים ברוחב אגן וקצות האצבעות של הרגליים פונות לאחור.","מתחו את הידיים מעל הראש ושלבו את האצבעות.","תוך שמירה על גב ישר, הטו את הגוף באיטיות ימינה, עד תחושת מתיחה ברחב הגבי השמאלי.","החזיקו את המתיחה 20–30 שניות, ואז חזרו לנקודת ההתחלה.","חזרו על המתיחה בצד שמאל, בהטיה שמאלה ותחושת מתיחה ברחב הגבי הימני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Kneel on the ground with your knees hip-width apart and your toes pointing back.","Extend your arms overhead and interlace your fingers.","Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте на колени, расставив колени на ширине плеч и носки ног назад.","Вытяните руки над головой и переплетите пальцы.","Держа спину прямо, медленно наклонитесь в правую сторону, чувствуя растяжение левой широчайшей мышцы.","Удерживайте растяжку 20–30 секунд, затем вернитесь в исходное положение.","Повторите растяжку с левой стороны, наклоняясь влево и чувствуя растяжение правой широчайшей мышцы.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Arrodíllate en el suelo con las rodillas separadas a la altura de las caderas y los dedos de los pies apuntando hacia atrás.","Extiende los brazos por encima de la cabeza y entrelaza los dedos.","Manteniendo la espalda recta, inclínate lentamente hacia el lado derecho, sintiendo un estiramiento en el dorsal izquierdo.","Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.","Repite el estiramiento en el lado izquierdo, inclinándote hacia la izquierda y sintiendo un estiramiento en el dorsal derecho.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"3239","name":"kneeling plank tap shoulder (male)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"abs","image":"images/3239-h1ezqSu.jpg","gif_url":"videos/3239-h1ezqSu.gif","instruction_steps":{"he":["התחילו בכריעה עם הידיים על הרצפה, ברוחב כתפיים.","מתחו את הרגליים לאחור, נשענים על קצות האצבעות של הרגליים, והרימו את הגוף לעמדת פלאנק.","תוך שמירה על ליבה מופעלת ואגן יציב, הרימו יד אחת מהרצפה וגעו בכתף הנגדית.","החזירו את היד לרצפה וחזרו על התנועה עם היד השנייה.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Start in a kneeling position with your hands on the ground, shoulder-width apart.","Extend your legs behind you, resting on your toes, and lift your body into a plank position.","Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.","Return the hand to the ground and repeat with the other hand.","Continue alternating sides for the desired number of repetitions."],"ru":["Начните в положении стоя на коленях, положив руки на землю на ширине плеч.","Вытяните ноги позади себя, опираясь на носки, и поднимите тело в положение планки.","Сохраняя корпус напряженным, а бедра устойчивыми, поднимите одну руку от земли и коснитесь противоположного плеча.","Верните руку на землю и повторите то же самое с другой рукой.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Comienza en posición de rodillas con las manos en el suelo, separadas a la altura de los hombros.","Extiende las piernas hacia atrás, apoyándote en los dedos de los pies, y levanta el cuerpo a una posición de plancha.","Manteniendo el core activado y las caderas estables, levanta una mano del suelo y toca el hombro opuesto.","Devuelve la mano al suelo y repite con la otra mano.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"3211","name":"kneeling push-up (male)","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/3211-ZOuKWir.jpg","gif_url":"videos/3211-ZOuKWir.gif","instruction_steps":{"he":["התחילו בכריעה על הרצפה עם ידיים ברוחב כתפיים, אצבעות פונות קדימה.","מתחו את הרגליים לאחור, נשענים על כריות כפות הרגליים, כך שהגוף יוצר קו ישר מהראש ועד העקבים.","הפעילו את הליבה והורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף.","המשיכו לרדת עד שהחזה מעט מעל הרצפה, ואז דחפו חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.","Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.","Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides.","Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте на колени на землю, поставив руки на ширине плеч, пальцы направлены вперед.","Вытяните ноги позади себя, опираясь на подушечки стоп так, чтобы ваше тело образовывало прямую линию от головы до пяток.","Напрягите корпус и опустите тело к земле, сгибая локти и держа их близко к бокам.","Продолжайте опускаться до тех пор, пока ваша грудь не окажется чуть выше земли, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Comienza arrodillado en el suelo con las manos separadas a la altura de los hombros, los dedos apuntando hacia adelante.","Extiende las piernas hacia atrás, apoyándote en la punta de los pies, de modo que tu cuerpo forme una línea recta desde la cabeza hasta los talones.","Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Continúa bajando hasta que el pecho esté justo encima del suelo, luego empuja hacia arriba a la posición inicial enderezando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"3288","name":"korean dips","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/3288-rWoBmi5.jpg","gif_url":"videos/3288-rWoBmi5.gif","instruction_steps":{"he":["התמקמו בין שני מקבילים עם ידיים מתוחות, תומכות במשקל הגוף.","הורידו את הגוף בכיפוף מרפקים עד שהזרועות העליונות מקבילות לרצפה.","עצרו לרגע, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Position yourself between two parallel bars with your arms extended and supporting your body weight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Встаньте между двумя параллельными брусьями, вытянув руки и поддерживая вес своего тела.","Опустите тело, сгибая локти, пока плечи не станут параллельны земле.","Сделайте паузу на мгновение, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Colócate entre dos barras paralelas con los brazos extendidos sosteniendo el peso de tu cuerpo.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"3418","name":"l-pull-up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/3418-d1GgzTU.jpg","gif_url":"videos/3418-d1GgzTU.gif","instruction_steps":{"he":["אחזו במוט המתח באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היתלו עם ידיים ישרות לגמרי וגוף ישר.","הפעילו את רחב הגבי והבייספס למשיכת הגוף למעלה לכיוון המוט, תוך שמירה על מרפקים קרובים לגוף.","המשיכו למשוך עד שהסנטר מעל המוט.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Возьмитесь за перекладину хватом сверху, на расстоянии чуть шире плеч.","Висите, полностью вытянув руки и выпрямив тело.","Задействуйте широчайшие и бицепсы, чтобы подтянуть тело к перекладине, держа локти близко к телу.","Продолжайте тянуть, пока подбородок не окажется над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.","Cuélgate con los brazos completamente extendidos y el cuerpo recto.","Activa los dorsales y los bíceps para llevar el cuerpo hacia arriba en dirección a la barra, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3419","name":"l-sit on floor","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3419-UpWmA5E.jpg","gif_url":"videos/3419-UpWmA5E.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים מתוחות לפניכם.","הניחו את הידיים על הרצפה לצידי האגן, אצבעות פונות קדימה.","הפעילו את הליבה והרימו את הרגליים מהרצפה, כשהן ישרות.","נסו להביא את הרגליים למקבילות לרצפה, ביצירת צורת L עם הגוף.","החזיקו את התנוחה כמה שיותר זמן.","הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the floor with your legs extended in front of you.","Place your hands on the floor beside your hips, fingers pointing forward.","Engage your core and lift your legs off the ground, keeping them straight.","Try to bring your legs parallel to the floor, forming an 'L' shape with your body.","Hold this position for as long as you can.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на пол, вытянув ноги перед собой.","Положите руки на пол рядом с бедрами, пальцы направлены вперед.","Напрягите корпус и поднимите ноги от земли, сохраняя их прямыми.","Постарайтесь поставить ноги параллельно полу, образуя своим телом букву «L».","Удерживайте это положение столько, сколько сможете.","Медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti.","Coloca las manos en el suelo junto a las caderas, con los dedos apuntando hacia adelante.","Activa el core y levanta las piernas del suelo, manteniéndolas rectas.","Intenta llevar las piernas paralelas al suelo, formando una 'L' con el cuerpo.","Mantén esta posición durante el mayor tiempo posible.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0562","name":"landmine 180","category":"waist","body_part":"waist","equipment":"barbell","muscle_group":"obliques","secondary_muscles":["obliques","quadriceps"],"target":"abs","image":"images/0562-QYysSLV.jpg","gif_url":"videos/0562-QYysSLV.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את המוט בשתי ידיים מול החזה.","כופפו ברכיים מעט וסובבו את הגו ימינה, בהנפת המוט מטה לכיוון מותן ימין.","בהגיעכם לנקודה התחתונה של התנועה, הפכו במהירות את הכיוון וסובבו את הגו שמאלה, בהנפת המוט למעלה ובאלכסון לכיוון כתף שמאל.","המשיכו בתנועת הסיבוב, לסירוגין בין הצדדים, למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest.","Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip.","As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder.","Continue this twisting motion, alternating sides, for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, и держите штангу обеими руками перед грудью.","Слегка согните ноги в коленях и поверните туловище вправо, перемещая штангу вниз к правому бедру.","Достигнув нижней точки движения, быстро поменяйте направление движения и поверните туловище влево, поднимая штангу вверх и поперек тела к левому плечу.","Продолжайте это скручивающее движение, чередуя стороны, необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente al pecho.","Flexiona ligeramente las rodillas y rota el torso hacia la derecha, llevando la barra hacia la cadera derecha.","Cuando llegues a la parte baja del movimiento, invierte rápidamente el movimiento y rota el torso hacia la izquierda, llevando la barra hacia arriba y a través del cuerpo en dirección al hombro izquierdo.","Continúa este movimiento de giro, alternando lados, durante el número de repeticiones deseado."]}},{"id":"3237","name":"landmine lateral raise","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"traps","secondary_muscles":["traps","upper back"],"target":"delts","image":"images/3237-eXMFHww.jpg","gif_url":"videos/3237-eXMFHww.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","החזיקו את המוט באחיזה עליונה, מונח על קדמת הכתפיים.","תוך שמירה על ליבה מופעלת וגב ישר, הרימו את המוט למעלה והרחק מהגוף, עד גובה הכתפיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, resting it on the front of your shoulders.","Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Возьмите штангу хватом сверху, положив ее на переднюю часть плеч.","Удерживая корпус напряженным и спину прямой, поднимите штангу вверх и в сторону от тела, подняв ее до уровня плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra con un agarre prono, apoyándola en la parte delantera de los hombros.","Manteniendo el core activado y la espalda recta, levanta la barra alejándola del cuerpo, elevándola hasta la altura del hombro.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3300","name":"lean planche","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","chest","triceps"],"target":"abs","image":"images/3300-LYJodFS.jpg","gif_url":"videos/3300-LYJodFS.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים ברוחב כתפיים וגוף ישר.","הפעילו את הליבה והעבירו באיטיות את המשקל קדימה, בהבאת הכתפיים מעבר לידיים.","שמרו על מרפקים כפופים מעט וגוף ישר תוך ההטיה קדימה.","החזיקו את התנוחה כמה שניות, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands shoulder-width apart and your body straight.","Engage your core and slowly shift your weight forward, bringing your shoulders past your hands.","Keep your elbows slightly bent and your body straight as you lean forward.","Hold this position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции для отжиманий, поставив руки на ширине плеч и выпрямив тело.","Напрягите корпус и медленно перенесите вес вперед, выводя плечи за руки.","Держите локти слегка согнутыми, а тело прямым, наклоняясь вперед.","Удерживайте это положение несколько секунд, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en una posición de flexión con las manos separadas a la altura de los hombros y el cuerpo recto.","Activa el core y traslada lentamente el peso hacia adelante, llevando los hombros más allá de las manos.","Mantén los codos ligeramente flexionados y el cuerpo recto mientras te inclinas hacia adelante.","Mantén esta posición durante unos segundos, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2271","name":"left hook. boxing","category":"shoulders","body_part":"shoulders","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","triceps","forearms"],"target":"delts","image":"images/2271-hoXt6wv.jpg","gif_url":"videos/2271-hoXt6wv.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","שמרו על יד שמאל למעלה להגנה על הפנים ויד ימין ליד הסנטר.","סובבו את האגן והסתובבו על כף רגל שמאל תוך מתיחת יד שמאל קדימה בתנועת אגרוף.","סובבו את הגו והפעילו את שרירי הליבה ליצירת כוח באגרוף.","החזירו את היד במהירות לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Keep your left hand up to protect your face and your right hand by your chin.","Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion.","Twist your torso and engage your core muscles to generate power in the punch.","Snap your arm back to the starting position and repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Держите левую руку вверх, чтобы защитить лицо, а правую руку — под подбородок.","Вращайте бедра и поворачивайтесь на левой ноге, одновременно вытягивая левую руку вперед для ударного движения.","Поверните туловище и задействуйте мышцы корпуса, чтобы генерировать силу удара.","Верните руку в исходное положение и повторите желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Mantén la mano izquierda arriba para proteger el rostro y la mano derecha junto a la barbilla.","Rota las caderas y pívota sobre el pie izquierdo mientras extiendes el brazo izquierdo hacia adelante con un movimiento de golpe.","Gira el torso y activa los músculos del core para generar potencia en el golpe.","Lleva el brazo rápidamente de vuelta a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"0570","name":"leg pull in flat bench","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0570-OyoZ3Pu.jpg","gif_url":"videos/0570-OyoZ3Pu.gif","instruction_steps":{"he":["שבו על ספסל ישר עם רגליים מתוחות ישר לפניכם.","הניחו את הידיים על הספסל לצידי האגן לתמיכה.","הפעילו את שרירי הבטן והרימו את הרגליים מהרצפה, בהבאת הברכיים לכיוון החזה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a flat bench with your legs extended straight out in front of you.","Place your hands on the bench beside your hips for support.","Engage your abs and lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на ровную скамью, вытянув ноги прямо перед собой.","Положите руки на скамью рядом с бедрами для поддержки.","Напрягите пресс и поднимите ноги от земли, подтягивая колени к груди.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco plano con las piernas extendidas rectas hacia adelante.","Coloca las manos en el banco junto a las caderas para mayor apoyo.","Activa el abdomen y levanta las piernas del suelo, llevando las rodillas hacia el pecho.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1576","name":"leg up hamstring stretch","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes"],"target":"hamstrings","image":"images/1576-sU5BrfP.jpg","gif_url":"videos/1576-sU5BrfP.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות.","כופפו ברך אחת והביאו אותה לכיוון החזה, אוחזים בירך או בשוק.","יישרו את הרגל ככל האפשר תוך השארתה מורמת.","החזיקו את המתיחה 20–30 שניות.","חזרו על התנועה עם הרגל השנייה."],"en":["Lie flat on your back with your legs extended.","Bend one knee and bring it towards your chest, holding onto your thigh or shin.","Straighten your leg as much as possible while keeping it elevated.","Hold the stretch for 20-30 seconds.","Repeat with the other leg."],"ru":["Лягте на спину, вытянув ноги.","Согните одно колено и поднесите его к груди, держась за бедро или голень.","Максимально выпрямите ногу, удерживая ее в приподнятом положении.","Удерживайте растяжку 20–30 секунд.","Повторите с другой ногой."],"es":["Túmbate boca arriba con las piernas extendidas.","Flexiona una rodilla y llévala hacia el pecho, sujetándote del muslo o la espinilla.","Endereza la pierna tanto como sea posible mientras la mantienes elevada.","Mantén el estiramiento durante 20-30 segundos.","Repite con la otra pierna."]}},{"id":"2287","name":"lever alternate leg press","category":"upper legs","body_part":"upper legs","equipment":"leverage machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"quads","image":"images/2287-V07qpXy.jpg","gif_url":"videos/2287-V07qpXy.gif","instruction_steps":{"he":["כווננו את המושב ומשטח הרגליים של מכונת המנוף לתנוחה הרצויה.","שבו על המכשיר כשהגב צמוד למשענת וכפות הרגליים על משטח הרגליים.","הניחו את הידיים על הידיות או צידי המכשיר לייצוב.","דחפו כף רגל אחת כנגד משטח הרגליים, במתיחת הרגל עד שהיא כמעט ישרה לגמרי.","עצרו לרגע, ואז כופפו באיטיות את הרגל וחזרו לנקודת ההתחלה.","חזרו על התנועה עם הרגל השנייה.","המשיכו להחליף רגליים למספר החזרות הרצוי."],"en":["Adjust the seat and foot platform of the leverage machine to your desired position.","Sit on the machine with your back against the backrest and your feet on the foot platform.","Place your hands on the handles or sides of the machine for stability.","Push one foot against the foot platform, extending your leg until it is almost fully straight.","Pause for a moment, then slowly bend your leg and return to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."],"ru":["Отрегулируйте сиденье и платформу для ног рычажной машины в желаемое положение.","Сядьте на тренажер, прислонившись спиной к спинке и поставив ноги на платформу для ног.","Положите руки на ручки или по бокам машины для устойчивости.","Упритесь одной ногой в платформу для ног, вытягивая ногу до тех пор, пока она не станет почти полностью прямой.","Сделайте паузу на мгновение, затем медленно согните ногу и вернитесь в исходное положение.","Повторите с другой ногой.","Продолжайте чередовать ноги желаемое количество повторений."],"es":["Ajusta el asiento y la plataforma para los pies de la máquina de palanca a la posición deseada.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la plataforma para los pies.","Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad.","Empuja un pie contra la plataforma para los pies, extendiendo la pierna hasta que esté casi completamente recta.","Haz una pausa breve, luego flexiona lentamente la pierna y vuelve a la posición inicial.","Repite con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."]}},{"id":"0571","name":"lever alternating narrow grip seated row","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0571-w2oRpuH.jpg","gif_url":"videos/0571-w2oRpuH.gif","instruction_steps":{"he":["כווננו את גובה המושב ומיקום משטח הרגליים ליישור נכון של הגוף.","שבו על המכשיר עם גב ישר וכפות רגליים על משטח הרגליים.","אחזו בידיות באחיזה צרה, כפות ידיים פונות זו לזו.","שמרו על חזה מורם וכתפיים לאחור לאורך כל התרגיל.","משכו ידית אחת לכיוון הגו, תוך שמירה על הידית השנייה ללא תזוזה.","כווצו את השכמות זו לזו בסוף התנועה.","החזירו באיטיות את הידית לנקודת ההתחלה וחזרו על התנועה בצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your back straight and feet flat on the footplate.","Grasp the handles with a narrow grip, palms facing each other.","Keep your chest up and shoulders back throughout the exercise.","Pull one handle towards your torso while keeping the other handle stationary.","Squeeze your shoulder blades together at the end of the movement.","Slowly return the handle to the starting position and repeat with the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и положение подножки, чтобы обеспечить правильное выравнивание.","Сядьте на тренажер, выпрямив спину и положив ступни на подножку.","Возьмитесь за ручки узким хватом, ладони обращены друг к другу.","На протяжении всего упражнения держите грудь поднятой, а плечи отведенными назад.","Потяните одну ручку к туловищу, удерживая другую ручку неподвижной.","В конце движения сведите лопатки вместе.","Медленно верните ручку в исходное положение и повторите то же самое с другой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta.","Siéntate en la máquina con la espalda recta y los pies planos sobre la placa para los pies.","Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra.","Mantén el pecho elevado y los hombros hacia atrás durante todo el ejercicio.","Tira de una asa hacia el torso mientras mantienes la otra asa inmóvil.","Aprieta los omóplatos al final del movimiento.","Devuelve lentamente el asa a la posición inicial y repite con el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0572","name":"lever assisted chin-up","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0572-MaMuGH6.jpg","gif_url":"videos/0572-MaMuGH6.gif","instruction_steps":{"he":["כווננו את מכונת המנוף לרמת ההתנגדות הרצויה.","עמדו על משטח הרגליים ואחזו בידיות באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היתלו עם ידיים ישרות לגמרי, תוך שמירה על גוף ישר.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון הידיות, כשהחזה מוביל את התנועה.","המשיכו למשוך עד שהסנטר מעל הידיות.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the leverage machine to your desired resistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your body straight.","Engage your back muscles and pull your body up towards the handles, leading with your chest.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте рычаг тренажера до желаемого уровня сопротивления.","Встаньте на платформу для ног и возьмитесь за рукоятки хватом сверху, на расстоянии чуть шире плеч.","Висите, полностью вытянув руки, сохраняя тело прямым.","Задействуйте мышцы спины и подтяните тело вверх к ручкам, ведя грудью.","Продолжайте тянуть, пока подбородок не окажется над ручками.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de palanca al nivel de resistencia deseado.","Sube a la plataforma para los pies y agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Cuélgate con los brazos completamente extendidos, manteniendo el cuerpo recto.","Activa los músculos de la espalda y tira del cuerpo hacia arriba en dirección a las asas, liderando con el pecho.","Continúa subiendo hasta que la barbilla quede por encima de las agarraderas.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0573","name":"lever back extension","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/0573-rUXfn3R.jpg","gif_url":"videos/0573-rUXfn3R.gif","instruction_steps":{"he":["כווננו את המכשיר לגודל הגוף וטווח התנועה שלכם.","שבו על המכשיר כשהגב צמוד לכרית וכפות הרגליים מקובעות.","הניחו את הידיים על הידיות או מוטות האחיזה.","הפעילו את הליבה ורכנו באיטיות קדימה, ותנו לגב להתעגל מעט.","עצרו לרגע בנקודה התחתונה, בתחושת מתיחה בגב התחתון.","בעזרת שרירי הגב, הרימו באיטיות את הגו חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to fit your body size and range of motion.","Sit on the machine with your back against the pad and your feet secured.","Place your hands on the handles or grip bars.","Engage your core and slowly lean forward, allowing your back to round slightly.","Pause for a moment at the bottom position, feeling a stretch in your lower back.","Using your back muscles, slowly raise your torso back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте тренажер в соответствии с размером вашего тела и диапазоном движений.","Сядьте на тренажер, прислонившись спиной к подушке и зафиксировав ноги.","Положите руки на ручки или поручни.","Напрягите корпус и медленно наклонитесь вперед, позволяя спине слегка округлиться.","Задержитесь на мгновение в нижнем положении, чувствуя растяжение в пояснице.","Используя мышцы спины, медленно поднимите туловище обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina según el tamaño de tu cuerpo y tu rango de movimiento.","Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies asegurados.","Coloca las manos en las asas o en las barras de agarre.","Activa el core e inclínate lentamente hacia adelante, permitiendo que la espalda se redondee ligeramente.","Haz una pausa breve en la posición baja, sintiendo un estiramiento en la zona lumbar.","Usando los músculos de la espalda, levanta lentamente el torso de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0574","name":"lever bent over row","category":"back","body_part":"back","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0574-X3cqyXz.jpg","gif_url":"videos/0574-X3cqyXz.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","אחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וחזה מורם.","משכו את המוט לכיוון החזה התחתון, תוך כיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Возьмите штангу хватом сверху, руки чуть шире плеч.","Наклонитесь вперед в бедрах, держа спину прямо и грудь вверх.","Потяните штангу к нижней части груди, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.","Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3200","name":"lever bent-over row with v-bar","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/3200-LuBEORI.jpg","gif_url":"videos/3200-LuBEORI.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו מול המכשיר.","אחזו בידית ה-V באחיזה עליונה, תוך שמירה על גב ישר וברכיים כפופות מעט.","משכו את ידית ה-V לכיוון הבטן, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה, ואז שחררו באיטיות את המשקל חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself facing the machine.","Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent.","Pull the v-bar towards your abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the weight back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь лицом к машине.","Возьмитесь за V-образную перекладину хватом сверху, сохраняя спину прямой и слегка согнутыми в коленях.","Потяните V-образную перекладину к животу, сжимая лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения, затем медленно опустите вес обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate frente a la máquina.","Sujeta la barra en V con un agarre prono, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Tira de la barra en V hacia el abdomen, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente el peso de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0575","name":"lever bicep curl","category":"upper arms","body_part":"upper arms","equipment":"leverage machine","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0575-q6y3OhV.jpg","gif_url":"videos/0575-q6y3OhV.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהגב צמוד לכרית.","אחזו בידיות באחיזה תחתונה, כפות ידיים כלפי מעלה, ושמרו על מרפקים צמודים לצידי הגוף.","נשפו וכופפו את הידיות כלפי מעלה, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","שאפו והורידו את הידיות באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an underhand grip, palms facing up, and keep your elbows close to your sides.","Exhale and curl the handles upward, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере спиной к подушке.","Возьмитесь за рукоятки обратным хватом ладонями вверх и держите локти близко к бокам.","Выдохните и поднимите ручки вверх, напрягая бицепсы.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Вдохните и медленно опустите рукоятки обратно в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.","Sujeta las asas con un agarre supino, con las palmas hacia arriba, y mantén los codos cerca de los costados.","Exhala y flexiona las asas hacia arriba, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente los mangos de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"2289","name":"lever calf press","category":"lower legs","body_part":"lower legs","equipment":"leverage machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/2289-7B4F5nZ.jpg","gif_url":"videos/2289-7B4F5nZ.gif","instruction_steps":{"he":["כווננו את מושב מכונת המנוף כך שהכתפיים בקו אחד עם כרית המנוף.","הניחו את קצות האצבעות של הרגליים על כרית המנוף, כשהעקבים משתלשלים מעבר לקצה.","אחזו בידיות או בתמיכות הצד לייצוב.","לחצו את כרית המנוף מטה ביישור הקרסוליים, בכיווץ שרירי התאומים.","עצרו לרגע בנקודה התחתונה של התנועה.","חזרו באיטיות לנקודת ההתחלה, ותנו לעקבים לעלות חזרה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat of the leverage machine so that your shoulders are aligned with the lever pad.","Place your toes on the lever pad, with your heels hanging off the edge.","Grasp the handles or side supports for stability.","Push the lever pad down by extending your ankles, contracting your calf muscles.","Pause for a moment at the bottom of the movement.","Slowly return to the starting position by allowing your heels to rise back up.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сиденье тренажера так, чтобы ваши плечи находились на одной линии с подушечкой рычага.","Поместите пальцы ног на подушечку рычага так, чтобы пятки свисали с края.","Возьмитесь за ручки или боковые опоры для устойчивости.","Нажмите на подушечку рычага вниз, вытянув лодыжки и напрягая икроножные мышцы.","Сделайте паузу на мгновение в нижней части движения.","Медленно вернитесь в исходное положение, позволяя пяткам снова подняться.","Повторите необходимое количество повторений."],"es":["Ajusta el asiento de la máquina de palanca de modo que los hombros queden alineados con la almohadilla de la palanca.","Coloca los dedos de los pies sobre la almohadilla de la palanca, con los talones colgando fuera del borde.","Sujeta las asas o los soportes laterales para mayor estabilidad.","Empuja la almohadilla de la palanca hacia abajo extendiendo los tobillos, contrayendo los músculos de las pantorrillas.","Haz una pausa por un momento en la parte baja del movimiento.","Vuelve lentamente a la posición inicial dejando que los talones se eleven de nuevo.","Repite el número de repeticiones deseado."]}},{"id":"0577","name":"lever chest press","category":"chest","body_part":"chest","equipment":"leverage machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0577-T0yTjgW.jpg","gif_url":"videos/0577-T0yTjgW.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהגב צמוד לכרית.","אחזו בידיות באחיזה עליונה ומקמו את המרפקים בזווית של 90 מעלות.","דחפו את הידיות קדימה עד יישור מלא של הידיים, תוך נשיפה במהלך התנועה.","עצרו קצרות בסוף התנועה, ואז חזרו באיטיות לנקודת ההתחלה תוך שאיפה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере, прижавшись спиной к подушке.","Возьмитесь за рукоятки хватом сверху и расположите локти под углом 90 градусов.","Толкайте ручки вперед до полного выпрямления рук, выдыхая во время движения.","Сделайте короткую паузу в конце движения, затем медленно вернитесь в исходное положение, вдыхая при этом.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla.","Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados.","Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento.","Haz una pausa breve al final del movimiento, luego vuelve lentamente a la posición inicial, inhalando mientras lo haces.","Repite el número de repeticiones deseado."]}},{"id":"0576","name":"lever chest press","category":"chest","body_part":"chest","equipment":"leverage machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0576-DOoWcnA.jpg","gif_url":"videos/0576-DOoWcnA.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהגב צמוד לכרית.","אחזו בידיות באחיזה עליונה ומקמו את המרפקים בזווית של 90 מעלות.","דחפו את הידיות קדימה עד יישור מלא של הידיים, תוך נשיפה במהלך התנועה.","עצרו קצרות בסוף התנועה, ואז חזרו באיטיות לנקודת ההתחלה תוך שאיפה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере, прижавшись спиной к подушке.","Возьмитесь за рукоятки хватом сверху и расположите локти под углом 90 градусов.","Толкайте ручки вперед до полного выпрямления рук, выдыхая во время движения.","Сделайте короткую паузу в конце движения, затем медленно вернитесь в исходное положение, вдыхая при этом.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla.","Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados.","Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento.","Haz una pausa breve al final del movimiento, luego vuelve lentamente a la posición inicial, inhalando mientras lo haces.","Repite el número de repeticiones deseado."]}},{"id":"0578","name":"lever deadlift","category":"upper legs","body_part":"upper legs","equipment":"leverage machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/0578-GUT8I22.jpg","gif_url":"videos/0578-GUT8I22.gif","instruction_steps":{"he":["כווננו את גובה המושב ומשטח הרגליים לתנוחה הרצויה.","שבו על המכשיר כשהגב צמוד לכרית וכפות הרגליים שטוחות על משטח הרגליים.","אחזו בידיות או בצידי המושב לייצוב.","הפעילו את הישבן והירך האחורית, ודחפו דרך העקבים להרמת המשקל.","שמרו על גב ישר והימנעו מעיגול הכתפיים.","יישרו את הירכיים לגמרי בנקודה העליונה של התנועה, בכיווץ הישבן.","הורידו את המשקל חזרה בשליטה, תוך שמירה על מתח בישבן ובירך האחורית.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and foot platform to your desired position.","Sit on the machine with your back against the pad and your feet flat on the foot platform.","Grasp the handles or the sides of the seat for stability.","Engage your glutes and hamstrings, and push through your heels to lift the weight up.","Keep your back straight and avoid rounding your shoulders.","Extend your hips fully at the top of the movement, squeezing your glutes.","Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и платформу для ног в желаемое положение.","Сядьте на тренажер, прислонившись спиной к подушке, а ноги поставьте на платформу для ног.","Возьмитесь за ручки или боковые стороны сиденья для устойчивости.","Задействуйте ягодицы и мышцы задней поверхности бедра и толкните пятки, чтобы поднять вес.","Держите спину прямо и не округляйте плечи.","Полностью выпрямите бедра в верхней точке движения, сжимая ягодицы.","Опустите вес обратно контролируемым образом, сохраняя напряжение в ягодицах и подколенных сухожилиях.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y la plataforma para los pies a la posición deseada.","Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies planos sobre la plataforma para los pies.","Sujeta las asas o los lados del asiento para mayor estabilidad.","Activa los glúteos y los isquiotibiales, y empuja con los talones para levantar el peso.","Mantén la espalda recta y evita redondear los hombros.","Extiende por completo las caderas en la parte alta del movimiento, apretando los glúteos.","Baja el peso de manera controlada, manteniendo la tensión en los glúteos y los isquiotibiales.","Repite el número de repeticiones deseado."]}},{"id":"1300","name":"lever decline chest press","category":"chest","body_part":"chest","equipment":"leverage machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1300-vsVoPHt.jpg","gif_url":"videos/1300-vsVoPHt.gif","instruction_steps":{"he":["כווננו את גובה המושב והמשענת של מכונת המנוף לתנוחה נוחה.","שבו על המכשיר כשהגב צמוד למשענת וכפות הרגליים על הרצפה.","אחזו בידיות באחיזה עליונה ומקמו את הידיים מעט רחב מרוחב הכתפיים.","דחפו את הידיות קדימה והרחק מהגוף עד יישור מלא של הידיים.","הורידו באיטיות את הידיות חזרה לכיוון החזה, תוך שמירה על מרפקים כפופים מעט.","עצרו לרגע בנקודה התחתונה, ואז דחפו את הידיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended.","Slowly lower the handles back towards your chest, keeping your elbows slightly bent.","Pause for a moment at the bottom, then push the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и спинку рычажной машины в удобное положение.","Сядьте на тренажер, прислонившись спиной к спинке, а ноги поставьте на пол.","Возьмитесь за рукоятки хватом сверху и поставьте руки чуть шире плеч.","Толкайте рукоятки вперед и в сторону от тела, пока руки полностью не выпрямятся.","Медленно опустите рукоятки обратно к груди, слегка согнув локти.","Задержитесь на мгновение внизу, затем верните ручки в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.","Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros.","Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos.","Baja lentamente las asas de vuelta hacia el pecho, manteniendo los codos ligeramente flexionados.","Haz una pausa breve en la parte baja, luego empuja las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1253","name":"lever donkey calf raise","category":"lower legs","body_part":"lower legs","equipment":"leverage machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1253-C9LuR4A.jpg","gif_url":"videos/1253-C9LuR4A.gif","instruction_steps":{"he":["כווננו את מכונת המנוף לגובה המתאים לגוף שלכם.","התמקמו מול המכשיר, כשקצות האצבעות של הרגליים על משטח הרגליים והעקבים משתלשלים מעבר לקצה.","הניחו את הידיים על הידיות או מוטות התמיכה לייצוב.","הפעילו את התאומים והרימו את העקבים גבוה ככל האפשר, בעזרת כריות כפות הרגליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the leverage machine to the appropriate height for your body.","Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.","Place your hands on the handles or the support bars for stability.","Engage your calves and lift your heels as high as possible, using the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте рычаг тренажера на высоту, соответствующую вашему телу.","Встаньте лицом к тренажеру, положив пальцы ног на платформу для ног, а пятки свисая с края.","Для устойчивости положите руки на ручки или опорные перекладины.","Напрягите икроножные мышцы и поднимите пятки как можно выше, используя подушечки стоп.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de palanca a la altura adecuada para tu cuerpo.","Colócate de frente a la máquina, con los dedos de los pies en la plataforma y los talones colgando fuera del borde.","Coloca las manos en las asas o en las barras de soporte para mayor estabilidad.","Activa las pantorrillas y levanta los talones tan alto como sea posible, usando la parte delantera de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0579","name":"lever front pulldown","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0579-7F1DVzn.jpg","gif_url":"videos/0579-7F1DVzn.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהברכיים מתחת לכריות וכפות הרגליים על הרצפה.","אחזו בידיות באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שבו זקוף עם חזה מורם וכתפיים לאחור, תוך שמירה על קשת קלה בגב התחתון.","הפעילו את רחב הגבי ומשכו את הידיות מטה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, ואז שחררו באיטיות את הידיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back.","Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на машине так, чтобы колени находились под подушками, а ступни стояли на земле.","Возьмитесь за ручки хватом сверху, на расстоянии чуть шире плеч.","Сядьте прямо, подняв грудь и отведя плечи назад, сохраняя небольшой изгиб в пояснице.","Напрягите широчайшие и потяните рукоятки вниз к груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно отпустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Siéntate erguido con el pecho elevado y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar.","Activa los dorsales y tira de las asas hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0580","name":"lever gripless shrug","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"shoulders","secondary_muscles":["shoulders","forearms"],"target":"traps","image":"images/0580-f91FwXG.jpg","gif_url":"videos/0580-f91FwXG.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על מכונת המנוף.","אחזו בידיות עם כפות ידיים פונות פנימה וידיים ישרות לגמרי.","תוך שמירה על גב ישר, נשפו והרימו את הכתפיים גבוה ככל האפשר.","החזיקו את הכיווץ לרגע קצר, ואז שאפו והורידו את הכתפיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with your palms facing inwards and your arms fully extended.","Keeping your back straight, exhale and elevate your shoulders as high as possible.","Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на рычаге машины.","Возьмитесь за ручки ладонями внутрь и полностью выпрямите руки.","Сохраняя спину прямой, выдохните и поднимите плечи как можно выше.","Задержите сокращение на короткое время, затем вдохните и медленно опустите плечи обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina de palanca.","Sujeta las asas con las palmas hacia adentro y los brazos completamente extendidos.","Manteniendo la espalda recta, exhala y eleva los hombros tan alto como sea posible.","Mantén la contracción por un momento breve, luego inhala y baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1439","name":"lever gripless shrug v. 2","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"shoulders","secondary_muscles":["shoulders","forearms"],"target":"traps","image":"images/1439-cbuFJrn.jpg","gif_url":"videos/1439-cbuFJrn.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהגב צמוד לכרית.","אחזו בידיות או במוטות באחיזה עליונה, תוך שמירה על ידיים ישרות.","תוך שמירה על גב ישר, הרימו את הכתפיים למעלה לכיוון האוזניים גבוה ככל האפשר.","החזיקו את הכיווץ לרגע, ואז הורידו את הכתפיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles or bars with an overhand grip, keeping your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере спиной к подушке.","Возьмитесь за ручки или перекладины верхним хватом, держа руки прямыми.","Сохраняя спину прямой, поднимите плечи как можно выше к ушам.","Удерживайте напряжение на мгновение, затем медленно опустите плечи обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.","Sujeta las asas o barras con un agarre prono, manteniendo los brazos rectos.","Manteniendo la espalda recta, eleva los hombros hacia las orejas tan alto como sea posible.","Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2288","name":"lever gripper hands","category":"lower arms","body_part":"lower arms","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"forearms","image":"images/2288-mKwcrHn.jpg","gif_url":"videos/2288-mKwcrHn.gif","instruction_steps":{"he":["כווננו את גובה המושב ואחזו בידיות מכונת המנוף.","שמרו על גב ישר וכפות רגליים על הרצפה.","נשפו ולחצו את הידיות, בכיווץ האמות.","החזיקו את הכיווץ שנייה, ואז שחררו באיטיות וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and grip the handles of the leverage machine.","Keep your back straight and your feet flat on the ground.","Exhale and squeeze the handles, contracting your forearms.","Hold the contraction for a second, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и возьмитесь за ручки рычага машины.","Держите спину прямо, а ноги на земле.","Выдохните и сожмите ручки, напрягая предплечья.","Удерживайте напряжение в течение секунды, затем медленно расслабьтесь и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y sujeta las asas de la máquina de palanca.","Mantén la espalda recta y los pies planos en el suelo.","Exhala y aprieta las asas, contrayendo los antebrazos.","Mantén la contracción durante un segundo, luego suelta lentamente y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1615","name":"lever hammer grip preacher curl","category":"upper arms","body_part":"upper arms","equipment":"leverage machine","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1615-OAguZoG.jpg","gif_url":"videos/1615-OAguZoG.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על מכונת המנוף.","הניחו את הזרועות העליונות על כרית הפריצ'ר, וודאו שהחזה צמוד אליה.","אחזו בידיות באחיזת פטיש (כפות ידיים פונות זו לזו).","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את הידיות לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את הידיות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the preacher pad, ensuring your chest is pressed against it.","Grasp the handles with a hammer grip (palms facing each other).","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на рычаге машины.","Положите плечи на коврик для проповедника так, чтобы грудь прижималась к нему.","Возьмитесь за ручки молотковым хватом (ладони обращены друг к другу).","Удерживая плечи неподвижно, выдохните и согните ручки к плечам.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina de palanca.","Coloca los brazos superiores sobre la almohadilla de predicador, asegurándote de que el pecho quede apoyado contra ella.","Sujeta las asas con agarre neutro (palmas una frente a la otra).","Manteniendo los brazos superiores inmóviles, exhala y flexiona las asas hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0581","name":"lever high row","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","rear deltoids"],"target":"upper back","image":"images/0581-nZZZy9m.jpg","gif_url":"videos/0581-nZZZy9m.gif","instruction_steps":{"he":["כווננו את גובה המושב ומשטח הרגליים לתנוחה נוחה.","שבו על המכשיר כשהחזה צמוד לכרית וכפות הרגליים על משטח הרגליים.","אחזו בידיות באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שמרו על גב ישר והפעילו את שרירי הליבה.","משכו את הידיות לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה, ואז שחררו באיטיות את הידיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and foot platform to a comfortable position.","Sit on the machine with your chest against the pad and your feet flat on the foot platform.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и платформу для ног в удобное положение.","Сядьте на тренажер, прижав грудь к подушке, а ступни поставив на платформу для ног.","Возьмитесь за ручки хватом сверху, на расстоянии чуть шире плеч.","Держите спину прямо и задействуйте корпус.","Потяните ручки к телу, сведя лопатки вместе.","Задержитесь на мгновение на пике движения, затем медленно отпустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y la plataforma para los pies a una posición cómoda.","Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la plataforma para los pies.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y activa el core.","Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2286","name":"lever hip extension v. 2","category":"upper legs","body_part":"upper legs","equipment":"leverage machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"glutes","image":"images/2286-OPqShYN.jpg","gif_url":"videos/2286-OPqShYN.gif","instruction_steps":{"he":["כווננו את המכשיר לגוף שלכם ושבו עליו כשהגב צמוד למשענת.","הניחו את כפות הרגליים על משענות הרגליים ואחזו בידיות לייצוב.","הפעילו את הישבן והירך האחורית, ואז דחפו כנגד משענות הרגליים ליישור הירכיים והרמת הרגליים לאחור.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your feet on the footrests and grip the handles for stability.","Engage your glutes and hamstrings, then push against the footrests to extend your hips and raise your legs backward.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте машину по размеру вашего тела и сядьте на нее, прижавшись спиной к спинке сиденья.","Поставьте ноги на подножки и возьмитесь за ручки для устойчивости.","Задействуйте ягодицы и мышцы задней поверхности бедра, затем оттолкнитесь от подножек, чтобы разогнуть бедра и поднять ноги назад.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo.","Coloca los pies en los apoyapiés y sujeta las asas para mayor estabilidad.","Activa los glúteos y los isquiotibiales, luego empuja contra los apoyapiés para extender las caderas y levantar las piernas hacia atrás.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2611","name":"lever horizontal one leg press","category":"upper legs","body_part":"upper legs","equipment":"leverage machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/2611-9KU9TYF.jpg","gif_url":"videos/2611-9KU9TYF.gif","instruction_steps":{"he":["כווננו את מושב המכשיר כך שהברכיים בזווית של 90 מעלות כשכפות הרגליים על משטח הרגליים.","שבו על המכשיר כשהגב צמוד למשענת וכפות הרגליים ברוחב כתפיים על משטח הרגליים.","הניחו את הידיים על הידיות או צידי המכשיר לייצוב.","דחפו את משטח הרגליים מהגוף ביישור הרגל, תוך שמירה על הגב צמוד למשענת.","עצרו לרגע בתנוחת היישור המלא, ואז כופפו באיטיות את הרגל וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Place your hands on the handles or sides of the machine for stability.","Push the footplate away from your body by extending your leg, keeping your back against the backrest.","Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Отрегулируйте сиденье тренажера так, чтобы колени находились под углом 90 градусов, когда ступни стоят на подножке.","Сядьте на тренажер спиной к спинке и поставьте ноги на подножку на ширине плеч.","Положите руки на ручки или по бокам машины для устойчивости.","Отодвиньте подножку от тела, вытянув ногу и прижав спину к спинке.","Задержитесь на мгновение в полностью выпрямленном положении, затем медленно согните ногу, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Ajusta el asiento de la máquina de modo que las rodillas queden en un ángulo de 90 grados cuando los pies estén sobre la placa para los pies.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies.","Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad.","Empuja la placa para los pies alejándola del cuerpo extendiendo la pierna, manteniendo la espalda apoyada en el respaldo.","Haz una pausa breve en la posición completamente extendida, luego flexiona lentamente la pierna para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"1299","name":"lever incline chest press","category":"chest","body_part":"chest","equipment":"leverage machine","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1299-jHAnWmT.jpg","gif_url":"videos/1299-jHAnWmT.gif","instruction_steps":{"he":["כווננו את המושב והמשענת של מכונת המנוף לתנוחה נוחה.","שבו על המכשיר כשהגב צמוד למשענת וכפות הרגליים על הרצפה.","אחזו בידיות באחיזה עליונה ומקמו את הידיים מעט רחב מרוחב הכתפיים.","דחפו את הידיות קדימה והרחק מהגוף עד יישור מלא של הידיים.","עצרו לרגע, ואז כופפו באיטיות מרפקים והורידו את הידיות חזרה לכיוון החזה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended.","Pause for a moment, then slowly bend your elbows and lower the handles back towards your chest.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сиденье и спинку рычажной машины в удобное положение.","Сядьте на тренажер, прислонившись спиной к спинке, а ноги поставьте на пол.","Возьмитесь за рукоятки хватом сверху и поставьте руки чуть шире плеч.","Толкайте рукоятки вперед и в сторону от тела, пока руки полностью не выпрямятся.","Сделайте паузу на мгновение, затем медленно согните локти и опустите рукоятки обратно к груди.","Повторите необходимое количество повторений."],"es":["Ajusta el asiento y el respaldo de la máquina de palanca a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.","Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros.","Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos.","Haz una pausa breve, luego flexiona lentamente los codos y baja las asas de vuelta hacia el pecho.","Repite el número de repeticiones deseado."]}},{"id":"1479","name":"lever incline chest press v. 2","category":"chest","body_part":"chest","equipment":"leverage machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1479-o17Jfkt.jpg","gif_url":"videos/1479-o17Jfkt.gif","instruction_steps":{"he":["כווננו את גובה המושב וזווית המשענת במכונת המנוף לתנוחה נוחה.","שבו על המכשיר כשהגב צמוד למשענת וכפות הרגליים על הרצפה.","אחזו בידיות באחיזה עליונה ומקמו את הידיים מעט רחב מרוחב הכתפיים.","דחפו את הידיות קדימה והרחק מהגוף עד יישור מלא של הידיים, אך בלי לנעול את המרפקים.","עצרו לרגע בתנוחת היישור המלא, ואז כופפו באיטיות מרפקים והחזירו את הידיות לכיוון החזה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and backrest angle on the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended, but without locking your elbows.","Pause for a moment at the fully extended position, then slowly bend your elbows and lower the handles back towards your chest.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и угол наклона спинки на рычаге машины до удобного положения.","Сядьте на тренажер, прислонившись спиной к спинке, а ноги поставьте на пол.","Возьмитесь за рукоятки хватом сверху и поставьте руки чуть шире плеч.","Толкайте рукоятки вперед и в сторону от тела до тех пор, пока руки полностью не выпрямятся, но не сгибайте локти.","Задержитесь на мгновение в полностью выпрямленном положении, затем медленно согните локти и опустите рукоятки обратно к груди.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y el ángulo del respaldo de la máquina de palanca a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.","Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros.","Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos, pero sin bloquear los codos.","Haz una pausa breve en la posición completamente extendida, luego flexiona lentamente los codos y baja las asas de vuelta hacia el pecho.","Repite el número de repeticiones deseado."]}},{"id":"0582","name":"lever kneeling leg curl","category":"upper legs","body_part":"upper legs","equipment":"leverage machine","muscle_group":"glutes","secondary_muscles":["glutes"],"target":"hamstrings","image":"images/0582-nnmCTLN.jpg","gif_url":"videos/0582-nnmCTLN.gif","instruction_steps":{"he":["כווננו את המכשיר לגוף שלכם ובחרו את המשקל הרצוי.","כרעו על המכשיר עם הפנים כלפי מטה, כשהברכיים מונחות על הכרית וכפות הרגליים מקובעות מתחת לכריות הרגליים.","אחזו בידיות או בצידי המכשיר לייצוב.","תוך שמירה על פלג גוף עליון ללא תזוזה, נשפו וגלגלו את הרגליים למעלה לכיוון הישבן בכיפוף הברכיים.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הירך האחורית.","שאפו והורידו את הרגליים באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הברכיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to fit your body and select the desired weight.","Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position, fully extending your knees.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте тренажер под свое тело и выберите желаемый вес.","Встаньте на колени на тренажере лицом вниз, положив колени на подушку, а ступни зафиксировав под подушечками.","Возьмитесь за ручки или боковые стороны машины для устойчивости.","Удерживая верхнюю часть тела неподвижно, выдохните и согните ноги к ягодицам, согнув колени.","Задержитесь на мгновение в верхней точке движения, сжимая мышцы задней поверхности бедра.","Вдохните и медленно опустите ноги обратно в исходное положение, полностью выпрямляя колени.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina a tu cuerpo y selecciona el peso deseado.","Arrodíllate en la máquina mirando hacia abajo, con las rodillas apoyadas en la almohadilla y los pies asegurados bajo las almohadillas para los pies.","Sujeta las asas o los lados de la máquina para mayor estabilidad.","Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales.","Inhala y baja lentamente las piernas de vuelta a la posición inicial, extendiendo por completo las rodillas.","Repite el número de repeticiones deseado."]}},{"id":"0583","name":"lever kneeling twist","category":"waist","body_part":"waist","equipment":"leverage machine","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0583-sZOR9EV.jpg","gif_url":"videos/0583-sZOR9EV.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהברכיים מונחות על הכריות ופלג הגוף העליון פונה קדימה.","אחזו בידיות או בצידי המכשיר לייצוב.","תוך שמירה על ליבה מופעלת, סובבו את הגו לצד אחד רחוק ככל שנוח לכם.","עצרו לרגע, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על הסיבוב לצד הנגדי.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward.","Grasp the handles or the sides of the machine for stability.","Keeping your core engaged, twist your torso to one side as far as comfortably possible.","Pause for a moment, then slowly return to the starting position.","Repeat the twist to the opposite side.","Continue alternating sides for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере так, чтобы колени лежали на подушках, а верхняя часть тела была обращена вперед.","Возьмитесь за ручки или боковые стороны машины для устойчивости.","Удерживая корпус в напряжении, поверните туловище в сторону, насколько это возможно.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение.","Повторите поворот в противоположную сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con las rodillas apoyadas en las almohadillas y la parte superior del cuerpo mirando hacia adelante.","Sujeta las asas o los lados de la máquina para mayor estabilidad.","Manteniendo el core activado, gira el torso hacia un lado tanto como sea cómodamente posible.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el giro hacia el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0584","name":"lever lateral raise","category":"shoulders","body_part":"shoulders","equipment":"leverage machine","muscle_group":"traps","secondary_muscles":["traps","upper back"],"target":"delts","image":"images/0584-dRTfGZT.jpg","gif_url":"videos/0584-dRTfGZT.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהגב צמוד לכרית.","אחזו בידיות באחיזה עליונה ושמרו על ידיים ישרות.","נשפו והרימו את הידיים לצדדים עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Exhale and raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере спиной к подушке.","Возьмитесь за рукоятки прямым хватом и держите руки прямыми.","Выдохните и поднимите руки в стороны, пока они не станут параллельны полу.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.","Sujeta las asas con un agarre prono y mantén los brazos rectos.","Exhala y levanta los brazos hacia los lados hasta que queden paralelos al suelo.","Haz una pausa breve en lo alto, luego inhala y baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0585","name":"lever leg extension","category":"upper legs","body_part":"upper legs","equipment":"leverage machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"quads","image":"images/0585-my33uHU.jpg","gif_url":"videos/0585-my33uHU.gif","instruction_steps":{"he":["כווננו את גובה המושב והמשענת של המכשיר לגוף שלכם.","שבו על המכשיר כשהגב צמוד למשענת וכפות הרגליים על משטח הרגליים.","אחזו בידיות או במוטות הצד לייצוב.","יישרו את הרגליים קדימה ביישור הברכיים, בהרמת המשקל.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and backrest of the machine to fit your body.","Sit on the machine with your back against the backrest and your feet on the footpad.","Grasp the handles or sidebars for stability.","Extend your legs forward by straightening your knees, lifting the weight.","Pause for a moment at the top, then slowly lower the weight back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и спинки машины в соответствии с вашим телом.","Сядьте на тренажер, прислонившись спиной к спинке сиденья и положив ноги на подножку.","Возьмитесь за ручки или боковые перекладины для устойчивости.","Вытяните ноги вперед, выпрямив колени и подняв вес.","Задержитесь на мгновение в верхней точке, затем медленно опустите вес обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y el respaldo de la máquina a tu cuerpo.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la almohadilla para los pies.","Sujeta las asas o las barras laterales para mayor estabilidad.","Extiende las piernas hacia adelante enderezando las rodillas, levantando el peso.","Haz una pausa breve en lo alto, luego baja lentamente el peso de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0586","name":"lever lying leg curl","category":"upper legs","body_part":"upper legs","equipment":"leverage machine","muscle_group":"calves","secondary_muscles":["calves"],"target":"hamstrings","image":"images/0586-17lJ1kr.jpg","gif_url":"videos/0586-17lJ1kr.gif","instruction_steps":{"he":["כווננו את המכשיר לגוף שלכם ובחרו את המשקל הרצוי.","שכבו על הבטן על המכשיר עם רגליים ישרות והעקבים כנגד המנוף המרופד.","אחזו בידיות או בצידי המכשיר לייצוב.","תוך שמירה על פלג גוף עליון ללא תזוזה, נשפו וגלגלו את הרגליים למעלה רחוק ככל האפשר בלי להרים את האגן מהכרית.","החזיקו את התנוחה המכווצת לרגע קצר תוך כיווץ הירך האחורית.","שאפו והורידו את המנוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to fit your body and select the desired weight.","Lie face down on the machine with your legs straight and your heels against the padded lever.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up as far as possible without lifting your hips off the pad.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте тренажер под свое тело и выберите желаемый вес.","Лягте на тренажер лицом вниз, выпрямив ноги и упираясь пятками в мягкий рычаг.","Возьмитесь за ручки или боковые стороны машины для устойчивости.","Удерживая верхнюю часть тела неподвижно, выдохните и согните ноги как можно выше, не отрывая бедра от подушки.","Задержитесь в сокращенном положении на короткую паузу, сжимая мышцы задней поверхности бедра.","Вдохните и медленно опустите рычаг обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina a tu cuerpo y selecciona el peso deseado.","Túmbate boca abajo en la máquina con las piernas rectas y los talones contra la palanca acolchada.","Sujeta las asas o los lados de la máquina para mayor estabilidad.","Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia arriba tanto como sea posible sin levantar las caderas de la almohadilla.","Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales.","Inhala y baja lentamente la palanca de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3195","name":"lever lying two-one leg curl","category":"upper legs","body_part":"upper legs","equipment":"leverage machine","muscle_group":"glutes","secondary_muscles":["glutes"],"target":"hamstrings","image":"images/3195-UXpKJoq.jpg","gif_url":"videos/3195-UXpKJoq.gif","instruction_steps":{"he":["כווננו את המכשיר לגוף שלכם ושבו עליו כשהגב צמוד למשענת.","הניחו את הרגליים על כרית המנוף, מעט מעל הקרסוליים.","אחזו בידיות שבצידי המכשיר לתמיכה.","תוך שמירה על פלג גוף עליון ללא תזוזה, נשפו וגלגלו את הרגליים למעלה לכיוון הישבן.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your legs on the lever pad, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper body still, exhale and curl your legs up towards your glutes.","Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте машину по размеру вашего тела и сядьте на нее, прижавшись спиной к спинке сиденья.","Поместите ноги на подушечку рычага, чуть выше лодыжек.","Возьмитесь за ручки по бокам машины для поддержки.","Удерживая верхнюю часть тела неподвижно, выдохните и согните ноги к ягодицам.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo.","Coloca las piernas sobre la almohadilla de la palanca, justo encima de los tobillos.","Sujeta las asas a los lados de la máquina para mayor apoyo.","Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia los glúteos.","Haz una pausa breve en lo alto, luego inhala y baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0587","name":"lever military press","category":"shoulders","body_part":"shoulders","equipment":"leverage machine","muscle_group":"triceps","secondary_muscles":["triceps","upper chest"],"target":"delts","image":"images/0587-CggQhII.jpg","gif_url":"videos/0587-CggQhII.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהגב צמוד למשענת.","אחזו בידיות באחיזה עליונה ומקמו את הידיים מעט רחב מרוחב הכתפיים.","דחפו את הידיות כלפי מעלה עד יישור מלא של הידיים, אך אל תנעלו את המרפקים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на машине спиной к спинке сиденья.","Возьмитесь за рукоятки хватом сверху и поставьте руки чуть шире плеч.","Толкайте ручки вверх до тех пор, пока руки полностью не выпрямятся, но не сгибайте локти.","Задержитесь на мгновение в верхней точке, затем медленно опустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo.","Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros.","Empuja las asas hacia arriba hasta que los brazos queden completamente extendidos, pero sin bloquear los codos.","Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0588","name":"lever narrow grip seated row","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0588-IGjKj1v.jpg","gif_url":"videos/0588-IGjKj1v.gif","instruction_steps":{"he":["כווננו את גובה המושב ומשענות הרגליים לטכניקה נכונה.","שבו על המכשיר עם כפות רגליים על משענות הרגליים וברכיים כפופות מעט.","אחזו בידיות באחיזה צרה, כפות ידיים פונות זו לזו.","שמרו על גב ישר והיטו מעט קדימה.","משכו את הידיות לכיוון הגו, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה.","שחררו באיטיות את הידיות וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and footrests to ensure proper form.","Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with a narrow grip, palms facing each other.","Keep your back straight and lean slightly forward.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и подножек, чтобы обеспечить правильную форму.","Сядьте на тренажер, поставьте ноги на подножки и слегка согните колени.","Возьмитесь за ручки узким хватом, ладони обращены друг к другу.","Держите спину прямо и слегка наклонитесь вперед.","Потяните ручки к туловищу, сжимая лопатки вместе.","Сделайте паузу на мгновение в пике движения.","Медленно отпустите ручки и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y los apoyapiés para asegurar una postura correcta.","Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra.","Mantén la espalda recta e inclínate ligeramente hacia adelante.","Tira de las asas hacia el torso, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento.","Suelta lentamente las asas y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0589","name":"lever one arm bent over row","category":"back","body_part":"back","equipment":"barbell","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0589-Fhdtwf3.jpg","gif_url":"videos/0589-Fhdtwf3.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, ברכיים כפופות מעט, ואחזו מוט באחיזה עליונה.","הטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר וראש מורם.","תנו למוט להשתלשל לפניכם עם ידיים ישרות לגמרי.","משכו את המוט למעלה לכיוון החזה, תוך שמירה על מרפקים קרובים לגוף.","כווצו את השכמות זו לזו בנקודה העליונה של התנועה.","הורידו את המוט חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip.","Bend forward at the hips, keeping your back straight and your head up.","Let the barbell hang in front of you with your arms fully extended.","Pull the barbell up towards your chest, keeping your elbows close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, слегка согнуты в коленях, возьмите штангу хватом сверху.","Наклонитесь вперед в бедрах, держа спину прямо и голову вверх.","Пусть штанга висит перед вами, руки полностью вытянуты.","Подтяните штангу к груди, держа локти близко к телу.","В верхней точке движения сведите лопатки вместе.","Опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con agarre prono.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la cabeza erguida.","Deja que la barra cuelgue frente a ti con los brazos completamente extendidos.","Tira de la barra hacia el pecho, manteniendo los codos cerca del cuerpo.","Junta los omóplatos en la parte superior del movimiento.","Baja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1356","name":"lever one arm lateral high row","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/1356-OIFMAp1.jpg","gif_url":"videos/1356-OIFMAp1.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו מול המכשיר.","אחזו בידית ביד אחת ושמרו על גב ישר.","משכו את הידית לכיוון הגוף, תוך שמירה על מרפק קרוב לצד.","כווצו את שרירי הגב בנקודה העליונה של התנועה.","שחררו באיטיות את הידית חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself facing the machine.","Grasp the handle with one hand and keep your back straight.","Pull the handle towards your body, keeping your elbow close to your side.","Squeeze your back muscles at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь лицом к машине.","Возьмитесь за рукоятку одной рукой и держите спину прямо.","Потяните рукоятку к себе, держа локоть близко к боку.","Напрягите мышцы спины в верхней точке движения.","Медленно отпустите ручку обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate frente a la máquina.","Sujeta el asa con una mano y mantén la espalda recta.","Tira del asa hacia el cuerpo, manteniendo el codo cerca del costado.","Aprieta los músculos de la espalda en la parte superior del movimiento.","Suelta lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1347","name":"lever one arm lateral wide pulldown","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/1347-tTuZSDT.jpg","gif_url":"videos/1347-tTuZSDT.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהחזה צמוד לכרית וכפות הרגליים על הרצפה.","אחזו בידית באחיזה עליונה ומתחו את היד לגמרי, עם כיפוף קל במרפק.","משכו את הידית מטה ובאלכסון על פני הגוף לכיוון המותן הנגדית, בכיווץ רחב הגבי בסוף התנועה.","החזירו באיטיות את הידית לנקודת ההתחלה, עד יישור מלא של היד.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow.","Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement.","Slowly return the handle to the starting position, fully extending your arm.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере так, чтобы грудь опиралась на подушку, а ступни стояли на полу.","Возьмитесь за рукоятку хватом сверху и полностью выпрямите руку, сохраняя небольшой изгиб в локте.","Потяните рукоятку вниз и поперек тела к противоположному бедру, сжимая широчайшие мышцы в нижней части движения.","Медленно верните рукоятку в исходное положение, полностью выпрямляя руку.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.","Sujeta el asa con un agarre prono y extiende el brazo por completo, manteniendo una ligera flexión en el codo.","Tira del asa hacia abajo y a través del cuerpo en dirección a la cadera opuesta, apretando el dorsal en la parte baja del movimiento.","Devuelve lentamente el asa a la posición inicial, extendiendo el brazo por completo.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0590","name":"lever one arm shoulder press","category":"shoulders","body_part":"shoulders","equipment":"leverage machine","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0590-2KGnL6M.jpg","gif_url":"videos/0590-2KGnL6M.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהגב צמוד לכרית.","אחזו בידית המנוף ביד אחת ומקמו את המרפק בזווית של 90 מעלות.","לחצו את המנוף כלפי מעלה עד יישור מלא של היד מעל הראש.","עצרו לרגע בנקודה העליונה, ואז הורידו את המנוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the lever handle with one hand and position your elbow at a 90-degree angle.","Press the lever upward until your arm is fully extended overhead.","Pause for a moment at the top, then slowly lower the lever back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере спиной к подушке.","Возьмитесь за рукоятку рычага одной рукой и расположите локоть под углом 90 градусов.","Нажмите рычаг вверх, пока ваша рука полностью не выпрямится над головой.","Задержитесь на мгновение в верхней точке, затем медленно опустите рычаг обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.","Sujeta el asa de la palanca con una mano y coloca el codo en un ángulo de 90 grados.","Presiona la palanca hacia arriba hasta que el brazo quede completamente extendido por encima de la cabeza.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"0591","name":"lever overhand triceps dip","category":"upper arms","body_part":"upper arms","equipment":"leverage machine","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0591-D5yqP2p.jpg","gif_url":"videos/0591-D5yqP2p.gif","instruction_steps":{"he":["כווננו את המכשיר לגובה המתאים וקבעו את הגוף בתנוחה.","אחזו בידיות באחיזה עליונה ומקמו את הגוף כך שהידיים מתוחות לגמרי.","הורידו את הגוף בכיפוף מרפקים, תוך שמירה על הזרועות העליונות צמודות לצידי הגוף.","המשיכו לרדת עד שהזרועות העליונות מקבילות לרצפה.","עצרו לרגע, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור המרפקים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to the appropriate height and secure your body in position.","Grasp the handles with an overhand grip and position your body so that your arms are fully extended.","Lower your body by bending your elbows, keeping your upper arms close to your sides.","Continue lowering until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте машину на нужную высоту и зафиксируйте свое тело в нужном положении.","Возьмитесь за рукоятки хватом сверху и расположите тело так, чтобы руки были полностью выпрямлены.","Опустите тело, согнув локти, держа плечи близко к бокам.","Продолжайте опускаться до тех пор, пока плечи не станут параллельны полу.","Сделайте паузу на мгновение, затем вернитесь в исходное положение, разгибая локти.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina a la altura adecuada y asegura tu cuerpo en posición.","Sujeta las asas con un agarre prono y coloca el cuerpo de modo que los brazos queden completamente extendidos.","Baja el cuerpo flexionando los codos, manteniendo los brazos superiores cerca de los costados.","Continúa bajando hasta que los brazos superiores queden paralelos al suelo.","Haz una pausa breve, luego empújate de vuelta hacia arriba a la posición inicial extendiendo los codos.","Repite el número de repeticiones deseado."]}},{"id":"0592","name":"lever preacher curl","category":"upper arms","body_part":"upper arms","equipment":"leverage machine","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0592-b6hQYMb.jpg","gif_url":"videos/0592-b6hQYMb.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על מכונת המנוף.","הניחו את הזרועות העליונות על הכרית ואחזו בידיות באחיזה תחתונה.","שמרו על גב ישר ומרפקים ממוקמים על הכרית.","נשפו וכופפו את האמות לכיוון הזרועות העליונות, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","שאפו והורידו את הידיות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the pad and grip the handles with an underhand grip.","Keep your back straight and your elbows positioned on the pad.","Exhale and curl your forearms towards your upper arms, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на рычаге машины.","Положите плечи на подушку и возьмитесь за рукоятки хватом снизу.","Держите спину прямо, а локти положите на подушку.","Выдохните и согните предплечья к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Вдохните и медленно опустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina de palanca.","Coloca los brazos superiores en la almohadilla y sujeta las asas con un agarre supino.","Mantén la espalda recta y los codos colocados sobre la almohadilla.","Exhala y flexiona los antebrazos hacia los brazos superiores, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1614","name":"lever preacher curl v. 2","category":"upper arms","body_part":"upper arms","equipment":"leverage machine","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1614-ye84CTU.jpg","gif_url":"videos/1614-ye84CTU.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהזרועות העליונות מונחות על הכרית והחזה צמוד למשענת.","אחזו בידיות באחיזה תחתונה, מעט רחבה מרוחב הכתפיים.","שמרו על זרועות עליונות ללא תזוזה ונשפו תוך כיפוף הידיות לכיוון הכתפיים, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","שאפו תוך הורדת הידיות באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support.","Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Keep your upper arms stationary and exhale as you curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale as you slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере так, чтобы плечи лежали на подушке, а грудь – на опоре.","Возьмитесь за ручки хватом снизу, на расстоянии чуть шире ширины плеч.","Держите плечи неподвижно и на выдохе подтягивайте рукоятки к плечам, сокращая бицепсы.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","На вдохе медленно опускайте рукоятки обратно в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con los brazos superiores apoyados en la almohadilla y el pecho contra el soporte.","Sujeta las asas con un agarre supino, un poco más separadas que la altura de los hombros.","Mantén los brazos superiores inmóviles y exhala mientras flexionas las asas hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala mientras bajas lentamente las asas de vuelta a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."]}},{"id":"2285","name":"lever pullover","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"lats","image":"images/2285-4U7iLb5.jpg","gif_url":"videos/2285-4U7iLb5.gif","instruction_steps":{"he":["כווננו את המושב והידיות של מכונת המנוף לתנוחה נוחה.","שבו על המכשיר כשהגב צמוד לכרית ואחזו בידיות באחיזה עליונה.","שמרו על ידיים כפופות מעט וליבה מופעלת.","משכו באיטיות את הידיות לכיוון החזה, בכיווץ רחב הגבי.","עצרו לרגע בשיא הכיווץ, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat and handles of the leverage machine to a comfortable position.","Sit on the machine with your back against the pad and grasp the handles with an overhand grip.","Keep your arms slightly bent and your core engaged.","Slowly pull the handles towards your chest, squeezing your lats.","Pause for a moment at the peak contraction, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сиденье и ручки рычага машины в удобное положение.","Сядьте на тренажер, прислонившись спиной к подушке, и возьмитесь за рукоятки верхним хватом.","Держите руки слегка согнутыми, а корпус напряженным.","Медленно потяните ручки к груди, сжимая широчайшие мышцы.","Сделайте паузу на мгновение в момент максимального сокращения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta el asiento y las asas de la máquina de palanca a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en la almohadilla y sujeta las asas con un agarre prono.","Mantén los brazos ligeramente flexionados y el core activado.","Tira lentamente de las asas hacia el pecho, apretando los dorsales.","Haz una pausa breve en el punto máximo de contracción, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2736","name":"lever reverse grip lateral pulldown","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/2736-ky8FLU8.jpg","gif_url":"videos/2736-ky8FLU8.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהברכיים מתחת לכריות וכפות הרגליים על הרצפה.","אחזו בידיות באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שבו זקוף עם חזה מורם וכתפיים לאחור, תוך שמירה על קשת קלה בגב התחתון.","משכו את הידיות מטה לכיוון החזה, כשהמרפקים מובילים וכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, ואז שחררו באיטיות את הידיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на машине так, чтобы колени находились под подушками, а ступни стояли на земле.","Возьмитесь за ручки хватом сверху, на расстоянии чуть шире плеч.","Сядьте прямо, вытянув грудь и отведя плечи назад, сохраняя небольшой изгиб в пояснице.","Потяните ручки вниз к груди, ведя локти и сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно отпустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Siéntate erguido con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar.","Tira de las asas hacia el pecho, liderando con los codos y juntando los omóplatos.","Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1616","name":"lever reverse grip preacher curl","category":"upper arms","body_part":"upper arms","equipment":"leverage machine","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1616-kj3hy6W.jpg","gif_url":"videos/1616-kj3hy6W.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על מכונת המנוף.","אחזו בידיות באחיזה תחתונה, כפות ידיים כלפי מעלה.","הניחו את הזרועות העליונות על כרית הפריצ'ר, וודאו שהמרפקים מתוחים לגמרי.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את הידיות לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","שאפו והורידו את הידיות באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של המרפקים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with an underhand grip, palms facing up.","Rest your upper arms on the preacher pad, ensuring your elbows are fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на рычаге машины.","Возьмитесь за ручки хватом снизу ладонями вверх.","Положите плечи на коврик для проповедника, убедившись, что локти полностью выпрямлены.","Удерживая плечи неподвижно, выдохните и согните ручки к плечам.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Вдохните и медленно опустите ручки обратно в исходное положение, полностью разгибая локти.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina de palanca.","Sujeta las asas con un agarre supino, con las palmas hacia arriba.","Apoya los brazos superiores sobre la almohadilla de predicador, asegurándote de que los codos queden completamente extendidos.","Manteniendo los brazos superiores inmóviles, exhala y flexiona las asas hacia los hombros.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente las agarraderas de vuelta a la posición inicial, extendiendo los codos por completo.","Repite el número de repeticiones deseado."]}},{"id":"1348","name":"lever reverse grip vertical row","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1348-ZqNOWQ6.jpg","gif_url":"videos/1348-ZqNOWQ6.gif","instruction_steps":{"he":["כווננו את גובה המושב ומיקום משטח הרגליים ליישור נכון של הגוף.","שבו על המכשיר כשהחזה צמוד לכרית וכפות הרגליים על משטח הרגליים.","אחזו בידיות באחיזה תחתונה, כפות ידיים כלפי מעלה.","שמרו על גב ישר והפעילו את שרירי הליבה.","משכו את הידיות לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה, ואז שחררו באיטיות ויישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an underhand grip, palms facing up.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и положение подножки, чтобы обеспечить правильное выравнивание.","Сядьте на тренажер, прижав грудь к подушке и положив ноги на подножку.","Возьмитесь за ручки хватом снизу ладонями вверх.","Держите спину прямо и задействуйте корпус.","Потяните ручки к груди, сведя лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения, затем медленно расслабьтесь и вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta.","Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies.","Sujeta las asas con un agarre supino, con las palmas hacia arriba.","Mantén la espalda recta y activa el core.","Tira de las asas hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0593","name":"lever reverse hyperextension","category":"upper legs","body_part":"upper legs","equipment":"leverage machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0593-Krmb3cB.jpg","gif_url":"videos/0593-Krmb3cB.gif","instruction_steps":{"he":["כווננו את מכונת המנוף לגוף שלכם וקבעו את כפות הרגליים בכריות הרגליים.","שכבו על הבטן על המכשיר כשפלג הגוף העליון משתלשל מהקצה והאגן מונח על הכרית.","הצליבו את הידיים על החזה או הניחו אותן מאחורי הראש.","הפעילו את הישבן והירך האחורית להרמת הרגליים כלפי מעלה עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the leverage machine to fit your body and secure your feet in the foot pads.","Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.","Cross your arms over your chest or place them behind your head.","Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте рычаг тренажера так, чтобы он соответствовал вашему телу, и зафиксируйте ноги в подушечках для ног.","Лягте лицом вниз на тренажер, свесив верхнюю часть тела с края и положив бедра на подушку.","Скрестите руки на груди или заведите их за голову.","Задействуйте ягодицы и мышцы задней поверхности бедра, чтобы поднять ноги вверх, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de palanca a tu cuerpo y asegura los pies en las almohadillas para los pies.","Túmbate boca abajo en la máquina con la parte superior del cuerpo colgando fuera del borde y las caderas apoyadas en la almohadilla.","Cruza los brazos sobre el pecho o colócalos detrás de la cabeza.","Activa los glúteos y los isquiotibiales para levantar las piernas hacia arriba hasta que queden paralelas al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1349","name":"lever reverse t-bar row","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1349-BgljGjd.jpg","gif_url":"videos/1349-BgljGjd.gif","instruction_steps":{"he":["כווננו את גובה המושב ומיקום משטח הרגליים במכונת המנוף.","שבו על המכשיר כשהחזה צמוד לכרית וכפות הרגליים על משטח הרגליים.","אחזו בידיות באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שמרו על גב ישר והפעילו את שרירי הליבה.","משכו את הידיות לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה, ואז שחררו באיטיות ויישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and footplate position on the leverage machine.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и положение подножки на рычаге машины.","Сядьте на тренажер, прижав грудь к подушке и положив ноги на подножку.","Возьмитесь за ручки хватом сверху, на расстоянии чуть шире плеч.","Держите спину прямо и задействуйте корпус.","Потяните ручки к груди, сведя лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения, затем медленно расслабьтесь и вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y la posición de la placa para los pies en la máquina de palanca.","Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y activa el core.","Tira de las asas hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2315","name":"lever rotary calf","category":"lower legs","body_part":"lower legs","equipment":"leverage machine","muscle_group":"soleus","secondary_muscles":["soleus","ankle stabilizers"],"target":"calves","image":"images/2315-MrgP9L6.jpg","gif_url":"videos/2315-MrgP9L6.gif","instruction_steps":{"he":["כווננו את גובה המושב כך שהברכיים כפופות מעט וכפות הרגליים שטוחות על משטח הרגליים.","הניחו את קצות האצבעות של הרגליים על משטח הרגליים, עם העקבים משתלשלים מעבר לקצה.","אחזו בידיות או בצידי המכשיר לייצוב.","דחפו דרך כריות כפות הרגליים, בהרמת העקבים גבוה ככל האפשר.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Place your toes on the footplate, with your heels hanging off the edge.","Grasp the handles or the sides of the machine for stability.","Push through the balls of your feet, raising your heels as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья так, чтобы ваши колени были слегка согнуты, а ступни лежали на подножке.","Поставьте пальцы ног на подножку так, чтобы пятки свисали с края.","Возьмитесь за ручки или боковые стороны машины для устойчивости.","Оттолкнитесь подушечками стоп, поднимая пятки как можно выше.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies.","Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde.","Sujeta las asas o los lados de la máquina para mayor estabilidad.","Empuja con la parte delantera de los pies, elevando los talones tan alto como sea posible.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2335","name":"lever seated calf press","category":"lower legs","body_part":"lower legs","equipment":"leverage machine","muscle_group":"soleus","secondary_muscles":["soleus","hamstrings"],"target":"calves","image":"images/2335-Ie9UGty.jpg","gif_url":"videos/2335-Ie9UGty.gif","instruction_steps":{"he":["כווננו את מושב המכשיר כך שהכתפיים בקו אחד עם כרית המנוף.","הניחו את קצות האצבעות של הרגליים על החלק התחתון של המשטח ומקמו את הברכיים מתחת לכרית המנוף.","אחזו בידיות שבצידי המושב לייצוב.","לחצו את כרית המנוף מטה ביישור הקרסוליים, בהרמת העקבים גבוה ככל האפשר.","עצרו לרגע בנקודה העליונה של התנועה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat of the machine so that your shoulders are aligned with the lever pad.","Place your toes on the lower portion of the platform and position your knees under the lever pad.","Grasp the handles on the sides of the seat for stability.","Press the lever pad down by extending your ankles, lifting your heels as high as possible.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сиденье тренажера так, чтобы ваши плечи находились на одной линии с подушечкой рычага.","Поместите пальцы ног на нижнюю часть платформы и расположите колени под накладкой рычага.","Возьмитесь за ручки по бокам сиденья для устойчивости.","Нажмите на подушечку рычага вниз, вытянув лодыжки и подняв пятки как можно выше.","Сделайте паузу на мгновение в верхней точке движения, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta el asiento de la máquina de modo que los hombros queden alineados con la almohadilla de la palanca.","Coloca los dedos de los pies en la parte inferior de la plataforma y posiciona las rodillas debajo de la almohadilla de la palanca.","Sujeta las asas a los lados del asiento para mayor estabilidad.","Presiona la almohadilla de la palanca hacia abajo extendiendo los tobillos, elevando los talones tan alto como sea posible.","Haz una pausa breve en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0594","name":"lever seated calf raise","category":"lower legs","body_part":"lower legs","equipment":"leverage machine","muscle_group":"soleus","secondary_muscles":["soleus","ankle stabilizers"],"target":"calves","image":"images/0594-bOOdeyc.jpg","gif_url":"videos/0594-bOOdeyc.gif","instruction_steps":{"he":["כווננו את גובה המושב כך שהברכיים כפופות מעט וכפות הרגליים שטוחות על משטח הרגליים.","הניחו את קצות האצבעות של הרגליים על משטח הרגליים, כשהעקבים משתלשלים מעבר לקצה.","אחזו בידיות או בצידי המושב לייצוב.","דחפו דרך כריות כפות הרגליים להרמת העקבים גבוה ככל האפשר.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Place your toes on the footplate with your heels hanging off the edge.","Grasp the handles or the sides of the seat for stability.","Push through the balls of your feet to raise your heels as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья так, чтобы ваши колени были слегка согнуты, а ступни лежали на подножке.","Поместите пальцы ног на подножку так, чтобы пятки свисали с края.","Возьмитесь за ручки или боковые стороны сиденья для устойчивости.","Оттолкнитесь подушечками стоп, чтобы поднять пятки как можно выше.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies.","Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde.","Sujeta las asas o los lados del asiento para mayor estabilidad.","Empuja con la parte delantera de los pies para elevar los talones tan alto como sea posible.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1452","name":"lever seated crunch","category":"waist","body_part":"waist","equipment":"leverage machine","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/1452-Wgaz7pm.jpg","gif_url":"videos/1452-Wgaz7pm.gif","instruction_steps":{"he":["שבו על מכונת המנוף כשהגב צמוד לכרית וכפות הרגליים על הרצפה.","אחזו בידיות או הניחו את הידיים על כריות הצד לתמיכה.","הפעילו את שרירי הבטן והיטו באיטיות לאחור, ותנו לכרית לנוע איתכם.","כשפלג הגוף העליון בזווית של 45 מעלות, כווצו את שרירי הבטן וגלגלו קדימה, בהבאת החזה לכיוון הברכיים.","עצרו לרגע בנקודה העליונה, ואז שחררו באיטיות וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the leverage machine with your back against the pad and your feet flat on the floor.","Grasp the handles or place your hands on the side pads for support.","Engage your abs and slowly lean back, allowing the pad to move with you.","Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на тренажер, прислонившись спиной к подушке, а ступни поставьте на пол.","Возьмитесь за ручки или положите руки на боковые подушечки для поддержки.","Напрягите пресс и медленно откиньтесь назад, позволяя подушечке двигаться вместе с вами.","Как только верхняя часть тела окажется под углом 45 градусов, напрягите пресс и наклонитесь вперед, приближая грудь к коленям.","Задержитесь на мгновение в верхней точке, затем медленно расслабьтесь и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en la máquina de palanca con la espalda apoyada en la almohadilla y los pies planos en el suelo.","Sujeta las asas o coloca las manos sobre las almohadillas laterales para mayor apoyo.","Activa el abdomen e inclínate lentamente hacia atrás, dejando que la almohadilla se mueva contigo.","Cuando la parte superior del cuerpo esté en un ángulo de 45 grados, contrae el abdomen y haz un crunch hacia adelante, llevando el pecho hacia las rodillas.","Haz una pausa breve en lo alto, luego suelta lentamente y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0595","name":"lever seated crunch (chest pad)","category":"waist","body_part":"waist","equipment":"leverage machine","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0595-ZnJHhMk.jpg","gif_url":"videos/0595-ZnJHhMk.gif","instruction_steps":{"he":["כווננו את גובה המושב ומיקום כרית החזה לנוחותכם.","שבו על המכשיר כשהגב צמוד לכרית החזה וכפות הרגליים על הרצפה.","אחזו בידיות או במוטות הצד לייצוב.","הפעילו את שרירי הבטן והיטו באיטיות לאחור, ותנו לכרית החזה לנוע איתכם.","עצרו לרגע בכיווץ המקסימלי, בתחושת המתח בשרירי הבטן.","חזרו באיטיות לנקודת ההתחלה בכיווץ שרירי הבטן ומשיכת עצמכם חזרה למעלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and chest pad position according to your comfort.","Sit on the machine with your back against the chest pad and your feet flat on the floor.","Grasp the handles or side bars for stability.","Engage your abs and slowly lean back, allowing the chest pad to move with you.","Pause for a moment at the maximum contraction, feeling the tension in your abs.","Slowly return to the starting position by contracting your abs and pulling yourself back up.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и положение подкладки для груди в соответствии с вашим комфортом.","Сядьте на тренажер, прислонившись спиной к нагруднику, а ступни поставьте на пол.","Возьмитесь за ручки или боковые перекладины для устойчивости.","Напрягите пресс и медленно откиньтесь назад, позволяя подушечке для груди двигаться вместе с вами.","Сделайте паузу на мгновение при максимальном сокращении, чувствуя напряжение в прессе.","Медленно вернитесь в исходное положение, напрягая пресс и подтягиваясь обратно вверх.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y la posición de la almohadilla para el pecho según tu comodidad.","Siéntate en la máquina con la espalda apoyada en la almohadilla para el pecho y los pies planos en el suelo.","Sujeta las asas o las barras laterales para mayor estabilidad.","Activa el abdomen y reclínate lentamente hacia atrás, permitiendo que el respaldo se mueva contigo.","Haz una pausa en la contracción máxima, sintiendo la tensión en el abdomen.","Vuelve lentamente a la posición inicial contrayendo el abdomen y tirando de tu cuerpo hacia arriba.","Repite el número de repeticiones deseado."]}},{"id":"3760","name":"lever seated crunch v. 2","category":"waist","body_part":"waist","equipment":"leverage machine","muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/3760-eXFXCY0.jpg","gif_url":"videos/3760-eXFXCY0.gif","instruction_steps":{"he":["שבו על מכונת המנוף כשהגב צמוד לכרית וכפות הרגליים מקובעות מתחת לכריות הרגליים.","הניחו את הידיים על הידיות או על צידי המושב לתמיכה.","הפעילו את שרירי הבטן והתגלגלו באיטיות קדימה, בהבאת החזה לכיוון הברכיים.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ שרירי הבטן.","חזרו באיטיות לנקודת ההתחלה, ותנו לגב להתעגל מעט.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the leverage machine with your back against the pad and your feet secured under the footpads.","Place your hands on the handles or the sides of the seat for support.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly return to the starting position, allowing your back to round slightly.","Repeat for the desired number of repetitions."],"ru":["Сядьте на тренажер, прислонившись спиной к подушке и зафиксировав ноги под подушечками.","Положите руки на ручки или по бокам сиденья для поддержки.","Напрягите пресс и медленно наклонитесь вперед, приближая грудь к коленям.","Задержитесь на мгновение в верхней точке движения, напрягая пресс.","Медленно вернитесь в исходное положение, слегка округляя спину.","Повторите необходимое количество повторений."],"es":["Siéntate en la máquina de palanca con la espalda apoyada en el respaldo y los pies sujetos bajo las almohadillas.","Coloca las manos en las asas o en los lados del asiento para mayor apoyo.","Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando el pecho hacia las rodillas.","Haz una pausa por un momento en la parte superior del movimiento, apretando el abdomen.","Vuelve lentamente a la posición inicial, dejando que tu espalda se redondee ligeramente.","Repite el número de repeticiones deseado."]}},{"id":"1451","name":"lever seated dip","category":"upper arms","body_part":"upper arms","equipment":"leverage machine","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1451-BRImeP8.jpg","gif_url":"videos/1451-BRImeP8.gif","instruction_steps":{"he":["כווננו את גובה המושב כך שכפות הרגליים על הרצפה והברכיים בזווית של 90 מעלות.","אחזו בידיות מכונת המנוף עם כפות ידיים כלפי מטה וידיים ישרות לגמרי.","הורידו באיטיות את הגוף בכיפוף מרפקים עד שהזרועות העליונות מקבילות לרצפה.","עצרו לרגע, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.","Grasp the handles of the leverage machine with your palms facing down and your arms fully extended.","Slowly lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья так, чтобы ваши ступни стояли ровно на земле, а колени находились под углом 90 градусов.","Возьмитесь за рукоятки тренажера ладонями вниз и полностью выпрямите руки.","Медленно опустите тело, сгибая локти, пока плечи не станут параллельны земле.","Сделайте паузу на мгновение, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento de modo que tus pies queden planos en el suelo y tus rodillas formen un ángulo de 90 grados.","Agarra las asas de la máquina de palanca con las palmas hacia abajo y los brazos completamente extendidos.","Baja lentamente el cuerpo flexionando los codos hasta que tus brazos queden paralelos al suelo.","Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0596","name":"lever seated fly","category":"chest","body_part":"chest","equipment":"leverage machine","muscle_group":"deltoids","secondary_muscles":["deltoids","trapezius"],"target":"pectorals","image":"images/0596-v3xmPAR.jpg","gif_url":"videos/0596-v3xmPAR.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהגב צמוד לכרית.","אחזו בידיות באחיזה עליונה ושמרו על מרפקים כפופים מעט.","נשפו ודחפו את הידיות קדימה, בהבאתן יחד מול החזה.","עצרו לרגע, תוך כיווץ שרירי החזה.","שאפו וחזרו באיטיות לנקודת ההתחלה, ותנו לשרירי החזה להימתח.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with a pronated grip and keep your elbows slightly bent.","Exhale and push the handles forward, bringing them together in front of your chest.","Pause for a moment, squeezing your chest muscles.","Inhale and slowly return to the starting position, allowing your chest muscles to stretch.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере спиной к подушке.","Возьмитесь за рукоятки пронированным хватом и держите локти слегка согнутыми.","Выдохните и вытолкните ручки вперед, соединив их перед грудью.","Сделайте паузу на мгновение, напрягая мышцы груди.","Вдохните и медленно вернитесь в исходное положение, позволяя мышцам груди растягиваться.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.","Agarra las asas con un agarre pronado y mantén los codos ligeramente flexionados.","Exhala y empuja las asas hacia adelante, juntándolas frente a tu pecho.","Haz una pausa por un momento, contrayendo los músculos del pecho.","Inhala y vuelve lentamente a la posición inicial, permitiendo que los músculos del pecho se estiren.","Repite el número de repeticiones deseado."]}},{"id":"3759","name":"lever seated good morning","category":"upper legs","body_part":"upper legs","equipment":"leverage machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/3759-XsCcxCC.jpg","gif_url":"videos/3759-XsCcxCC.gif","instruction_steps":{"he":["כווננו את גובה המושב כך שהאגן מעט גבוה מהברכיים.","שבו על המכשיר כשהגב צמוד לכרית וכפות הרגליים על משענות הרגליים.","אחזו בידיות או בצידי המושב לייצוב.","תוך שמירה על גב ישר, הטו באיטיות את הגו קדימה מהירכיים עד שפלג הגוף העליון מקביל לרצפה.","עצרו לרגע, ואז חזרו באיטיות לנקודת ההתחלה בדחיפה דרך הישבן והירך האחורית.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height so that your hips are slightly higher than your knees.","Sit on the machine with your back against the pad and your feet flat on the footrests.","Grasp the handles or the sides of the seat for stability.","Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.","Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья так, чтобы бедра были немного выше колен.","Сядьте на тренажер, прислонившись спиной к подушке, а ноги поставьте на подножки.","Возьмитесь за ручки или боковые стороны сиденья для устойчивости.","Удерживая спину прямо, медленно наклонитесь вперед от бедер, пока верхняя часть тела не станет параллельна земле.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение, напрягая ягодицы и мышцы задней поверхности бедра.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento de modo que tus caderas queden un poco más altas que tus rodillas.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos sobre los apoyapiés.","Sujeta las asas o los lados del asiento para mayor estabilidad.","Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas hasta que la parte superior de tu cuerpo quede paralela al suelo.","Haz una pausa por un momento y luego vuelve lentamente a la posición inicial empujando con los glúteos y los isquiotibiales.","Repite el número de repeticiones deseado."]}},{"id":"0597","name":"lever seated hip abduction","category":"upper legs","body_part":"upper legs","equipment":"leverage machine","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"abductors","image":"images/0597-CHpahtl.jpg","gif_url":"videos/0597-CHpahtl.gif","instruction_steps":{"he":["כווננו את גובה המושב כך שהברכיים בזווית של 90 מעלות.","שבו על המכשיר כשהגב צמוד למשענת וכפות הרגליים על משענות הרגליים.","הניחו את הידיים על ידיות הצד לייצוב.","הפעילו את מרחיקי הירך ודחפו באיטיות את הרגליים זו מזו, הרחק מקו האמצע של הגוף.","עצרו לרגע בסוף התנועה, ואז החזירו באיטיות את הרגליים יחד לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height so that your knees are at a 90-degree angle.","Sit on the machine with your back against the backrest and your feet on the footrests.","Place your hands on the side handles for stability.","Engage your abductors and slowly push your legs apart, away from the midline of your body.","Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья так, чтобы колени находились под углом 90 градусов.","Сядьте на тренажер, прислонившись спиной к спинке сиденья и положив ноги на подножки.","Положите руки на боковые ручки для устойчивости.","Включите похитители и медленно разведите ноги в стороны от средней линии тела.","В конце движения сделайте паузу на мгновение, затем медленно верните ноги вместе в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento de modo que tus rodillas formen un ángulo de 90 grados.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre los apoyapiés.","Coloca las manos en las asas laterales para mayor estabilidad.","Activa los abductores y empuja lentamente las piernas hacia afuera, alejándolas de la línea media del cuerpo.","Haz una pausa al final del movimiento y luego junta lentamente las piernas de nuevo hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0598","name":"lever seated hip adduction","category":"upper legs","body_part":"upper legs","equipment":"leverage machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"adductors","image":"images/0598-oHsrypV.jpg","gif_url":"videos/0598-oHsrypV.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהגב צמוד למשענת.","הניחו את כפות הרגליים על משענות הרגליים ואחזו בידיות לייצוב.","הפעילו את מקרבי הירך והביאו באיטיות את הרגליים יחד, בכיווץ הירכיים הפנימיות.","עצרו לרגע בשיא הכיווץ, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your back against the backrest.","Place your feet on the footrests and grasp the handles for stability.","Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs.","Pause for a moment at the peak contraction, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на машине спиной к спинке сиденья.","Поставьте ноги на подножки и возьмитесь за ручки для устойчивости.","Напрягите приводящие мышцы и медленно сведите ноги вместе, сжимая внутреннюю поверхность бедер.","Сделайте паузу на мгновение в момент максимального сокращения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo.","Coloca los pies sobre los apoyapiés y agarra las asas para mayor estabilidad.","Activa los aductores y junta lentamente las piernas, apretando la parte interna de los muslos.","Haz una pausa breve en el punto máximo de contracción, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0599","name":"lever seated leg curl","category":"upper legs","body_part":"upper legs","equipment":"leverage machine","muscle_group":"calves","secondary_muscles":["calves"],"target":"hamstrings","image":"images/0599-Zg3XY7P.jpg","gif_url":"videos/0599-Zg3XY7P.gif","instruction_steps":{"he":["כווננו את המכשיר לגוף שלכם ושבו עליו כשהגב צמוד למשענת.","הניחו את השוקיים מתחת למנוף המרופד, מעט מעל הקרסוליים.","אחזו בידיות שבצידי המכשיר לתמיכה.","תוך שמירה על הירכיים ללא תזוזה, נשפו וגלגלו את הרגליים למעלה רחוק ככל האפשר.","החזיקו את התנוחה המכווצת לרגע קצר תוך כיווץ הירך האחורית.","שאפו והורידו את המנוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your lower legs under the padded lever, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper legs stationary, exhale and curl your legs up as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте машину по размеру вашего тела и сядьте на нее, прижавшись спиной к спинке сиденья.","Поместите голени под мягкий рычаг, чуть выше лодыжек.","Возьмитесь за ручки по бокам машины для поддержки.","Удерживая верхнюю часть ног неподвижно, выдохните и согните ноги как можно сильнее.","Задержитесь в сокращенном положении на короткую паузу, сжимая мышцы задней поверхности бедра.","Вдохните и медленно опустите рычаг обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo.","Coloca la parte baja de las piernas debajo de la palanca acolchada, justo por encima de los tobillos.","Sujeta las asas a los lados de la máquina para mayor apoyo.","Manteniendo la parte superior de las piernas inmóvil, exhala y flexiona las piernas hacia arriba todo lo que puedas.","Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales.","Inhala y baja lentamente la palanca de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0600","name":"lever seated leg raise crunch","category":"waist","body_part":"waist","equipment":"leverage machine","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0600-PQ2AtC3.jpg","gif_url":"videos/0600-PQ2AtC3.gif","instruction_steps":{"he":["שבו על מכונת המנוף כשהגב צמוד למשענת וכפות הרגליים על משענות הרגליים.","אחזו בידיות או במוטות הצד לייצוב.","הפעילו את שרירי הבטן והרימו באיטיות את הרגליים לכיוון החזה, תוך גלגול הגו קדימה בו-זמנית.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את הרגליים והגו חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the leverage machine with your back against the backrest and your feet on the footrests.","Grasp the handles or sidebars for stability.","Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time.","Pause for a moment at the top, then slowly lower your legs and torso back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на тренажер, прислонившись спиной к спинке и поставив ноги на подножки.","Возьмитесь за ручки или боковые перекладины для устойчивости.","Напрягите пресс и медленно поднимите ноги к груди, одновременно наклоняя туловище вперед.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги и туловище обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en la máquina de palanca con la espalda apoyada en el respaldo y los pies sobre los apoyapiés.","Sujeta las asas o las barras laterales para mayor estabilidad.","Activa el abdomen y eleva lentamente las piernas hacia el pecho, mientras curvas el torso hacia adelante al mismo tiempo.","Haz una pausa por un momento en la parte alta y luego baja lentamente las piernas y el torso a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0602","name":"lever seated reverse fly","category":"shoulders","body_part":"shoulders","equipment":"leverage machine","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0602-myfUsKf.jpg","gif_url":"videos/0602-myfUsKf.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהחזה צמוד לכרית וכפות הרגליים על הרצפה.","אחזו בידיות באחיזה עליונה ושמרו על ידיים כפופות מעט.","נשפו וכווצו את השכמות זו לזו תוך משיכת הידיות לאחור והחוצה, הרחק מהגוף.","עצרו לרגע בשיא הכיווץ, ואז שאפו וחזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере так, чтобы грудь опиралась на подушку, а ступни стояли на полу.","Возьмитесь за рукоятки верхним хватом и держите руки слегка согнутыми.","Выдохните и сведите лопатки вместе, потянув рукоятки назад и наружу, от тела.","Сделайте паузу на мгновение в момент максимального сокращения, затем вдохните и медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.","Agarra las asas con un agarre prono y mantén los brazos ligeramente flexionados.","Exhala y junta las escápulas mientras llevas las asas hacia atrás y hacia afuera, alejándolas de tu cuerpo.","Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0601","name":"lever seated reverse fly (parallel grip)","category":"shoulders","body_part":"shoulders","equipment":"leverage machine","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0601-xiHiJcA.jpg","gif_url":"videos/0601-xiHiJcA.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהחזה צמוד לכרית וכפות הרגליים על הרצפה.","אחזו בידיות באחיזה מקבילה, כפות ידיים פונות זו לזו, ושמרו על ידיים כפופות מעט.","נשפו וכווצו את השכמות זו לזו תוך משיכת הידיות לאחור והחוצה, הרחק מהגוף.","עצרו לרגע בשיא הכיווץ, ואז שאפו וחזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере так, чтобы грудь опиралась на подушку, а ступни стояли на полу.","Возьмитесь за рукоятки параллельным хватом, ладони обращены друг к другу, руки держите слегка согнутыми.","Выдохните и сведите лопатки вместе, потянув рукоятки назад и наружу, от тела.","Сделайте паузу на мгновение в момент максимального сокращения, затем вдохните и медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.","Agarra las asas con un agarre paralelo, con las palmas enfrentadas, y mantén los brazos ligeramente flexionados.","Exhala y junta las escápulas mientras llevas las asas hacia atrás y hacia afuera, alejándolas de tu cuerpo.","Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1350","name":"lever seated row","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1350-7I6LNUG.jpg","gif_url":"videos/1350-7I6LNUG.gif","instruction_steps":{"he":["כווננו את גובה המושב ומשענות הרגליים לתנוחה נוחה.","שבו על המכשיר כשהחזה צמוד לכרית וכפות הרגליים על משענות הרגליים.","אחזו בידיות באחיזה עליונה, ברוחב כתפיים.","שמרו על גב ישר וליבה מופעלת.","משכו את הידיות לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה.","שחררו באיטיות את הידיות וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and footrests to a comfortable position.","Sit on the machine with your chest against the pad and your feet on the footrests.","Grasp the handles with an overhand grip, shoulder-width apart.","Keep your back straight and your core engaged.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и подножки в удобное положение.","Сядьте на тренажер, прижав грудь к подушке, а ноги поставив на подножки.","Возьмитесь за ручки хватом сверху на ширине плеч.","Держите спину прямо, а корпус напряженным.","Потяните ручки к телу, сведя лопатки вместе.","Сделайте паузу на мгновение в пике движения.","Медленно отпустите ручки и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y los apoyapiés a una posición cómoda.","Siéntate en la máquina con el pecho apoyado en la almohadilla y los pies sobre los apoyapiés.","Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros.","Mantén la espalda recta y el core activado.","Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta del movimiento.","Suelta lentamente las asas y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1385","name":"lever seated squat calf raise on leg press machine","category":"lower legs","body_part":"lower legs","equipment":"leverage machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes"],"target":"calves","image":"images/1385-IeDEXTe.jpg","gif_url":"videos/1385-IeDEXTe.gif","instruction_steps":{"he":["כווננו את מושב מכונת לחיצת הרגליים כך שהברכיים כפופות מעט כשכפות הרגליים על משטח הרגליים.","שבו על המכשיר כשהגב צמוד למשענת וכפות הרגליים שטוחות על משטח הרגליים, ברוחב כתפיים.","הניחו את קצות האצבעות וכריות כפות הרגליים על משטח הרגליים, כשהעקבים מחוץ לקצה.","שחררו את ידיות הבטיחות ודחפו את משטח הרגליים מכם ביישור הברכיים.","כשהברכיים מתוחות לגמרי, הורידו באיטיות את העקבים בכיפוף התאומים.","עצרו לרגע בנקודה התחתונה, ואז דחפו את משטח הרגליים חזרה למעלה ביישור התאומים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.","Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.","Release the safety handles and push the footplate away from you by extending your knees.","Once your knees are fully extended, slowly lower your heels by flexing your calves.","Pause for a moment at the bottom, then push the footplate back up by extending your calves.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сиденье тренажера для жима ногами так, чтобы колени были слегка согнуты, когда ступни стоят на подножке.","Сядьте на тренажер, прислонившись спиной к спинке, поставив ноги на подножку на ширине плеч.","Поместите пальцы ног и подушечки стоп на подножку, не отрывая пятки от края.","Отпустите защитные ручки и отодвиньте подножку от себя, вытянув колени.","Как только ваши колени полностью выпрямятся, медленно опустите пятки, сгибая икроножные мышцы.","Задержитесь на мгновение в нижней точке, затем поднимите подножку обратно вверх, вытянув икроножные мышцы.","Повторите необходимое количество повторений."],"es":["Ajusta el asiento de la máquina de prensa de piernas de modo que tus rodillas queden ligeramente flexionadas cuando los pies estén sobre la plataforma.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos sobre la plataforma, separados a la altura de los hombros.","Coloca los dedos y la planta de los pies sobre la plataforma, manteniendo los talones alejados del borde.","Suelta las palancas de seguridad y empuja la plataforma alejándola de ti extendiendo las rodillas.","Una vez que tus rodillas estén completamente extendidas, baja lentamente los talones flexionando las pantorrillas.","Haz una pausa por un momento en la parte baja y luego empuja la plataforma de nuevo hacia arriba extendiendo las pantorrillas.","Repite el número de repeticiones deseado."]}},{"id":"0603","name":"lever shoulder press","category":"shoulders","body_part":"shoulders","equipment":"leverage machine","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0603-67n3r98.jpg","gif_url":"videos/0603-67n3r98.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהגב צמוד למשענת.","אחזו בידיות באחיזה עליונה ומקמו את הידיים בגובה הכתפיים.","דחפו את הידיות כלפי מעלה עד יישור מלא של הידיים, אך אל תנעלו את המרפקים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands at shoulder level.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на машине спиной к спинке сиденья.","Возьмитесь за рукоятки верхним хватом и расположите руки на уровне плеч.","Толкайте ручки вверх до тех пор, пока руки полностью не выпрямятся, но не сгибайте локти.","Задержитесь на мгновение в верхней точке, затем медленно опустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo.","Agarra las asas con un agarre prono y coloca las manos a la altura de los hombros.","Empuja las asas hacia arriba hasta que los brazos queden completamente extendidos, pero sin bloquear los codos.","Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0869","name":"lever shoulder press v. 2","category":"shoulders","body_part":"shoulders","equipment":"leverage machine","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0869-vqsbmL0.jpg","gif_url":"videos/0869-vqsbmL0.gif","instruction_steps":{"he":["כווננו את גובה המושב והמשענת של מכונת המנוף לתנוחה נוחה.","שבו על המכשיר כשהגב צמוד למשענת וכפות הרגליים על הרצפה.","אחזו בידיות המכשיר באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","דחפו את הידיות למעלה וקדימה עד יישור מלא של הידיים, אך ללא נעילה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и спинку рычажной машины в удобное положение.","Сядьте на тренажер, прислонившись спиной к спинке, а ноги поставьте на пол.","Возьмитесь за рукоятки тренажера хватом сверху, на расстоянии чуть шире ширины плеч.","Толкайте ручки вверх и вперед, пока руки не будут полностью выпрямлены, но не зафиксированы.","Задержитесь на мгновение в верхней точке, затем медленно опустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.","Agarra las asas de la máquina con un agarre prono, un poco más separadas que la anchura de los hombros.","Empuja las asas hacia arriba y hacia adelante hasta que los brazos queden completamente extendidos, pero sin bloquear los codos.","Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2318","name":"lever shoulder press v. 3","category":"shoulders","body_part":"shoulders","equipment":"leverage machine","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/2318-dNFYIU1.jpg","gif_url":"videos/2318-dNFYIU1.gif","instruction_steps":{"he":["כווננו את גובה המושב והמשענת של מכונת המנוף לתנוחה נוחה.","שבו על המכשיר כשהגב צמוד למשענת וכפות הרגליים על הרצפה.","אחזו בידיות המכשיר באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","דחפו את הידיות למעלה וקדימה עד יישור מלא של הידיים, אך ללא נעילה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и спинку рычажной машины в удобное положение.","Сядьте на тренажер, прислонившись спиной к спинке, а ноги поставьте на пол.","Возьмитесь за рукоятки тренажера хватом сверху, на расстоянии чуть шире ширины плеч.","Толкайте ручки вверх и вперед, пока руки не будут полностью выпрямлены, но не зафиксированы.","Задержитесь на мгновение в верхней точке, затем медленно опустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.","Agarra las asas de la máquina con un agarre prono, un poco más separadas que la anchura de los hombros.","Empuja las asas hacia arriba y hacia adelante hasta que los brazos queden completamente extendidos, pero sin bloquear los codos.","Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0604","name":"lever shrug","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0604-ZZKbeMw.jpg","gif_url":"videos/0604-ZZKbeMw.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על מכונת המנוף כשהגב צמוד לכרית.","אחזו בידיות באחיזה עליונה ושמרו על ידיים ישרות.","תוך שמירה על גב ישר, הרימו את הכתפיים למעלה לכיוון האוזניים גבוה ככל האפשר.","החזיקו את הכיווץ לרגע, ואז הורידו את הכתפיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the leverage machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере спиной к подушке.","Возьмитесь за рукоятки прямым хватом и держите руки прямыми.","Сохраняя спину прямой, поднимите плечи как можно выше к ушам.","Удерживайте напряжение на мгновение, затем медленно опустите плечи обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina de palanca con la espalda apoyada en la almohadilla.","Sujeta las asas con un agarre prono y mantén los brazos rectos.","Manteniendo la espalda recta, eleva los hombros hacia las orejas tan alto como sea posible.","Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0605","name":"lever standing calf raise","category":"lower legs","body_part":"lower legs","equipment":"leverage machine","muscle_group":"soleus","secondary_muscles":["soleus","ankle stabilizers"],"target":"calves","image":"images/0605-ykUOVze.jpg","gif_url":"videos/0605-ykUOVze.gif","instruction_steps":{"he":["כווננו את המכשיר לגובה שלכם ועמדו עם רגליים ברוחב כתפיים.","מקמו את הכתפיים מתחת לכריות ואחזו בידיות לייצוב.","הרימו את העקבים גבוה ככל האפשר ביישור הקרסוליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the machine to your height and stand with your feet shoulder-width apart.","Place your shoulders under the pads and hold onto the handles for stability.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте тренажер по своему росту и встаньте, поставив ноги на ширине плеч.","Поместите плечи под подушечки и держитесь за ручки для устойчивости.","Поднимите пятки как можно выше, вытянув лодыжки.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina a tu altura y ponte de pie con los pies separados a la altura de los hombros.","Coloca los hombros debajo de las almohadillas y sujétate de las asas para mayor estabilidad.","Eleva los talones tan alto como puedas extendiendo los tobillos.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3758","name":"lever standing chest press","category":"chest","body_part":"chest","equipment":"leverage machine","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/3758-WbNq5Xu.jpg","gif_url":"videos/3758-WbNq5Xu.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר עם כפות רגליים על הרצפה.","אחזו בידיות באחיזה עליונה ומקמו את הידיים בגובה החזה.","דחפו את הידיות קדימה עד יישור מלא של הידיים, תוך שמירה על מרפקים כפופים מעט.","עצרו לרגע, ואז החזירו באיטיות את הידיות לכיוון החזה, תוך שמירה על שליטה לאורך כל התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your feet flat on the ground.","Grasp the handles with an overhand grip and position your hands at chest level.","Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.","Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на машине, поставив ноги на землю.","Возьмитесь за рукоятки верхним хватом и расположите руки на уровне груди.","Толкайте ручки вперед до тех пор, пока руки полностью не выпрямятся, сохраняя локти слегка согнутыми.","Сделайте паузу на мгновение, затем медленно верните ручки обратно к груди, сохраняя контроль на протяжении всего движения.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con los pies planos en el suelo.","Agarra las asas con un agarre prono y coloca las manos a la altura del pecho.","Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, manteniendo los codos ligeramente flexionados.","Haz una pausa por un momento y luego lleva lentamente las asas de vuelta hacia el pecho, manteniendo el control durante todo el movimiento.","Repite el número de repeticiones deseado."]}},{"id":"0606","name":"lever t bar row","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0606-aaXr7ld.jpg","gif_url":"videos/0606-aaXr7ld.gif","instruction_steps":{"he":["כווננו את גובה המושב ומיקום משטח הרגליים ליישור נכון של הגוף.","שבו על המכשיר כשהחזה צמוד לכרית וכפות הרגליים על משטח הרגליים.","אחזו בידיות באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שמרו על גב ישר והפעילו את שרירי הליבה.","משכו את הידיות לכיוון הגו, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא הכיווץ, ואז שחררו באיטיות את הידיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak contraction, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и положение подножки, чтобы обеспечить правильное выравнивание.","Сядьте на тренажер, прижав грудь к подушке и положив ноги на подножку.","Возьмитесь за ручки хватом сверху, на расстоянии чуть шире плеч.","Держите спину прямо и задействуйте корпус.","Потяните ручки к туловищу, сжимая лопатки вместе.","Сделайте паузу на мгновение в момент максимального сокращения, затем медленно отпустите рукоятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta.","Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y activa el core.","Tira de las asas hacia el torso, juntando los omóplatos.","Haz una pausa en el punto de máxima contracción y luego suelta lentamente las asas hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1351","name":"lever t-bar reverse grip row","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1351-FVM1AUZ.jpg","gif_url":"videos/1351-FVM1AUZ.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהחזה צמוד לכרית וכפות הרגליים על הרצפה.","אחזו בידיות באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שמרו על גב ישר והפעילו את שרירי הליבה.","משכו את הידיות לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה, ואז שחררו באיטיות ויישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере так, чтобы грудь опиралась на подушку, а ступни стояли на полу.","Возьмитесь за ручки хватом сверху, на расстоянии чуть шире плеч.","Держите спину прямо и задействуйте корпус.","Потяните ручки к груди, сведя лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения, затем медленно расслабьтесь и вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y activa el core.","Tira de las asas hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0607","name":"lever triceps extension","category":"upper arms","body_part":"upper arms","equipment":"leverage machine","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0607-Ser9eQp.jpg","gif_url":"videos/0607-Ser9eQp.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהגב צמוד לכרית.","אחזו בידיות באחיזה עליונה ומתחו את הידיים לגמרי לפניכם.","תוך שמירה על הזרועות העליונות ללא תזוזה, הורידו באיטיות את הידיות לכיוון המצח בכיפוף מרפקים.","עצרו לרגע בנקודה התחתונה, ואז דחפו את הידיות חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an overhand grip and fully extend your arms in front of you.","Keeping your upper arms stationary, slowly lower the handles towards your forehead by bending your elbows.","Pause for a moment at the bottom, then push the handles back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере спиной к подушке.","Возьмитесь за рукоятки верхним хватом и полностью вытяните руки перед собой.","Удерживая плечи неподвижно, медленно опустите рукоятки ко лбу, сгибая локти.","Задержитесь на мгновение в нижней точке, затем верните рукоятки в исходное положение, вытянув руки.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.","Agarra las asas con un agarre prono y extiende completamente los brazos frente a ti.","Manteniendo la parte superior de los brazos inmóvil, baja lentamente las asas hacia tu frente flexionando los codos.","Haz una pausa por un momento en la parte baja y luego empuja las asas de vuelta hacia arriba hasta la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1313","name":"lever unilateral row","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1313-oROuvrX.jpg","gif_url":"videos/1313-oROuvrX.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו מול המכשיר.","אחזו בידיות באחיזה עליונה ושמרו על גב ישר.","משכו את הידיות לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה, ואז שחררו באיטיות ויישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself facing the machine.","Grasp the handles with an overhand grip and keep your back straight.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь лицом к машине.","Возьмитесь за рукоятки верхним хватом и держите спину прямо.","Потяните ручки к телу, сведя лопатки вместе.","Задержитесь на мгновение на пике движения, затем медленно расслабьтесь и вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate frente a la máquina.","Agarra las asas con un agarre prono y mantén la espalda recta.","Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.","Haz una pausa en el punto máximo del movimiento y luego suelta lentamente, extendiendo los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0609","name":"london bridge","category":"back","body_part":"back","equipment":"rope","muscle_group":"shoulders","secondary_muscles":["shoulders","biceps","forearms"],"target":"upper back","image":"images/0609-bLyQokI.jpg","gif_url":"videos/0609-bLyQokI.gif","instruction_steps":{"he":["עגנו את החבל לנקודת עיגון גבוהה.","עמדו עם הגב לנקודת העיגון, רגליים ברוחב כתפיים.","אחזו בחבל באחיזה עליונה, כפות ידיים כלפי מטה.","רכנו מעט קדימה, תוך שמירה על גב ישר וליבה מופעלת.","משכו את החבל לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה, ואז שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach the rope to a high anchor point.","Stand facing away from the anchor point with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Lean forward slightly, keeping your back straight and core engaged.","Pull the rope towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите веревку к высокой точке крепления.","Встаньте лицом от точки крепления, поставив ноги на ширине плеч.","Возьмите веревку прямым хватом ладонями вниз.","Слегка наклонитесь вперед, сохраняя спину прямой и напряженным корпусом.","Потяните веревку к себе, сжимая лопатки вместе.","Задержитесь на мгновение на пике движения, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta la cuerda a un punto de anclaje alto.","Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.","Agarra la cuerda con un agarre prono, con las palmas hacia abajo.","Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado.","Tira de la cuerda hacia tu cuerpo, juntando las escápulas.","Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3013","name":"low glute bridge on floor","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","core"],"target":"glutes","image":"images/3013-u0cNiij.jpg","gif_url":"videos/3013-u0cNiij.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים לצידי הגוף, עם כפות ידיים כלפי מטה.","הפעילו את הישבן והליבה, ואז הרימו את האגן מהרצפה עד שהגוף יוצר קו ישר מהברכיים ועד הכתפיים.","עצרו לרגע בנקודה העליונה, תוך כיווץ הישבן.","הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your arms by your sides, palms facing down.","Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки по бокам ладонями вниз.","Задействуйте ягодицы и корпус, затем поднимите бедра от земли, пока ваше тело не образует прямую линию от колен до плеч.","Задержитесь на мгновение в верхней точке, напрягая ягодицы.","Медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca los brazos a los lados del cuerpo, con las palmas hacia abajo.","Activa los glúteos y el core, y luego eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa breve en la parte alta, apretando los glúteos.","Baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1352","name":"lower back curl","category":"back","body_part":"back","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1352-ANbbry2.jpg","gif_url":"videos/1352-ANbbry2.gif","instruction_steps":{"he":["שכבו על הבטן עם רגליים ישרות וידיים לצידי הגוף.","הפעילו את הישבן והירך האחורית, והרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול הגב כלפי מעלה.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your stomach with your legs extended and your arms by your sides.","Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на живот, вытянув ноги и положив руки по бокам.","Задействуйте ягодицы и мышцы задней поверхности бедра и медленно поднимите верхнюю часть тела от земли, сгибая спину вверх.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo con las piernas extendidas y los brazos a los lados del cuerpo.","Activa los glúteos y los isquiotibiales, y eleva lentamente la parte superior del cuerpo del suelo, curvando la espalda hacia arriba.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3582","name":"lunge with jump","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3582-PM1PZjg.jpg","gif_url":"videos/3582-PM1PZjg.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים.","צעדו קדימה עם רגל ימין והורידו את הגוף לעמדת מספריים (לאנג').","דחפו עם כף רגל ימין וקפצו לאוויר, בהחלפת מיקום כפות הרגליים באוויר.","נחתו ברכות עם רגל שמאל קדימה והורידו מיד את הגוף לעמדת מספריים.","המשיכו להחליף בין מספריים לקפיצות למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","Push off with your right foot and jump into the air, switching the position of your feet mid-air.","Land softly with your left foot forward and immediately lower your body into a lunge position.","Continue alternating between lunges and jumps for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч.","Сделайте шаг вперед правой ногой, опуская тело в положение выпада.","Оттолкнитесь правой ногой и подпрыгните в воздух, меняя положение ног в воздухе.","Мягко приземлитесь левой ногой вперед и сразу же опустите тело в положение выпада.","Продолжайте чередовать выпады и прыжки желаемое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de los hombros.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Empújate con el pie derecho y salta al aire, cambiando la posición de los pies en pleno vuelo.","Aterriza suavemente con el pie izquierdo hacia adelante y baja inmediatamente el cuerpo a una posición de zancada.","Continúa alternando entre zancadas y saltos el número de repeticiones deseado."]}},{"id":"1688","name":"lunge with twist","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","glutes","hamstrings"],"target":"abs","image":"images/1688-K9VL0Jq.jpg","gif_url":"videos/1688-K9VL0Jq.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים.","צעדו קדימה עם רגל ימין והורידו את הגוף לעמדת מספריים (לאנג').","תוך כדי המספריים, סובבו את הגו ימינה, בהבאת מרפק שמאל לכיוון ברך ימין.","עצרו לרגע, ואז חזרו לנקודת ההתחלה.","חזרו על התנועה בצד השני, בצעד קדימה עם רגל שמאל וסיבוב הגו שמאלה.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.","Pause for a moment, then return to the starting position.","Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.","Continue alternating sides for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч.","Сделайте шаг вперед правой ногой, опуская тело в положение выпада.","Делая выпад, поверните туловище вправо, поднеся левый локоть к правому колену.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите то же самое с другой стороны, шагнув вперед левой ногой и повернув туловище влево.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de los hombros.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Al hacer la zancada, gira el torso hacia la derecha, llevando el codo izquierdo hacia la rodilla derecha.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite hacia el otro lado, dando un paso adelante con el pie izquierdo y girando el torso hacia la izquierda.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0613","name":"lying (side) quads stretch","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"quads","image":"images/0613-BWnJR72.jpg","gif_url":"videos/0613-BWnJR72.gif","instruction_steps":{"he":["שכבו על הצד עם רגליים ישרות.","כופפו את הרגל העליונה ואחזו בקרסול או בכף הרגל עם היד.","משכו בעדינות את הקרסול או כף הרגל לכיוון הישבן עד לתחושת מתיחה בארבע ראשי.","החזיקו את המתיחה 20–30 שניות.","שחררו את המתיחה וחזרו עליה בצד השני."],"en":["Lie on your side with your legs straight.","Bend your top leg and grab your ankle or foot with your hand.","Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."],"ru":["Лягте на бок, ноги прямые.","Согните верхнюю ногу и возьмитесь рукой за лодыжку или ступню.","Аккуратно подтяните лодыжку или ступню к ягодицам, пока не почувствуете растяжение квадрицепсов.","Удерживайте растяжку 20–30 секунд.","Освободите растяжку и повторите с другой стороны."],"es":["Túmbate de lado con las piernas rectas.","Flexiona la pierna de arriba y agarra tu tobillo o pie con la mano.","Tira suavemente del tobillo o del pie hacia los glúteos hasta sentir un estiramiento en los cuádriceps.","Mantén el estiramiento durante 20-30 segundos.","Suelta el estiramiento y repite del otro lado."]}},{"id":"2312","name":"lying elbow to knee","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/2312-AQIhRjM.jpg","gif_url":"videos/2312-AQIhRjM.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","הפעילו את שרירי הבטן והרימו את פלג הגוף העליון מהרצפה, בהבאת מרפק ימין לכיוון ברך שמאל.","בו-זמנית, מתחו את רגל ימין ישר והרימו אותה מהרצפה.","עצרו לרגע, ואז חזרו לנקודת ההתחלה.","חזרו על התנועה, הפעם בהבאת מרפק שמאל לכיוון ברך ימין ומתיחת רגל שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, extend your right leg straight out and lift it off the ground.","Pause for a moment, then return to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.","Continue alternating sides for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Напрягите пресс и поднимите верхнюю часть тела от земли, поднеся правый локоть к левому колену.","В то же время вытяните правую ногу прямо и поднимите ее над землей.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите движение, на этот раз поднеся левый локоть к правому колену и вытягивая левую ногу.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda.","Al mismo tiempo, extiende la pierna derecha en línea recta y levántala del suelo.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y extendiendo la pierna izquierda.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0620","name":"lying leg raise flat bench","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0620-WhuFnR7.jpg","gif_url":"videos/0620-WhuFnR7.gif","instruction_steps":{"he":["שכבו על ספסל ישר כשהגב צמוד אליו.","הניחו את הידיים מתחת לישבן לתמיכה.","שמרו על רגליים ישרות וצמודות, והרימו אותן לכיוון התקרה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a flat bench with your back pressed against it.","Place your hands under your glutes for support.","Keep your legs straight and together, and lift them up towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на плоскую скамью, прижавшись к ней спиной.","Положите руки под ягодицы для поддержки.","Держите ноги прямо и вместе и поднимите их к потолку.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate en un banco plano con la espalda presionada contra él.","Coloca las manos debajo de los glúteos como apoyo.","Mantén las piernas rectas y juntas, y elévalas hacia el techo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0865","name":"lying leg-hip raise","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0865-9IxJdtC.jpg","gif_url":"videos/0865-9IxJdtC.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וידיים לצידי הגוף.","הניחו את הידיים מתחת לישבן לתמיכה.","הפעילו את הליבה והרימו את הרגליים מהרצפה, לכיוון התקרה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, raising them towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, вытянув ноги и положив руки по бокам.","Положите руки под ягодицы для поддержки.","Напрягите корпус и поднимите ноги от земли, поднимая их к потолку.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Coloca las manos debajo de los glúteos como apoyo.","Activa el core y levanta las piernas del suelo, elevándolas hacia el techo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1301","name":"machine inner chest press","category":"chest","body_part":"chest","equipment":"leverage machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1301-wDN97Ca.jpg","gif_url":"videos/1301-wDN97Ca.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהגב צמוד לכרית.","אחזו בידיות באחיזה עליונה ומקמו את המרפקים בזווית של 90 מעלות.","דחפו את הידיות קדימה עד יישור מלא של הידיים, תוך נשיפה במהלך התנועה.","עצרו לרגע בסוף התנועה, ואז חזרו באיטיות לנקודת ההתחלה תוך שאיפה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере, прижавшись спиной к подушке.","Возьмитесь за рукоятки хватом сверху и расположите локти под углом 90 градусов.","Толкайте ручки вперед до полного выпрямления рук, выдыхая во время движения.","Сделайте паузу в конце движения, затем медленно вернитесь в исходное положение, вдыхая при этом.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla.","Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados.","Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento.","Haz una pausa al final del movimiento y luego vuelve lentamente a la posición inicial, inhalando mientras lo haces.","Repite el número de repeticiones deseado."]}},{"id":"0624","name":"march sit (wall)","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0624-sVQCCeG.jpg","gif_url":"videos/0624-sVQCCeG.gif","instruction_steps":{"he":["עמדו עם הגב לקיר ורגליים ברוחב אגן.","החליקו באיטיות את הגב במורד הקיר עד שהברכיים כפופות בזווית של 90 מעלות.","הרימו את כף רגל ימין מהרצפה והביאו את הברך לכיוון החזה.","הורידו את כף רגל ימין חזרה והרימו את כף רגל שמאל מהרצפה, בהבאת הברך לכיוון החזה.","המשיכו להחליף בין הרמת כף רגל ימין ושמאל למספר החזרות הרצוי."],"en":["Stand with your back against a wall and your feet hip-width apart.","Slowly slide your back down the wall until your knees are bent at a 90-degree angle.","Lift your right foot off the ground and bring your knee towards your chest.","Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.","Continue alternating between lifting your right and left foot for the desired number of repetitions."],"ru":["Встаньте спиной к стене, поставив ноги на ширине плеч.","Медленно сдвиньте спину вниз по стене, пока колени не согнутся под углом 90 градусов.","Поднимите правую ногу от земли и поднесите колено к груди.","Опустите правую ногу обратно и поднимите левую ногу от земли, поднеся колено к груди.","Продолжайте попеременно поднимать правую и левую ногу необходимое количество повторений."],"es":["Ponte de pie con la espalda contra una pared y los pies separados a la altura de las caderas.","Desliza lentamente la espalda hacia abajo por la pared hasta que las rodillas formen un ángulo de 90 grados.","Levanta el pie derecho del suelo y lleva la rodilla hacia el pecho.","Baja el pie derecho de nuevo y levanta el pie izquierdo del suelo, llevando la rodilla hacia el pecho.","Continúa alternando entre levantar el pie derecho y el izquierdo el número de repeticiones deseado."]}},{"id":"1353","name":"medicine ball catch and overhead throw","category":"back","body_part":"back","equipment":"medicine ball","muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"lats","image":"images/1353-PsVS1QP.jpg","gif_url":"videos/1353-PsVS1QP.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים כדור כוח בשתי ידיים בגובה החזה.","כופפו ברכיים מעט והפעילו את הליבה.","הורידו את הגוף לעמדת סקוואט, תוך שמירה על גב ישר וחזה מורם.","יישרו ירכיים ורגליים בפיצוץ, ובו-זמנית הטילו את כדור הכוח מעל הראש.","שחררו את הכדור בנקודה העליונה של התנועה ותפסו אותו בדרך למטה.","הורידו את הגוף חזרה לעמדת הסקוואט וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.","Bend your knees slightly and engage your core.","Lower your body into a squat position, keeping your back straight and chest up.","Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead.","Release the ball at the top of the movement and catch it on the way down.","Lower your body back into the squat position and repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите медицинский мяч обеими руками на уровне груди.","Слегка согните колени и задействуйте корпус.","Опустите тело в положение приседа, держа спину прямо и грудь вверх.","Резко выпрямите бедра и ноги, одновременно бросая медицинский мяч над головой.","Отпустите мяч в верхней точке движения и поймайте его на пути вниз.","Опустите тело обратно в положение приседа и повторите желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal con ambas manos a la altura del pecho.","Flexiona ligeramente las rodillas y activa el core.","Baja el cuerpo a una posición de sentadilla, manteniendo la espalda recta y el pecho hacia arriba.","Extiende explosivamente las caderas y las piernas, mientras lanzas simultáneamente el balón medicinal por encima de la cabeza.","Suelta el balón en la parte más alta del movimiento y atrápalo cuando vaya bajando.","Baja de nuevo el cuerpo a la posición de sentadilla y repite el número de repeticiones deseado."]}},{"id":"1302","name":"medicine ball chest pass","category":"chest","body_part":"chest","equipment":"medicine ball","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1302-aDoFKrE.jpg","gif_url":"videos/1302-aDoFKrE.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים את כדור הכוח בגובה החזה.","מתחו את הידיים קדימה, בדחיפת כדור הכוח בעוצמה הרחק מהחזה.","עם שחרור הכדור, המשיכו את התנועה עם הידיים והגו, בהעברת המשקל מהרגל האחורית לקדמית.","תפסו את הכדור כשהוא חוזר מהקיר או מבן/בת הזוג, וחזרו מיד על התנועה.","המשיכו למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest with force.","As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot.","Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement.","Continue for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, удерживая медицинский мяч на уровне груди.","Вытяните руки вперед, с силой отталкивая медицинский мяч от груди.","Выпуская мяч, продолжайте движение руками и туловищем, перенося вес тела с задней ноги на переднюю.","Поймайте мяч, когда он отскакивает от стены или партнера, и сразу же повторите движение.","Продолжайте необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal a la altura del pecho.","Extiende los brazos hacia adelante, empujando el balón medicinal con fuerza para alejarlo del pecho.","Al soltar el balón, continúa el movimiento con los brazos y el torso, transfiriendo el peso del pie de atrás al pie de adelante.","Atrapa el balón cuando rebote en la pared o en tu compañero, y repite el movimiento de inmediato.","Continúa durante el número de repeticiones deseado."]}},{"id":"1303","name":"medicine ball chest push from 3 point stance","category":"chest","body_part":"chest","equipment":"medicine ball","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1303-dCJnuVq.jpg","gif_url":"videos/1303-dCJnuVq.gif","instruction_steps":{"he":["התחילו בעמדת 3 נקודות — יד אחת על כדור הכוח והיד השנייה על הרצפה.","מתחו את הרגליים ומקמו את הגוף בקו ישר.","הורידו את החזה לכיוון הרצפה תוך שמירה על גב ישר.","דחפו את כדור הכוח הרחק מהגוף, במתיחת היד המלאה.","חזרו לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.","Extend your legs and position your body in a straight line.","Lower your chest towards the ground while keeping your back straight.","Push the medicine ball away from your body, extending your arm fully.","Return to the starting position and repeat for the desired number of repetitions."],"ru":["Начните с трехточечной стойки, положив одну руку на медицинский мяч, а другую на землю.","Вытяните ноги и расположите тело по прямой линии.","Опустите грудь к земле, сохраняя спину прямой.","Оттолкните медицинский мяч от тела, полностью выпрямив руку.","Вернитесь в исходное положение и повторите необходимое количество повторений."],"es":["Comienza en una posición de apoyo de 3 puntos con una mano sobre el balón medicinal y la otra en el suelo.","Extiende las piernas y coloca tu cuerpo en línea recta.","Baja el pecho hacia el suelo manteniendo la espalda recta.","Empuja el balón medicinal alejándolo de tu cuerpo, extendiendo completamente el brazo.","Vuelve a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"1304","name":"medicine ball chest push multiple response","category":"chest","body_part":"chest","equipment":"medicine ball","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1304-7aolH9D.jpg","gif_url":"videos/1304-7aolH9D.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים כדור כוח בגובה החזה.","מתחו את הידיים קדימה, בדחיפת כדור הכוח הרחק מהחזה.","עצרו לרגע, ואז החזירו באיטיות את כדור הכוח לחזה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, удерживая медицинский мяч на уровне груди.","Вытяните руки вперед, отталкивая медицинский мяч от груди.","Сделайте паузу на мгновение, затем медленно верните медицинский мяч обратно к груди.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal a la altura del pecho.","Extiende los brazos hacia adelante, alejando el balón medicinal de tu pecho.","Haz una pausa por un momento y luego lleva lentamente el balón medicinal de vuelta al pecho.","Repite el número de repeticiones deseado."]}},{"id":"1305","name":"medicine ball chest push single response","category":"chest","body_part":"chest","equipment":"medicine ball","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1305-jeHtrlO.jpg","gif_url":"videos/1305-jeHtrlO.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים את כדור הכוח בגובה החזה.","מתחו את הידיים קדימה, בדחיפת כדור הכוח הרחק מהחזה.","עצרו לרגע, ואז החזירו באיטיות את כדור הכוח לחזה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, удерживая медицинский мяч на уровне груди.","Вытяните руки вперед, отталкивая медицинский мяч от груди.","Сделайте паузу на мгновение, затем медленно верните медицинский мяч обратно к груди.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal a la altura del pecho.","Extiende los brazos hacia adelante, alejando el balón medicinal de tu pecho.","Haz una pausa por un momento y luego lleva lentamente el balón medicinal de vuelta al pecho.","Repite el número de repeticiones deseado."]}},{"id":"1312","name":"medicine ball chest push with run release","category":"chest","body_part":"chest","equipment":"medicine ball","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/1312-pX9Elbe.jpg","gif_url":"videos/1312-pX9Elbe.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים כדור כוח בגובה החזה.","צעדו קדימה עם כף רגל ימין ובו-זמנית דחפו את כדור הכוח קדימה, ביישור מלא של הידיים.","תוך כדי דחיפת הכדור קדימה, שחררו אותו ותנו לו להתגלגל.","רוצו מהר קדימה ותפסו את הכדור לפני שהוא נוגע ברצפה.","אחרי תפיסת הכדור, החזירו אותו לחזה וחזרו על התנועה עם כף רגל שמאל קדימה.","המשיכו להחליף רגליים ולחזור על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.","As you push the ball forward, release it and let it roll forward.","Quickly run forward and catch the ball before it hits the ground.","Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward.","Continue alternating legs and repeating the exercise for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, удерживая медицинский мяч на уровне груди.","Сделайте шаг вперед правой ногой и одновременно толкните медицинский мяч вперед, полностью выпрямляя руки.","Когда вы толкаете мяч вперед, отпустите его и позвольте ему катиться вперед.","Быстро бегите вперед и поймайте мяч, прежде чем он упадет на землю.","Как только вы поймаете мяч, верните его к груди и повторите движение, выставив левую ногу вперед.","Продолжайте чередовать ноги и повторять упражнение желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal a la altura del pecho.","Da un paso adelante con el pie derecho y, al mismo tiempo, empuja el balón medicinal hacia adelante, extendiendo completamente los brazos.","Mientras empujas el balón hacia adelante, suéltalo y déjalo rodar.","Corre rápidamente hacia adelante y atrapa el balón antes de que toque el suelo.","Una vez que atrapes el balón, llévalo de vuelta al pecho y repite el movimiento con el pie izquierdo adelante.","Continúa alternando piernas y repitiendo el ejercicio el número de repeticiones deseado."]}},{"id":"1701","name":"medicine ball close grip push up","category":"upper arms","body_part":"upper arms","equipment":"medicine ball","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1701-8K7m2SS.jpg","gif_url":"videos/1701-8K7m2SS.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם הידיים על כדור הכוח, ברוחב כתפיים.","הורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף.","דחפו חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, положив руки на медицинский мяч на ширине плеч.","Опустите тело к земле, согнув локти и держа их близко к бокам.","Вернитесь в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Empuja de vuelta hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1354","name":"medicine ball overhead slam","category":"back","body_part":"back","equipment":"medicine ball","muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"upper back","image":"images/1354-oHg8eop.jpg","gif_url":"videos/1354-oHg8eop.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים כדור כוח בשתי ידיים מעל הראש.","הפעילו את הליבה ושמרו על גב ישר.","כופפו ברכיים מעט והטיחו בעוצמה את כדור הכוח ברצפה לפניכם.","בהטחת הכדור מטה, השתמשו בכל הגוף ליצירת כוח, כולל הכתפיים והליבה.","תפסו את הכדור בקפיצה חזרה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.","Engage your core and keep your back straight.","Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you.","As you slam the ball down, use your entire body to generate power, including your shoulders and core.","Catch the ball on the bounce and repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите медицинский мяч обеими руками над головой.","Напрягите корпус и держите спину прямо.","Слегка согните ноги в коленях и с силой швырните медицинский мяч на землю перед собой.","Когда вы бросаете мяч, используйте все свое тело для создания силы, включая плечи и корпус.","Поймайте мяч на отскоке и повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal con ambas manos por encima de la cabeza.","Activa el core y mantén la espalda recta.","Flexiona ligeramente las rodillas y lanza con fuerza el balón medicinal contra el suelo frente a ti.","Al lanzar el balón al suelo, utiliza todo el cuerpo para generar potencia, incluidos los hombros y el core.","Atrapa el balón al rebotar y repite el número de repeticiones deseado."]}},{"id":"1750","name":"medicine ball supine chest throw","category":"upper arms","body_part":"upper arms","equipment":"medicine ball","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1750-Al3tP0D.jpg","gif_url":"videos/1750-Al3tP0D.gif","instruction_steps":{"he":["שכבו על הגב על ספסל עם ברכיים כפופות וכפות רגליים על הרצפה.","החזיקו את כדור הכוח בשתי ידיים, במתיחת הידיים ישר מעל החזה.","הורידו את כדור הכוח לכיוון החזה, תוך שמירה על מרפקים צמודים לגוף.","דחפו את כדור הכוח כלפי מעלה בפיצוץ, ביישור מלא של הידיים וזריקת הכדור גבוה ככל האפשר.","תפסו את כדור הכוח וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back on a bench with your knees bent and feet flat on the ground.","Hold the medicine ball with both hands, extending your arms straight up above your chest.","Lower the medicine ball towards your chest, keeping your elbows close to your body.","Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible.","Catch the medicine ball and repeat for the desired number of repetitions."],"ru":["Лягте на спину на скамью, согните колени и поставьте ступни на землю.","Держите медицинский мяч обеими руками, вытянув руки прямо над грудью.","Опустите медицинский мяч к груди, держа локти близко к телу.","Со взрывной силой толкните медицинский мяч вверх, полностью выпрямив руки и подбросив мяч как можно выше.","Поймайте медицинский мяч и повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco con las rodillas flexionadas y los pies planos en el suelo.","Sostén el balón medicinal con ambas manos, extendiendo los brazos rectos por encima del pecho.","Baja el balón medicinal hacia el pecho, manteniendo los codos cerca del cuerpo.","Empuja el balón medicinal explosivamente hacia arriba, extendiendo completamente los brazos y lanzando el balón lo más alto posible.","Atrapa el balón medicinal y repite el número de repeticiones deseado."]}},{"id":"0627","name":"mixed grip chin-up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0627-T8UpLkb.jpg","gif_url":"videos/0627-T8UpLkb.gif","instruction_steps":{"he":["אחזו במוט המתח באחיזה תחתונה (כפות ידיים פונות אליכם), ידיים מעט רחבות מרוחב הכתפיים.","היתלו על המוט עם ידיים ישרות לגמרי וכפות רגליים באוויר.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון המוט, כשהחזה מוביל את התנועה.","המשיכו למשוך עד שהסנטר מעל המוט.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות ובשליטה חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."],"ru":["Возьмитесь за перекладину хватом снизу (ладонями к себе), расставив руки чуть шире плеч.","Повисните на перекладине, полностью вытянув руки и оторвав ноги от земли.","Задействуйте мышцы спины и подтяните тело к перекладине, ведя грудью.","Продолжайте тянуть, пока подбородок не окажется над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение, контролируя его.","Повторите необходимое количество повторений."],"es":["Agarra la barra de dominadas con un agarre supino (las palmas hacia ti) y las manos un poco más separadas que la anchura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo.","Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte alta y luego baja lentamente tu cuerpo, con control, hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3217","name":"modified hindu push-up (male)","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/3217-epOSYUZ.jpg","gif_url":"videos/3217-epOSYUZ.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים מעט רחבות מרוחב הכתפיים ורגליים ברוחב אגן.","הורידו את הגוף לכיוון הרצפה, בכיפוף מרפקים והפעלת הליבה.","תוך כדי הורדת הגוף, העבירו את המשקל לאחור והרימו את האגן לכיוון התקרה, ביצירת צורת V הפוכה עם הגוף.","המשיכו לרדת עד שהחזה מעט מעל הרצפה, ואז הפכו את התנועה — דחפו את האגן חזרה מטה ויישרו ידיים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.","Lower your body towards the ground, bending your elbows and keeping your core engaged.","As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.","Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции для отжиманий, поставив руки чуть шире ширины плеч и ноги на ширине плеч.","Опустите тело к земле, сгибая локти и сохраняя корпус напряженным.","Опуская тело, перенесите вес назад и поднимите бедра вверх к потолку, создавая своим телом перевернутую V-образную форму.","Продолжайте опускать тело до тех пор, пока грудь не окажется чуть выше земли, затем поменяйте направление движения, отталкивая бедра вниз и вытягивая руки, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies separados a la altura de las caderas.","Baja el cuerpo hacia el suelo, flexionando los codos y manteniendo el core activado.","Mientras bajas el cuerpo, desplaza el peso hacia atrás y eleva las caderas hacia el techo, formando una V invertida con tu cuerpo.","Sigue bajando el cuerpo hasta que el pecho quede justo por encima del suelo y luego invierte el movimiento, empujando las caderas hacia abajo y extendiendo los brazos para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1421","name":"modified push up to lower arms","category":"lower arms","body_part":"lower arms","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","chest","shoulders"],"target":"forearms","image":"images/1421-arvaszz.jpg","gif_url":"videos/1421-arvaszz.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים ישר מתחת לכתפיים והגוף בקו ישר.","הורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף.","כשהמרפקים בזווית של 90 מעלות, הורידו את האמות לרצפה, תוך שמירה על מרפקים ישר מתחת לכתפיים.","עצרו לרגע, ואז דחפו דרך כפות הידיים להרמת האמות חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands directly under your shoulders and your body in a straight line.","Lower your body down towards the ground by bending your elbows, keeping them close to your sides.","Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.","Pause for a moment, then push through your palms to lift your forearms back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции отжимания, положив руки прямо под плечи, а тело образуя прямую линию.","Опустите тело вниз к земле, сгибая локти и держа их близко к бокам.","Как только ваши локти окажутся под углом 90 градусов, опустите предплечья на землю, держа локти прямо под плечами.","Сделайте паузу на мгновение, затем надавите ладонями, чтобы поднять предплечья обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de flexión con las manos directamente debajo de los hombros y el cuerpo en línea recta.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de tu costado.","Cuando los codos formen un ángulo de 90 grados, baja los antebrazos hasta el suelo, manteniendo los codos justo debajo de los hombros.","Haz una pausa por un momento y luego empuja con las palmas para llevar los antebrazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0628","name":"monster walk","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/0628-O95afRA.jpg","gif_url":"videos/0628-O95afRA.gif","instruction_steps":{"he":["הניחו גומיית התנגדות סביב הקרסוליים.","עמדו עם רגליים ברוחב כתפיים וכופפו ברכיים מעט.","צעדו הצידה עם כף רגל ימין, תוך שמירה על מתח בגומיית ההתנגדות.","המשיכו עם כף רגל שמאל, בצעד הצידה לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Place a resistance band around your ankles.","Stand with your feet shoulder-width apart and slightly bend your knees.","Take a step to the side with your right foot, maintaining tension on the resistance band.","Follow with your left foot, stepping to the side to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Наденьте эластичную ленту на лодыжки.","Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Сделайте шаг в сторону правой ногой, сохраняя напряжение на эспандере.","Следуйте левой ногой, делая шаг в сторону, чтобы вернуться в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Coloca una banda elástica alrededor de los tobillos.","Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.","Da un paso hacia el lado con el pie derecho, manteniendo la tensión en la banda elástica.","Continúa con el pie izquierdo, dando un paso lateral para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0630","name":"mountain climber","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"core","secondary_muscles":["core","shoulders","triceps"],"target":"cardiovascular system","image":"images/0630-RJgzwny.jpg","gif_url":"videos/0630-RJgzwny.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים ישר מתחת לכתפיים והגוף בקו ישר.","הפעילו את שרירי הליבה והביאו את ברך ימין לכיוון החזה, ואז החליפו במהירות והביאו את ברך שמאל לכיוון החזה.","המשיכו להחליף רגליים בתנועת ריצה, תוך שמירה על אגן נמוך וליבה מופעלת.","שמרו על קצב אחיד ונשימה סדירה לאורך כל התרגיל.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.","Continue alternating legs in a running motion, keeping your hips low and your core engaged.","Maintain a steady pace and breathe evenly throughout the exercise.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, положив руки прямо под плечи, а тело образуя прямую линию.","Напрягите корпус и поднесите правое колено к груди, затем быстро переключитесь и подтяните левое колено к груди.","Продолжайте чередовать ноги в беговом движении, держа бедра низко и напрягая корпус.","Поддерживайте устойчивый темп и дышите ровно на протяжении всего упражнения.","Повторите необходимое количество повторений."],"es":["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.","Activa el core y lleva la rodilla derecha hacia el pecho, luego cambia rápidamente y lleva la rodilla izquierda hacia el pecho.","Continúa alternando las piernas con un movimiento de carrera, manteniendo las caderas bajas y el core activado.","Mantén un ritmo constante y respira de forma regular durante todo el ejercicio.","Repite el número de repeticiones deseado."]}},{"id":"0631","name":"muscle up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","triceps","shoulders","chest"],"target":"lats","image":"images/0631-yJUHKTn.jpg","gif_url":"videos/0631-yJUHKTn.gif","instruction_steps":{"he":["התחילו בתלייה על מוט מתח עם כפות ידיים פונות מכם וידיים ישרות לגמרי.","הפעילו את הליבה ומשכו את הגוף למעלה לכיוון המוט, כשהחזה מוביל את התנועה.","בהגיעכם לנקודה העליונה של התנועה, החליפו אחיזה כך שכפות הידיים פונות אליכם.","המשיכו למשוך את עצמכם למעלה עד שהחזה מעל המוט והידיים כפופות לגמרי.","הפכו את התנועה בהורדת עצמכם באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest is above the bar and your arms are fully flexed.","Reverse the movement by slowly lowering yourself back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с подвешивания на перекладине, повернув ладони от себя и полностью вытянув руки.","Напрягите корпус и подтяните тело к перекладине, ведя грудью.","Достигнув вершины движения, поменяйте хват так, чтобы ладони были обращены к вам.","Продолжайте подтягиваться до тех пор, пока грудь не окажется над перекладиной, а руки полностью не согнутся.","Выполните обратное движение, медленно опускаясь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza colgándote de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos.","Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.","Al llegar a la parte alta del movimiento, cambia el agarre de modo que las palmas queden hacia ti.","Sigue tirando hacia arriba hasta que el pecho quede por encima de la barra y los brazos estén completamente flexionados.","Invierte el movimiento bajando lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1401","name":"muscle-up (on vertical bar)","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","triceps","forearms"],"target":"lats","image":"images/1401-Af0EW2I.jpg","gif_url":"videos/1401-Af0EW2I.gif","instruction_steps":{"he":["התחילו בתלייה על מוט אנכי עם כפות ידיים פונות מכם וידיים ישרות לגמרי.","הפעילו את הליבה ומשכו את הגוף למעלה לכיוון המוט, כשהחזה מוביל את התנועה.","תוך כדי המשיכה למעלה, היטו את הגוף מעט לאחור והביאו את המרפקים לצידי הגוף.","המשיכו למשוך עד שהחזה מגיע למוט והמרפקים כפופים לגמרי.","עצרו לרגע בנקודה העליונה, ואז הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you pull yourself up, lean back slightly and bring your elbows towards your sides.","Continue pulling until your chest reaches the bar and your elbows are fully bent.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с висения на вертикальной перекладине, повернув ладони от себя и полностью вытянув руки.","Напрягите корпус и подтяните тело к перекладине, ведя грудью.","Подтягиваясь, слегка откиньтесь назад и разведите локти в стороны.","Продолжайте тянуть, пока ваша грудь не достигнет перекладины, а локти полностью не согнутся.","Задержитесь на мгновение в верхней точке, затем медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza colgándote de una barra vertical con las palmas hacia afuera y los brazos completamente extendidos.","Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.","Al subir tu cuerpo, inclínate ligeramente hacia atrás y lleva los codos hacia los costados.","Sigue tirando hasta que el pecho llegue a la barra y los codos estén completamente flexionados.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2328","name":"narrow push-up on exercise ball","category":"upper arms","body_part":"upper arms","equipment":"stability ball","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/2328-4cWjYEN.jpg","gif_url":"videos/2328-4cWjYEN.gif","instruction_steps":{"he":["הניחו את כדור הפיזיו על הרצפה והתמקמו בעמדת שכיבת סמיכה עם הידיים על הכדור, מעט צר מרוחב הכתפיים.","הפעילו את הליבה ושמרו על הגוף בקו ישר מהראש ועד כפות הרגליים.","הורידו את החזה לכיוון הכדור בכיפוף מרפקים, תוך שמירה עליהם קרובים לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ball by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Положите мяч на землю и примите положение для отжимания, положив руки на мяч на расстоянии чуть уже ширины плеч.","Напрягите корпус и держите тело на прямой линии от головы до пят.","Опустите грудь к мячу, согнув локти и удерживая их близко к телу.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Coloca el balón de estabilidad en el suelo y ponte en posición de flexión con las manos sobre el balón, un poco más juntas que la anchura de los hombros.","Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies.","Baja el pecho hacia el balón flexionando los codos, manteniéndolos cerca del cuerpo.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1403","name":"neck side stretch","category":"neck","body_part":"neck","equipment":"body weight","muscle_group":"trapezius","secondary_muscles":["trapezius","sternocleidomastoid"],"target":"levator scapulae","image":"images/1403-x2chWLO.jpg","gif_url":"videos/1403-x2chWLO.gif","instruction_steps":{"he":["עמדו או שבו זקוף עם כתפיים רפויות.","הטו את הראש לצד אחד, בהבאת האוזן לכיוון הכתף.","החזיקו את המתיחה 15–30 שניות.","חזרו על התנועה בצד השני.","בצעו 2–4 סטים לכל צד."],"en":["Stand or sit up straight with your shoulders relaxed.","Tilt your head to one side, bringing your ear towards your shoulder.","Hold the stretch for 15-30 seconds.","Repeat on the other side.","Perform 2-4 sets on each side."],"ru":["Встаньте или сядьте прямо, расслабив плечи.","Наклоните голову в сторону, приближая ухо к плечу.","Удерживайте растяжку 15–30 секунд.","Повторите с другой стороны.","Выполните по 2–4 подхода на каждую сторону."],"es":["Ponte de pie o siéntate erguido con los hombros relajados.","Inclina la cabeza hacia un lado, llevando la oreja hacia el hombro.","Mantén el estiramiento durante 15-30 segundos.","Repite del otro lado.","Realiza de 2 a 4 series por cada lado."]}},{"id":"0634","name":"negative crunch","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0634-szIn2UK.jpg","gif_url":"videos/0634-szIn2UK.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1495","name":"oblique crunch v. 2","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/1495-cJgSTmh.jpg","gif_url":"videos/1495-cJgSTmh.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","מקמו את הידיים מאחורי הראש או הצליבו אותן על החזה.","הפעילו את שרירי הבטן והרימו את השכמות מהרצפה, תוך סיבוב הגו לצד אחד.","עצרו לרגע, ואז הורידו את השכמות חזרה לנקודת ההתחלה.","חזרו על התנועה בצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Lie on your back with your knees bent and feet flat on the ground.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Заведите руки за голову или скрестите их на груди.","Напрягите пресс и поднимите лопатки от земли, повернув туловище в одну сторону.","Сделайте паузу на мгновение, затем опустите лопатки обратно в исходное положение.","Повторите с другой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado.","Haz una pausa por un momento y luego baja las escápulas de nuevo a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0635","name":"oblique crunches floor","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0635-QUDd8WS.jpg","gif_url":"videos/0635-QUDd8WS.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","מקמו את הידיים מאחורי הראש או הצליבו אותן על החזה.","הפעילו את שרירי הבטן והרימו את השכמות מהרצפה, תוך סיבוב הגו לצד אחד.","עצרו לרגע, ואז הורידו את השכמות חזרה לרצפה.","חזרו על התנועה בצד השני, לסירוגין בין הצדדים בכל חזרה."],"en":["Lie on your back with your knees bent and feet flat on the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the floor.","Repeat on the other side, alternating sides with each repetition."],"ru":["Лягте на спину, согните колени и поставьте ступни на пол.","Заведите руки за голову или скрестите их на груди.","Напрягите пресс и поднимите лопатки от пола, поворачивая туловище в одну сторону.","Сделайте паузу на мгновение, затем опустите лопатки обратно на пол.","Повторите то же самое с другой стороны, чередуя стороны при каждом повторении."],"es":["Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado.","Haz una pausa por un momento y luego baja las escápulas de nuevo hasta el suelo.","Repite hacia el otro lado, alternando los lados en cada repetición."]}},{"id":"0636","name":"olympic barbell hammer curl","category":"upper arms","body_part":"upper arms","equipment":"olympic barbell","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0636-o1ntciW.jpg","gif_url":"videos/0636-o1ntciW.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים והחזיקו מוט אולימפי באחיזה עליונה.","תנו למוט להשתלשל בידיים ישרות מול הירכיים, עם כפות ידיים פונות לגוף.","שמרו על הזרועות העליונות במקומן, נשפו וכופפו את המשקולות תוך כיווץ שרירי הבייספס.","המשיכו להרים את המוט עד שהבייספס מכווץ במלואו והוא בגובה הכתפיים.","החזיקו בנקודת הכיווץ לרגע קצר תוך לחיצה על הבייספס.","שאפו והתחילו להוריד את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.","Let the barbell hang at arm's length in front of your thighs, with your palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите олимпийскую штангу хватом сверху.","Пусть штанга висит на расстоянии вытянутой руки перед бедрами, ладонями к телу.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra olímpica con un agarre prono.","Deja que la barra cuelgue a la altura de los brazos frente a tus muslos, con las palmas hacia tu cuerpo.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0637","name":"olympic barbell triceps extension","category":"upper arms","body_part":"upper arms","equipment":"olympic barbell","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0637-wu5LXwz.jpg","gif_url":"videos/0637-wu5LXwz.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים, אוחזים את המוט באחיזה עליונה.","הרימו את המוט מעל הראש, עד יישור מלא של הידיים.","תוך שמירה על הזרועות העליונות קרובות לראש, הורידו באיטיות את המוט מאחורי הראש בכיפוף המרפקים.","עצרו לרגע, ואז יישרו את הידיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и удерживая штангу хватом сверху.","Поднимите штангу над головой, полностью выпрямив руки.","Держа плечи близко к голове, медленно опустите штангу за голову, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de los hombros y sosteniendo la barra con un agarre prono.","Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.","Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1355","name":"one arm against wall","category":"back","body_part":"back","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"lats","image":"images/1355-ZZTGMKh.jpg","gif_url":"videos/1355-ZZTGMKh.gif","instruction_steps":{"he":["עמדו מול קיר עם רגליים ברוחב כתפיים.","מתחו יד אחת ישר לפניכם והניחו את כף היד על הקיר.","הפעילו את הליבה והטו את הגוף קדימה, תוך שמירה על יד ישרה וגב שטוח.","דחפו באיטיות את הקיר עם כף היד, בהפעלת רחב הגבי.","החזיקו את התנוחה כמה שניות, ואז שחררו וחזרו עם היד השנייה."],"en":["Stand facing a wall with your feet shoulder-width apart.","Extend one arm straight out in front of you and place your palm against the wall.","Engage your core and lean your body forward, keeping your arm straight and your back flat.","Slowly push against the wall with your palm, activating your lat muscles.","Hold the position for a few seconds, then release and repeat with the other arm."],"ru":["Встаньте лицом к стене, ноги на ширине плеч.","Вытяните одну руку прямо перед собой и прижмите ладонь к стене.","Напрягите корпус и наклоните тело вперед, держа руку прямой, а спину ровной.","Медленно прижмите ладонь к стене, активируя широчайшие мышцы.","Удерживайте положение несколько секунд, затем отпустите и повторите то же самое с другой рукой."],"es":["Ponte de pie frente a una pared con los pies separados a la altura de los hombros.","Extiende un brazo recto hacia adelante y coloca la palma contra la pared.","Activa el core e inclina el cuerpo hacia adelante, manteniendo el brazo recto y la espalda plana.","Empuja lentamente la pared con la palma, activando los dorsales.","Mantén la posición durante unos segundos, luego suelta y repite con el otro brazo."]}},{"id":"0638","name":"one arm chin-up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0638-HjdqmZa.jpg","gif_url":"videos/0638-HjdqmZa.gif","instruction_steps":{"he":["עמדו מול מוט מתח עם רגליים ברוחב כתפיים.","הושיטו ידיים למעלה ואחזו במוט באחיזה תחתונה — יד אחת אוחזת במוט והיד השנייה אוחזת בשורש כף היד לתמיכה.","היתלו על המוט עם היד מתוחה לגמרי, תוך שמירה על גוף ישר וליבה מופעלת.","משכו את עצמכם למעלה לכיוון המוט בכיפוף המרפק וכיווץ שרירי הגב.","המשיכו למשוך עד שהסנטר מעל המוט, ואז הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים וחזרו."],"en":["Stand facing a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support.","Hang from the bar with your arm fully extended, keeping your body straight and your core engaged.","Pull yourself up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."],"ru":["Встаньте лицом к перекладине, ноги на ширине плеч.","Потянитесь вверх и возьмите перекладину хватом снизу, при этом одна рука держится за перекладину, а другая рука удерживает запястье для поддержки.","Повисните на перекладине, полностью вытянув руку, сохраняя тело прямым и напряженным корпусом.","Подтягивайтесь к перекладине, сгибая локоть и напрягая мышцы спины.","Продолжайте тянуть, пока подбородок не окажется над перекладиной, затем медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений, затем поменяйте руки и повторите."],"es":["Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros.","Estírate y agarra la barra con un agarre supino, con una mano sujetando la barra y la otra sosteniendo la muñeca como apoyo.","Cuélgate de la barra con el brazo completamente extendido, manteniendo el cuerpo recto y el core activado.","Tira de tu cuerpo hacia la barra flexionando el codo y contrayendo los músculos de la espalda.","Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo y repite."]}},{"id":"0639","name":"one arm dip","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0639-FAoIFMw.jpg","gif_url":"videos/0639-FAoIFMw.gif","instruction_steps":{"he":["עמדו עם הגב לספסל או כיסא, רגליים ברוחב כתפיים.","הניחו יד אחת על הספסל או הכיסא מאחוריכם, אצבעות פונות לכיוון הגוף.","מתחו את הרגליים לפניכם, כשהעקבים על הרצפה.","כופפו מרפקים והורידו את הגוף לכיוון הרצפה, תוך שמירה על הגב קרוב לספסל או לכיסא.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד וחזרו עם היד השנייה."],"en":["Stand facing away from a bench or chair, with your feet shoulder-width apart.","Place one hand on the bench or chair behind you, fingers pointing towards your body.","Extend your legs out in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.","Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."],"ru":["Встаньте лицом от скамьи или стула, поставив ноги на ширине плеч.","Положите одну руку на скамью или стул позади себя, пальцами направив ее к себе.","Вытяните ноги перед собой, удерживая пятки на земле.","Согните локти и опустите тело к земле, держа спину близко к скамье или стулу.","Задержитесь на мгновение в нижней точке, затем оттолкнитесь ладонями, чтобы выпрямить руки и вернуться в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону и повторите с другой рукой."],"es":["Ponte de pie de espaldas a un banco o silla, con los pies separados a la altura de los hombros.","Coloca una mano en el banco o silla detrás de ti, con los dedos apuntando hacia tu cuerpo.","Extiende las piernas hacia adelante, manteniendo los talones en el suelo.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco o silla.","Haz una pausa por un momento en la parte baja y luego empuja con las palmas para estirar los brazos y volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo."]}},{"id":"0640","name":"one arm slam (with medicine ball)","category":"waist","body_part":"waist","equipment":"medicine ball","muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"abs","image":"images/0640-jCrtE9b.jpg","gif_url":"videos/0640-jCrtE9b.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים את כדור הכוח ביד אחת מול המותניים.","כופפו ברכיים מעט והפעילו את הליבה.","הרימו את כדור הכוח מעל הראש, במתיחת היד המלאה.","הטיחו בעוצמה את כדור הכוח ברצפה, בעזרת הליבה והכתפיים ליצירת כוח.","תפסו את כדור הכוח בקפיצה חזרה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.","Bend your knees slightly and engage your core.","Raise the medicine ball above your head, fully extending your arm.","Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power.","Catch the medicine ball on the bounce and repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, удерживая медицинский мяч одной рукой перед талией.","Слегка согните колени и задействуйте корпус.","Поднимите медицинский мяч над головой, полностью выпрямляя руку.","С силой ударьте набивным мячом по земле, используя корпус и плечи для создания силы.","Поймайте медицинский мяч в момент отскока и повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal con una mano frente a la cintura.","Flexiona ligeramente las rodillas y activa el core.","Eleva el balón medicinal por encima de la cabeza, extendiendo completamente el brazo.","Lanza con fuerza el balón medicinal contra el suelo, usando el core y los hombros para generar potencia.","Atrapa el balón medicinal al rebotar y repite el número de repeticiones deseado."]}},{"id":"1773","name":"one arm towel row","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1773-bKWbrTA.jpg","gif_url":"videos/1773-bKWbrTA.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, ברכיים כפופות מעט, ואחזו מגבת ביד אחת.","הטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר וליבה מופעלת.","יישרו את היד לגמרי, ותנו למגבת להשתלשל לפניכם.","משכו את המגבת לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המגבת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ידיים."],"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm fully, allowing the towel to hang in front of you.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"ru":["Встаньте, ноги на ширине плеч, колени слегка согнуты, одной рукой держите полотенце.","Наклонитесь вперед в талии, сохраняя спину прямой и напрягая корпус.","Полностью вытяните руку, чтобы полотенце висело перед вами.","Подтяните полотенце к груди, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите полотенце обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"es":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.","Extiende completamente el brazo, dejando que la toalla cuelgue frente a ti.","Tira de la toalla hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."]}},{"id":"1386","name":"one leg donkey calf raise","category":"lower legs","body_part":"lower legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1386-A2upspL.jpg","gif_url":"videos/1386-A2upspL.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, כפות רגליים פונות קדימה.","הניחו את הידיים על משטח יציב לתמיכה, כמו קיר או מוט.","הרימו רגל אחת מהרצפה, עם ברך כפופה מעט.","הרימו את העקב גבוה ככל האפשר, בעזרת שרירי התאומים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקב באיטיות חזרה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a stable surface for support, such as a wall or a bar.","Lift one leg off the ground, keeping your knee slightly bent.","Raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Встаньте, ноги на ширине плеч, носки направлены вперед.","Положите руки на устойчивую поверхность для поддержки, например, на стену или перекладину.","Поднимите одну ногу от земли, слегка согнув колено.","Поднимите пятку как можно выше, задействуя икроножные мышцы.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятку обратно вниз.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.","Coloca las manos sobre una superficie estable para apoyarte, como una pared o una barra.","Levanta una pierna del suelo, manteniendo la rodilla ligeramente flexionada.","Eleva el talón lo más alto posible, usando los músculos de la pantorrilla.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"1387","name":"one leg floor calf raise","category":"lower legs","body_part":"lower legs","equipment":"body weight","muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/1387-0jp9Rlz.jpg","gif_url":"videos/1387-0jp9Rlz.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן והניחו את הידיים על קיר או חפץ יציב לשיווי משקל.","הרימו כף רגל אחת מהרצפה ואזנו על כף הרגל השנייה.","הרימו באיטיות את העקב מהרצפה, בהרמת הגוף על כרית כף הרגל.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקב באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגליים וחזרו על התרגיל."],"en":["Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel off the ground, lifting your body up onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"ru":["Встаньте, расставив ноги на ширине плеч, и положите руки на стену или прочный предмет для равновесия.","Поднимите одну ногу от земли и балансируйте на другой ноге.","Медленно поднимите пятку от земли, поднимая тело на подушечки стопы.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятку обратно в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу и повторите."],"es":["Ponte de pie con los pies separados a la altura de las caderas y coloca las manos en una pared u objeto firme para mantener el equilibrio.","Levanta un pie del suelo y mantén el equilibrio sobre el otro pie.","Levanta lentamente el talón del suelo, elevando el cuerpo sobre las puntas de los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."]}},{"id":"1476","name":"one leg squat","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1476-C31LMnP.jpg","gif_url":"videos/1476-C31LMnP.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","מתחו רגל אחת קדימה, כשהיא באוויר.","כופפו את רגל העמידה והורידו את הגוף כאילו אתם מתיישבים לאחור על כיסא.","שמרו על חזה מורם וגב ישר.","דחפו דרך העקב לחזרה לנקודת ההתחלה.","חזרו על התנועה עם הרגל השנייה."],"en":["Stand with your feet shoulder-width apart.","Extend one leg forward, keeping it off the ground.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Push through your heel to return to the starting position.","Repeat with the other leg."],"ru":["Встаньте, ноги на ширине плеч.","Вытяните одну ногу вперед, не отрывая ее от земли.","Согните стоящую ногу и опустите тело вниз, как будто садитесь на стул.","Держите грудь поднятой, а спину прямой.","Оттолкнитесь пяткой, чтобы вернуться в исходное положение.","Повторите с другой ногой."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Extiende una pierna hacia adelante, manteniéndola elevada del suelo.","Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla.","Mantén el pecho arriba y la espalda recta.","Empuja con el talón para regresar a la posición inicial.","Repite con la otra pierna."]}},{"id":"0641","name":"otis up","category":"waist","body_part":"waist","equipment":"weighted","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0641-UVL20oz.jpg","gif_url":"videos/0641-UVL20oz.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0642","name":"outside leg kick push-up","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0642-jNU1gFQ.jpg","gif_url":"videos/0642-jNU1gFQ.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים מעט רחבות מרוחב הכתפיים ורגליים צמודות.","הורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה על גב ישר וליבה מופעלת.","תוך כדי הדחיפה חזרה למעלה, בעטו רגל אחת הצידה, במתיחתה המלאה והפעלת הישבן.","החזירו את הרגל לנקודת ההתחלה וחזרו על שכיבת הסמיכה, לסירוגין בין הרגליים בכל חזרה.","המשיכו להחליף בעיטות רגליים ושכיבות סמיכה למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.","Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.","Continue alternating leg kicks and push-ups for the desired number of repetitions."],"ru":["Начните с позиции для отжиманий, поставив руки чуть шире плеч, а ноги вместе.","Опустите тело к земле, согнув локти, сохраняя спину прямой и напряженным корпусом.","Отталкиваясь назад, отведите одну ногу в сторону, полностью выпрямляя ее и задействуя ягодицы.","Верните ногу в исходное положение и повторите отжимание, чередуя ноги при каждом повторении.","Продолжайте чередовать удары ногами и отжимания желаемое количество повторений."],"es":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado.","Al empujar de vuelta hacia arriba, lanza una pierna hacia el lado, extendiéndola completamente y activando los glúteos.","Vuelve a colocar la pierna en la posición inicial y repite la flexión, alternando las piernas en cada repetición.","Continúa alternando las patadas de pierna y las flexiones el número de repeticiones deseado."]}},{"id":"0643","name":"overhead triceps stretch","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0643-Z5YStHW.jpg","gif_url":"videos/0643-Z5YStHW.gif","instruction_steps":{"he":["עמדו או שבו זקוף עם רגליים ברוחב כתפיים.","מתחו יד אחת מעל הראש, בכיפוף המרפק כך שכף היד מגיעה לכיוון השכמה הנגדית.","עם היד השנייה, משכו בעדינות את מרפק היד המתוחה לכיוון הצד הנגדי של הראש, עד תחושת מתיחה בטרייספס.","החזיקו את המתיחה 15–30 שניות, ואז שחררו.","חזרו על התנועה בצד השני."],"en":["Stand or sit upright with your feet shoulder-width apart.","Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.","With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."],"ru":["Встаньте или сядьте прямо, ноги на ширине плеч.","Вытяните одну руку над головой, согнув ее в локте так, чтобы рука тянулась к противоположной лопатке.","Другой рукой осторожно потяните локоть вытянутой руки к противоположной стороне головы, чувствуя растяжение трицепса.","Удерживайте растяжку 15–30 секунд, затем расслабьтесь.","Повторите с другой стороны."],"es":["Ponte de pie o siéntate erguido con los pies separados a la altura de los hombros.","Extiende un brazo por encima de la cabeza, flexionando el codo de modo que la mano llegue hacia la escápula opuesta.","Con la otra mano, tira suavemente del codo del brazo extendido hacia el lado opuesto de la cabeza, sintiendo un estiramiento en el tríceps.","Mantén el estiramiento durante 15-30 segundos, luego suelta.","Repite del otro lado."]}},{"id":"3147","name":"pelvic tilt","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"lower back","secondary_muscles":["lower back"],"target":"abs","image":"images/3147-NKJ8o6x.jpg","gif_url":"videos/3147-NKJ8o6x.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים לצידי הגוף.","הפעילו את שרירי הבטן והטו את האגן כלפי מעלה, בלחיצת הגב התחתון לרצפה.","החזיקו את התנוחה כמה שניות, בהתמקדות בכיווץ שרירי הבטן.","שחררו את ההטיה וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides.","Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.","Hold this position for a few seconds, focusing on contracting your abs.","Release the tilt and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки по бокам.","Напрягите пресс и наклоните таз вверх, прижимая поясницу к земле.","Удерживайте это положение несколько секунд, сосредоточив внимание на сокращении пресса.","Освободите наклон и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos a los lados del cuerpo.","Activa el abdomen e inclina la pelvis hacia arriba, presionando la zona lumbar contra el suelo.","Mantén esta posición durante unos segundos, concentrándote en contraer el abdomen.","Deshaz la inclinación y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1422","name":"pelvic tilt into bridge","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","core"],"target":"glutes","image":"images/1422-D9qe7CM.jpg","gif_url":"videos/1422-D9qe7CM.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים לצידי הגוף, כפות ידיים כלפי מטה.","הפעילו את שרירי הישבן והליבה.","הטו את האגן כלפי מעלה, בהרמתו מהרצפה.","החזיקו את תנוחת הגשר כמה שניות.","הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on your back with your knees bent and feet flat on the ground.","Place your arms by your sides with your palms facing down.","Engage your glutes and core muscles.","Tilt your pelvis upward, lifting your hips off the ground.","Hold the bridge position for a few seconds.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки по бокам ладонями вниз.","Задействуйте ягодицы и мышцы корпуса.","Наклоните таз вверх, отрывая бедра от земли.","Удерживайте положение моста в течение нескольких секунд.","Медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca los brazos a los lados del cuerpo con las palmas hacia abajo.","Activa los glúteos y los músculos del core.","Inclina la pelvis hacia arriba, levantando las caderas del suelo.","Mantén la posición de puente durante unos segundos.","Baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1388","name":"peroneals stretch","category":"lower legs","body_part":"lower legs","equipment":"rope","muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/1388-XhfS1DZ.jpg","gif_url":"videos/1388-XhfS1DZ.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים ישרות לפניכם.","לפפו את החבל סביב כרית כף הרגל והחזיקו את קצוות החבל בידיים.","משכו בעדינות את החבל אליכם, בכיפוף כף הרגל ומתיחת שרירי התאומים.","החזיקו את המתיחה 15–30 שניות.","שחררו את המתח בחבל וחזרו על המתיחה ברגל השנייה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the ground with your legs extended in front of you.","Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Hold the stretch for 15-30 seconds.","Release the tension on the rope and repeat the stretch on the other leg.","Repeat for the desired number of repetitions."],"ru":["Сядьте на пол, вытянув ноги перед собой.","Оберните веревку вокруг подушечки стопы и удерживайте концы веревки руками.","Аккуратно потяните веревку на себя, сгибая ногу и растягивая икроножные мышцы.","Удерживайте растяжку 15–30 секунд.","Ослабьте натяжение веревки и повторите растяжку для другой ноги.","Повторите необходимое количество повторений."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti.","Enrolla la cuerda alrededor de la planta del pie y sujeta los extremos de la cuerda con las manos.","Tira suavemente de la cuerda hacia ti, flexionando el pie y estirando los músculos de la pantorrilla.","Mantén el estiramiento durante 15-30 segundos.","Suelta la tensión de la cuerda y repite el estiramiento en la otra pierna.","Repite el número de repeticiones deseado."]}},{"id":"3662","name":"pike-to-cobra push-up","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"core","secondary_muscles":["core","shoulders","triceps"],"target":"glutes","image":"images/3662-XPUDTt7.jpg","gif_url":"videos/3662-XPUDTt7.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים מעט רחבות מרוחב הכתפיים ורגליים צמודות.","הפעילו את הליבה והרימו את האגן לכיוון התקרה, ביצירת צורת V הפוכה עם הגוף.","הורידו את פלג הגוף העליון לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם צמודים לגוף.","תוך כדי הירידה, העבירו את המשקל קדימה ועברו לתנוחת קוברה — יישרו ידיים והרימו את החזה.","הפכו את התנועה בכיפוף מרפקים והורדת החזה חזרה לכיוון הרצפה.","דחפו דרך הידיים לחזרה לתנוחת ה-V ההפוכה.","המשיכו את התנועה בהורדת האגן חזרה לכיוון הרצפה, בחזרה לעמדת שכיבת הסמיכה ההתחלתית.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.","Lower your upper body towards the ground by bending your elbows, keeping them close to your body.","As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.","Reverse the movement by bending your elbows and lowering your chest back down towards the ground.","Push through your hands to return to the inverted V position.","Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции для отжиманий, поставив руки чуть шире плеч, а ноги вместе.","Напрягите корпус и поднимите бедра к потолку, образуя своим телом перевернутую V-образную форму.","Опустите верхнюю часть тела к земле, согнув локти и удерживая их близко к телу.","Опускаясь вниз, перенесите вес тела вперед и перейдите в позу кобры, выпрямив руки и подняв грудь вверх.","Выполните обратное движение, согнув локти и опустив грудь обратно к земле.","Протолкните руки, чтобы вернуться в положение перевернутой буквы V.","Продолжайте движение, опуская бедра обратно к земле и возвращаясь в исходное положение для отжиманий.","Повторите необходимое количество повторений."],"es":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Activa el core y eleva las caderas hacia el techo, formando una V invertida con tu cuerpo.","Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.","Al bajar, desplaza el peso hacia adelante y haz la transición a una postura de cobra estirando los brazos y elevando el pecho.","Invierte el movimiento flexionando los codos y bajando el pecho de nuevo hacia el suelo.","Empuja con las manos para volver a la posición de V invertida.","Continúa el movimiento bajando las caderas de nuevo hacia el suelo, volviendo a la posición inicial de flexión.","Repite el número de repeticiones deseado."]}},{"id":"1306","name":"plyo push up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/1306-Snj1wSv.jpg","gif_url":"videos/1306-Snj1wSv.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים מעט רחבות מרוחב הכתפיים.","הורידו את החזה לכיוון הרצפה בכיפוף מרפקים, תוך שמירה על גוף בקו ישר.","דחפו בפיצוץ מהרצפה, בעזרת שרירי החזה להעפת פלג הגוף העליון מהרצפה.","נחתו ברכות כשהידיים חוזרות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground by bending your elbows, keeping your body in a straight line.","Push explosively off the ground, using your chest muscles to propel your upper body off the ground.","Land softly with your hands back in the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, расставив руки чуть шире плеч.","Опустите грудь к земле, сгибая локти, сохраняя тело прямой.","Резко оттолкнитесь от земли, используя мышцы груди, чтобы оторвать верхнюю часть тела от земли.","Мягко приземлитесь, вернув руки в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.","Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta.","Empuja explosivamente contra el suelo, usando los músculos del pecho para impulsar la parte superior del cuerpo fuera del suelo.","Aterriza suavemente con las manos de vuelta en la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1687","name":"posterior step to overhead reach","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","quadriceps","shoulders"],"target":"abs","image":"images/1687-ErqK3UL.jpg","gif_url":"videos/1687-ErqK3UL.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן וידיים לצידי הגוף.","צעדו לאחור עם כף רגל ימין, בנחיתה על כרית כף הרגל.","כופפו את ברך שמאל והורידו את הגוף לעמדת מספריים.","תוך כדי הירידה למספריים, מתחו בו-זמנית את הידיים מעל הראש.","עצרו לרגע בנקודה התחתונה של המספריים, ואז חזרו לנקודת ההתחלה בדחיפה דרך עקב שמאל והבאת כף רגל ימין קדימה.","חזרו על התנועה בצד השני, בצעד לאחור עם כף רגל שמאל וכיפוף ברך ימין.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet hip-width apart and your arms by your sides.","Take a step back with your right foot, landing on the ball of your foot.","Bend your left knee and lower your body into a lunge position.","As you lower into the lunge, simultaneously reach your arms overhead.","Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.","Repeat the movement on the other side, stepping back with your left foot and bending your right knee.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, руки по бокам.","Сделайте шаг назад правой ногой, приземлившись на подушечку стопы.","Согните левое колено и опустите тело в положение выпада.","Опускаясь в выпад, одновременно вытяните руки над головой.","Сделайте паузу на мгновение в нижней части выпада, затем вернитесь в исходное положение, отталкивая левую пятку и вынося правую ногу вперед.","Повторите движение в другую сторону, отступив левой ногой назад и согнув правое колено.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de las caderas y los brazos a los lados del cuerpo.","Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.","Flexiona la rodilla izquierda y baja el cuerpo a una posición de zancada.","Mientras bajas a la zancada, lleva simultáneamente los brazos por encima de la cabeza.","Haz una pausa por un momento en la parte baja de la zancada y luego vuelve a la posición inicial empujando con el talón izquierdo y llevando el pie derecho hacia adelante.","Repite el movimiento hacia el otro lado, retrocediendo con el pie izquierdo y flexionando la rodilla derecha.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1389","name":"posterior tibialis stretch","category":"lower legs","body_part":"lower legs","equipment":"rope","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/1389-DEEqoI2.jpg","gif_url":"videos/1389-DEEqoI2.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים ישרות לפניכם.","לפפו את החבל סביב כרית כף הרגל והחזיקו את קצוות החבל בידיים.","משכו בעדינות את החבל אליכם, בכיפוף כף הרגל ומתיחת שרירי התאומים.","החזיקו את המתיחה 20–30 שניות.","שחררו את המתח בחבל והרפו את כף הרגל.","חזרו על המתיחה ברגל השנייה."],"en":["Sit on the ground with your legs extended in front of you.","Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Hold the stretch for 20-30 seconds.","Release the tension on the rope and relax your foot.","Repeat the stretch on the other leg."],"ru":["Сядьте на пол, вытянув ноги перед собой.","Оберните веревку вокруг подушечки стопы и удерживайте концы веревки руками.","Аккуратно потяните веревку на себя, сгибая ногу и растягивая икроножные мышцы.","Удерживайте растяжку 20–30 секунд.","Ослабьте натяжение веревки и расслабьте ногу.","Повторите растяжку на другой ноге."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti.","Enrolla la cuerda alrededor de la planta del pie y sujeta los extremos de la cuerda con las manos.","Tira suavemente de la cuerda hacia ti, flexionando el pie y estirando los músculos de la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Suelta la tensión de la cuerda y relaja el pie.","Repite el estiramiento en la otra pierna."]}},{"id":"3119","name":"potty squat","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","glutes"],"target":"abs","image":"images/3119-75Bgtjy.jpg","gif_url":"videos/3119-75Bgtjy.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, קצות האצבעות של הרגליים פונות מעט החוצה.","הורידו את הגוף בכיפוף ברכיים ודחיפת האגן לאחור כאילו אתם מתיישבים על כיסא.","שמרו על חזה מורם וגב ישר לאורך כל התנועה.","רדו עד שהירכיים מקבילות לרצפה או נמוך ככל שנוח לכם.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.","Keep your chest up and your back straight throughout the movement.","Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","Опустите тело вниз, согнув колени и отведя бедра назад, как будто вы сидите на стуле.","На протяжении всего движения держите грудь поднятой, а спину прямой.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla.","Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.","Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3132","name":"potty squat with support","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3132-b63ZzGe.jpg","gif_url":"videos/3132-b63ZzGe.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, קצות האצבעות של הרגליים פונות מעט החוצה.","אחזו במשענת יציבה, כמו כיסא או קיר, לשיווי משקל.","הורידו את הגוף לעמדת סקוואט בכיפוף ברכיים ודחיפת האגן לאחור.","שמרו על חזה מורם וגב ישר לאורך כל התנועה.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold onto a stable support, such as a chair or wall, for balance.","Lower your body down into a squat position by bending your knees and pushing your hips back.","Keep your chest up and your back straight throughout the movement.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","Для равновесия держитесь за устойчивую опору, например, за стул или стену.","Опустите тело в положение приседа, согнув колени и отведя бедра назад.","На протяжении всего движения держите грудь поднятой, а спину прямой.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Sujétate de un apoyo estable, como una silla o una pared, para mantener el equilibrio.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0648","name":"power clean","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"glutes","secondary_muscles":["glutes","quadriceps","calves"],"target":"hamstrings","image":"images/0648-SiWCcTN.jpg","gif_url":"videos/0648-SiWCcTN.gif","instruction_steps":{"he":["התחילו עם המוט על הרצפה לפניכם, עם רגליים ברוחב כתפיים.","התכופפו ואחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שמרו על גב ישר וחזה מורם תוך הרמת המוט מהרצפה, ביישור הירכיים והברכיים.","כשהמוט מגיע לאמצע הירך, משכו אותו למעלה בפיצוץ, במשיכת כתפיים והבאת המרפקים גבוה ולצדדים.","כשהמוט מגיע לנקודה הגבוהה ביותר, רדו מתחתיו במהירות, בסיבוב המרפקים ותפיסת המוט על הכתפיים בעמדת סקוואט קדמי.","עמדו עם המוט, ביישור מלא של הירכיים והברכיים.","הורידו את המוט חזרה לנקודת ההתחלה, תוך שליטה במשקל לאורך כל התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start with the barbell on the ground in front of you, with your feet shoulder-width apart.","Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees.","As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position.","Stand up with the barbell, fully extending your hips and knees.","Lower the barbell back down to the starting position, keeping control of the weight throughout the movement.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что штанга лежит на земле перед собой, ноги на ширине плеч.","Наклонитесь и возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Держите спину прямо и грудь вверх, поднимая штангу с земли, вытягивая бедра и колени.","Когда штанга достигнет середины бедра, резко потяните ее вверх, пожимая плечами и отводя локти высоко и в стороны.","Когда штанга достигнет своей наивысшей точки, быстро опуститесь под нее, развернув локти и удерживая штангу на плечах в положении переднего приседа.","Встаньте со штангой, полностью выпрямив бедра и колени.","Опустите штангу обратно в исходное положение, сохраняя контроль над весом на протяжении всего движения.","Повторите необходимое количество повторений."],"es":["Comienza con la barra en el suelo frente a ti, con los pies separados a la altura de los hombros.","Agáchate y agarra la barra con un agarre prono, un poco más separado que la anchura de los hombros.","Mantén la espalda recta y el pecho hacia arriba al levantar la barra del suelo, extendiendo las caderas y las rodillas.","Cuando la barra llegue a la mitad del muslo, tira de ella explosivamente hacia arriba, encogiendo los hombros y llevando los codos hacia arriba y hacia los lados.","Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, rotando los codos y atrapando la barra sobre los hombros en una posición de sentadilla frontal.","Ponte de pie con la barra, extendiendo completamente las caderas y las rodillas.","Baja la barra de nuevo a la posición inicial, manteniendo el control del peso durante todo el movimiento.","Repite el número de repeticiones deseado."]}},{"id":"3665","name":"power point plank","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","glutes"],"target":"abs","image":"images/3665-hCjGsRQ.jpg","gif_url":"videos/3665-hCjGsRQ.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים ישר מתחת לכתפיים והגוף בקו ישר מהראש ועד כפות הרגליים.","הפעילו את הליבה וכווצו את הישבן לשמירה על תנוחה יציבה.","הורידו את הגוף אל האמות, יד אחת בכל פעם, תוך שמירה על קו ישר מהראש ועד כפות הרגליים.","החזיקו את התנוחה למשך הזמן הרצוי, תוך שמירה על ליבה וישבן מופעלים.","לחזרה לנקודת ההתחלה, דחפו דרך האמות והרימו את הגוף חזרה לעמדת פלאנק גבוה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and squeeze your glutes to maintain a stable position.","Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.","Hold this position for the desired amount of time, keeping your core and glutes engaged.","To return to the starting position, push through your forearms and lift your body back up into a high plank position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, положив руки прямо под плечи, а тело образуя прямую линию от головы до пят.","Напрягите корпус и сожмите ягодицы, чтобы сохранить устойчивое положение.","Опустите тело на предплечья, по одной руке за раз, сохраняя прямую линию от головы до пят.","Удерживайте это положение желаемое время, сохраняя при этом мышцы корпуса и ягодиц.","Чтобы вернуться в исходное положение, оттолкнитесь предплечьями и поднимите тело обратно в положение высокой планки.","Повторите необходимое количество повторений."],"es":["Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies.","Activa el core y aprieta los glúteos para mantener una posición estable.","Baja el cuerpo hasta los antebrazos, un brazo a la vez, manteniendo una línea recta de la cabeza a los pies.","Mantén esta posición durante el tiempo deseado, con el core y los glúteos activados.","Para volver a la posición inicial, empuja con los antebrazos y eleva el cuerpo de nuevo a una posición de plancha alta.","Repite el número de repeticiones deseado."]}},{"id":"3203","name":"prisoner half sit-up (male)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3203-mgejmGP.jpg","gif_url":"videos/3203-mgejmGP.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1707","name":"prone twist on stability ball","category":"waist","body_part":"waist","equipment":"stability ball","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/1707-1IG6gVF.jpg","gif_url":"videos/1707-1IG6gVF.gif","instruction_steps":{"he":["התחילו בשכיבה על הבטן על כדור פיזיו עם רגליים ברוחב כתפיים וקצות האצבעות של הרגליים נוגעות ברצפה.","מקמו את הידיים מאחורי הראש או הצליבו אותן על החזה.","הפעילו את שרירי הליבה והרימו באיטיות את פלג הגוף העליון מהכדור, תוך שמירה על גב ישר.","סובבו את הגו לצד אחד, בהבאת הכתף לכיוון המותן. שמרו על אגן ורגליים יציבים לאורך כל התנועה.","עצרו לרגע, ואז חזרו לנקודת ההתחלה.","חזרו על הסיבוב לצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.","Place your hands behind your head or cross them over your chest.","Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.","Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.","Pause for a moment, then return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Начните с того, что лягте лицом вниз на мяч для стабилизации, поставив ноги на ширине плеч и коснувшись пальцами ног земли.","Заведите руки за голову или скрестите их на груди.","Задействуйте мышцы корпуса и медленно поднимите верхнюю часть тела с мяча, сохраняя спину прямой.","Поверните туловище в сторону, приближая плечо к бедру. Держите бедра и ноги устойчивыми на протяжении всего движения.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите поворот в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Comienza tumbándote boca abajo sobre un balón de estabilidad con los pies separados a la altura de los hombros y los dedos de los pies tocando el suelo.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa los músculos del core y eleva lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta.","Rota el torso hacia un lado, llevando el hombro hacia la cadera. Mantén las caderas y las piernas estables durante todo el movimiento.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite la rotación hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0651","name":"pull up (neutral grip)","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0651-0V2YQjW.jpg","gif_url":"videos/0651-0V2YQjW.gif","instruction_steps":{"he":["היתלו על מוט מתח באחיזה ניטרלית (כפות ידיים פונות זו לזו) וידיים ישרות לגמרי.","הפעילו את שרירי הליבה וכווצו את השכמות זו לזו.","משכו את הגוף למעלה לכיוון המוט בכיפוף מרפקים והורדתם למטה לכיוון הירכיים.","המשיכו למשוך עד שהסנטר מעל המוט.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות ובשליטה חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине нейтральным хватом (ладони обращены друг к другу) и полностью выпрямите руки.","Напрягите корпус и сведите лопатки вместе.","Подтяните тело к перекладине, сгибая локти и направляя локти вниз к бедрам.","Продолжайте тянуть, пока подбородок не окажется над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение, контролируя его.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con un agarre neutro (las palmas enfrentadas) y los brazos completamente extendidos.","Activa el core y junta los omóplatos.","Tira de tu cuerpo hacia la barra flexionando los codos y llevándolos hacia las caderas.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte alta y luego baja lentamente tu cuerpo, con control, hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0650","name":"pull-in (on stability ball)","category":"waist","body_part":"waist","equipment":"stability ball","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0650-UQr48Oi.jpg","gif_url":"videos/0650-UQr48Oi.gif","instruction_steps":{"he":["התחילו בישיבה על כדור הפיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","הניחו את הידיים על צידי כדור הפיזיו לתמיכה.","הפעילו את שרירי הבטן וגלגלו באיטיות את האגן קדימה, בהבאת הברכיים לכיוון החזה.","עצרו לרגע בנקודה העליונה של התנועה, ואז יישרו באיטיות את הרגליים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the sides of the stability ball for support.","Engage your abs and slowly roll your hips forward, bringing your knees towards your chest.","Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что сядьте на мяч для стабилизации, поставив ступни на землю и согнув колени под углом 90 градусов.","Положите руки по бокам мяча для устойчивости.","Напрягите пресс и медленно поверните бедра вперед, подтягивая колени к груди.","Сделайте паузу на мгновение в верхней точке движения, затем медленно вытяните ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza sentándote en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas a un ángulo de 90 grados.","Coloca las manos a los lados del balón de estabilidad para mayor apoyo.","Activa el abdomen y rueda lentamente las caderas hacia adelante, llevando las rodillas hacia el pecho.","Haz una pausa por un momento en la parte alta del movimiento y luego extiende lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0652","name":"pull-up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0652-lBDjFxJ.jpg","gif_url":"videos/0652-lBDjFxJ.gif","instruction_steps":{"he":["היתלו על מוט מתח עם כפות ידיים פונות מכם וידיים ישרות לגמרי.","הפעילו את שרירי הליבה וכווצו את השכמות זו לזו.","משכו את הגוף למעלה לכיוון המוט על ידי כיפוף המרפקים והבאת החזה אל המוט.","עצרו בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your palms facing away from you and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, повернув ладонями от себя и полностью вытянув руки.","Напрягите корпус и сведите лопатки вместе.","Подтяните тело к перекладине, сгибая локти и приближая грудь к перекладине.","Сделайте паузу в верхней точке движения, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos.","Activa el core y junta los omóplatos.","Tira de tu cuerpo hacia la barra flexionando los codos y llevando el pecho hacia la barra.","Haz una pausa en la parte alta del movimiento y luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1689","name":"push and pull bodyweight","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","deltoids"],"target":"pectorals","image":"images/1689-wXvUZC8.jpg","gif_url":"videos/1689-wXvUZC8.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים מעט רחבות מרוחב הכתפיים והגוף בקו ישר.","הורידו את החזה לכיוון הרצפה בכיפוף מרפקים, תוך שמירה על גוף ישר.","דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","מעמדת שכיבת הסמיכה, משכו את החזה לכיוון הרצפה בכיפוף מרפקים, תוך שמירה על גוף ישר.","דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции для отжиманий, расставив руки чуть шире ширины плеч, а тело образуя прямую линию.","Опустите грудь к земле, согнув локти, сохраняя тело прямым.","Оттолкнитесь ладонями, чтобы вытянуть руки и вернуться в исходное положение.","Из положения отжимания подтяните грудь к земле, сгибая локти, сохраняя тело прямым.","Оттолкнитесь ладонями, чтобы вытянуть руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta.","Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Desde la posición de flexión, tira del pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3638","name":"push to run","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3638-PrQbjvB.jpg","gif_url":"videos/3638-PrQbjvB.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים ברוחב כתפיים והגוף בקו ישר.","הורידו את החזה לכיוון הרצפה בכיפוף מרפקים, תוך שמירה על גוף ישר.","דחפו דרך הידיים ליישורן וחזרה לנקודת ההתחלה.","הביאו במהירות ברך אחת לכיוון החזה, ואז החליפו במהירות והביאו את הברך השנייה לכיוון החזה.","המשיכו להחליף ברכיים מהר ככל האפשר תוך שמירה על טכניקה נכונה.","המשיכו למשך הזמן או מספר החזרות הרצוי."],"en":["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your hands to extend your arms and return to the starting position.","Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest.","Continue alternating knees as fast as you can while maintaining good form.","Continue for the desired duration or number of repetitions."],"ru":["Начните с позиции для отжиманий, поставив руки на ширине плеч, а тело образуя прямую линию.","Опустите грудь к земле, согнув локти, сохраняя тело прямым.","Оттолкнитесь руками, чтобы вытянуть руки и вернуться в исходное положение.","Быстро поднесите одно колено к груди, затем быстро поменяйте местами и подтяните другое колено к груди.","Продолжайте чередовать колени так быстро, как только можете, сохраняя при этом хорошую форму.","Продолжайте желаемую продолжительность или количество повторений."],"es":["Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta.","Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto.","Empuja con las manos para extender los brazos y volver a la posición inicial.","Lleva rápidamente una rodilla hacia el pecho, luego cambia rápidamente y lleva la otra rodilla hacia el pecho.","Continúa alternando las rodillas tan rápido como puedas manteniendo una buena forma.","Continúa durante el tiempo o el número de repeticiones deseado."]}},{"id":"1307","name":"push up on bosu ball","category":"chest","body_part":"chest","equipment":"bosu ball","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/1307-wVompEp.jpg","gif_url":"videos/1307-wVompEp.gif","instruction_steps":{"he":["הניחו את כדור הבוסו על הרצפה כשהצד השטוח פונה כלפי מעלה.","התמקמו בעמדת שכיבת סמיכה עם הידיים על הקצוות החיצוניים של כדור הבוסו.","הפעילו את הליבה והורידו את הגוף לכיוון כדור הבוסו בכיפוף מרפקים.","דחפו את עצמכם חזרה למעלה לנקודת ההתחלה על ידי יישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"ru":["Положите босу-шар на землю плоской стороной вверх.","Займите позицию для отжимания, положив руки на внешние края мяча босу.","Напрягите корпус и опустите тело вниз к мячу босу, ​​сгибая локти.","Вернитесь в исходное положение, вытянув руки.","Повторите необходимое количество повторений."],"es":["Coloca el bosu en el suelo con el lado plano hacia arriba.","Colócate en posición de flexión con las manos en los bordes exteriores del bosu.","Activa el core y baja el cuerpo hacia el bosu flexionando los codos.","Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0662","name":"push-up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","deltoids","core"],"target":"pectorals","image":"images/0662-I4hDWkc.jpg","gif_url":"videos/0662-I4hDWkc.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים מעט רחבות מרוחב הכתפיים ורגליים צמודות.","הפעילו את שרירי הליבה והורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה על גוף בקו ישר.","עצרו לרגע כשהחזה מעט מעל הרצפה, ואז דחפו את עצמכם חזרה למעלה על ידי יישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line.","Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, расставив руки чуть шире плеч и поставив ноги вместе.","Напрягите корпус и опустите тело к земле, сгибая локти, удерживая тело на прямой линии.","Сделайте паузу на мгновение, когда ваша грудь окажется чуть выше земли, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta.","Haz una pausa cuando el pecho esté justo por encima del suelo y luego empújate de vuelta a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0653","name":"push-up (bosu ball)","category":"chest","body_part":"chest","equipment":"bosu ball","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0653-2kr2lWy.jpg","gif_url":"videos/0653-2kr2lWy.gif","instruction_steps":{"he":["הניחו את כדור הבוסו על הרצפה כשהצד השטוח פונה כלפי מעלה.","התמקמו בעמדת שכיבת סמיכה עם הידיים על הקצוות החיצוניים של כדור הבוסו.","הפעילו את הליבה והורידו את הגוף לכיוון כדור הבוסו בכיפוף מרפקים.","דחפו את עצמכם חזרה למעלה לנקודת ההתחלה על ידי יישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"ru":["Положите босу-шар на землю плоской стороной вверх.","Займите позицию для отжимания, положив руки на внешние края мяча босу.","Напрягите корпус и опустите тело вниз к мячу босу, ​​сгибая локти.","Вернитесь в исходное положение, вытянув руки.","Повторите необходимое количество повторений."],"es":["Coloca el bosu en el suelo con el lado plano hacia arriba.","Colócate en posición de flexión con las manos en los bordes exteriores del bosu.","Activa el core y baja el cuerpo hacia el bosu flexionando los codos.","Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0655","name":"push-up (on stability ball)","category":"chest","body_part":"chest","equipment":"stability ball","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0655-Y4BRNQF.jpg","gif_url":"videos/0655-Y4BRNQF.gif","instruction_steps":{"he":["הניחו את כדור הפיזיו על הרצפה והתמקמו עם הפנים כלפי מטה, ידיים על הכדור ברוחב כתפיים.","מתחו את הרגליים ישר לאחור, באיזון על קצות האצבעות של הרגליים.","הפעילו את הליבה והורידו את החזה לכיוון הכדור בכיפוף מרפקים, תוך שמירה על גוף בקו ישר.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Extend your legs straight out behind you, balancing on your toes.","Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Положите мяч на землю и расположитесь лицом вниз, положив руки на мяч на ширине плеч.","Вытяните ноги прямо позади себя, балансируя на носках.","Напрягите корпус и опустите грудь к мячу, сгибая локти, удерживая тело на прямой линии.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Coloca el balón de estabilidad en el suelo y ponte boca abajo con las manos sobre el balón, separadas a la altura de los hombros.","Extiende las piernas rectas detrás de ti, equilibrándote sobre los dedos de los pies.","Activa el core y baja el pecho hacia el balón flexionando los codos, manteniendo el cuerpo en línea recta.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0656","name":"push-up (on stability ball)","category":"chest","body_part":"chest","equipment":"stability ball","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0656-tgryw5Y.jpg","gif_url":"videos/0656-tgryw5Y.gif","instruction_steps":{"he":["הניחו את כדור הפיזיו על הרצפה והתמקמו עם הפנים כלפי מטה, ידיים על הכדור ברוחב כתפיים.","מתחו את הרגליים ישר לאחור, באיזון על קצות האצבעות של הרגליים.","הפעילו את הליבה והורידו את החזה לכיוון הכדור בכיפוף מרפקים, תוך שמירה על גוף בקו ישר.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Extend your legs straight out behind you, balancing on your toes.","Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Положите мяч на землю и расположитесь лицом вниз, положив руки на мяч на ширине плеч.","Вытяните ноги прямо позади себя, балансируя на носках.","Напрягите корпус и опустите грудь к мячу, сгибая локти, удерживая тело на прямой линии.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Coloca el balón de estabilidad en el suelo y ponte boca abajo con las manos sobre el balón, separadas a la altura de los hombros.","Extiende las piernas rectas detrás de ti, equilibrándote sobre los dedos de los pies.","Activa el core y baja el pecho hacia el balón flexionando los codos, manteniendo el cuerpo en línea recta.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0659","name":"push-up (wall)","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","deltoids"],"target":"pectorals","image":"images/0659-LEH9jxP.jpg","gif_url":"videos/0659-LEH9jxP.gif","instruction_steps":{"he":["עמדו מול קיר, במרחק אורך יד בערך.","הניחו את הידיים על הקיר בגובה הכתפיים, מעט רחב מרוחב הכתפיים.","צעדו כמה צעדים לאחור, תוך שמירה על גוף ישר ורגליים ברוחב אגן.","כופפו מרפקים והורידו את החזה לכיוון הקיר, תוך שמירה על גוף בקו ישר.","דחפו חזרה למעלה לנקודת ההתחלה, ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing a wall, about arm's length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back a few feet, keeping your body straight and your feet hip-width apart.","Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.","Push back up to the starting position, straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к стене на расстоянии вытянутой руки.","Положите руки на стену на уровне плеч, чуть шире ширины плеч.","Отступите на несколько футов назад, держа тело прямо, а ноги на ширине плеч.","Согните руки в локтях и опустите грудь к стене, сохраняя тело прямой.","Вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a una pared, a una distancia aproximada de un brazo.","Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros.","Da un paso atrás, manteniendo el cuerpo recto y los pies separados a la altura de las caderas.","Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo en línea recta.","Empuja de vuelta a la posición inicial, estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0658","name":"push-up (wall) v. 2","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0658-NCmbLCw.jpg","gif_url":"videos/0658-NCmbLCw.gif","instruction_steps":{"he":["עמדו מול קיר, במרחק אורך יד בערך.","הניחו את הידיים על הקיר בגובה הכתפיים, מעט רחב מרוחב הכתפיים.","צעדו לאחור עם כפות הרגליים, תוך שמירה עליהן ברוחב אגן.","הפעילו את הליבה ושמרו על הגוף בקו ישר מהראש ועד העקבים.","כופפו מרפקים והורידו את החזה לכיוון הקיר, תוך שמירה על גוף ישר.","עצרו לרגע, ואז דחפו את עצמכם חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing a wall, about arm's length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back with your feet, keeping them hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the wall, keeping your body straight.","Pause for a moment, then push yourself back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к стене на расстоянии вытянутой руки.","Положите руки на стену на уровне плеч, чуть шире ширины плеч.","Отступите ногами назад, держа их на ширине плеч.","Напрягите корпус и держите тело на прямой линии от головы до пяток.","Согните локти и опустите грудь к стене, сохраняя тело прямым.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a una pared, a una distancia aproximada de un brazo.","Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros.","Retrocede con los pies, manteniéndolos separados a la altura de las caderas.","Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones.","Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo recto.","Haz una pausa por un momento y luego empújate de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0660","name":"push-up close-grip off dumbbell","category":"upper arms","body_part":"upper arms","equipment":"dumbbell","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0660-KZXAtKQ.jpg","gif_url":"videos/0660-KZXAtKQ.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים קרובות זו לזו, ישר מתחת לכתפיים.","החזיקו משקולת יד בכל יד, מונחות על הרצפה.","הורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף.","דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands placed close together, directly under your shoulders.","Hold a dumbbell in each hand, resting them on the ground.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции отжимания, поместив руки близко друг к другу, прямо под плечами.","Возьмите в каждую руку по гантели, положив их на пол.","Опустите тело к земле, согнув локти и держа их близко к бокам.","Оттолкнитесь ладонями, чтобы вытянуть руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de flexión con las manos juntas, directamente debajo de los hombros.","Sostén una mancuerna en cada mano, apoyándolas en el suelo.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0661","name":"push-up inside leg kick","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/0661-0br45wL.jpg","gif_url":"videos/0661-0br45wL.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים מעט רחבות מרוחב הכתפיים ורגליים צמודות.","הורידו את הגוף לכיוון הרצפה בכיפוף המרפקים, תוך שמירה על גב ישר והפעלת הליבה.","תוך כדי הדחיפה חזרה למעלה, הרימו רגל אחת מהרצפה ובעטו אותה הצידה, כשהיא ישרה.","הורידו את הרגל חזרה וחזרו על שכיבת הסמיכה, ואז החליפו לרגל השנייה.","המשיכו להחליף בעיטות רגליים בכל חזרת שכיבת סמיכה."],"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.","As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.","Lower your leg back down and repeat the push-up, then switch to the other leg.","Continue alternating leg kicks with each push-up repetition."],"ru":["Начните с позиции для отжиманий, поставив руки чуть шире плеч, а ноги вместе.","Опустите тело к земле, согнув локти, сохраняя спину прямой и напрягая корпус.","Отталкиваясь назад, поднимите одну ногу от земли и отведите ее в сторону, сохраняя ее прямой.","Опустите ногу обратно и повторите отжимание, затем переключитесь на другую ногу.","Продолжайте попеременные удары ногами при каждом повторении отжимания."],"es":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado.","Al empujar de vuelta hacia arriba, levanta una pierna del suelo y lánzala hacia el lado, manteniéndola recta.","Baja la pierna de nuevo y repite la flexión, luego cambia a la otra pierna.","Continúa alternando las patadas de pierna en cada repetición de la flexión."]}},{"id":"0663","name":"push-up medicine ball","category":"chest","body_part":"chest","equipment":"medicine ball","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0663-W8KAlkI.jpg","gif_url":"videos/0663-W8KAlkI.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם הידיים על כדור הכוח, ברוחב כתפיים.","הפעילו את הליבה והורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה על גב ישר.","דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, положив руки на медицинский мяч на ширине плеч.","Напрягите корпус и опустите тело к земле, сгибая локти, сохраняя спину прямой.","Оттолкнитесь ладонями, чтобы вытянуть руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros.","Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1467","name":"push-up on lower arms","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1467-4Jt8QsQ.jpg","gif_url":"videos/1467-4Jt8QsQ.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק על האמות, כשהמרפקים ישר מתחת לכתפיים.","הפעילו את הליבה ושמרו על הגוף בקו ישר מהראש ועד כפות הרגליים.","הורידו את החזה לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם קרובים לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a plank position with your forearms on the ground and elbows directly below your shoulders.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с положения планки, положив предплечья на землю и локти прямо под плечами.","Напрягите корпус и держите тело на прямой линии от головы до пят.","Опустите грудь к земле, согнув локти и удерживая их близко к телу.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de plancha con los antebrazos en el suelo y los codos directamente debajo de los hombros.","Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies.","Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3145","name":"push-up plus","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/3145-pvBMLHA.jpg","gif_url":"videos/3145-pvBMLHA.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים מעט רחבות מרוחב הכתפיים והגוף בקו ישר מהראש ועד העקבים.","הורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף.","כשהחזה מעט מעל הרצפה, דחפו דרך הידיים ליישורן והרמת פלג הגוף העליון.","בנקודה העליונה של התנועה, דחפו את השכמות קדימה בדחיפת הגב העליון לכיוון התקרה.","עצרו לרגע, ואז הפכו את התנועה בכיווץ השכמות לאחור והורדת הגוף חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.","At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.","Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с положения высокой планки, расставив руки чуть шире плеч, а тело образуя прямую линию от головы до пяток.","Опустите тело к земле, согнув локти и держа их близко к бокам.","Как только ваша грудь окажется чуть выше земли, протолкните руки, чтобы вытянуть руки и поднять верхнюю часть тела вверх.","В верхней точке движения вытяните лопатки, подталкивая верхнюю часть спины к потолку.","Сделайте паузу на мгновение, затем поменяйте направление движения, сводя лопатки и опуская тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Cuando el pecho esté justo por encima del suelo, empuja con las manos para extender los brazos y levantar la parte superior del cuerpo.","En la parte alta del movimiento, separa las escápulas empujando la parte superior de la espalda hacia el techo.","Haz una pausa por un momento y luego invierte el movimiento juntando las escápulas y bajando el cuerpo de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0664","name":"push-up to side plank","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","chest","triceps"],"target":"abs","image":"images/0664-KhHJ338.jpg","gif_url":"videos/0664-KhHJ338.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים ברוחב כתפיים והגוף בקו ישר.","הורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה על ליבה מופעלת.","דחפו חזרה למעלה לנקודת ההתחלה.","העבירו את המשקל ליד שמאל וסובבו את הגוף ימינה, בהרמת יד ימין לכיוון התקרה.","החזיקו את תנוחת הפלאנק הצדי כמה שניות, ואז חזרו לנקודת ההתחלה.","חזרו על שכיבת הסמיכה והפלאנק הצדי בצד הנגדי.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push back up to the starting position.","Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.","Hold the side plank position for a few seconds, then return to the starting position.","Repeat the push-up and side plank on the opposite side.","Continue alternating sides for the desired number of repetitions."],"ru":["Начните с позиции для отжиманий, поставив руки на ширине плеч, а тело образуя прямую линию.","Опустите тело к земле, сгибая локти, сохраняя при этом корпус напряженным.","Вернитесь в исходное положение.","Перенесите вес тела на левую руку и поверните тело вправо, подняв правую руку к потолку.","Удерживайте положение боковой планки несколько секунд, затем вернитесь в исходное положение.","Повторите отжимание и боковую планку на противоположной стороне.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta.","Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado.","Empuja hacia arriba para volver a la posición inicial.","Desplaza el peso hacia la mano izquierda y rota el cuerpo hacia la derecha, elevando el brazo derecho hacia el techo.","Mantén la posición de plancha lateral durante unos segundos y luego vuelve a la posición inicial.","Repite la flexión y la plancha lateral en el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"3533","name":"quads","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"quads","image":"images/3533-6YUfHPL.jpg","gif_url":"videos/3533-6YUfHPL.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","הורידו את הגוף בכיפוף ברכיים ודחיפת האגן לאחור כאילו אתם מתיישבים על כיסא.","שמרו על חזה מורם וגב ישר.","רדו עד שהירכיים מקבילות לרצפה.","דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Lower your body by bending your knees and pushing your hips back as if sitting on a chair.","Keep your chest up and your back straight.","Lower yourself until your thighs are parallel to the ground.","Push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Опустите тело, согнув колени и отведя бедра назад, как будто вы сидите на стуле.","Держите грудь поднятой, а спину прямой.","Опускайтесь до тех пор, пока бедра не станут параллельны земле.","Оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla.","Mantén el pecho arriba y la espalda recta.","Baja hasta que los muslos queden paralelos al suelo.","Empuja con los talones para volver a ponerte de pie en la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3201","name":"quarter sit-up","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3201-enxnJcM.jpg","gif_url":"videos/3201-enxnJcM.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3552","name":"quick feet v. 2","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"calves","secondary_muscles":["calves","hamstrings"],"target":"quads","image":"images/3552-mweqJin.jpg","gif_url":"videos/3552-mweqJin.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וידיים לצידי הגוף.","התחילו להזיז את כפות הרגליים למעלה ולמטה במהירות, כאילו אתם רצים במקום.","שמרו על תנועות מהירות וקלות, בהתמקדות בהישארות על כריות כפות הרגליים.","המשיכו למשך הזמן או מספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your arms by your sides.","Begin by rapidly moving your feet up and down, as if you were running in place.","Keep your movements quick and light, focusing on staying on the balls of your feet.","Continue for the desired duration or number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, руки по бокам.","Начните с быстрого перемещения ногами вверх и вниз, как будто вы бежите на месте.","Делайте движения быстрыми и легкими, стараясь оставаться на подушечках стоп.","Продолжайте желаемую продолжительность или количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.","Comienza moviendo los pies rápidamente hacia arriba y hacia abajo, como si estuvieras corriendo en el sitio.","Mantén los movimientos rápidos y ligeros, concentrándote en quedarte sobre la punta de los pies.","Continúa durante el tiempo o el número de repeticiones deseado."]}},{"id":"0666","name":"raise single arm push-up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0666-13TpY4H.jpg","gif_url":"videos/0666-13TpY4H.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים מעט רחבות מרוחב הכתפיים ורגליים צמודות.","מתחו יד אחת ישר הצידה, מקבילה לרצפה.","הורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה על גב ישר וליבה מופעלת.","דחפו חזרה למעלה לנקודת ההתחלה, בעזרת שרירי החזה להרמת הגוף.","חזרו על התרגיל עם היד השנייה מתוחה."],"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Extend one arm straight out to the side, parallel to the ground.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position, using your chest muscles to lift your body.","Repeat with the other arm extended."],"ru":["Начните с позиции для отжиманий, поставив руки чуть шире плеч, а ноги вместе.","Вытяните одну руку прямо в сторону, параллельно земле.","Опустите тело к земле, согнув локти, сохраняя спину прямой и напряженным корпусом.","Вернитесь в исходное положение, используя мышцы груди, чтобы поднять тело.","Повторите, вытянув другую руку."],"es":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Extiende un brazo hacia el lado, paralelo al suelo.","Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado.","Empuja de vuelta a la posición inicial, usando los músculos del pecho para elevar el cuerpo.","Repite con el otro brazo extendido."]}},{"id":"0668","name":"rear decline bridge","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0668-UpAlold.jpg","gif_url":"videos/0668-UpAlold.gif","instruction_steps":{"he":["שכבו על הגב עם כפות רגליים על הרצפה וברכיים כפופות.","הניחו את הידיים לצידי הגוף, כפות ידיים כלפי מטה.","הפעילו את הישבן והירך האחורית, והרימו את האגן מהרצפה עד שהגוף יוצר קו ישר מהברכיים ועד הכתפיים.","החזיקו את התנוחה כמה שניות, ואז הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie on your back with your feet flat on the ground and your knees bent.","Place your arms by your sides with your palms facing down.","Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Hold this position for a few seconds, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, поставьте ступни на землю и согните колени.","Положите руки по бокам ладонями вниз.","Задействуйте ягодицы и мышцы задней поверхности бедра и поднимите бедра от земли, пока ваше тело не образует прямую линию от колен до плеч.","Удерживайте это положение несколько секунд, затем медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba con los pies planos en el suelo y las rodillas flexionadas.","Coloca los brazos a los lados del cuerpo con las palmas hacia abajo.","Activa los glúteos y los isquiotibiales, y eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros.","Mantén esta posición durante unos segundos y luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0669","name":"rear deltoid stretch","category":"shoulders","body_part":"shoulders","equipment":"body weight","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0669-xifhB5W.jpg","gif_url":"videos/0669-xifhB5W.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים.","מתחו את יד ימין על פני החזה, והניחו את יד שמאל על מרפק ימין.","משכו בעדינות את יד ימין לכיוון כתף שמאל, עד תחושת מתיחה בכתף ימין.","החזיקו את המתיחה 15–30 שניות, ואז שחררו.","חזרו על התנועה בצד השני."],"en":["Stand tall with your feet shoulder-width apart.","Extend your right arm across your chest, placing your left hand on your right elbow.","Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."],"ru":["Встаньте прямо, ноги на ширине плеч.","Вытяните правую руку через грудь, положив левую руку на правый локоть.","Аккуратно потяните правую руку к левому плечу, чувствуя растяжение в правом плече.","Удерживайте растяжку 15–30 секунд, затем расслабьтесь.","Повторите с другой стороны."],"es":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende el brazo derecho a través del pecho, colocando la mano izquierda sobre el codo derecho.","Tira suavemente del brazo derecho hacia el hombro izquierdo, sintiendo un estiramiento en el hombro derecho.","Mantén el estiramiento durante 15-30 segundos, luego suelta.","Repite del otro lado."]}},{"id":"0670","name":"rear pull-up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0670-CbFSYC1.jpg","gif_url":"videos/0670-CbFSYC1.gif","instruction_steps":{"he":["אחזו במוט המתח באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היתלו על המוט עם ידיים ישרות לגמרי וגוף ישר.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון המוט, תוך שמירה על מרפקים קרובים לגוף.","המשיכו למשוך עד שהסנטר מעל המוט.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Возьмитесь за перекладину хватом сверху, на расстоянии чуть шире плеч.","Повисните на перекладине, полностью вытянув руки и выпрямив тело.","Напрягите мышцы спины и подтяните тело к перекладине, держа локти близко к телу.","Продолжайте тянуть, пока подбородок не окажется над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.","Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1582","name":"reclining big toe pose with rope","category":"upper legs","body_part":"upper legs","equipment":"rope","muscle_group":"calves","secondary_muscles":["calves","glutes"],"target":"hamstrings","image":"images/1582-K5xgdvI.jpg","gif_url":"videos/1582-K5xgdvI.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים מתוחות וידיים לצידי הגוף.","לפפו את החבל סביב כרית כף רגל ימין והחזיקו את קצוות החבל בידיים.","הרימו באיטיות את רגל ימין לכיוון החזה, תוך שמירה על ברך ישרה וכף רגל מכופפת.","החזיקו את המתיחה כמה שניות, ואז הורידו את הרגל באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה עם רגל שמאל.","המשיכו להחליף רגליים למספר החזרות הרצוי."],"en":["Lie on your back with your legs extended and your arms by your sides.","Loop the rope around the ball of your right foot and hold the ends of the rope with your hands.","Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.","Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."],"ru":["Лягте на спину, вытянув ноги и положив руки по бокам.","Оберните веревку вокруг подушечки правой ноги и держите концы веревки руками.","Медленно поднимите правую ногу к груди, сохраняя колено прямым, а ступню согнутой.","Удерживайте растяжку несколько секунд, затем медленно опустите ногу обратно в исходное положение.","Повторите с левой ногой.","Продолжайте чередовать ноги желаемое количество повторений."],"es":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Enrolla la cuerda alrededor de la planta del pie derecho y sujeta los extremos de la cuerda con las manos.","Eleva lentamente la pierna derecha hacia el pecho, manteniendo la rodilla recta y el pie flexionado.","Mantén el estiramiento durante unos segundos y luego baja lentamente la pierna de vuelta a la posición inicial.","Repite con la pierna izquierda.","Continúa alternando las piernas durante el número de repeticiones deseado."]}},{"id":"3236","name":"resistance band hip thrusts on knees (female)","category":"upper legs","body_part":"upper legs","equipment":"resistance band","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/3236-Pjbc0Kt.jpg","gif_url":"videos/3236-Pjbc0Kt.gif","instruction_steps":{"he":["התחילו בכריעה על הרצפה עם ברכיים ברוחב אגן וכפות רגליים מכופפות.","לפפו את גומיית ההתנגדות סביב הירכיים, מעט מעל הברכיים.","הניחו את הידיים על המותניים או מתחו אותן לפניכם לשיווי משקל.","הפעילו את שרירי הישבן והליבה.","דחפו את האגן קדימה וכווצו את הישבן תוך הרמת הברכיים מהרצפה, ביישור הירכיים עד שהירכיים מקבילות לרצפה.","החזיקו את התנוחה לרגע, ואז הורידו את הברכיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by kneeling on the ground with your knees hip-width apart and your feet flexed.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on your hips or extend them out in front of you for balance.","Engage your glutes and core muscles.","Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground.","Hold the position for a moment, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте на колени на землю, расставив колени на ширине плеч и согнув ступни.","Оберните ленту сопротивления вокруг бедер, чуть выше колен.","Положите руки на бедра или вытяните их перед собой для равновесия.","Задействуйте ягодицы и мышцы корпуса.","Выдвиньте бедра вперед и сожмите ягодицы, отрывая колени от земли, вытягивая бедра до тех пор, пока бедра не станут параллельны земле.","Задержитесь в этом положении на мгновение, затем медленно опустите колени обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas y los pies flexionados.","Envuelve la banda elástica alrededor de los muslos, justo por encima de las rodillas.","Coloca las manos en las caderas o extiéndelas frente a ti para mantener el equilibrio.","Activa los glúteos y los músculos del core.","Empuja las caderas hacia adelante y aprieta los glúteos mientras levantas las rodillas del suelo, extendiendo las caderas hasta que los muslos queden paralelos al suelo.","Mantén la posición por un momento y luego baja lentamente las rodillas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3007","name":"resistance band leg extension","category":"upper legs","body_part":"upper legs","equipment":"resistance band","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"quads","image":"images/3007-Y1MsI1l.jpg","gif_url":"videos/3007-Y1MsI1l.gif","instruction_steps":{"he":["עגנו את גומיית ההתנגדות לנקודת עיגון יציבה וקבעו אותה סביב הקרסול.","עמדו מול נקודת העיגון עם רגליים ברוחב כתפיים.","תוך שמירה על ליבה מופעלת ופלג גוף עליון יציב, מתחו את הרגל ישר לפניכם.","עצרו לרגע בנקודה העליונה, ואז החזירו באיטיות את הרגל לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Attach the resistance band to a sturdy anchor point and secure it around your ankle.","Stand facing the anchor point with your feet shoulder-width apart.","Keeping your core engaged and your upper body stable, extend your leg straight out in front of you.","Pause for a moment at the top, then slowly return your leg to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Прикрепите эспандер к прочной точке крепления и закрепите его вокруг лодыжки.","Встаньте лицом к точке крепления, поставив ноги на ширине плеч.","Сохраняя корпус напряженным, а верхнюю часть тела стабильной, вытяните ногу прямо перед собой.","Задержитесь на мгновение в верхней точке, затем медленно верните ногу в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Sujeta la banda elástica a un punto de anclaje firme y asegúrala alrededor de tu tobillo.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Manteniendo el core activado y la parte superior del cuerpo estable, extiende la pierna recta frente a ti.","Haz una pausa por un momento en la parte alta y luego vuelve lentamente la pierna a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"3123","name":"resistance band seated biceps curl","category":"upper arms","body_part":"upper arms","equipment":"resistance band","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/3123-XFc3vpY.jpg","gif_url":"videos/3123-XFc3vpY.gif","instruction_steps":{"he":["שבו על כיסא או ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו את הגומייה באחיזה תחתונה, כפות ידיים כלפי מעלה, וידיים מתוחות לצידי הגוף.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את הגומייה למעלה לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את הגומייה באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.","Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the resistance band back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на стул или скамью, выпрямив спину и поставив ступни на землю.","Держите эспандер обратным хватом ладонями вверх и вытянутыми вниз руками по бокам.","Удерживая плечи неподвижно, выдохните и согните ленту сопротивления к плечам.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите ленту сопротивления обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.","Sostén la banda elástica con un agarre supino, con las palmas hacia arriba y los brazos extendidos a los lados del cuerpo.","Manteniendo la parte superior de los brazos inmóvil, exhala y flexiona la banda elástica hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la banda elástica de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3124","name":"resistance band seated chest press","category":"chest","body_part":"chest","equipment":"resistance band","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/3124-4x5Okof.jpg","gif_url":"videos/3124-4x5Okof.gif","instruction_steps":{"he":["שבו על כיסא או ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו את ידיות הגומייה בכל יד, כפות ידיים כלפי מטה ומרפקים כפופים בזווית של 90 מעלות.","מתחו את הידיים קדימה, בדחיפת גומיית ההתנגדות הרחק מהחזה.","עצרו לרגע בסוף התנועה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.","Extend your arms forward, pushing the resistance band away from your chest.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на стул или скамью, выпрямив спину и поставив ступни на землю.","Возьмите ручки эспандеров в каждую руку ладонями вниз и согнутыми в локтях под углом 90 градусов.","Вытяните руки вперед, отталкивая ленту сопротивления от груди.","Сделайте небольшую паузу в конце движения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.","Sostén las asas de la banda elástica en cada mano, con las palmas hacia abajo y los codos flexionados en un ángulo de 90 grados.","Extiende los brazos hacia adelante, alejando la banda elástica de tu pecho.","Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3006","name":"resistance band seated hip abduction","category":"upper legs","body_part":"upper legs","equipment":"resistance band","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"abductors","image":"images/3006-0xDpB4L.jpg","gif_url":"videos/3006-0xDpB4L.gif","instruction_steps":{"he":["שבו על כיסא או ספסל עם גב ישר וכפות רגליים על הרצפה.","לפפו את גומיית ההתנגדות סביב הירכיים, מעט מעל הברכיים.","הניחו את הידיים על צידי הכיסא או הספסל לתמיכה.","הפעילו את מרחיקי הירך (שרירי הירך החיצוניים) ודחפו באיטיות את הברכיים זו מזו, כנגד התנגדות הגומייה.","עצרו לרגע בסוף התנועה, ואז החזירו באיטיות את הברכיים יחד.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a chair or bench with your back straight and feet flat on the ground.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on the sides of the chair or bench for support.","Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band.","Pause for a moment at the end of the movement, then slowly bring your knees back together.","Repeat for the desired number of repetitions."],"ru":["Сядьте на стул или скамью, выпрямив спину и поставив ступни на землю.","Оберните ленту сопротивления вокруг бедер, чуть выше колен.","Положите руки по бокам стула или скамьи для поддержки.","Задействуйте отводящие мышцы (внешние мышцы бедра) и медленно разведите колени в стороны, преодолевая сопротивление ленты.","Сделайте паузу на мгновение в конце движения, затем медленно сведите колени вместе.","Повторите необходимое количество повторений."],"es":["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.","Envuelve la banda elástica alrededor de los muslos, justo por encima de las rodillas.","Coloca las manos en los lados de la silla o el banco para mayor apoyo.","Activa los abductores (los músculos externos del muslo) y empuja lentamente las rodillas hacia afuera, contra la resistencia de la banda.","Haz una pausa al final del movimiento y luego junta lentamente las rodillas de nuevo.","Repite el número de repeticiones deseado."]}},{"id":"3122","name":"resistance band seated shoulder press","category":"shoulders","body_part":"shoulders","equipment":"resistance band","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/3122-S93zLTG.jpg","gif_url":"videos/3122-S93zLTG.gif","instruction_steps":{"he":["שבו על כיסא או ספסל עם גב ישר וכפות רגליים על הרצפה.","החזיקו את הגומייה בשתי ידיים, כפות ידיים פונות קדימה, והביאו אותה לגובה הכתפיים.","לחצו את הגומייה מעל הראש, עד יישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגומייה באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.","Press the band overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the band back down to shoulder level.","Repeat for the desired number of repetitions."],"ru":["Сядьте на стул или скамью, выпрямив спину и поставив ступни на землю.","Возьмите эспандер обеими руками ладонями вперед и поднимите его до уровня плеч.","Нажмите на ленту над головой, полностью вытянув руки.","Задержитесь на мгновение в верхней точке, затем медленно опустите ленту обратно до уровня плеч.","Повторите необходимое количество повторений."],"es":["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.","Sostén la banda elástica con ambas manos, con las palmas hacia adelante, y elévala hasta la altura de los hombros.","Empuja la banda por encima de la cabeza, extendiendo completamente los brazos.","Haz una pausa por un momento en la parte alta y luego baja lentamente la banda hasta la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"3144","name":"resistance band seated straight back row","category":"back","body_part":"back","equipment":"resistance band","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/3144-Nu7jqFE.jpg","gif_url":"videos/3144-Nu7jqFE.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים מתוחות ולפפו את גומיית ההתנגדות סביב כפות הרגליים.","החזיקו את קצוות גומיית ההתנגדות בידיים, כפות ידיים פונות זו לזו.","שמרו על גב ישר והיטו מעט לאחור, תוך הפעלת הליבה.","משכו את גומיית ההתנגדות לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז שחררו באיטיות את המתח וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the floor with your legs extended and loop the resistance band around your feet.","Hold the ends of the resistance band with your hands, palms facing each other.","Keep your back straight and lean slightly back, engaging your core.","Pull the resistance band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на пол, вытянув ноги, и оберните ленту сопротивления вокруг ступней.","Возьмите концы эспандера руками, ладонями друг к другу.","Держите спину прямо и слегка откиньтесь назад, задействуя корпус.","Потяните ленту сопротивления к груди, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el suelo con las piernas extendidas y enrolla la banda elástica alrededor de los pies.","Sostén los extremos de la banda elástica con las manos, con las palmas enfrentadas.","Mantén la espalda recta e inclínate ligeramente hacia atrás, activando el core.","Tira de la banda elástica hacia el pecho, juntando las escápulas.","Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0872","name":"reverse crunch","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0872-nCU1Ekp.jpg","gif_url":"videos/0872-nCU1Ekp.gif","instruction_steps":{"he":["שכבו על הגב עם ידיים מתוחות לצידי הגוף.","כופפו ברכיים והרימו את כפות הרגליים מהרצפה, בהבאת הירכיים לתנוחה ניצבת לרצפה.","כווצו את שרירי הבטן וגלגלו את האגן מהרצפה, בהבאת הברכיים לכיוון החזה.","עצרו לרגע בנקודה העליונה, ואז הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your arms extended along your sides.","Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.","Contract your abs and curl your hips off the floor, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, вытянув руки по бокам.","Согните ноги в коленях и оторвите ступни от земли, приведя бедра перпендикулярно полу.","Напрягите пресс и оторвите бедра от пола, подтягивая колени к груди.","Задержитесь на мгновение в верхней точке, затем медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba con los brazos extendidos a los lados del cuerpo.","Flexiona las rodillas y levanta los pies del suelo, llevando los muslos perpendiculares al suelo.","Contrae el abdomen y eleva las caderas del suelo, llevando las rodillas hacia el pecho.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0672","name":"reverse dip","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0672-NZ5Qqkz.jpg","gif_url":"videos/0672-NZ5Qqkz.gif","instruction_steps":{"he":["התמקמו בין שני מקבילים עם ידיים ישרות לגמרי וגוף ישר.","הורידו את הגוף בכיפוף מרפקים עד שהזרועות העליונות מקבילות לרצפה.","עצרו לרגע, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Position yourself between two parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Встаньте между двумя параллельными брусьями, полностью выпрямив руки и выпрямив тело.","Опустите тело, сгибая локти, пока плечи не станут параллельны земле.","Сделайте паузу на мгновение, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo recto.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0673","name":"reverse grip machine lat pulldown","category":"back","body_part":"back","equipment":"leverage machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0673-ecpY0rH.jpg","gif_url":"videos/0673-ecpY0rH.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהברכיים מתחת לכריות וכפות הרגליים על הרצפה.","אחזו בידיות באחיזה תחתונה, מעט רחבה מרוחב הכתפיים.","שבו זקוף עם חזה מורם וכתפיים לאחור, תוך שמירה על קשת קלה בגב התחתון.","משכו את הידיות מטה לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, ואז שחררו באיטיות את הידיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Pull the handles down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на машине так, чтобы колени находились под подушками, а ступни стояли на земле.","Возьмитесь за ручки хватом снизу, на расстоянии чуть шире ширины плеч.","Сядьте прямо, вытянув грудь и отведя плечи назад, сохраняя небольшой изгиб в пояснице.","Потяните ручки вниз к груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно отпустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo.","Sujeta las asas con un agarre supino, un poco más separadas que la altura de los hombros.","Siéntate erguido con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar.","Tira de las asas hacia el pecho, juntando las escápulas.","Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0674","name":"reverse grip pull-up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0674-YAk5dIw.jpg","gif_url":"videos/0674-YAk5dIw.gif","instruction_steps":{"he":["אחזו במוט המתח באחיזה תחתונה, ידיים ברוחב כתפיים.","היתלו על המוט עם ידיים ישרות לגמרי וגוף ישר.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון המוט, כשהחזה מוביל את התנועה.","המשיכו למשוך עד שהסנטר מעל המוט.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Grab the pull-up bar with an underhand grip, hands shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Возьмитесь за перекладину хватом снизу, руки на ширине плеч.","Повисните на перекладине, полностью вытянув руки и выпрямив тело.","Задействуйте мышцы спины и подтяните тело к перекладине, ведя грудью.","Продолжайте тянуть, пока подбородок не окажется над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Agarra la barra de dominadas con un agarre supino, con las manos separadas a la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.","Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0675","name":"reverse hyper extension (on stability ball)","category":"upper legs","body_part":"upper legs","equipment":"stability ball","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0675-vM5YS2g.jpg","gif_url":"videos/0675-vM5YS2g.gif","instruction_steps":{"he":["שכבו על הבטן על כדור פיזיו כשהאגן נשען על הכדור והרגליים מתוחות ישר לאחור.","הניחו את הידיים על הרצפה לפניכם לייצוב.","תוך הפעלת הישבן והירך האחורית, הרימו את הרגליים למעלה לכיוון התקרה גבוה ככל האפשר.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for stability.","Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте лицом вниз на мяч для стабилизации, положив бедра на мяч и вытянув ноги прямо позади себя.","Положите руки на землю перед собой для устойчивости.","Задействуя ягодицы и мышцы задней поверхности бедра, поднимите ноги к потолку как можно выше.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo sobre un balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti.","Coloca las manos en el suelo frente a ti para mayor estabilidad.","Activando los glúteos y los isquiotibiales, eleva las piernas hacia el techo tan alto como puedas.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1423","name":"reverse hyper on flat bench","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1423-OrETs32.jpg","gif_url":"videos/1423-OrETs32.gif","instruction_steps":{"he":["שכבו על הבטן על ספסל ישר כשהאגן בקצה והרגליים משתלשלות מהספסל.","אחזו בספסל לייצוב.","תוך שמירה על רגליים ישרות, הרימו אותן למעלה לכיוון התקרה גבוה ככל האפשר.","כווצו את הישבן בנקודה העליונה של התנועה.","הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.","Hold onto the bench for stability.","Keeping your legs straight, raise them up towards the ceiling as high as you can.","Squeeze your glutes at the top of the movement.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте лицом вниз на плоскую скамью, прижав бедра к краю и свесив ноги со скамьи.","Держитесь за скамью для устойчивости.","Держа ноги прямыми, поднимите их к потолку как можно выше.","Напрягите ягодицы в верхней точке движения.","Медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo en un banco plano con las caderas en el borde y las piernas colgando del banco.","Sujétate del banco para mantener la estabilidad.","Manteniendo las piernas rectas, elévalas hacia el techo tan alto como puedas.","Aprieta los glúteos en la parte alta del movimiento.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3663","name":"reverse plank with leg lift","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","shoulders"],"target":"abs","image":"images/3663-tFToB7l.jpg","gif_url":"videos/3663-tFToB7l.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים מתוחות לפניכם והידיים מונחות על הרצפה מאחוריכם, אצבעות פונות לכיוון כפות הרגליים.","דחפו דרך הידיים והרימו את האגן מהרצפה, לתנוחת פלאנק הפוך.","הפעילו את הליבה והרימו רגל אחת מהרצפה, במתיחתה ישר לכיוון התקרה.","החזיקו לרגע, ואז הורידו את הרגל חזרה מטה.","חזרו על התנועה עם הרגל השנייה.","המשיכו להחליף רגליים למספר החזרות הרצוי."],"en":["Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.","Press through your hands and lift your hips off the ground, coming into a reverse plank position.","Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.","Hold for a moment, then lower your leg back down.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."],"ru":["Сядьте на землю, вытянув ноги перед собой, а руки положите на землю позади себя, пальцы направлены к ногам.","Нажмите руками и поднимите бедра от земли, приняв положение обратной планки.","Напрягите корпус и поднимите одну ногу от земли, вытягивая ее прямо к потолку.","Задержитесь на мгновение, затем опустите ногу обратно вниз.","Повторите с другой ногой.","Продолжайте чередовать ноги желаемое количество повторений."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti y las manos apoyadas en el suelo detrás de ti, con los dedos apuntando hacia los pies.","Presiona con las manos y levanta las caderas del suelo, llegando a una posición de plancha inversa.","Activa el core y levanta una pierna del suelo, extendiéndola recta hacia el techo.","Mantén la posición por un momento y luego baja la pierna de nuevo.","Repite con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."]}},{"id":"0677","name":"ring dips","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0677-ezTvXcr.jpg","gif_url":"videos/0677-ezTvXcr.gif","instruction_steps":{"he":["התחילו בתלייה על הטבעות עם ידיים ישרות לגמרי וגוף ישר.","הורידו את הגוף בכיפוף מרפקים עד שהכתפיים מתחת למרפקים.","דחפו את עצמכם חזרה למעלה לנקודת ההתחלה על ידי יישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by hanging from the rings with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Начните с висения на кольцах, полностью вытянув руки и выпрямив тело.","Опускайте корпус, сгибая локти, пока плечи не окажутся ниже локтей.","Вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Comienza colgándote de las anillas con los brazos completamente extendidos y el cuerpo recto.","Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos.","Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"2571","name":"rocking frog stretch","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/2571-2Dk4xQV.jpg","gif_url":"videos/2571-2Dk4xQV.gif","instruction_steps":{"he":["התחילו בכריעה על הרצפה עם ברכיים ברוחב אגן.","הניחו את הידיים על הרצפה לפניכם לתמיכה.","רכנו באיטיות קדימה, בהעברת המשקל לידיים ומתיחת הרגליים לאחור.","שמרו על גב ישר והפעילו את הישבן תוך דחיפת האגן לאחור ולמעלה לכיוון התקרה.","החזיקו את התנוחה כמה שניות, בתחושת מתיחה בישבן.","חזרו באיטיות לנקודת ההתחלה בכיפוף ברכיים והורדת האגן חזרה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by kneeling on the ground with your knees hip-width apart.","Place your hands on the ground in front of you for support.","Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.","Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.","Hold this position for a few seconds, feeling a stretch in your glutes.","Slowly return to the starting position by bending your knees and lowering your hips back down.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте на колени на землю, расставив колени на ширине плеч.","Положите руки на землю перед собой для поддержки.","Медленно наклонитесь вперед, перенеся вес тела на руки и вытянув ноги позади себя.","Держите спину прямо и задействуйте ягодицы, толкая бедра назад и вверх к потолку.","Удерживайте это положение несколько секунд, чувствуя растяжение ягодиц.","Медленно вернитесь в исходное положение, согнув колени и опустив бедра обратно вниз.","Повторите необходимое количество повторений."],"es":["Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas.","Coloca las manos en el suelo frente a ti para mayor apoyo.","Inclínate lentamente hacia adelante, desplazando el peso hacia las manos y extendiendo las piernas detrás de ti.","Mantén la espalda recta y activa los glúteos mientras empujas las caderas hacia atrás y hacia arriba en dirección al techo.","Mantén esta posición durante unos segundos, sintiendo un estiramiento en los glúteos.","Vuelve lentamente a la posición inicial flexionando las rodillas y bajando las caderas de nuevo.","Repite el número de repeticiones deseado."]}},{"id":"0678","name":"rocky pull-up pulldown","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0678-cQ19bBP.jpg","gif_url":"videos/0678-cQ19bBP.gif","instruction_steps":{"he":["עמדו מול מוט מתח עם רגליים ברוחב כתפיים.","הושיטו ידיים למעלה ואחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היתלו על המוט עם ידיים ישרות לגמרי וגוף ישר.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון המוט, כשהחזה מוביל את התנועה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand in front of a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте перед перекладиной, ноги на ширине плеч.","Потянитесь вверх и возьмите перекладину хватом сверху, на расстоянии чуть шире ширины плеч.","Повисните на перекладине, полностью вытянув руки и выпрямив тело.","Задействуйте мышцы спины и подтяните тело к перекладине, ведя грудью.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros.","Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.","Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2208","name":"roller back stretch","category":"back","body_part":"back","equipment":"roller","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"spine","image":"images/2208-isofgzg.jpg","gif_url":"videos/2208-isofgzg.gif","instruction_steps":{"he":["התחילו בישיבה על הרצפה עם רגליים מתוחות לפניכם.","הניחו את הרולר ניצב לגוף, מעט מתחת לישבן.","התגלגלו באיטיות לאחור, ותנו לרולר לנוע במעלה הגב.","המשיכו להתגלגל עד שהרולר מגיע לגב העליון.","עצרו לרגע, ואז התגלגלו באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by sitting on the ground with your legs extended in front of you.","Place the roller perpendicular to your body, just below your glutes.","Slowly roll your body backwards, allowing the roller to move up your back.","Continue rolling until the roller reaches your upper back.","Pause for a moment, then slowly roll back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что сядьте на землю, вытянув ноги перед собой.","Поместите валик перпендикулярно телу, чуть ниже ягодиц.","Медленно перекатите тело назад, позволяя ролику двигаться вверх по спине.","Продолжайте кататься, пока ролик не достигнет верхней части спины.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza sentándote en el suelo con las piernas extendidas frente a ti.","Coloca el rodillo perpendicular a tu cuerpo, justo debajo de los glúteos.","Rueda lentamente el cuerpo hacia atrás, dejando que el rodillo se desplace hacia arriba por tu espalda.","Continúa rodando hasta que el rodillo llegue a la parte superior de tu espalda.","Haz una pausa por un momento y luego rueda lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2204","name":"roller body saw","category":"waist","body_part":"waist","equipment":"roller","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","core"],"target":"abs","image":"images/2204-XeMvLgE.jpg","gif_url":"videos/2204-XeMvLgE.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק עם האמות על הרולר והגוף בקו ישר.","הפעילו את הליבה וגלגלו באיטיות את הרולר קדימה, במתיחת הגוף רחוק ככל האפשר תוך שמירה על שליטה.","עצרו לרגע בנקודה הרחוקה ביותר, ואז גלגלו באיטיות את הרולר חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a plank position with your forearms on the roller and your body in a straight line.","Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с положения планки, положив предплечья на валик, а тело образуя прямую линию.","Включите корпус и медленно катите ролик вперед, вытягивая тело как можно дальше, сохраняя при этом контроль.","Сделайте паузу на мгновение в самой дальней точке, затем медленно катите ролик обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de plancha con los antebrazos sobre el rodillo y el cuerpo en línea recta.","Activa el core y rueda lentamente el rodillo hacia adelante, extendiendo el cuerpo tanto como puedas mientras mantienes el control.","Haz una pausa por un momento en el punto más lejano y luego rueda lentamente el rodillo de vuelta hacia tu posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2205","name":"roller hip lat stretch","category":"upper legs","body_part":"upper legs","equipment":"roller","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/2205-0L2KwtI.jpg","gif_url":"videos/2205-0L2KwtI.gif","instruction_steps":{"he":["התחילו בכריעה על הרצפה עם הרולר ממוקם מתחת לירכיים.","הניחו את הידיים על הרולר לתמיכה.","גלגלו באיטיות את הרולר קדימה, ביישור הירכיים ומתיחת הישבן.","החזיקו את המתיחה כמה שניות, ואז התגלגלו חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by kneeling on the ground with the roller positioned under your hips.","Place your hands on the roller for support.","Slowly roll the roller forward, extending your hips and stretching your glutes.","Hold the stretch for a few seconds, then roll back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встанете на колени на землю, расположив валик под бедрами.","Положите руки на валик для поддержки.","Медленно катите ролик вперед, вытягивая бедра и растягивая ягодицы.","Удерживайте растяжку несколько секунд, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza arrodillándote en el suelo con el rodillo colocado debajo de las caderas.","Coloca las manos sobre el rodillo para mayor apoyo.","Rueda lentamente el rodillo hacia adelante, extendiendo las caderas y estirando los glúteos.","Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2202","name":"roller hip stretch","category":"upper legs","body_part":"upper legs","equipment":"roller","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/2202-oMypNrz.jpg","gif_url":"videos/2202-oMypNrz.gif","instruction_steps":{"he":["התחילו בישיבה על הרצפה עם רגליים מתוחות לפניכם.","הניחו את הרולר מתחת לישבן, מעט מעל הברכיים.","היטו לאחור והניחו את הידיים על הרצפה מאחוריכם לתמיכה.","הפעילו את הישבן וגלגלו באיטיות את הרולר קדימה, בכיפוף הברכיים והבאתן לכיוון החזה.","עצרו לרגע בסוף התנועה, בהרגשת המתיחה בישבן.","גלגלו באיטיות את הרולר חזרה לנקודת ההתחלה, במתיחת הרגליים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by sitting on the ground with your legs extended in front of you.","Place the roller under your glutes, just above your knees.","Lean back and place your hands on the ground behind you for support.","Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.","Pause for a moment at the end of the movement, feeling a stretch in your glutes.","Slowly roll the roller back to the starting position, extending your legs.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что сядьте на землю, вытянув ноги перед собой.","Поместите валик под ягодицы, чуть выше колен.","Откиньтесь назад и положите руки на пол позади себя для поддержки.","Напрягите ягодицы и медленно катите ролик вперед, сгибая колени и приближая их к груди.","Сделайте паузу в конце движения, почувствовав растяжение ягодиц.","Медленно перекатите ролик обратно в исходное положение, вытягивая ноги.","Повторите необходимое количество повторений."],"es":["Comienza sentándote en el suelo con las piernas extendidas frente a ti.","Coloca el rodillo debajo de los glúteos, justo por encima de las rodillas.","Inclínate hacia atrás y coloca las manos en el suelo detrás de ti para apoyarte.","Activa los glúteos y rueda lentamente el rodillo hacia adelante, flexionando las rodillas y llevándolas hacia el pecho.","Haz una pausa al final del movimiento, sintiendo un estiramiento en los glúteos.","Rueda lentamente el rodillo de vuelta a la posición inicial, extendiendo las piernas.","Repite el número de repeticiones deseado."]}},{"id":"2206","name":"roller reverse crunch","category":"waist","body_part":"waist","equipment":"roller","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/2206-SKXQAx3.jpg","gif_url":"videos/2206-SKXQAx3.gif","instruction_steps":{"he":["שכבו על הגב עם ידיים מתוחות ישר מעל הראש ורגליים ישרות לפניכם.","הניחו את הרולר בין כפות הרגליים ואחזו בו עם קצות האצבעות.","תוך הפעלת שרירי הבטן, הרימו את הרגליים מהרצפה וגלגלו את הברכיים לכיוון החזה, בגלגול הרולר לכיוון הגוף.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה, בגלגול הרולר הרחק מהגוף.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.","Place the roller between your feet and grip it with your toes.","Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.","Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, вытяните руки прямо над головой и вытяните ноги прямо перед собой.","Поместите валик между стопами и возьмитесь за него пальцами ног.","Включив пресс, поднимите ноги от земли и подтяните колени к груди, перекатывая валик по направлению к телу.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение, откатывая валик от тела.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba con los brazos extendidos rectos por encima de la cabeza y las piernas rectas frente a ti.","Coloca el rodillo entre los pies y sujétalo con los dedos de los pies.","Activando el abdomen, levanta las piernas del suelo y flexiona las rodillas hacia el pecho, rodando el rodillo hacia tu cuerpo.","Haz una pausa por un momento en la parte alta y luego baja lentamente las piernas de vuelta a la posición inicial, rodando el rodillo alejándolo de tu cuerpo.","Repite el número de repeticiones deseado."]}},{"id":"2203","name":"roller seated shoulder flexor depresor retractor","category":"chest","body_part":"chest","equipment":"roller","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/2203-8coXSYU.jpg","gif_url":"videos/2203-8coXSYU.gif","instruction_steps":{"he":["שבו על משטח ישר עם רגליים מתוחות לפניכם.","החזיקו את הרולר בשתי ידיים, כפות ידיים כלפי מטה, והניחו אותו על הירכיים.","רכנו מעט קדימה וגלגלו את הרולר הרחק מהגוף, במתיחת הידיים ישר לפניכם.","עצרו לרגע, ואז גלגלו באיטיות את הרולר חזרה לכיוון הגוף, בכיפוף הידיים והחזרתו לירכיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.","Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.","Repeat for the desired number of repetitions."],"ru":["Сядьте на ровную поверхность, вытянув ноги перед собой.","Возьмите валик обеими руками ладонями вниз и положите его на бедра.","Слегка наклонитесь вперед и откатите валик от тела, вытянув руки прямо перед собой.","Сделайте паузу на мгновение, затем медленно перекатите валик обратно к телу, сгибая руки и возвращая валик обратно к бедрам.","Повторите необходимое количество повторений."],"es":["Siéntate sobre una superficie plana con las piernas extendidas frente a ti.","Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos.","Inclínate ligeramente hacia delante y aleja el rodillo de tu cuerpo, extendiendo los brazos rectos frente a ti.","Haz una pausa por un momento, luego rueda el rodillo lentamente de vuelta hacia tu cuerpo, doblando los brazos y trayéndolo de nuevo hacia los muslos.","Repite el número de repeticiones deseado."]}},{"id":"2209","name":"roller seated single leg shoulder flexor depresor retractor","category":"chest","body_part":"chest","equipment":"roller","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/2209-CjETvlw.jpg","gif_url":"videos/2209-CjETvlw.gif","instruction_steps":{"he":["שבו על משטח ישר עם רגליים מתוחות לפניכם.","החזיקו את הרולר בשתי ידיים, כפות ידיים כלפי מטה, והניחו אותו על הירכיים.","היטו את הגוף מעט לאחור והפעילו את שרירי הליבה.","הרימו את הרולר לגובה הכתפיים, תוך שמירה על ידיים ישרות.","הורידו באיטיות את הרולר חזרה לירכיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean back slightly and engage your core muscles.","Raise the roller up to shoulder level, keeping your arms straight.","Slowly lower the roller back down to your thighs.","Repeat for the desired number of repetitions."],"ru":["Сядьте на ровную поверхность, вытянув ноги перед собой.","Возьмите валик обеими руками ладонями вниз и положите его на бедра.","Слегка откиньтесь назад и задействуйте мышцы корпуса.","Поднимите валик до уровня плеч, держа руки прямыми.","Медленно опустите валик обратно на бедра.","Повторите необходимое количество повторений."],"es":["Siéntate sobre una superficie plana con las piernas extendidas frente a ti.","Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos.","Inclínate ligeramente hacia atrás y contrae los músculos del core.","Eleva el rodillo hasta la altura de los hombros, manteniendo los brazos rectos.","Baja lentamente el rodillo de nuevo hacia los muslos.","Repite el número de repeticiones deseado."]}},{"id":"2207","name":"roller side lat stretch","category":"back","body_part":"back","equipment":"roller","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"lats","image":"images/2207-c3Pfhti.jpg","gif_url":"videos/2207-c3Pfhti.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את הרולר בשתי ידיים מול הגוף.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","מתחו את הידיים קדימה וגלגלו את הרולר מטה לכיוון כפות הרגליים, עד תחושת מתיחה ברחב הגבי.","החזיקו את המתיחה כמה שניות, ואז גלגלו באיטיות את הרולר חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.","Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите валик обеими руками перед собой.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Вытяните руки вперед и катите валик к ногам, чувствуя растяжение широчайших мышц.","Удерживайте растяжку несколько секунд, затем медленно перекатите ролик обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta el rodillo con ambas manos frente al cuerpo.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Extiende los brazos hacia delante y rueda el rodillo hacia los pies, sintiendo un estiramiento en los dorsales.","Mantén el estiramiento durante unos segundos, luego rueda el rodillo lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0680","name":"rope climb","category":"back","body_part":"back","equipment":"rope","muscle_group":"forearms","secondary_muscles":["forearms","biceps","shoulders"],"target":"upper back","image":"images/0680-yaAxcQr.jpg","gif_url":"videos/0680-yaAxcQr.gif","instruction_steps":{"he":["עמדו מול החבל עם רגליים ברוחב כתפיים.","אחזו בחבל בשתי ידיים, כפות ידיים פונות אליכם.","כופפו ברכיים מעט והפעילו את הליבה.","התחילו לטפס על החבל בתנועות יד-אחר-יד לסירוגין.","היעזרו ברגליים לסיוע בתנועה כלפי מעלה.","המשיכו לטפס עד לגובה הרצוי או לראש החבל.","לירידה, הפכו את תנועת היד-אחר-יד תוך שליטה בירידה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing the rope with your feet shoulder-width apart.","Grab the rope with both hands, palms facing towards you.","Bend your knees slightly and engage your core.","Begin pulling yourself up the rope by alternating hand-over-hand movements.","Use your legs to assist in the upward movement.","Continue climbing until you reach the desired height or the top of the rope.","To descend, reverse the hand-over-hand movement while controlling your descent.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к веревке, поставив ноги на ширине плеч.","Возьмите веревку обеими руками, ладонями к себе.","Слегка согните колени и задействуйте корпус.","Начните подтягиваться вверх по веревке, попеременно двигая руками.","Используйте ноги, чтобы помочь в движении вверх.","Продолжайте подниматься, пока не достигнете желаемой высоты или вершины веревки.","Чтобы опуститься, поменяйте направление движения руками, контролируя при этом спуск.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a la cuerda con los pies separados a la altura de los hombros.","Sujeta la cuerda con ambas manos, con las palmas mirando hacia ti.","Flexiona ligeramente las rodillas y activa el core.","Comienza a subir por la cuerda alternando los movimientos de las manos.","Usa las piernas para ayudar en el movimiento ascendente.","Continúa trepando hasta alcanzar la altura deseada o la parte superior de la cuerda.","Para descender, invierte el movimiento alterno de las manos mientras controlas tu descenso.","Repite el número de repeticiones deseado."]}},{"id":"0685","name":"run","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/0685-oLrKqDH.jpg","gif_url":"videos/0685-oLrKqDH.gif","instruction_steps":{"he":["התחילו בעמידה זקופה עם רגליים ברוחב אגן.","הפעילו את הליבה ושמרו על פלג גוף עליון רפוי.","התחילו לרוץ במקום, בהרמת הברכיים לכיוון החזה ונחיתה רכה על כריות כפות הרגליים.","שמרו על קצב אחיד והמשיכו לרוץ קלות למשך הזמן או המרחק הרצוי.","זכרו לנשום עמוק ולשמור על יציבה טובה לאורך כל התרגיל."],"en":["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."],"ru":["Начните с того, что встаньте прямо, ноги на ширине плеч.","Задействуйте корпус и держите верхнюю часть тела расслабленной.","Начните бег на месте, подтягивая колени к груди и мягко приземляясь на подушечки стоп.","Поддерживайте устойчивый темп и продолжайте бег трусцой желаемую продолжительность или расстояние.","Не забывайте глубоко дышать и сохранять правильную осанку на протяжении всего упражнения."],"es":["Comienza de pie con los pies separados a la altura de la cadera.","Activa el core y mantén la parte superior del cuerpo relajada.","Comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies.","Mantén un ritmo constante y continúa trotando durante la duración o distancia deseada.","Recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio."]}},{"id":"0684","name":"run (equipment)","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/0684-y5p0H8a.jpg","gif_url":"videos/0684-y5p0H8a.gif","instruction_steps":{"he":["התחילו בעמידה זקופה עם רגליים ברוחב אגן.","הפעילו את הליבה ושמרו על פלג גוף עליון רפוי.","התחילו לרוץ במקום, בהרמת הברכיים לכיוון החזה ונחיתה רכה על כריות כפות הרגליים.","שמרו על קצב אחיד והמשיכו לרוץ קלות למשך הזמן או המרחק הרצוי.","זכרו לנשום עמוק ולשמור על יציבה טובה לאורך כל התרגיל."],"en":["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."],"ru":["Начните с того, что встаньте прямо, ноги на ширине плеч.","Задействуйте корпус и держите верхнюю часть тела расслабленной.","Начните бег на месте, подтягивая колени к груди и мягко приземляясь на подушечки стоп.","Поддерживайте устойчивый темп и продолжайте бег трусцой желаемую продолжительность или расстояние.","Не забывайте глубоко дышать и сохранять правильную осанку на протяжении всего упражнения."],"es":["Comienza de pie con los pies separados a la altura de la cadera.","Activa el core y mantén la parte superior del cuerpo relajada.","Comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies.","Mantén un ritmo constante y continúa trotando durante la duración o distancia deseada.","Recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio."]}},{"id":"1585","name":"runners stretch","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"calves","secondary_muscles":["calves","quadriceps"],"target":"hamstrings","image":"images/1585-0mB6wHO.jpg","gif_url":"videos/1585-0mB6wHO.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן.","צעדו קדימה עם כף רגל ימין, תוך שמירה על כף רגל שמאל נטועה במקומה.","כופפו את ברך ימין והורידו את הגוף, תוך שמירה על רגל שמאל ישרה.","הניחו את הידיים על ירך ימין לתמיכה.","החזיקו את המתיחה 20–30 שניות, ואז החליפו צד וחזרו על התרגיל."],"en":["Stand with your feet hip-width apart.","Take a step forward with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down, keeping your left leg straight.","Place your hands on your right thigh for support.","Hold the stretch for 20-30 seconds, then switch sides and repeat."],"ru":["Встаньте, расставив ноги на ширине плеч.","Сделайте шаг вперед правой ногой, удерживая левую ногу на месте.","Согните правое колено и опустите корпус вниз, сохраняя левую ногу прямой.","Положите руки на правое бедро для поддержки.","Удерживайте растяжку 20–30 секунд, затем поменяйте сторону и повторите."],"es":["Ponte de pie con los pies separados a la altura de la cadera.","Da un paso hacia delante con el pie derecho, manteniendo el pie izquierdo firme en el suelo.","Dobla la rodilla derecha y baja el cuerpo, manteniendo la pierna izquierda recta.","Coloca las manos sobre el muslo derecho para apoyarte.","Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."]}},{"id":"0687","name":"russian twist","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0687-XVDdcoj.jpg","gif_url":"videos/0687-XVDdcoj.gif","instruction_steps":{"he":["שבו על הרצפה עם ברכיים כפופות וכפות רגליים על הרצפה.","הטו את הגוף מעט לאחור תוך שמירה על גב ישר וליבה מופעלת.","החזיקו את הידיים יחד מול החזה, או החזיקו משקל אם תרצו.","הרימו את הרגליים מהרצפה ואזנו את הגוף על עצמות הישיבה.","סובבו את הגו ימינה והביאו את הידיים או המשקל לצד ימין של הגוף.","עצרו לרגע, ואז סובבו את הגו שמאלה והביאו את הידיים או המשקל לצד שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Sit on the ground with your knees bent and feet flat on the floor.","Lean back slightly while keeping your back straight and your core engaged.","Hold your hands together in front of your chest or hold a weight if desired.","Lift your feet off the ground, balancing on your sit bones.","Twist your torso to the right, bringing your hands or weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."],"ru":["Сядьте на пол, согните колени и поставьте ступни на пол.","Слегка откиньтесь назад, сохраняя спину прямой и напряженный корпус.","При желании держите руки вместе перед грудью или держите гирю.","Поднимите ноги от земли, балансируя на седалищных костях.","Поверните туловище вправо, перемещая руки или вес тела к правой стороне тела.","Сделайте паузу на мгновение, затем поверните туловище влево, перемещая руки или вес тела к левой стороне тела.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.","Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado.","Junta las manos frente al pecho o sujeta una pesa si lo deseas.","Levanta los pies del suelo, equilibrándote sobre los isquiones.","Gira el torso hacia la derecha, llevando las manos o la pesa hacia el lado derecho del cuerpo.","Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando las manos o la pesa hacia el lado izquierdo del cuerpo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"3012","name":"scapula dips","category":"back","body_part":"back","equipment":"body weight","muscle_group":"rhomboids","secondary_muscles":["rhomboids","deltoids"],"target":"traps","image":"images/3012-7xeukSt.jpg","gif_url":"videos/3012-7xeukSt.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים וידיים מתוחות לפניכם.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","הורידו את הגוף בכיפוף מרפקים וכיווץ השכמות לאחור, כאילו אתם מנסים ללחוץ עיפרון ביניהן.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך הידיים ליישור המרפקים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.","Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и вытянув руки перед собой.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Опустите корпус, сгибая локти и сводя лопатки, как будто пытаетесь зажать между ними карандаш.","Задержитесь на мгновение в нижней точке, затем подтолкните руки, чтобы разогнуть локти и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Baja el cuerpo doblando los codos y retrayendo las escápulas, como si intentaras apretar un lápiz entre ellas.","Haz una pausa por un momento en la posición baja, luego empuja con las manos para extender los codos y volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3021","name":"scapula push-up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"serratus anterior","image":"images/3021-jV65tKx.jpg","gif_url":"videos/3021-jV65tKx.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים ישר מתחת לכתפיים והגוף בקו ישר.","הורידו את החזה לכיוון הרצפה, תוך שמירה על מרפקים קרובים לגוף.","תוך כדי הירידה, כווצו את השכמות זו לזו ודחפו את החזה קדימה.","עצרו לרגע בנקודה התחתונה, ואז דחפו חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your chest towards the ground, keeping your elbows close to your body.","As you lower, squeeze your shoulder blades together and push your chest forward.","Pause for a moment at the bottom, then push back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, положив руки прямо под плечи, а тело образуя прямую линию.","Опустите грудь к земле, держа локти близко к телу.","Опускаясь, сведите лопатки вместе и выдвиньте грудь вперед.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.","Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.","A medida que bajas, junta las escápulas y empuja el pecho hacia delante.","Haz una pausa por un momento en la posición baja, luego empuja de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0688","name":"scapular pull-up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"traps","image":"images/0688-uTBt1HV.jpg","gif_url":"videos/0688-uTBt1HV.gif","instruction_steps":{"he":["התחילו בתלייה על מוט מתח עם כפות ידיים פונות מכם וידיים ישרות לגמרי.","כווצו את השכמות במשיכתן מטה ולאחור.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון המוט, בהתמקדות בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Retract your shoulder blades by pulling them down and back.","Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с подвешивания на перекладине, повернув ладони от себя и полностью вытянув руки.","Втяните лопатки, потянув их вниз и назад.","Напрягите мышцы спины и подтяните тело к перекладине, стараясь свести лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza colgándote de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos.","Retrae las escápulas llevándolas hacia abajo y atrás.","Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, enfocándote en juntar las escápulas.","Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3219","name":"scissor jumps (male)","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3219-Eh2v5Iu.jpg","gif_url":"videos/3219-Eh2v5Iu.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","קפצו מהרצפה ובו-זמנית הצליבו את רגל ימין לפני רגל שמאל.","עם הנחיתה, החליפו רגליים במהירות, בהצלבת רגל שמאל לפני רגל ימין.","המשיכו להחליף רגליים ולקפוץ מהר ככל האפשר.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Jump off the ground and simultaneously cross your right leg in front of your left leg.","As you land, quickly switch legs, crossing your left leg in front of your right leg.","Continue alternating legs and jumping as quickly as possible.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Спрыгните с земли и одновременно скрестите правую ногу перед левой ногой.","При приземлении быстро поменяйте ноги, скрещивая левую ногу перед правой ногой.","Продолжайте чередовать ноги и прыгать как можно быстрее.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Salta del suelo y al mismo tiempo cruza la pierna derecha por delante de la pierna izquierda.","Al aterrizar, cambia rápidamente de pierna, cruzando la pierna izquierda por delante de la pierna derecha.","Continúa alternando las piernas y saltando lo más rápido posible.","Repite el número de repeticiones deseado."]}},{"id":"1390","name":"seated calf stretch (male)","category":"lower legs","body_part":"lower legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1390-17bqEXD.jpg","gif_url":"videos/1390-17bqEXD.gif","instruction_steps":{"he":["שבו על קצה כיסא או ספסל עם כפות רגליים על הרצפה.","מתחו רגל אחת ישר לפניכם, כשהעקב על הרצפה.","רכנו מעט קדימה, עד תחושת מתיחה בשריר התאומים.","החזיקו את המתיחה 20–30 שניות.","החליפו רגליים וחזרו על המתיחה."],"en":["Sit on the edge of a chair or bench with your feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."],"ru":["Сядьте на край стула или скамьи, поставив ноги на землю.","Вытяните одну ногу прямо перед собой, удерживая пятку на земле.","Слегка наклонитесь вперед, чувствуя растяжение икроножных мышц.","Удерживайте растяжку 20–30 секунд.","Поменяйте ноги и повторите растяжку."],"es":["Siéntate en el borde de una silla o banco con los pies planos sobre el suelo.","Extiende una pierna recta frente a ti, manteniendo el talón en el suelo.","Inclínate ligeramente hacia delante, sintiendo un estiramiento en la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Cambia de pierna y repite el estiramiento."]}},{"id":"1424","name":"seated glute stretch","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"glutes","image":"images/1424-DeDThfG.jpg","gif_url":"videos/1424-DeDThfG.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים ישרות לפניכם.","כופפו את ברך ימין והצליבו את קרסול ימין מעל ירך שמאל.","הניחו את יד ימין על הרצפה מאחוריכם לתמיכה.","עם יד שמאל, לחצו בעדינות על ברך ימין להעמקת המתיחה.","החזיקו את המתיחה 30 שניות עד דקה.","החליפו צדדים וחזרו על התרגיל."],"en":["Sit on the ground with your legs extended in front of you.","Bend your right knee and cross your right ankle over your left thigh.","Place your right hand on the ground behind you for support.","With your left hand, gently press down on your right knee to deepen the stretch.","Hold the stretch for 30 seconds to 1 minute.","Switch sides and repeat."],"ru":["Сядьте на пол, вытянув ноги перед собой.","Согните правое колено и перекиньте правую лодыжку через левое бедро.","Положите правую руку на землю позади себя для поддержки.","Левой рукой осторожно надавите на правое колено, чтобы углубить растяжку.","Удерживайте растяжку от 30 секунд до 1 минуты.","Поменяйте стороны и повторите."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti.","Dobla la rodilla derecha y cruza el tobillo derecho sobre el muslo izquierdo.","Coloca la mano derecha en el suelo detrás de ti para apoyarte.","Con la mano izquierda, presiona suavemente la rodilla derecha para profundizar el estiramiento.","Mantén el estiramiento durante 30 segundos a 1 minuto.","Cambia de lado y repite."]}},{"id":"0689","name":"seated leg raise","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0689-Hgs6Nl1.jpg","gif_url":"videos/0689-Hgs6Nl1.gif","instruction_steps":{"he":["שבו על ספסל ישר עם גב ישר וכפות רגליים על הרצפה.","הניחו את הידיים על צידי הספסל לתמיכה.","תוך שמירה על רגליים ישרות, הרימו אותן באיטיות לפניכם עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a flat bench with your back straight and your feet flat on the ground.","Place your hands on the sides of the bench for support.","Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на ровную скамью, выпрямив спину и поставив ноги на землю.","Положите руки по бокам скамьи для поддержки.","Держа ноги прямыми, медленно поднимите их перед собой, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco plano con la espalda recta y los pies planos sobre el suelo.","Coloca las manos a los lados del banco para apoyarte.","Manteniendo las piernas rectas, levántalas lentamente frente a ti hasta que queden paralelas al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0690","name":"seated lower back stretch","category":"back","body_part":"back","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"lats","image":"images/0690-QFmz6ch.jpg","gif_url":"videos/0690-QFmz6ch.gif","instruction_steps":{"he":["שבו על קצה כיסא עם כפות רגליים על הרצפה.","הניחו את הידיים על הירכיים או על צידי הכיסא לתמיכה.","רכנו באיטיות קדימה מהירכיים, תוך שמירה על גב ישר.","הרגישו את המתיחה בגב התחתון והחזיקו 20–30 שניות.","חזרו באיטיות לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the edge of a chair with your feet flat on the ground.","Place your hands on your thighs or on the sides of the chair for support.","Slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your lower back and hold for 20-30 seconds.","Slowly return to the starting position and repeat for the desired number of repetitions."],"ru":["Сядьте на край стула, поставив ноги на землю.","Положите руки на бедра или по бокам стула для поддержки.","Медленно наклонитесь вперед от бедер, сохраняя спину прямой.","Почувствуйте растяжение в пояснице и задержитесь на 20–30 секунд.","Медленно вернитесь в исходное положение и повторите необходимое количество повторений."],"es":["Siéntate en el borde de una silla con los pies planos sobre el suelo.","Coloca las manos sobre los muslos o a los lados de la silla para apoyarte.","Inclínate lentamente hacia delante desde la cadera, manteniendo la espalda recta.","Siente el estiramiento en la zona lumbar y mantén la posición durante 20-30 segundos.","Regresa lentamente a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"2567","name":"seated piriformis stretch","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"glutes","image":"images/2567-QY39eBr.jpg","gif_url":"videos/2567-QY39eBr.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים ישרות לפניכם.","כופפו את ברך ימין והניחו את כף רגל ימין מחוץ לברך שמאל.","הניחו את מרפק שמאל מחוץ לברך ימין וסובבו בעדינות את הגו ימינה.","החזיקו את המתיחה 20–30 שניות, ואז החליפו צד וחזרו על התרגיל."],"en":["Sit on the ground with your legs extended in front of you.","Bend your right knee and place your right foot on the outside of your left knee.","Place your left elbow on the outside of your right knee and gently twist your torso to the right.","Hold the stretch for 20-30 seconds, then switch sides and repeat."],"ru":["Сядьте на пол, вытянув ноги перед собой.","Согните правое колено и поставьте правую стопу снаружи левого колена.","Положите левый локоть на внешнюю сторону правого колена и осторожно поверните туловище вправо.","Удерживайте растяжку 20–30 секунд, затем поменяйте сторону и повторите."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti.","Dobla la rodilla derecha y coloca el pie derecho en la parte exterior de la rodilla izquierda.","Coloca el codo izquierdo en la parte exterior de la rodilla derecha y gira suavemente el torso hacia la derecha.","Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."]}},{"id":"0691","name":"seated side crunch (wall)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0691-Y9hNPcN.jpg","gif_url":"videos/0691-Y9hNPcN.gif","instruction_steps":{"he":["שבו על הרצפה כשהגב צמוד לקיר והרגליים מתוחות לפניכם.","כופפו ברכיים והניחו את כפות הרגליים על הרצפה, ברוחב אגן.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","הפעילו את שרירי הבטן והיטו את הגוף לצד אחד, בהבאת המרפק לכיוון המותן.","עצרו לרגע, ואז חזרו לנקודת ההתחלה.","חזרו על התנועה בצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Sit on the floor with your back against a wall and your legs extended in front of you.","Bend your knees and place your feet flat on the floor, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lean to one side, bringing your elbow towards your hip.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Сядьте на пол, прислонившись спиной к стене и вытянув ноги перед собой.","Согните колени и поставьте ступни на пол, на ширине плеч.","Положите руки за голову локтями наружу.","Напрягите пресс и наклонитесь в сторону, поднеся локоть к бедру.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите с другой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Siéntate en el suelo con la espalda contra una pared y las piernas extendidas frente a ti.","Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Contrae el abdomen e inclínate hacia un lado, llevando el codo hacia la cadera.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1587","name":"seated wide angle pose sequence","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","calves"],"target":"hamstrings","image":"images/1587-HIgYKAB.jpg","gif_url":"videos/1587-HIgYKAB.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים מתוחות בפיסוק רחב.","כופפו את כפות הרגליים והפעילו את הארבע ראשי.","הניחו את הידיים על הרצפה מאחוריכם לתמיכה.","תוך שמירה על גב ישר, רכנו קדימה מהירכיים.","המשיכו לרכון קדימה עד לתחושת מתיחה בירך האחורית.","החזיקו את התנוחה כמה נשימות.","שחררו באיטיות את המתיחה וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the ground with your legs extended in a wide angle.","Flex your feet and engage your quadriceps.","Place your hands on the ground behind you for support.","Keeping your back straight, lean forward from your hips.","Continue leaning forward until you feel a stretch in your hamstrings.","Hold this position for a few breaths.","Slowly release the stretch and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на пол, вытянув ноги под широким углом.","Согните ноги и задействуйте квадрицепсы.","Положите руки на землю позади себя для поддержки.","Сохраняя спину прямой, наклонитесь вперед от бедер.","Продолжайте наклоняться вперед, пока не почувствуете растяжение подколенных сухожилий.","Задержитесь в этом положении на несколько вдохов.","Медленно ослабьте растяжку и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el suelo con las piernas extendidas formando un ángulo amplio.","Flexiona los pies y contrae los cuádriceps.","Coloca las manos en el suelo detrás de ti para apoyarte.","Manteniendo la espalda recta, inclínate hacia delante desde la cadera.","Continúa inclinándote hacia delante hasta sentir un estiramiento en los isquiotibiales.","Mantén esta posición durante unas cuantas respiraciones.","Libera lentamente el estiramiento y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0697","name":"self assisted inverse leg curl","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","calves"],"target":"hamstrings","image":"images/0697-GwYwElT.jpg","gif_url":"videos/0697-GwYwElT.gif","instruction_steps":{"he":["שכבו על הגב על מזרן או ספסל עם רגליים מתוחות.","הניחו את הידיים לצידי הגוף או מתחת לישבן לתמיכה.","כופפו ברכיים והרימו את כפות הרגליים מהרצפה, בהבאת הירכיים לכיוון החזה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back on a mat or bench with your legs extended.","Place your hands by your sides or under your glutes for support.","Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину на коврик или скамью, вытянув ноги.","Положите руки по бокам или под ягодицы для поддержки.","Согните колени и оторвите ступни от земли, подтягивая бедра к груди.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba sobre una esterilla o banco con las piernas extendidas.","Coloca las manos a los lados o debajo de los glúteos para apoyarte.","Dobla las rodillas y levanta los pies del suelo, llevando los muslos hacia el pecho.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1766","name":"self assisted inverse leg curl","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","calves"],"target":"hamstrings","image":"images/1766-ZSY3MsL.jpg","gif_url":"videos/1766-ZSY3MsL.gif","instruction_steps":{"he":["שכבו על הבטן על מכונת כפיפת רגליים עם רגליים מתוחות והקרסוליים מעוגנים מתחת למנוף המרופד.","הניחו את הידיים על ידיות הצד של המכשיר לתמיכה.","תוך שמירה על פלג גוף עליון ללא תזוזה, נשפו וגלגלו את הרגליים כלפי מעלה רחוק ככל האפשר.","החזיקו את התנוחה המכווצת לרגע קצר תוך כיווץ הירך האחורית.","הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה תוך שאיפה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.","Place your hands on the side handles of the machine for support.","Keeping your upper body stationary, exhale and curl your legs upward as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Slowly lower your legs back to the starting position while inhaling.","Repeat for the desired number of repetitions."],"ru":["Лягте лицом вниз на тренажер для сгибания ног, вытянув ноги и зацепив лодыжки под мягким рычагом.","Положите руки на боковые ручки машины для поддержки.","Удерживая верхнюю часть тела неподвижно, выдохните и поднимите ноги вверх, насколько это возможно.","Задержитесь в сокращенном положении на короткую паузу, сжимая мышцы задней поверхности бедра.","Медленно опустите ноги обратно в исходное положение на вдохе.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo en una máquina de curl femoral con las piernas extendidas y los tobillos enganchados bajo la palanca acolchada.","Coloca las manos en las asas laterales de la máquina para apoyarte.","Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia arriba lo más posible.","Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales.","Baja lentamente las piernas de vuelta a la posición inicial mientras inhalas.","Repite el número de repeticiones deseado."]}},{"id":"0696","name":"self assisted inverse leg curl (on floor)","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","calves"],"target":"hamstrings","image":"images/0696-E4PwJqI.jpg","gif_url":"videos/0696-E4PwJqI.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וידיים לצידי הגוף.","כופפו ברכיים והניחו את כפות הרגליים על הרצפה, ברוחב אגן.","הרימו את האגן מהרצפה, תוך הפעלת הישבן והירך האחורית.","גלגלו באיטיות את הרגליים לכיוון הישבן, תוך שמירה על אגן מורם.","עצרו לרגע בנקודה העליונה, ואז יישרו באיטיות את הרגליים חזרה לנקודת ההתחלה.","הורידו את האגן חזרה לרצפה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and place your feet flat on the ground, hip-width apart.","Lift your hips off the ground, engaging your glutes and hamstrings.","Slowly curl your legs towards your glutes, keeping your hips lifted.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Lower your hips back down to the ground.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, вытянув ноги и положив руки по бокам.","Согните колени и поставьте ступни на землю, на ширине плеч.","Поднимите бедра от земли, задействуя ягодицы и мышцы задней поверхности бедра.","Медленно согните ноги к ягодицам, держа бедра приподнятыми.","Задержитесь на мгновение в верхней точке, затем медленно вытяните ноги обратно в исходное положение.","Опустите бедра обратно на землю.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.","Levanta las caderas del suelo, activando los glúteos y los isquiotibiales.","Flexiona lentamente las piernas hacia los glúteos, manteniendo las caderas elevadas.","Haz una pausa breve en la parte superior, luego extiende lentamente las piernas de vuelta a la posición inicial.","Baja las caderas de nuevo hacia el suelo.","Repite el número de repeticiones deseado."]}},{"id":"3222","name":"semi squat jump (male)","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3222-6FMU51h.jpg","gif_url":"videos/3222-6FMU51h.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","כופפו ברכיים והורידו את הגוף לעמדת סקוואט.","קפצו בפיצוץ, תוך יישור הירכיים והברכיים והנפת הידיים לתנופה.","נחתו ברכות על כריות כפות הרגליים והמשיכו מיד לחזרה הבאה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively, extending your hips and knees while swinging your arms for momentum.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Согните колени и опустите тело в присед.","Прыгайте взрывно, разгибая бедра и колени, одновременно размахивая руками для создания импульса.","Мягко приземлитесь на подушечки стоп и сразу же переходите к следующему повторению.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.","Salta de forma explosiva, extendiendo las caderas y las rodillas mientras balanceas los brazos para generar impulso.","Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición.","Repite el número de repeticiones deseado."]}},{"id":"3656","name":"short stride run","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3656-CcWEoWV.jpg","gif_url":"videos/3656-CcWEoWV.gif","instruction_steps":{"he":["מצאו שטח פתוח או הליכון לביצוע התרגיל.","עמדו זקוף עם רגליים ברוחב אגן.","התחילו לרוץ במקום, בהרמת ברכיים גבוה והנפת הידיים.","אחרי כמה שניות, התחילו לצעוד קדימה בצעדים קצרים, בקצב מהיר.","המשיכו לרוץ בצעדים קצרים למשך הזמן או המרחק הרצוי."],"en":["Find an open space or a treadmill to perform the exercise.","Stand tall with your feet hip-width apart.","Start jogging in place, lifting your knees high and pumping your arms.","After a few seconds, start taking short strides forward, maintaining a quick pace.","Continue running with short strides for the desired duration or distance."],"ru":["Найдите открытое пространство или беговую дорожку для выполнения упражнения.","Встаньте прямо, ноги на ширине плеч.","Начните бег на месте, высоко поднимая колени и качая руками.","Через несколько секунд начните делать короткие шаги вперед, сохраняя быстрый темп.","Продолжайте бежать короткими шагами желаемую продолжительность или расстояние."],"es":["Busca un espacio abierto o una cinta de correr para realizar el ejercicio.","Ponte de pie con los pies separados a la altura de la cadera.","Comienza a trotar en el lugar, levantando las rodillas alto y moviendo los brazos.","Después de unos segundos, comienza a dar pasos cortos hacia delante, manteniendo un ritmo rápido.","Continúa corriendo con pasos cortos durante la duración o distancia deseada."]}},{"id":"1763","name":"shoulder grip pull-up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1763-YtgD7Xq.jpg","gif_url":"videos/1763-YtgD7Xq.gif","instruction_steps":{"he":["אחזו במוט המתח באחיזה ברוחב כתפיים, כפות ידיים פונות מכם.","היתלו בחופשיות עם ידיים ישרות לגמרי.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון המוט עד שהסנטר מעל המוט.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Grab the pull-up bar with a shoulder-width grip, palms facing away from you.","Hang freely with your arms fully extended.","Engage your back muscles and pull your body up towards the bar until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Возьмитесь за перекладину хватом на ширине плеч, ладонями от себя.","Свободно висите, полностью вытянув руки.","Напрягите мышцы спины и подтяните тело к перекладине, пока подбородок не окажется над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta la barra de dominadas con un agarre a la altura de los hombros, con las palmas mirando hacia fuera.","Cuélgate libremente con los brazos completamente extendidos.","Activa los músculos de la espalda y tira de tu cuerpo hacia la barra hasta que la barbilla quede por encima de ella.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3699","name":"shoulder tap","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"abs","image":"images/3699-yRpV5TC.jpg","gif_url":"videos/3699-yRpV5TC.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים ישר מתחת לכתפיים והגוף בקו ישר.","הפעילו את הליבה והרימו את יד ימין מהרצפה, בהצלבה לנגיעה בכתף שמאל.","החזירו את יד ימין לרצפה וחזרו על התנועה עם יד שמאל נוגעת בכתף ימין.","המשיכו בנגיעות כתפיים לסירוגין תוך שמירה על אגן וגו יציבים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.","Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.","Continue alternating shoulder taps while keeping your hips and torso stable.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, положив руки прямо под плечи, а тело образуя прямую линию.","Напрягите корпус и поднимите правую руку от земли, протягивая руку и коснувшись левого плеча.","Положите правую руку обратно на землю и повторите то же самое, постукивая левой рукой по правому плечу.","Продолжайте поочередно постукивать плечами, сохраняя при этом бедра и туловище устойчивыми.","Повторите необходимое количество повторений."],"es":["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.","Activa el core y levanta la mano derecha del suelo, extendiéndola para tocar el hombro izquierdo.","Coloca la mano derecha de nuevo en el suelo y repite tocando el hombro derecho con la mano izquierda.","Continúa alternando los toques de hombro mientras mantienes las caderas y el torso estables.","Repite el número de repeticiones deseado."]}},{"id":"0699","name":"shoulder tap push-up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"pectorals","image":"images/0699-qEse6fe.jpg","gif_url":"videos/0699-qEse6fe.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים מעט רחבות מרוחב הכתפיים והגוף בקו ישר מהראש ועד העקבים.","הורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף.","תוך כדי הדחיפה חזרה למעלה, הרימו את יד ימין מהרצפה וגעו בכתף שמאל.","החזירו את יד ימין לרצפה וחזרו על שכיבת הסמיכה, הפעם בהרמת יד שמאל ונגיעה בכתף ימין.","המשיכו להחליף נגיעות כתפיים בכל חזרת שכיבת סמיכה.","שמרו על ליבה יציבה והימנעו מסיבוב אגן מוגזם לאורך כל התרגיל.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you push back up, lift your right hand off the ground and tap your left shoulder.","Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.","Continue alternating shoulder taps with each push-up repetition.","Maintain a stable core and avoid excessive hip rotation throughout the exercise.","Repeat for the desired number of repetitions."],"ru":["Начните с положения высокой планки, расставив руки чуть шире плеч, а тело образуя прямую линию от головы до пяток.","Опустите тело к земле, согнув локти и держа их близко к бокам.","Отталкиваясь назад, поднимите правую руку от земли и коснитесь левого плеча.","Верните правую руку на землю и повторите отжимание, на этот раз подняв левую руку и коснувшись правого плеча.","Продолжайте поочередно постукивать по плечам при каждом повторении отжиманий.","Поддерживайте стабильное положение корпуса и избегайте чрезмерного вращения бедрами на протяжении всего упражнения.","Повторите необходимое количество повторений."],"es":["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Mientras empujas hacia arriba, levanta la mano derecha del suelo y toca el hombro izquierdo.","Vuelve a colocar la mano derecha en el suelo y repite la flexión, esta vez levantando la mano izquierda y tocando el hombro derecho.","Continúa alternando los toques de hombro en cada repetición de la flexión.","Mantén el core estable y evita una rotación excesiva de la cadera durante todo el ejercicio.","Repite el número de repeticiones deseado."]}},{"id":"1774","name":"side bridge hip abduction","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","obliques"],"target":"abductors","image":"images/1774-WL4EmxJ.jpg","gif_url":"videos/1774-WL4EmxJ.gif","instruction_steps":{"he":["שכבו על הצד עם רגליים מתוחות זו על גבי זו.","היתמכו על האמה, תוך שמירה על המרפק ישר מתחת לכתף.","הפעילו את הליבה והרימו את האגן מהרצפה, ביצירת קו ישר מהראש ועד כפות הרגליים.","תוך שמירה על ליבה מופעלת, הרימו את הרגל העליונה גבוה ככל האפשר בלי לסובב את האגן.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגל חזרה מטה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Lie on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While keeping your core engaged, lift your top leg as high as possible without rotating your hips.","Pause for a moment at the top, then lower your leg back down.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Лягте на бок, вытянув ноги и положив их друг на друга.","Обопритесь на предплечье, держа локоть прямо под плечом.","Напрягите корпус и поднимите бедра от земли, создавая прямую линию от головы до ступней.","Удерживая корпус в напряжении, поднимите верхнюю ногу как можно выше, не вращая бедрами.","Задержитесь на мгновение в верхней точке, затем опустите ногу обратно вниз.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Túmbate de lado con las piernas extendidas y una sobre la otra.","Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro.","Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.","Manteniendo el core activado, levanta la pierna superior lo más alto posible sin rotar las caderas.","Haz una pausa por un momento en la posición alta, luego baja la pierna de nuevo.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0705","name":"side bridge v. 2","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","glutes"],"target":"abs","image":"images/0705-RKjH6Lt.jpg","gif_url":"videos/0705-RKjH6Lt.gif","instruction_steps":{"he":["שכבו על הצד עם רגליים מתוחות זו על גבי זו.","הניחו את האמה על הרצפה ישר מתחת לכתף, עם מרפק כפוף בזווית של 90 מעלות.","הפעילו את הליבה והרימו את האגן מהרצפה, ביצירת קו ישר מהראש ועד כפות הרגליים.","החזיקו את התנוחה למשך הזמן הרצוי.","הורידו את האגן חזרה לנקודת ההתחלה.","חזרו על התנועה בצד השני."],"en":["Lie on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the starting position.","Repeat on the other side."],"ru":["Лягте на бок, вытянув ноги и положив их друг на друга.","Положите предплечье на землю прямо под плечом, согнув локоть под углом 90 градусов.","Напрягите корпус и поднимите бедра от земли, создавая прямую линию от головы до ступней.","Удерживайте это положение желаемое время.","Опустите бедра обратно в исходное положение.","Повторите с другой стороны."],"es":["Túmbate de lado con las piernas extendidas y una sobre la otra.","Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados.","Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.","Mantén esta posición durante el tiempo deseado.","Baja las caderas de vuelta a la posición inicial.","Repite del otro lado."]}},{"id":"0709","name":"side hip (on parallel bars)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/0709-jTkSc6o.jpg","gif_url":"videos/0709-jTkSc6o.gif","instruction_steps":{"he":["עמדו בין שני מקבילים עם רגליים ברוחב כתפיים.","הניחו את הידיים על המוטות והרימו את הגוף מהרצפה, בתמיכת משקל הגוף על הידיים.","הפעילו את שרירי הבטן והרימו באיטיות את הרגליים הצידה, כשהן ישרות.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand between two parallel bars with your feet shoulder-width apart.","Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.","Engage your abs and slowly lift your legs to the side, keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте между двумя параллельными брусьями, поставив ноги на ширине плеч.","Положите руки на перекладины и поднимите тело от земли, удерживая вес на руках.","Напрягите пресс и медленно поднимите ноги в стороны, сохраняя их прямыми.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie entre dos barras paralelas con los pies separados a la altura de los hombros.","Coloca las manos sobre las barras y levanta el cuerpo del suelo, apoyando tu peso en los brazos.","Contrae el abdomen y levanta lentamente las piernas hacia el lado, manteniéndolas rectas.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0710","name":"side hip abduction","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","quadriceps"],"target":"abductors","image":"images/0710-7WaDzyL.jpg","gif_url":"videos/0710-7WaDzyL.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וידיים על המותניים.","העבירו את המשקל לרגל אחת והרימו את הרגל הנגדית הצידה, כשהיא ישרה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגל באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה בצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your hands on your hips.","Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, руки на бедрах.","Перенесите вес тела на одну ногу и поднимите противоположную ногу в сторону, сохраняя ее прямой.","Задержитесь на мгновение в верхней точке, затем медленно опустите ногу обратно в исходное положение.","Повторите с другой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas.","Traslada el peso a una pierna y levanta la pierna opuesta hacia el lado, manteniéndola recta.","Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1358","name":"side lying floor stretch","category":"back","body_part":"back","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","glutes"],"target":"lats","image":"images/1358-jDOKRM5.jpg","gif_url":"videos/1358-jDOKRM5.gif","instruction_steps":{"he":["שכבו על הצד עם רגליים ישרות והיד התחתונה מתוחה ישר מעל הראש.","כופפו את הברך העליונה והניחו את כף הרגל על הרצפה לפני הרגל התחתונה.","מתחו את היד העליונה מעל הראש ואחזו במשהו יציב, כמו קיר או רהיט.","הרימו באיטיות את הרגל התחתונה מהרצפה, כשהיא ישרה, עד תחושת מתיחה בצד הגוף.","החזיקו את המתיחה 20–30 שניות, ואז הורידו את הרגל באיטיות חזרה.","חזרו על התנועה בצד השני."],"en":["Lie on your side with your legs straight and your bottom arm extended straight overhead.","Bend your top knee and place your foot on the ground in front of your bottom leg.","Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.","Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.","Hold the stretch for 20-30 seconds, then slowly lower your leg back down.","Repeat on the other side."],"ru":["Лягте на бок, выпрямив ноги и вытянув нижнюю руку над головой.","Согните верхнее колено и поставьте ступню на землю перед нижней ногой.","Вытяните верхнюю руку над головой и ухватитесь за что-нибудь устойчивое, например, за стену или предмет мебели.","Медленно поднимите нижнюю ногу от земли, удерживая ее прямой, пока не почувствуете растяжение в боку.","Удерживайте растяжку 20–30 секунд, затем медленно опустите ногу обратно вниз.","Повторите с другой стороны."],"es":["Túmbate de lado con las piernas rectas y el brazo de abajo extendido recto por encima de la cabeza.","Dobla la rodilla de arriba y coloca el pie en el suelo frente a la pierna de abajo.","Extiende el brazo de arriba por encima de la cabeza y agárrate a algo estable, como una pared o un mueble.","Levanta lentamente la pierna de abajo del suelo, manteniéndola recta, hasta sentir un estiramiento en el costado.","Mantén el estiramiento durante 20-30 segundos, luego baja lentamente la pierna de nuevo.","Repite del otro lado."]}},{"id":"3667","name":"side lying hip adduction (male)","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"adductors","image":"images/3667-c8f5cSY.jpg","gif_url":"videos/3667-c8f5cSY.gif","instruction_steps":{"he":["שכבו על הצד עם רגליים ישרות זו על גבי זו.","הניחו את היד התחתונה מתחת לראש לתמיכה.","הפעילו את מקרבי הירך והרימו את הרגל העליונה גבוה ככל האפשר בלי לסובב את האגן או להישען לאחור.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Лягте на бок, выпрямив ноги и положив их друг на друга.","Поместите нижнюю руку под голову для поддержки.","Включите приводящие мышцы и поднимите верхнюю ногу как можно выше, не вращая бедрами и не отклоняясь назад.","Задержитесь на мгновение в верхней точке, затем медленно опустите ногу обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Túmbate de lado con las piernas rectas y apiladas una sobre la otra.","Coloca el brazo de abajo bajo la cabeza para apoyarte.","Activa los aductores y levanta la pierna de arriba lo más alto posible sin rotar las caderas ni inclinarte hacia atrás.","Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"1775","name":"side plank hip adduction","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","glutes"],"target":"adductors","image":"images/1775-VO2qeJg.jpg","gif_url":"videos/1775-VO2qeJg.gif","instruction_steps":{"he":["התחילו בשכיבה על הצד עם רגליים מתוחות זו על גבי זו.","היתמכו על האמה, תוך שמירה על המרפק ישר מתחת לכתף.","הפעילו את הליבה והרימו את האגן מהרצפה, ביצירת קו ישר מהראש ועד כפות הרגליים.","תוך שמירה על תנוחת הפלאנק הצדי, הרימו את הרגל העליונה לכיוון התקרה, כשהיא ישרה.","הורידו את הרגל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Start by lying on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.","Slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Начните с того, что лягте на бок, вытянув ноги и положив их друг на друга.","Обопритесь на предплечье, держа локоть прямо под плечом.","Напрягите корпус и поднимите бедра от земли, создавая прямую линию от головы до ступней.","Сохраняя положение боковой планки, поднимите верхнюю ногу к потолку, сохраняя ее прямой.","Медленно опустите ногу обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.","Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro.","Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.","Manteniendo la posición de plancha lateral, levanta la pierna de arriba hacia el techo, manteniéndola recta.","Baja lentamente la pierna de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0716","name":"side push neck stretch","category":"neck","body_part":"neck","equipment":"body weight","muscle_group":"trapezius","secondary_muscles":["trapezius","sternocleidomastoid"],"target":"levator scapulae","image":"images/0716-oQRJYkC.jpg","gif_url":"videos/0716-oQRJYkC.gif","instruction_steps":{"he":["עמדו או שבו זקוף עם כתפיים רפויות.","הטו את הראש ימינה, בהבאת אוזן ימין לכיוון כתף ימין.","הניחו את יד ימין על צד שמאל של הראש ולחצו בעדינות להגברת המתיחה.","החזיקו את המתיחה 15–30 שניות.","חזרו על התנועה בצד השני, בהטיית הראש שמאלה ולחיצה עדינה עם יד שמאל.","חזרו על המתיחה 2–3 פעמים בכל צד."],"en":["Stand or sit up straight with your shoulders relaxed.","Tilt your head to the right, bringing your right ear towards your right shoulder.","Place your right hand on the left side of your head and gently apply pressure to increase the stretch.","Hold the stretch for 15-30 seconds.","Repeat on the other side, tilting your head to the left and applying pressure with your left hand.","Repeat the stretch 2-3 times on each side."],"ru":["Встаньте или сядьте прямо, расслабив плечи.","Наклоните голову вправо, приближая правое ухо к правому плечу.","Положите правую руку на левую сторону головы и осторожно надавите, чтобы усилить растяжение.","Удерживайте растяжку 15–30 секунд.","Повторите то же самое с другой стороны, наклонив голову влево и надавив левой рукой.","Повторите растяжку 2–3 раза с каждой стороны."],"es":["Ponte de pie o siéntate erguido con los hombros relajados.","Inclina la cabeza hacia la derecha, llevando la oreja derecha hacia el hombro derecho.","Coloca la mano derecha en el lado izquierdo de la cabeza y aplica una presión suave para aumentar el estiramiento.","Mantén el estiramiento durante 15-30 segundos.","Repite hacia el otro lado, inclinando la cabeza hacia la izquierda y aplicando presión con la mano izquierda.","Repite el estiramiento 2-3 veces en cada lado."]}},{"id":"0717","name":"side push-up","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","chest","core"],"target":"triceps","image":"images/0717-wpbD28t.jpg","gif_url":"videos/0717-wpbD28t.gif","instruction_steps":{"he":["התחילו בשכיבה על הצד עם רגליים מתוחות זו על גבי זו.","הניחו את היד התחתונה על הרצפה ישר מתחת לכתף, אצבעות פונות קדימה.","דחפו דרך היד התחתונה להרמת הגוף מהרצפה, תוך שמירה על רגליים ישרות וליבה מופעלת.","מתחו את היד העליונה ישר למעלה לכיוון התקרה, ביצירת קו ישר מהראש ועד העקבים.","הורידו את הגוף חזרה לנקודת ההתחלה בשליטה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.","Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.","Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Начните с того, что лягте на бок, вытянув ноги и положив их друг на друга.","Положите нижнюю руку на землю прямо под плечом, пальцы направлены вперед.","Надавите нижней рукой, чтобы оторвать тело от земли, сохраняя ноги прямыми и напряженным корпусом.","Вытяните верхнюю руку прямо вверх к потолку, создавая прямую линию от головы до пяток.","Опустите тело обратно в исходное положение, контролируя его.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.","Coloca la mano de abajo en el suelo directamente debajo del hombro, con los dedos apuntando hacia delante.","Empuja con la mano de abajo para levantar el cuerpo del suelo, manteniendo las piernas rectas y el core activado.","Extiende el brazo de arriba recto hacia el techo, formando una línea recta desde la cabeza hasta los talones.","Baja el cuerpo de nuevo a la posición inicial con control.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0721","name":"side wrist pull stretch","category":"lower arms","body_part":"lower arms","equipment":"body weight","muscle_group":"wrists","secondary_muscles":["wrists","hands"],"target":"forearms","image":"images/0721-UtmIqcI.jpg","gif_url":"videos/0721-UtmIqcI.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וידיים מתוחות לפניכם.","מתחו את יד ימין הצידה, מקבילה לרצפה, עם כף יד כלפי מטה.","עם יד שמאל, אחזו ביד ימין ומשכו אותה בעדינות לכיוון הגוף, עד תחושת מתיחה באמת ימין.","החזיקו את המתיחה 15–30 שניות, ואז שחררו.","חזרו על התנועה בצד השני."],"en":["Stand with your feet shoulder-width apart and your arms extended in front of you.","Extend your right arm out to the side, parallel to the ground, with your palm facing down.","With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."],"ru":["Встаньте, ноги на ширине плеч, руки вытянуты перед собой.","Вытяните правую руку в сторону параллельно земле ладонью вниз.","Левой рукой возьмите правую руку и осторожно потяните ее к телу, чувствуя растяжение в правом предплечье.","Удерживайте растяжку 15–30 секунд, затем расслабьтесь.","Повторите с другой стороны."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti.","Extiende el brazo derecho hacia el lado, paralelo al suelo, con la palma hacia abajo.","Con la mano izquierda, sujeta la mano derecha y tira de ella suavemente hacia tu cuerpo, sintiendo un estiramiento en el antebrazo derecho.","Mantén el estiramiento durante 15-30 segundos, luego suelta.","Repite del otro lado."]}},{"id":"0720","name":"side-to-side chin","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0720-isAAZWA.jpg","gif_url":"videos/0720-isAAZWA.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","אחזו במוט מתח באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","היתלו על המוט עם ידיים ישרות לגמרי וגוף רפוי.","משכו את עצמכם למעלה בכיפוף המרפקים והבאת הסנטר לכיוון המוט, תוך שמירה על גוף ישר.","כשהסנטר מעל המוט, הורידו את עצמכם חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body relaxed.","Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.","Once your chin is above the bar, lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Возьмитесь за перекладину хватом сверху, руки на расстоянии чуть шире плеч.","Повисните на перекладине, полностью вытянув руки и расслабив тело.","Поднимитесь, сгибая локти и подтягивая подбородок к перекладине, сохраняя при этом тело прямым.","Как только подбородок окажется над перекладиной, опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo relajado.","Levántate doblando los codos y llevando la barbilla hacia la barra, manteniendo el cuerpo recto.","Una vez que la barbilla esté por encima de la barra, bájate de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3213","name":"side-to-side toe touch (male)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/3213-WCAvOfC.jpg","gif_url":"videos/3213-WCAvOfC.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וידיים מתוחות לצדדים.","הטו את הגו ימינה מהמותניים, במתיחת יד ימין לכיוון כף רגל ימין תוך שמירה על יד שמאל מתוחה הצידה.","חזרו לנקודת ההתחלה ואז הטו את הגו שמאלה מהמותניים, במתיחת יד שמאל לכיוון כף רגל שמאל תוך שמירה על יד ימין מתוחה הצידה.","חזרו על תנועת ההטיה מצד לצד למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.","Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.","Repeat the side-to-side bending motion for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, руки вытянуты в стороны.","Согнитесь в талии вправо, потянув правую руку к правой ноге, сохраняя при этом левую руку вытянутой в сторону.","Вернитесь в исходное положение, а затем согнитесь в талии влево, потянув левую руку к левой ноге, удерживая правую руку вытянутой в сторону.","Повторите наклоняющее движение из стороны в сторону необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.","Dobla la cintura hacia la derecha, llevando la mano derecha hacia el pie derecho mientras mantienes la mano izquierda extendida hacia el lado.","Vuelve a la posición inicial y luego dobla la cintura hacia la izquierda, llevando la mano izquierda hacia el pie izquierdo mientras mantienes la mano derecha extendida hacia el lado.","Repite el movimiento de flexión lateral el número de repeticiones deseado."]}},{"id":"0725","name":"single arm push-up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0725-MUic5zN.jpg","gif_url":"videos/0725-MUic5zN.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים ברוחב כתפיים, כשיד אחת ממוקמת מעט רחב מהשנייה.","הפעילו את הליבה והורידו את הגוף לכיוון הרצפה בכיפוף מרפקים, תוך שמירה על גב ישר.","תוך כדי הירידה, העבירו את המשקל לצד אחד והרימו את היד הנגדית מהרצפה, במתיחתה ישר הצידה.","דחפו דרך החזה והטרייספס להרמת הגוף חזרה לנקודת ההתחלה, ובו-זמנית הורידו את היד המתוחה חזרה לרצפה.","חזרו על התנועה, לסירוגין בין הידיים המתוחות בכל חזרה."],"en":["Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.","Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.","Repeat the movement, alternating the arm you extend with each repetition."],"ru":["Начните с позиции отжимания, поставив руки на ширине плеч и одну руку немного шире другой.","Напрягите корпус и опустите тело к земле, сгибая локти, сохраняя спину прямой.","Опускаясь, перенесите вес тела в одну сторону и поднимите противоположную руку от земли, вытягивая ее прямо в сторону.","Надавите на грудь и трицепс, чтобы поднять тело обратно в исходное положение, одновременно опуская вытянутую руку обратно на землю.","Повторите движение, чередуя вытягиваемую руку при каждом повторении."],"es":["Comienza en posición de flexión con las manos separadas a la altura de los hombros y una mano colocada un poco más ancha que la otra.","Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta.","Al bajar, traslada el peso hacia un lado y levanta el brazo opuesto del suelo, extendiéndolo recto hacia el lado.","Empuja con el pecho y los tríceps para subir el cuerpo de nuevo a la posición inicial, mientras bajas simultáneamente el brazo extendido de vuelta al suelo.","Repite el movimiento, alternando el brazo que extiendes en cada repetición."]}},{"id":"3645","name":"single leg bridge with outstretched leg","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/3645-rmEukuS.jpg","gif_url":"videos/3645-rmEukuS.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","מתחו רגל אחת ישר לפניכם.","הפעילו את הישבן והרימו את האגן מהרצפה, ביצירת קו ישר מהברכיים ועד הכתפיים.","החזיקו לרגע בנקודה העליונה, ואז הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Lie on your back with your knees bent and feet flat on the ground.","Extend one leg straight out in front of you.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Вытяните одну ногу прямо перед собой.","Напрягите ягодицы и поднимите бедра от земли, образуя прямую линию от колен до плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende una pierna recta hacia delante.","Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.","Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"0727","name":"single leg calf raise (on a dumbbell)","category":"lower legs","body_part":"lower legs","equipment":"dumbbell","muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/0727-fKZgDEO.jpg","gif_url":"videos/0727-fKZgDEO.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן והחזיקו משקולת יד ביד אחת.","הרימו כף רגל אחת מהרצפה ואזנו על כף הרגל השנייה.","הרימו באיטיות את העקב גבוה ככל האפשר, בעזרת שרירי התאומים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקב באיטיות חזרה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו לרגל השנייה."],"en":["Stand with your feet hip-width apart and hold a dumbbell in one hand.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch to the other leg."],"ru":["Встаньте, ноги на ширине плеч, в одной руке возьмите гантель.","Поднимите одну ногу от земли и балансируйте на другой ноге.","Медленно поднимите пятку как можно выше, задействуя икроножные мышцы.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятку обратно вниз.","Повторите желаемое количество повторений, затем переключитесь на другую ногу."],"es":["Ponte de pie con los pies separados a la altura de la cadera y sujeta una mancuerna en una mano.","Levanta un pie del suelo y mantén el equilibrio sobre el otro pie.","Eleva lentamente el talón lo más alto posible, usando los músculos de la pantorrilla.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo.","Repite el número de repeticiones deseado, luego cambia a la otra pierna."]}},{"id":"0730","name":"single leg platform slide","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","quadriceps"],"target":"hamstrings","image":"images/0730-LNE3wfo.jpg","gif_url":"videos/0730-LNE3wfo.gif","instruction_steps":{"he":["התחילו בעמידה עם כף רגל אחת על משטח או קרש החלקה.","כופפו את הברך מעט והחליקו את כף הרגל שעל המשטח לאחור, במתיחת הרגל.","שמרו על ליבה מופעלת ויציבה זקופה לאורך כל התנועה.","חזרו באיטיות לנקודת ההתחלה בהחלקת כף הרגל חזרה לתנוחה ההתחלתית.","חזרו על התנועה למספר החזרות הרצוי, ואז החליפו רגליים."],"en":["Start by standing with one foot on a platform or slide board.","Bend your knee slightly and slide the foot on the platform backward, extending your leg.","Keep your core engaged and maintain a straight posture throughout the movement.","Slowly return to the starting position by sliding your foot back to the initial position.","Repeat the movement for the desired number of repetitions, then switch legs."],"ru":["Начните с того, что встаньте одной ногой на платформу или слайд-доску.","Слегка согните колено и сдвиньте стопу по платформе назад, вытягивая ногу.","Держите корпус включенным и сохраняйте прямую осанку на протяжении всего движения.","Медленно вернитесь в исходное положение, сдвинув ногу обратно в исходное положение.","Повторите движение желаемое количество повторений, затем поменяйте ногу."],"es":["Comienza de pie con un pie sobre una plataforma o tabla deslizante.","Dobla ligeramente la rodilla y desliza el pie sobre la plataforma hacia atrás, extendiendo la pierna.","Mantén el core activado y conserva una postura recta durante todo el movimiento.","Vuelve lentamente a la posición inicial deslizando el pie de regreso a la posición inicial.","Repite el movimiento el número de repeticiones deseado y luego cambia de pierna."]}},{"id":"1759","name":"single leg squat (pistol) male","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1759-nqs5HGV.jpg","gif_url":"videos/1759-nqs5HGV.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וידיים מתוחות לפניכם.","הרימו את כף רגל ימין מהרצפה ומתחו אותה קדימה.","הורידו באיטיות את הגוף בכיפוף ברך שמאל ודחיפת האגן לאחור.","שמרו על חזה מורם וגב ישר תוך כדי הירידה.","רדו עד שירך שמאל מקבילה לרצפה, או נמוך ככל שנוח לכם.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך עקב שמאל לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Stand with your feet shoulder-width apart and arms extended in front of you.","Lift your right foot off the ground and extend it forward.","Slowly lower your body down by bending your left knee and pushing your hips back.","Keep your chest up and your back straight as you lower yourself down.","Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Встаньте, ноги на ширине плеч, руки вытянуты перед собой.","Поднимите правую ногу от земли и вытяните ее вперед.","Медленно опустите тело вниз, согнув левое колено и отведя бедра назад.","Держите грудь поднятой, а спину прямой, когда опускаетесь вниз.","Опускайтесь до тех пор, пока левое бедро не станет параллельно земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь левой пяткой, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti.","Levanta el pie derecho del suelo y extiéndelo hacia delante.","Baja lentamente el cuerpo doblando la rodilla izquierda y empujando las caderas hacia atrás.","Mantén el pecho elevado y la espalda recta mientras bajas el cuerpo.","Baja hasta que el muslo izquierdo quede paralelo al suelo, o lo más abajo que puedas llegar cómodamente.","Haz una pausa por un momento en la posición baja, luego empuja con el talón izquierdo para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"1489","name":"sissy squat","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"calves","secondary_muscles":["calves","glutes"],"target":"quads","image":"images/1489-xdYPUtE.jpg","gif_url":"videos/1489-xdYPUtE.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וקצות האצבעות של הרגליים פונות מעט החוצה.","אחזו בחפץ יציב לשיווי משקל במידת הצורך.","הורידו את הגוף באיטיות בכיפוף ברכיים והטיה לאחור, תוך שמירה על גו זקוף.","המשיכו לרדת עד שהירכיים מקבילות לרצפה או רחוק ככל שנוח לכם.","עצרו לרגע, ואז דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Hold onto a stable object for balance if needed.","Slowly lower your body by bending your knees and leaning back, keeping your torso upright.","Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","При необходимости держитесь за устойчивый предмет для равновесия.","Медленно опустите тело, согнув колени и откинувшись назад, сохраняя туловище в вертикальном положении.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько далеко, насколько вам будет удобно.","Сделайте паузу на мгновение, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujétate de un objeto estable para mantener el equilibrio si es necesario.","Baja lentamente el cuerpo doblando las rodillas e inclinándote hacia atrás, manteniendo el torso erguido.","Continúa bajando hasta que los muslos queden paralelos al suelo o tan lejos como puedas llegar cómodamente.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0735","name":"sit-up v. 2","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0735-Bn6TXyO.jpg","gif_url":"videos/0735-Bn6TXyO.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו באיטיות את פלג הגוף העליון מהרצפה, בגלגול קדימה עד זווית של 45 מעלות.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3679","name":"sit-up with arms on chest","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3679-6ZCiYWQ.jpg","gif_url":"videos/3679-6ZCiYWQ.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הצליבו את הידיים על החזה.","תוך הפעלת שרירי הבטן, הרימו את פלג הגוף העליון מהרצפה לכיוון הברכיים.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Cross your arms over your chest.","Engaging your abs, lift your upper body off the ground towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Скрестите руки на груди.","Включив пресс, поднимите верхнюю часть тела от земли к коленям.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Cruza los brazos sobre el pecho.","Contrayendo el abdomen, levanta la parte superior del cuerpo del suelo hacia las rodillas.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3361","name":"skater hops","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/3361-zfNHMN9.jpg","gif_url":"videos/3361-zfNHMN9.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","כופפו ברכיים מעט וקפצו ימינה, בנחיתה על כף רגל ימין.","עם הנחיתה, הניפו את רגל שמאל מאחורי רגל ימין וגעו ברצפה עם קצות אצבעות שמאל.","קפצו מיד שמאלה, בנחיתה על כף רגל שמאל.","עם הנחיתה, הניפו את רגל ימין מאחורי רגל שמאל וגעו ברצפה עם קצות אצבעות ימין.","המשיכו להחליף צדדים, בקפיצה ונגיעה ברצפה עם כל רגל.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump to the right, landing on your right foot.","As you land, swing your left leg behind your right leg and tap the ground with your left toes.","Immediately jump to the left, landing on your left foot.","As you land, swing your right leg behind your left leg and tap the ground with your right toes.","Continue alternating sides, jumping and tapping the ground with each leg.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Слегка согните колени и прыгните вправо, приземлившись на правую ногу.","При приземлении заведите левую ногу за правую и коснитесь земли пальцами левой ноги.","Сразу же прыгните влево, приземлившись на левую ногу.","При приземлении заведите правую ногу за левую и коснитесь земли пальцами правой ноги.","Продолжайте чередовать стороны, подпрыгивая и постукивая по земле каждой ногой.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Dobla ligeramente las rodillas y salta hacia la derecha, aterrizando sobre el pie derecho.","Al aterrizar, balancea la pierna izquierda detrás de la pierna derecha y toca el suelo con los dedos del pie izquierdo.","Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo.","Al aterrizar, balancea la pierna derecha detrás de la pierna izquierda y toca el suelo con los dedos del pie derecho.","Continúa alternando los lados, saltando y tocando el suelo con cada pierna.","Repite el número de repeticiones deseado."]}},{"id":"2142","name":"ski ergometer","category":"upper arms","body_part":"upper arms","equipment":"skierg machine","muscle_group":"shoulders","secondary_muscles":["shoulders","forearms"],"target":"triceps","image":"images/2142-vpQaQkH.jpg","gif_url":"videos/2142-vpQaQkH.gif","instruction_steps":{"he":["כווננו את גובה המושב ומשענות הרגליים לתנוחה נוחה.","אחזו בידיות באחיזה עליונה, כפות ידיים כלפי מטה.","שבו זקוף עם כפות רגליים על משענות הרגליים.","מתחו את הידיים ישר לפניכם, עם כיפוף קל במרפקים.","הפעילו את הטרייספס ודחפו את הידיות מטה לכיוון הירכיים.","עצרו לרגע בנקודה התחתונה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and footrests to a comfortable position.","Grasp the handles with an overhand grip, palms facing down.","Sit up straight with your feet flat on the footrests.","Extend your arms straight out in front of you, keeping your elbows slightly bent.","Engage your triceps and push the handles down towards your thighs.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и подножки в удобное положение.","Возьмитесь за рукоятки верхним хватом ладонями вниз.","Сядьте прямо, положив ноги на подножки.","Вытяните руки прямо перед собой, слегка согнув локти.","Задействуйте трицепсы и толкните ручки вниз к бедрам.","Задержитесь на мгновение внизу, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y los apoyapiés a una posición cómoda.","Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo.","Siéntate erguido con los pies planos sobre los apoyapiés.","Extiende los brazos rectos frente a ti, manteniendo los codos ligeramente flexionados.","Activa los tríceps y empuja las asas hacia abajo, hacia los muslos.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3671","name":"ski step","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/3671-5MRH8H2.jpg","gif_url":"videos/3671-5MRH8H2.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","כופפו ברכיים מעט ושמרו על גב ישר.","קפצו ימינה, בנחיתה על כף רגל ימין תוך הנפת רגל שמאל מאחורי רגל ימין.","קפצו מיד שמאלה, בנחיתה על כף רגל שמאל תוך הנפת רגל ימין מאחורי רגל שמאל.","המשיכו לקפוץ מצד לצד לסירוגין, בחיקוי תנועת סקי.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Bend your knees slightly and keep your back straight.","Jump to the right, landing on your right foot while swinging your left leg behind your right leg.","Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.","Continue alternating jumps from side to side, mimicking a skiing motion.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Слегка согните колени и держите спину прямо.","Прыгните вправо, приземлившись на правую ногу и заведя левую ногу за правую.","Немедленно прыгните влево, приземлившись на левую ногу и заведя правую ногу за левую.","Продолжайте попеременные прыжки из стороны в сторону, имитируя движение на лыжах.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Dobla ligeramente las rodillas y mantén la espalda recta.","Salta hacia la derecha, aterrizando sobre el pie derecho mientras balanceas la pierna izquierda detrás de la pierna derecha.","Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo mientras balanceas la pierna derecha detrás de la pierna izquierda.","Continúa alternando los saltos de lado a lado, imitando un movimiento de esquí.","Repite el número de repeticiones deseado."]}},{"id":"3304","name":"skin the cat","category":"back","body_part":"back","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"upper back","image":"images/3304-MSfvriJ.jpg","gif_url":"videos/3304-MSfvriJ.gif","instruction_steps":{"he":["התחילו בתלייה על מוט עם ידיים ישרות לגמרי וגוף רפוי.","הפעילו את הליבה והרימו את הרגליים, בהבאת הברכיים לכיוון החזה.","המשיכו להרים את הרגליים למעלה ומעבר לראש, ותנו לגוף לעבור דרך הידיים.","כשהרגליים מתוחות לגמרי מעל הראש, התחילו להוריד אותן חזרה לכיוון נקודת ההתחלה.","תוך כדי הורדת הרגליים, תנו לגוף לחזור דרך הידיים עד שאתם תלויים שוב עם ידיים ישרות לגמרי.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by hanging from a bar with your arms fully extended and your body relaxed.","Engage your core and lift your legs up, bringing your knees towards your chest.","Continue to lift your legs up and over your head, allowing your body to pass through the arms.","Once your legs are fully extended over your head, begin to lower them back down towards the starting position.","As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.","Repeat for the desired number of repetitions."],"ru":["Начните с висения на перекладине, полностью выпрямив руки и расслабив тело.","Напрягите корпус и поднимите ноги вверх, подтягивая колени к груди.","Продолжайте поднимать ноги вверх и над головой, позволяя телу проходить через руки.","Как только ваши ноги полностью выпрямятся над головой, начните опускать их обратно в исходное положение.","Опуская ноги, позвольте телу пройти обратно через руки, пока вы снова не повиснете с полностью выпрямленными руками.","Повторите необходимое количество повторений."],"es":["Comienza colgándote de una barra con los brazos completamente extendidos y el cuerpo relajado.","Activa el core y levanta las piernas, llevando las rodillas hacia el pecho.","Continúa levantando las piernas por encima de la cabeza, permitiendo que el cuerpo pase entre los brazos.","Una vez que las piernas estén completamente extendidas por encima de la cabeza, comienza a bajarlas de nuevo hacia la posición inicial.","Mientras bajas las piernas, permite que el cuerpo pase de nuevo entre los brazos hasta quedar colgado con los brazos completamente extendidos otra vez.","Repite el número de repeticiones deseado."]}},{"id":"1425","name":"sled 45 degrees one leg press","category":"upper legs","body_part":"upper legs","equipment":"sled machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1425-WWD6FzI.jpg","gif_url":"videos/1425-WWD6FzI.gif","instruction_steps":{"he":["כווננו את מכונת המזחלת לזווית של 45 מעלות.","שבו על מכונת המזחלת כשהגב צמוד לכרית וכפות הרגליים על משטח הרגליים.","הניחו כף רגל אחת על משטח הרגליים ויישרו את הרגל, בדחיפת המזחלת מכם.","כופפו באיטיות את הברך והורידו את המזחלת חזרה לנקודת ההתחלה.","חזרו על התנועה עם הרגל השנייה.","המשיכו להחליף רגליים למספר החזרות הרצוי."],"en":["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the footplate.","Place one foot on the footplate and extend your leg, pushing the sled away from you.","Slowly bend your knee and lower the sled back to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."],"ru":["Отрегулируйте салазки под углом 45 градусов.","Сядьте на салазки, прислонившись спиной к подушке и положив ноги на подножку.","Поставьте одну ногу на подножку и вытяните ногу, отталкивая сани от себя.","Медленно согните колено и опустите сани обратно в исходное положение.","Повторите с другой ногой.","Продолжайте чередовать ноги желаемое количество повторений."],"es":["Ajusta la máquina de trineo a un ángulo de 45 grados.","Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la placa.","Coloca un pie sobre la placa y extiende la pierna, empujando el trineo alejándolo de ti.","Dobla lentamente la rodilla y baja el trineo de vuelta a la posición inicial.","Repite con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."]}},{"id":"0738","name":"sled 45° calf press","category":"lower legs","body_part":"lower legs","equipment":"sled machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/0738-qCNVnaU.jpg","gif_url":"videos/0738-qCNVnaU.gif","instruction_steps":{"he":["כווננו את מכונת המזחלת לזווית של 45 מעלות.","הניחו את כפות הרגליים על משטח המזחלת, כשקצות האצבעות פונות קדימה.","דחפו את משטח המזחלת מכם ביישור הקרסוליים והתאומים.","עצרו לרגע בנקודה העליונה, ואז הורידו את משטח המזחלת באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the sled machine to a 45-degree angle.","Place your feet on the sled platform with your toes pointing forward.","Push the sled platform away from you by extending your ankles and calves.","Pause for a moment at the top, then slowly lower the sled platform back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте салазки под углом 45 градусов.","Поставьте ноги на платформу саней пальцами ног вперед.","Отодвиньте платформу саней от себя, вытянув лодыжки и икроножные мышцы.","Задержитесь на мгновение в верхней точке, затем медленно опустите платформу саней обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de trineo a un ángulo de 45 grados.","Coloca los pies sobre la plataforma del trineo con los dedos de los pies apuntando hacia delante.","Empuja la plataforma del trineo alejándola de ti extendiendo los tobillos y las pantorrillas.","Haz una pausa por un momento en la posición alta, luego baja lentamente la plataforma del trineo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0739","name":"sled 45° leg press","category":"upper legs","body_part":"upper legs","equipment":"sled machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0739-10Z2DXU.jpg","gif_url":"videos/0739-10Z2DXU.gif","instruction_steps":{"he":["כווננו את המושב ומשטח הרגליים של מכונת המזחלת לתנוחה נוחה.","שבו על מכונת המזחלת כשהגב צמוד למשענת וכפות הרגליים ברוחב כתפיים על משטח הרגליים.","אחזו בידיות שבצידי המושב לייצוב.","דחפו את משטח הרגליים מהגוף ביישור הרגליים, תוך שמירה על העקבים על המשטח.","המשיכו לדחוף עד שהרגליים כמעט ישרות לגמרי, אך בלי לנעול את הברכיים.","עצרו לרגע בנקודה העליונה של התנועה, ואז הורידו את משטח הרגליים באיטיות חזרה בכיפוף הברכיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat and footplate of the sled machine to a comfortable position.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Continue pushing until your legs are almost fully extended, but without locking your knees.","Pause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сиденье и подножку салазок в удобное положение.","Сядьте на санки, прислонившись спиной к спинке сиденья и поставив ноги на подножку на ширине плеч.","Возьмитесь за ручки по бокам сиденья для устойчивости.","Отодвиньте подножку от тела, вытянув ноги и удерживая пятки на подножке.","Продолжайте толкать, пока ноги не выпрямятся почти полностью, но не сгибайте колени.","Сделайте паузу на мгновение в верхней части движения, затем медленно опустите подножку обратно к телу, согнув колени.","Повторите необходимое количество повторений."],"es":["Ajusta el asiento y la placa de la máquina de trineo a una posición cómoda.","Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies separados a la altura de los hombros sobre la placa.","Sujeta las asas a los lados del asiento para mayor estabilidad.","Empuja la placa alejándola de tu cuerpo extendiendo las piernas, manteniendo los talones sobre la placa.","Continúa empujando hasta que las piernas estén casi completamente extendidas, pero sin bloquear las rodillas.","Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente la placa de vuelta hacia tu cuerpo doblando las rodillas.","Repite el número de repeticiones deseado."]}},{"id":"1464","name":"sled 45° leg press (back pov)","category":"upper legs","body_part":"upper legs","equipment":"sled machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1464-yn2lLSI.jpg","gif_url":"videos/1464-yn2lLSI.gif","instruction_steps":{"he":["כווננו את מושב מכונת המזחלת כך שהברכיים בזווית של 45 מעלות.","שבו על מכונת המזחלת כשהגב צמוד למשענת וכפות הרגליים ברוחב כתפיים על משטח הרגליים.","אחזו בידיות שבצידי המושב לייצוב.","דחפו את משטח הרגליים מהגוף ביישור הרגליים, תוך שמירה על העקבים על המשטח.","עצרו לרגע בתנוחת היישור המלא.","כופפו באיטיות ברכיים והורידו את משטח הרגליים חזרה לכיוון הגוף, בשליטה על התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat of the sled machine so that your knees are at a 45-degree angle.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards your body, controlling the movement.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сиденье санной машины так, чтобы колени находились под углом 45 градусов.","Сядьте на санки, прислонившись спиной к спинке сиденья и поставив ноги на подножку на ширине плеч.","Возьмитесь за ручки по бокам сиденья для устойчивости.","Отодвиньте подножку от тела, вытянув ноги и удерживая пятки на подножке.","Задержитесь на мгновение в полностью выдвинутом положении.","Медленно согните колени и опустите подножку обратно к телу, контролируя движение.","Повторите необходимое количество повторений."],"es":["Ajusta el asiento de la máquina de trineo de modo que las rodillas queden en un ángulo de 45 grados.","Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies separados a la altura de los hombros sobre la placa.","Sujeta las asas a los lados del asiento para mayor estabilidad.","Empuja la placa alejándola de tu cuerpo extendiendo las piernas, manteniendo los talones sobre la placa.","Haz una pausa por un momento en la posición completamente extendida.","Dobla lentamente las rodillas y baja la placa de vuelta hacia tu cuerpo, controlando el movimiento.","Repite el número de repeticiones deseado."]}},{"id":"1463","name":"sled 45° leg press (side pov)","category":"upper legs","body_part":"upper legs","equipment":"sled machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1463-2Qh2J1e.jpg","gif_url":"videos/1463-2Qh2J1e.gif","instruction_steps":{"he":["כווננו את מושב מכונת המזחלת כך שהברכיים בזווית של 90 מעלות כשכפות הרגליים על משטח הרגליים.","שבו על מכונת המזחלת כשהגב שטוח כנגד המשענת וכפות הרגליים ברוחב כתפיים על משטח הרגליים.","אחזו בידיות שבצידי המושב לייצוב.","דחפו כנגד משטח הרגליים ליישור הרגליים, עד יישורן המלא.","עצרו לרגע בנקודה העליונה, ואז כופפו באיטיות ברכיים והורידו את משטח הרגליים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push against the footplate to extend your legs, straightening them completely.","Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сиденье саней так, чтобы колени находились под углом 90 градусов, когда ступни стоят на подножке.","Сядьте на санки, прижав спину к спинке и поставив ноги на подножку на ширине плеч.","Возьмитесь за ручки по бокам сиденья для устойчивости.","Надавите на подножку, чтобы вытянуть ноги и полностью их выпрямить.","Задержитесь на мгновение в верхней точке, затем медленно согните колени, чтобы опустить подножку обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta el asiento de la máquina de trineo de modo que las rodillas queden en un ángulo de 90 grados cuando los pies estén sobre la placa.","Siéntate en la máquina de trineo con la espalda plana contra el respaldo y los pies separados a la altura de los hombros sobre la placa.","Sujeta las asas a los lados del asiento para mayor estabilidad.","Empuja contra la placa para extender las piernas, estirándolas por completo.","Haz una pausa por un momento en la posición alta, luego dobla lentamente las rodillas para bajar la placa de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0740","name":"sled 45° leg wide press","category":"upper legs","body_part":"upper legs","equipment":"sled machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0740-tj41Nu6.jpg","gif_url":"videos/0740-tj41Nu6.gif","instruction_steps":{"he":["כווננו את מכונת המזחלת לזווית של 45 מעלות.","שבו על מכונת המזחלת כשהגב צמוד לכרית וכפות הרגליים על משטח הרגליים.","מקמו את כפות הרגליים רחב מרוחב הכתפיים.","דחפו כנגד משטח הרגליים ליישור הרגליים והברכיים.","עצרו לרגע בסוף התנועה, ואז כופפו באיטיות ברכיים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the foot platform.","Position your feet wider than shoulder-width apart.","Push against the foot platform to extend your legs and straighten your knees.","Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте салазки под углом 45 градусов.","Сядьте на салазки, прислонившись спиной к подушке и поставив ноги на платформу для ног.","Поставьте ноги шире ширины плеч.","Надавите на платформу для ног, чтобы вытянуть ноги и выпрямить колени.","В конце движения сделайте паузу на мгновение, затем медленно согните колени, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de trineo a un ángulo de 45 grados.","Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma.","Coloca los pies más separados que el ancho de los hombros.","Empuja contra la plataforma para extender las piernas y enderezar las rodillas.","Haz una pausa por un momento al final del movimiento, luego dobla lentamente las rodillas para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1391","name":"sled calf press on leg press","category":"lower legs","body_part":"lower legs","equipment":"sled machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/1391-ykHcWme.jpg","gif_url":"videos/1391-ykHcWme.gif","instruction_steps":{"he":["כווננו את מושב מכונת לחיצת הרגליים כך שהברכיים כפופות מעט כשכפות הרגליים על המזחלת.","הניחו את כפות הרגליים ברוחב כתפיים על המזחלת, כשקצות האצבעות פונות קדימה.","שחררו את ידיות הבטיחות ודחפו את המזחלת מכם ביישור הברכיים והקרסוליים.","עצרו לרגע בנקודה העליונה של התנועה, ואז הורידו את המזחלת באיטיות חזרה בכיפוף ברכיים וקרסוליים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Place your feet shoulder-width apart on the sled, with your toes pointing forward.","Release the safety handles and push the sled away from you by extending your knees and ankles.","Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сиденье тренажера для жима ногами так, чтобы колени были слегка согнуты, когда ноги стоят на санях.","Поставьте ноги на сани на ширине плеч, носки ног направлены вперед.","Отпустите ручки безопасности и оттолкните сани от себя, вытянув колени и лодыжки.","Сделайте паузу на мгновение в верхней точке движения, затем медленно опустите сани обратно вниз, сгибая колени и лодыжки.","Повторите необходимое количество повторений."],"es":["Ajusta el asiento de la máquina de prensa de piernas de modo que las rodillas queden ligeramente flexionadas cuando los pies estén sobre el trineo.","Coloca los pies separados a la altura de los hombros sobre el trineo, con los dedos de los pies apuntando hacia delante.","Suelta las asas de seguridad y empuja el trineo alejándolo de ti extendiendo las rodillas y los tobillos.","Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente el trineo doblando las rodillas y los tobillos.","Repite el número de repeticiones deseado."]}},{"id":"0741","name":"sled closer hack squat","category":"upper legs","body_part":"upper legs","equipment":"sled machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0741-gf3ZjB9.jpg","gif_url":"videos/0741-gf3ZjB9.gif","instruction_steps":{"he":["כווננו את מכונת המזחלת למשקל נוח והתמקמו כשהגב צמוד לכרית.","הניחו את כפות הרגליים ברוחב כתפיים על המשטח, כשקצות האצבעות פונות מעט החוצה.","אחזו בידיות שבצידי המכשיר לייצוב.","הפעילו את הליבה והורידו באיטיות את הגוף בכיפוף ברכיים וירכיים, תוך שמירה על גב ישר.","המשיכו לרדת עד שהירכיים מקבילות לרצפה או מעט מתחת.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים ליישור הרגליים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.","Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Grip the handles on the sides of the machine for stability.","Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сани до удобного веса и расположитесь спиной к подушке.","Поставьте ноги на платформу на ширине плеч, носки слегка направлены наружу.","Возьмитесь за ручки по бокам машины для устойчивости.","Напрягите корпус и медленно опустите тело, сгибая колени и бедра, сохраняя спину прямой.","Продолжайте опускаться до тех пор, пока бедра не станут параллельны земле или немного ниже.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вытянуть ноги и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de trineo a un peso cómodo y colócate con la espalda contra el respaldo.","Coloca los pies separados a la altura de los hombros sobre la plataforma, con los dedos de los pies ligeramente apuntando hacia fuera.","Sujeta las asas a los lados de la máquina para mayor estabilidad.","Activa el core y baja lentamente el cuerpo doblando las rodillas y las caderas, manteniendo la espalda recta.","Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa por un momento en la posición baja, luego empuja con los talones para extender las piernas y volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0742","name":"sled forward angled calf raise","category":"lower legs","body_part":"lower legs","equipment":"sled machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/0742-XDOiFns.jpg","gif_url":"videos/0742-XDOiFns.gif","instruction_steps":{"he":["כווננו את מכונת המזחלת למשקל נוח והתמקמו עליה כשקצות האצבעות של הרגליים על המשטח והעקבים משתלשלים.","הניחו את הידיים על הידיות או צידי המכשיר לתמיכה.","הפעילו את התאומים והרימו באיטיות את העקבים גבוה ככל האפשר, בדחיפה כנגד התנגדות המזחלת.","עצרו לרגע בנקודה העליונה של התנועה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.","Place your hands on the handles or the sides of the machine for support.","Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте салазки до удобного веса и расположитесь на тренажере, положив пальцы ног на платформу и свесив пятки.","Положите руки на ручки или по бокам машины для поддержки.","Включите икроножные мышцы и медленно поднимите пятки как можно выше, преодолевая сопротивление саней.","Сделайте паузу на мгновение в верхней точке движения, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de trineo a un peso cómodo y colócate en la máquina con la punta de los pies sobre la plataforma y los talones colgando.","Coloca las manos en las asas o a los lados de la máquina para apoyarte.","Activa las pantorrillas y eleva lentamente los talones lo más alto posible, empujando contra la resistencia del trineo.","Haz una pausa breve en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0743","name":"sled hack squat","category":"upper legs","body_part":"upper legs","equipment":"sled machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0743-Qa55kX1.jpg","gif_url":"videos/0743-Qa55kX1.gif","instruction_steps":{"he":["כווננו את מכונת המזחלת לתנוחה נוחה לגובה שלכם.","עמדו עם רגליים ברוחב כתפיים על המשטח, קצות האצבעות פונות מעט החוצה.","אחזו בידיות או במוטות לייצוב.","הורידו את הגוף בכיפוף ברכיים וירכיים, תוך שמירה על גב ישר וחזה מורם.","המשיכו לרדת עד שהירכיים מקבילות לרצפה או מעט מתחת.","עצרו לרגע, ואז דחפו דרך העקבים להרמת הגוף חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the sled machine to a comfortable position for your height.","Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Hold onto the handles or bars for stability.","Lower your body by bending your knees and hips, keeping your back straight and chest up.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to raise your body back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте салазки в удобное положение для вашего роста.","Встаньте на платформу, поставив ноги на ширине плеч, носки слегка направлены наружу.","Держитесь за ручки или перекладины для устойчивости.","Опустите тело, согнув колени и бедра, держа спину прямо и грудь вверх.","Продолжайте опускаться до тех пор, пока бедра не станут параллельны земле или немного ниже.","Сделайте паузу на мгновение, затем оттолкнитесь пятками, чтобы поднять тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de trineo a una posición cómoda según tu altura.","Ponte de pie con los pies separados a la altura de los hombros sobre la plataforma, con los dedos de los pies ligeramente apuntando hacia fuera.","Sujétate de las asas o barras para mayor estabilidad.","Baja el cuerpo doblando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.","Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa por un momento, luego empuja con los talones para subir el cuerpo de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2334","name":"sled lying calf press","category":"lower legs","body_part":"lower legs","equipment":"sled machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/2334-g376LuL.jpg","gif_url":"videos/2334-g376LuL.gif","instruction_steps":{"he":["כווננו את מכונת המזחלת למשקל נוח.","שבו על מכונת המזחלת כשהגב צמוד לכרית וכפות הרגליים על המשטח.","הניחו את קצות האצבעות וכריות כפות הרגליים על קצה המשטח, כשהעקבים משתלשלים.","דחפו את המשטח מכם ביישור הקרסוליים, תוך שמירה על ברכיים כפופות מעט.","המשיכו לדחוף עד שהתאומים מכווצים במלואם.","החזיקו את הכיווץ לרגע, ואז הורידו את המשטח באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the sled machine to a comfortable weight.","Sit on the sled machine with your back against the pad and your feet on the platform.","Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.","Push the platform away from you by extending your ankles, keeping your knees slightly bent.","Continue pushing until your calves are fully contracted.","Hold the contraction for a moment, then slowly lower the platform back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сани до удобного веса.","Сядьте на сани, прислонившись спиной к подушке и поставив ноги на платформу.","Поставьте пальцы ног и подушечки стоп на край платформы, свесив пятки.","Оттолкните платформу от себя, вытянув лодыжки и слегка согнув колени.","Продолжайте нажимать до тех пор, пока икроножные мышцы не будут полностью сокращены.","Удерживайте напряжение на мгновение, затем медленно опустите платформу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de trineo a un peso adecuado.","Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma.","Coloca la punta y la almohadilla de los pies en el borde de la plataforma, con los talones colgando.","Empuja la plataforma alejándola de ti extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas.","Continúa empujando hasta que las pantorrillas estén completamente contraídas.","Mantén la contracción por un momento, luego baja lentamente la plataforma de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0744","name":"sled lying squat","category":"upper legs","body_part":"upper legs","equipment":"sled machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0744-9n2149Z.jpg","gif_url":"videos/0744-9n2149Z.gif","instruction_steps":{"he":["כווננו את מכונת המזחלת למשקל נוח.","שכבו על הגב על מכונת המזחלת עם כפות הרגליים על משטח הרגליים.","מקמו את כפות הרגליים ברוחב כתפיים ובזווית קלה החוצה.","אחזו בידיות מכונת המזחלת לייצוב.","הפעילו את שרירי הישבן והליבה.","דחפו דרך העקבים ויישרו רגליים להרמת המזחלת.","הורידו את המזחלת חזרה בכיפוף ברכיים וירכיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the sled machine to a comfortable weight.","Lie on your back on the sled machine with your feet on the footplate.","Position your feet shoulder-width apart and slightly angled outwards.","Grip the handles of the sled machine for stability.","Engage your glutes and core muscles.","Push through your heels and extend your legs to lift the sled.","Lower the sled back down by bending your knees and hips.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сани до удобного веса.","Лягте на спину на санях, положив ноги на подножку.","Поставьте ноги на ширине плеч и слегка разверните их наружу.","Возьмитесь за ручки саней для устойчивости.","Задействуйте ягодицы и мышцы корпуса.","Оттолкнитесь пятками и вытяните ноги, чтобы поднять сани.","Опустите сани обратно вниз, согнув колени и бедра.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina de trineo a un peso adecuado.","Túmbate boca arriba en la máquina de trineo con los pies sobre la placa.","Coloca los pies separados a la altura de los hombros y ligeramente angulados hacia fuera.","Sujeta las asas de la máquina de trineo para mayor estabilidad.","Activa los glúteos y los músculos del core.","Empuja con los talones y extiende las piernas para levantar el trineo.","Baja el trineo de nuevo doblando las rodillas y las caderas.","Repite el número de repeticiones deseado."]}},{"id":"1392","name":"sled one leg calf press on leg press","category":"lower legs","body_part":"lower legs","equipment":"sled machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1392-u0pLNgz.jpg","gif_url":"videos/1392-u0pLNgz.gif","instruction_steps":{"he":["כווננו את מושב מכונת לחיצת הרגליים כך שהברכיים כפופות מעט כשכפות הרגליים על המזחלת.","שבו על המכשיר כשהגב צמוד למשענת וכפות הרגליים על המזחלת, ברוחב כתפיים.","הניחו את קצות האצבעות וכריות כפות הרגליים על המזחלת, כשהעקבים באוויר.","דחפו את המזחלת קדימה ביישור הקרסוליים, תוך שמירה על ברכיים כפופות מעט.","עצרו לרגע בנקודה העליונה, ואז הורידו את המזחלת באיטיות חזרה בכיפוף הקרסוליים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.","Place your toes and the balls of your feet on the sled, keeping your heels off.","Push the sled forward by extending your ankles, keeping your knees slightly bent.","Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сиденье тренажера для жима ногами так, чтобы колени были слегка согнуты, когда ноги стоят на санях.","Сядьте на тренажер спиной к спинке, а ногами на салазках на ширине плеч.","Поставьте пальцы ног и подушечки стоп на салазки, не касаясь пяток.","Толкайте сани вперед, вытянув лодыжки и слегка согнув колени.","Задержитесь на мгновение в верхней точке, затем медленно опустите сани обратно вниз, сгибая лодыжки.","Повторите необходимое количество повторений."],"es":["Ajusta el asiento de la máquina de prensa de piernas de modo que las rodillas queden ligeramente flexionadas cuando los pies estén sobre el trineo.","Siéntate en la máquina con la espalda contra el respaldo y los pies sobre el trineo, separados a la altura de los hombros.","Coloca la punta y la almohadilla de los pies sobre el trineo, manteniendo los talones levantados.","Empuja el trineo hacia delante extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas.","Haz una pausa por un momento en la posición alta, luego baja lentamente el trineo flexionando los tobillos.","Repite el número de repeticiones deseado."]}},{"id":"1496","name":"sledge hammer","category":"waist","body_part":"waist","equipment":"hammer","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"abs","image":"images/1496-REXmfVC.jpg","gif_url":"videos/1496-REXmfVC.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את פטיש הכוח בשתי הידיים.","הפעילו את הליבה ושמרו על גב ישר.","הניפו את פטיש הכוח מטה לכיוון הרצפה, בעזרת כוח הליבה ופלג הגוף העליון.","בתנופה כלפי מטה, סובבו את האגן והעבירו את הכוח לפטיש.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.","Engage your core and keep your back straight.","Swing the sledge hammer down towards the ground, using your core and upper body strength.","As you swing down, pivot your hips and transfer the force to the hammer.","Repeat for the desired number of repetitions."],"ru":["Встаньте, расставив ноги на ширине плеч, и возьмите кувалду обеими руками.","Напрягите корпус и держите спину прямо.","Поверните кувалду вниз к земле, используя силу корпуса и верхней части тела.","Делая мах вниз, разверните бедра и перенесите силу на молот.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta el mazo con ambas manos.","Activa el core y mantén la espalda recta.","Balancea el mazo hacia el suelo, usando la fuerza del core y de la parte superior del cuerpo.","Mientras balanceas hacia abajo, gira las caderas y transfiere la fuerza al mazo.","Repite el número de repeticiones deseado."]}},{"id":"0746","name":"smith back shrug","category":"back","body_part":"back","equipment":"smith machine","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0746-MzNnwx9.jpg","gif_url":"videos/0746-MzNnwx9.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","אחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","שמרו על ידיים ישרות ותנו למוט להשתלשל מול הירכיים.","הרימו את הכתפיים ישר למעלה לכיוון האוזניים, בכיווץ הטרפז בנקודה העליונה.","החזיקו לרגע, ואז הורידו את הכתפיים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and allow the barbell to hang in front of your thighs.","Lift your shoulders straight up towards your ears, squeezing your traps at the top.","Hold for a moment, then lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Возьмите штангу хватом сверху, руки на расстоянии чуть шире плеч.","Держите руки прямо и позвольте штанге висеть перед бедрами.","Поднимите плечи прямо вверх к ушам, сжимая трапеции вверху.","Задержитесь на мгновение, затем опустите плечи обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Mantén los brazos rectos y deja que la barra cuelgue frente a los muslos.","Levanta los hombros directamente hacia las orejas, contrayendo los trapecios en la parte alta.","Mantén la posición por un momento, luego baja los hombros de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0747","name":"smith behind neck press","category":"shoulders","body_part":"shoulders","equipment":"smith machine","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0747-Gpn4ADc.jpg","gif_url":"videos/0747-Gpn4ADc.gif","instruction_steps":{"he":["כווננו את גובה המושב במכונת הסמית' כך שהמוט בגובה הכתפיים.","עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט מהמתקן וצעדו לאחור, בעמידה יציבה.","הורידו את המוט לכיוון העורף, תוך שמירה על מרפקים פונים קדימה.","לחצו את המוט למעלה מעל הראש עד יישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Lower the bar down to the back of your neck, keeping your elbows pointing forward.","Press the bar up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья машины Смита так, чтобы штанга находилась на уровне плеч.","Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Возьмите штангу хватом сверху, на расстоянии чуть шире ширины плеч.","Снимите штангу со стоек и отступите назад, сохраняя устойчивую стойку.","Опустите штангу к задней части шеи, держа локти направленными вперед.","Выжмите штангу вверх над головой, пока руки полностью не выпрямятся.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros.","Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Levanta la barra del soporte y da un paso atrás, manteniendo una postura estable.","Baja la barra hacia la parte de atrás del cuello, manteniendo los codos apuntando hacia delante.","Empuja la barra hacia arriba, por encima de la cabeza, hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0748","name":"smith bench press","category":"chest","body_part":"chest","equipment":"smith machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0748-trqKQv2.jpg","gif_url":"videos/0748-trqKQv2.gif","instruction_steps":{"he":["כווננו את גובה מוט מכונת הסמית' לגובה החזה.","שכבו על הספסל עם כפות רגליים נטועות היטב ברצפה.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו לכיוון החזה, עם מרפקים צמודים לגוף.","עצרו לרגע כשהמוט נוגע בחזה.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the height of the smith machine bar to chest level.","Lie flat on the bench with your feet firmly planted on the ground.","Grip the bar with an overhand grip slightly wider than shoulder-width apart.","Unrack the bar and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar touches your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту грифа машины Смита до уровня груди.","Лягте на скамью, твердо поставив ноги на землю.","Возьмите штангу верхним хватом на расстоянии чуть шире плеч.","Снимите штангу и опустите ее к груди, держа локти прижатыми.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Ajusta la altura de la barra de la máquina Smith a la altura del pecho.","Túmbate en el banco con los pies firmemente apoyados en el suelo.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Suelta la barra del soporte y bájala hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa por un momento cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."]}},{"id":"0749","name":"smith bent knee good morning","category":"upper legs","body_part":"upper legs","equipment":"smith machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0749-1bQkKZK.jpg","gif_url":"videos/0749-1bQkKZK.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים, קצות האצבעות של הרגליים פונות קדימה.","הניחו את המוט על הגב העליון, מונח על שרירי הטרפז.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","הורידו את הגו עד שהוא מקביל לרצפה, עד תחושת מתיחה בירך האחורית.","הפעילו את הישבן והירך האחורית להרמת הגו חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart, toes pointing forward.","Place the barbell across your upper back, resting it on your traps.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to raise your torso back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч, носки направлены вперед.","Положите штангу на верхнюю часть спины, положив ее на трапеции.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Опускайте туловище до тех пор, пока оно не станет параллельно земле, чувствуя растяжение подколенных сухожилий.","Задействуйте ягодицы и мышцы задней поверхности бедра, чтобы поднять туловище обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de los hombros, con los dedos de los pies apuntando hacia delante.","Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.","Activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1359","name":"smith bent over row","category":"back","body_part":"back","equipment":"smith machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1359-ZX9UZmj.jpg","gif_url":"videos/1359-ZX9UZmj.gif","instruction_steps":{"he":["הכינו את מכונת הסמית' עם המוט בגובה האגן.","עמדו מול המוט עם רגליים ברוחב כתפיים.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","אחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","משכו את המוט לכיוון החזה התחתון, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите машину Смита так, чтобы штанга находилась на уровне бедер.","Встаньте лицом к перекладине, ноги на ширине плеч.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Возьмите перекладину хватом сверху, руки на расстоянии чуть шире плеч.","Потяните штангу к нижней части груди, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Configura la máquina Smith con la barra a la altura de la cadera.","Ponte de pie frente a la barra con los pies separados a la altura de los hombros.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Tira de la barra hacia la parte baja del pecho, juntando las escápulas.","Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0750","name":"smith chair squat","category":"upper legs","body_part":"upper legs","equipment":"smith machine","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0750-Gu2rNJd.jpg","gif_url":"videos/0750-Gu2rNJd.gif","instruction_steps":{"he":["כווננו את גובה המוט במכונת הסמית' לתנוחה נוחה.","עמדו עם רגליים ברוחב כתפיים, כפות הרגליים פונות מעט החוצה.","הניחו את המוט על הגב העליון, מונח על שרירי הטרפז.","הפעילו את הליבה ושמרו על חזה מורם תוך הורדת הגוף באיטיות בכיפוף ברכיים וירכיים.","המשיכו לרדת עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","עצרו לרגע, ואז דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the height of the smith machine bar to a comfortable position.","Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell across your upper back, resting it on your traps.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту стержня машины Смита до удобного положения.","Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Положите штангу на верхнюю часть спины, положив ее на трапеции.","Напрягите корпус и держите грудь поднятой, медленно опуская тело, сгибая колени и бедра.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Сделайте паузу на мгновение, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura de la barra de la máquina Smith a una posición cómoda.","Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.","Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo doblando las rodillas y las caderas.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0751","name":"smith close-grip bench press","category":"upper arms","body_part":"upper arms","equipment":"smith machine","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0751-WcHl7ru.jpg","gif_url":"videos/0751-WcHl7ru.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על הספסל עם כפות רגליים על הרצפה.","אחזו במוט באחיזה צרה, מעט צרה מרוחב הכתפיים.","הורידו את המוט לכיוון החזה, עם מרפקים קרובים לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на скамье, поставив ноги на землю.","Возьмите штангу узким хватом, на расстоянии чуть уже ширины плеч.","Опустите штангу к груди, держа локти близко к телу.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en el banco con los pies planos sobre el suelo.","Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.","Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0752","name":"smith deadlift","category":"upper legs","body_part":"upper legs","equipment":"smith machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"target":"glutes","image":"images/0752-UfePqpx.jpg","gif_url":"videos/0752-UfePqpx.gif","instruction_steps":{"he":["הכינו את מכונת הסמית' עם המוט בגובה האגן.","עמדו עם רגליים ברוחב כתפיים, קצות האצבעות של הרגליים פונות מעט החוצה.","כופפו ירכיים וברכיים, תוך שמירה על גב ישר וחזה מורם, ואחזו במוט באחיזה עליונה מעט רחבה מרוחב הכתפיים.","הפעילו את הליבה והרימו את המוט ביישור הירכיים והברכיים, כשהמוט צמוד לגוף.","עמדו זקוף, ביישור מלא של הירכיים והברכיים.","הורידו את המוט חזרה בכיפוף ירכיים וברכיים, תוך שליטה ושמירה על גב ישר.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up the smith machine with the bar at hip height.","Stand with your feet shoulder-width apart, toes pointing slightly outward.","Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.","Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.","Stand up straight, fully extending your hips and knees.","Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.","Repeat for the desired number of repetitions."],"ru":["Установите машину Смита так, чтобы штанга находилась на уровне бедер.","Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","Согните бедра и колени, держа спину прямо и грудь вверх, и возьмитесь за перекладину хватом сверху, чуть шире ширины плеч.","Напрягите корпус и поднимите штангу, вытягивая бедра и колени, удерживая штангу близко к телу.","Встаньте прямо, полностью выпрямив бедра и колени.","Опустите штангу обратно вниз, сгибая бедра и колени, сохраняя контроль и сохраняя спину прямой.","Повторите необходимое количество повторений."],"es":["Configura la máquina Smith con la barra a la altura de la cadera.","Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Dobla las caderas y las rodillas, manteniendo la espalda recta y el pecho elevado, y sujeta la barra con un agarre prono un poco más ancho que los hombros.","Activa el core y levanta la barra extendiendo las caderas y las rodillas, manteniendo la barra cerca del cuerpo.","Ponte de pie erguido, extendiendo por completo las caderas y las rodillas.","Baja la barra de nuevo doblando las caderas y las rodillas, manteniendo el control y la espalda recta.","Repite el número de repeticiones deseado."]}},{"id":"0753","name":"smith decline bench press","category":"chest","body_part":"chest","equipment":"smith machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0753-ETZfAbZ.jpg","gif_url":"videos/0753-ETZfAbZ.gif","instruction_steps":{"he":["כווננו את ספסל השיפוע השלילי לזווית הרצויה.","שכבו על הספסל כשכפות הרגליים מקובעות מתחת לכריות הרגליים.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו באיטיות לכיוון החזה, עם מרפקים צמודים לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте наклонную скамью под желаемым углом.","Лягте на скамью, зафиксировав ноги под подушечками для ног.","Возьмите штангу хватом сверху на расстоянии чуть шире плеч.","Ослабьте штангу и медленно опустите ее к груди, держа локти прижатыми.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta el banco declinado al ángulo deseado.","Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0754","name":"smith decline reverse-grip press","category":"chest","body_part":"chest","equipment":"smith machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0754-MY9P1WA.jpg","gif_url":"videos/0754-MY9P1WA.gif","instruction_steps":{"he":["כווננו את מכונת הסמית' לתנוחת שיפוע שלילי.","שכבו על הספסל כשכפות הרגליים מקובעות מתחת לכריות הרגליים.","אחזו במוט באחיזה הפוכה, ידיים מעט רחבות מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו לכיוון החזה, עם מרפקים צמודים לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте машину Смита в положение опускания.","Лягте на скамью, зафиксировав ноги под подушечками для ног.","Возьмите штангу обратным хватом, руки чуть шире плеч.","Снимите штангу и опустите ее к груди, держа локти прижатыми.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina Smith a una posición declinada.","Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.","Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros.","Suelta la barra y bájala hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1433","name":"smith front squat (clean grip)","category":"upper legs","body_part":"upper legs","equipment":"smith machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/1433-lFhb2Rw.jpg","gif_url":"videos/1433-lFhb2Rw.gif","instruction_steps":{"he":["הכינו את מכונת הסמית' עם המוט בגובה הכתפיים.","עמדו מול המוט עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","צעדו לאחור ומקמו את המוט על הכתפיים הקדמיות, מונח על עצם הבריח והדלתא.","שמרו על חזה מורם, גב ישר וליבה מופעלת.","הורידו את הגוף בכיפוף ברכיים וירכיים, כאילו אתם מתיישבים לאחור על כיסא.","המשיכו לרדת עד שהירכיים מקבילות לרצפה או מעט מתחת.","עצרו לרגע, ואז דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up the smith machine with the barbell at shoulder height.","Stand facing the barbell with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.","Keep your chest up, back straight, and core engaged.","Lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите машину Смита так, чтобы штанга находилась на уровне плеч.","Встаньте лицом к штанге, поставив ноги на ширине плеч.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Сделайте шаг назад и поместите штангу на передние плечи, положив ее на ключицы и дельтоиды.","Держите грудь поднятой, спину прямой и корпус напряженным.","Опустите тело, согнув колени и бедра, как будто садитесь на стул.","Продолжайте опускаться до тех пор, пока бедра не станут параллельны земле или немного ниже.","Сделайте паузу на мгновение, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Configura la máquina Smith con la barra a la altura de los hombros.","Ponte de pie frente a la barra con los pies separados a la altura de los hombros.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Da un paso atrás y coloca la barra sobre los hombros delanteros, apoyándola en la clavícula y los deltoides.","Mantén el pecho elevado, la espalda recta y el core activado.","Baja el cuerpo doblando las rodillas y las caderas, como si te sentaras en una silla.","Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3281","name":"smith full squat","category":"upper legs","body_part":"upper legs","equipment":"smith machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3281-NNoHCEA.jpg","gif_url":"videos/3281-NNoHCEA.gif","instruction_steps":{"he":["הכינו את מכונת הסמית' עם המוט בגובה הכתפיים.","עמדו עם רגליים ברוחב כתפיים, כפות הרגליים פונות מעט החוצה.","היכנסו מתחת למוט ומקמו אותו על הגב העליון, מונח על הטרפז.","אחזו במוט עם ידיים מעט רחבות מרוחב הכתפיים.","הרימו את המוט מהמתקן וצעדו לאחור, בעמידה יציבה.","תוך שמירה על חזה מורם וליבה מופעלת, התחילו את הסקוואט בדחיפת האגן לאחור וכיפוף הברכיים.","הורידו את הגוף עד שהירכיים מקבילות לרצפה, או עד כמה שהגמישות מאפשרת.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up the smith machine with the barbell at shoulder height.","Stand with your feet shoulder-width apart, toes slightly turned out.","Step under the bar and position it across your upper back, resting on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar and take a step back, maintaining a stable stance.","Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите машину Смита так, чтобы штанга находилась на уровне плеч.","Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Встаньте под штангу и расположите ее на верхней части спины, опираясь на трапеции.","Возьмитесь за перекладину, расставив руки чуть шире плеч.","Снимите штангу и сделайте шаг назад, сохраняя устойчивую стойку.","Удерживая грудь поднятой и напряженным корпус, начните приседать, отводя бедра назад и сгибая колени.","Опускайте тело до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько позволяет ваша гибкость.","Задержитесь на мгновение внизу, затем ведите пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Configura la máquina Smith con la barra a la altura de los hombros.","Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios.","Sujeta la barra con las manos un poco más separadas que el ancho de los hombros.","Suelta la barra del soporte y da un paso atrás, manteniendo una postura estable.","Manteniendo el pecho elevado y el core activado, inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas.","Baja el cuerpo hasta que los muslos queden paralelos al suelo, o tan abajo como tu flexibilidad lo permita.","Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0755","name":"smith hack squat","category":"upper legs","body_part":"upper legs","equipment":"smith machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0755-ZuPXtCK.jpg","gif_url":"videos/0755-ZuPXtCK.gif","instruction_steps":{"he":["כווננו את מוט מכונת הסמית' לגובה מתאים לגוף שלכם.","עמדו עם רגליים ברוחב כתפיים, קצות האצבעות פונות מעט החוצה.","התמקמו מתחת למוט, כשהוא מונח על הטרפז העליון והכתפיים.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הפעילו את הליבה ושמרו על חזה מורם תוך הרמת המוט מהמתקן.","צעדו לאחור ומקמו את כפות הרגליים מעט רחב מרוחב הכתפיים.","כופפו ברכיים והורידו את הגוף, תוך שמירה על חזה מורם וגב ישר.","המשיכו לרדת עד שהירכיים מקבילות לרצפה או מעט מתחת.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the barbell on the smith machine to an appropriate height for your body.","Stand with your feet shoulder-width apart, toes slightly pointed outwards.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your chest up as you unrack the barbell.","Take a step back and position your feet slightly wider than shoulder-width apart.","Bend your knees and lower your body down, keeping your chest up and back straight.","Continue descending until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте штангу на машине Смита на высоту, подходящую для вашего тела.","Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","Расположитесь под штангой, положив ее на верхнюю часть трапеции и плеч.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Напрягите корпус и держите грудь поднятой, когда снимаете штангу со стоек.","Сделайте шаг назад и поставьте ноги чуть шире плеч.","Согните колени и опустите тело вниз, держа грудь вверх и спину прямо.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или немного ниже.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la barra de la máquina Smith a una altura adecuada para tu cuerpo.","Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Activa el core y mantén el pecho elevado mientras sueltas la barra del soporte.","Da un paso atrás y coloca los pies un poco más separados que el ancho de los hombros.","Dobla las rodillas y baja el cuerpo, manteniendo el pecho elevado y la espalda recta.","Continúa descendiendo hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0756","name":"smith hip raise","category":"waist","body_part":"waist","equipment":"smith machine","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"abs","image":"images/0756-CqhoytW.jpg","gif_url":"videos/0756-CqhoytW.gif","instruction_steps":{"he":["התמקמו במכונת הסמית' כשהגב צמוד לכרית ורגליים ברוחב כתפיים.","הניחו את הידיים על המוט, מעט רחב מרוחב הכתפיים.","הפעילו את הליבה והישבן, ואז דחפו דרך העקבים להרמת האגן מהרצפה.","המשיכו להרים עד שהגוף יוצר קו ישר מהברכיים ועד הכתפיים.","החזיקו לרגע בנקודה העליונה, ואז הורידו את האגן באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.","Place your hands on the barbell, slightly wider than shoulder-width apart.","Engage your core and glutes, then push through your heels to raise your hips off the ground.","Continue lifting until your body forms a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте на тренажер Смита, прислонившись спиной к подушке и поставив ноги на ширине плеч.","Положите руки на штангу на расстоянии чуть шире ширины плеч.","Задействуйте корпус и ягодицы, затем подтолкните пятки, чтобы поднять бедра от земли.","Продолжайте подниматься до тех пор, пока ваше тело не образует прямую линию от колен до плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Colócate en la máquina Smith con la espalda contra la almohadilla y los pies separados a la altura de los hombros.","Coloca las manos en la barra, un poco más separadas que el ancho de los hombros.","Activa el core y los glúteos, luego empuja con los talones para levantar las caderas del suelo.","Continúa levantando hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0757","name":"smith incline bench press","category":"chest","body_part":"chest","equipment":"smith machine","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0757-5v7KYld.jpg","gif_url":"videos/0757-5v7KYld.gif","instruction_steps":{"he":["כווננו את הספסל לשיפוע של 30–45 מעלות.","שבו על הספסל כשהגב צמוד לכרית וכפות הרגליים נטועות היטב ברצפה.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו באיטיות לכיוון החזה העליון, עם מרפקים צמודים מעט.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the bench to a 30-45 degree incline.","Sit on the bench with your back flat against the pad and feet firmly on the ground.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте наклон скамьи на 30-45 градусов.","Сядьте на скамью, прижав спину к подушке и твердо поставив ноги на землю.","Возьмите штангу хватом сверху на расстоянии чуть шире плеч.","Ослабьте штангу и медленно опустите ее к верхней части груди, слегка прижав локти.","Задержитесь на мгновение в нижней точке, затем поднимите штангу обратно в исходное положение, полностью выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Ajusta el banco a una inclinación de 30-45 grados.","Siéntate en el banco con la espalda plana contra la almohadilla y los pies firmemente apoyados en el suelo.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Suelta la barra y bájala lentamente hacia la parte alta del pecho, manteniendo los codos ligeramente pegados al cuerpo.","Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."]}},{"id":"0758","name":"smith incline reverse-grip press","category":"chest","body_part":"chest","equipment":"smith machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0758-78VqWQK.jpg","gif_url":"videos/0758-78VqWQK.gif","instruction_steps":{"he":["כווננו את מושב מכונת הסמית' לזווית שיפוע נוחה.","שבו על המכשיר כשהגב צמוד לכרית וכפות הרגליים על הרצפה.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו באיטיות לכיוון החזה, עם מרפקים צמודים לגוף.","עצרו לרגע כשהמוט מעט מעל החזה.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat of the smith machine to a comfortable incline angle.","Sit on the machine with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.","Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar is just above your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сиденье машины кузнеца под удобный угол наклона.","Сядьте на тренажер, прислонившись спиной к подушке, а ноги поставьте на землю.","Возьмите перекладину хватом сверху, на расстоянии чуть шире ширины плеч.","Снимите штангу и медленно опустите ее к груди, держа локти прижатыми.","Сделайте паузу на мгновение, когда штанга окажется чуть выше груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Ajusta el asiento de la máquina Smith a un ángulo de inclinación cómodo.","Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo.","Sujeta la barra con un agarre prono un poco más ancho que el ancho de los hombros.","Suelta la barra y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa por un momento cuando la barra esté justo por encima del pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."]}},{"id":"0759","name":"smith incline shoulder raises","category":"chest","body_part":"chest","equipment":"smith machine","muscle_group":"deltoids","secondary_muscles":["deltoids","trapezius"],"target":"serratus anterior","image":"images/0759-ayAHcEm.jpg","gif_url":"videos/0759-ayAHcEm.gif","instruction_steps":{"he":["כווננו את מכונת הסמית' לתנוחת שיפוע חיובי.","עמדו מול המכשיר עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שמרו על גב ישר וליבה מופעלת.","הרימו את המוט למעלה לכיוון התקרה, כשהמרפקים מובילים את התנועה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the smith machine to an incline position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Raise the barbell up towards the ceiling, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите машину Смита в наклонное положение.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмите штангу хватом сверху, на расстоянии чуть шире ширины плеч.","Держите спину прямо и напрягите корпус.","Поднимите штангу вверх к потолку, ведя локтями.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina Smith a una posición inclinada.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Mantén la espalda recta y el core activado.","Eleva la barra hacia el techo, guiando el movimiento con los codos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0760","name":"smith leg press","category":"upper legs","body_part":"upper legs","equipment":"smith machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0760-7zdxRTl.jpg","gif_url":"videos/0760-7zdxRTl.gif","instruction_steps":{"he":["כווננו את המושב ומשטח הרגליים של מכונת הסמית' לתנוחה נוחה.","שבו על המכשיר כשהגב צמוד למשענת וכפות הרגליים ברוחב כתפיים על משטח הרגליים.","אחזו בידיות או בצידי המכשיר לייצוב.","דחפו את משטח הרגליים מכם ביישור הרגליים, תוך שמירה על הגב צמוד למשענת.","עצרו לרגע בתנוחת היישור המלא.","כופפו באיטיות ברכיים והורידו את משטח הרגליים חזרה אליכם, לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat and footplate of the smith machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grasp the handles or sides of the machine for stability.","Push the footplate away from you by extending your legs, keeping your back against the backrest.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards you, returning to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сиденье и подножку кузнечного станка в удобное положение.","Сядьте на тренажер спиной к спинке и поставьте ноги на подножку на ширине плеч.","Возьмитесь за ручки или боковые стороны машины для устойчивости.","Отодвиньте подножку от себя, вытянув ноги и прижимая спину к спинке.","Задержитесь на мгновение в полностью выдвинутом положении.","Медленно согните колени и опустите подножку обратно на себя, возвращаясь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta el asiento y la placa para los pies de la máquina Smith a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies.","Sujeta las asas o los lados de la máquina para mayor estabilidad.","Empuja la placa alejándola de ti extendiendo las piernas, manteniendo la espalda contra el respaldo.","Haz una pausa por un momento en la posición completamente extendida.","Dobla lentamente las rodillas y baja la placa de vuelta hacia ti, regresando a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1434","name":"smith low bar squat","category":"upper legs","body_part":"upper legs","equipment":"smith machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1434-RGLscZM.jpg","gif_url":"videos/1434-RGLscZM.gif","instruction_steps":{"he":["הכינו את מכונת הסמית' עם המוט בגובה שמאפשר להניח אותו בנוחות על הגב העליון.","עמדו עם רגליים ברוחב כתפיים, קצות האצבעות מסובבות מעט החוצה.","היכנסו מתחת למוט ומקמו אותו על הגב העליון, מונח על הטרפז.","אחזו במוט עם ידיים מעט רחבות מרוחב הכתפיים.","הרימו את המוט מהמתקן ביישור הרגליים וצעדו לאחור מהמתקן.","קחו נשימה עמוקה והדקו את הליבה.","התחילו את הסקוואט בדחיפת האגן לאחור וכיפוף הברכיים.","הורידו את הגוף עד שהירכיים מקבילות לרצפה או מעט מתחת.","שמרו על חזה מורם וגב ישר לאורך כל התנועה.","דחפו דרך העקבים כדי לחזור לעמידה, תוך יישור הירכיים והברכיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.","Stand with your feet shoulder-width apart, toes slightly turned outwards.","Step under the bar and position it across your upper back, resting it on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar by straightening your legs and stepping back from the rack.","Take a deep breath and brace your core.","Initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your chest up and your back straight throughout the movement.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"ru":["Установите тренажер Смита со штангой на высоте, позволяющей удобно расположить ее на верхней части спины.","Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Встаньте под штангу и положите ее на верхнюю часть спины, опираясь на трапеции.","Возьмитесь за перекладину, расставив руки чуть шире плеч.","Снимите штангу, выпрямив ноги и отойдя от стойки.","Сделайте глубокий вдох и напрягите мышцы кора.","Начните приседание, отведя бедра назад и согнув колени.","Опускайте тело до тех пор, пока бедра не станут параллельны земле или немного ниже.","На протяжении всего движения держите грудь поднятой, а спину прямой.","Протолкните пятки, чтобы встать обратно, выпрямляя бедра и колени.","Повторите необходимое количество повторений."],"es":["Configura la máquina Smith con la barra a una altura que te permita apoyarla cómodamente en la parte alta de la espalda.","Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios.","Sujeta la barra con las manos un poco más separadas que el ancho de los hombros.","Suelta la barra del soporte estirando las piernas y dando un paso atrás para alejarte del soporte.","Respira profundamente y tensa el core.","Inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas.","Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.","Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."]}},{"id":"1683","name":"smith machine bicep curl","category":"upper arms","body_part":"upper arms","equipment":"smith machine","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1683-zILLZ98.jpg","gif_url":"videos/1683-zILLZ98.gif","instruction_steps":{"he":["כווננו את גובה מוט מכונת הסמית' לגובה המותניים.","עמדו מול מכונת הסמית' עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה תחתונה, ידיים מעט רחבות מרוחב הכתפיים.","שמרו על מרפקים צמודים לגוף וזרועות עליונות ללא תזוזה.","נשפו וכופפו את המוט למעלה לכיוון הכתפיים, בכיווץ הבייספס.","עצרו לרגע בנקודה העליונה של התנועה, תוך כיווץ הבייספס.","שאפו והורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the height of the smith machine bar to be at waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту грифа машины Смита так, чтобы она находилась на уровне талии.","Встаньте лицом к машине Смита, поставив ноги на ширине плеч.","Возьмите перекладину хватом снизу, руки на расстоянии чуть шире плеч.","Держите локти близко к бокам, а плечи неподвижно.","Выдохните и поднимите штангу к плечам, напрягая бицепсы.","Задержитесь на мгновение в верхней точке движения, напрягая бицепсы.","Вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura de la barra de la máquina Smith a la altura de la cintura.","Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos.","Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1625","name":"smith machine decline close grip bench press","category":"upper arms","body_part":"upper arms","equipment":"smith machine","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1625-yB9SvIF.jpg","gif_url":"videos/1625-yB9SvIF.gif","instruction_steps":{"he":["כווננו את הספסל במכונת הסמית' לתנוחת שיפוע שלילי.","שכבו על הספסל עם כפות רגליים נטועות היטב על הרצפה.","אחזו במוט באחיזה צרה, מעט צרה מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו באיטיות לכיוון החזה, עם מרפקים קרובים לגוף.","עצרו לרגע כשהמוט מעט מעל החזה.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the bench on the smith machine to a decline position.","Lie down on the bench with your feet firmly planted on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Установите скамью на машине Смита в наклонное положение.","Лягте на скамью, твердо поставив ноги на землю.","Возьмите штангу узким хватом, на расстоянии чуть уже ширины плеч.","Снимите штангу и медленно опустите ее к груди, держа локти близко к телу.","Сделайте паузу на мгновение, когда штанга окажется чуть выше груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Ajusta el banco de la máquina Smith a una posición declinada.","Túmbate en el banco con los pies firmemente apoyados en el suelo.","Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra esté justo encima del pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1752","name":"smith machine incline tricep extension","category":"upper arms","body_part":"upper arms","equipment":"smith machine","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1752-o8aOcrz.jpg","gif_url":"videos/1752-o8aOcrz.gif","instruction_steps":{"he":["כווננו את מושב מכונת הסמית' כך שהמוט בגובה הכתפיים.","שבו על הספסל כשהגב צמוד לכרית וכפות הרגליים על הרצפה.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","מתחו את הידיים לגמרי, בהרמת המוט מהמתקן והחזקתו ישר מעל החזה.","הורידו את המוט באיטיות לכיוון המצח, תוך שמירה על מרפקים קרובים לראש.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat of the smith machine so that the bar is at shoulder height.","Sit on the bench with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.","Lower the bar slowly towards your forehead, keeping your elbows close to your head.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте сиденье машины кузнеца так, чтобы штанга находилась на уровне плеч.","Сядьте на скамью, прислонившись спиной к подушке, а ноги поставьте на землю.","Возьмите штангу хватом сверху, на расстоянии чуть шире ширины плеч.","Полностью выпрямите руки, подняв штангу со стойки и удерживая ее прямо над грудью.","Медленно опустите штангу ко лбу, держа локти близко к голове.","Сделайте небольшую паузу в нижней точке, затем поднимите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta el asiento de la máquina Smith de modo que la barra quede a la altura de los hombros.","Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Extiende los brazos por completo, levantando la barra del soporte y sosteniéndola directamente sobre el pecho.","Baja la barra lentamente hacia la frente, manteniendo los codos cerca de la cabeza.","Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1626","name":"smith machine reverse decline close grip bench press","category":"chest","body_part":"chest","equipment":"smith machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1626-QyO6Uma.jpg","gif_url":"videos/1626-QyO6Uma.gif","instruction_steps":{"he":["כווננו את מכונת הסמית' לתנוחת שיפוע שלילי.","שכבו על הספסל כשכפות הרגליים מקובעות מתחת לכריות הרגליים.","אחזו במוט באחיזה צרה, מעט צרה מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו באיטיות לכיוון החזה, עם מרפקים צמודים לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте машину Смита в положение опускания.","Лягте на скамью, зафиксировав ноги под подушечками для ног.","Возьмите штангу узким хватом, на расстоянии чуть уже ширины плеч.","Ослабьте штангу и медленно опустите ее к груди, держа локти прижатыми.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la máquina Smith a una posición declinada.","Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.","Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0761","name":"smith narrow row","category":"back","body_part":"back","equipment":"smith machine","muscle_group":"biceps","secondary_muscles":["biceps","rear deltoids"],"target":"upper back","image":"images/0761-JGKowMS.jpg","gif_url":"videos/0761-JGKowMS.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר עם כפות רגליים על הרצפה.","אחזו בידיות באחיזה עליונה, מעט צרה מרוחב הכתפיים.","שמרו על גב ישר וחזה מורם תוך משיכת הידיות לכיוון הגוף, בכיווץ השכמות זו לזו.","עצרו לרגע בשיא התנועה, ואז שחררו באיטיות את הידיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your feet flat on the floor.","Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.","Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на тренажере, поставив ноги на пол.","Возьмитесь за ручки хватом сверху, на расстоянии чуть уже ширины плеч.","Держите спину прямо и грудь вверх, подтягивая рукоятки к телу, сжимая лопатки вместе.","Задержитесь на мгновение на пике движения, затем медленно отпустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con los pies planos sobre el suelo.","Sujeta las asas con un agarre prono, un poco más estrecho que el ancho de los hombros.","Mantén la espalda recta y el pecho elevado mientras tiras de las asas hacia tu cuerpo, juntando las escápulas.","Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1360","name":"smith one arm row","category":"back","body_part":"back","equipment":"smith machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1360-Q4DSJPC.jpg","gif_url":"videos/1360-Q4DSJPC.gif","instruction_steps":{"he":["כווננו את גובה מוט מכונת הסמית' לגובה המותניים.","עמדו מול מכונת הסמית' עם רגליים ברוחב כתפיים.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","אחזו במוט ביד אחת באחיזה עליונה, כשכף היד כלפי מטה.","שמרו על מרפק קרוב לגוף ומשכו את המוט לכיוון המותניים, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו ליד השנייה."],"en":["Adjust the height of the smith machine bar to waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with one hand using an overhand grip, with your palm facing down.","Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"ru":["Отрегулируйте высоту грифа машины Смита до уровня талии.","Встаньте лицом к машине Смита, поставив ноги на ширине плеч.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Возьмите перекладину одной рукой хватом сверху, ладонью вниз.","Держите локоть близко к телу и потяните штангу к талии, сжимая лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения, затем медленно опустите штангу обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"es":["Ajusta la altura de la barra de la máquina Smith a la altura de la cintura.","Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Sujeta la barra con una mano usando un agarre prono, con la palma hacia abajo.","Mantén el codo cerca del cuerpo y tira de la barra hacia la cintura, juntando las escápulas.","Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."]}},{"id":"1393","name":"smith one leg floor calf raise","category":"lower legs","body_part":"lower legs","equipment":"smith machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1393-9GXrTE6.jpg","gif_url":"videos/1393-9GXrTE6.gif","instruction_steps":{"he":["התמקמו על הרצפה מתחת למוט מכונת הסמית', עם הגב למכשיר.","הניחו את כריות כפות הרגליים על משטח מוגבה, כמו פלטת משקל או בלוק.","מקמו את מוט מכונת הסמית' על השוקיים התחתונות, מעט מעל הקרסוליים.","אחזו במוט עם הידיים לייצוב.","הרימו את העקבים מהרצפה ביישור הקרסוליים, בהרמת הגוף.","עצרו בנקודה העליונה של התנועה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Position yourself on the floor under the smith machine bar, facing away from the machine.","Place the balls of your feet on a raised surface, such as a weight plate or block.","Position the smith machine bar across your lower legs, just above your ankles.","Hold onto the bar with your hands for stability.","Raise your heels off the ground by extending your ankles, lifting your body up.","Pause at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Расположитесь на полу под стойкой станка Смита лицом от станка.","Поставьте подушечки стоп на возвышенную поверхность, например, на блин или блок.","Расположите гриф тренажера Смита на голенях чуть выше лодыжек.","Держитесь за перекладину руками для устойчивости.","Поднимите пятки от земли, вытянув лодыжки и подняв тело вверх.","Сделайте паузу в верхней точке движения, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Colócate en el suelo debajo de la barra de la máquina Smith, mirando en dirección contraria a la máquina.","Coloca la punta de los pies sobre una superficie elevada, como un disco de peso o un bloque.","Coloca la barra de la máquina Smith sobre la parte baja de las piernas, justo por encima de los tobillos.","Sujeta la barra con las manos para mayor estabilidad.","Levanta los talones del suelo extendiendo los tobillos, elevando el cuerpo hacia arriba.","Haz una pausa en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0762","name":"smith rear delt row","category":"shoulders","body_part":"shoulders","equipment":"smith machine","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/0762-nFUwqG6.jpg","gif_url":"videos/0762-nFUwqG6.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו על המכשיר כשהחזה צמוד לכרית וכפות הרגליים על הרצפה.","אחזו בידיות באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","שמרו על גב ישר וליבה מופעלת תוך משיכת הידיות לכיוון החזה, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה של התנועה, ואז שחררו באיטיות את הידיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на машине так, чтобы грудь опиралась на подушку, а ступни стояли на земле.","Возьмитесь за ручки хватом сверху, на расстоянии чуть шире плеч.","Держите спину прямо, а корпус напряженным, подтягивая рукоятки к груди, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке движения, затем медленно отпустите рукоятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y el core activado mientras tiras de las asas hacia el pecho, juntando las escápulas.","Haz una pausa por un momento en la parte alta del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0763","name":"smith reverse calf raises","category":"lower legs","body_part":"lower legs","equipment":"smith machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/0763-ywaNfuh.jpg","gif_url":"videos/0763-ywaNfuh.gif","instruction_steps":{"he":["כווננו את מוט מכונת הסמית' לגובה מעט מתחת לכתפיים.","עמדו מול המוט עם רגליים ברוחב אגן וקצות האצבעות פונות קדימה.","הניחו את כריות כפות הרגליים על קצה מדרגה או משטח, כשהעקבים משתלשלים.","אחזו במוט לתמיכה, תוך שמירה על גב ישר וליבה מופעלת.","הרימו את העקבים גבוה ככל האפשר, בהעברת משקל הגוף לכריות כפות הרגליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the smith machine bar to a height just below your shoulders.","Stand facing the bar with your feet hip-width apart and toes pointing forward.","Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Hold onto the bar for support, keeping your back straight and core engaged.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте гриф машины Смита на высоту чуть ниже плеч.","Встаньте лицом к перекладине, ноги на ширине плеч, носки направлены вперед.","Поставьте подушечки стоп на край ступеньки или платформы, свесив пятки.","Держитесь за перекладину для поддержки, сохраняя спину прямой и напряженный корпус.","Поднимите пятки как можно выше, перенеся вес тела на подушечки стоп.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros.","Ponte de pie frente a la barra con los pies separados a la altura de la cadera y los dedos de los pies apuntando hacia delante.","Coloca la punta de los pies en el borde de un escalón o plataforma, con los talones colgando.","Sujétate de la barra para apoyarte, manteniendo la espalda recta y el core activado.","Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1394","name":"smith reverse calf raises","category":"lower legs","body_part":"lower legs","equipment":"smith machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1394-Lsqrgh4.jpg","gif_url":"videos/1394-Lsqrgh4.gif","instruction_steps":{"he":["כווננו את מוט מכונת הסמית' לגובה מעט מתחת לכתפיים.","עמדו מול המוט עם רגליים ברוחב אגן וקצות האצבעות פונות קדימה.","הניחו את כריות כפות הרגליים על קצה מדרגה או משטח, כשהעקבים משתלשלים.","אחזו במוט לתמיכה.","הרימו את העקבים גבוה ככל האפשר, בהרמת הגוף על קצות האצבעות.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the smith machine bar to a height just below your shoulders.","Stand facing the bar with your feet hip-width apart and toes pointing forward.","Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Hold onto the bar for support.","Raise your heels as high as possible, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте гриф машины Смита на высоту чуть ниже плеч.","Встаньте лицом к перекладине, ноги на ширине плеч, носки направлены вперед.","Поставьте подушечки стоп на край ступеньки или платформы, свесив пятки.","Держитесь за перекладину для поддержки.","Поднимите пятки как можно выше, поднимая тело на носки.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros.","Ponte de pie frente a la barra con los pies separados a la altura de la cadera y los dedos de los pies apuntando hacia delante.","Coloca la punta de los pies en el borde de un escalón o plataforma, con los talones colgando.","Sujétate de la barra para apoyarte.","Levanta los talones lo más alto posible, elevando el cuerpo sobre la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1361","name":"smith reverse grip bent over row","category":"back","body_part":"back","equipment":"smith machine","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1361-aaxA3cm.jpg","gif_url":"videos/1361-aaxA3cm.gif","instruction_steps":{"he":["הכינו את מכונת הסמית' עם המוט בגובה האגן.","עמדו מול המוט עם רגליים ברוחב כתפיים.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","אחזו במוט באחיזה תחתונה, ידיים ברוחב כתפיים.","משכו את המוט לכיוון החזה התחתון, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите машину Смита так, чтобы штанга находилась на уровне бедер.","Встаньте лицом к перекладине, ноги на ширине плеч.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Возьмитесь за перекладину хватом снизу, руки на ширине плеч.","Потяните штангу к нижней части груди, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Configura la máquina Smith con la barra a la altura de la cadera.","Ponte de pie frente a la barra con los pies separados a la altura de los hombros.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Tira de la barra hacia la parte baja del pecho, juntando las escápulas.","Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0764","name":"smith reverse-grip press","category":"chest","body_part":"chest","equipment":"smith machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0764-zK8Fu1W.jpg","gif_url":"videos/0764-zK8Fu1W.gif","instruction_steps":{"he":["כווננו את גובה מוט מכונת הסמית' לגובה החזה.","עמדו מול המוט עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","צעדו לאחור והתמקמו עם כיפוף קל בברכיים.","שמרו על חזה מורם וליבה מופעלת לאורך כל התרגיל.","הורידו את המוט לכיוון החזה, עם מרפקים צמודים לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את המוט חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the height of the smith machine bar to chest level.","Stand facing the bar with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step back and position yourself with a slight bend in your knees.","Keep your chest up and core engaged throughout the exercise.","Lower the bar towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту грифа машины Смита до уровня груди.","Встаньте лицом к перекладине, ноги на ширине плеч.","Возьмите перекладину хватом сверху, руки на расстоянии чуть шире плеч.","Сделайте шаг назад и расположитесь, слегка согнув колени.","Держите грудь поднятой и напряженным корпусом на протяжении всего упражнения.","Опустите штангу к груди, держа локти прижатыми.","Сделайте небольшую паузу в нижней точке, затем поднимите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura de la barra de la máquina Smith a la altura del pecho.","Ponte de pie frente a la barra con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Da un paso atrás y colócate con una ligera flexión en las rodillas.","Mantén el pecho elevado y el core activado durante todo el ejercicio.","Baja la barra hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1395","name":"smith seated one leg calf raise","category":"lower legs","body_part":"lower legs","equipment":"smith machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1395-0S75mYG.jpg","gif_url":"videos/1395-0S75mYG.gif","instruction_steps":{"he":["שבו על המכשיר כשהגב צמוד לכרית וכפות הרגליים על משענת הרגליים.","הניחו רגל אחת על משענת הרגליים והשאירו את הרגל השנייה מחוץ למשענת.","בעזרת שרירי התאומים, הרימו את העקב גבוה ככל האפשר.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקב באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגליים וחזרו על התרגיל."],"en":["Sit on the machine with your back against the pad and your feet on the footrest.","Place one leg on the footrest and keep the other leg off the footrest.","Using your calf muscles, raise your heel as high as possible.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"ru":["Сядьте на тренажер спиной к подушке, а ногами на подножке.","Поставьте одну ногу на подставку для ног, а другую ногу держите подальше от подставки для ног.","Используя икроножные мышцы, поднимите пятку как можно выше.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятку обратно в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу и повторите."],"es":["Siéntate en la máquina con la espalda contra la almohadilla y los pies sobre el apoyapiés.","Coloca una pierna sobre el apoyapiés y mantén la otra pierna fuera de él.","Eleva el talón lo más alto posible, usando los músculos de la pantorrilla.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."]}},{"id":"0765","name":"smith seated shoulder press","category":"shoulders","body_part":"shoulders","equipment":"smith machine","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0765-xUwnBMT.jpg","gif_url":"videos/0765-xUwnBMT.gif","instruction_steps":{"he":["כווננו את גובה המושב כך שהידיות בגובה הכתפיים.","שבו על המכשיר כשהגב צמוד לכרית וכפות הרגליים על הרצפה.","אחזו בידיות באחיזה עליונה והרימו אותן מהתמיכות, עד יישור מלא של הידיים.","הורידו את הידיות לגובה הכתפיים, תוך שמירה על מרפקים כפופים מעט.","לחצו את הידיות מעל הראש עד יישור מלא של הידיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיות באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height so that the handles are at shoulder level.","Sit on the machine with your back against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.","Lower the handles down to shoulder level, keeping your elbows slightly bent.","Press the handles up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья так, чтобы ручки находились на уровне плеч.","Сядьте на тренажер, прислонившись спиной к подушке, а ноги поставьте на пол.","Возьмитесь за рукоятки верхним хватом и поднимите их с опор, полностью выпрямив руки.","Опустите рукоятки до уровня плеч, держа локти слегка согнутыми.","Поднимите ручки над головой, пока руки полностью не выпрямятся.","Задержитесь на мгновение в верхней точке, затем медленно опустите ручки обратно до уровня плеч.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento de modo que las asas queden a la altura de los hombros.","Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo.","Sujeta las asas con un agarre prono y levántalas de los soportes, extendiendo los brazos por completo.","Baja las asas hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.","Empuja las asas hacia arriba, por encima de la cabeza, hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento en la parte alta y luego baja lentamente las agarraderas de vuelta a la altura del hombro.","Repite el número de repeticiones deseado."]}},{"id":"1426","name":"smith seated wrist curl","category":"lower arms","body_part":"lower arms","equipment":"smith machine","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/1426-B6dAO1t.jpg","gif_url":"videos/1426-B6dAO1t.gif","instruction_steps":{"he":["שבו על ספסל מול מכונת סמית' עם כפות רגליים על הרצפה.","אחזו במוט באחיזה תחתונה, ידיים ברוחב כתפיים.","השעינו את האמות על הירכיים, ותנו לשורשי כף היד להשתלשל.","גלגלו באיטיות את שורשי כף היד כלפי מעלה, והביאו את המוט לכיוון האמות.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench in front of a Smith machine with your feet flat on the ground.","Grasp the barbell with an underhand grip, hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью перед тренажером Смита, поставив ноги на землю.","Возьмите штангу хватом снизу, руки на ширине плеч.","Положите предплечья на бедра, позволяя запястьям свисать.","Медленно поднимите запястья вверх, поднося штангу к предплечьям.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco frente a una máquina Smith con los pies planos sobre el suelo.","Sujeta la barra con un agarre supino, con las manos separadas a la altura de los hombros.","Apoya los antebrazos sobre los muslos, permitiendo que las muñecas cuelguen.","Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia los antebrazos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0766","name":"smith shoulder press","category":"shoulders","body_part":"shoulders","equipment":"smith machine","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0766-903mzG8.jpg","gif_url":"videos/0766-903mzG8.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו במכונת הסמית' עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט מהמתקן ומקמו אותו בגובה הכתפיים, עם מרפקים כפופים וכפות ידיים פונות קדימה.","לחצו את המוט כלפי מעלה עד יישור מלא של הידיים מעל הראש.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.","Press the bar upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the bar back down to shoulder level.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь на машине Смита, поставив ноги на ширине плеч.","Возьмите штангу хватом сверху, на расстоянии чуть шире ширины плеч.","Снимите штангу со стойки и поместите ее на уровне плеч, согнув локти и повернув ладони вперед.","Выжимайте штангу вверх до тех пор, пока руки полностью не выпрямятся над головой.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно до уровня плеч.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate en la máquina Smith con los pies separados a la altura de los hombros.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Levanta la barra del soporte y colócala a la altura de los hombros, con los codos flexionados y las palmas hacia delante.","Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"0767","name":"smith shrug","category":"back","body_part":"back","equipment":"smith machine","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0767-OUQ0ZyW.jpg","gif_url":"videos/0767-OUQ0ZyW.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","אחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","שמרו על ידיים ישרות וכתפיים רפויות.","הרימו את הכתפיים למעלה לכיוון האוזניים, בכיווץ הטרפז בנקודה העליונה.","החזיקו לרגע, ואז הורידו את הכתפיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and your shoulders relaxed.","Lift your shoulders up towards your ears, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Возьмите штангу хватом сверху, руки на расстоянии чуть шире плеч.","Держите руки прямыми, а плечи расслабленными.","Поднимите плечи к ушам, сжимая трапеции вверху.","Задержитесь на мгновение, затем медленно опустите плечи обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Mantén los brazos rectos y los hombros relajados.","Levanta los hombros hacia las orejas, contrayendo los trapecios en la parte alta.","Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0768","name":"smith single leg split squat","category":"upper legs","body_part":"upper legs","equipment":"smith machine","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"quads","image":"images/0768-wWFspEi.jpg","gif_url":"videos/0768-wWFspEi.gif","instruction_steps":{"he":["עמדו מול מכונת הסמית' עם רגליים ברוחב כתפיים.","הניחו כף רגל אחת מאחוריכם על ספסל או מדרגה, כשקצות האצבעות פונות קדימה.","אחזו במוט מכונת הסמית' לייצוב.","כופפו את הברך הקדמית והורידו את הגוף לעמדת מספריים, תוך שמירה על גב ישר.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקב הקדמי לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Stand in front of the smith machine with your feet shoulder-width apart.","Place one foot behind you on a bench or step, with your toes pointing forward.","Hold onto the smith machine bar for stability.","Bend your front knee and lower your body down into a lunge position, keeping your back straight.","Pause for a moment at the bottom, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Встаньте перед машиной Смита, поставив ноги на ширине плеч.","Поставьте одну ногу позади себя на скамью или ступеньку так, чтобы пальцы ног были направлены вперед.","Держитесь за стержень машины Смита для устойчивости.","Согните переднее колено и опустите тело в положение выпада, сохраняя спину прямой.","Задержитесь на мгновение внизу, затем оттолкнитесь передней пяткой, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.","Coloca un pie detrás de ti sobre un banco o escalón, con los dedos del pie apuntando hacia delante.","Sujétate de la barra de la máquina Smith para mayor estabilidad.","Dobla la rodilla delantera y baja el cuerpo hacia una posición de zancada, manteniendo la espalda recta.","Haz una pausa por un momento en la posición baja, luego empuja con el talón delantero para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"0769","name":"smith sprint lunge","category":"upper legs","body_part":"upper legs","equipment":"smith machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0769-HsjbB1z.jpg","gif_url":"videos/0769-HsjbB1z.gif","instruction_steps":{"he":["הכינו את מכונת הסמית' עם המוט בגובה האגן.","עמדו עם הגב למכשיר, רגליים ברוחב כתפיים.","צעדו לאחור עם רגל ימין והניחו אותה על המוט, כשגב כף הרגל מונח עליו.","כופפו את ברך שמאל והורידו את הגוף לעמדת מספריים, תוך שמירה על גב ישר.","דחפו דרך עקב שמאל כדי לחזור לנקודת ההתחלה.","חזרו על התנועה בצד השני, בצעד לאחור עם רגל שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Set up the smith machine with the barbell at hip height.","Stand facing away from the machine with your feet shoulder-width apart.","Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.","Bend your left knee and lower your body into a lunge position, keeping your back straight.","Push through your left heel to return to the starting position.","Repeat on the other side, stepping back with your left foot.","Continue alternating sides for the desired number of repetitions."],"ru":["Установите машину Смита так, чтобы штанга находилась на уровне бедер.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Сделайте шаг назад правой ногой и поставьте ее на штангу, положив верхнюю часть стопы на перекладину.","Согните левое колено и опустите тело в положение выпада, сохраняя спину прямой.","Оттолкнитесь левой пяткой, чтобы вернуться в исходное положение.","Повторите то же самое в другую сторону, отступив левой ногой назад.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Configura la máquina Smith con la barra a la altura de la cadera.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Da un paso atrás con el pie derecho y colócalo sobre la barra, apoyando la parte superior del pie en ella.","Dobla la rodilla izquierda y baja el cuerpo hacia una posición de zancada, manteniendo la espalda recta.","Empuja con el talón izquierdo para volver a la posición inicial.","Repite del otro lado, dando un paso hacia atrás con el pie izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0770","name":"smith squat","category":"upper legs","body_part":"upper legs","equipment":"smith machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0770-jFtipLl.jpg","gif_url":"videos/0770-jFtipLl.gif","instruction_steps":{"he":["הכינו את מכונת הסמית' עם המוט בגובה מתאים לסקוואט שלכם.","עמדו עם רגליים ברוחב כתפיים, כפות הרגליים פונות מעט החוצה.","התמקמו מתחת למוט, כשהוא מונח על הטרפז העליון והכתפיים.","אחזו במוט באחיזה רחבה, מעט רחבה מרוחב הכתפיים.","הפעילו את הליבה והרימו את המוט מהמתקן, בצעד לאחור להתרחקות מהמתקן.","תוך שמירה על חזה מורם וגב ישר, התחילו את הסקוואט בכיפוף הירכיים והברכיים.","הורידו את הגוף עד שהירכיים מקבילות לרצפה או מעט מתחת.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up the smith machine with the barbell at an appropriate height for your squat.","Stand with your feet shoulder-width apart, toes slightly turned out.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grip the barbell with a wide grip, slightly wider than shoulder-width apart.","Engage your core and unrack the barbell, stepping back to clear the rack.","Keeping your chest up and back straight, initiate the squat by bending at the hips and knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите машину Смита со штангой на высоте, подходящей для вашего приседания.","Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Расположитесь под штангой, положив ее на верхнюю часть трапеции и плеч.","Возьмите штангу широким хватом, на расстоянии чуть шире ширины плеч.","Напрягите корпус и снимите штангу со стойки, отступив назад, чтобы освободить стойку.","Подняв грудь и спину прямо, начните приседать, сгибая бедра и колени.","Опускайте тело до тех пор, пока бедра не станут параллельны земле или немного ниже.","Задержитесь на мгновение внизу, затем ведите пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Configura la máquina Smith con la barra a una altura adecuada para tu sentadilla.","Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros.","Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.","Activa el core y suelta la barra del soporte, dando un paso atrás para alejarte del soporte.","Manteniendo el pecho elevado y la espalda recta, inicia la sentadilla doblando las caderas y las rodillas.","Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0771","name":"smith standing back wrist curl","category":"lower arms","body_part":"lower arms","equipment":"smith machine","muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"forearms","image":"images/0771-hfmQ0Tz.jpg","gif_url":"videos/0771-hfmQ0Tz.gif","instruction_steps":{"he":["עמדו מול מכונת הסמית' עם רגליים ברוחב כתפיים.","אחזו במוט באחיזה עליונה, ידיים ברוחב כתפיים.","שמרו על גב ישר ומרפקים צמודים לגוף.","כופפו באיטיות את שורשי כף היד כלפי מעלה, בהבאת המוט לכיוון הגוף.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand facing the smith machine with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, hands shoulder-width apart.","Keep your back straight and your elbows close to your body.","Slowly curl your wrists upwards, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте лицом к машине Смита, поставив ноги на ширине плеч.","Возьмите штангу хватом сверху, руки на ширине плеч.","Держите спину прямо, а локти близко к телу.","Медленно поднимите запястья вверх, приближая штангу к телу.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros.","Mantén la espalda recta y los codos cerca del cuerpo.","Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0772","name":"smith standing behind head military press","category":"shoulders","body_part":"shoulders","equipment":"smith machine","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0772-ht8xDrP.jpg","gif_url":"videos/0772-ht8xDrP.gif","instruction_steps":{"he":["כווננו את גובה המושב במכונת הסמית' כך שהמוט בגובה הכתפיים.","עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט מהמתקן וצעדו לאחור, בעמידה יציבה.","מקמו את המוט מאחורי הראש, מונח על הטרפז העליון.","שמרו על ליבה מופעלת וחזה מורם לאורך כל התרגיל.","לחצו את המוט מעל הראש ביישור הידיים, עד יישורן המלא.","עצרו קצרות בנקודה העליונה של התנועה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Position the bar behind your head, resting on your upper traps.","Keep your core engaged and your chest lifted throughout the exercise.","Press the bar overhead by extending your arms, fully straightening them.","Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья машины Смита так, чтобы штанга находилась на уровне плеч.","Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Возьмите штангу хватом сверху, на расстоянии чуть шире ширины плеч.","Снимите штангу со стоек и отступите назад, сохраняя устойчивую стойку.","Расположите штангу за головой, опираясь на верхние трапеции.","На протяжении всего упражнения держите корпус напряженным, а грудь приподнятой.","Нажмите на штангу над головой, вытянув руки и полностью выпрямив их.","Сделайте короткую паузу в верхней части движения, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros.","Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Levanta la barra del soporte y da un paso atrás, manteniendo una postura estable.","Coloca la barra detrás de la cabeza, apoyándola en la parte alta de los trapecios.","Mantén el core activado y el pecho elevado durante todo el ejercicio.","Empuja la barra por encima de la cabeza extendiendo los brazos, estirándolos por completo.","Haz una breve pausa en la parte alta del movimiento, luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0773","name":"smith standing leg calf raise","category":"lower legs","body_part":"lower legs","equipment":"smith machine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/0773-6MaEjVA.jpg","gif_url":"videos/0773-6MaEjVA.gif","instruction_steps":{"he":["כווננו את מוט מכונת הסמית' לגובה שמאפשר לעמוד עם כפות רגליים על הרצפה והכתפיים מתחת למוט.","התמקמו מתחת למוט עם רגליים ברוחב כתפיים וקצות האצבעות פונות קדימה.","הניחו את הידיים על המוט לייצוב.","הפעילו את התאומים והרימו באיטיות את העקבים מהרצפה, בהרמת הגוף על קצות האצבעות.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.","Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.","Place your hands on the bar for stability.","Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте гриф машины Смита на такую ​​высоту, чтобы вы могли стоять, поставив ноги на землю, а плечи - под гриф.","Встаньте под перекладиной, ноги на ширине плеч, носки ног направлены вперед.","Положите руки на перекладину для устойчивости.","Включите икроножные мышцы и медленно поднимите пятки от земли, поднимая тело на носки.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la barra de la máquina Smith a una altura que te permita estar de pie con los pies planos sobre el suelo y los hombros debajo de la barra.","Colócate debajo de la barra con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante.","Coloca las manos sobre la barra para mayor estabilidad.","Activa las pantorrillas y levanta lentamente los talones del suelo, elevando el cuerpo sobre la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0774","name":"smith standing military press","category":"shoulders","body_part":"shoulders","equipment":"smith machine","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0774-jjUPrze.jpg","gif_url":"videos/0774-jjUPrze.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הרימו את המוט מהמתקן והורידו אותו לגובה הכתפיים, עם כפות ידיים פונות קדימה.","לחצו את המוט כלפי מעלה עד יישור מלא של הידיים מעל הראש.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לגובה הכתפיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.","Press the barbell upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Снимите штангу со стойки и опустите ее на уровень плеч, ладонями вперед.","Нажмите штангу вверх, пока руки полностью не выпрямятся над головой.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно до уровня плеч.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y bájala hasta la altura de los hombros, con las palmas hacia delante.","Empuja la barra hacia arriba hasta que tus brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa de un momento en la parte superior y luego baja lentamente la barra de nuevo hasta la altura de los hombros.","Repite el número de repeticiones deseado."]}},{"id":"3142","name":"smith sumo squat","category":"upper legs","body_part":"upper legs","equipment":"smith machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3142-dzz6BiV.jpg","gif_url":"videos/3142-dzz6BiV.gif","instruction_steps":{"he":["הכינו את מכונת הסמית' עם המוט בגובה האגן.","עמדו עם רגליים רחבות מרוחב הכתפיים, קצות האצבעות של הרגליים פונות החוצה.","התמקמו מתחת למוט, כשהוא מונח על הגב העליון והכתפיים.","הפעילו את הליבה ושמרו על חזה מורם תוך הורדת הגוף לעמדת סקוואט, בדחיפת האגן לאחור וכיפוף הברכיים.","רדו עד שהירכיים מקבילות לרצפה, או נמוך ככל שנוח לכם.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up the smith machine with the barbell at hip height.","Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Position yourself under the barbell, resting it on your upper back and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите машину Смита так, чтобы штанга находилась на уровне бедер.","Встаньте, расставив ноги шире плеч, носки наружу.","Расположитесь под штангой, положив ее на верхнюю часть спины и плечи.","Напрягите корпус и держите грудь поднятой, опуская тело в присед, отводя бедра назад и сгибая колени.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Configura la máquina Smith con la barra a la altura de la cadera.","Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera.","Colócate debajo de la barra, apoyándola sobre la parte superior de la espalda y los hombros.","Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1396","name":"smith toe raise","category":"lower legs","body_part":"lower legs","equipment":"smith machine","muscle_group":"ankles","secondary_muscles":["ankles","shins"],"target":"calves","image":"images/1396-Y4QlY8z.jpg","gif_url":"videos/1396-Y4QlY8z.gif","instruction_steps":{"he":["כווננו את מוט מכונת הסמית' לגובה שמאפשר לכם לעמוד בנוחות עם כפות רגליים על הרצפה.","התמקמו מתחת למוט כשהכתפיים ישר מתחתיו ורגליים ברוחב כתפיים.","הניחו את כריות כפות הרגליים על משטח מוגבה או פלטות משקל, כשהעקבים משתלשלים מעבר לקצה.","אחזו במוט באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","הפעילו את הליבה ושמרו על גב ישר לאורך כל התרגיל.","הרימו באיטיות את העקבים גבוה ככל האפשר, בהעברת משקל הגוף לכריות כפות הרגליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.","Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.","Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your back straight throughout the exercise.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте планку машины Смита на такую ​​высоту, чтобы вам было удобно стоять, поставив ноги на землю.","Встаньте под перекладиной так, чтобы плечи находились прямо под ней, а ноги были на ширине плеч.","Поставьте подушечки стоп на приподнятую платформу или блины так, чтобы пятки свисали с края.","Возьмите штангу хватом сверху, на расстоянии чуть шире ширины плеч.","Напрягите корпус и держите спину прямо на протяжении всего упражнения.","Медленно поднимите пятки как можно выше, перенося вес тела на подушечки стоп.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la barra de la máquina Smith a una altura que te permita pararte cómodamente con los pies planos sobre el suelo.","Colócate debajo de la barra con los hombros justo debajo de ella y los pies separados a la altura de los hombros.","Coloca la planta de los pies sobre una plataforma elevada o discos de peso, dejando los talones colgando fuera del borde.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Activa el core y mantén la espalda recta durante todo el ejercicio.","Levanta lentamente los talones lo más alto posible, elevando el peso de tu cuerpo sobre la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0775","name":"smith upright row","category":"shoulders","body_part":"shoulders","equipment":"smith machine","muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0775-1DN3iz4.jpg","gif_url":"videos/0775-1DN3iz4.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, מול מכונת הסמית'.","אחזו במוט באחיזה עליונה, ידיים מעט רחבות מרוחב הכתפיים.","שמרו על גב ישר וליבה מופעלת.","משכו את המוט למעלה לכיוון הסנטר, כשהמרפקים מובילים את התנועה.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, facing the smith machine.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell up towards your chin, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, лицом к машине Смита.","Возьмите штангу хватом сверху, руки на расстоянии чуть шире плеч.","Держите спину прямо, а корпус напряженным.","Подтяните штангу к подбородку, ведя локтями.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, de frente a la máquina Smith.","Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y el core activado.","Tira de la barra hacia tu barbilla, guiando el movimiento con los codos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1308","name":"smith wide grip bench press","category":"chest","body_part":"chest","equipment":"smith machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1308-zoOvPcx.jpg","gif_url":"videos/1308-zoOvPcx.gif","instruction_steps":{"he":["כווננו את הספסל לתנוחה נוחה במכונת הסמית'.","שכבו על הספסל עם כפות רגליים על הרצפה.","אחזו במוט באחיזה רחבה, מעט רחבה מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו באיטיות לכיוון החזה, עם מרפקים פתוחים לצדדים.","עצרו לרגע כשהמוט נוגע בחזה.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the bench to a comfortable position on the smith machine.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Установите скамью в удобное положение на машине кузнеца.","Лягте на скамью, положив ноги на землю.","Возьмите штангу широким хватом, на расстоянии чуть шире ширины плеч.","Снимите штангу и медленно опустите ее к груди, держа локти в стороны.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Ajusta el banco a una posición cómoda en la máquina Smith.","Túmbate en el banco con los pies planos sobre el suelo.","Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.","Desengancha la barra y bájala lentamente hacia tu pecho, manteniendo los codos hacia afuera a los costados.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1309","name":"smith wide grip decline bench press","category":"chest","body_part":"chest","equipment":"smith machine","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1309-wi2H9QX.jpg","gif_url":"videos/1309-wi2H9QX.gif","instruction_steps":{"he":["כווננו את ספסל השיפוע השלילי לזווית הרצויה.","שכבו על הספסל כשכפות הרגליים מקובעות מתחת לכריות הרגליים.","אחזו במוט באחיזה רחבה, מעט רחבה מרוחב הכתפיים.","שחררו את המוט מהמתקן והורידו אותו באיטיות לכיוון החזה, עם מרפקים פונים החוצה.","עצרו לרגע כשהמוט נוגע בחזה.","דחפו את המוט חזרה למעלה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте наклонную скамью под желаемым углом.","Лягте на скамью, зафиксировав ноги под подушечками для ног.","Возьмите штангу широким хватом, на расстоянии чуть шире ширины плеч.","Снимите штангу и медленно опустите ее к груди, держа локти направленными наружу.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Ajusta el banco declinado al ángulo deseado.","Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.","Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.","Desengancha la barra y bájala lentamente hacia tu pecho, manteniendo los codos apuntando hacia afuera.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0776","name":"snatch pull","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes","calves"],"target":"quads","image":"images/0776-dG5Smob.jpg","gif_url":"videos/0776-dG5Smob.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים כשהמוט על הרצפה מולכם.","כופפו ברכיים והטו את הגו מהירכיים לירידה לעמדת סקוואט, ואחזו במוט באחיזה עליונה.","שמרו על גב ישר וחזה מורם תוך דחיפה דרך העקבים להרמת המוט מהרצפה, ביישור הירכיים והברכיים.","כשהמוט מגיע לגובה האגן, משכו אותו למעלה בפיצוץ, במשיכת כתפיים והבאת המרפקים גבוה ולצדדים.","כשהמוט מגיע לנקודה הגבוהה ביותר, רדו מתחתיו במהירות, במשיכת עצמכם לעמדת סקוואט עמוק.","תפסו את המוט מעל הראש עם ידיים ישרות לגמרי וברכיים כפופות.","עמדו ביישור הירכיים והברכיים, תוך שמירה על המוט מעל הראש.","הורידו את המוט חזרה לנקודת ההתחלה בהיפוך התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.","Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.","Catch the barbell overhead with your arms fully extended and your knees bent.","Stand up by extending your hips and knees, keeping the barbell overhead.","Lower the barbell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, положите штангу на землю перед собой.","Согните колени и наклоните бедра, чтобы опуститься в присед, удерживая штангу хватом сверху.","Держите спину прямо и грудь вверх, поднимая пятки, чтобы поднять штангу с земли, вытягивая бедра и колени.","Когда штанга достигнет уровня бедер, резко потяните ее вверх, пожимая плечами и отводя локти высоко и в стороны.","Когда штанга достигнет своей высшей точки, быстро опуститесь под нее, приняв положение глубокого приседа.","Возьмите штангу над головой, полностью выпрямив руки и согнув колени.","Встаньте, вытянув бедра и колени, удерживая штангу над головой.","Опустите штангу обратно в исходное положение, выполняя движение в обратном направлении.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.","Flexiona las rodillas y dobla las caderas para bajar a una posición de sentadilla, agarrando la barra con un agarre prono.","Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas.","Cuando la barra llegue a la altura de la cadera, tira de ella hacia arriba de forma explosiva, encogiendo los hombros y llevando los codos altos y hacia los lados.","Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, llevando tu cuerpo a una posición de sentadilla profunda.","Recibe la barra por encima de la cabeza con los brazos completamente extendidos y las rodillas flexionadas.","Ponte de pie extendiendo las caderas y las rodillas, manteniendo la barra por encima de la cabeza.","Baja la barra de nuevo a la posición inicial invirtiendo el movimiento.","Repite el número de repeticiones deseado."]}},{"id":"0777","name":"spell caster","category":"waist","body_part":"waist","equipment":"dumbbell","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0777-p9cCe2r.jpg","gif_url":"videos/0777-p9cCe2r.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד ביד אחת.","כופפו ברכיים מעט והטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר.","מתחו את היד עם המשקולת לכיוון כף הרגל הנגדית, תוך סיבוב הגו.","חזרו לנקודת ההתחלה וחזרו על התנועה בצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Bend your knees slightly and hinge forward at the waist, keeping your back straight.","Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, в одной руке возьмите гантель.","Слегка согните колени и наклонитесь вперед в талии, сохраняя спину прямой.","Вытяните руку с гантелью к противоположной ноге, вращая при этом туловище.","Вернитесь в исходное положение и повторите то же самое в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta.","Extiende el brazo con la mancuerna hacia el pie opuesto, rotando el torso mientras lo haces.","Regresa a la posición inicial y repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1362","name":"sphinx","category":"back","body_part":"back","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1362-DIVyqrU.jpg","gif_url":"videos/1362-DIVyqrU.gif","instruction_steps":{"he":["שכבו על הבטן על הרצפה עם האמות שטוחות על הרצפה, מרפקים ישר מתחת לכתפיים.","הפעילו את הליבה והרימו את החזה מהרצפה, תוך שמירה על האמות וקצות האצבעות של הרגליים על הרצפה.","החזיקו את התנוחה כמה שניות, תוך הקפדה על צוואר בתנוחה ניטרלית.","הורידו את החזה באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.","Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.","Hold this position for a few seconds, making sure to keep your neck in a neutral position.","Slowly lower your chest back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте лицом вниз на пол, положив предплечья на пол, локти прямо под плечами.","Напрягите корпус и поднимите грудь от земли, удерживая предплечья и пальцы ног на полу.","Удерживайте это положение несколько секунд, следя за тем, чтобы шея оставалась в нейтральном положении.","Медленно опустите грудь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo en el suelo con los antebrazos planos sobre el piso y los codos justo debajo de los hombros.","Activa el core y levanta el pecho del suelo, manteniendo los antebrazos y los dedos de los pies en el piso.","Mantén esta posición durante unos segundos, asegurándote de mantener el cuello en una posición neutral.","Baja lentamente el pecho de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0778","name":"spider crawl push up","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"core","secondary_muscles":["core","chest","shoulders"],"target":"glutes","image":"images/0778-P9GFBME.jpg","gif_url":"videos/0778-P9GFBME.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים מעט רחבות מרוחב הכתפיים ורגליים צמודות.","הביאו את ברך ימין לכיוון מרפק ימין, כשהיא באוויר.","תוך החזרת ברך ימין לאחור, הורידו בו-זמנית את הגוף לכיוון הרצפה בכיפוף המרפקים.","דחפו חזרה למעלה לנקודת ההתחלה וחזרו עם ברך שמאל לכיוון מרפק שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Bring your right knee towards your right elbow, keeping it off the ground.","As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.","Push back up to the starting position and repeat with your left knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."],"ru":["Начните с позиции для отжиманий, поставив руки чуть шире плеч, а ноги вместе.","Поднесите правое колено к правому локтю, не отрывая его от земли.","Возвращая правое колено назад, одновременно опустите тело к земле, сгибая локти.","Вернитесь в исходное положение и повторите, подтянув левое колено к левому локтю.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Lleva la rodilla derecha hacia el codo derecho, manteniéndola elevada del suelo.","Mientras llevas la rodilla derecha hacia atrás, baja simultáneamente el cuerpo hacia el suelo flexionando los codos.","Empuja de nuevo hacia arriba a la posición inicial y repite llevando la rodilla izquierda hacia el codo izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"1363","name":"spine stretch","category":"back","body_part":"back","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"spine","image":"images/1363-JbC2iaV.jpg","gif_url":"videos/1363-JbC2iaV.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים ישרות לפניכם.","הניחו את הידיים על הרצפה מאחוריכם, אצבעות פונות לכיוון הגוף.","הפעילו את הליבה והיטו את הגוף לאחור באיטיות, תוך שמירה על גב ישר.","המשיכו להטות לאחור עד לתחושת מתיחה בעמוד השדרה.","החזיקו את המתיחה כמה שניות, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the ground with your legs extended in front of you.","Place your hands on the ground behind you, fingers pointing towards your body.","Engage your core and slowly lean back, keeping your back straight.","Continue leaning back until you feel a stretch in your spine.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на пол, вытянув ноги перед собой.","Положите руки на землю позади себя, пальцы направлены к телу.","Напрягите корпус и медленно откиньтесь назад, сохраняя спину прямой.","Продолжайте откидываться назад, пока не почувствуете растяжение в позвоночнике.","Удерживайте растяжку несколько секунд, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti.","Coloca las manos en el suelo detrás de ti, con los dedos apuntando hacia tu cuerpo.","Activa el core e inclínate lentamente hacia atrás, manteniendo la espalda recta.","Sigue inclinándote hacia atrás hasta que sientas un estiramiento en la columna.","Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2329","name":"spine twist","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/2329-2jl9K55.jpg","gif_url":"videos/2329-2jl9K55.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים ישרות לפניכם.","כופפו ברכיים והניחו את כפות הרגליים על הרצפה, ברוחב אגן.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","הפעילו את שרירי הבטן וסובבו באיטיות את הגו ימינה, בהבאת מרפק ימין לכיוון ברך שמאל.","עצרו לרגע בסוף הסיבוב, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על הסיבוב לצד שמאל, בהבאת מרפק שמאל לכיוון ברך ימין.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Sit on the ground with your legs extended in front of you.","Bend your knees and place your feet flat on the ground, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side, bringing your left elbow towards your right knee.","Continue alternating sides for the desired number of repetitions."],"ru":["Сядьте на пол, вытянув ноги перед собой.","Согните колени и поставьте ступни на землю, на ширине плеч.","Положите руки за голову локтями наружу.","Напрягите пресс и медленно поверните туловище вправо, приближая правый локоть к левому колену.","Сделайте небольшую паузу в конце поворота, затем медленно вернитесь в исходное положение.","Повторите поворот в левую сторону, поднеся левый локоть к правому колену.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti.","Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activa el abdomen y gira lentamente el torso hacia la derecha, llevando el codo derecho hacia la rodilla izquierda.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite el giro hacia el lado izquierdo, llevando el codo izquierdo hacia la rodilla derecha.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"2368","name":"split squats","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/2368-9E25EOx.jpg","gif_url":"videos/2368-9E25EOx.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","צעדו קדימה עם כף רגל אחת והניחו אותה כחצי מטר לפני כף הרגל השנייה.","הורידו את הגוף בכיפוף ברכיים וירכיים, תוך שמירה על גב ישר.","המשיכו לרדת עד שהירך הקדמית מקבילה לרצפה והברך האחורית מרחפת מעט מעל הרצפה.","עצרו לרגע, ואז דחפו דרך העקב הקדמי לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגליים וחזרו על התרגיל."],"en":["Stand with your feet shoulder-width apart.","Take a step forward with one foot and place it about two feet in front of the other foot.","Lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"ru":["Встаньте, ноги на ширине плеч.","Сделайте шаг вперед одной ногой и поставьте ее примерно на два фута перед другой ногой.","Опустите тело, согнув колени и бедра, сохраняя спину прямой.","Продолжайте опускаться до тех пор, пока переднее бедро не станет параллельно земле, а заднее колено не окажется прямо над землей.","Сделайте паузу на мгновение, затем оттолкнитесь передней пяткой, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу и повторите."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con un pie y colócalo aproximadamente a dos pies de distancia por delante del otro pie.","Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta.","Sigue bajando hasta que el muslo delantero quede paralelo al suelo y la rodilla trasera quede justo por encima del suelo.","Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."]}},{"id":"0786","name":"squat jerk","category":"upper legs","body_part":"upper legs","equipment":"barbell","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves","core"],"target":"quads","image":"images/0786-IMRsOCn.jpg","gif_url":"videos/0786-IMRsOCn.gif","instruction_steps":{"he":["התחילו עם המוט מונח על הכתפיים, עם רגליים ברוחב כתפיים.","הורידו את הגוף לעמדת סקוואט, תוך שמירה על חזה מורם וברכיים בקו אחד עם קצות האצבעות.","בהגיעכם לנקודה התחתונה של הסקוואט, דחפו בפיצוץ דרך הרגליים ולחצו את המוט מעל הראש.","כשהמוט מגיע לשיאו, רדו במהירות לעמדת ספליט, עם כף רגל אחת קדימה ואחת לאחור.","תפסו את המוט מעל הראש עם ידיים ישרות לגמרי והברך האחורית נוגעת קלות ברצפה.","עמדו מעמדת הספליט, בהחזרת כפות הרגליים יחד.","הורידו את המוט חזרה לכתפיים וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Start with the barbell resting on your shoulders, with your feet shoulder-width apart.","Lower your body into a squat position, keeping your chest up and your knees tracking over your toes.","As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.","As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.","Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.","Stand up from the split position, bringing your feet back together.","Lower the barbell back to your shoulders and repeat for the desired number of repetitions."],"ru":["Начните с того, что штанга лежит на плечах, ноги на ширине плеч.","Опустите тело в положение приседа, удерживая грудь поднятой, а колени касаясь пальцев ног.","Достигнув нижней точки приседа, резко разведите ноги и вытолкните штангу над головой.","Когда штанга достигнет пика, быстро опуститесь в положение шпагата, поставив одну ногу вперед, а другую назад.","Возьмите штангу над головой, полностью вытянув руки и слегка касаясь земли задним коленом.","Встаньте из позиции шпагата, снова сводя ноги вместе.","Опустите штангу обратно на плечи и повторите желаемое количество повторений."],"es":["Comienza con la barra apoyada sobre los hombros y los pies separados a la altura de los hombros.","Baja el cuerpo a una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con la punta de los pies.","Al llegar al punto más bajo de la sentadilla, empuja con fuerza a través de las piernas y eleva la barra por encima de la cabeza.","Cuando la barra alcance su punto más alto, baja rápidamente a una posición de zancada dividida, con un pie adelante y otro atrás.","Recibe la barra por encima de la cabeza con los brazos completamente extendidos y la rodilla trasera tocando ligeramente el suelo.","Ponte de pie desde la posición dividida, juntando de nuevo los pies.","Baja la barra de nuevo a los hombros y repite el número de repeticiones deseado."]}},{"id":"1705","name":"squat on bosu ball","category":"upper legs","body_part":"upper legs","equipment":"bosu ball","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/1705-T2fA5Ir.jpg","gif_url":"videos/1705-T2fA5Ir.gif","instruction_steps":{"he":["הניחו את כדור הבוסו על הרצפה כשהצד השטוח כלפי מעלה.","עמדו עם רגליים ברוחב כתפיים והתמקמו על כדור הבוסו.","הורידו את הגוף בכיפוף ברכיים וירכיים, כאילו אתם מתיישבים לאחור על כיסא.","שמרו על חזה מורם והמשקל בעקבים.","רדו עד שהירכיים מקבילות לרצפה.","עצרו לרגע, ואז דחפו דרך העקבים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Place the bosu ball on the ground with the flat side up.","Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.","Lower your body down by bending your knees and hips, as if sitting back into a chair.","Keep your chest up and your weight on your heels.","Lower yourself until your thighs are parallel to the ground.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Положите босу-шар на землю плоской стороной вверх.","Встаньте, расставив ноги на ширине плеч, и расположитесь на вершине мяча босу.","Опустите тело вниз, согнув колени и бедра, как будто садитесь на стул.","Держите грудь поднятой, а вес тела перенесите на пятки.","Опускайтесь до тех пор, пока бедра не станут параллельны земле.","Сделайте паузу на мгновение, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca el bosu en el suelo con el lado plano hacia arriba.","Ponte de pie con los pies separados a la altura de los hombros y colócate encima del bosu.","Baja el cuerpo flexionando las rodillas y las caderas, como si te sentaras en una silla.","Mantén el pecho elevado y el peso en los talones.","Baja hasta que los muslos queden paralelos al suelo.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1685","name":"squat to overhead reach","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","core"],"target":"quads","image":"images/1685-QChZi3x.jpg","gif_url":"videos/1685-QChZi3x.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וכפות רגליים פונות מעט החוצה.","הורידו את הגוף לעמדת סקוואט בכיפוף ברכיים ודחיפת האגן לאחור.","בעלייה מהסקוואט, מתחו את הידיים מעל הראש, לכיוון התקרה.","חזרו לנקודת ההתחלה בהורדת הידיים וכיפוף הברכיים לירידה לסקוואט נוסף.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body down into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, extend your arms overhead, reaching towards the ceiling.","Return to the starting position by lowering your arms and bending your knees to squat down again.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка развернув пальцы ног.","Опустите тело в положение приседа, согнув колени и отведя бедра назад.","Поднявшись из приседа, вытяните руки над головой, дотягиваясь до потолка.","Вернитесь в исходное положение, опустив руки и согнув колени, чтобы снова присесть.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Mientras te levantas de la sentadilla, extiende los brazos por encima de la cabeza, alcanzando hacia el techo.","Vuelve a la posición inicial bajando los brazos y flexionando las rodillas para volver a hacer la sentadilla.","Repite el número de repeticiones deseado."]}},{"id":"1686","name":"squat to overhead reach with twist","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","core"],"target":"quads","image":"images/1686-5BZHW9s.jpg","gif_url":"videos/1686-5BZHW9s.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וכפות רגליים פונות מעט החוצה.","רדו לסקוואט בכיפוף ברכיים ודחיפת האגן לאחור.","בעלייה מהסקוואט, הרימו את הידיים מעל הראש וסובבו את הגו לצד אחד.","חזרו לנקודת ההתחלה וחזרו על הסקוואט, הפעם בסיבוב הגו לצד הנגדי.","המשיכו להחליף צדדים בכל חזרת סקוואט."],"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, raise your arms overhead and twist your torso to one side.","Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.","Continue alternating sides with each squat repetition."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка развернув пальцы ног.","Опустите тело в присед, согнув колени и отведя бедра назад.","Поднявшись из приседа, поднимите руки над головой и поверните туловище в одну сторону.","Вернитесь в исходное положение и повторите приседание, на этот раз повернув туловище в противоположную сторону.","Продолжайте чередовать стороны при каждом повторении приседаний."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Mientras te levantas de la sentadilla, eleva los brazos por encima de la cabeza y gira el torso hacia un lado.","Vuelve a la posición inicial y repite la sentadilla, esta vez girando el torso hacia el lado opuesto.","Continúa alternando los lados en cada repetición de la sentadilla."]}},{"id":"2297","name":"stability ball crunch (full range hands behind head)","category":"waist","body_part":"waist","equipment":"stability ball","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/2297-Gn5FwYT.jpg","gif_url":"videos/2297-Gn5FwYT.gif","instruction_steps":{"he":["שבו על כדור הפיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, גלגלו באיטיות את פלג הגוף העליון קדימה, בהבאת החזה לכיוון הברכיים.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your upper body back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч для стабилизации, поставьте ступни на землю и согните колени под углом 90 градусов.","Положите руки за голову локтями наружу.","Включив пресс, медленно наклоните верхнюю часть тела вперед, приближая грудь к коленям.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, curva lentamente la parte superior del cuerpo hacia adelante, llevando el pecho hacia las rodillas.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3291","name":"stalder press","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"triceps","image":"images/3291-zd4P4B2.jpg","gif_url":"videos/3291-zd4P4B2.gif","instruction_steps":{"he":["התחילו בעמידה עם רגליים ברוחב כתפיים וידיים מתוחות מעל הראש.","כופפו ברכיים מעט והפעילו את הליבה.","הורידו את הגוף לעמדת סקוואט תוך שמירה על הידיים מתוחות מעל הראש.","תוך כדי הירידה לסקוואט, לחצו את הידיים מטה לכיוון הרצפה, בהפעלת הטרייספס.","עצרו לרגע בנקודה התחתונה של הסקוואט, ואז דחפו דרך העקבים לעמידה תוך הרמת הידיים חזרה מעל הראש.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing with your feet shoulder-width apart and your arms extended overhead.","Bend your knees slightly and engage your core.","Lower your body down into a squat position while keeping your arms extended overhead.","As you squat down, press your arms down towards the ground, engaging your triceps.","Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и вытянув руки над головой.","Слегка согните колени и задействуйте корпус.","Опустите тело в положение приседа, держа руки вытянутыми над головой.","Приседая, прижмите руки к земле, задействуя трицепсы.","Задержитесь на мгновение в нижней части приседа, затем оттолкнитесь пятками, чтобы снова встать, одновременно поднимая руки над головой.","Повторите необходимое количество повторений."],"es":["Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos por encima de la cabeza.","Flexiona ligeramente las rodillas y activa el core.","Baja el cuerpo a una posición de sentadilla mientras mantienes los brazos extendidos por encima de la cabeza.","Mientras bajas en la sentadilla, empuja los brazos hacia el suelo, activando los tríceps.","Haz una pausa de un momento en la parte baja de la sentadilla, luego empuja con los talones para levantarte mientras al mismo tiempo elevas de nuevo los brazos por encima de la cabeza.","Repite el número de repeticiones deseado."]}},{"id":"3669","name":"standing archer","category":"back","body_part":"back","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","biceps","forearms"],"target":"upper back","image":"images/3669-JF8AkMX.jpg","gif_url":"videos/3669-JF8AkMX.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","מתחו את הידיים ישר לפניכם בגובה הכתפיים, מקבילות לרצפה.","סובבו את הגו ימינה, תוך שמירה על ידיים מתוחות וגב ישר.","תוך כדי הסיבוב, מתחו את יד ימין קדימה ויד שמאל לאחור, בחיקוי תנועת מתיחת קשת.","החזיקו את התנוחה לרגע, ואז חזרו לנקודת ההתחלה.","חזרו על התנועה, הפעם בסיבוב הגו שמאלה ומתיחת יד שמאל קדימה ויד ימין לאחור.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you at shoulder height, parallel to the ground.","Rotate your torso to the right, keeping your arms extended and your back straight.","As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.","Hold the position for a moment, then return to the starting position.","Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.","Continue alternating sides for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Вытяните руки прямо перед собой на уровне плеч, параллельно земле.","Поверните туловище вправо, держа руки вытянутыми и спину прямой.","Во время вращения вытяните правую руку вперед, а левую назад, имитируя движение натягивания тетивы.","Удерживайте положение на мгновение, затем вернитесь в исходное положение.","Повторите движение, на этот раз повернув туловище влево и вытянув левую руку вперед, а правую назад.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Extiende los brazos rectos hacia adelante a la altura de los hombros, paralelos al suelo.","Gira el torso hacia la derecha, manteniendo los brazos extendidos y la espalda recta.","Mientras giras, extiende el brazo derecho hacia adelante y el brazo izquierdo hacia atrás, imitando el movimiento de tensar un arco.","Mantén la posición por un momento y luego vuelve a la posición inicial.","Repite el movimiento, esta vez girando el torso hacia la izquierda y extendiendo el brazo izquierdo hacia adelante y el brazo derecho hacia atrás.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0788","name":"standing behind neck press","category":"shoulders","body_part":"shoulders","equipment":"barbell","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0788-xDh0lJr.jpg","gif_url":"videos/0788-xDh0lJr.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו את המוט מאחורי הצוואר באחיזה עליונה.","שמרו על גב ישר וליבה מופעלת.","לחצו את המוט מעל הראש ביישור הידיים, עד יישור מלא של המרפקים.","עצרו לרגע בנקודה העליונה, ואז הורידו את המוט באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.","Keep your back straight and core engaged.","Press the barbell overhead by extending your arms, fully extending your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, и держите штангу за шеей хватом сверху.","Держите спину прямо и напрягите корпус.","Выжмите штангу над головой, вытянув руки и полностью разогнув локти.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra detrás del cuello con un agarre prono.","Mantén la espalda recta y el core activado.","Empuja la barra por encima de la cabeza extendiendo los brazos, estirando completamente los codos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1490","name":"standing calf raise (on a staircase)","category":"lower legs","body_part":"lower legs","equipment":"body weight","muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/1490-6HmFgmx.jpg","gif_url":"videos/1490-6HmFgmx.gif","instruction_steps":{"he":["עמדו על קצה מדרגה או משטח יציב כשהעקבים משתלשלים וקצות האצבעות של הרגליים על המדרגה.","אחזו במעקה או בקיר לשיווי משקל במידת הצורך.","הרימו באיטיות את העקבים גבוה ככל האפשר, בהעברת משקל הגוף לכריות כפות הרגליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.","Hold onto a railing or wall for balance if needed.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте на край ступеньки или прочной платформы, свесив пятки и положив пальцы ног на ступеньку.","При необходимости держитесь за перила или стену для равновесия.","Медленно поднимите пятки как можно выше, перенося вес тела на подушечки стоп.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie en el borde de un escalón o una plataforma firme, con los talones colgando y la punta de los pies sobre el escalón.","Sujétate de una baranda o pared para mantener el equilibrio si es necesario.","Levanta lentamente los talones lo más alto posible, elevando el peso de tu cuerpo sobre la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1397","name":"standing calves","category":"lower legs","body_part":"lower legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1397-XIHEoCG.jpg","gif_url":"videos/1397-XIHEoCG.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, כפות רגליים פונות קדימה.","הרימו את העקבים מהרצפה גבוה ככל האפשר, בעמידה על קצות האצבעות.","החזיקו את התנוחה לרגע, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, toes pointing forward.","Raise your heels off the ground as high as possible, standing on your toes.","Hold the position for a moment, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки направлены вперед.","Поднимите пятки от земли как можно выше, встав на носки.","Задержитесь в этом положении на мгновение, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.","Levanta los talones del suelo lo más alto posible, apoyándote sobre la punta de los pies.","Mantén la posición por un momento y luego baja lentamente los talones de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1398","name":"standing calves calf stretch","category":"lower legs","body_part":"lower legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1398-qOKcgVP.jpg","gif_url":"videos/1398-qOKcgVP.gif","instruction_steps":{"he":["עמדו מול קיר או חפץ יציב, במרחק אורך יד בערך.","הניחו את הידיים על הקיר או החפץ בגובה הכתפיים.","צעדו לאחור עם כף רגל אחת, תוך שמירה על העקב שטוח על הרצפה.","כופפו את הברך הקדמית מעט ורכנו קדימה, תוך שמירה על הרגל האחורית ישרה.","אתם אמורים להרגיש מתיחה בשריר התאומים.","החזיקו את המתיחה 20–30 שניות.","חזרו על התרגיל ברגל השנייה."],"en":["Stand facing a wall or sturdy object, about an arm's length away.","Place your hands on the wall or object at shoulder height.","Step back with one foot, keeping your heel flat on the ground.","Bend your front knee slightly and lean forward, keeping your back leg straight.","You should feel a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Repeat on the other leg."],"ru":["Встаньте лицом к стене или прочному предмету на расстоянии вытянутой руки.","Положите руки на стену или предмет на уровне плеч.","Сделайте шаг назад одной ногой, удерживая пятку на земле.","Слегка согните переднее колено и наклонитесь вперед, сохраняя заднюю ногу прямой.","Вы должны почувствовать растяжение икроножной мышцы.","Удерживайте растяжку 20–30 секунд.","Повторите на другой ноге."],"es":["Ponte de pie frente a una pared u objeto firme, a una distancia aproximada de un brazo.","Coloca las manos sobre la pared o el objeto a la altura de los hombros.","Da un paso hacia atrás con un pie, manteniendo el talón plano sobre el suelo.","Flexiona ligeramente la rodilla delantera e inclínate hacia adelante, manteniendo la pierna trasera recta.","Deberías sentir un estiramiento en el músculo de la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Repite con la otra pierna."]}},{"id":"1599","name":"standing hamstring and calf stretch with strap","category":"upper legs","body_part":"upper legs","equipment":"rope","muscle_group":"calves","secondary_muscles":["calves"],"target":"hamstrings","image":"images/1599-xTjr103.jpg","gif_url":"videos/1599-xTjr103.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים.","החזיקו את הרצועה בשתי ידיים ומקמו אותה סביב כרית כף הרגל.","שמרו על הרגל ישרה והטו באיטיות קדימה מהירכיים, תוך שמירה על גב ישר.","הרגישו את המתיחה בשרירי הירך האחורית והתאומים.","החזיקו את המתיחה 20–30 שניות.","שחררו את המתיחה וחזרו עליה ברגל השנייה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand upright with your feet shoulder-width apart.","Hold the strap with both hands and place it around the ball of your foot.","Keep your leg straight and slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your hamstring and calf muscles.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat with the other leg.","Repeat for the desired number of repetitions."],"ru":["Встаньте прямо, ноги на ширине плеч.","Возьмите ремешок обеими руками и наденьте его на подушечку стопы.","Держите ногу прямо и медленно наклонитесь вперед от бедер, сохраняя спину прямой.","Почувствуйте растяжение подколенных сухожилий и икроножных мышц.","Удерживайте растяжку 20–30 секунд.","Освободите растяжку и повторите с другой ногой.","Повторите необходимое количество повторений."],"es":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Sostén la correa con ambas manos y colócala alrededor de la parte anterior de la planta del pie.","Mantén la pierna recta e inclínate lentamente hacia adelante desde las caderas, manteniendo la espalda recta.","Siente el estiramiento en los isquiotibiales y en los músculos de la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Suelta el estiramiento y repite con la otra pierna.","Repite el número de repeticiones deseado."]}},{"id":"0794","name":"standing lateral stretch","category":"back","body_part":"back","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","obliques"],"target":"lats","image":"images/0794-1jXLYEw.jpg","gif_url":"videos/0794-1jXLYEw.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","מתחו את הידיים ישר לצדדים, מקבילות לרצפה.","הטו באיטיות את פלג הגוף העליון לצד אחד, עד תחושת מתיחה בצד וברחב הגבי.","החזיקו את המתיחה 15–30 שניות.","חזרו לנקודת ההתחלה וחזרו על התנועה בצד השני.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out to the sides, parallel to the ground.","Slowly lean your upper body to one side, feeling a stretch in your side and lats.","Hold the stretch for 15-30 seconds.","Return to the starting position and repeat on the other side.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Вытяните руки прямо в стороны, параллельно земле.","Медленно наклоните верхнюю часть тела в сторону, чувствуя растяжение в боках и широчайших.","Удерживайте растяжку 15–30 секунд.","Вернитесь в исходное положение и повторите то же самое в другую сторону.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Extiende los brazos hacia los lados, paralelos al suelo.","Inclina lentamente la parte superior del cuerpo hacia un lado, sintiendo un estiramiento en el costado y los dorsales.","Mantén el estiramiento durante 15-30 segundos.","Regresa a la posición inicial y repite del otro lado.","Repite el número de repeticiones deseado."]}},{"id":"1364","name":"standing pelvic tilt","category":"back","body_part":"back","equipment":"body weight","muscle_group":"abdominals","secondary_muscles":["abdominals"],"target":"spine","image":"images/1364-cuKYxhu.jpg","gif_url":"videos/1364-cuKYxhu.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","הניחו את הידיים על המותניים או תנו להן להשתלשל לצידי הגוף.","הפעילו את שרירי הליבה והטו את האגן קדימה, בדחיפת הגב התחתון לכיוון הקיר שמאחוריכם.","החזיקו את התנוחה כמה שניות, ואז שחררו וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or let them hang by your sides.","Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.","Hold the position for a few seconds, then release and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Положите руки на бедра или позвольте им свисать по бокам.","Задействуйте мышцы корпуса и наклоните таз вперед, прижимая поясницу к стене позади себя.","Удерживайте положение несколько секунд, затем расслабьтесь и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Coloca las manos sobre las caderas o déjalas colgar a los lados.","Activa los músculos del core e inclina la pelvis hacia adelante, empujando la zona lumbar hacia la pared detrás de ti.","Mantén la posición durante unos segundos, luego suelta y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0795","name":"standing single leg curl","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes"],"target":"hamstrings","image":"images/0795-C5jncD2.jpg","gif_url":"videos/0795-C5jncD2.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן והידיים על המותניים.","העבירו את המשקל לרגל שמאל והרימו את כף רגל ימין מהרצפה, בכיפוף הברך.","גלגלו באיטיות את עקב ימין לכיוון הישבן, בכיווץ הירך האחורית.","עצרו לרגע בנקודה העליונה, ואז הורידו את כף רגל ימין באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Stand with your feet hip-width apart and your hands on your hips.","Shift your weight onto your left leg and lift your right foot off the ground, bending your knee.","Slowly curl your right heel towards your glutes, squeezing your hamstring.","Pause for a moment at the top, then slowly lower your right foot back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Встаньте, ноги на ширине плеч, руки на бедрах.","Перенесите вес тела на левую ногу и поднимите правую ногу от земли, согнув колено.","Медленно подогните правую пятку к ягодицам, сжимая подколенное сухожилие.","Задержитесь на мгновение в верхней точке, затем медленно опустите правую ногу обратно в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas.","Traslada tu peso a la pierna izquierda y levanta el pie derecho del suelo, flexionando la rodilla.","Curva lentamente el talón derecho hacia los glúteos, contrayendo el isquiotibial.","Haz una pausa de un momento en la parte superior y luego baja lentamente el pie derecho de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"0796","name":"standing wheel rollerout","category":"waist","body_part":"waist","equipment":"wheel roller","muscle_group":"lower back","secondary_muscles":["lower back","shoulders"],"target":"abs","image":"images/0796-KtRomty.jpg","gif_url":"videos/0796-KtRomty.gif","instruction_steps":{"he":["התחילו בעמידה זקופה עם רגליים ברוחב כתפיים וגלגל הבטן לפניכם.","הטו את הגו מהמותניים וגלגלו באיטיות את הגלגל קדימה, תוך שמירה על גב ישר וליבה מופעלת.","המשיכו להתגלגל קדימה עד לתחושת מתיחה בשרירי הבטן והגוף מתוח רחוק ככל האפשר.","עצרו לרגע, ואז גלגלו באיטיות את הגלגל חזרה לכיוון הגוף, לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.","Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.","Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.","Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с того, что встаньте прямо, ноги на ширине плеч и ролик-колесо перед собой.","Согнитесь в талии и медленно катите колесо вперед, сохраняя спину прямой и напряженный корпус.","Продолжайте перекатываться вперед до тех пор, пока не почувствуете растяжение мышц пресса и тело не выпрямится настолько, насколько это возможно.","Сделайте паузу на мгновение, затем медленно поверните колесо обратно к телу, возвращаясь в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza de pie, erguido, con los pies separados a la altura de los hombros y el rodillo frente a ti.","Dobla la cintura y haz rodar lentamente el rodillo hacia adelante, manteniendo la espalda recta y el core activado.","Continúa rodando hacia adelante hasta sentir un estiramiento en el abdomen y que tu cuerpo esté extendido lo máximo posible.","Haz una pausa de un momento, luego haz rodar lentamente el rodillo de regreso hacia tu cuerpo, volviendo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3223","name":"star jump (male)","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3223-HtfCpfi.jpg","gif_url":"videos/3223-HtfCpfi.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וידיים לצידי הגוף.","כופפו ברכיים מעט וקפצו למעלה בפיצוץ.","תוך כדי הקפיצה, פתחו את הרגליים ומתחו את הידיים לצדדים, ביצירת צורת כוכב עם הגוף.","נחתו ברכות על כריות כפות הרגליים עם ברכיים כפופות מעט.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your arms by your sides.","Bend your knees slightly and jump up explosively.","As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.","Land softly on the balls of your feet with your knees slightly bent.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, руки по бокам.","Слегка согните колени и резко подпрыгните вверх.","Во время прыжка раздвиньте ноги и вытяните руки в стороны, образуя своим телом звездообразную форму.","Мягко приземлитесь на подушечки стоп, слегка согнув колени.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.","Flexiona ligeramente las rodillas y salta hacia arriba de forma explosiva.","Mientras saltas, separa las piernas y extiende los brazos hacia los lados, formando una figura de estrella con tu cuerpo.","Aterriza suavemente sobre la punta de los pies con las rodillas ligeramente flexionadas.","Repite el número de repeticiones deseado."]}},{"id":"2138","name":"stationary bike run v. 3","category":"cardio","body_part":"cardio","equipment":"stationary bike","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/2138-H1PESYI.jpg","gif_url":"videos/2138-H1PESYI.gif","instruction_steps":{"he":["כווננו את גובה המושב והתנוחה ליישור נכון.","הניחו את כפות הרגליים על הדוושות וקבעו אותן ברצועות אם ישנן.","התחילו לדווש בקצב נוח.","שמרו על קצב אחיד והגבירו את ההתנגדות כרצונכם.","הפעילו את שרירי הליבה לשמירה על יציבות ויציבה נכונה.","המשיכו לדווש למשך הזמן הרצוי של האימון.","הפחיתו בהדרגה את ההתנגדות והאטו לפני עצירה מלאה.","מתחו את הרגליים ובצעו שחרור בסיום האימון."],"en":["Adjust the seat height and position to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace.","Maintain a steady rhythm and increase the resistance as desired.","Engage your core muscles to maintain stability and proper posture.","Continue pedaling for the desired duration of your workout.","Gradually decrease the resistance and slow down before coming to a complete stop.","Stretch your legs and cool down after the workout."],"ru":["Отрегулируйте высоту и положение сиденья, чтобы обеспечить правильное выравнивание.","Поставьте ноги на педали и закрепите их ремнями, если таковые имеются.","Начните крутить педали в удобном темпе.","Поддерживайте устойчивый ритм и увеличивайте сопротивление по желанию.","Задействуйте основные мышцы, чтобы поддерживать устойчивость и правильную осанку.","Продолжайте крутить педали в течение желаемой продолжительности тренировки.","Постепенно уменьшайте сопротивление и замедляйтесь, прежде чем полностью остановиться.","Разомните ноги и остыньте после тренировки."],"es":["Ajusta la altura y la posición del asiento para asegurar una alineación correcta.","Coloca los pies sobre los pedales y sujétalos con las correas si están disponibles.","Comienza a pedalear a un ritmo cómodo.","Mantén un ritmo constante y aumenta la resistencia según lo desees.","Activa los músculos del core para mantener la estabilidad y una postura correcta.","Continúa pedaleando durante la duración deseada de tu entrenamiento.","Disminuye gradualmente la resistencia y reduce la velocidad antes de detenerte por completo.","Estira las piernas y enfría después del entrenamiento."]}},{"id":"0798","name":"stationary bike walk","category":"cardio","body_part":"cardio","equipment":"leverage machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/0798-a8VDgLw.jpg","gif_url":"videos/0798-a8VDgLw.gif","instruction_steps":{"he":["כווננו את גובה המושב והתנוחה על האופניים הנייחים ליישור נכון של הגוף.","הניחו את כפות הרגליים על הדוושות וקבעו אותן ברצועות אם ישנן.","התחילו לדווש בקצב נוח, תוך שמירה על גב ישר וליבה מופעלת.","שמרו על קצב אחיד והגבירו את רמת ההתנגדות אם תרצו.","המשיכו לדווש למשך הזמן הרצוי של אימון האירובי.","לסיום, הפחיתו בהדרגה את הקצב ורמת ההתנגדות.","מתחו את שרירי הרגליים אחרי האימון למניעת נוקשות וקידום התאוששות."],"en":["Adjust the seat height and position on the stationary bike to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace, keeping your back straight and core engaged.","Maintain a steady rhythm and increase the resistance level if desired.","Continue pedaling for the desired duration of your cardio workout.","Cool down by gradually reducing your pace and resistance level.","Stretch your leg muscles after the workout to prevent tightness and promote recovery."],"ru":["Отрегулируйте высоту и положение сиденья на велотренажере, чтобы обеспечить правильное выравнивание.","Поставьте ноги на педали и закрепите их ремнями, если таковые имеются.","Начните крутить педали в удобном темпе, держа спину прямо и напрягая корпус.","Поддерживайте устойчивый ритм и при желании увеличивайте уровень сопротивления.","Продолжайте крутить педали в течение желаемой продолжительности кардио-тренировки.","Охладитесь, постепенно снижая темп и уровень сопротивления.","Растягивайте мышцы ног после тренировки, чтобы предотвратить напряжение и ускорить восстановление."],"es":["Ajusta la altura y la posición del asiento en la bicicleta estática para asegurar una alineación correcta.","Coloca los pies sobre los pedales y sujétalos con las correas si están disponibles.","Comienza a pedalear a un ritmo cómodo, manteniendo la espalda recta y el core activado.","Mantén un ritmo constante y aumenta el nivel de resistencia si lo deseas.","Continúa pedaleando durante la duración deseada de tu entrenamiento cardiovascular.","Enfría reduciendo gradualmente tu ritmo y el nivel de resistencia.","Estira los músculos de las piernas después del entrenamiento para prevenir la rigidez y favorecer la recuperación."]}},{"id":"3314","name":"straddle maltese","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"abs","image":"images/3314-HfqciZF.jpg","gif_url":"videos/3314-HfqciZF.gif","instruction_steps":{"he":["התחילו בתלייה על זוג טבעות עם ידיים ישרות לגמרי והגוף בקו ישר.","פסקו את הרגליים לרווחה, בתנוחת פיסוק רחבה.","הפעילו את הליבה והורידו באיטיות את הגוף עד שהידיים מקבילות לרצפה.","החזיקו את התנוחה כמה שניות, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.","Spread your legs wide apart, forming a straddle position.","Engage your core and slowly lower your body until your arms are parallel to the ground.","Hold this position for a few seconds, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с подвешивания на паре колец, полностью вытянув руки и выстроив тело по прямой линии.","Широко разведите ноги в стороны, образуя положение сидя.","Напрягите корпус и медленно опускайте тело, пока руки не станут параллельны земле.","Удерживайте это положение несколько секунд, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza colgándote de un par de anillas con los brazos completamente extendidos y el cuerpo en línea recta.","Separa bien las piernas, formando una posición a horcajadas.","Activa el core y baja lentamente el cuerpo hasta que los brazos queden paralelos al suelo.","Mantén esta posición durante unos segundos, luego empújate de nuevo hacia arriba a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3298","name":"straddle planche","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","chest"],"target":"abs","image":"images/3298-BL3GHeY.jpg","gif_url":"videos/3298-BL3GHeY.gif","instruction_steps":{"he":["התחילו בעמדת שכיבת סמיכה עם ידיים ברוחב כתפיים ורגליים פתוחות לרווחה.","הפעילו את הליבה והעבירו באיטיות את המשקל קדימה, בהבאת הכתפיים מעל הידיים.","כופפו מרפקים והורידו את הגוף לכיוון הרצפה, תוך שמירה על מרפקים צמודים לצידי הגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך כפות הידיים ליישור הידיים והרמת הגוף חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.","Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.","Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции для отжиманий, поставив руки на ширине плеч и широко расставив ноги.","Напрягите корпус и медленно перенесите вес вперед, перенося плечи на руки.","Согните локти и опустите тело к земле, держа локти близко к бокам.","Задержитесь на мгновение в нижней точке, затем подтолкните руки, чтобы выпрямить руки и поднять тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en posición de flexión con las manos separadas a la altura de los hombros y los pies bien separados.","Activa el core y traslada lentamente tu peso hacia adelante, llevando los hombros por encima de las manos.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.","Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1427","name":"straight leg outer hip abductor","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"abductors","image":"images/1427-mQ1tBXn.jpg","gif_url":"videos/1427-mQ1tBXn.gif","instruction_steps":{"he":["שכבו על הצד עם רגליים ישרות זו על גבי זו.","הניחו את היד התחתונה מתחת לראש לתמיכה.","הפעילו את הליבה והרימו את הרגל העליונה גבוה ככל האפשר בלי לסובב את האגן או להישען לאחור.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Лягте на бок, выпрямив ноги и положив их друг на друга.","Поместите нижнюю руку под голову для поддержки.","Напрягите корпус и поднимите верхнюю ногу как можно выше, не вращая бедрами и не отклоняясь назад.","Задержитесь на мгновение в верхней точке, затем медленно опустите ногу обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Túmbate de lado con las piernas rectas y apiladas una sobre la otra.","Coloca el brazo de abajo bajo la cabeza para apoyarte.","Activa el core y levanta la pierna superior lo más alto posible sin rotar las caderas ni inclinarte hacia atrás.","Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0803","name":"superman push-up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"core","secondary_muscles":["core","shoulders"],"target":"pectorals","image":"images/0803-4GqRrAk.jpg","gif_url":"videos/0803-4GqRrAk.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים מעט רחבות מרוחב הכתפיים ורגליים צמודות.","הפעילו את הליבה והורידו את הגוף לכיוון הרצפה, תוך שמירה על מרפקים צמודים לצידי הגוף.","תוך כדי הורדת הגוף, הרימו בו-זמנית את יד ימין ורגל שמאל מהרצפה, במתיחתן ישר החוצה.","עצרו לרגע בנקודה העליונה, ואז הורידו את היד והרגל חזרה תוך דחיפת הגוף למעלה לנקודת ההתחלה.","חזרו על התנועה, הפעם בהרמת יד שמאל ורגל ימין.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.","Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.","Repeat the movement, this time lifting your left arm and right leg.","Continue alternating sides for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, расставив руки чуть шире плеч и поставив ноги вместе.","Напрягите корпус и опустите тело к земле, держа локти близко к бокам.","Опуская тело, одновременно поднимите правую руку и левую ногу от земли, вытягивая их прямо.","Задержитесь на мгновение в верхней точке, затем опустите руку и ногу обратно вниз, одновременно возвращаясь в исходное положение.","Повторите движение, на этот раз поднимая левую руку и правую ногу.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.","Mientras bajas el cuerpo, levanta simultáneamente el brazo derecho y la pierna izquierda del suelo, extendiéndolos completamente.","Haz una pausa de un momento en la parte superior, luego baja el brazo y la pierna mientras te empujas de nuevo hacia arriba a la posición inicial.","Repite el movimiento, esta vez levantando el brazo izquierdo y la pierna derecha.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0805","name":"suspended abdominal fallout","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/0805-X3TCNEU.jpg","gif_url":"videos/0805-X3TCNEU.gif","instruction_steps":{"he":["חברו רצועות אימון לנקודת עיגון גבוהה וכווננו אותן לגובה המותניים.","עמדו עם הגב לנקודת העיגון ואחזו בידיות עם ידיים מתוחות לפניכם.","רכנו קדימה מהמותניים, תוך שמירה על גוף ישר וליבה מופעלת.","הורידו את הגוף רחוק ככל האפשר, תוך שמירה על שליטה ומתח בשרירי הבטן.","עצרו לרגע בנקודה התחתונה, ואז הרימו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a suspension trainer to a high anchor point and adjust the straps to waist height.","Stand facing away from the anchor point and hold the handles with your arms extended in front of you.","Lean forward at the waist, keeping your body straight and your core engaged.","Lower your body as far as you can while maintaining control and tension in your abs.","Pause for a moment at the bottom, then slowly raise your body back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите тренажер для подвески к высокой точке крепления и отрегулируйте ремни по высоте талии.","Встаньте лицом от точки крепления и возьмитесь за ручки, вытянув руки перед собой.","Наклонитесь вперед в талии, сохраняя тело прямым и напряженным корпусом.","Опустите тело как можно ниже, сохраняя при этом контроль и напряжение в прессе.","Задержитесь на мгновение в нижней точке, затем медленно поднимите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta un entrenador de suspensión a un punto de anclaje alto y ajusta las correas a la altura de la cintura.","Ponte de pie de espaldas al punto de anclaje y sostén las asas con los brazos extendidos frente a ti.","Inclínate hacia adelante desde la cintura, manteniendo el cuerpo recto y el core activado.","Baja el cuerpo todo lo que puedas mientras mantienes el control y la tensión en el abdomen.","Haz una pausa de un momento en la parte baja, luego eleva lentamente el cuerpo de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0806","name":"suspended push-up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0806-IaGQCrC.jpg","gif_url":"videos/0806-IaGQCrC.gif","instruction_steps":{"he":["מצאו רצועות אימון וכווננו אותן לגובה מתאים.","עמדו עם הגב לנקודת העיגון ואחזו בידיות באחיזה עליונה.","צעדו עם כפות הרגליים קדימה, בהטיית הגוף קדימה עד שהמשקל נתמך על רצועות האימון.","שמרו על גוף ישר מהראש ועד העקבים, הפעילו את הליבה, והורידו את החזה לכיוון הידיות.","דחפו דרך החזה והידיים לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Find a suspension trainer and adjust it to an appropriate height.","Stand facing away from the anchor point and hold the handles with an overhand grip.","Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.","Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.","Push through your chest and arms to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Найдите тренажер для подвески и отрегулируйте его на подходящую высоту.","Встаньте лицом от точки крепления и возьмитесь за ручки верхним хватом.","Идите ногами вперед, наклоняя тело вперед, пока ваш вес не будет поддержан тренажером для подвески.","Держите тело прямо от головы до пяток, задействуйте корпус и опустите грудь к ручкам.","Оттолкнитесь грудью и руками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Busca un entrenador de suspensión y ajústalo a una altura adecuada.","Ponte de pie de espaldas al punto de anclaje y sostén las asas con un agarre prono.","Camina hacia adelante con los pies, inclinando el cuerpo hacia adelante hasta que tu peso quede sostenido por el entrenador de suspensión.","Mantén el cuerpo recto desde la cabeza hasta los talones, activa el core y baja el pecho hacia las asas.","Empuja con el pecho y los brazos para volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0807","name":"suspended reverse crunch","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0807-R1WYG5D.jpg","gif_url":"videos/0807-R1WYG5D.gif","instruction_steps":{"he":["היתלו על מוט מתח עם ידיים ישרות לגמרי וכפות ידיים פונות מכם.","הפעילו את שרירי הליבה והרימו את הברכיים לכיוון החזה, תוך גלגול האגן לכיוון בית החזה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הברכיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.","Pause for a moment at the top, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, полностью вытянув руки и повернув ладони от себя.","Напрягите корпус и поднимите колени к груди, подогнув таз к грудной клетке.","Задержитесь на мгновение в верхней точке, затем медленно опустите колени обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y sube las rodillas hacia el pecho, curvando la pelvis hacia la caja torácica.","Haz una pausa de un momento en la parte superior, luego baja lentamente las rodillas de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0808","name":"suspended row","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0808-4OaumBr.jpg","gif_url":"videos/0808-4OaumBr.gif","instruction_steps":{"he":["הכינו רצועות אימון בגובה מתאים.","עמדו מול נקודת העיגון עם רגליים ברוחב כתפיים.","אחזו בידיות באחיזה עליונה, כפות ידיים פונות זו לזו.","היטו לאחור, תוך שמירה על גוף ישר והעקבים על הרצפה.","משכו את החזה לכיוון הידיות, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה העליונה, ואז הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Set up a suspension trainer at an appropriate height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the handles with an overhand grip, palms facing each other.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Установите тренажер для подвески на подходящей высоте.","Встаньте лицом к точке крепления, поставив ноги на ширине плеч.","Возьмитесь за ручки хватом сверху, ладонями друг к другу.","Откиньтесь назад, держа тело прямо, а пятки на земле.","Подтяните грудь к ручкам, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Coloca un entrenador de suspensión a una altura adecuada.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Sostén las asas con un agarre prono, con las palmas mirándose entre sí.","Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo.","Tira del pecho hacia las asas, apretando los omóplatos entre sí.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0809","name":"suspended split squat","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0809-QpXqiq8.jpg","gif_url":"videos/0809-QpXqiq8.gif","instruction_steps":{"he":["עמדו עם הגב לרצועות האימון, רגליים ברוחב כתפיים.","מתחו רגל אחת קדימה והניחו את גב כף הרגל בתוך רצועת הרגל של רצועות האימון.","כופפו את רגל העמידה והורידו את הגוף לעמדת מספריים, תוך שמירה על חזה מורם וברך בקו אחד עם כף הרגל.","דחפו דרך העקב לחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו רגל מובילה."],"en":["Stand facing away from a suspension trainer with your feet shoulder-width apart.","Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.","Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"ru":["Встаньте лицом к тренажеру с подвеской, поставив ноги на ширине плеч.","Вытяните одну ногу вперед и поместите верхнюю часть стопы в подставку для подвесного тренажера.","Согните стоящую ногу и опустите тело в положение выпада, удерживая грудь вверх, а колено на одной линии с пальцами ног.","Оттолкнитесь пяткой, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"es":["Ponte de pie de espaldas a un entrenador de suspensión con los pies separados a la altura de los hombros.","Extiende una pierna hacia adelante y coloca el empeine del pie en el soporte para pie del entrenador de suspensión.","Flexiona la pierna de apoyo y baja el cuerpo a una posición de zancada, manteniendo el pecho elevado y la rodilla alineada con la punta del pie.","Empuja con el talón para regresar a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]}},{"id":"3433","name":"swimmer kicks v. 2 (male)","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","calves"],"target":"glutes","image":"images/3433-SP3hUez.jpg","gif_url":"videos/3433-SP3hUez.gif","instruction_steps":{"he":["שכבו על הבטן על מזרן עם ידיים מתוחות מעל הראש.","הפעילו את הליבה והרימו את החזה והרגליים מהרצפה בו-זמנית.","בעטו עם הרגליים למעלה ולמטה בתנועת רפרוף, כאילו אתם שוחים.","המשיכו בבעיטות למספר החזרות הרצוי.","הורידו את החזה והרגליים חזרה לנקודת ההתחלה."],"en":["Lie face down on a mat with your arms extended overhead.","Engage your core and lift your chest and legs off the ground simultaneously.","Kick your legs up and down in a fluttering motion, as if you were swimming.","Continue kicking for the desired number of repetitions.","Lower your chest and legs back down to the starting position."],"ru":["Лягте лицом вниз на коврик, вытянув руки над головой.","Напрягите корпус и одновременно поднимите грудь и ноги от земли.","Двигайте ногами вверх и вниз порхающими движениями, как будто вы плывете.","Продолжайте выполнять удары ногами желаемое количество повторений.","Опустите грудь и ноги обратно в исходное положение."],"es":["Túmbate boca abajo sobre una esterilla con los brazos extendidos por encima de la cabeza.","Activa el core y levanta el pecho y las piernas del suelo al mismo tiempo.","Mueve las piernas hacia arriba y hacia abajo con un movimiento de aleteo, como si estuvieras nadando.","Continúa el movimiento de patada el número de repeticiones deseado.","Baja el pecho y las piernas de nuevo a la posición inicial."]}},{"id":"3318","name":"swing 360","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"cardiovascular system","image":"images/3318-tnaj0mT.jpg","gif_url":"videos/3318-tnaj0mT.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","החזיקו את הידיים ישר לפניכם, מקבילות לרצפה.","הפעילו את הליבה והניפו את הידיים בתנועה מעגלית, תוך סיבוב הגו תוך כדי.","המשיכו בתנועה המעגלית, בהנפת הידיים וסיבוב הגו, למספר החזרות הרצוי.","זכרו לנשום לאורך כל התרגיל."],"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold your arms straight out in front of you, parallel to the ground.","Engage your core and swing your arms in a circular motion, rotating your torso as you do so.","Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.","Remember to breathe throughout the exercise."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Держите руки прямо перед собой, параллельно земле.","Напрягите корпус и совершайте круговые движения руками, вращая при этом туловище.","Продолжайте круговое движение, размахивая руками и вращая туловищем желаемое количество повторений.","Не забывайте дышать на протяжении всего упражнения."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Mantén los brazos extendidos rectos frente a ti, paralelos al suelo.","Activa el core y mueve los brazos en un movimiento circular, rotando el torso mientras lo haces.","Continúa el movimiento circular, moviendo los brazos y rotando el torso el número de repeticiones deseado.","Recuerda respirar durante todo el ejercicio."]}},{"id":"1753","name":"three bench dip","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1753-DQ0cqkT.jpg","gif_url":"videos/1753-DQ0cqkT.gif","instruction_steps":{"he":["שבו על ספסל כשהידיים אוחזות בקצה והאצבעות פונות קדימה.","החליקו את הישבן מהספסל ותמכו במשקל הגוף עם הידיים.","כופפו מרפקים והורידו את הגוף עד שהזרועות העליונות מקבילות לרצפה.","דחפו את עצמכם חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, взявшись руками за край, пальцами вперед.","Сдвиньте ягодицы со скамьи, поддерживая вес руками.","Согните локти и опустите тело до тех пор, пока плечи не станут параллельны земле.","Вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.","Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.","Flexiona los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo.","Empújate de vuelta hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2459","name":"tire flip","category":"upper legs","body_part":"upper legs","equipment":"tire","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","core"],"target":"glutes","image":"images/2459-oZjMu1t.jpg","gif_url":"videos/2459-oZjMu1t.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, מול הצמיג.","כופפו ברכיים והטו את הגו מהירכיים, בירידה לעמדת סקוואט.","התכופפו ואחזו בקצה התחתון של הצמיג בשתי ידיים, אצבעות פונות אליכם.","הפעילו את הישבן ושרירי הרגליים, ודחפו בפיצוץ דרך הרגליים להרמת הצמיג מהרצפה.","כשהצמיג מתהפך, השתמשו בכוח פלג הגוף העליון להכוונתו ושמירה על שליטה.","כשהצמיג מתהפך לגמרי, צעדו במהירות לאחור והתמקמו מחדש.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, facing the tire.","Bend your knees and hinge at the hips, lowering into a squat position.","Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you.","Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.","As the tire flips over, use your upper body strength to guide it and maintain control.","Once the tire is fully flipped, quickly step back and reset your stance.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч, лицом к шине.","Согните колени и наклонитесь в бедрах, опускаясь в присед.","Наклонитесь вниз и возьмитесь за нижний край шины обеими руками, пальцами к себе.","Задействуйте ягодицы и мышцы ног и резко совершите движение ногами, чтобы поднять колесо с земли.","Когда шина переворачивается, используйте силу верхней части тела, чтобы направлять ее и сохранять контроль.","Как только шина полностью перевернется, быстро отступите назад и восстановите стойку.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, de frente al neumático.","Flexiona las rodillas y dobla las caderas, bajando a una posición de sentadilla.","Agáchate y agarra el borde inferior del neumático con ambas manos, con los dedos apuntando hacia ti.","Activa los glúteos y los músculos de las piernas, y empuja con fuerza a través de las piernas para levantar el neumático del suelo.","Mientras el neumático se voltea, usa la fuerza de la parte superior del cuerpo para guiarlo y mantener el control.","Una vez que el neumático esté completamente volteado, retrocede rápidamente y reinicia tu postura.","Repite el número de repeticiones deseado."]}},{"id":"0811","name":"trap bar deadlift","category":"upper legs","body_part":"upper legs","equipment":"trap bar","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"target":"glutes","image":"images/0811-jQGwmxN.jpg","gif_url":"videos/0811-jQGwmxN.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים ומוט הטראפ על הרצפה לפניכם.","כופפו ירכיים וברכיים לירידה ואחזו בידיות מוט הטראפ באחיזה עליונה.","שמרו על גב ישר וחזה מורם כשאתם מתחילים להרים את מוט הטראפ מהרצפה ביישור הירכיים והברכיים.","תוך כדי ההרמה, התמקדו בדחיפה דרך העקבים וכיווץ הישבן בנקודה העליונה של התנועה.","הורידו את מוט הטראפ חזרה לרצפה בכיפוף ירכיים וברכיים, תוך שמירה על גב ישר לאורך כל התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.","Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.","Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.","As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.","Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, поставьте трэп-штангу на землю перед собой.","Согните бедра и колени, чтобы опуститься вниз, и возьмитесь за ручки трэп-перекладины хватом сверху.","Держите спину прямо и грудь вверх, когда начнете отрывать трэп-штангу от земли, вытягивая бедра и колени.","Во время подъема сосредоточьтесь на том, чтобы двигаться пятками и сжимать ягодицы в верхней части движения.","Опустите трэп-штангу обратно на землю, сгибая бедра и колени, сохраняя спину прямой на протяжении всего движения.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y la barra hexagonal en el suelo frente a ti.","Flexiona las caderas y las rodillas para bajar y agarra las asas de la barra hexagonal con un agarre prono.","Mantén la espalda recta y el pecho elevado mientras comienzas a levantar la barra hexagonal del suelo extendiendo las caderas y las rodillas.","Al levantar, concéntrate en empujar con los talones y contraer los glúteos en la parte superior del movimiento.","Baja la barra hexagonal de nuevo al suelo flexionando las caderas y las rodillas, manteniendo la espalda recta durante todo el movimiento.","Repite el número de repeticiones deseado."]}},{"id":"0814","name":"triceps dip","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0814-X6C6i5Y.jpg","gif_url":"videos/0814-X6C6i5Y.gif","instruction_steps":{"he":["שבו על קצה ספסל או כיסא כשהידיים אוחזות בקצה והאצבעות פונות קדימה.","החליקו את הישבן מהספסל ותמכו במשקל הגוף עם הידיים.","כופפו מרפקים והורידו את הגוף לכיוון הרצפה, כשהגב קרוב לספסל.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на край скамьи или стула, взявшись руками за край, пальцами вперед.","Сдвиньте ягодицы со скамьи, поддерживая вес руками.","Согните локти и опустите тело к земле, держа спину близко к скамье.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante.","Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0812","name":"triceps dip (bench leg)","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0812-VuoerH0.jpg","gif_url":"videos/0812-VuoerH0.gif","instruction_steps":{"he":["שבו על קצה ספסל כשהידיים אוחזות בקצה, אצבעות פונות קדימה.","צעדו עם כפות הרגליים קדימה, בהחלקת הישבן מהספסל, ויישרו את הידיים.","כופפו מרפקים והורידו את הגוף לכיוון הרצפה, כשהגב קרוב לספסל.","דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench, and straighten your arms.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на край скамьи, взявшись руками за край, пальцами вперед.","Пройдите ногами вперед, сдвинув ягодицы со скамьи, и выпрямите руки.","Согните локти и опустите тело к земле, держа спину близко к скамье.","Оттолкнитесь ладонями, чтобы выпрямить руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el borde de un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.","Camina con los pies hacia adelante, deslizando los glúteos fuera del banco, y estira los brazos.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.","Empuja con las palmas para estirar los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0813","name":"triceps dip (between benches)","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0813-Wgbn9qo.jpg","gif_url":"videos/0813-Wgbn9qo.gif","instruction_steps":{"he":["שבו על ספסל כשהידיים אוחזות בקצה הספסל, אצבעות פונות קדימה.","החליקו את הישבן מהספסל ותמכו במשקל הגוף עם הידיים.","כופפו מרפקים והורידו את הגוף לכיוון הרצפה, כשהגב קרוב לספסל.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, взявшись руками за край скамьи, пальцами вперед.","Сдвиньте ягодицы со скамьи, поддерживая вес руками.","Согните локти и опустите тело к земле, держа спину близко к скамье.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con las manos agarrando el borde del banco, los dedos apuntando hacia adelante.","Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0815","name":"triceps dips floor","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0815-7aVz15j.jpg","gif_url":"videos/0815-7aVz15j.gif","instruction_steps":{"he":["שבו על קצה כיסא או ספסל כשהידיים ליד האגן, אצבעות פונות קדימה.","החליקו את הישבן מקדמת הכיסא כשהרגליים מתוחות לפניכם.","יישרו את הידיים, עם כיפוף קל במרפקים לשמירה על מתח בטרייספס והורדת עומס ממפרקי המרפק.","כופפו באיטיות מרפקים והורידו את הגוף לכיוון הרצפה עד שהמרפקים בזווית של כ-90 מעלות.","בהגיעכם לנקודה התחתונה של התנועה, דחפו על הכיסא ליישור המרפקים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.","Slide your butt off the front of the chair with your legs extended in front of you.","Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.","Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.","Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на край стула или скамьи, положив руки рядом с бедрами, пальцами вперед.","Сдвиньте задницу с передней части стула, вытянув ноги перед собой.","Выпрямите руки, сохраняя небольшой изгиб в локтях, чтобы сохранить напряжение в трицепсах и локтевых суставах.","Медленно согните локти, чтобы опустить тело к полу, пока локти не окажутся под углом примерно 90 градусов.","Как только вы достигнете нижней точки движения, прижмитесь к стулу, чтобы выпрямить локти и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el borde de una silla o banco con las manos junto a las caderas, los dedos apuntando hacia adelante.","Desliza los glúteos fuera del frente de la silla con las piernas extendidas frente a ti.","Estira los brazos, manteniendo una ligera flexión en los codos para conservar la tensión en los tríceps y aliviarla en las articulaciones del codo.","Flexiona lentamente los codos para bajar el cuerpo hacia el suelo hasta que los codos formen un ángulo de aproximadamente 90 grados.","Cuando llegues al punto más bajo del movimiento, empuja hacia abajo contra la silla para estirar los codos, volviendo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0816","name":"triceps press","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0816-fSrPP6B.jpg","gif_url":"videos/0816-fSrPP6B.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וברכיים כפופות מעט.","מתחו את הידיים ישר לפניכם, מקבילות לרצפה.","כופפו מרפקים והורידו את הגוף לכיוון הרצפה, תוך שמירה על הזרועות העליונות צמודות לגוף.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground.","Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Вытяните руки прямо перед собой, параллельно земле.","Согните локти и опустите тело к земле, держа плечи близко к бокам.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Extiende los brazos rectos frente a ti, paralelos al suelo.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la parte superior de los brazos cerca de los costados.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0817","name":"triceps stretch","category":"upper arms","body_part":"upper arms","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0817-uOV3Itw.jpg","gif_url":"videos/0817-uOV3Itw.gif","instruction_steps":{"he":["עמדו או שבו זקוף עם גב ישר.","מתחו יד אחת מעל הראש, בכיפוף המרפק.","הניחו את היד הנגדית על המרפק הכפוף ומשכו אותו בעדינות לכיוון הראש.","החזיקו את המתיחה 15–30 שניות, בתחושת מתיחה עדינה בטרייספס.","שחררו את המתיחה וחזרו עליה ביד השנייה."],"en":["Stand or sit upright with your back straight.","Extend one arm overhead, bending it at the elbow.","Place your opposite hand on the bent elbow and gently pull it towards your head.","Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.","Release the stretch and repeat on the other arm."],"ru":["Встаньте или сядьте прямо, спина прямая.","Вытяните одну руку над головой, согнув ее в локте.","Положите противоположную руку на согнутый локоть и осторожно потяните ее к голове.","Удерживайте растяжку 15–30 секунд, ощущая легкое растяжение в трицепсе.","Освободите растяжку и повторите то же самое для другой руки."],"es":["Ponte de pie o siéntate erguido con la espalda recta.","Extiende un brazo por encima de la cabeza, flexionándolo por el codo.","Coloca la mano opuesta sobre el codo flexionado y tira de él suavemente hacia tu cabeza.","Mantén el estiramiento de 15 a 30 segundos, sintiendo un estiramiento suave en el tríceps.","Suelta el estiramiento y repite con el otro brazo."]}},{"id":"0871","name":"tuck crunch","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0871-BMMolZ3.jpg","gif_url":"videos/0871-BMMolZ3.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים מאחורי הראש עם מרפקים פונים החוצה.","תוך הפעלת שרירי הבטן, הרימו את השכמות מהרצפה והביאו את הברכיים לכיוון החזה, ובו-זמנית גלגלו את פלג הגוף העליון לכיוון הברכיים.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את השכמות ויישרו את הרגליים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.","Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, поднимите лопатки от земли и подтяните колени к груди, одновременно сгибая верхнюю часть тела к коленям.","Задержитесь на мгновение в верхней точке, затем медленно опустите лопатки и вытяните ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta los omóplatos del suelo y lleva las rodillas hacia el pecho, curvando al mismo tiempo la parte superior del cuerpo hacia las rodillas.","Haz una pausa de un momento en la parte superior, luego baja lentamente los omóplatos y extiende las piernas de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0818","name":"twin handle parallel grip lat pulldown","category":"back","body_part":"back","equipment":"cable","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0818-rkg41Fb.jpg","gif_url":"videos/0818-rkg41Fb.gif","instruction_steps":{"he":["כווננו את גובה המושב והתמקמו מול מכשיר הכבלים.","אחזו בידיות באחיזה עליונה, ידיים ברוחב כתפיים.","שבו ומקמו את הירכיים מתחת לכריות הירכיים, תוך שמירה על כפות רגליים על הרצפה.","היטו מעט לאחור ושמרו על חזה מורם, עם עמוד שדרה ניטרלי.","משכו את הידיות מטה לכיוון החזה העליון, בכיווץ השכמות זו לזו.","עצרו לרגע בנקודה התחתונה של התנועה, בהרגשת הכיווץ ברחב הגבי.","שחררו באיטיות את הידיות וחזרו לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Adjust the seat height and position yourself facing the cable machine.","Grasp the handles with an overhand grip, hands shoulder-width apart.","Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.","Lean back slightly and keep your chest up, maintaining a neutral spine.","Pull the handles down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Отрегулируйте высоту сиденья и расположитесь лицом к канатной машине.","Возьмитесь за рукоятки хватом сверху, руки на ширине плеч.","Сядьте и расположите бедра под подушечками для бедер, удерживая ступни ровно на полу.","Слегка откиньтесь назад и держите грудь вверх, сохраняя нейтральное положение позвоночника.","Потяните ручки вниз к верхней части груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, чувствуя сокращение широчайших мышц.","Медленно отпустите ручки и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ajusta la altura del asiento y colócate de frente a la máquina de cable.","Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros.","Siéntate y coloca los muslos debajo de las almohadillas para muslos, manteniendo los pies planos sobre el suelo.","Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando una columna neutral.","Tira de las asas hacia la parte superior del pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.","Suelta lentamente las asas y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1466","name":"twist hip lift","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","hamstrings"],"target":"glutes","image":"images/1466-AX1kB0o.jpg","gif_url":"videos/1466-AX1kB0o.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","הניחו את הידיים לצידי הגוף לתמיכה.","הפעילו את הישבן והרימו את האגן מהרצפה, ביצירת קו ישר מהברכיים ועד הכתפיים.","תוך שמירה על אגן מורם, סובבו את פלג הגוף התחתון ימינה, בהבאת הברכיים לכיוון הרצפה.","חזרו לנקודת ההתחלה וחזרו על הסיבוב לצד שמאל.","המשיכו להחליף סיבובים למספר החזרות הרצוי."],"en":["Lie on your back with your knees bent and feet flat on the ground.","Place your hands by your sides for support.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.","Return to the starting position and repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки по бокам для поддержки.","Напрягите ягодицы и поднимите бедра от земли, образуя прямую линию от колен до плеч.","Удерживая бедра поднятыми, поверните нижнюю часть тела вправо, приближая колени к земле.","Вернитесь в исходное положение и повторите поворот в левую сторону.","Продолжайте чередовать скручивания желаемое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos a los lados para mayor apoyo.","Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.","Manteniendo las caderas elevadas, gira la parte inferior del cuerpo hacia el lado derecho, llevando las rodillas hacia el suelo.","Vuelve a la posición inicial y repite el giro hacia el lado izquierdo.","Continúa alternando los giros el número de repeticiones deseado."]}},{"id":"2802","name":"twisted leg raise","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/2802-C0eCeEt.jpg","gif_url":"videos/2802-C0eCeEt.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וידיים לצידי הגוף.","הניחו את הידיים מתחת לישבן לתמיכה.","הפעילו את שרירי הבטן והרימו את שתי הרגליים מהרצפה, כשהן ישרות.","תוך כדי הרמת הרגליים, סובבו את האגן לצד אחד, בהבאת הרגליים לכיוון הכתף הנגדית.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה, הפעם בסיבוב האגן לצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift both legs off the ground, keeping them straight.","As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Лягте на спину, вытянув ноги и положив руки по бокам.","Положите руки под ягодицы для поддержки.","Напрягите пресс и поднимите обе ноги от земли, удерживая их прямыми.","Поднимая ноги, поверните бедра в одну сторону, приближая ноги к противоположному плечу.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите движение, на этот раз повернув бедра в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Coloca las manos debajo de los glúteos como apoyo.","Activa el abdomen y levanta ambas piernas del suelo, manteniéndolas rectas.","Mientras levantas las piernas, gira las caderas hacia un lado, llevando las piernas hacia el hombro opuesto.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el movimiento, esta vez girando las caderas hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"2801","name":"twisted leg raise (female)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/2801-yT9tk17.jpg","gif_url":"videos/2801-yT9tk17.gif","instruction_steps":{"he":["שכבו על הגב עם רגליים ישרות וידיים לצידי הגוף.","כופפו ברכיים והרימו את הרגליים מהרצפה, בהבאתן לכיוון החזה.","תוך כדי הרמת הרגליים, סובבו את האגן לצד אחד, בהבאת הברכיים לכיוון הכתף הנגדית.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התנועה, הפעם בסיבוב האגן לצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and lift your legs off the ground, bringing them towards your chest.","As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Лягте на спину, вытянув ноги и положив руки по бокам.","Согните ноги в коленях и оторвите ноги от земли, поднеся их к груди.","Поднимая ноги, поверните бедра в одну сторону, приближая колени к противоположному плечу.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите движение, на этот раз повернув бедра в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Flexiona las rodillas y levanta las piernas del suelo, llevándolas hacia el pecho.","Mientras levantas las piernas, gira las caderas hacia un lado, llevando las rodillas hacia el hombro opuesto.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el movimiento, esta vez girando las caderas hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"3231","name":"two toe touch (male)","category":"back","body_part":"back","equipment":"body weight","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"spine","image":"images/3231-p195zsJ.jpg","gif_url":"videos/3231-p195zsJ.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וידיים מתוחות לצדדים.","הטו את הגו קדימה מהמותניים, תוך שמירה על גב ישר וברכיים כפופות מעט.","מתחו את שתי הידיים לכיוון קצות האצבעות של הרגליים, תוך שמירה על רגליים ישרות.","עצרו לרגע בנקודה התחתונה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your arms extended out to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with both hands, keeping your legs straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, руки вытянуты в стороны.","Наклонитесь вперед в талии, сохраняя спину прямой и слегка согнутыми в коленях.","Потянитесь обеими руками к пальцам ног, держа ноги прямыми.","Задержитесь на мгновение в нижней точке, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Estira los brazos hacia la punta de los pies con ambas manos, manteniendo las piernas rectas.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1365","name":"upper back stretch","category":"back","body_part":"back","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"upper back","image":"images/1365-GSDioYu.jpg","gif_url":"videos/1365-GSDioYu.gif","instruction_steps":{"he":["עמדו זקוף עם רגליים ברוחב כתפיים.","מתחו את הידיים ישר לפניכם, מקבילות לרצפה.","שלבו את האצבעות וסובבו את כפות הידיים הרחק מהגוף.","הרימו באיטיות את הידיים מעל הראש, כשהן ישרות ומקבילות זו לזו.","תוך כדי הרמת הידיים, כווצו את השכמות זו לזו.","החזיקו את המתיחה 15–30 שניות, ואז שחררו וחזרו."],"en":["Stand up straight with your feet shoulder-width apart.","Extend your arms straight in front of you, parallel to the ground.","Interlace your fingers and rotate your palms away from your body.","Slowly raise your arms overhead, keeping them straight and parallel to each other.","As you raise your arms, squeeze your shoulder blades together.","Hold the stretch for 15-30 seconds, then release and repeat."],"ru":["Встаньте прямо, ноги на ширине плеч.","Вытяните руки прямо перед собой, параллельно земле.","Переплетите пальцы и поверните ладони от тела.","Медленно поднимите руки над головой, держа их прямыми и параллельными друг другу.","Поднимая руки, сведите лопатки вместе.","Удерживайте растяжку 15–30 секунд, затем отпустите и повторите."],"es":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende los brazos rectos frente a ti, paralelos al suelo.","Entrelaza los dedos y gira las palmas alejándolas de tu cuerpo.","Eleva lentamente los brazos por encima de la cabeza, manteniéndolos rectos y paralelos entre sí.","Mientras elevas los brazos, aprieta los omóplatos entre sí.","Mantén el estiramiento de 15 a 30 segundos, luego suelta y repite."]}},{"id":"1366","name":"upward facing dog","category":"back","body_part":"back","equipment":"body weight","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"spine","image":"images/1366-01qpYSe.jpg","gif_url":"videos/1366-01qpYSe.gif","instruction_steps":{"he":["שכבו על הבטן על הרצפה עם רגליים מתוחות לאחור.","הניחו את הידיים על הרצפה ליד הצלעות התחתונות, אצבעות פונות קדימה.","לחצו את הידיים חזק לרצפה ויישרו אותן, בהרמת הגו והירכיים מהרצפה.","גלגלו את הכתפיים לאחור ולמטה, בפתיחת החזה והרמת המבט לכיוון התקרה.","החזיקו את התנוחה כמה נשימות, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie face down on the floor with your legs extended behind you.","Place your hands on the floor next to your lower ribs, fingers pointing forward.","Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.","Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.","Hold this position for a few breaths, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на пол лицом вниз, вытянув ноги позади себя.","Положите руки на пол рядом с нижними ребрами, пальцы направлены вперед.","Плотно прижмите руки к полу и выпрямите руки, отрывая туловище и бедра от земли.","Поверните плечи назад и вниз, раскрывая грудь и подняв взгляд к потолку.","Задержитесь в этом положении на несколько вдохов, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca abajo en el suelo con las piernas extendidas detrás de ti.","Coloca las manos en el suelo junto a las costillas inferiores, con los dedos apuntando hacia adelante.","Presiona las manos firmemente contra el suelo y estira los brazos, levantando el torso y los muslos del suelo.","Lleva los hombros hacia atrás y hacia abajo, abriendo el pecho y elevando la mirada hacia el techo.","Mantén esta posición durante unas cuantas respiraciones, luego baja lentamente el cuerpo de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3420","name":"v-sit on floor","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3420-ZuXu4Eq.jpg","gif_url":"videos/3420-ZuXu4Eq.gif","instruction_steps":{"he":["שבו על הרצפה עם רגליים מתוחות לפניכם.","היטו את הגוף מעט לאחור והרימו את הרגליים מהרצפה, כשהן ישרות.","בו-זמנית, הרימו את פלג הגוף העליון מהרצפה ומתחו את הידיים לכיוון הרגליים.","החזיקו את התנוחה כמה שניות, ואז הורידו באיטיות את פלג הגוף העליון והרגליים חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the floor with your legs extended in front of you.","Lean back slightly and lift your legs off the ground, keeping them straight.","Simultaneously, lift your upper body off the ground and reach your arms towards your legs.","Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на пол, вытянув ноги перед собой.","Слегка откиньтесь назад и оторвите ноги от земли, сохраняя их прямыми.","Одновременно поднимите верхнюю часть тела от земли и протяните руки к ногам.","Удерживайте это положение несколько секунд, затем медленно опустите верхнюю часть тела и ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti.","Inclínate ligeramente hacia atrás y levanta las piernas del suelo, manteniéndolas rectas.","Al mismo tiempo, levanta la parte superior del cuerpo del suelo y extiende los brazos hacia las piernas.","Mantén esta posición durante unos segundos, luego baja lentamente la parte superior del cuerpo y las piernas de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0826","name":"vertical leg raise (on parallel bars)","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0826-ZNgOYQU.jpg","gif_url":"videos/0826-ZNgOYQU.gif","instruction_steps":{"he":["היתלו על המקבילים עם ידיים ישרות לגמרי וגוף ישר.","הפעילו את שרירי הליבה והרימו את הרגליים לפניכם, כשהן ישרות.","המשיכו להרים עד שהרגליים מקבילות לרצפה או מעט גבוה יותר.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from the parallel bars with your arms fully extended and your body straight.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на параллельных брусьях, полностью вытянув руки и выпрямив тело.","Напрягите корпус и поднимите ноги перед собой, сохраняя их прямыми.","Продолжайте поднимать, пока ваши ноги не станут параллельны земле или немного выше.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de las barras paralelas con los brazos completamente extendidos y el cuerpo recto.","Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.","Continúa levantando hasta que las piernas queden paralelas al suelo o un poco más arriba.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2141","name":"walk elliptical cross trainer","category":"cardio","body_part":"cardio","equipment":"elliptical machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/2141-rjtuP6X.jpg","gif_url":"videos/2141-rjtuP6X.gif","instruction_steps":{"he":["כווננו את רמת ההתנגדות והשיפוע של האליפטיקל להגדרות הרצויות.","עלו על דוושות המכשיר ואחזו בידיות בעדינות.","התחילו בדחיפה עם הרגליים ומשיכת הידיות לכיוון הגוף.","המשיכו בתנועה זו, לסירוגין בין דחיפה למשיכה, בחיקוי תנועת הליכה או ריצה.","שמרו על קצב אחיד וליבה מופעלת לאורך כל התרגיל.","המשיכו למשך הזמן הרצוי של אימון האירובי.","הפחיתו בהדרגה את העצימות והמהירות של המכשיר לפני הירידה ממנו."],"en":["Adjust the resistance level and incline of the elliptical machine to your desired settings.","Step onto the pedals of the machine and grip the handles lightly.","Begin by pushing down with your feet and pulling the handles towards your body.","Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion.","Maintain a steady pace and keep your core engaged throughout the exercise.","Continue for the desired duration of your cardio workout.","Gradually decrease the intensity and speed of the machine before stepping off."],"ru":["Отрегулируйте уровень сопротивления и наклон эллиптического тренажера до желаемых настроек.","Встаньте на педали машины и слегка возьмитесь за ручки.","Начните с отталкивания ногами и подтягивания ручек к телу.","Продолжайте это движение, чередуя толкание и вытягивание, чтобы имитировать ходьбу или бег.","Поддерживайте устойчивый темп и задействуйте корпус на протяжении всего упражнения.","Продолжайте кардио-тренировку в течение желаемой продолжительности.","Постепенно уменьшайте интенсивность и скорость тренажера, прежде чем сойти с него."],"es":["Ajusta el nivel de resistencia y la inclinación de la máquina elíptica a los valores deseados.","Sube a los pedales de la máquina y agarra las asas con suavidad.","Comienza empujando hacia abajo con los pies y tirando de las asas hacia tu cuerpo.","Continúa con este movimiento, alternando entre empujar y tirar, para simular un movimiento de caminar o correr.","Mantén un ritmo constante y conserva el core activado durante todo el ejercicio.","Continúa durante la duración deseada de tu entrenamiento cardiovascular.","Disminuye gradualmente la intensidad y la velocidad de la máquina antes de bajarte."]}},{"id":"3655","name":"walking high knees lunge","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/3655-J9zIWig.jpg","gif_url":"videos/3655-J9zIWig.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב אגן.","הרימו את ברך ימין לכיוון החזה גבוה ככל האפשר, תוך איזון על רגל שמאל.","צעדו קדימה עם כף רגל ימין והורידו את הגוף לעמדת מספריים, בכיפוף שתי הברכיים לזווית של 90 מעלות.","דחפו עם כף רגל ימין והביאו את ברך שמאל למעלה לכיוון החזה.","צעדו קדימה עם כף רגל שמאל והורידו את הגוף לעמדת מספריים.","המשיכו להחליף רגליים ולצעוד קדימה במספריים, תוך שמירה על ליבה מופעלת וקצב אחיד.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet hip-width apart.","Lift your right knee up towards your chest as high as you can while balancing on your left leg.","Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle.","Push off with your right foot and bring your left knee up towards your chest.","Step forward with your left foot and lower your body into a lunge position.","Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace.","Repeat for the desired number of repetitions."],"ru":["Встаньте, расставив ноги на ширине плеч.","Поднимите правое колено к груди как можно выше, балансируя на левой ноге.","Сделайте шаг вперед правой ногой и опустите тело в положение выпада, сгибая оба колена под углом 90 градусов.","Оттолкнитесь правой ногой и поднимите левое колено к груди.","Сделайте шаг вперед левой ногой и опустите тело в положение выпада.","Продолжайте чередовать ноги и делать выпады вперед, напрягая корпус и сохраняя постоянный темп.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de la cadera.","Levanta la rodilla derecha hacia el pecho lo más alto que puedas mientras mantienes el equilibrio sobre la pierna izquierda.","Da un paso adelante con el pie derecho y baja el cuerpo a una posición de zancada, flexionando ambas rodillas a un ángulo de 90 grados.","Empújate con el pie derecho y lleva la rodilla izquierda hacia el pecho.","Da un paso adelante con el pie izquierdo y baja el cuerpo a una posición de zancada.","Continúa alternando las piernas y avanzando con zancadas, manteniendo el core activado y un ritmo constante.","Repite el número de repeticiones deseado."]}},{"id":"1460","name":"walking lunge","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1460-IZVHb27.jpg","gif_url":"videos/1460-IZVHb27.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","צעדו קדימה עם רגל ימין, בהורדת הגוף לעמדת מספריים.","שמרו על גו זקוף והברך הקדמית בקו אחד עם הקרסול.","דחפו עם כף רגל ימין והביאו את כף רגל שמאל קדימה, בכניסה לעמדת מספריים עם רגל שמאל.","המשיכו להחליף רגליים ולצעוד קדימה, בקצב מבוקר ואחיד.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Take a step forward with your right leg, lowering your body into a lunge position.","Keep your torso upright and your front knee aligned with your ankle.","Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.","Continue alternating legs and walking forward, maintaining a controlled and steady pace.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Сделайте шаг вперед правой ногой, опуская тело в положение выпада.","Держите туловище прямо, а переднее колено на одной линии с лодыжкой.","Оттолкнитесь правой ногой и вынесите левую ногу вперед, приняв положение выпада левой ногой.","Продолжайте чередовать ноги и идти вперед, сохраняя контролируемый и устойчивый темп.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con la pierna derecha, bajando el cuerpo a una posición de zancada.","Mantén el torso erguido y la rodilla delantera alineada con el tobillo.","Empújate con el pie derecho y lleva el pie izquierdo hacia adelante, entrando en una posición de zancada con la pierna izquierda.","Continúa alternando las piernas y avanzando, manteniendo un ritmo controlado y constante.","Repite el número de repeticiones deseado."]}},{"id":"3666","name":"walking on incline treadmill","category":"cardio","body_part":"cardio","equipment":"leverage machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3666-rjiM4L3.jpg","gif_url":"videos/3666-rjiM4L3.gif","instruction_steps":{"he":["כווננו את רמת השיפוע בהליכון לעצימות הרצויה.","עמדו על ההליכון עם רגליים ברוחב כתפיים.","התחילו ללכת בקצב נוח, תוך הקפדה על טכניקה נכונה.","הפעילו את שרירי הליבה ושמרו על גב ישר לאורך כל התרגיל.","המשיכו ללכת על ההליכון המשופע למשך הזמן הרצוי של אימון האירובי.","הפחיתו בהדרגה את השיפוע והמהירות של ההליכון לצינון לפני העצירה."],"en":["Adjust the incline level on the treadmill to your desired intensity.","Stand on the treadmill with your feet shoulder-width apart.","Start walking at a comfortable pace, ensuring that you maintain proper form.","Engage your core muscles and keep your back straight throughout the exercise.","Continue walking on the incline treadmill for the desired duration of your cardio workout.","Gradually decrease the incline and speed of the treadmill to cool down before stopping."],"ru":["Отрегулируйте уровень наклона беговой дорожки до желаемой интенсивности.","Встаньте на беговую дорожку, поставив ноги на ширине плеч.","Начните ходить в удобном темпе, следя за тем, чтобы поддерживать правильную форму.","Задействуйте мышцы корпуса и держите спину прямо на протяжении всего упражнения.","Продолжайте ходить по наклонной беговой дорожке в течение желаемой продолжительности кардиотренировки.","Постепенно уменьшайте наклон и скорость беговой дорожки, чтобы она остыла перед остановкой."],"es":["Ajusta el nivel de inclinación de la cinta de correr a la intensidad deseada.","Ponte de pie sobre la cinta de correr con los pies separados a la altura de los hombros.","Comienza a caminar a un ritmo cómodo, asegurándote de mantener una forma correcta.","Activa los músculos del core y mantén la espalda recta durante todo el ejercicio.","Continúa caminando en la cinta inclinada durante la duración deseada de tu entrenamiento cardiovascular.","Disminuye gradualmente la inclinación y la velocidad de la cinta para enfriar antes de detenerte."]}},{"id":"2311","name":"walking on stepmill","category":"cardio","body_part":"cardio","equipment":"stepmill machine","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/2311-j9Q5crt.jpg","gif_url":"videos/2311-j9Q5crt.gif","instruction_steps":{"he":["כווננו את מכונת הסטפמיל לרמה נוחה.","עלו על המכשיר והניחו את הידיים על המעקות לתמיכה.","התחילו ללכת — הניחו כף רגל אחת על מדרגה ואז את השנייה, לסירוגין בין הרגליים.","שמרו על יציבה זקופה והפעילו את שרירי הליבה.","המשיכו ללכת למשך הזמן או המרחק הרצוי.","הגבירו בהדרגה את העצימות או המהירות ככל שתרגישו יותר בנוח עם התרגיל.","זכרו לבצע שחרור ומתיחות בסיום התרגיל."],"en":["Adjust the stepmill machine to a comfortable level.","Step onto the machine and place your hands on the handrails for support.","Start walking by placing one foot on a step and then the other, alternating between legs.","Maintain an upright posture and engage your core muscles.","Continue walking for the desired duration or distance.","Gradually increase the intensity or speed as you become more comfortable with the exercise.","Remember to cool down and stretch after completing the exercise."],"ru":["Отрегулируйте шаговую дорожку до комфортного уровня.","Встаньте на тренажер и положите руки на поручни для поддержки.","Начните ходьбу, поставив одну ногу на ступеньку, а затем другую, чередуя ноги.","Сохраняйте вертикальное положение и задействуйте мышцы корпуса.","Продолжайте идти желаемое время или расстояние.","Постепенно увеличивайте интенсивность или скорость по мере того, как вы будете чувствовать себя более комфортно в выполнении упражнения.","Не забудьте остыть и растянуться после завершения упражнения."],"es":["Ajusta la máquina de escalones a un nivel cómodo.","Sube a la máquina y coloca las manos sobre los pasamanos para apoyarte.","Comienza a caminar colocando un pie en un escalón y luego el otro, alternando entre las piernas.","Mantén una postura erguida y activa los músculos del core.","Continúa caminando durante la duración o distancia deseada.","Aumenta gradualmente la intensidad o la velocidad a medida que te sientas más cómodo con el ejercicio.","Recuerda enfriar y estirar después de completar el ejercicio."]}},{"id":"0830","name":"weighted bench dip","category":"upper arms","body_part":"upper arms","equipment":"weighted","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0830-MU9HnE7.jpg","gif_url":"videos/0830-MU9HnE7.gif","instruction_steps":{"he":["שבו על ספסל כשהידיים אוחזות בקצה והאצבעות פונות קדימה.","החליקו את הישבן מהספסל ותמכו במשקל הגוף עם הידיים.","הורידו את הגוף בכיפוף מרפקים עד שהזרועות העליונות מקבילות לרצפה.","דחפו את עצמכם חזרה למעלה לנקודת ההתחלה על ידי יישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Сядьте на скамью, взявшись руками за край, пальцами вперед.","Сдвиньте ягодицы со скамьи, поддерживая вес руками.","Опустите тело, сгибая локти, пока плечи не станут параллельны полу.","Вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Siéntate en un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.","Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"2987","name":"weighted close grip chin-up on dip cage","category":"back","body_part":"back","equipment":"weighted","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/2987-Gk1r408.jpg","gif_url":"videos/2987-Gk1r408.gif","instruction_steps":{"he":["עמדו מול כלוב הדיפים ואחזו במקבילים באחיזה תחתונה, ידיים ברוחב כתפיים.","היתלו על המוטות עם ידיים ישרות לגמרי, כפות רגליים באוויר וגוף ישר.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון המוטות, תוך שמירה על מרפקים צמודים לצידי הגוף.","המשיכו למשוך עד שהסנטר מעל המוטות, ואז עצרו לרגע.","הורידו את הגוף באיטיות חזרה לנקודת ההתחלה, עד יישור מלא של הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.","Hang from the bars with your arms fully extended, feet off the ground, and body straight.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.","Continue pulling until your chin is above the bars, then pause for a moment.","Slowly lower your body back down to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"ru":["Встаньте перед клеткой и возьмитесь за параллельные брусья хватом снизу, руки на ширине плеч.","Повисните на перекладинах, полностью вытянув руки, оторвав ноги от земли и выпрямив тело.","Задействуйте мышцы спины и подтяните тело к перекладинам, держа локти близко к бокам.","Продолжайте тянуть, пока подбородок не окажется над перекладинами, затем сделайте паузу на мгновение.","Медленно опустите тело обратно в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"es":["Ponte de pie frente a la jaula de fondos y agarra las barras paralelas con un agarre supino, con las manos separadas a la altura de los hombros.","Cuélgate de las barras con los brazos completamente extendidos, los pies levantados del suelo y el cuerpo recto.","Activa los músculos de la espalda y tira de tu cuerpo hacia arriba en dirección a las barras, manteniendo los codos cerca de los costados.","Continúa tirando hasta que tu barbilla quede por encima de las barras, luego haz una pausa de un momento.","Baja lentamente el cuerpo de nuevo a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."]}},{"id":"3643","name":"weighted cossack squats (male)","category":"upper legs","body_part":"upper legs","equipment":"weighted","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3643-GWoKnIm.jpg","gif_url":"videos/3643-GWoKnIm.gif","instruction_steps":{"he":["עמדו עם רגליים רחבות מרוחב הכתפיים וקצות האצבעות פונות מעט החוצה.","החזיקו משקל מול החזה בשתי ידיים.","העבירו את המשקל לצד אחד והורידו את הגוף בכיפוף הברך של אותו צד, תוך שמירה על הרגל השנייה ישרה.","רדו נמוך ככל האפשר תוך שמירה על שיווי משקל וחזה מורם.","דחפו דרך העקב של הרגל הכפופה לחזרה לנקודת ההתחלה.","חזרו על התנועה בצד השני, לסירוגין בין הרגליים."],"en":["Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.","Hold a weight in front of your chest with both hands.","Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.","Go as low as you can while maintaining balance and keeping your chest up.","Push through the heel of the bent leg to return to the starting position.","Repeat on the other side, alternating between legs."],"ru":["Встаньте, поставив ноги шире ширины плеч, носки слегка направлены наружу.","Держите гирю перед грудью обеими руками.","Перенесите вес тела в одну сторону и опустите тело, согнув колено той стороны, в которую вы сместились, сохраняя при этом другую ногу прямой.","Опускайтесь как можно ниже, сохраняя равновесие и поднимая грудь вверх.","Оттолкнитесь пяткой согнутой ноги, чтобы вернуться в исходное положение.","Повторите то же самое с другой стороны, чередуя ноги."],"es":["Ponte de pie con los pies más separados que la anchura de los hombros y la punta de los pies apuntando ligeramente hacia afuera.","Sostén un peso frente al pecho con ambas manos.","Traslada tu peso hacia un lado y baja el cuerpo flexionando la rodilla del lado hacia el que te inclinaste, manteniendo la otra pierna recta.","Baja todo lo que puedas mientras mantienes el equilibrio y el pecho elevado.","Empuja con el talón de la pierna flexionada para volver a la posición inicial.","Repite con el otro lado, alternando entre las piernas."]}},{"id":"0832","name":"weighted crunch","category":"waist","body_part":"waist","equipment":"weighted","muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0832-s8nrDXF.jpg","gif_url":"videos/0832-s8nrDXF.gif","instruction_steps":{"he":["שכבו על הגב עם ברכיים כפופות וכפות רגליים על הרצפה.","החזיקו פלטת משקל או משקולת יד על החזה.","הפעילו את שרירי הבטן והרימו את פלג הגוף העליון מהרצפה, בגלגול קדימה עד שהשכמות מתרוממות מהרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Hold a weight plate or dumbbell on your chest.","Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Держите блин или гантель на груди.","Напрягите пресс и поднимите верхнюю часть тела от земли, наклоняясь вперед, пока лопатки не оторвутся от земли.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Sostén un disco de peso o una mancuerna sobre el pecho.","Activa el abdomen y levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que los omóplatos se separen del suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3670","name":"weighted decline sit-up","category":"waist","body_part":"waist","equipment":"weighted","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/3670-EZeDVzO.jpg","gif_url":"videos/3670-EZeDVzO.gif","instruction_steps":{"he":["שכבו על ספסל בשיפוע שלילי כשכפות הרגליים מקובעות מתחת לכריות הרגליים.","מקמו את הידיים מאחורי הראש או מוצלבות על החזה.","הפעילו את שרירי הבטן והרימו באיטיות את פלג הגוף העליון מהספסל, בגלגול קדימה עד שהגו ניצב לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Lie flat on a decline bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Лягте на наклонную скамью, зафиксировав ступни под подушечками для ног.","Положите руки за голову или на грудь.","Напрягите пресс и медленно поднимите верхнюю часть тела со скамьи, наклоняясь вперед, пока туловище не станет перпендикулярно земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Túmbate boca arriba en un banco declinado con los pies sujetos debajo de las almohadillas para los pies.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el abdomen y levanta lentamente la parte superior del cuerpo del banco, curvándote hacia adelante hasta que el torso quede perpendicular al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0833","name":"weighted donkey calf raise","category":"lower legs","body_part":"lower legs","equipment":"weighted","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/0833-LmaFNZS.jpg","gif_url":"videos/0833-LmaFNZS.gif","instruction_steps":{"he":["עמדו על משטח מוגבה כשקצות האצבעות של הרגליים בקצה והעקבים משתלשלים.","אחזו בחפץ יציב לתמיכה.","הרימו את העקבים גבוה ככל האפשר ביישור הקרסוליים.","עצרו לרגע בנקודה העליונה, ואז הורידו את העקבים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand on a raised platform with your toes on the edge and your heels hanging off.","Hold onto a stable object for support.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте на приподнятую платформу, положив пальцы ног на край и свесив пятки.","Держитесь за устойчивый объект для поддержки.","Поднимите пятки как можно выше, вытянув лодыжки.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie sobre una plataforma elevada con la punta de los pies en el borde y los talones colgando.","Sujétate de un objeto estable para mayor apoyo.","Eleva los talones tan alto como puedas extendiendo los tobillos.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1310","name":"weighted drop push up","category":"chest","body_part":"chest","equipment":"weighted","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1310-PSlvNMs.jpg","gif_url":"videos/1310-PSlvNMs.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים מעט רחבות מרוחב הכתפיים ורגליים צמודות.","הורידו את החזה לכיוון הרצפה, תוך שמירה על מרפקים קרובים לגוף.","כשהחזה מעט מעל הרצפה, דחפו את עצמכם למעלה בפיצוץ, בהרמת הידיים מהרצפה.","תוך כדי הדחיפה למעלה, הזיזו במהירות את הידיים לצדדים ומעט קדימה, ותנו לגוף לרדת לכיוון הרצפה.","תפסו את עצמכם עם הידיים בתנוחה הרחבה והורידו מיד את החזה שוב לכיוון הרצפה.","חזרו על תנועת שכיבת הסמיכה, ברדת הגוף ותפיסתו עם הידיים בתנוחה הצרה.","המשיכו להחליף בין תנוחת הידיים הרחבה והצרה למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.","As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.","Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.","Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.","Continue alternating between the wider and narrower hand positions for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, расставив руки чуть шире плеч и поставив ноги вместе.","Опустите грудь к земле, держа локти близко к телу.","Как только ваша грудь окажется над землей, резко подтолкните себя вверх, отрывая руки от земли.","Отжимаясь, быстро разведите руки в стороны и немного вперед, позволяя телу опуститься к земле.","Поймайте себя, поставив руки в более широкое положение, и сразу же снова опустите грудь к земле.","Повторите движение отжимания, опускаясь вниз и ловя руки в более узком положении.","Продолжайте чередовать более широкие и более узкие положения рук необходимое количество повторений."],"es":["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.","Cuando el pecho esté justo por encima del suelo, empújate hacia arriba de forma explosiva, levantando las manos del suelo.","Mientras te empujas hacia arriba, mueve rápidamente las manos hacia los lados y un poco hacia adelante, permitiendo que tu cuerpo caiga hacia el suelo.","Recíbete con las manos en la posición más ancha y baja de nuevo el pecho inmediatamente hacia el suelo.","Repite el movimiento de flexión, bajando y recibiéndote con las manos en la posición más estrecha.","Continúa alternando entre las posiciones de manos más ancha y más estrecha el número de repeticiones deseado."]}},{"id":"2135","name":"weighted front plank","category":"waist","body_part":"waist","equipment":"weighted","muscle_group":"shoulders","secondary_muscles":["shoulders","lower back"],"target":"abs","image":"images/2135-VBAWRPG.jpg","gif_url":"videos/2135-VBAWRPG.gif","instruction_steps":{"he":["התחילו בשכיבה על הבטן על הרצפה.","הניחו את האמות על הרצפה, כשהמרפקים ישר מתחת לכתפיים.","מתחו את הרגליים ישר לאחור, כשקצות האצבעות על הרצפה.","הפעילו את הליבה והרימו את הגוף מהרצפה, באיזון על האמות וקצות האצבעות של הרגליים.","שמרו על הגוף בקו ישר מהראש ועד העקבים.","החזיקו את התנוחה למשך הזמן הרצוי.","הורידו את הגוף חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by lying face down on the floor.","Place your forearms on the ground, with your elbows directly under your shoulders.","Extend your legs straight out behind you, with your toes on the ground.","Engage your core and lift your body off the ground, balancing on your forearms and toes.","Keep your body in a straight line from your head to your heels.","Hold this position for the desired amount of time.","Lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Для начала лягте на пол лицом вниз.","Положите предплечья на землю так, чтобы локти находились прямо под плечами.","Вытяните ноги прямо позади себя, положив пальцы ног на землю.","Напрягите корпус и поднимите тело от земли, балансируя на предплечьях и пальцах ног.","Держите тело на прямой линии от головы до пяток.","Удерживайте это положение желаемое время.","Опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza tumbándote boca abajo en el suelo.","Coloca los antebrazos en el suelo, con los codos justo debajo de los hombros.","Extiende las piernas rectas hacia atrás, con la punta de los pies en el suelo.","Activa el core y levanta el cuerpo del suelo, equilibrándote sobre los antebrazos y la punta de los pies.","Mantén el cuerpo en línea recta desde la cabeza hasta los talones.","Mantén esta posición durante el tiempo deseado.","Baja el cuerpo de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0834","name":"weighted front raise","category":"shoulders","body_part":"shoulders","equipment":"weighted","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"delts","image":"images/0834-e4aFmFY.jpg","gif_url":"videos/0834-e4aFmFY.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים במשקולת יד בכל יד עם כפות ידיים פונות לירכיים.","תוך שמירה על ידיים ישרות, נשפו והרימו את המשקולות לפניכם עד גובה הכתפיים.","עצרו לרגע בנקודה העליונה, ואז שאפו והורידו את המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держите по гантели в каждой руке ладонями к бедрам.","Держа руки прямыми, выдохните и поднимите гантели перед собой до уровня плеч.","Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантели обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos.","Manteniendo los brazos rectos, exhala y levanta las mancuernas frente a ti hasta que queden a la altura de los hombros.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0866","name":"weighted hanging leg-hip raise","category":"waist","body_part":"waist","equipment":"weighted","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0866-QOA0FD0.jpg","gif_url":"videos/0866-QOA0FD0.gif","instruction_steps":{"he":["היתלו על מוט מתח עם ידיים ישרות לגמרי וכפות ידיים פונות מכם.","הפעילו את שרירי הליבה והרימו את הרגליים לפניכם, כשהן ישרות.","המשיכו להרים עד שהרגליים מקבילות לרצפה או מעט גבוה יותר.","עצרו לרגע בנקודה העליונה, ואז הורידו את הרגליים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, полностью вытянув руки и повернув ладони от себя.","Напрягите корпус и поднимите ноги перед собой, сохраняя их прямыми.","Продолжайте поднимать, пока ваши ноги не станут параллельны земле или немного выше.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.","Continúa levantando hasta que las piernas queden paralelas al suelo o un poco más arriba.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0835","name":"weighted hyperextension (on stability ball)","category":"back","body_part":"back","equipment":"weighted","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/0835-8urJS9b.jpg","gif_url":"videos/0835-8urJS9b.gif","instruction_steps":{"he":["התמקמו על הבטן על כדור פיזיו כשהאגן נשען על הכדור וכפות הרגליים נשענות על קיר לייצוב.","מקמו את הידיים מאחורי הראש או הצליבו אותן על החזה.","הפעילו את הליבה והרימו באיטיות את פלג הגוף העליון מהכדור, ביישור הגב עד שהגוף יוצר קו ישר.","עצרו לרגע בנקודה העליונה, ואז הורידו באיטיות את פלג הגוף העליון חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Расположитесь лицом вниз на мяче для стабилизации, опираясь бедрами на мяч, а ступнями упираясь в стену для устойчивости.","Заведите руки за голову или скрестите их на груди.","Напрягите корпус и медленно поднимите верхнюю часть тела с мяча, вытягивая спину, пока тело не образует прямую линию.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Colócate boca abajo sobre un balón de estabilidad con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3641","name":"weighted kneeling step with swing","category":"shoulders","body_part":"shoulders","equipment":"weighted","muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/3641-7uFJuXp.jpg","gif_url":"videos/3641-7uFJuXp.gif","instruction_steps":{"he":["התחילו בכריעה עם ברכיים ברוחב אגן וגב ישר.","החזיקו משקל בכל יד, עם ידיים מתוחות ישר מטה לפניכם.","הפעילו את הליבה והניפו את המשקולות למעלה ומעל הראש, תוך שמירה על ידיים ישרות.","הורידו את המשקולות חזרה לנקודת ההתחלה וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a kneeling position with your knees hip-width apart and your back straight.","Hold a weight in each hand, with your arms extended straight down in front of you.","Engage your core and swing the weights up and overhead, keeping your arms straight.","Lower the weights back down to the starting position and repeat for the desired number of repetitions."],"ru":["Начните в положении стоя на коленях, расставив колени на ширине плеч и выпрямив спину.","Возьмите по гантели в каждую руку, вытянув руки прямо перед собой.","Напрягите корпус и поднимите гири вверх и над головой, держа руки прямыми.","Опустите гири обратно в исходное положение и повторите желаемое количество повторений."],"es":["Comienza en posición de rodillas con las rodillas separadas a la altura de las caderas y la espalda recta.","Sostén un peso en cada mano, con los brazos extendidos rectos hacia abajo frente a ti.","Activa el core y balancea los pesos hacia arriba y por encima de la cabeza, manteniendo los brazos rectos.","Baja los pesos de nuevo a la posición inicial y repite el número de repeticiones deseado."]}},{"id":"3644","name":"weighted lunge with swing","category":"upper legs","body_part":"upper legs","equipment":"weighted","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3644-5WiFcYk.jpg","gif_url":"videos/3644-5WiFcYk.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, אוחזים משקל בכל יד.","צעדו קדימה עם רגל ימין והורידו את הגוף לעמדת מספריים (לאנג').","תוך כדי המספריים קדימה, הניפו את המשקולות קדימה ולמעלה, תוך שמירה על ידיים ישרות.","דחפו עם כף רגל ימין וחזרו לנקודת ההתחלה, בהנפת המשקולות חזרה מטה.","חזרו על התנועה עם כף רגל שמאל והמשיכו להחליף רגליים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, holding a weight in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, swing the weights forward and upward, keeping your arms straight.","Push off with your right foot and return to the starting position, swinging the weights back down.","Repeat with your left foot and continue alternating legs for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, держа в каждой руке по гире.","Сделайте шаг вперед правой ногой, опуская тело в положение выпада.","Делая выпад вперед, делайте махи гантелями вперед и вверх, держа руки прямыми.","Оттолкнитесь правой ногой и вернитесь в исходное положение, опуская гирю обратно.","Повторите то же самое левой ногой и продолжайте чередовать ноги желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un peso en cada mano.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Mientras avanzas en la zancada, balancea los pesos hacia adelante y hacia arriba, manteniendo los brazos rectos.","Empújate con el pie derecho y vuelve a la posición inicial, balanceando los pesos de nuevo hacia abajo.","Repite con el pie izquierdo y continúa alternando las piernas el número de repeticiones deseado."]}},{"id":"3286","name":"weighted muscle up","category":"back","body_part":"back","equipment":"weighted","muscle_group":"biceps","secondary_muscles":["biceps","triceps","shoulders","chest"],"target":"lats","image":"images/3286-JsOV1SU.jpg","gif_url":"videos/3286-JsOV1SU.gif","instruction_steps":{"he":["התחילו בתלייה על מוט מתח עם כפות ידיים פונות מכם וידיים מעט רחבות מרוחב הכתפיים.","הפעילו את הליבה ומשכו את הגוף למעלה לכיוון המוט, כשהחזה מוביל את התנועה.","בהגיעכם לנקודה העליונה של התנועה, החליפו אחיזה כך שכפות הידיים פונות אליכם.","המשיכו למשוך את עצמכם למעלה עד שהחזה מגיע למוט, ואז עצרו לרגע.","הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה, תוך שמירה על שליטה לאורך כל התנועה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest reaches the bar, then pause for a moment.","Slowly lower yourself back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."],"ru":["Начните с подвешивания на перекладине, повернув ладонями от себя и расставив руки чуть шире плеч.","Напрягите корпус и подтяните тело к перекладине, ведя грудью.","Достигнув вершины движения, поменяйте хват так, чтобы ладони были обращены к вам.","Продолжайте подтягиваться до тех пор, пока грудь не достигнет перекладины, затем сделайте паузу на мгновение.","Медленно опуститесь обратно в исходное положение, сохраняя контроль на протяжении всего движения.","Повторите необходимое количество повторений."],"es":["Comienza colgándote de una barra de dominadas con las palmas mirando hacia afuera y las manos un poco más separadas que la anchura de los hombros.","Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.","Al llegar a la parte alta del movimiento, cambia el agarre de modo que las palmas queden hacia ti.","Continúa subiendo hasta que el pecho llegue a la barra, luego haz una pausa de un momento.","Baja lentamente de nuevo a la posición inicial, manteniendo el control durante todo el movimiento.","Repite el número de repeticiones deseado."]}},{"id":"3312","name":"weighted muscle up (on bar)","category":"back","body_part":"back","equipment":"weighted","muscle_group":"biceps","secondary_muscles":["biceps","triceps","shoulders","forearms"],"target":"lats","image":"images/3312-MCkqdKE.jpg","gif_url":"videos/3312-MCkqdKE.gif","instruction_steps":{"he":["התחילו בתלייה על מוט מתח עם כפות ידיים פונות מכם וידיים מעט רחבות מרוחב הכתפיים.","הפעילו את הליבה ומשכו את השכמות מטה ולאחור.","כופפו מרפקים ומשכו את החזה לכיוון המוט, תוך שמירה על גוף ישר.","כשהחזה מגיע למוט, דחפו מטה עם הידיים והובילו את המרפקים לאחור, בהרמת הגוף מעל המוט.","עצרו בנקודה העליונה של התנועה, ואז הורידו את עצמכם באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your elbows and pull your chest towards the bar, keeping your body straight.","Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с подвешивания на перекладине, повернув ладонями от себя и расставив руки чуть шире плеч.","Напрягите корпус и потяните лопатки вниз и назад.","Согните локти и подтяните грудь к перекладине, сохраняя тело прямым.","Как только ваша грудь достигнет перекладины, оттолкнитесь руками и отведите локти назад, поднимая тело над перекладиной.","Сделайте паузу в верхней точке движения, затем медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza colgándote de una barra de dominadas con las palmas mirando hacia afuera y las manos un poco más separadas que la anchura de los hombros.","Activa el core y lleva los omóplatos hacia abajo y atrás.","Flexiona los codos y tira del pecho hacia la barra, manteniendo el cuerpo recto.","Cuando tu pecho llegue a la barra, empuja hacia abajo con las manos y lleva los codos hacia atrás, elevando el cuerpo por encima de la barra.","Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"3290","name":"weighted one hand pull up","category":"back","body_part":"back","equipment":"weighted","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/3290-fXfqg1E.jpg","gif_url":"videos/3290-fXfqg1E.gif","instruction_steps":{"he":["אחזו במוט המתח באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היתלו על המוט עם יד ישרה לגמרי וגוף ישר.","הפעילו את הליבה ומשכו את הגוף למעלה לכיוון המוט בכיפוף המרפק וכיווץ שרירי הגב.","המשיכו למשוך עד שהסנטר מעל המוט.","הורידו את הגוף חזרה לנקודת ההתחלה בשליטה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arm fully extended and your body straight.","Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."],"ru":["Возьмитесь за перекладину хватом сверху, на расстоянии чуть шире плеч.","Повисните на перекладине, полностью вытянув руку и выпрямив тело.","Напрягите корпус и подтяните тело к перекладине, сгибая локоть и напрягая мышцы спины.","Продолжайте тянуть, пока подбородок не окажется над перекладиной.","Опустите тело обратно в исходное положение, контролируя его.","Повторите необходимое количество повторений."],"es":["Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.","Cuélgate de la barra con un brazo completamente extendido y el cuerpo recto.","Activa el core y tira de tu cuerpo hacia arriba en dirección a la barra flexionando el codo y contrayendo los músculos de la espalda.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Baja el cuerpo de nuevo a la posición inicial con control.","Repite el número de repeticiones deseado."]}},{"id":"0840","name":"weighted overhead crunch (on stability ball)","category":"waist","body_part":"waist","equipment":"weighted","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0840-xmM75XG.jpg","gif_url":"videos/0840-xmM75XG.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","החזיקו פלטת משקל או משקולת יד בשתי ידיים ומתחו את הידיים מעל הראש.","הפעילו את שרירי הבטן וגלגלו באיטיות את הגו קדימה, בהבאת החזה לכיוון הברכיים.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגו באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands and extend your arms overhead.","Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your torso back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч, поставив ступни на землю и согнув колени под углом 90 градусов.","Возьмите блин или гантель обеими руками и вытяните руки над головой.","Напрягите пресс и медленно согните туловище вперед, приближая грудь к коленям.","Задержитесь на мгновение в верхней точке, затем медленно опустите туловище обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sostén un disco de peso o una mancuerna con ambas manos y extiende los brazos por encima de la cabeza.","Activa el abdomen y curva lentamente el torso hacia adelante, llevando el pecho hacia las rodillas.","Haz una pausa de un momento en la parte superior, luego baja lentamente el torso de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0841","name":"weighted pull-up","category":"back","body_part":"back","equipment":"weighted","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0841-HMzLjXx.jpg","gif_url":"videos/0841-HMzLjXx.gif","instruction_steps":{"he":["אחזו במוט המתח באחיזה עליונה, מעט רחבה מרוחב הכתפיים.","היתלו על המוט עם ידיים ישרות לגמרי וגוף ישר.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון המוט, תוך שמירה על מרפקים קרובים לגוף.","המשיכו למשוך עד שהסנטר מעל המוט.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Возьмитесь за перекладину хватом сверху, на расстоянии чуть шире плеч.","Повисните на перекладине, полностью вытянув руки и выпрямив тело.","Напрягите мышцы спины и подтяните тело к перекладине, держа локти близко к телу.","Продолжайте тянуть, пока подбородок не окажется над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.","Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0844","name":"weighted round arm","category":"shoulders","body_part":"shoulders","equipment":"weighted","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0844-VLYXo8S.jpg","gif_url":"videos/0844-VLYXo8S.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד.","כופפו ברכיים מעט והטו את הגו קדימה מהירכיים, תוך שמירה על גב ישר.","הרימו את הידיים לצדדים, עם כיפוף קל במרפקים.","המשיכו להרים את הידיים עד שהן מקבילות לרצפה.","עצרו לרגע בנקודה העליונה, ואז הורידו את הידיים באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows.","Continue lifting your arms until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Поднимите руки в стороны, сохраняя небольшой изгиб в локтях.","Продолжайте поднимать руки, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Eleva los brazos hacia los lados, manteniendo una ligera flexión en los codos.","Continúa elevando los brazos hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0846","name":"weighted russian twist","category":"waist","body_part":"waist","equipment":"weighted","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0846-fZFZ704.jpg","gif_url":"videos/0846-fZFZ704.gif","instruction_steps":{"he":["שבו על הרצפה עם ברכיים כפופות וכפות רגליים על הרצפה.","החזיקו משקל או כדור כוח בשתי ידיים מול החזה.","היטו את הגוף מעט לאחור, תוך שמירה על גב ישר וליבה מופעלת.","סובבו באיטיות את הגו ימינה, בהבאת המשקל או כדור הכוח לכיוון הרצפה בצד ימין.","עצרו לרגע, ואז סובבו את הגו שמאלה, בהבאת המשקל או כדור הכוח לכיוון הרצפה בצד שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Sit on the ground with your knees bent and your feet flat on the floor.","Hold a weight or medicine ball with both hands in front of your chest.","Lean back slightly, keeping your back straight and your core engaged.","Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.","Continue alternating sides for the desired number of repetitions."],"ru":["Сядьте на пол, согните колени и поставьте ступни на пол.","Держите гирю или медицинский мяч обеими руками перед грудью.","Слегка откиньтесь назад, сохраняя спину прямой и напряженный корпус.","Медленно поверните туловище вправо, приближая гирю или медицинский мяч к полу с правой стороны.","Сделайте паузу на мгновение, затем поверните туловище влево, перемещая гирю или медицинский мяч к полу с левой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.","Sostén un peso o un balón medicinal con ambas manos frente al pecho.","Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado.","Gira lentamente el torso hacia la derecha, llevando el peso o el balón medicinal hacia el suelo a tu lado derecho.","Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso o el balón medicinal hacia el suelo a tu lado izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0845","name":"weighted russian twist (legs up)","category":"waist","body_part":"waist","equipment":"weighted","muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/0845-WU9BLIs.jpg","gif_url":"videos/0845-WU9BLIs.gif","instruction_steps":{"he":["שבו על הרצפה עם ברכיים כפופות וכפות רגליים מורמות מהרצפה, כשהרגליים צמודות.","החזיקו את המשקל בשתי ידיים מול החזה, תוך שמירה על מרפקים כפופים מעט.","היטו את הגוף מעט לאחור להפעלת שרירי הליבה.","סובבו את הגו ימינה, בהבאת המשקל לכיוון הרצפה בצד ימין.","עצרו לרגע, ואז סובבו את הגו שמאלה, בהבאת המשקל לכיוון הרצפה בצד שמאל.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.","Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the ground on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.","Continue alternating sides for the desired number of repetitions."],"ru":["Сядьте на землю, согните колени и оторвите ступни от земли, держа ноги вместе.","Держите вес обеими руками перед грудью, слегка согнув локти.","Слегка откиньтесь назад, чтобы задействовать мышцы корпуса.","Поверните туловище вправо, перенося вес тела на землю с правой стороны.","Сделайте паузу на мгновение, затем поверните туловище влево, перенося вес тела на землю с левой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Siéntate en el suelo con las rodillas flexionadas y los pies levantados del suelo, manteniendo las piernas juntas.","Sostén el peso con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados.","Inclínate ligeramente hacia atrás para activar los músculos del core.","Gira el torso hacia la derecha, llevando el peso hacia el suelo a tu lado derecho.","Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso hacia el suelo a tu lado izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"2371","name":"weighted russian twist v. 2","category":"waist","body_part":"waist","equipment":"weighted","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/2371-YIUAtYf.jpg","gif_url":"videos/2371-YIUAtYf.gif","instruction_steps":{"he":["שבו על הרצפה עם ברכיים כפופות וכפות רגליים על הרצפה.","החזיקו את המשקל בשתי ידיים מול החזה.","היטו את הגוף מעט לאחור להפעלת שרירי הליבה.","סובבו את הגו ימינה, בהבאת המשקל לצד ימין של הגוף.","עצרו לרגע, ואז סובבו את הגו שמאלה, בהבאת המשקל לצד שמאל של הגוף.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Sit on the ground with your knees bent and feet flat on the floor.","Hold the weight with both hands in front of your chest.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."],"ru":["Сядьте на пол, согните колени и поставьте ступни на пол.","Держите гирю обеими руками перед грудью.","Слегка откиньтесь назад, чтобы задействовать мышцы корпуса.","Поверните туловище вправо, перенеся вес на правую сторону тела.","Сделайте паузу на мгновение, затем поверните туловище влево, перенеся вес на левую сторону тела.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.","Sostén el peso con ambas manos frente al pecho.","Inclínate ligeramente hacia atrás para activar los músculos del core.","Gira el torso hacia la derecha, llevando el peso hacia el lado derecho de tu cuerpo.","Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso hacia el lado izquierdo de tu cuerpo.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0847","name":"weighted seated bicep curl (on stability ball)","category":"upper arms","body_part":"upper arms","equipment":"medicine ball","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0847-b4b6afT.jpg","gif_url":"videos/0847-b4b6afT.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וגב ישר.","החזיקו כדור כוח באחיזה תחתונה, כפות ידיים כלפי מעלה, ותנו לידיים להשתלשל לצידי הגוף.","תוך שמירה על הזרועות העליונות ללא תזוזה, נשפו וכופפו את כדור הכוח למעלה לכיוון הכתפיים.","עצרו לרגע בנקודה העליונה, תוך כיווץ הבייספס.","שאפו והורידו את כדור הכוח באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides.","Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the medicine ball back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на мяч, поставив ноги на землю и выпрямив спину.","Держите медицинский мяч хватом снизу ладонями вверх, руки свисают по бокам.","Удерживая плечи неподвижно, выдохните и поднимите медицинский мяч к плечам.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите медицинский мяч обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.","Sostén un balón medicinal con un agarre supino, las palmas hacia arriba, y deja que los brazos cuelguen a los lados.","Manteniendo la parte superior de los brazos quieta, exhala y curva el balón medicinal hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente el balón medicinal de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0849","name":"weighted seated twist (on stability ball)","category":"waist","body_part":"waist","equipment":"weighted","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0849-s34Y4LR.jpg","gif_url":"videos/0849-s34Y4LR.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם כפות רגליים על הרצפה וברכיים כפופות בזווית של 90 מעלות.","החזיקו פלטת משקל או משקולת יד בשתי ידיים, קרוב לחזה.","הפעילו את הליבה וסובבו באיטיות את הגו לצד אחד, תוך שמירה על אגן יציב.","עצרו לרגע בסוף הסיבוב, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על הסיבוב לצד השני.","המשיכו להחליף צדדים למספר החזרות הרצוי."],"en":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands close to your chest.","Engage your core and slowly rotate your torso to one side, keeping your hips stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."],"ru":["Сядьте на мяч, поставив ступни на землю и согнув колени под углом 90 градусов.","Держите блин или гантель обеими руками близко к груди.","Напрягите корпус и медленно поверните туловище в сторону, сохраняя бедра устойчивыми.","Сделайте небольшую паузу в конце вращения, затем медленно вернитесь в исходное положение.","Повторите поворот в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"es":["Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sostén un disco de peso o una mancuerna con ambas manos cerca del pecho.","Activa el core y rota lentamente el torso hacia un lado, manteniendo las caderas estables.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite la rotación hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]}},{"id":"0850","name":"weighted side bend (on stability ball)","category":"waist","body_part":"waist","equipment":"weighted","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0850-6bOA1Oi.jpg","gif_url":"videos/0850-6bOA1Oi.gif","instruction_steps":{"he":["שבו על כדור פיזיו עם רגליים ברוחב כתפיים וכפות רגליים על הרצפה.","החזיקו משקל ביד אחת והניחו את היד השנייה על המותן.","הפעילו את הליבה והיטו את הגוף באיטיות הצידה לכיוון הצד עם המשקל, תוך שמירה על גב ישר.","עצרו לרגע בנקודה התחתונה, ואז חזרו באיטיות לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי, ואז החליפו צד."],"en":["Sit on a stability ball with your feet shoulder-width apart and flat on the ground.","Hold a weight in one hand and place your other hand on your hip.","Engage your core and slowly bend sideways towards the weighted side, keeping your back straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"ru":["Сядьте на мяч, поставив ноги на ширине плеч и прижавшись к земле.","Возьмите гирю в одну руку, а другую руку положите на бедро.","Напрягите корпус и медленно наклонитесь в сторону отягощенной стороны, сохраняя спину прямой.","Задержитесь на мгновение в нижней точке, затем медленно вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"es":["Siéntate sobre un balón de estabilidad con los pies separados a la altura de los hombros y planos sobre el suelo.","Sostén un peso en una mano y coloca la otra mano sobre la cadera.","Activa el core e inclínate lentamente hacia el lado del peso, manteniendo la espalda recta.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]}},{"id":"0851","name":"weighted sissy squat","category":"upper legs","body_part":"upper legs","equipment":"weighted","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0851-0lQnxMZ.jpg","gif_url":"videos/0851-0lQnxMZ.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים וקצות האצבעות של הרגליים פונות מעט החוצה.","החזיקו משקל מול החזה בשתי הידיים, או הניחו מוט על הגב העליון.","תוך שמירה על חזה מורם וליבה מופעלת, הורידו את הגוף באיטיות בכיפוף ברכיים וירכיים.","המשיכו לרדת עד שהירכיים מקבילות לרצפה או נמוך ככל שנוח לכם.","עצרו לרגע בנקודה התחתונה, ואז דחפו דרך העקבים כדי לחזור לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Hold a weight in front of your chest with both hands, or place a barbell across your upper back.","Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips.","Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","Держите гирю перед грудью обеими руками или положите штангу на верхнюю часть спины.","Удерживая грудь поднятой и напряженным корпус, медленно опустите тело вниз, сгибая колени и бедра.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sostén un peso frente al pecho con ambas manos, o coloca una barra sobre la parte superior de la espalda.","Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y las caderas.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0852","name":"weighted squat","category":"upper legs","body_part":"upper legs","equipment":"weighted","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0852-JZuApnB.jpg","gif_url":"videos/0852-JZuApnB.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים, קצות האצבעות של הרגליים פונות מעט החוצה.","החזיקו משקל מול החזה או על הכתפיים.","הפעילו את הליבה ושמרו על חזה מורם תוך הורדת האגן למטה ולאחור, כאילו אתם מתיישבים על כיסא.","רדו עד שהירכיים מקבילות לרצפה, או עד כמה שנוח לכם.","דחפו דרך העקבים לחזרה לעמידה, בכיווץ הישבן בנקודה העליונה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold a weight in front of your chest or on your shoulders.","Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Push through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","Держите вес перед грудью или на плечах.","Напрягите корпус и держите грудь поднятой, опуская бедра вниз и назад, как будто вы садитесь на стул.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Оттолкнитесь пятками, чтобы встать, сжимая ягодицы в верхней части.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Sostén un peso frente al pecho o sobre los hombros.","Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte superior.","Repite el número de repeticiones deseado."]}},{"id":"0853","name":"weighted standing curl","category":"upper arms","body_part":"upper arms","equipment":"weighted","muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0853-M5Y7GPg.jpg","gif_url":"videos/0853-M5Y7GPg.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקולת יד בכל יד, כפות ידיים פונות קדימה.","שמרו על מרפקים צמודים לגו ונשפו תוך כיפוף המשקולות לגובה הכתפיים.","עצרו לרגע בנקודה העליונה, ואז שאפו תוך הורדת המשקולות באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level.","Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями вперед.","Держите локти близко к туловищу и на выдохе поднимайте гирю до уровня плеч.","Сделайте паузу на мгновение в верхней точке, затем на вдохе медленно опускайте гири обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.","Mantén los codos cerca del torso y exhala mientras curvas los pesos hasta la altura de los hombros.","Haz una pausa de un momento en la parte superior, luego inhala mientras bajas lentamente los pesos de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0854","name":"weighted standing hand squeeze","category":"lower arms","body_part":"lower arms","equipment":"weighted","muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"forearms","image":"images/0854-bjqbauy.jpg","gif_url":"videos/0854-bjqbauy.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו משקל בכל יד.","מתחו את הידיים ישר לפניכם, כפות ידיים פונות זו לזו.","לחצו את הידיים זו לזו חזק ככל האפשר, בהפעלת האמות.","החזיקו את הלחיצה כמה שניות, ואז שחררו.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a weight in each hand.","Extend your arms straight in front of you, palms facing each other.","Squeeze your hands together as hard as you can, engaging your forearms.","Hold the squeeze for a few seconds, then release.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гире.","Вытяните руки прямо перед собой, ладони обращены друг к другу.","Сожмите руки вместе как можно сильнее, задействуя предплечья.","Удерживайте сжатие несколько секунд, затем отпустите.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén un peso en cada mano.","Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí.","Aprieta las manos entre sí con la mayor fuerza posible, activando los antebrazos.","Mantén la contracción durante unos segundos y luego suelta.","Repite el número de repeticiones deseado."]}},{"id":"3313","name":"weighted straight bar dip","category":"chest","body_part":"chest","equipment":"weighted","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/3313-Ff18ItA.jpg","gif_url":"videos/3313-Ff18ItA.gif","instruction_steps":{"he":["התמקמו בין מקבילים עם ידיים ישרות לגמרי וגוף ישר.","הורידו את הגוף בכיפוף מרפקים עד שהזרועות העליונות מקבילות לרצפה.","עצרו לרגע, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Position yourself between parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Встаньте между параллельными брусьями, полностью вытянув руки и выпрямив тело.","Опустите тело, сгибая локти, пока плечи не станут параллельны земле.","Сделайте паузу на мгновение, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Colócate entre las barras paralelas con los brazos completamente extendidos y el cuerpo recto.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"3642","name":"weighted stretch lunge","category":"upper legs","body_part":"upper legs","equipment":"weighted","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3642-13VW2VO.jpg","gif_url":"videos/3642-13VW2VO.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים.","צעדו קדימה עם רגל ימין, תוך שמירה על גב ישר.","הורידו את הגוף בכיפוף ברכיים עד שירך ימין מקבילה לרצפה.","דחפו דרך עקב ימין כדי לחזור לנקודת ההתחלה.","חזרו על התנועה עם רגל שמאל.","המשיכו להחליף רגליים למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart.","Take a step forward with your right foot, keeping your back straight.","Lower your body by bending your knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч.","Сделайте шаг вперед правой ногой, держа спину прямо.","Опустите тело, сгибая колени, пока правое бедро не станет параллельно земле.","Оттолкнитесь правой пяткой, чтобы вернуться в исходное положение.","Повторите с левой ногой.","Продолжайте чередовать ноги желаемое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con el pie derecho, manteniendo la espalda recta.","Baja el cuerpo flexionando las rodillas hasta que el muslo derecho quede paralelo al suelo.","Empuja con el talón derecho para regresar a la posición inicial.","Repite con la pierna izquierda.","Continúa alternando las piernas durante el número de repeticiones deseado."]}},{"id":"0856","name":"weighted svend press","category":"chest","body_part":"chest","equipment":"weighted","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0856-I1OBLnn.jpg","gif_url":"videos/0856-I1OBLnn.gif","instruction_steps":{"he":["עמדו עם רגליים ברוחב כתפיים והחזיקו פלטת משקל מול החזה בשתי ידיים.","שמרו על מרפקים כפופים מעט וכפות ידיים פונות זו לזו.","לחצו את פלטת המשקל ישר לפניכם, עד יישור מלא של הידיים.","עצרו לרגע בסוף התנועה, ואז החזירו באיטיות את פלטת המשקל לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.","Keep your elbows slightly bent and your palms facing each other.","Press the weight plate straight out in front of you, fully extending your arms.","Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте, ноги на ширине плеч, обеими руками держите блин перед грудью.","Держите локти слегка согнутыми и ладонями друг к другу.","Выжмите блин прямо перед собой, полностью выпрямив руки.","Сделайте небольшую паузу в конце движения, затем медленно верните блин в исходное положение.","Повторите необходимое количество повторений."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén un disco de peso frente al pecho con ambas manos.","Mantén los codos ligeramente flexionados y las palmas mirándose entre sí.","Empuja el disco de peso recto hacia adelante, extendiendo completamente los brazos.","Haz una pausa de un momento al final del movimiento, luego lleva lentamente el disco de peso de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1754","name":"weighted three bench dips","category":"upper arms","body_part":"upper arms","equipment":"weighted","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1754-gtO1ErP.jpg","gif_url":"videos/1754-gtO1ErP.gif","instruction_steps":{"he":["שבו על קצה ספסל כשהידיים אוחזות בקצה, אצבעות פונות קדימה.","צעדו עם כפות הרגליים קדימה, בהחלקת הישבן מהספסל ותמיכת המשקל על הידיים.","הורידו את הגוף בכיפוף מרפקים, תוך שמירה על הגב קרוב לספסל.","עצרו לרגע בנקודה התחתונה, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms.","Lower your body by bending your elbows, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"ru":["Сядьте на край скамьи, взявшись руками за край, пальцами вперед.","Пройдите ногами вперед, отрывая ягодицы от скамьи и поддерживая свой вес руками.","Опустите корпус, согнув локти, держа спину близко к скамье.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"es":["Siéntate en el borde de un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.","Camina con los pies hacia adelante, deslizando los glúteos fuera del banco y sosteniendo tu peso con los brazos.","Baja el cuerpo flexionando los codos, manteniendo la espalda cerca del banco.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1755","name":"weighted tricep dips","category":"upper arms","body_part":"upper arms","equipment":"weighted","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1755-bZq4bwK.jpg","gif_url":"videos/1755-bZq4bwK.gif","instruction_steps":{"he":["שבו על קצה ספסל או כיסא כשהידיים אוחזות בקצה לצידי האגן.","החליקו את הישבן מקדמת הספסל כשהרגליים מתוחות לפניכם.","שמרו על הגב קרוב לספסל ועל כיפוף קל במרפקים.","הורידו את הגוף בכיפוף מרפקים עד שהזרועות העליונות מקבילות לרצפה.","דחפו את עצמכם חזרה למעלה לנקודת ההתחלה על ידי יישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the front of the bench with your legs extended in front of you.","Keep your back close to the bench and your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Сядьте на край скамьи или стула, взявшись руками за край рядом с бедрами.","Сдвиньте ягодицы с передней части скамьи, вытянув ноги перед собой.","Держите спину близко к скамье, а локти слегка согнуты.","Опустите тело, сгибая локти, пока плечи не станут параллельны полу.","Вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas.","Desliza los glúteos fuera del frente del banco con las piernas extendidas frente a ti.","Mantén la espalda cerca del banco y los codos ligeramente flexionados.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1767","name":"weighted triceps dip on high parallel bars","category":"upper arms","body_part":"upper arms","equipment":"weighted","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1767-K1vlode.jpg","gif_url":"videos/1767-K1vlode.gif","instruction_steps":{"he":["התמקמו בין שני מקבילים עם ידיים אוחזות במוטות וידיים ישרות לגמרי.","כופפו מרפקים והורידו את הגוף עד שהזרועות העליונות מקבילות לרצפה.","עצרו לרגע, ואז דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Встаньте между двумя параллельными брусьями, держась руками за брусья и полностью вытянув руки.","Согните локти и опустите тело до тех пор, пока плечи не станут параллельны земле.","Сделайте паузу на мгновение, затем оттолкнитесь ладонями, чтобы выпрямить руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Colócate entre dos barras paralelas con las manos agarrando las barras y los brazos completamente extendidos.","Flexiona los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo.","Haz una pausa de un momento, luego empuja con las palmas para estirar los brazos y volver a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"0857","name":"wheel rollerout","category":"waist","body_part":"waist","equipment":"wheel roller","muscle_group":"lower back","secondary_muscles":["lower back"],"target":"abs","image":"images/0857-NAgVB3t.jpg","gif_url":"videos/0857-NAgVB3t.gif","instruction_steps":{"he":["כרעו על הרצפה והניחו את גלגל הבטן לפניכם.","הניחו את הידיים על ידיות גלגל הבטן ומתחו את הידיים ישר לפניכם.","הפעילו את שרירי הליבה וגלגלו באיטיות את הגלגל קדימה, תוך שמירה על גב ישר ובטן מכווצת.","המשיכו להתגלגל קדימה עד שהגוף מתוח לגמרי והידיים מעל הראש.","עצרו לרגע, ואז גלגלו באיטיות את הגלגל חזרה לכיוון הברכיים, תוך שליטה ובטן מכווצת.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Kneel on the floor and place the wheel roller in front of you.","Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.","Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.","Repeat for the desired number of repetitions."],"ru":["Встаньте на колени и поместите ролик перед собой.","Положите руки на ручки роликового колеса и вытяните руки прямо перед собой.","Задействуйте мышцы корпуса и медленно катите колесо вперед, сохраняя спину прямой и пресс напряженным.","Продолжайте перекатываться вперед до тех пор, пока ваше тело не будет полностью выпрямлено, а руки не окажутся над головой.","Сделайте паузу на мгновение, затем медленно поверните колесо обратно к коленям, сохраняя контроль и напрягая пресс.","Повторите необходимое количество повторений."],"es":["Arrodíllate en el suelo y coloca el rodillo frente a ti.","Coloca las manos en las asas del rodillo y extiende los brazos rectos hacia adelante.","Activa los músculos del core y haz rodar lentamente el rodillo hacia adelante, manteniendo la espalda recta y el abdomen contraído.","Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.","Haz una pausa de un momento, luego haz rodar lentamente el rodillo de regreso hacia las rodillas, manteniendo el control y el abdomen activado.","Repite el número de repeticiones deseado."]}},{"id":"3637","name":"wheel run","category":"cardio","body_part":"cardio","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3637-km2Ljzj.jpg","gif_url":"videos/3637-km2Ljzj.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק עם הידיים על הגלגל והגוף ישר.","הפעילו את הליבה והתחילו לגלגל את הגלגל קדימה במתיחת הידיים.","המשיכו להתגלגל עד שהגוף מתוח לגמרי והידיים מעל הראש.","הפכו את התנועה במשיכת הגלגל חזרה לכיוון הגוף, בעזרת הליבה והידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a plank position with your hands on the wheel and your body straight.","Engage your core and start rolling the wheel forward by extending your arms.","Continue rolling until your body is fully extended and your arms are overhead.","Reverse the movement by pulling the wheel back towards your body, using your core and arms.","Repeat for the desired number of repetitions."],"ru":["Начните с положения планки, положив руки на руль и выпрямив тело.","Включите корпус и начните катить колесо вперед, вытягивая руки.","Продолжайте перекатываться до тех пор, пока ваше тело не будет полностью выпрямлено, а руки не окажутся над головой.","Выполните обратное движение, потянув колесо назад к телу, используя корпус и руки.","Повторите необходимое количество повторений."],"es":["Comienza en posición de plancha con las manos sobre el rodillo y el cuerpo recto.","Activa el core y comienza a hacer rodar el rodillo hacia adelante extendiendo los brazos.","Continúa rodando hasta que tu cuerpo quede completamente extendido y los brazos por encima de la cabeza.","Invierte el movimiento tirando del rodillo de vuelta hacia tu cuerpo, usando el core y los brazos.","Repite el número de repeticiones deseado."]}},{"id":"1429","name":"wide grip pull-up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1429-Qqi7bko.jpg","gif_url":"videos/1429-Qqi7bko.gif","instruction_steps":{"he":["היתלו על מוט מתח עם כפות ידיים פונות מכם וידיים רחבות מרוחב הכתפיים.","הפעילו את שרירי הליבה וכווצו את השכמות זו לזו.","משכו את הגוף למעלה לכיוון המוט עד שהסנטר מעל המוט.","הורידו את הגוף חזרה לנקודת ההתחלה בשליטה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."],"ru":["Повисните на перекладине, повернув ладонями от себя и расставив руки на ширине плеч.","Напрягите корпус и сведите лопатки вместе.","Подтягивайте тело к перекладине, пока подбородок не окажется над перекладиной.","Опустите тело обратно в исходное положение, контролируя его.","Повторите необходимое количество повторений."],"es":["Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos más separadas que la anchura de los hombros.","Activa el core y junta los omóplatos.","Tira de tu cuerpo hacia arriba en dirección a la barra hasta que tu barbilla quede por encima de la barra.","Baja el cuerpo de nuevo a la posición inicial con control.","Repite el número de repeticiones deseado."]}},{"id":"1367","name":"wide grip rear pull-up","category":"back","body_part":"back","equipment":"body weight","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1367-OYFhXVD.jpg","gif_url":"videos/1367-OYFhXVD.gif","instruction_steps":{"he":["אחזו במוט המתח באחיזה עליונה רחבה, ידיים מעט רחבות מרוחב הכתפיים.","היתלו על המוט עם ידיים ישרות לגמרי וגוף ישר.","הפעילו את שרירי הגב ומשכו את הגוף למעלה לכיוון המוט, כשהחזה מוביל את התנועה.","המשיכו למשוך עד שהסנטר מעל המוט.","עצרו לרגע בנקודה העליונה, ואז הורידו את הגוף באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Возьмитесь за перекладину широким хватом сверху, руки на расстоянии чуть шире плеч.","Повисните на перекладине, полностью вытянув руки и выпрямив тело.","Задействуйте мышцы спины и подтяните тело к перекладине, ведя грудью.","Продолжайте тянуть, пока подбородок не окажется над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Agarra la barra de dominadas con un agarre prono amplio, las manos un poco más separadas que la anchura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.","Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"1311","name":"wide hand push up","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1311-JmMVpR3.jpg","gif_url":"videos/1311-JmMVpR3.gif","instruction_steps":{"he":["התחילו בעמדת פלאנק גבוה עם ידיים רחבות מרוחב הכתפיים.","שמרו על הגוף בקו ישר מהראש ועד כפות הרגליים.","הורידו את החזה לכיוון הרצפה בכיפוף מרפקים, תוך שמירה עליהם צמודים לצידי הגוף.","דחפו דרך כפות הידיים ליישור הידיים וחזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Start in a high plank position with your hands wider than shoulder-width apart.","Keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"ru":["Начните с позиции высокой планки, поставив руки шире плеч.","Держите тело на прямой линии от головы до пят.","Опустите грудь к земле, согнув локти и держа их близко к бокам.","Оттолкнитесь ладонями, чтобы вытянуть руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"es":["Comienza en una posición de plancha alta con las manos más separadas que la anchura de los hombros.","Mantén el cuerpo en línea recta de la cabeza a los pies.","Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]}},{"id":"2363","name":"wide-grip chest dip on high parallel bars","category":"chest","body_part":"chest","equipment":"body weight","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/2363-O2K9Vb5.jpg","gif_url":"videos/2363-O2K9Vb5.gif","instruction_steps":{"he":["התמקמו על המקבילים עם ידיים ישרות לגמרי והגוף תלוי באוויר.","רכנו מעט קדימה והורידו את הגוף בכיפוף מרפקים עד שהחזה מעט מעל המוטות.","עצרו לרגע, ואז דחפו את עצמכם חזרה למעלה לנקודת ההתחלה ביישור הידיים.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.","Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"ru":["Встаньте на параллельные брусья, полностью вытянув руки и подвешивая тело в воздухе.","Слегка наклонитесь вперед и опустите тело, сгибая локти, пока грудь не окажется чуть выше перекладин.","Сделайте паузу на мгновение, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."],"es":["Colócate sobre las barras paralelas con los brazos completamente extendidos y el cuerpo suspendido en el aire.","Inclínate ligeramente hacia adelante y baja el cuerpo flexionando los codos hasta que el pecho quede justo por encima de las barras.","Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]}},{"id":"0858","name":"wind sprints","category":"waist","body_part":"waist","equipment":"body weight","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"abs","image":"images/0858-Qoujh3Q.jpg","gif_url":"videos/0858-Qoujh3Q.gif","instruction_steps":{"he":["מצאו שטח פתוח או מסלול לביצוע התרגיל.","התחילו בעמידה עם רגליים ברוחב כתפיים.","התחילו לרוץ מהר ככל האפשר, בהנפת הידיים והרמת הברכיים גבוה.","המשיכו לספרינט למרחק או לפרק זמן מוגדר.","נוחו וחזרו על התרגיל למספר החזרות הרצוי."],"en":["Find an open space or a track to perform the exercise.","Start by standing with your feet shoulder-width apart.","Begin running as fast as you can, pumping your arms and driving your knees up.","Continue sprinting for a specific distance or time period.","Rest and repeat for the desired number of repetitions."],"ru":["Найдите открытое пространство или дорожку для выполнения упражнения.","Начните с того, что встаньте, поставив ноги на ширине плеч.","Начните бежать как можно быстрее, размахивая руками и поднимая колени.","Продолжайте бежать на определенную дистанцию ​​или в течение определенного периода времени.","Отдохните и повторите необходимое количество повторений."],"es":["Busca un espacio abierto o una pista para realizar el ejercicio.","Comienza de pie con los pies separados a la altura de los hombros.","Comienza a correr lo más rápido que puedas, bombeando los brazos y elevando las rodillas.","Continúa el sprint durante una distancia o periodo de tiempo específico.","Descansa y repite el número de repeticiones deseado."]}},{"id":"1604","name":"world greatest stretch","category":"upper legs","body_part":"upper legs","equipment":"body weight","muscle_group":"glutes","secondary_muscles":["glutes","quadriceps","calves"],"target":"hamstrings","image":"images/1604-DFGXwZr.jpg","gif_url":"videos/1604-DFGXwZr.gif","instruction_steps":{"he":["התחילו בעמדת מספריים עם כף רגל ימין קדימה וכף רגל שמאל לאחור.","הניחו את הידיים על הרצפה משני צידי כף רגל ימין.","הורידו את ברך שמאל לרצפה ומתחו את רגל ימין, תוך שמירה על כף רגל ימין שטוחה על הרצפה.","סובבו את הגו ימינה, במתיחת יד ימין למעלה לכיוון התקרה.","החזיקו את התנוחה כמה שניות, ואז חזרו לנקודת ההתחלה.","החליפו צדדים וחזרו על המתיחה עם כף רגל שמאל קדימה."],"en":["Start in a lunge position with your right foot forward and your left foot back.","Place your hands on the ground on either side of your right foot.","Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.","Rotate your torso to the right, reaching your right arm up towards the ceiling.","Hold this position for a few seconds, then return to the starting position.","Switch sides and repeat the stretch with your left foot forward."],"ru":["Начните с выпада, поставив правую ногу вперед, а левую назад.","Положите руки на землю по обе стороны от правой стопы.","Опустите левое колено на землю и вытяните правую ногу, удерживая правую ступню на земле.","Поверните туловище вправо, подняв правую руку к потолку.","Удерживайте это положение несколько секунд, затем вернитесь в исходное положение.","Поменяйте сторону и повторите растяжку, поставив левую ногу вперед."],"es":["Comienza en posición de zancada con el pie derecho adelante y el pie izquierdo atrás.","Coloca las manos en el suelo a ambos lados de tu pie derecho.","Baja la rodilla izquierda hacia el suelo y extiende la pierna derecha, manteniendo el pie derecho plano sobre el suelo.","Gira el torso hacia la derecha, extendiendo el brazo derecho hacia el techo.","Mantén esta posición durante unos segundos, luego vuelve a la posición inicial.","Cambia de lado y repite el estiramiento con el pie izquierdo adelante."]}},{"id":"1428","name":"wrist circles","category":"lower arms","body_part":"lower arms","equipment":"body weight","muscle_group":"hands","secondary_muscles":["hands","wrists"],"target":"forearms","image":"images/1428-2zNKRUB.jpg","gif_url":"videos/1428-2zNKRUB.gif","instruction_steps":{"he":["מתחו את הידיים ישר לפניכם.","קמצו את שתי הידיים לאגרוף.","סובבו את שורשי כף היד בתנועה מעגלית, תוך שמירה על ידיים ללא תזוזה.","המשיכו בסיבובי שורש כף היד למספר החזרות הרצוי."],"en":["Extend your arms straight out in front of you.","Make a fist with both hands.","Rotate your wrists in a circular motion, keeping your arms still.","Continue the wrist circles for the desired number of repetitions."],"ru":["Вытяните руки прямо перед собой.","Сожмите кулак обеими руками.","Делайте круговые движения запястьями, сохраняя руки неподвижными.","Продолжайте круговые движения запястьями желаемое количество повторений."],"es":["Extiende los brazos rectos frente a ti.","Cierra ambas manos en un puño.","Gira las muñecas en un movimiento circular, manteniendo los brazos quietos.","Continúa los círculos de muñeca el número de repeticiones deseado."]}},{"id":"0859","name":"wrist rollerer","category":"lower arms","body_part":"lower arms","equipment":"weighted","muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"forearms","image":"images/0859-bd5b860.jpg","gif_url":"videos/0859-bd5b860.gif","instruction_steps":{"he":["חברו משקל לקצה אחד של חבל או מוט.","החזיקו את הקצה השני של החבל או המוט בשתי ידיים, כפות ידיים כלפי מטה.","עמדו עם רגליים ברוחב כתפיים וידיים מתוחות לגמרי לפניכם.","גלגלו באיטיות את המשקל למעלה לכיוון הידיים בכיפוף שורשי כף היד.","עצרו לרגע בנקודה העליונה, ואז הורידו את המשקל באיטיות חזרה לנקודת ההתחלה.","חזרו על התרגיל למספר החזרות הרצוי."],"en":["Attach a weight to one end of a rope or bar.","Hold the other end of the rope or bar with both hands, palms facing down.","Stand with your feet shoulder-width apart and your arms fully extended in front of you.","Slowly roll the weight up towards your hands by flexing your wrists.","Pause for a moment at the top, then slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions."],"ru":["Прикрепите груз к одному концу веревки или перекладины.","Возьмите другой конец веревки или перекладины обеими руками ладонями вниз.","Встаньте, ноги на ширине плеч, а руки полностью вытянуты перед собой.","Медленно поднимите вес к рукам, сгибая запястья.","Задержитесь на мгновение в верхней точке, затем медленно опустите вес обратно в исходное положение.","Повторите необходимое количество повторений."],"es":["Sujeta un peso a un extremo de una cuerda o barra.","Sostén el otro extremo de la cuerda o barra con ambas manos, con las palmas hacia abajo.","Ponte de pie con los pies separados a la altura de los hombros y los brazos completamente extendidos frente a ti.","Enrolla lentamente el peso hacia las manos flexionando las muñecas.","Haz una pausa breve en lo alto, luego baja lentamente el peso de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]}}];
